    /** «Cloudflare consigliato» (2.3.0): the browser always revalidates, the edge keeps a copy 10 minutes, purged on change. */
    const CLOUDFLARE_RECOMMENDED_CACHE_CONTROL = 'public, max-age=0, s-maxage=600';
    const CLOUDFLARE_PURGE_OPTION = 'static_bridge_cloudflare_purge_pending';
    const CLOUDFLARE_PURGE_STATUS_OPTION = 'static_bridge_cloudflare_purge_last';
    const CLOUDFLARE_PURGE_LOCK = 'static_bridge_cloudflare_purge_lock';
