    const CLOUDFLARE_PURGE_BATCH = 30;
    const CLOUDFLARE_PURGE_MAX_URLS = 2000;
    const CLOUDFLARE_PURGE_MAX_ATTEMPTS = 4;
    const CLOUDFLARE_PURGE_TIMEOUT = 8;
    const STRICT_404_CACHE_CONTROL = 'no-store, max-age=0';
