    const STALE_RELEASE_OPTION = 'static_bridge_stale_release';
    // Content withdrawn while the plugin was off (2.2.11): the public posts at deactivation, so that
    // reactivation can tell a deleted or moved one; and, when the static copy of such content cannot be
    // found, the release whose routing stays off until a full export replaces it.
    const DEACTIVATION_SNAPSHOT_OPTION = 'static_bridge_deactivation_public';
    const DEACTIVATION_SNAPSHOT_LIMIT = 100000;
    const ROUTING_HOLD_OPTION = 'static_bridge_routing_hold';
    const WITHDRAWN_ON_ACTIVATION_LIMIT = 1000;
    const SECURITY_HEADER_NAMES = array('X-Frame-Options', 'X-Content-Type-Options', 'Referrer-Policy', 'Permissions-Policy', 'Strict-Transport-Security', 'Content-Security-Policy');
    // Apache serves an immutable hard-linked copy of the current release (served/<id>/):
    // a path its rules have made servable never changes content (Apache's stat-then-open race).
    const SERVED_COPY_OPTION = 'static_bridge_served_copy';
    // The web server seen by the last web request (web_server_kind()): WP-CLI and the system cron have none.
    const WEB_SERVER_OPTION = 'static_bridge_web_server';
    const OPENLITESPEED_PROBE_PREFIX = 'static-bridge-rules-';
    const OPENLITESPEED_FOLDER_GUARD = "# Static Bridge: OpenLiteSpeed rilegge subito questo file, quello della radice solo all'avvio.\n# Nessun file di questa cartella è raggiungibile per indirizzo diretto: le pagine statiche ci arrivano dalle regole della radice.\nRewriteEngine On\nRewriteRule ^ - [F]\n";
    const SERVED_COPY_HOOK = 'static_bridge_served_copy_maintenance';
    const SERVED_COPY_GRACE = 60;
    const SERVED_COPY_PRUNE_BUDGET = 5;
    const SERVED_COPY_LOCK_WAIT = 10;
    const ACTIVATION_MIN_MEMORY = 134217728;
    const ACTIVATION_MEMORY_RESERVE = 33554432;

    private $incremental_old_archive_urls = array();
    private $incremental_old_term_urls = array();
    private $filtering_excluded_paths = false;
    private $shared_output_refresh_queued_this_request = false;
    /** True while this request is inside change_incremental_queue(): a change inside a change takes no second lock. */
