    private $markdown_user_check = false;

    public function __construct()
    {
        $this->request_uri_at_load = isset($_SERVER['REQUEST_URI']) ? (string) $_SERVER['REQUEST_URI'] : null;
        // Recovery can build translated errors (for example while an export
        // holds the render lock); WordPress 6.7+ requires init for that.
        if (did_action('init')) {
            $this->recover_interrupted_render_bypass();
        } else {
            add_action('init', function () {
                $this->recover_interrupted_render_bypass();
            }, 0);
        }
        $this->mark_verified_render_uncacheable();
        add_action('wp_abilities_api_categories_init', array($this, 'register_mcp_ability_category'));
        add_action('wp_abilities_api_init', array($this, 'register_mcp_abilities'));
        add_action('admin_menu', array($this, 'register_admin_page'));
        add_action('admin_enqueue_scripts', array($this, 'enqueue_admin_assets'));
        add_action('add_meta_boxes', array($this, 'register_post_push_meta_box'), 10, 2);
        add_action('admin_post_static_bridge_push_post', array($this, 'handle_post_push'));
        add_action('admin_post_static_bridge_post_push_status', array($this, 'handle_post_push_status'));
        add_action('admin_notices', array($this, 'render_post_push_notice'));
        add_action('admin_bar_menu', array($this, 'add_admin_bar_push_node'), 90);
        add_action('save_post', array($this, 'save_post_static_exclusion'), 10, 2);
        add_action('deleted_post', array($this, 'forget_deleted_post_exclusion'), 10, 1);
        add_action('permalink_structure_changed', array($this, 'refresh_editor_excluded_paths'), 10, 0);
        add_action('admin_notices', array($this, 'render_stale_release_notice'));
        add_action('admin_notices', array($this, 'render_stalled_export_notice'));
        add_action('admin_notices', array($this, 'render_layout_notice'));
        add_action('admin_notices', array($this, 'render_server_check_notice'));
        // After an update of WP, the theme or a plugin (2.5.0): what changed after the release online, a notice with
        // «Rigenera», and the optional export once maintenance is over.
        add_action('admin_notices', array($this, 'render_after_update_notice'));
        add_action('upgrader_process_complete', array($this, 'note_upgrader_change'), 10, 2);
        add_action('upgrader_overwrote_package', array($this, 'note_overwritten_package'), 10, 3);
        add_action('switch_theme', array($this, 'note_theme_switch'), 10, 1);
        add_action('activated_plugin', array($this, 'note_plugin_activated'), 10, 1);
        add_action('deactivated_plugin', array($this, 'note_plugin_deactivated'), 10, 1);
        add_action('admin_post_static_bridge_after_update', array($this, 'handle_after_update'));
        add_action(self::AFTER_UPDATE_HOOK, array($this, 'run_after_update_export'));
        // WP-Cron in «Salute del sito» (2.5.0): the same read-only result as the Server tab.
        add_filter('site_status_tests', array($this, 'add_site_status_tests'));
        add_filter('post_row_actions', array($this, 'add_post_push_row_action'), 10, 2);
        add_filter('page_row_actions', array($this, 'add_post_push_row_action'), 10, 2);
        add_action('admin_post_static_bridge_save_settings', array($this, 'save_settings'));
        add_action('admin_post_static_bridge_save_form_modes', array($this, 'save_form_modes'));
        add_action('admin_post_static_bridge_save_form_nonce_refresh', array($this, 'save_form_nonce_refresh'));
        add_action('admin_post_static_bridge_export_diagnostics', array($this, 'export_diagnostic_log'));
        add_action('admin_post_static_bridge_apply_retention', array($this, 'handle_apply_retention'));
        add_action('admin_post_static_bridge_delete_release', array($this, 'handle_delete_release'));
        add_action('admin_post_static_bridge_cleanup_releases', array($this, 'handle_cleanup_releases'));
        add_action('admin_post_static_bridge_enable_retention', array($this, 'handle_enable_retention'));
        add_action('admin_post_static_bridge_cloudflare_purge', array($this, 'handle_cloudflare_purge'));
        add_action('admin_post_static_bridge_server_tuning', array($this, 'handle_server_tuning'));
        // Public on purpose: the request that tests a new object-cache.php carries no cookies.
        // It answers only with the token of a probe in progress (Static_Bridge_Object_Cache::probe()).
        add_action('wp_ajax_nopriv_static_bridge_object_cache_probe', array('Static_Bridge_Object_Cache', 'probe_response'));
        add_action('wp_ajax_static_bridge_object_cache_probe', array('Static_Bridge_Object_Cache', 'probe_response'));
        add_action('admin_post_static_bridge_refresh', array($this, 'handle_refresh_request'));
        add_action('admin_post_static_bridge_link_check', array($this, 'handle_link_check'));
        // Basic Auth (2.5.0): the loopback with which WP starts WP-Cron carries the credentials too.
        add_filter('cron_request', array($this, 'add_basic_auth_to_cron_request'), PHP_INT_MAX, 1);
