        add_action('admin_init', array($this, 'maybe_schedule_served_copy_adoption'), 20);
        add_action('wp_after_insert_post', array($this, 'maybe_queue_incremental_post'), 100, 4);
        add_action('wp_after_insert_post', array($this, 'maybe_queue_shared_content_post'), 101, 4);
        add_action('customize_save_after', array($this, 'maybe_queue_customizer_shared_output'), 10, 1);
        add_action('added_option', array($this, 'maybe_queue_bricks_global_option'), 10, 2);
        add_action('updated_option', array($this, 'maybe_queue_bricks_global_option'), 10, 3);
        add_action('deleted_option', array($this, 'maybe_queue_bricks_global_option'), 10, 2);
        add_action('added_option', array($this, 'maybe_queue_etch_global_option'), 10, 2);
        add_action('updated_option', array($this, 'maybe_queue_etch_global_option'), 10, 3);
        add_action('deleted_option', array($this, 'maybe_queue_etch_global_option'), 10, 1);
        add_action('added_option', array($this, 'maybe_note_complianz_option'), 10, 1);
        add_action('updated_option', array($this, 'maybe_note_complianz_option'), 10, 1);
        add_action('deleted_option', array($this, 'maybe_note_complianz_option'), 10, 1);
        add_action('cmplz_after_css_generation', array($this, 'note_complianz_change'), 10, 0);
        add_filter('cmplz_do_action', array($this, 'note_complianz_admin_action'), 1, 2);
        // Classic menus and widgets (2.5.0): the options here, the actions of static_bridge_shared_refresh_hooks once
