        add_action('added_option', array($this, 'maybe_note_layout_option'), 10, 3);
        add_action('updated_option', array($this, 'maybe_note_layout_option'), 10, 3);
        add_action('deleted_option', array($this, 'maybe_note_layout_option'), 10, 3);
        if (did_action('init')) {
            $this->register_layout_refresh_hooks();
        } else {
            add_action('init', array($this, 'register_layout_refresh_hooks'), 99);
