        add_action('added_post_meta', array($this, 'maybe_queue_shared_content_meta'), 101, 4);
        add_action('updated_post_meta', array($this, 'maybe_queue_shared_content_meta'), 101, 4);
        add_action('deleted_post_meta', array($this, 'maybe_queue_shared_content_meta'), 101, 4);
        add_action('elementor/document/after_save', array($this, 'maybe_queue_elementor_document'), 10, 2);
        add_action('before_delete_post', array($this, 'maybe_queue_deleted_post'), 10, 2);
        // Archives change without a post change too: a renamed or new term, an author's slug, the reading settings.
        add_action('edit_terms', array($this, 'remember_incremental_old_term'), 10, 2);
        add_action('edited_term', array($this, 'maybe_queue_term_archive'), 10, 3);
        add_action('created_term', array($this, 'maybe_queue_term_archive'), 10, 3);
        add_action('pre_delete_term', array($this, 'maybe_queue_deleted_term'), 10, 2);
        add_action('profile_update', array($this, 'maybe_queue_author_archive'), 10, 2);
        // Comments (2.5.0): the number of approved comments changed, or an approved comment was edited.
        add_action('wp_update_comment_count', array($this, 'maybe_queue_comment_count_change'), 10, 3);
        add_action('edit_comment', array($this, 'maybe_queue_edited_comment'), 10, 2);
        foreach (array('posts_per_page', 'permalink_structure', 'category_base', 'tag_base', 'show_on_front', 'page_on_front', 'page_for_posts', 'woocommerce_permalinks') as $reading_option) {
            add_action('update_option_' . $reading_option, array($this, 'maybe_queue_reading_option_refresh'), 10, 3);
        }
        add_action('before_delete_post', array($this, 'maybe_queue_deleted_shared_content_post'), 11, 2);
        // WooCommerce (2.2.13): prices, stock and promotions change through the data stores (orders, REST, imports,
        // scheduled sales), most of the time without wp_after_insert_post.
        add_action('woocommerce_before_product_object_save', array($this, 'note_woocommerce_product_changes'), 10, 1);
        add_action('woocommerce_before_product_variation_object_save', array($this, 'note_woocommerce_product_changes'), 10, 1);
        add_action('woocommerce_new_product', array($this, 'note_woocommerce_new_product'), 10, 1);
        add_action('woocommerce_new_product_variation', array($this, 'note_woocommerce_new_product'), 10, 1);
        add_action('woocommerce_update_product', array($this, 'note_woocommerce_product_saved'), 10, 1);
        add_action('woocommerce_update_product_variation', array($this, 'note_woocommerce_product_saved'), 10, 1);
        add_action('woocommerce_product_set_stock', array($this, 'note_woocommerce_product_page'), 10, 1);
        add_action('woocommerce_variation_set_stock', array($this, 'note_woocommerce_product_page'), 10, 1);
        add_action('woocommerce_product_set_stock_status', array($this, 'note_woocommerce_product_lists'), 10, 1);
        add_action('woocommerce_variation_set_stock_status', array($this, 'note_woocommerce_product_lists'), 10, 1);
        add_action('woocommerce_after_product_ordering', array($this, 'note_woocommerce_product_lists'), 10, 1);
        add_action('woocommerce_before_delete_product_variation', array($this, 'note_woocommerce_product_lists'), 10, 1);
        add_action('woocommerce_trash_product_variation', array($this, 'note_woocommerce_product_lists'), 10, 1);
        foreach (array('added_term_meta', 'updated_term_meta', 'deleted_term_meta') as $term_meta_hook) {
            add_action($term_meta_hook, array($this, 'maybe_queue_woocommerce_term_meta'), 10, 3);
        }
        add_action('added_option', array($this, 'maybe_note_woocommerce_option'), 10, 1);
        add_action('updated_option', array($this, 'maybe_note_woocommerce_option'), 10, 1);
        add_action('deleted_option', array($this, 'maybe_note_woocommerce_option'), 10, 1);
        add_filter('nonce_life', array($this, 'record_render_nonce_action'), PHP_INT_MAX, 2);
        add_filter('wp_headers', array($this, 'record_render_cache_headers'), PHP_INT_MAX, 1);
