        add_action('static_bridge_process_export_queue', array($this, 'process_export_queue_cron'));
        // «Export completo pianificato» (2.5.0): a single event that schedules the next one after each run.
        add_action(self::SCHEDULED_EXPORT_HOOK, array($this, 'run_scheduled_export'));
        // «Pagine da aggiornare ogni notte» (2.5.0): a single event that schedules the next night after each run.
        add_action(self::NIGHTLY_PATHS_HOOK, array($this, 'run_nightly_paths'));
        // Every path that ends a full export saves the job: one place sees it finish (2.5.0).
        add_action('update_option_' . self::JOB_OPTION, array($this, 'handle_export_job_saved'), 10, 2);
        add_action(self::RETENTION_HOOK, array($this, 'process_release_retention_cron'));
        // The link check after a publication with Strict (2.5.0): a single event that reschedules itself per chunk.
        add_action(self::LINK_CHECK_HOOK, array($this, 'run_link_check'));
        add_action(self::CLOUDFLARE_PURGE_HOOK, array($this, 'process_cloudflare_purge_cron'));
        add_action(self::SERVED_COPY_HOOK, array($this, 'process_served_copy_maintenance'));
        add_action('wp_ajax_static_bridge_start', array($this, 'ajax_start'));
        add_action('wp_ajax_static_bridge_tick', array($this, 'ajax_tick'));
        add_action('wp_ajax_static_bridge_status', array($this, 'ajax_status'));
        add_action('wp_ajax_static_bridge_cancel', array($this, 'ajax_cancel'));
        add_action('wp_ajax_static_bridge_resume', array($this, 'ajax_resume'));
        // Not logged in on purpose: the request comes from the server itself; the per-export token is the credential.
        add_action('wp_ajax_nopriv_' . self::EXPORT_CONTINUE_ACTION, array($this, 'ajax_export_continue'));
        add_action('wp_ajax_' . self::EXPORT_CONTINUE_ACTION, array($this, 'ajax_export_continue'));
        add_action('wp_ajax_static_bridge_diagnostic_start', array($this, 'ajax_diagnostic_start'));
        add_action('wp_ajax_static_bridge_diagnostic_tick', array($this, 'ajax_diagnostic_tick'));
        add_action('wp_ajax_static_bridge_diagnostic_status', array($this, 'ajax_diagnostic_status'));
        add_action('wp_ajax_static_bridge_server_check_start', array($this, 'ajax_server_check_start'));
        add_action('wp_ajax_static_bridge_server_check_step', array($this, 'ajax_server_check_step'));
