        add_action('wp_ajax_nopriv_static_bridge_public_form_nonces', array($this, 'ajax_public_form_nonces'));
        add_action('wp_ajax_static_bridge_public_form_nonces', array($this, 'ajax_public_form_nonces'));
        add_action('wp_ajax_nopriv_' . self::WOOCOMMERCE_NONCE_AJAX_ACTION, array($this, 'ajax_public_woocommerce_nonces'));
