    public function register_mcp_ability_category()
    {
        if (!function_exists('wp_register_ability_category')) {
            return;
        }

        wp_register_ability_category(self::MCP_ABILITY_CATEGORY, array(
            'label' => __('Static Bridge', 'static-bridge'),
            'description' => __('Diagnostica read-only e aggiornamento immediato di una singola copia statica.', 'static-bridge'),
        ));
    }

    public function register_mcp_abilities()
    {
        if (!function_exists('wp_register_ability')) {
            return;
        }

        wp_register_ability(self::MCP_PUSH_DIAGNOSTIC_ABILITY, array(
            'label' => __('Diagnostica push statico', 'static-bridge'),
            'description' => __('Legge lo stato incrementale, il prossimo evento WP-Cron, gli errori recenti e i metadati del file statico per un singolo contenuto. Non accoda, esegue o modifica alcuna operazione.', 'static-bridge'),
            'category' => self::MCP_ABILITY_CATEGORY,
            'input_schema' => array(
                'type' => 'object',
                'properties' => array(
                    'post_id' => array(
                        'type' => 'integer',
                        'minimum' => 1,
                        'description' => __('ID WordPress del contenuto da diagnosticare.', 'static-bridge'),
                    ),
                ),
                'required' => array('post_id'),
                'additionalProperties' => false,
            ),
            'output_schema' => array(
                'type' => 'object',
                'properties' => array(
                    'post_id' => array('type' => 'integer'),
                    'post_exists' => array('type' => 'boolean'),
                    'post_type' => array('type' => 'string'),
                    'post_status' => array('type' => 'string'),
                    'post_modified_gmt' => array('type' => 'string'),
                    'route' => array('type' => 'string'),
                    'incremental_enabled' => array('type' => 'boolean'),
                    'active_release' => array('type' => 'string'),
                    'worker_scheduled_at' => array('type' => 'integer'),
                    'wp_cron_disabled' => array('type' => 'boolean'),
                    'worker_lock_active' => array('type' => 'boolean'),
                    'queue_items' => array('type' => 'array', 'items' => array('type' => 'object')),
                    'push_status' => array('type' => 'string'),
                    'push_last_error' => array('type' => 'string'),
                    'push_updated_at' => array('type' => 'integer'),
                    'static_file_exists' => array('type' => 'boolean'),
                    'static_file_mtime' => array('type' => 'integer'),
                    'static_file_bytes' => array('type' => 'integer'),
                    'static_file_sha256' => array('type' => 'string'),
                    'file_may_be_stale' => array('type' => 'boolean'),
                    'recent_activity' => array('type' => 'array', 'items' => array('type' => 'object')),
                ),
            ),
            'execute_callback' => array($this, 'get_post_push_diagnostics'),
            'permission_callback' => array($this, 'can_read_post_push_diagnostics'),
            'meta' => array(
                'public' => true,
                'show_in_rest' => false,
                'mcp' => array(
                    'public' => true,
                    'type' => 'tool',
                ),
                'annotations' => array(
                    'readonly' => true,
                    'destructive' => false,
                    'idempotent' => true,
                ),
            ),
        ));

        wp_register_ability(self::MCP_PUSH_POST_ABILITY, array(
            'label' => __('Aggiorna una copia statica', 'static-bridge'),
            'description' => __('Esegue subito il push statico di una singola pagina o articolo pubblicato. Richiede conferma esplicita, non avvia un export completo e lascia la vecchia copia online se il rendering o la scrittura falliscono.', 'static-bridge'),
            'category' => self::MCP_ABILITY_CATEGORY,
            'input_schema' => array(
                'type' => 'object',
                'properties' => array(
                    'post_id' => array(
                        'type' => 'integer',
                        'minimum' => 1,
                        'description' => __('ID WordPress della pagina o dell’articolo da pubblicare.', 'static-bridge'),
                    ),
                    'confirm' => array(
                        'type' => 'boolean',
                        'description' => __('Imposta true per autorizzare la scrittura della copia statica di questo singolo contenuto.', 'static-bridge'),
                    ),
                ),
                'required' => array('post_id', 'confirm'),
                'additionalProperties' => false,
            ),
            'output_schema' => array(
                'type' => 'object',
                'properties' => array(
                    'post_id' => array('type' => 'integer'),
                    'route' => array('type' => 'string'),
                    'status' => array('type' => 'string'),
                    'last_error' => array('type' => 'string'),
                    'static_file_exists' => array('type' => 'boolean'),
                    'static_file_mtime' => array('type' => 'integer'),
                    'static_file_bytes' => array('type' => 'integer'),
                    'static_file_sha256' => array('type' => 'string'),
                    'file_may_be_stale' => array('type' => 'boolean'),
                ),
            ),
            'execute_callback' => array($this, 'push_post_via_mcp'),
            'permission_callback' => array($this, 'can_push_post_via_mcp'),
            'meta' => array(
                'public' => true,
                'show_in_rest' => false,
                'mcp' => array(
                    'public' => true,
                    'type' => 'tool',
                ),
                'annotations' => array(
                    'readonly' => false,
                    'destructive' => false,
                    'idempotent' => false,
                ),
            ),
        ));
    }

    public function can_read_post_push_diagnostics($input = array())
    {
        return current_user_can('manage_options');
    }

    public function can_push_post_via_mcp($input = array())
    {
        $input = is_array($input) ? $input : array();
        $post_id = isset($input['post_id']) ? absint($input['post_id']) : 0;
        if (!current_user_can('manage_options') || $post_id < 1 || !current_user_can('edit_post', $post_id)) {
            return false;
        }
        $post = get_post($post_id);
        if (!($post instanceof WP_Post) && is_object($post)) {
            $post = new WP_Post($post);
        }
        // A missing content is reported by the ability itself; an existing one follows static_bridge_can_push_post.
        return !($post instanceof WP_Post) || $this->can_push_post($post);
    }

    public function push_post_via_mcp($input = array())
    {
        $input = is_array($input) ? $input : array();
        $post_id = isset($input['post_id']) ? absint($input['post_id']) : 0;
        if (!current_user_can('manage_options') || $post_id < 1 || !current_user_can('edit_post', $post_id)) {
            return new WP_Error('static_bridge_mcp_push_forbidden', __('Non hai i permessi per aggiornare la copia statica di questo contenuto.', 'static-bridge'));
        }
        if (empty($input['confirm'])) {
            return new WP_Error('static_bridge_mcp_push_confirmation_required', __('Conferma esplicitamente il push statico del singolo contenuto.', 'static-bridge'));
        }

        $post = get_post($post_id);
        if (!($post instanceof WP_Post) && is_object($post)) {
            $post = new WP_Post($post);
        }
        if (!($post instanceof WP_Post)) {
            return new WP_Error('static_bridge_mcp_push_post_missing', __('Il contenuto richiesto non è disponibile.', 'static-bridge'));
        }
        if (!$this->can_push_post($post)) {
            return new WP_Error('static_bridge_mcp_push_forbidden', __('Non hai i permessi per aggiornare la copia statica di questo contenuto.', 'static-bridge'));
        }
        $unavailable = $this->post_push_unavailable_reason($post);
        if ('' !== $unavailable) {
            return new WP_Error('static_bridge_mcp_push_unavailable', $unavailable);
        }

        $push_token = wp_generate_uuid4();
        $queued = $this->queue_manual_post_push($post, $push_token);
        if (is_wp_error($queued)) {
            return $queued;
        }
        $this->process_manual_post_push_now($post, $push_token);

        $record = $this->post_push_status_record($push_token);
        if (!is_array($record)) {
            return new WP_Error('static_bridge_mcp_push_status_missing', __('Il push è stato avviato, ma non è disponibile il suo stato verificato.', 'static-bridge'));
        }
        $url = get_permalink($post);
        $file = $url && $this->current_release()
            ? $this->mcp_diagnostic_file($this->current_release(), $url)
            : array('exists' => false, 'mtime' => 0, 'bytes' => 0, 'sha256' => '');
        $modified_gmt = isset($post->post_modified_gmt) ? sanitize_text_field((string) $post->post_modified_gmt) : '';
        $modified_timestamp = '' !== $modified_gmt ? strtotime($modified_gmt . ' UTC') : false;

        return array(
            'post_id' => $post_id,
            'route' => $url ? $this->normalize_route_path($url) : '',
            'status' => isset($record['status']) ? sanitize_key($record['status']) : 'unknown',
            'last_error' => isset($record['last_error']) ? $this->mcp_diagnostic_text($record['last_error'], 500) : '',
            'static_file_exists' => !empty($file['exists']),
            'static_file_mtime' => absint($file['mtime']),
            'static_file_bytes' => absint($file['bytes']),
            'static_file_sha256' => isset($file['sha256']) ? sanitize_text_field($file['sha256']) : '',
            'file_may_be_stale' => !empty($file['exists']) && false !== $modified_timestamp
                && $modified_timestamp > (int) $file['mtime'],
        );
    }

    public function get_post_push_diagnostics($input = array())
    {
        $input = is_array($input) ? $input : array();
        $post_id = isset($input['post_id']) ? absint($input['post_id']) : 0;
        if ($post_id < 1) {
            return new WP_Error('static_bridge_diagnostic_invalid_post', __('Indica un ID contenuto valido.', 'static-bridge'));
        }
        if (!current_user_can('manage_options')) {
            return new WP_Error('static_bridge_diagnostic_forbidden', __('Non hai i permessi per leggere la diagnostica di questo contenuto.', 'static-bridge'));
        }

        $post = get_post($post_id);
        $post_exists = is_object($post);
        $url = $post_exists ? get_permalink($post) : '';
        $path = $url ? $this->normalize_route_path($url) : '';
        $queue_items = array();
        foreach ($this->incremental_queue() as $item) {
            if (!is_array($item)) {
                continue;
            }
            $item_path = isset($item['path']) ? $this->normalize_route_path((string) $item['path']) : '';
            if ((int) (isset($item['post_id']) ? $item['post_id'] : 0) !== $post_id
                && ('' === $path || $item_path !== $path)) {
                continue;
            }
            $queue_items[] = array(
                'path' => $item_path,
                'action' => isset($item['action']) ? sanitize_key($item['action']) : '',
                'role' => isset($item['role']) ? sanitize_key($item['role']) : '',
                'queued_at' => isset($item['queued_at']) ? absint($item['queued_at']) : 0,
                'attempts' => isset($item['attempts']) ? absint($item['attempts']) : 0,
                'has_manual_push' => !empty($item['manual_push_token']),
                'last_error' => isset($item['last_error']) ? $this->mcp_diagnostic_text($item['last_error'], 500) : '',
            );
        }

        $push_status = array('status' => 'unknown', 'last_error' => '', 'updated_at' => 0);
        $status_records = get_option(self::POST_PUSH_STATUS_OPTION, array());
        if (is_array($status_records)) {
            foreach ($status_records as $record) {
                if (!is_array($record) || (int) (isset($record['post_id']) ? $record['post_id'] : 0) !== $post_id
                    || absint(isset($record['updated_at']) ? $record['updated_at'] : 0) < $push_status['updated_at']) {
                    continue;
                }
                $push_status = array(
                    'status' => isset($record['status']) ? sanitize_key($record['status']) : 'unknown',
                    'last_error' => isset($record['last_error']) ? $this->mcp_diagnostic_text($record['last_error'], 500) : '',
                    'updated_at' => absint(isset($record['updated_at']) ? $record['updated_at'] : 0),
                );
            }
        }

        $release = $this->current_release();
        $file = $post_exists && $release && $url ? $this->mcp_diagnostic_file($release, $url) : array('exists' => false, 'mtime' => 0, 'bytes' => 0);
        $post_modified_gmt = $post_exists && isset($post->post_modified_gmt) ? sanitize_text_field((string) $post->post_modified_gmt) : '';
        $post_modified_timestamp = '' !== $post_modified_gmt ? strtotime($post_modified_gmt . ' UTC') : false;
        $file_may_be_stale = !empty($file['exists']) && false !== $post_modified_timestamp
            && $post_modified_timestamp > (int) $file['mtime'];

        return array(
            'post_id' => $post_id,
            'post_exists' => $post_exists,
            'post_type' => $post_exists ? sanitize_key($post->post_type) : '',
            'post_status' => $post_exists ? sanitize_key($post->post_status) : '',
            'post_modified_gmt' => $post_modified_gmt,
            'route' => $path,
            'incremental_enabled' => !empty($this->settings()['incremental_enabled']),
            'active_release' => $release ? basename($release) : '',
            'worker_scheduled_at' => (int) wp_next_scheduled('static_bridge_process_incremental_queue'),
            'wp_cron_disabled' => defined('DISABLE_WP_CRON') && DISABLE_WP_CRON,
            'worker_lock_active' => $this->row_lock_active(self::INCREMENTAL_LOCK_OPTION),
            'queue_items' => array_slice($queue_items, 0, 10),
            'push_status' => $push_status['status'],
            'push_last_error' => $push_status['last_error'],
            'push_updated_at' => $push_status['updated_at'],
            'static_file_exists' => !empty($file['exists']),
            'static_file_mtime' => absint($file['mtime']),
            'static_file_bytes' => absint($file['bytes']),
            'static_file_sha256' => isset($file['sha256']) ? sanitize_text_field($file['sha256']) : '',
            'file_may_be_stale' => $file_may_be_stale,
            'recent_activity' => $this->mcp_diagnostic_activity($path),
        );
    }

    private function mcp_diagnostic_file($release, $url)
    {
        $result = array('exists' => false, 'mtime' => 0, 'bytes' => 0, 'sha256' => '');
        $root = realpath((string) $release);
        $relative = $this->relative_html_path($url);
        if (!$root || is_wp_error($relative) || !is_string($relative) || '' === $relative) {
            return $result;
        }

        $candidate = trailingslashit($root) . ltrim($relative, '/\\');
        $file = realpath($candidate);
        if (!$file || 0 !== strpos($file, trailingslashit($root)) || !is_file($file)) {
            return $result;
        }

        $mtime = filemtime($file);
        $bytes = filesize($file);
        $sha256 = hash_file('sha256', $file);
        return array(
            'exists' => false !== $mtime && false !== $bytes,
            'mtime' => false === $mtime ? 0 : (int) $mtime,
            'bytes' => false === $bytes ? 0 : (int) $bytes,
            'sha256' => false === $sha256 ? '' : $sha256,
        );
    }

    private function mcp_diagnostic_activity($path)
    {
        if ('' === (string) $path) {
            return array();
        }
        $items = get_option(self::ACTIVITY_OPTION, array());
        if (!is_array($items)) {
            return array();
        }

        $matches = array();
        foreach (array_reverse($items) as $item) {
            if (!is_array($item) || !isset($item['detail']) || !$this->mcp_diagnostic_detail_matches_path((string) $item['detail'], $path)) {
                continue;
            }
            $matches[] = array(
                'time' => isset($item['time']) ? $this->mcp_diagnostic_text($item['time'], 64) : '',
                'message' => isset($item['message']) ? $this->mcp_diagnostic_text($item['message'], 160) : '',
                'detail' => $this->mcp_diagnostic_text($item['detail'], 500),
                'error' => !empty($item['error']),
            );
            if (count($matches) >= 5) {
                break;
            }
        }
        return $matches;
    }

    private function mcp_diagnostic_detail_matches_path($detail, $path)
    {
        $detail = (string) $detail;
        $path = (string) $path;
        if ('/' === $path) {
            return '/' === trim($detail) || false !== strpos($detail, ' — /');
        }
        $position = strpos($detail, $path);
        if (false === $position) {
            return false;
        }
        $before = $position > 0 ? substr($detail, $position - 1, 1) : '';
        $after_position = $position + strlen($path);
        $after = $after_position < strlen($detail) ? substr($detail, $after_position, 1) : '';
        $delimiter = '/[\\s—·→]/u';
        return ('' === $before || preg_match($delimiter, $before))
            && ('' === $after || preg_match($delimiter, $after));
    }

    private function mcp_diagnostic_text($text, $maximum_length)
    {
        $text = sanitize_text_field(wp_strip_all_tags((string) $text));
        $text = preg_replace('~((?:https?://|/)[^\\s?#]*)\\?[^\\s#]*~i', '$1?[query redacted]', $text);
        $text = is_string($text) ? $text : '';
        if (function_exists('mb_substr')) {
            return mb_substr($text, 0, absint($maximum_length));
        }
        return substr($text, 0, absint($maximum_length));
    }

    public static function activation_preflight($context = array())
    {
        $context = is_array($context) ? $context : array();
        $errors = array();
        $warnings = array();
        $php_version = isset($context['php_version']) ? (string) $context['php_version'] : PHP_VERSION;
        $wp_version = isset($context['wp_version']) ? (string) $context['wp_version'] : (isset($GLOBALS['wp_version']) ? (string) $GLOBALS['wp_version'] : '');
        $memory_limit = isset($context['memory_limit']) ? (string) $context['memory_limit'] : (string) ini_get('memory_limit');
        $current_memory = isset($context['current_memory']) ? (int) $context['current_memory'] : memory_get_usage(true);
        $peak_memory = isset($context['peak_memory']) ? (int) $context['peak_memory'] : memory_get_peak_usage(true);
        $required_functions = isset($context['required_functions']) && is_array($context['required_functions'])
            ? $context['required_functions']
            : array('add_action', 'get_option', 'home_url', 'wp_die', 'wp_mkdir_p', 'wp_safe_remote_get', 'update_option', 'wp_json_encode', 'symlink', 'rename', 'file_put_contents');

        if (version_compare($php_version, '8.4', '<')) {
            $errors[] = sprintf(/* translators: %s: PHP version */ __('PHP %s non è supportato: Static Bridge richiede PHP 8.4 o successivo.', 'static-bridge'), $php_version);
        }
        // All sites of a network share one document root, one .htaccess and one
        // wp-content/static-bridge folder, so their releases and routing would collide.
        $multisite = isset($context['multisite']) ? (bool) $context['multisite'] : (function_exists('is_multisite') && is_multisite());
        if ($multisite) {
            $errors[] = __('WordPress multisito non è supportato: i siti della rete condividono document root, regole del server e cartella wp-content/static-bridge, quindi le release statiche si sovrascriverebbero.', 'static-bridge');
        }
        $layout = self::unsupported_layout_reason($context);
        if ('' !== $layout) {
            $errors[] = $layout;
        }
        if ('' !== $wp_version && version_compare($wp_version, '6.9', '<')) {
            $errors[] = sprintf(/* translators: %s: WordPress version */ __('WordPress %s non è supportato: Static Bridge richiede WordPress 6.9 o successivo.', 'static-bridge'), $wp_version);
        } elseif ('' === $wp_version) {
            $warnings[] = __('Versione WordPress non rilevabile durante il preflight; il controllo dei requisiti core resta affidato a WordPress.', 'static-bridge');
        }
        foreach ($required_functions as $function) {
            if (!is_string($function) || '' === $function || !function_exists($function)) {
                $errors[] = sprintf(/* translators: %s: PHP function name */ __('Funzione WordPress richiesta non disponibile: %s.', 'static-bridge'), is_scalar($function) ? (string) $function : __('sconosciuta', 'static-bridge'));
            }
        }
        if (!class_exists('Static_Bridge_Export_Queue')) {
            $errors[] = __('Il modulo della coda indicizzata non è leggibile o non può essere caricato; estrai nuovamente tutti i file del plugin prima di attivarlo.', 'static-bridge');
        }
        if (!class_exists('Static_Bridge_Dependency_Index')) {
            $errors[] = __('Il modulo dell’indice V2 non è leggibile o non può essere caricato; estrai nuovamente tutti i file del plugin prima di attivarlo.', 'static-bridge');
        }
        if (!class_exists('Static_Bridge_Header_Fragments')) {
            $errors[] = __('Il modulo dei frammenti header V2 non è leggibile o non può essere caricato; estrai nuovamente tutti i file del plugin prima di attivarlo.', 'static-bridge');
        }

        $content_dir = isset($context['content_dir'])
            ? (string) $context['content_dir']
            : (defined('WP_CONTENT_DIR') ? (string) WP_CONTENT_DIR : '');
        if ('' === $content_dir || !is_dir($content_dir) || !is_writable($content_dir)) {
            $errors[] = __('La cartella wp-content non è disponibile o non è scrivibile dal processo PHP.', 'static-bridge');
        } else {
            $static_root = rtrim($content_dir, '/\\') . DIRECTORY_SEPARATOR . 'static-bridge';
            if (is_link($static_root) || (file_exists($static_root) && !is_dir($static_root))) {
                $errors[] = __('Il percorso wp-content/static-bridge è un collegamento simbolico o un file non sicuro.', 'static-bridge');
            } elseif (is_dir($static_root) && !is_writable($static_root)) {
                $errors[] = __('La cartella wp-content/static-bridge esiste ma non è scrivibile dal processo PHP.', 'static-bridge');
            }
        }

        $limit_bytes = self::memory_limit_bytes($memory_limit);
        if (null === $limit_bytes) {
            $warnings[] = __('Il limite memoria PHP non è interpretabile; verifica manualmente che il processo disponga di almeno 128 MiB.', 'static-bridge');
        } elseif (0 < $limit_bytes) {
            if ($limit_bytes < self::ACTIVATION_MIN_MEMORY) {
                $errors[] = __('Il limite memoria PHP è inferiore a 128 MiB; l’attivazione viene fermata prima di modificare opzioni o regole del sito.', 'static-bridge');
            }
            $measured_peak = max($current_memory, $peak_memory);
            if ($limit_bytes - min($limit_bytes, $measured_peak) < self::ACTIVATION_MEMORY_RESERVE) {
                $errors[] = __('La memoria PHP residua è inferiore a 32 MiB; l’attivazione viene fermata prima di modificare opzioni o regole del sito.', 'static-bridge');
            }
        }

        return array(
            'ok' => empty($errors),
            'errors' => array_values(array_unique($errors)),
            'warnings' => array_values(array_unique($warnings)),
            'memory_limit' => $memory_limit,
            'memory_current' => $current_memory,
            'memory_peak' => $peak_memory,
        );
    }

    private static function memory_limit_bytes($value)
    {
        $value = trim((string) $value);
        if ('-1' === $value) {
            return 0;
        }
        if (!preg_match('/^(\d+(?:\.\d+)?)\s*([KMG])?$/i', $value, $match)) {
            return null;
        }
        $unit = isset($match[2]) ? strtoupper($match[2]) : '';
        $multiplier = 'G' === $unit ? 1073741824 : ('M' === $unit ? 1048576 : ('K' === $unit ? 1024 : 1));
        return (int) ((float) $match[1] * $multiplier);
    }

    public static function is_activation_request()
    {
        if (!defined('WP_SANDBOX_SCRAPING') || !function_exists('plugin_basename')) {
            return false;
        }
        $plugin_file = plugin_basename(__FILE__);
        $action = '';
        if (isset($_REQUEST['action']) && is_scalar($_REQUEST['action'])) {
            $action = sanitize_key(wp_unslash((string) $_REQUEST['action']));
        }
        if ('activate' !== $action && 'activate-selected' !== $action) {
            return false;
        }
        $candidates = array();
        foreach (array($_GET, $_POST) as $request) {
            if (!is_array($request)) {
                continue;
            }
            if (isset($request['plugin']) && is_string($request['plugin'])) {
                $candidates[] = wp_unslash($request['plugin']);
            }
            if (isset($request['checked']) && is_array($request['checked'])) {
                foreach ($request['checked'] as $checked_plugin) {
                    if (is_string($checked_plugin)) {
                        $candidates[] = wp_unslash($checked_plugin);
                    }
                }
            }
        }
        foreach ($candidates as $candidate) {
            if ($plugin_file === plugin_basename($candidate)) {
                return true;
            }
        }
        return false;
    }

    public static function halt_activation($report)
    {
        $errors = isset($report['errors']) && is_array($report['errors']) ? $report['errors'] : array();
        $message = '<p>' . esc_html__('Static Bridge non è stato attivato: il controllo preventivo ha rilevato condizioni che potrebbero interrompere la richiesta o il sito.', 'static-bridge') . '</p>';
        if (!empty($errors)) {
            $message .= '<ul>';
            foreach ($errors as $error) {
                $message .= '<li>' . esc_html($error) . '</li>';
            }
            $message .= '</ul>';
        }
        $message .= '<p>' . esc_html__('Correggi i requisiti indicati e riprova. Nessuna impostazione, regola di routing o file statico è stato modificato da Static Bridge.', 'static-bridge') . '</p>';
        wp_die($message, esc_html__('Attivazione Static Bridge fermata in sicurezza', 'static-bridge'), array('response' => 503, 'back_link' => true));
    }

    /**
     * Why this site cannot be served static, '' when it can. The Apache and Nginx rules, the protection
     * of the releases and the SSI includes written into the pages all assume the home at the root of the
     * domain and the content folder at /wp-content, so elsewhere the pages would never be served static
     * (or, with another Static Bridge at the root, served from the wrong folder).
     */
    private static function unsupported_layout_reason($context = array())
    {
        // The stored option, not home_url(): a language plugin may filter that to /en/ in wp-admin.
        $home_path = isset($context['home_path']) ? (string) $context['home_path'] : (string) wp_parse_url((string) get_option('home'), PHP_URL_PATH);
        $content_path = isset($context['content_path'])
            ? (string) $context['content_path']
            : (string) wp_parse_url(function_exists('content_url') ? content_url() : (defined('WP_CONTENT_URL') ? WP_CONTENT_URL : '/wp-content'), PHP_URL_PATH);
        $home_path = trim($home_path, '/');
        if ('' !== $home_path) {
            return sprintf(/* translators: %s: path of the home page, such as /blog/ */ __('La home del sito è in una sottocartella (%s): Static Bridge serve le pagine statiche solo con la home alla radice del dominio, quindi il sito resterebbe dinamico.', 'static-bridge'), '/' . $home_path . '/');
        }
        $content_path = '/' . trim($content_path, '/');
        if ('/wp-content' !== $content_path) {
            return sprintf(/* translators: %s: URL path of the content folder, such as /app/ */ __('La cartella dei contenuti non è /wp-content/ (qui %s): le regole del server e le inclusioni SSI di Static Bridge usano /wp-content/static-bridge/, quindi il sito resterebbe dinamico.', 'static-bridge'), $content_path . '/');
        }
        return '';
    }

    public function render_layout_notice()
    {
        $reason = current_user_can('manage_options') ? self::unsupported_layout_reason() : '';
        if ('' !== $reason) {
            echo '<div class="notice notice-error"><p>' . esc_html(__('Static Bridge non può servire questo sito in modo statico.', 'static-bridge') . ' ' . $reason) . '</p></div>';
        }
    }

    public static function activate()
    {
        $preflight = self::activation_preflight();
        if (empty($preflight['ok'])) {
            self::halt_activation($preflight);
        }
        $plugin = new self();
        $settings = get_option(self::SETTINGS_OPTION, null);
        if (!is_array($settings)) {
            $settings = array(
                'strict_mode' => 0,
                'excluded_paths' => array('/iscriviti/', '/contatti/'),
                'woocommerce_enabled' => 0,
                'incremental_enabled' => 1,
                'export_archives' => 1,
                'selective_shared_updates' => 0,
                // 2.4.0: a new site keeps the release online and one previous; upgrades keep their choice.
                'retention_enabled' => 1,
                'retention_keep' => self::RETENTION_NEW_SITE_KEEP,
            );
            add_option(self::SETTINGS_OPTION, $settings, '', false);
        }
        // Edits made while the plugin was off were never queued: the release is served again (as the FAQ
        // says), but Strict would answer 404 for the new posts, so it waits for the next full export.
        $release = $plugin->current_release();
        $changes = $release ? $plugin->content_changes_since_release() : 0;
        // Content made draft, private, password-protected, trashed or deleted meanwhile must not come back
        // online with the release (doc 23, item 169). Its copies leave the release before any rule serves
        // it again; when one cannot be found or removed, no route is served static until a full export.
        $withdrawn = $release
            ? $plugin->remove_withdrawn_static_copies($release)
            : array('removed' => array(), 'unresolved' => array(), 'deleted' => 0, 'dependents' => array());
        $changes += $withdrawn['deleted'];
        $hold = '' !== $release && (!empty($withdrawn['unresolved']) || $plugin->routing_held());
        if ($hold) {
            $previous_hold = get_option(self::ROUTING_HOLD_OPTION, array());
            $unresolved = max(count($withdrawn['unresolved']), is_array($previous_hold) && isset($previous_hold['unresolved']) ? absint($previous_hold['unresolved']) : 0, 1);
            update_option(self::ROUTING_HOLD_OPTION, array('release' => basename($release), 'unresolved' => $unresolved, 'at' => time()), false);
            $changes = max(1, $changes);
        } else {
            delete_option(self::ROUTING_HOLD_OPTION);
        }
        delete_option(self::DEACTIVATION_SNAPSHOT_OPTION);
        if (!empty($withdrawn['removed'])) {
            $removed_paths = array();
            foreach (array_slice($withdrawn['removed'], 0, 10) as $removed_url) {
                $removed_paths[] = $plugin->normalize_route_path($removed_url);
            }
            $plugin->log_activity(
                sprintf(/* translators: %s: number of static pages */ _n('Riattivazione: tolta %s copia statica di un contenuto non più pubblico.', 'Riattivazione: tolte %s copie statiche di contenuti non più pubblici.', count($withdrawn['removed']), 'static-bridge'), number_format_i18n(count($withdrawn['removed']))),
                implode(', ', $removed_paths)
            );
            $plugin->queue_cloudflare_purge($withdrawn['removed'], __('contenuto ritirato mentre il plugin era disattivato', 'static-bridge'));
        }
        if ($hold) {
            $plugin->log_activity(
                __('Riattivazione: il routing statico resta spento fino al prossimo export completo.', 'static-bridge'),
                __('Un contenuto pubblico alla disattivazione è stato eliminato o spostato mentre il plugin era spento, oppure la sua copia statica non si è potuta togliere: la release lo servirebbe ancora. Il frontend resta gestito da WordPress finché un export completo non sostituisce la release.', 'static-bridge')
                    . (!empty($withdrawn['unresolved']) ? ' ' . implode(', ', array_slice($withdrawn['unresolved'], 0, 10)) : ''),
                true
            );
        }
        if (!$hold && !empty($withdrawn['dependents']) && !empty($plugin->settings()['incremental_enabled'])) {
            // The lists that showed the withdrawn content (home, archives, query pages) drop it too.
            $plugin->enqueue_incremental_urls($withdrawn['dependents'], 0, 'refresh', array(), 'dependent');
        }
        if ($changes > 0) {
            $last = get_option('static_bridge_last_release', array());
            update_option(self::STALE_RELEASE_OPTION, array(
                'release' => is_array($last) && isset($last['id']) ? (string) $last['id'] : basename((string) $plugin->current_release()),
                'changes' => $changes,
                'at' => time(),
            ), false);
            $plugin->log_activity(
                sprintf(/* translators: %s: number of changed posts and pages */ _n('Riattivazione: %s contenuto è cambiato dopo l’ultima release.', 'Riattivazione: %s contenuti sono cambiati dopo l’ultima release.', $changes, 'static-bridge'), number_format_i18n($changes)),
                __('Le pagine statiche sono quelle dell’ultimo export e la modalità strict resta spenta: avvia un export completo.', 'static-bridge'),
                true
            );
        } else {
            delete_option(self::STALE_RELEASE_OPTION);
        }
        if (!$plugin->sync_strict_marker(!empty($settings['strict_mode']) && (bool) $plugin->current_release())) {
            $plugin->log_activity(__('Il marcatore della modalità strict non è stato sincronizzato.', 'static-bridge'), __('Controlla che wp-content/static-bridge e .strict non siano collegamenti simbolici o percorsi non scrivibili.', 'static-bridge'), true);
        }
        $has_static_release = (bool) $plugin->current_release();
        if (!$has_static_release) {
            // Do not arm the static router on a fresh install. Until a validated
            // release exists, WordPress is already the intended frontend.
            if (!$plugin->sync_routing_enabled_marker(false)) {
                $plugin->log_activity(
                    __('Plugin attivato senza release, ma il marcatore di routing non è stato rimosso.', 'static-bridge'),
                    __('Controlla wp-content/static-bridge/.enabled: senza una release pubblicata il frontend deve restare gestito da WordPress.', 'static-bridge'),
                    true
                );
            }
        } elseif ($plugin->routing_held()) {
            // update_routing_rules() keeps the marker and the Apache rules off while the hold applies.
            if (!$plugin->update_routing_rules()) {
                $plugin->log_activity(
                    __('Routing statico da tenere spento, ma il marcatore o le regole Apache non sono stati rimossi.', 'static-bridge'),
                    __('Controlla wp-content/static-bridge/.enabled e il blocco Static Bridge in .htaccess: finché il prossimo export completo non sostituisce la release, il frontend deve restare gestito da WordPress.', 'static-bridge'),
                    true
                );
            }
        } elseif ($plugin->server_uses_nginx()) {
            if (!$plugin->sync_routing_enabled_marker(true)) {
                $plugin->log_activity(__('Plugin attivato, ma il marcatore Nginx non è stato creato.', 'static-bridge'), __('Controlla i permessi di wp-content/static-bridge; il routing statico resterà disattivato.', 'static-bridge'), true);
            }
        } elseif (!$plugin->update_routing_rules()) {
            $plugin->sync_routing_enabled_marker(false);
            $plugin->log_activity(__('Plugin attivato, ma il routing Apache non è stato abilitato.', 'static-bridge'), __('Controlla i permessi di .htaccess e wp-content/static-bridge; il frontend resta gestito da WordPress.', 'static-bridge'), true);
        }
        $warning_detail = !empty($preflight['warnings']) ? implode(' ', $preflight['warnings']) : '';
        $job = get_option(self::JOB_OPTION, array());
        if (is_array($job) && !empty($job['queue_version']) && 'running' === (isset($job['status']) ? $job['status'] : '')) {
            $plugin->schedule_export_worker(15);
        }
        // Deactivation removed the scheduled export; it comes back only if the schedule is on.
        $plugin->schedule_scheduled_export();
        // The same for the nightly paths, and a menu or widget refresh still waiting when the plugin was deactivated.
        $plugin->schedule_nightly_paths();
        if (false !== get_option(self::LAYOUT_REFRESH_OPTION, false)) {
            $plugin->schedule_layout_refresh();
        }
        // The same for the export after an update, when «Rigenera dopo gli aggiornamenti» is on.
        if ($plugin->regenerate_after_updates_enabled()) {
            $plugin->schedule_after_update_export();
        }
        $plugin->log_activity(__('Static Bridge attivato.', 'static-bridge'), $warning_detail);
    }

    public static function deactivate()
    {
        $plugin = new self();
        wp_clear_scheduled_hook('static_bridge_process_export_queue');
        wp_clear_scheduled_hook(self::SCHEDULED_EXPORT_HOOK);
        wp_clear_scheduled_hook(self::NIGHTLY_PATHS_HOOK);
        wp_clear_scheduled_hook(self::LAYOUT_REFRESH_HOOK);
        wp_clear_scheduled_hook(self::AFTER_UPDATE_HOOK);
        wp_clear_scheduled_hook('static_bridge_release_retention');
        wp_clear_scheduled_hook(self::CLOUDFLARE_PURGE_HOOK);
        wp_clear_scheduled_hook(self::SERVED_COPY_HOOK);
        wp_clear_scheduled_hook(self::LINK_CHECK_HOOK);
        $plugin->remember_public_content_at_deactivation();
        $is_nginx = $plugin->server_uses_nginx();
        $marker_removed = $plugin->sync_routing_enabled_marker(false);
        $rules_removed = true;
        if (!$marker_removed) {
            if ($is_nginx) {
                $plugin->log_activity(__('Disattivazione completata, ma il marcatore Nginx non è stato rimosso.', 'static-bridge'), __('Controlla manualmente wp-content/static-bridge/.enabled: se resta presente, il routing Nginx potrebbe continuare a servire HTML statico.', 'static-bridge'), true);
            } else {
                $plugin->log_activity(__('Disattivazione completata, ma il marcatore statico non è stato rimosso.', 'static-bridge'), __('Controlla manualmente wp-content/static-bridge/.enabled. La rimozione delle regole Apache verrà tentata comunque.', 'static-bridge'), true);
            }
        }
        if (!$is_nginx) {
            $rules_removed = $plugin->write_rewrite_rules(false);
            if (!$rules_removed) {
                $plugin->log_activity(__('Disattivazione completata, ma le regole Apache non sono state rimosse.', 'static-bridge'), __('Controlla il blocco Static Bridge in .htaccess. Se il marcatore .enabled è stato rimosso, il routing aggiornato ricade su WordPress.', 'static-bridge'), true);
            }
        }
        if (!$plugin->sync_strict_marker(false)) {
            $plugin->log_activity(__('Disattivazione completata, ma il marcatore strict non è stato rimosso.', 'static-bridge'), __('Controlla manualmente wp-content/static-bridge/.strict; dopo la disattivazione la modalità strict non deve restare attiva.', 'static-bridge'), true);
        }
        $routing_disabled = $is_nginx ? $marker_removed : ($marker_removed || $rules_removed);
        // What the Server tab added goes with the plugin: the .htaccess block and Static Bridge's own drop-in.
        $htaccess = trailingslashit(ABSPATH) . '.htaccess';
        if (is_file($htaccess) && Static_Bridge_Server_Tuning::htaccess_has_block((string) @file_get_contents($htaccess))
            && is_wp_error(Static_Bridge_Server_Tuning::write_htaccess_block($htaccess, false))) {
            $plugin->log_activity(__('Disattivazione completata, ma il blocco di compressione e cache non è stato tolto da .htaccess.', 'static-bridge'), __('Toglilo a mano: va da «# BEGIN StaticBridge-Server» a «# END StaticBridge-Server».', 'static-bridge'), true);
        }
        if ('ours' === Static_Bridge_Object_Cache::dropin_state()) {
            $removed = Static_Bridge_Object_Cache::remove();
            if (is_wp_error($removed)) {
                $plugin->log_activity(__('Disattivazione completata, ma l’object cache di Static Bridge è rimasta attiva.', 'static-bridge'), $removed->get_error_message(), true);
            }
        }
        // The edge may still hold static HTML; no cron hook runs once the plugin is inactive.
        $plugin->cloudflare_purge_everything_now(__('plugin disattivato', 'static-bridge'));
        if ($routing_disabled) {
            $plugin->log_activity(__('Static Bridge disattivato: il frontend torna a WordPress.', 'static-bridge'));
        } else {
            $plugin->log_activity(__('Static Bridge disattivato, ma il routing statico potrebbe essere ancora attivo.', 'static-bridge'), __('Il marcatore Nginx e le regole Apache non sono stati rimossi. Ripristina il routing WordPress prima di lasciare il sito online.', 'static-bridge'), true);
        }
    }

    public function register_admin_page()
    {
        // An administrator always sees the page; static_bridge_export_capability opens it to others (2.5.0).
        add_menu_page(
            __('Static Bridge', 'static-bridge'),
            __('Static Bridge', 'static-bridge'),
            current_user_can('manage_options') ? 'manage_options' : $this->export_capability(),
            self::ADMIN_SLUG,
            array($this, 'render_admin_page'),
            'dashicons-cloud',
            58
        );
    }

    public function register_post_push_meta_box($post_type, $post)
    {
        if (!($post instanceof WP_Post)
            || !$this->is_public_incremental_post($post)
            || $this->is_shared_content_post_type($post->post_type)
            || !current_user_can('edit_post', (int) $post->ID)) {
            return;
        }

        add_meta_box(
            'static-bridge-post-push',
            __('Static Bridge', 'static-bridge'),
            array($this, 'render_post_push_meta_box'),
            sanitize_key($post_type),
            'side',
            'high'
        );
    }

    public function render_post_push_meta_box($post)
    {
        if (!($post instanceof WP_Post) || !current_user_can('edit_post', (int) $post->ID)) {
            return;
        }

        if ($this->can_push_post($post)) {
            echo '<p>' . esc_html__('Elabora subito la route di questo contenuto e accoda solo le pagine di archivio correlate; non avvia un export completo.', 'static-bridge') . '</p>';
            $unavailable = $this->post_push_unavailable_reason($post);
            if ('' !== $unavailable) {
                echo '<p class="description">' . esc_html($unavailable) . '</p>';
            } else {
                $url = $this->post_push_action_url((int) $post->ID);
                echo '<p><a class="button button-primary" href="' . esc_url($url) . '">' . esc_html__('Aggiorna copia statica', 'static-bridge') . '</a></p>';
            }
        }
        $this->render_editor_exclusion_field($post);
    }

    /**
     * The checkbox «Non salvare questa pagina in statico» (2.5.0). No form of its own: it is saved with the post
     * (classic editor, or the meta box request of the block editor) by save_post_static_exclusion().
     */
    private function render_editor_exclusion_field($post)
    {
        $post_id = (int) $post->ID;
        $excluded = '1' === (string) get_post_meta($post_id, self::EDITOR_EXCLUDE_META, true);
        $entries = $this->editor_exclusion_entries();
        $full = !$excluded && !isset($entries[$post_id]) && count($entries) >= self::MAX_EDITOR_EXCLUDED_POSTS;
        wp_nonce_field('static_bridge_editor_exclude_' . $post_id, 'static_bridge_exclude_nonce');
        echo '<p><label for="static-bridge-exclude"><input type="checkbox" id="static-bridge-exclude" name="static_bridge_exclude" value="1"'
            . ($excluded ? ' checked="checked"' : '') . ($full ? ' disabled="disabled"' : '') . '> '
            . esc_html__('Non salvare questa pagina in statico', 'static-bridge') . '</label></p>';
        echo '<p class="description">' . esc_html__('La pagina e le sue sottopagine restano servite da WP e la copia statica esistente viene tolta. La scelta vale quando salvi il contenuto.', 'static-bridge') . '</p>';
        if ($full) {
            echo '<p class="description">' . esc_html(sprintf(
                /* translators: %s: maximum number of contents */
                __('Ci sono già %s contenuti esclusi dall’editor: togli la spunta da uno di loro o usa i percorsi dinamici nelle Impostazioni.', 'static-bridge'),
                number_format_i18n(self::MAX_EDITOR_EXCLUDED_POSTS)
            )) . '</p>';
        }
        if ($this->server_uses_nginx()) {
            echo '<p class="description">' . esc_html__('Su Nginx la scelta vale solo dopo che un amministratore ha aggiornato il server.', 'static-bridge')
                . ' ' . esc_html__('Copia il blocco Nginx aggiornato e ricarica Nginx.', 'static-bridge') . '</p>';
        }
    }

    public function add_post_push_row_action($actions, $post)
    {
        if (!is_array($actions)
            || !($post instanceof WP_Post)
            || !$this->can_push_post($post)
            || '' !== $this->post_push_unavailable_reason($post)) {
            return $actions;
        }

        $url = $this->post_push_action_url((int) $post->ID);
        $actions['static_bridge_push'] = '<a href="' . esc_url($url) . '">' . esc_html__('Push alla versione statica', 'static-bridge') . '</a>';
        return $actions;
    }

    private function post_push_action_url($post_id)
    {
        $url = add_query_arg(
            array('action' => 'static_bridge_push_post', 'post_id' => absint($post_id)),
            admin_url('admin-post.php')
        );
        return wp_nonce_url($url, 'static_bridge_push_post_' . absint($post_id));
    }

    /**
     * Whether the current user may push this content (2.5.0). The default is edit_post on the content, as before;
     * static_bridge_can_push_post( bool $allowed, WP_Post $post, int $user_id ) may narrow it, and widen it only up
     * to edit_post: without edit_post on the content there is never a push. Only boolean true allows.
     */
    private function can_push_post($post)
    {
        if (!($post instanceof WP_Post) || (int) $post->ID < 1) {
            return false;
        }
        $can_edit = current_user_can('edit_post', (int) $post->ID);
        $allowed = apply_filters('static_bridge_can_push_post', $can_edit, $post, get_current_user_id());
        return $can_edit && true === $allowed;
    }

    /**
     * «Aggiorna la copia statica» in the admin bar (2.5.0), on the front end of a single content and on its edit
     * screen: the same link and nonce as the push of the meta box. Nothing for who may not push it.
     */
    public function add_admin_bar_push_node($wp_admin_bar)
    {
        if (!is_object($wp_admin_bar) || !method_exists($wp_admin_bar, 'add_node')) {
            return;
        }
        $post = $this->admin_bar_post();
        if (!$post || !$this->can_push_post($post) || '' !== $this->post_push_unavailable_reason($post)) {
            return;
        }
        $wp_admin_bar->add_node(array(
            'id' => 'static-bridge-push',
            'title' => esc_html__('Aggiorna la copia statica', 'static-bridge'),
            'href' => $this->post_push_action_url((int) $post->ID),
        ));
    }

    /** The single content the admin bar is shown for: the queried one on the front end, the edited one in wp-admin. */
    private function admin_bar_post()
    {
        if (is_admin()) {
            $screen = function_exists('get_current_screen') ? get_current_screen() : null;
            if (!is_object($screen) || !isset($screen->base) || 'post' !== $screen->base
                || !isset($_GET['post']) || !is_scalar($_GET['post'])) {
                return null;
            }
            $post = get_post(absint(wp_unslash($_GET['post'])));
        } else {
            if (!function_exists('is_singular') || !is_singular() || !function_exists('get_queried_object')) {
                return null;
            }
            $post = get_queried_object();
        }
        return $post instanceof WP_Post ? $post : null;
    }

    public function handle_post_push()
    {
        $post_id = isset($_REQUEST['post_id']) && is_scalar($_REQUEST['post_id']) ? absint(wp_unslash($_REQUEST['post_id'])) : 0;
        $post = $post_id > 0 ? get_post($post_id) : null;
        if ($post_id < 1 || !current_user_can('edit_post', $post_id)
            || ($post instanceof WP_Post && !$this->can_push_post($post))) {
            wp_die(esc_html__('Non hai i permessi per aggiornare la copia statica di questo contenuto.', 'static-bridge'), '', array('response' => 403));
        }
        check_admin_referer('static_bridge_push_post_' . $post_id);

        $push_token = wp_generate_uuid4();
        $queued = $post instanceof WP_Post ? $this->queue_manual_post_push($post, $push_token) : new WP_Error('static_bridge_push_post_missing', __('Il contenuto richiesto non è disponibile.', 'static-bridge'));
        $status = true === $queued ? 'queued' : 'unavailable';
        if (is_wp_error($queued)) {
            $this->log_activity(__('Push statico non accodato.', 'static-bridge'), $queued->get_error_message(), true);
        } else {
            $this->process_manual_post_push_now($post, $push_token);
        }

        $redirect = get_edit_post_link($post_id, 'raw');
        if (!$redirect) {
            $redirect = admin_url('edit.php');
        }
        $redirect_args = array('static_bridge_push' => $status, 'post' => $post_id);
        if (true === $queued) {
            $redirect_args['static_bridge_push_token'] = $push_token;
        }
        wp_safe_redirect(add_query_arg($redirect_args, $redirect));
        exit;
    }

    public function handle_post_push_status()
    {
        $token = isset($_REQUEST['token']) ? $this->sanitize_post_push_token(wp_unslash($_REQUEST['token'])) : '';
        $record = $this->post_push_status_record($token);
        $post_id = is_array($record) && isset($record['post_id']) ? absint($record['post_id']) : 0;
        if (!$post_id || !current_user_can('edit_post', $post_id) || !isset($record['user_id'])
            || ((int) $record['user_id'] !== get_current_user_id() && !current_user_can('manage_options'))) {
            wp_send_json_error(array('message' => __('Non hai i permessi per leggere lo stato di questo push.', 'static-bridge')), 403);
        }
        check_admin_referer('static_bridge_post_push_status_' . $post_id);

        wp_send_json_success(array(
            'status' => isset($record['status']) ? sanitize_key($record['status']) : 'queued',
            'lastError' => isset($record['last_error']) ? sanitize_text_field($record['last_error']) : '',
            'updatedAt' => isset($record['updated_at']) ? absint($record['updated_at']) : 0,
        ));
    }

    public function render_post_push_notice()
    {
        if (!isset($_GET['static_bridge_push'], $_GET['post'])) {
            return;
        }
        $status = sanitize_key(wp_unslash($_GET['static_bridge_push']));
        $post_id = absint(wp_unslash($_GET['post']));
        if (!in_array($status, array('queued', 'unavailable'), true)
            || $post_id < 1
            || !current_user_can('edit_post', $post_id)) {
            return;
        }

        if ('queued' === $status) {
            $token = isset($_GET['static_bridge_push_token']) ? $this->sanitize_post_push_token(wp_unslash($_GET['static_bridge_push_token'])) : '';
            $record = $this->post_push_status_record($token);
            if (!is_array($record) || empty($record['post_id']) || !isset($record['user_id'], $record['status'])
                || (int) $record['post_id'] !== $post_id || (int) $record['user_id'] !== get_current_user_id()) {
                return;
            }
            if ('completed' === $record['status']) {
                echo '<div class="notice notice-success is-dismissible"><p>' . esc_html__('Copia statica aggiornata e pubblicata correttamente.', 'static-bridge') . '</p></div>';
                return;
            }
            if ('failed' === $record['status']) {
                echo '<div class="notice notice-error is-dismissible"><p>' . esc_html(sprintf(
                    /* translators: %s: error message, or a hint to check the route and the logs */
                    __('Push non completato: %s', 'static-bridge'),
                    isset($record['last_error']) ? $record['last_error'] : __('verifica la route e i log di Static Bridge.', 'static-bridge')
                )) . '</p></div>';
                return;
            }
            $notice_state = isset($record['status']) && 'retrying' === $record['status'] ? 'retrying' : 'queued';
            $notice_text = 'retrying' === $notice_state
                ? __('Aggiornamento statico in retry: la copia esistente resta online. Attendo la conferma della scrittura riuscita…', 'static-bridge')
                : __('Push in coda: la copia esistente resta online. Il completamento verrà confermato solo dopo la scrittura della nuova pagina statica.', 'static-bridge');
            $last_error = isset($record['last_error']) ? $record['last_error'] : '';
            echo '<div id="static-bridge-post-push-status" class="notice notice-info" role="status" aria-live="polite" data-state="' . esc_attr($notice_state) . '" data-last-error="' . esc_attr($last_error) . '"><p>' . esc_html($notice_text) . '</p></div>';
            return;
        }
        echo '<div class="notice notice-warning is-dismissible"><p>' . esc_html__('Push non accodato: verifica che il contenuto sia pubblicato, che esista una release statica e che gli aggiornamenti incrementali siano attivi. I percorsi esclusi o dinamici non possono essere staticizzati.', 'static-bridge') . '</p></div>';
    }

    private function post_push_unavailable_reason($post)
    {
        if (!($post instanceof WP_Post)
            || !$this->is_public_incremental_post($post)
            || $this->is_shared_content_post_type($post->post_type)) {
            return __('Questo tipo di contenuto non può essere aggiornato singolarmente.', 'static-bridge');
        }
        if ('publish' !== $post->post_status || !empty($post->post_password)) {
            return __('Il push è disponibile solo per contenuti pubblicati e non protetti da password.', 'static-bridge');
        }
        if (empty($this->settings()['incremental_enabled'])) {
            return __('Attiva gli aggiornamenti incrementali nelle impostazioni di Static Bridge.', 'static-bridge');
        }
        if (!$this->current_release()) {
            return __('Pubblica prima una release statica completa.', 'static-bridge');
        }
        $path = $this->normalize_route_path(get_permalink($post));
        if ('' === $path) {
            return __('Il permalink non è una route statica valida.', 'static-bridge');
        }
        if ($this->is_excluded_path($path)) {
            return __('Questo percorso è escluso o dinamico e resta gestito da WordPress.', 'static-bridge');
        }
        return '';
    }

    /**
     * The stored editor exclusions, checked again on every read: post ID => route paths. At most
     * MAX_EDITOR_EXCLUDED_POSTS contents and MAX_EDITOR_EXCLUDED_PATHS paths; anything else in the option is dropped.
     */
    private function editor_exclusion_entries()
    {
        $stored = get_option(self::EDITOR_EXCLUDED_OPTION, array());
        if (is_array($this->editor_exclusion_cache) && $this->editor_exclusion_cache[0] === $stored) {
            return $this->editor_exclusion_cache[1];
        }
        $entries = array();
        $count = 0;
        foreach (is_array($stored) ? $stored : array() as $post_id => $paths) {
            $post_id = is_int($post_id) || (is_string($post_id) && ctype_digit($post_id)) ? (int) $post_id : 0;
            if ($post_id < 1 || !is_array($paths) || count($entries) >= self::MAX_EDITOR_EXCLUDED_POSTS) {
                continue;
            }
            $clean = array();
            foreach ($paths as $path) {
                $path = $this->normalize_route_path($path);
                if ('' !== $path && !in_array($path, $clean, true) && $count < self::MAX_EDITOR_EXCLUDED_PATHS) {
                    $clean[] = $path;
                    $count++;
                }
            }
            if (!empty($clean)) {
                $entries[$post_id] = $clean;
            }
        }
        $this->editor_exclusion_cache = array($stored, $entries);
        return $entries;
    }

    /** Route paths of the contents excluded from the editor, for settings(): read from the option only. */
    private function editor_excluded_paths()
    {
        $paths = array();
        foreach ($this->editor_exclusion_entries() as $entry_paths) {
            $paths = array_merge($paths, $entry_paths);
        }
        return array_values(array_unique($paths));
    }

    /** The routes of a published public content: its permalink and the same page in the site's other languages. */
    private function editor_exclusion_paths_for_post($post)
    {
        if (!($post instanceof WP_Post) || 'publish' !== $post->post_status
            || !$this->is_public_incremental_post($post) || $this->is_shared_content_post_type($post->post_type)) {
            return array();
        }
        $permalink = get_permalink($post);
        if (!is_string($permalink) || '' === $permalink) {
            return array();
        }
        $paths = array();
        foreach ($this->with_translated_urls(array($permalink)) as $url) {
            $path = $this->normalize_route_path($url);
            if ('' !== $path && !in_array($path, $paths, true)) {
                $paths[] = $path;
            }
        }
        return array_slice($paths, 0, 1 + self::MAX_TRANSLATED_URLS);
    }

    /**
     * save_post: stores the editor checkbox (only with its own nonce and edit_post), then brings the stored paths in
     * line with the post, whose slug, parent or status may have changed. Saving a page may move the routes of its
     * children, so a hierarchical content rechecks every excluded one (at most MAX_EDITOR_EXCLUDED_POSTS).
     */
    public function save_post_static_exclusion($post_id, $post)
    {
        $post_id = absint($post_id);
        if ($post_id < 1 || !is_object($post) || wp_is_post_revision($post_id) || wp_is_post_autosave($post_id)
            || (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE)) {
            return;
        }
        $choice_saved = false;
        if (isset($_POST['static_bridge_exclude_nonce']) && is_string($_POST['static_bridge_exclude_nonce'])
            && wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['static_bridge_exclude_nonce'])), 'static_bridge_editor_exclude_' . $post_id)
            && current_user_can('edit_post', $post_id)) {
            $wanted = isset($_POST['static_bridge_exclude']) && is_string($_POST['static_bridge_exclude'])
                && '1' === wp_unslash($_POST['static_bridge_exclude']);
            $current = '1' === (string) get_post_meta($post_id, self::EDITOR_EXCLUDE_META, true);
            $entries = $this->editor_exclusion_entries();
            if ($wanted && !$current && !isset($entries[$post_id]) && count($entries) >= self::MAX_EDITOR_EXCLUDED_POSTS) {
                $this->log_activity(
                    __('Contenuto non escluso dalla copia statica: limite raggiunto.', 'static-bridge'),
                    sprintf(/* translators: %s: maximum number of contents */ __('Si possono escludere dall’editor al massimo %s contenuti; per altri percorsi usa i percorsi dinamici nelle Impostazioni.', 'static-bridge'), number_format_i18n(self::MAX_EDITOR_EXCLUDED_POSTS)),
                    true
                );
            } elseif ($wanted && !$current) {
                update_post_meta($post_id, self::EDITOR_EXCLUDE_META, '1');
                $choice_saved = true;
            } elseif (!$wanted && $current) {
                delete_post_meta($post_id, self::EDITOR_EXCLUDE_META);
                $choice_saved = true;
            }
        }
        $entries = $this->editor_exclusion_entries();
        if (!$choice_saved && !isset($entries[$post_id]) && '1' !== (string) get_post_meta($post_id, self::EDITOR_EXCLUDE_META, true)) {
            if (empty($entries) || !$this->post_may_move_excluded_routes($post)) {
                return;
            }
        }
        $post_ids = array($post_id);
        if (!empty($entries) && $this->post_may_move_excluded_routes($post)) {
            $post_ids = array_merge($post_ids, array_keys($entries));
        }
        $this->sync_editor_exclusions(array_unique($post_ids));
    }

    /** A hierarchical content (a page) carries the routes of its children: renaming it moves them. */
    private function post_may_move_excluded_routes($post)
    {
        $post_type = is_object($post) && isset($post->post_type) ? (string) $post->post_type : '';
        return 'page' === $post_type || (function_exists('is_post_type_hierarchical') && '' !== $post_type && is_post_type_hierarchical($post_type));
    }

    /**
     * deleted_post: a deleted content no longer keeps its route with WP. The object cache may still return the post
     * at this point, so its entry is dropped without reading it.
     */
    public function forget_deleted_post_exclusion($post_id)
    {
        $post_id = absint($post_id);
        if ($post_id > 0 && isset($this->editor_exclusion_entries()[$post_id])) {
            $this->sync_editor_exclusions(array($post_id), true);
        }
    }

    /** permalink_structure_changed: every excluded content gets the routes of the new structure. */
    public function refresh_editor_excluded_paths()
    {
        $entries = $this->editor_exclusion_entries();
        if (!empty($entries)) {
            $this->sync_editor_exclusions(array_keys($entries));
        }
    }

    /**
     * Recomputes the entries of these posts from their meta, status and permalink, writes the option once and
     * applies the difference: copies of newly excluded routes leave the release through the incremental worker (as a
     * removed page does), contents back to static are queued, the server rules are rewritten and, on Nginx, the
     * administrator is told to copy the block again. Returns true when the excluded paths changed.
     */
    private function sync_editor_exclusions($post_ids, $deleted = false)
    {
        $before = $this->editor_exclusion_entries();
        $entries = $before;
        $reincluded = array();
        foreach ((array) $post_ids as $post_id) {
            $post_id = absint($post_id);
            if ($post_id < 1) {
                continue;
            }
            $post = $deleted ? null : get_post($post_id);
            $flagged = $post instanceof WP_Post && '1' === (string) get_post_meta($post_id, self::EDITOR_EXCLUDE_META, true);
            $wanted = $flagged ? $this->editor_exclusion_paths_for_post($post) : array();
            if (empty($wanted)) {
                if (isset($entries[$post_id]) && $post instanceof WP_Post && !$flagged) {
                    $reincluded[] = $post;
                }
                unset($entries[$post_id]);
                continue;
            }
            $others = $entries;
            unset($others[$post_id]);
            $other_paths = 0;
            foreach ($others as $other) {
                $other_paths += count($other);
            }
            if (count($others) >= self::MAX_EDITOR_EXCLUDED_POSTS || $other_paths + count($wanted) > self::MAX_EDITOR_EXCLUDED_PATHS) {
                // Not applied: the checkbox must not say «excluded» for a route that WP does not keep.
                unset($entries[$post_id]);
                delete_post_meta($post_id, self::EDITOR_EXCLUDE_META);
                $this->log_activity(
                    __('Contenuto non escluso dalla copia statica: limite raggiunto.', 'static-bridge'),
                    sprintf(/* translators: %s: maximum number of paths */ __('I percorsi esclusi dall’editor sarebbero più di %s; per altri percorsi usa i percorsi dinamici nelle Impostazioni.', 'static-bridge'), number_format_i18n(self::MAX_EDITOR_EXCLUDED_PATHS)),
                    true
                );
                continue;
            }
            $entries[$post_id] = $wanted;
        }
        if ($entries === $before) {
            return false;
        }
        update_option(self::EDITOR_EXCLUDED_OPTION, $entries, false);

        $old_paths = array();
        foreach ($before as $paths) {
            $old_paths = array_merge($old_paths, $paths);
        }
        $new_paths = $this->editor_excluded_paths();
        $added = array_values(array_diff($new_paths, $old_paths));
        $removed = array_values(array_diff(array_unique($old_paths), $new_paths));
        if (empty($added) && empty($removed)) {
            return false;
        }

        $settings = $this->settings();
        $release = $this->current_release();
        $incremental = !empty($settings['incremental_enabled']) && $release;
        $removing = array();
        if ($incremental) {
            // The worker removes the copy as for a removed page, under its lock and with the manifest and the rules.
            $deletions = array();
            foreach ($added as $path) {
                if (!$this->static_file_exists_for_path($path)) {
                    continue;
                }
                $deletions[sha1($path)] = array(
                    'url' => $this->route_url($path),
                    'path' => $path,
                    'action' => 'delete',
                    'role' => 'single',
                    'post_id' => 0,
                    'builders' => array(),
                    'queued_at' => time(),
                    'token' => wp_generate_uuid4(),
                    'attempts' => 0,
                );
                $removing[] = $path;
            }
            if (!empty($deletions)) {
                $this->change_incremental_queue(function ($queue) use ($deletions) {
                    foreach ($deletions as $key => $deletion) {
                        $queue[$key] = $deletion;
                    }
                    return $queue;
                });
            }
            foreach ($reincluded as $post) {
                if ('publish' === $post->post_status && empty($post->post_password)) {
                    $this->enqueue_incremental_url(get_permalink($post), (int) $post->ID, 'refresh', $this->page_builders($post), 'single');
                }
            }
        }
        $rules_written = $this->update_routing_rules();
        if (!empty($removing)) {
            $this->schedule_incremental_worker_after_change();
        }
        $this->queue_cloudflare_purge(array_map(array($this, 'route_url'), array_merge($added, $removed)), __('percorsi esclusi dall’editor modificati', 'static-bridge'));

        $details = array();
        if (!empty($added)) {
            /* translators: %s: list of paths */
            $details[] = sprintf(__('Restano a WP: %s.', 'static-bridge'), implode(', ', array_slice($added, 0, 10)));
        }
        if (!empty($removed)) {
            /* translators: %s: list of paths */
            $details[] = sprintf(__('Tornano statici: %s.', 'static-bridge'), implode(', ', array_slice($removed, 0, 10)));
        }
        if (!$incremental) {
            $details[] = __('Gli aggiornamenti incrementali sono spenti o manca una release: la copia statica cambia al prossimo export completo.', 'static-bridge');
        }
        $nginx = $this->server_uses_nginx();
        if ($nginx) {
            $details[] = __('Copia il blocco Nginx aggiornato e ricarica Nginx.', 'static-bridge');
        }
        $this->log_activity(__('Percorsi esclusi dall’editor aggiornati.', 'static-bridge'), implode(' ', $details), $nginx);
        if (!$rules_written) {
            $this->log_activity(__('Esclusione dall’editor salvata, ma .htaccess non aggiornato.', 'static-bridge'), __('Il server non consente la scrittura del file .htaccess.', 'static-bridge'), true);
        }
        return true;
    }

    /** The excluded contents listed read-only in Impostazioni: post ID, title, edit link and paths. */
    private function editor_excluded_posts_for_settings()
    {
        $rows = array();
        foreach ($this->editor_exclusion_entries() as $post_id => $paths) {
            $post = get_post($post_id);
            $rows[] = array(
                'title' => is_object($post) ? (string) get_the_title($post) : '',
                'edit_url' => is_object($post) ? (string) get_edit_post_link($post_id, 'raw') : '',
                'paths' => $paths,
                'id' => (int) $post_id,
            );
        }
        return $rows;
    }

    private function queue_manual_post_push($post, $push_token = '')
    {
        $unavailable = $this->post_push_unavailable_reason($post);
        if ('' !== $unavailable) {
            return new WP_Error('static_bridge_push_unavailable', $unavailable);
        }

        $push_token = $this->sanitize_post_push_token($push_token);
        if ('' === $push_token) {
            $push_token = wp_generate_uuid4();
        }
        $post_id = (int) $post->ID;
        $path = $this->normalize_route_path(get_permalink($post));
        $this->maybe_queue_incremental_post($post_id, $post, true, $post);
        $key = sha1($path);
        $in_queue = false;
        $this->change_incremental_queue(function ($queue) use ($key, $push_token, &$in_queue) {
            if (!isset($queue[$key]) || !is_array($queue[$key])) {
                return null;
            }
            $in_queue = true;
            $queue[$key]['manual_push_token'] = $push_token;
            $manual_item = $queue[$key];
            unset($queue[$key]);
            return array($key => $manual_item) + $queue;
        });
        if (!$in_queue) {
            return new WP_Error('static_bridge_push_not_queued', __('La route non è stata aggiunta alla coda incrementale.', 'static-bridge'));
        }
        $queue = $this->incremental_queue();
        if (!isset($queue[$key]['manual_push_token']) || $queue[$key]['manual_push_token'] !== $push_token) {
            return new WP_Error('static_bridge_push_not_queued', __('Non è stato possibile registrare il push nella coda incrementale.', 'static-bridge'));
        }
        if (!$this->set_post_push_status($push_token, 'queued', array(
            'post_id' => $post_id,
            'user_id' => get_current_user_id(),
            'path' => $path,
            'last_error' => '',
        ))) {
            return new WP_Error('static_bridge_push_status_unavailable', __('La route è stata accodata, ma non è stato possibile registrare lo stato del push.', 'static-bridge'));
        }

        $this->log_activity(
            __('Push manuale della pagina statica avviato.', 'static-bridge'),
            $path . ' — ' . __('La coda aggiornerà anche gli archivi correlati.', 'static-bridge')
        );
        return true;
    }

    private function process_manual_post_push_now($post, $push_token)
    {
        $push_token = $this->sanitize_post_push_token($push_token);
        $path = $post instanceof WP_Post ? $this->normalize_route_path(get_permalink($post)) : '';
        $key = '' !== $path ? sha1($path) : '';
        $queue = $this->incremental_queue();
        $item = '' !== $key && isset($queue[$key]) && is_array($queue[$key]) ? $queue[$key] : array();

        if ('' === $push_token || '' === $key || empty($item['manual_push_token'])
            || $this->sanitize_post_push_token($item['manual_push_token']) !== $push_token) {
            $message = __('La route richiesta non è più presente nella coda del push.', 'static-bridge');
            $this->set_post_push_status($push_token, 'failed', array('last_error' => $message));
            $this->log_activity(__('Push manuale non avviato.', 'static-bridge'), $message, true);
            return false;
        }

        if ($this->job_is_running()) {
            $message = __('Push immediato rinviato: è in corso un export completo.', 'static-bridge');
            $this->set_post_push_status($push_token, 'retrying', array('last_error' => $message));
            $this->schedule_incremental_worker_within(60);
            return false;
        }

        $release = $this->current_release();
        if (!$release) {
            $message = __('Push immediato non eseguito: non è disponibile una release statica corrente.', 'static-bridge');
            $this->set_post_push_status($push_token, 'failed', array('last_error' => $message));
            $this->log_activity(__('Push manuale non avviato.', 'static-bridge'), $message, true);
            return false;
        }

        $lock = $this->acquire_incremental_lock();
        if (false === $lock) {
            // The worker (or another push) is rendering: it takes this route too, first in the queue.
            $message = __('Push immediato rinviato: un altro worker incrementale è già in esecuzione.', 'static-bridge');
            $this->set_post_push_status($push_token, 'retrying', array('last_error' => $message));
            $this->schedule_incremental_worker_within(20);
            return false;
        }

        $this->processing_incremental_items = true;
        try {
            $queue = $this->incremental_queue();
            $item = isset($queue[$key]) && is_array($queue[$key]) ? $queue[$key] : array();
            if (empty($item['manual_push_token'])
                || $this->sanitize_post_push_token($item['manual_push_token']) !== $push_token) {
                $message = __('La route del push è cambiata prima dell’elaborazione immediata.', 'static-bridge');
                $this->set_post_push_status($push_token, 'failed', array('last_error' => $message));
                $this->log_activity(__('Push manuale non avviato.', 'static-bridge'), $message, true);
                return false;
            }

            $result = $this->process_incremental_item($key, $item, $release);
            return 'done' === $result;
        } catch (Throwable $exception) {
            $message = sanitize_text_field($exception->getMessage());
            if ('' === $message) {
                $message = __('Errore inatteso durante l’elaborazione immediata della route.', 'static-bridge');
            }
            $this->retry_incremental_item($key, $item, $message);
            $this->log_activity(__('Push manuale interrotto; la route resta in coda per il retry.', 'static-bridge'), $path . ' — ' . $message, true);
            return false;
        } finally {
            $this->processing_incremental_items = false;
            $this->release_incremental_lock($lock);
            $this->flush_incremental_cache_signals();
            // Visitors behind Cloudflare should see the pushed page now, not after the edge TTL.
            $this->run_cloudflare_purge(1);
        }
    }

    private function sanitize_post_push_token($token)
    {
        if (!is_string($token)) {
            return '';
        }
        $token = strtolower(trim($token));
        return preg_match('/^[a-f0-9-]{36}$/', $token) ? $token : '';
    }

    private function post_push_status_record($token)
    {
        $token = $this->sanitize_post_push_token($token);
        if ('' === $token) {
            return false;
        }
        $records = get_option(self::POST_PUSH_STATUS_OPTION, array());
        return is_array($records) && isset($records[$token]) && is_array($records[$token]) ? $records[$token] : false;
    }

    private function set_post_push_status($token, $status, $details = array())
    {
        $token = $this->sanitize_post_push_token($token);
        if ('' === $token || !in_array($status, array('queued', 'retrying', 'completed', 'failed'), true)) {
            return false;
        }
        $records = get_option(self::POST_PUSH_STATUS_OPTION, array());
        $records = is_array($records) ? $records : array();
        $record = isset($records[$token]) && is_array($records[$token]) ? $records[$token] : array();
        $record = array_merge($record, is_array($details) ? $details : array());
        $record['status'] = $status;
        $record['updated_at'] = time();
        $records[$token] = $record;

        foreach ($records as $record_token => $stored_record) {
            if (!is_array($stored_record) || empty($stored_record['updated_at']) || time() - (int) $stored_record['updated_at'] > 604800) {
                unset($records[$record_token]);
            }
        }
        if (count($records) > 50) {
            uasort($records, function ($left, $right) {
                return (int) (isset($left['updated_at']) ? $left['updated_at'] : 0)
                    - (int) (isset($right['updated_at']) ? $right['updated_at'] : 0);
            });
            $records = array_slice($records, -50, null, true);
        }
        update_option(self::POST_PUSH_STATUS_OPTION, $records, false);
        $saved = get_option(self::POST_PUSH_STATUS_OPTION, array());
        return isset($saved[$token]) && is_array($saved[$token]) && $saved[$token]['status'] === $status;
    }

    public function enqueue_admin_assets($hook)
    {
        if ('toplevel_page_' . self::ADMIN_SLUG !== $hook) {
            if ('post.php' !== $hook || !isset($_GET['static_bridge_push_token'], $_GET['post'])) {
                return;
            }
            $token = $this->sanitize_post_push_token(wp_unslash($_GET['static_bridge_push_token']));
            $post_id = absint(wp_unslash($_GET['post']));
            $record = $this->post_push_status_record($token);
            if (!is_array($record) || empty($record['post_id']) || (int) $record['post_id'] !== $post_id
                || !isset($record['user_id']) || (int) $record['user_id'] !== get_current_user_id()
                || !current_user_can('edit_post', $post_id)) {
                return;
            }
            wp_enqueue_script('static-bridge-post-push', plugin_dir_url(__FILE__) . 'assets/post-push.js', array(), self::VERSION, true);
            wp_localize_script('static-bridge-post-push', 'StaticBridgePostPush', array(
                'statusUrl' => admin_url('admin-post.php'),
                'nonce' => wp_create_nonce('static_bridge_post_push_status_' . $post_id),
                'token' => $token,
                'strings' => array(
                    'queued' => __('Push in coda: la copia statica esistente resta online. Il completamento verrà confermato solo dopo la scrittura della nuova pagina statica.', 'static-bridge'),
                    'retrying' => __('Aggiornamento statico in retry: la copia esistente resta online. Attendo la conferma della scrittura riuscita…', 'static-bridge'),
                    'completed' => __('Copia statica aggiornata e pubblicata correttamente.', 'static-bridge'),
                    'failed' => __('Push non completato: ', 'static-bridge'),
                    'statusError' => __('Non riesco a verificare l’esito del push; nessun successo è stato confermato. Ricarica più tardi per ricontrollare lo stato.', 'static-bridge'),
                ),
            ));
            return;
        }
        wp_enqueue_style('static-bridge-admin', plugin_dir_url(__FILE__) . 'assets/admin.css', array(), self::VERSION);
        wp_enqueue_script('static-bridge-admin', plugin_dir_url(__FILE__) . 'assets/admin.js', array('wp-i18n'), self::VERSION, true);
        if (class_exists('Static_Bridge_I18n')) {
            Static_Bridge_I18n::script('static-bridge-admin');
        }
        wp_localize_script('static-bridge-admin', 'StaticBridgeAdmin', array(
            'ajaxUrl' => admin_url('admin-ajax.php'),
            'nonce' => wp_create_nonce(self::AJAX_NONCE),
            'isRunning' => $this->job_is_running() ? 1 : 0,
            'isResumable' => $this->job_is_resumable() ? 1 : 0,
            'isDiagnosticRunning' => $this->diagnostic_is_running() ? 1 : 0,
            'urls' => array(
                'forms' => $this->tab_url('forms'),
                'settings' => $this->tab_url('settings'),
                'generate' => $this->tab_url('generate'),
                'server' => $this->tab_url('server'),
            ),
            // The Server tab runs its first check by itself.
            'serverCheckAutoRun' => isset($_GET['tab']) && 'server' === sanitize_key(wp_unslash($_GET['tab'])) && 0 === $this->server_check_state()['completed_at'] ? 1 : 0,
            'retryLimit' => self::MAX_EXPORT_HTTP_RETRIES,
            'strings' => array(
                'starting' => __('Preparazione esportazione…', 'static-bridge'),
                'running' => __('Esportazione in corso…', 'static-bridge'),
                'resume' => __('Riprendi esportazione', 'static-bridge'),
                'paused' => __('Esportazione in pausa', 'static-bridge'),
                'pausedMessage' => __('Questa coda proviene da una versione precedente: riprendi per registrare l’errore della URL già fallita e continuare senza rifare l’export.', 'static-bridge'),
                'start' => __('Avvia export completo', 'static-bridge'),
                'retrying' => __('Nuovo tentativo di rendering', 'static-bridge'),
                'complete' => __('Pubblicazione completata', 'static-bridge'),
                'completeWithErrors' => /* translators: %d: number of URLs with errors */ __('Pubblicazione completata con errori su %d URL', 'static-bridge'),
                'failed' => __('Esportazione interrotta', 'static-bridge'),
                'connectionLost' => __('Stato dell’esportazione non verificabile', 'static-bridge'),
                'connectionRetrying' => __('Collegamento instabile; verifico di nuovo lo stato…', 'static-bridge'),
                'connectionLostMessage' => __('Non riesco a verificare il server in questo momento. Continuo a controllare automaticamente; nessuna release parziale viene pubblicata.', 'static-bridge'),
                'workerBusy' => __('Worker occupato o in ripristino; ricontrollo tra qualche secondo…', 'static-bridge'),
                'cancelled' => __('Esportazione annullata', 'static-bridge'),
                'cancelledMessage' => __('La release parziale è rimasta in staging e non è stata pubblicata né rimossa.', 'static-bridge'),
                'cancel' => __('Annulla esportazione', 'static-bridge'),
                'scanning' => __('scansione inventario', 'static-bridge'),
                'parallelMode' => /* translators: %d: maximum number of pages rendered in parallel */ __('rendering parallelo fino a %d pagine', 'static-bridge'),
                'sequentialMode' => __('rendering sequenziale', 'static-bridge'),
                'issuesTitle' => __('URL da controllare', 'static-bridge'),
                'issuesHelp' => __('Le URL con errori non fermano l’export. Se esiste una copia precedente valida, viene mantenuta; controlla i dettagli nella sezione Attività.', 'static-bridge'),
                'diagnosticStarting' => __('Preparazione dei controlli…', 'static-bridge'),
                'diagnosticRunning' => __('Test in corso…', 'static-bridge'),
                'diagnosticResume' => __('Riprendi test', 'static-bridge'),
                'diagnosticStart' => __('Esegui test ora', 'static-bridge'),
                'diagnosticPassed' => __('Test completato: tutto regolare', 'static-bridge'),
                'diagnosticWarning' => __('Test completato con avvisi', 'static-bridge'),
                'diagnosticFailed' => __('Test completato: problemi rilevati', 'static-bridge'),
                'requestError' => __('La richiesta non è riuscita. Riprova o apri Attività per i dettagli.', 'static-bridge'),
                'serverCheckRunning' => __('Controllo in corso…', 'static-bridge'),
                'serverCheckStart' => __('Ricontrolla', 'static-bridge'),
            ),
        ));
    }

    public function render_admin_page()
    {
        // An administrator sees every tab; who has only static_bridge_export_capability sees Genera and Attività (2.5.0).
        $full_access = current_user_can('manage_options');
        if (!$full_access && !$this->can_run_exports()) {
            return;
        }

        $tab = isset($_GET['tab']) && is_string($_GET['tab']) ? sanitize_key(wp_unslash($_GET['tab'])) : 'generate';
        $allowed_tabs = $full_access
            ? array('generate', 'forms', 'settings', 'server', 'versions', 'diagnostics', 'activity')
            : array('generate', 'activity');
        if (!in_array($tab, $allowed_tabs, true)) {
            $tab = 'generate';
        }
        $job = get_option(self::JOB_OPTION, array());
        $job_running = $this->job_is_running();
        $job_resumable = $this->job_is_resumable();
        $job_progress = ($job_running || $job_resumable) ? $this->job_response($job) : array();
        $settings = $this->settings();
        $release = $this->current_release();
        $generated_count = $release ? $this->count_html_files($release) : 0;
        $activity = get_option(self::ACTIVITY_OPTION, array());
        $diagnostic = get_option(self::DIAGNOSTIC_OPTION, array());
        $diagnostic_history = get_option(self::DIAGNOSTIC_HISTORY_OPTION, array());
        $incremental_queue = $this->incremental_queue();
        $release_id = $release ? basename($release) : '';
        $dependency_index = new Static_Bridge_Dependency_Index();
        $dependency_state = '' !== $release_id ? $dependency_index->state($release_id) : null;
        $dependency_queue_count = '' !== $release_id ? $dependency_index->pending_count($release_id) : 0;
        $dependency_queue_count = is_int($dependency_queue_count) ? $dependency_queue_count : 0;
        $incremental_queue_count = count($incremental_queue) + $dependency_queue_count;
        ?>
        <div class="wrap sb-wrap">
            <div class="sb-header">
                <div class="sb-brand-mark" aria-hidden="true"><span class="dashicons dashicons-cloud" aria-hidden="true"></span></div>
                <div class="sb-heading">
                    <p class="sb-eyebrow">STATIC BRIDGE</p>
                    <h1><?php esc_html_e('Pubblica WordPress come HTML statico', 'static-bridge'); ?></h1>
                    <p><?php esc_html_e('Puoi pubblicare il frontend come file statici sullo stesso dominio; wp-admin e i percorsi dinamici restano gestiti da WordPress.', 'static-bridge'); ?></p>
                </div>
                <a class="button sb-view-site" href="<?php echo esc_url(home_url('/')); ?>" target="_blank" rel="noopener noreferrer">
                    <?php esc_html_e('Apri il sito', 'static-bridge'); ?> <span class="dashicons dashicons-external" aria-hidden="true"></span>
                </a>
            </div>

            <nav class="nav-tab-wrapper sb-tabs" aria-label="<?php esc_attr_e('Sezioni Static Bridge', 'static-bridge'); ?>">
                <a class="nav-tab <?php echo 'generate' === $tab ? 'nav-tab-active' : ''; ?>" <?php echo 'generate' === $tab ? 'aria-current="page"' : ''; ?> href="<?php echo esc_url($this->tab_url('generate')); ?>"><span class="dashicons dashicons-controls-play" aria-hidden="true"></span><?php esc_html_e('Genera', 'static-bridge'); ?></a>
                <?php if ($full_access) : ?>
                <a class="nav-tab <?php echo 'forms' === $tab ? 'nav-tab-active' : ''; ?>" <?php echo 'forms' === $tab ? 'aria-current="page"' : ''; ?> href="<?php echo esc_url($this->tab_url('forms')); ?>"><span class="dashicons dashicons-feedback" aria-hidden="true"></span><?php esc_html_e('Moduli', 'static-bridge'); ?></a>
                <a class="nav-tab <?php echo 'settings' === $tab ? 'nav-tab-active' : ''; ?>" <?php echo 'settings' === $tab ? 'aria-current="page"' : ''; ?> href="<?php echo esc_url($this->tab_url('settings')); ?>"><span class="dashicons dashicons-admin-generic" aria-hidden="true"></span><?php esc_html_e('Impostazioni', 'static-bridge'); ?></a>
                <a class="nav-tab <?php echo 'server' === $tab ? 'nav-tab-active' : ''; ?>" <?php echo 'server' === $tab ? 'aria-current="page"' : ''; ?> href="<?php echo esc_url($this->tab_url('server')); ?>"><span class="dashicons dashicons-performance" aria-hidden="true"></span><?php esc_html_e('Server', 'static-bridge'); ?></a>
                <a class="nav-tab <?php echo 'versions' === $tab ? 'nav-tab-active' : ''; ?>" <?php echo 'versions' === $tab ? 'aria-current="page"' : ''; ?> href="<?php echo esc_url($this->tab_url('versions')); ?>"><span class="dashicons dashicons-backup" aria-hidden="true"></span><?php esc_html_e('Versioni', 'static-bridge'); ?></a>
                <a class="nav-tab <?php echo 'diagnostics' === $tab ? 'nav-tab-active' : ''; ?>" <?php echo 'diagnostics' === $tab ? 'aria-current="page"' : ''; ?> href="<?php echo esc_url($this->tab_url('diagnostics')); ?>"><span class="dashicons dashicons-heart" aria-hidden="true"></span><?php esc_html_e('Diagnostica', 'static-bridge'); ?></a>
                <?php endif; ?>
                <a class="nav-tab <?php echo 'activity' === $tab ? 'nav-tab-active' : ''; ?>" <?php echo 'activity' === $tab ? 'aria-current="page"' : ''; ?> href="<?php echo esc_url($this->tab_url('activity')); ?>"><span class="dashicons dashicons-list-view" aria-hidden="true"></span><?php esc_html_e('Attività', 'static-bridge'); ?></a>
            </nav>
            <hr class="wp-header-end">

            <?php if (isset($_GET['settings-updated'])) : ?>
                <div class="notice notice-success is-dismissible"><p><?php esc_html_e('Impostazioni salvate.', 'static-bridge'); ?></p></div>
            <?php endif; ?>
            <?php if (isset($_GET['versions-run'])) : ?>
                <?php $versions_notice = get_option(self::RETENTION_LAST_OPTION, array()); ?>
                <?php if (is_array($versions_notice) && !empty($versions_notice['message'])) : ?>
                    <div class="notice <?php echo in_array($versions_notice['status'] ?? '', array('error', 'busy'), true) || !empty($versions_notice['refused']) || !empty($versions_notice['failed']) ? 'notice-warning' : 'notice-success'; ?> is-dismissible"><p><?php echo esc_html($versions_notice['message']); ?></p></div>
                <?php endif; ?>
            <?php endif; ?>
            <?php if (isset($_GET['retention-enabled'])) : ?>
                <div class="notice notice-success is-dismissible"><p><?php esc_html_e('Pulizia automatica attivata: tra un minuto e dopo ogni pubblicazione riuscita restano la versione online, una precedente e quelle protette.', 'static-bridge'); ?></p></div>
            <?php endif; ?>
            <?php if ($full_access && 'generate' === $tab && empty($settings['retention_enabled'])) : ?>
                <?php $versions_waste = $this->release_cleanup_count(); ?>
                <?php if ($versions_waste >= 3) : ?>
                    <div class="notice notice-info"><p><?php echo esc_html(sprintf(/* translators: %s: number of folders */ _n('Sul disco c’è %s versione statica che non serve più.', 'Sul disco ci sono %s versioni statiche che non servono più.', $versions_waste, 'static-bridge'), number_format_i18n($versions_waste))); ?> <a href="<?php echo esc_url($this->tab_url('versions')); ?>"><?php esc_html_e('Apri Versioni', 'static-bridge'); ?></a></p></div>
                <?php endif; ?>
            <?php endif; ?>
            <?php if (isset($_GET['retention-run'])) : ?>
                <?php $retention_notice = get_option(self::RETENTION_LAST_OPTION, array()); ?>
                <?php if (is_array($retention_notice) && !empty($retention_notice['message'])) : ?>
                    <div class="notice <?php echo in_array($retention_notice['status'] ?? '', array('error', 'busy'), true) || !empty($retention_notice['failed']) ? 'notice-warning' : 'notice-success'; ?> is-dismissible"><p><?php echo esc_html($retention_notice['message']); ?></p></div>
                <?php endif; ?>
            <?php endif; ?>
            <?php if (isset($_GET['refresh'])) : ?>
                <?php
                $refresh_notices = array(
                    'queued' => array('notice-success', __('Pagine statiche in coda per la rigenerazione. La versione online resta attiva finché ogni pagina non è pronta.', 'static-bridge')),
                    'nothing' => array('notice-info', __('Non c’era nessuna pagina da rigenerare.', 'static-bridge')),
                    'no_release' => array('notice-warning', __('Non c’è ancora una versione statica: avvia un export completo.', 'static-bridge')),
                    'incremental_off' => array('notice-warning', __('Gli aggiornamenti incrementali sono spenti nelle Impostazioni: accendili oppure avvia un export completo.', 'static-bridge')),
                    'failed' => array('notice-error', __('La rigenerazione non è stata messa in coda; i dettagli sono in Attività.', 'static-bridge')),
                );
                $refresh_notice = $refresh_notices[sanitize_key(wp_unslash($_GET['refresh']))] ?? null;
                ?>
                <?php if ($refresh_notice) : ?>
                    <div class="notice <?php echo esc_attr($refresh_notice[0]); ?> is-dismissible"><p><?php echo esc_html($refresh_notice[1]); ?></p></div>
                <?php endif; ?>
            <?php endif; ?>
            <?php if (isset($_GET['link-check'])) : ?>
                <?php
                $link_check_notices = array(
                    'queued' => array('notice-success', __('Controllo dei link programmato: l’esito compare nella scheda Genera fra qualche minuto.', 'static-bridge')),
                    'strict_off' => array('notice-warning', __('Il controllo dei link serve solo con la modalità strict attiva.', 'static-bridge')),
                    'no_release' => array('notice-warning', __('Non c’è ancora una versione statica: avvia un export completo.', 'static-bridge')),
                    'failed' => array('notice-error', __('Il controllo dei link non è stato programmato: WP-Cron ha rifiutato l’evento.', 'static-bridge')),
                );
                $link_check_notice = $link_check_notices[sanitize_key(wp_unslash($_GET['link-check']))] ?? null;
                ?>
                <?php if ($link_check_notice) : ?>
                    <div class="notice <?php echo esc_attr($link_check_notice[0]); ?> is-dismissible"><p><?php echo esc_html($link_check_notice[1]); ?></p></div>
                <?php endif; ?>
            <?php endif; ?>
            <?php if (isset($_GET['forms-updated'])) : ?>
                <div class="notice notice-success is-dismissible"><p><?php esc_html_e('Modalità dei moduli salvate. Le nuove regole di routing sono state aggiornate.', 'static-bridge'); ?></p></div>
            <?php endif; ?>
            <?php if (isset($_GET['forms-rules-error'])) : ?>
                <div class="notice notice-error"><p><?php esc_html_e('Modalità dei moduli salvate nel database, ma .htaccess non è stato aggiornato: il routing attivo potrebbe non corrispondere alla scelta. Verifica permessi e regole Apache prima di considerare applicata la modifica.', 'static-bridge'); ?></p></div>
            <?php endif; ?>

            <?php if ('generate' === $tab) : ?>
                <div class="sb-layout">
                    <div class="sb-main-column">
                        <section class="sb-card sb-generate-card">
                            <div class="sb-card-heading">
                                <div>
                                    <p class="sb-eyebrow"><?php esc_html_e('PUBBLICAZIONE', 'static-bridge'); ?></p>
                                    <h2><?php esc_html_e('Crea una release completa', 'static-bridge'); ?></h2>
                                </div>
                                <span class="sb-status-pill <?php echo $release ? 'is-published' : 'is-draft'; ?>"><span></span><?php echo $release ? esc_html__('Pubblicato', 'static-bridge') : esc_html__('Non ancora pubblicato', 'static-bridge'); ?></span>
                            </div>
                            <div class="sb-release-summary">
                                <div class="sb-release-icon"><span class="dashicons dashicons-media-document" aria-hidden="true"></span></div>
                                <div class="sb-release-details">
                                    <strong><?php echo $release ? esc_html__('Versione statica online', 'static-bridge') : esc_html__('Nessuna versione pubblicata', 'static-bridge'); ?></strong>
                                    <span><?php echo esc_html(sprintf(/* translators: %s: number of HTML pages */ _n('%s pagina HTML', '%s pagine HTML', $generated_count, 'static-bridge'), number_format_i18n($generated_count))); ?><?php if ($release) : ?> · <?php esc_html_e('codice', 'static-bridge'); ?> <code><?php echo esc_html(basename($release)); ?></code><?php endif; ?></span>
                                </div>
                                <span class="sb-release-date"><?php echo $release ? esc_html($this->release_date($release)) : ''; ?></span>
                            </div>
                            <?php $last_page_update = get_option(self::LAST_PAGE_UPDATE_OPTION, array()); ?>
                            <?php if ($release && is_array($last_page_update) && !empty($last_page_update['at']) && !empty($last_page_update['path'])) : ?>
                                <p class="sb-last-page-update"><?php echo esc_html(sprintf(
                                    /* translators: 1: date and time, 2: page path */
                                    __('Ultimo aggiornamento di una pagina: %1$s (%2$s). Le pagine aggiornate da sole hanno ciascuna la sua data; l’elenco con il motivo è in Attività.', 'static-bridge'),
                                    $this->format_site_datetime((int) $last_page_update['at']),
                                    (string) $last_page_update['path']
                                )); ?> <a href="<?php echo esc_url($this->tab_url('activity')); ?>"><?php esc_html_e('Apri Attività', 'static-bridge'); ?></a></p>
                            <?php endif; ?>

                            <div class="sb-progress-panel" id="sb-progress-panel" <?php echo ($job_running || $job_resumable) ? '' : 'hidden'; ?>>
                                <div class="sb-progress-topline">
                                    <strong id="sb-progress-title"><?php echo $job_running ? esc_html__('Esportazione in corso…', 'static-bridge') : ($job_resumable ? esc_html__('Esportazione in pausa', 'static-bridge') : ''); ?></strong>
                                    <span id="sb-progress-count"><?php echo isset($job_progress['processed'], $job_progress['total']) ? esc_html(number_format_i18n($job_progress['processed']) . ' / ' . number_format_i18n($job_progress['total'])) : ''; ?></span>
                                </div>
                                <div class="sb-progress-track" role="progressbar" aria-label="<?php esc_attr_e('Avanzamento esportazione', 'static-bridge'); ?>" aria-valuemin="0" aria-valuemax="100" aria-valuenow="<?php echo isset($job_progress['progress']) ? (int) $job_progress['progress'] : 0; ?>"><span id="sb-progress-bar" style="width: <?php echo isset($job_progress['progress']) ? (int) $job_progress['progress'] : 0; ?>%"></span></div>
                                <p id="sb-progress-current" class="sb-progress-current"><?php echo $job_resumable && isset($job['current_url']) ? esc_html($job['current_url']) : ''; ?></p>
                                <div id="sb-progress-message" class="sb-progress-message" aria-live="polite"><?php echo $job_resumable ? esc_html__('I tentativi automatici sono esauriti. La URL resta in coda e la release parziale non è pubblicata. Correggi il problema e riprendi, oppure annulla per scartare la coda.', 'static-bridge') : ''; ?></div>
                            </div>

                            <div class="sb-card-actions">
                                <button type="button" class="button button-primary sb-primary-button" id="sb-generate" <?php disabled($job_running); ?>>
                                    <span class="dashicons dashicons-controls-play" aria-hidden="true"></span>
                                    <span class="sb-button-label"><?php echo $job_running ? esc_html__('Esportazione in corso…', 'static-bridge') : ($job_resumable ? esc_html__('Riprendi esportazione', 'static-bridge') : esc_html__('Avvia export completo', 'static-bridge')); ?></span>
                                </button>
                                <button type="button" class="button" id="sb-cancel" <?php echo ($job_running || $job_resumable) ? '' : 'hidden'; ?>><?php esc_html_e('Annulla esportazione', 'static-bridge'); ?></button>
                                <span class="sb-action-note"><?php esc_html_e('Prima di un export ampio esegui la Diagnostica e configura un cron di sistema: WP-Cron da solo non garantisce tempi regolari.', 'static-bridge'); ?></span>
                            </div>
                            <?php $scheduled_export_next = 'off' !== $settings['scheduled_export'] ? (int) wp_next_scheduled(self::SCHEDULED_EXPORT_HOOK) : 0; ?>
                            <?php if ($scheduled_export_next > 0) : ?>
                                <p class="sb-scheduled-export-note" id="sb-scheduled-export-generate"><span class="dashicons dashicons-calendar-alt" aria-hidden="true"></span> <?php echo esc_html(sprintf(/* translators: %s: date and time of the next scheduled export */ __('Prossimo export completo pianificato: %s.', 'static-bridge'), $this->format_site_datetime($scheduled_export_next))); ?><?php if ($full_access) : ?> <a href="<?php echo esc_url($this->tab_url('settings') . '#sb-scheduled-export-field'); ?>"><?php esc_html_e('Configura', 'static-bridge'); ?></a><?php endif; ?></p>
                            <?php endif; ?>

                            <p class="sb-card-copy"><?php esc_html_e('Questa azione crea una nuova release completa e rigenera tutte le pagine. Usala per la prima pubblicazione o dopo modifiche globali non intercettate automaticamente; sui siti grandi può richiedere anche ore. Dopo la prima release, articoli e pagine si aggiornano singolarmente. Blocchi/template Gutenberg, template Bricks, elementi Kadence, dati globali Bricks, stili e loop di Etch e salvataggi del Customizer accodano il refresh di tutti i percorsi statici, senza rifare la scansione completa del sito. La release attuale resta online durante gli aggiornamenti.', 'static-bridge'); ?></p>

                            <?php if ($full_access && $release && !empty($settings['incremental_enabled'])) : ?>
                                <form class="sb-refresh-all" method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>">
                                    <input type="hidden" name="action" value="static_bridge_refresh">
                                    <input type="hidden" name="scope" value="all">
                                    <?php wp_nonce_field('static_bridge_refresh'); ?>
                                    <p><strong><?php esc_html_e('Hai cambiato codice o stili fuori dall’editor?', 'static-bridge'); ?></strong>
                                        <?php esc_html_e('Uno snippet (FluentSnippets, WPCode, Code Snippets), il tema o un plugin che cambia tutte le pagine non avvisa Static Bridge. Questo pulsante rigenera ogni pagina già statica in coda, senza rifare la scansione del sito.', 'static-bridge'); ?></p>
                                    <button type="submit" class="button"><span class="dashicons dashicons-update" aria-hidden="true"></span> <?php esc_html_e('Aggiorna tutte le pagine statiche', 'static-bridge'); ?></button>
                                </form>
                            <?php endif; ?>

                            <section class="sb-incremental-status <?php echo !empty($settings['incremental_enabled']) ? 'is-enabled' : 'is-disabled'; ?>">
                                <span class="dashicons dashicons-update" aria-hidden="true"></span>
                                <div><strong><?php esc_html_e('Aggiornamenti incrementali', 'static-bridge'); ?></strong>
                                    <?php if (empty($release)) : ?>
                                        <p><?php esc_html_e('Dopo la prima pubblicazione, le nuove pagine e quelle modificate verranno aggiornate; i blocchi e template condivisi Gutenberg accoderanno tutti i percorsi statici esistenti.', 'static-bridge'); ?></p>
                                    <?php elseif (empty($settings['incremental_enabled'])) : ?>
                                        <p><?php esc_html_e('Disattivati nelle Impostazioni: per pubblicare le modifiche servirà una generazione completa.', 'static-bridge'); ?></p>
                                    <?php elseif ($incremental_queue_count > 0) : ?>
                                        <p><?php echo esc_html(sprintf(/* translators: %s: number of queued pages */ _n('%s pagina in coda; la versione statica esistente resta online durante l’aggiornamento.', '%s pagine in coda; le versioni statiche esistenti restano online durante gli aggiornamenti.', $incremental_queue_count, 'static-bridge'), number_format_i18n($incremental_queue_count))); ?></p>
                                        <?php $incremental_wait_remaining = $this->incremental_wait_remaining(); ?>
                                        <?php if ($incremental_wait_remaining > 0) : ?>
                                            <p id="sb-incremental-wait-status"><?php echo esc_html(sprintf(
                                                /* translators: %s: time when the waiting updates start */
                                                __('In attesa dopo l’ultima modifica: gli aggiornamenti automatici partono alle %s, se nel frattempo nessuno salva. Il push manuale non aspetta.', 'static-bridge'),
                                                wp_date((string) get_option('time_format', 'H:i'), time() + $incremental_wait_remaining)
                                            )); ?></p>
                                        <?php endif; ?>
                                    <?php else : ?>
                                        <p><?php esc_html_e('Attivi: articoli e pagine aggiornano solo le URL interessate; i componenti globali supportati aggiornano tutti i percorsi già statici, senza una nuova scansione completa.', 'static-bridge'); ?></p>
                                    <?php endif; ?>
                                </div>
                                <?php if ($full_access) : ?><a href="<?php echo esc_url($this->tab_url('settings')); ?>"><?php esc_html_e('Configura', 'static-bridge'); ?></a><?php endif; ?>
                            </section>
                        </section>

                        <?php $rate_limited = get_option(self::RATE_LIMITED_ROUTES_OPTION, array()); ?>
                        <?php if ($release && is_array($rate_limited) && !empty($rate_limited['urls']) && is_array($rate_limited['urls'])) : ?>
                            <section class="sb-card sb-rate-limited-card" id="sb-rate-limited-card">
                                <h2><?php echo esc_html(sprintf(/* translators: %s: number of pages */ _n('%s pagina non aggiornata per errori 429', '%s pagine non aggiornate per errori 429', count($rate_limited['urls']), 'static-bridge'), number_format_i18n(count($rate_limited['urls'])))); ?></h2>
