                            <?php else : ?>
                                <ul class="sb-path-list">
                                    <?php foreach ($editor_excluded_rows as $editor_excluded_row) : ?>
                                        <li><?php if ('' !== $editor_excluded_row['edit_url']) : ?><a href="<?php echo esc_url($editor_excluded_row['edit_url']); ?>"><?php echo esc_html('' !== $editor_excluded_row['title'] ? $editor_excluded_row['title'] : sprintf(/* translators: %d: content ID */ __('Contenuto %d', 'static-bridge'), $editor_excluded_row['id'])); ?></a><?php else : ?><?php echo esc_html('' !== $editor_excluded_row['title'] ? $editor_excluded_row['title'] : sprintf(/* translators: %d: content ID */ __('Contenuto %d', 'static-bridge'), $editor_excluded_row['id'])); ?><?php endif; ?>
