                                <?php if (!empty($diagnostic['status'])) : ?><span class="sb-status-pill <?php echo 'passed' === $diagnostic['status'] ? 'is-published' : ('running' === $diagnostic['status'] ? 'is-running' : ('failed' === $diagnostic['status'] ? 'is-failed' : 'is-warning')); ?>"><span></span><?php echo esc_html($this->diagnostic_status_label($diagnostic['status'])); ?></span><?php endif; ?>
