                                <p class="description"><?php esc_html_e('I riepiloghi delle verifiche concluse appariranno qui.', 'static-bridge'); ?></p>
                            <?php else : ?>
                                <div class="sb-diagnostic-history-list">
                                    <?php foreach (array_slice($diagnostic_history, 0, 8) as $entry) : ?>
                                        <div class="sb-diagnostic-history-entry"><span class="sb-diagnostic-dot is-<?php echo esc_attr(isset($entry['status']) ? $entry['status'] : 'warning'); ?>"></span><div><strong><?php echo esc_html(isset($entry['summary']['label']) ? $entry['summary']['label'] : $this->diagnostic_status_label(isset($entry['status']) ? $entry['status'] : 'warning')); ?></strong><small><?php echo esc_html(isset($entry['time']) ? $entry['time'] : ''); ?></small></div><span><?php $failed_count = isset($entry['summary']['failed']) ? (int) $entry['summary']['failed'] : 0; echo esc_html(sprintf(/* translators: %s: number of failed checks */ _n('%s errore', '%s errori', $failed_count, 'static-bridge'), number_format_i18n($failed_count))); ?></span></div>
