    public function save_settings()
    {
        if (!current_user_can('manage_options')) {
            wp_die(esc_html__('Non hai i permessi necessari.', 'static-bridge'));
        }
        check_admin_referer('static_bridge_save_settings');

        $raw_paths = isset($_POST['excluded_paths']) ? sanitize_textarea_field(wp_unslash($_POST['excluded_paths'])) : '';
        $paths = array();
        foreach (preg_split('/\r\n|\r|\n/', $raw_paths) as $path) {
            $path = trim($path);
            if ('' === $path) {
                continue;
            }
            $path = '/' . trim(wp_parse_url($path, PHP_URL_PATH), '/') . '/';
            if ('//' !== $path && '/' !== $path && !in_array($path, $paths, true)) {
                $paths[] = $path;
            }
        }

        $settings = array(
            'strict_mode' => isset($_POST['strict_mode']) ? 1 : 0,
            'woocommerce_enabled' => $this->woocommerce_is_active() && isset($_POST['woocommerce_enabled']) ? 1 : 0,
            'woocommerce_decided' => $this->woocommerce_is_active() ? 1 : 0,
            'incremental_enabled' => isset($_POST['incremental_enabled']) ? 1 : 0,
            'incremental_wait' => $this->sanitize_incremental_wait(isset($_POST['incremental_wait']) && is_string($_POST['incremental_wait']) ? sanitize_text_field(wp_unslash($_POST['incremental_wait'])) : 0),
            'failure_email' => isset($_POST['failure_email']) ? 1 : 0,
            'relative_dates' => isset($_POST['relative_dates']) ? 1 : 0,
            'markdown_pages' => isset($_POST['markdown_pages']) ? 1 : 0,
            'regenerate_after_updates' => isset($_POST['regenerate_after_updates']) ? 1 : 0,
            'skip_identical_pages' => isset($_POST['skip_identical_pages']) ? 1 : 0,
            'export_load_brake' => isset($_POST['export_load_brake']) ? 1 : 0,
            'export_archives' => isset($_POST['export_archives']) ? 1 : 0,
            'selective_shared_updates' => isset($_POST['selective_shared_updates']) ? 1 : 0,
            'shared_header_fragments' => isset($_POST['shared_header_fragments']) ? 1 : 0,
            'retention_enabled' => isset($_POST['retention_enabled']) ? 1 : 0,
            'retention_keep' => $this->sanitize_retention_keep(isset($_POST['retention_keep']) ? sanitize_text_field(wp_unslash($_POST['retention_keep'])) : self::RETENTION_DEFAULT_KEEP),
            'excluded_paths' => $paths,
            'cloudflare_purge' => isset($_POST['cloudflare_purge']) ? 1 : 0,
            'precompressed_pages' => isset($_POST['precompressed_pages']) ? 1 : 0,
            'ignore_tracking_params' => isset($_POST['ignore_tracking_params']) ? 1 : 0,
        );
        $previous_settings = $this->settings();
        // «Importa i redirect di…» (2.5.0): a box is shown only for a plugin that is running; the choice for one that
        // is off now is kept for when it comes back, as with WooCommerce.
        $posted_imports = $this->sanitize_redirect_import_sources(isset($_POST['import_redirects']) && is_array($_POST['import_redirects']) ? array_map(function ($source) {
            return is_string($source) ? sanitize_key($source) : '';
        }, wp_unslash($_POST['import_redirects'])) : array());
        $settings['import_redirects'] = array_values(array_filter(array_keys(self::REDIRECT_IMPORT_SOURCES), function ($source) use ($posted_imports, $previous_settings) {
            return in_array($source, $this->redirect_import_source_active($source) ? $posted_imports : $previous_settings['import_redirects'], true);
        }));
        // «Cookie che mandano a WP» (2.5.0): one name per line; the names enter the server rules, so an invalid line
        // is left out and said in Attività, never written.
        $raw_cookies = isset($_POST['dynamic_cookies']) && is_string($_POST['dynamic_cookies']) ? sanitize_textarea_field(wp_unslash($_POST['dynamic_cookies'])) : '';
        $cookies = $this->sanitize_dynamic_cookie_names(preg_split('/\r\n|\r|\n/', $raw_cookies));
        $settings['dynamic_cookies'] = $cookies['names'];
        if (!empty($cookies['invalid']) || $cookies['dropped'] > 0) {
            $this->log_activity(
                __('Alcuni cookie che mandano a WP non sono stati salvati.', 'static-bridge'),
                trim((empty($cookies['invalid']) ? '' : sprintf(/* translators: %s: list of cookie names */ __('Nomi non validi: %s. Usa solo lettere, cifre, «_», «-» e «.», al massimo 64, e «*» in fondo per un prefisso di almeno 3 caratteri.', 'static-bridge'), implode(', ', array_map(function ($name) {
                    return '«' . substr($name, 0, 80) . '»';
                }, array_slice($cookies['invalid'], 0, 10)))))
                    . ($cookies['dropped'] > 0 ? ' ' . sprintf(/* translators: %s: maximum number of cookies */ __('Si possono indicare al massimo %s cookie.', 'static-bridge'), number_format_i18n(self::MAX_DYNAMIC_COOKIES)) : '')),
                true
            );
        }
        // «Pagine da aggiornare a ogni pubblicazione» and «… ogni notte» (2.5.0): one path per line; a line that is
        // not a route of this site is left out and said in Attività, never written.
        $refresh_refused = array();
        $refresh_dropped = 0;
        foreach (array('publish_paths', 'nightly_paths') as $refresh_field) {
            $raw_refresh = isset($_POST[$refresh_field]) && is_string($_POST[$refresh_field]) ? sanitize_textarea_field(wp_unslash($_POST[$refresh_field])) : '';
            $refresh = $this->sanitize_refresh_paths(preg_split('/\r\n|\r|\n/', $raw_refresh));
            $settings[$refresh_field] = $refresh['paths'];
            $refresh_refused = array_merge($refresh_refused, $refresh['invalid']);
            $refresh_dropped += $refresh['dropped'];
        }
        if (!empty($refresh_refused) || $refresh_dropped > 0) {
            $this->log_activity(
                __('Alcune pagine da aggiornare non sono state salvate.', 'static-bridge'),
                trim((empty($refresh_refused) ? '' : sprintf(/* translators: %s: list of refused lines */ __('Righe non valide: %s. Scrivi un percorso del sito, come /eventi/, o il suo indirizzo completo, senza «?» e senza «#»; i percorsi che restano a WP non si aggiornano.', 'static-bridge'), implode(', ', array_map(function ($line) {
                    return '«' . substr($line, 0, 80) . '»';
                }, array_slice($refresh_refused, 0, 10)))))
                    . ($refresh_dropped > 0 ? ' ' . sprintf(/* translators: %s: maximum number of paths */ __('Si possono indicare al massimo %s percorsi per elenco.', 'static-bridge'), number_format_i18n(self::MAX_REFRESH_PATHS)) : '')),
                true
            );
        }
        // «Export completo pianificato» (2.5.0): a closed list, HH:MM and a day 0-6. A value outside them (only a
        // forged request sends one) keeps the previous choice; a field missing from the form keeps it silently.
        $schedule_invalid = false;
        foreach (array(
            'scheduled_export' => 'sanitize_scheduled_export_frequency',
            'scheduled_export_time' => 'sanitize_scheduled_export_time',
            'scheduled_export_day' => 'sanitize_scheduled_export_day',
        ) as $schedule_field => $schedule_sanitizer) {
            $raw = isset($_POST[$schedule_field]) && is_string($_POST[$schedule_field]) ? trim(wp_unslash($_POST[$schedule_field])) : null;
            $value = null === $raw ? null : $this->{$schedule_sanitizer}($raw);
            if (null === $value) {
                $schedule_invalid = $schedule_invalid || null !== $raw || isset($_POST[$schedule_field]);
                $settings[$schedule_field] = $previous_settings[$schedule_field];
            } else {
                $settings[$schedule_field] = $value;
            }
        }
        if (!$this->woocommerce_is_active()) {
            // The switch is disabled while WooCommerce is off: keep the choice for when it comes back.
            $stored_settings = get_option(self::SETTINGS_OPTION, array());
            foreach (array('woocommerce_enabled', 'woocommerce_decided') as $woocommerce_key) {
                $settings[$woocommerce_key] = is_array($stored_settings) && !empty($stored_settings[$woocommerce_key]) ? 1 : 0;
            }
        }
        // Cloudflare/CDN values are written into server rules and outbound requests:
        // an invalid value never replaces the previous valid one.
        $cdn_fields = array(
            'render_origin' => array('sanitize_render_origin', __('Indirizzo di origine per il rendering non valido; è stato mantenuto il valore precedente.', 'static-bridge')),
            'static_cache_control' => array('sanitize_static_cache_control', __('Cache-Control delle pagine statiche non valido; è stato mantenuto il valore precedente.', 'static-bridge')),
        );
        // The «Cloudflare consigliato» button saves the same form with the recommended Cache-Control and purge on.
        $cloudflare_preset = isset($_POST['cloudflare_preset']);
        foreach ($cdn_fields as $field => $definition) {
            $raw = isset($_POST[$field]) && is_string($_POST[$field]) ? sanitize_text_field(wp_unslash($_POST[$field])) : '';
            if ($cloudflare_preset && 'static_cache_control' === $field) {
                $raw = self::CLOUDFLARE_RECOMMENDED_CACHE_CONTROL;
            }
            $value = $this->{$definition[0]}($raw);
            if (is_wp_error($value)) {
                $settings[$field] = $previous_settings[$field];
                $this->log_activity($definition[1], $value->get_error_message(), true);
            } else {
                $settings[$field] = $value;
            }
        }
        if ($cloudflare_preset) {
            $settings['cloudflare_purge'] = 1;
            $credentials_valid = !empty($this->cloudflare_credentials()['valid']);
            $this->log_activity(
                __('Impostazioni consigliate per Cloudflare applicate.', 'static-bridge'),
                sprintf(/* translators: %s: Cache-Control value */ __('Cache-Control delle pagine statiche: %s; svuotamento automatico acceso. Incolla la regola di cache consigliata in Cloudflare e, su Nginx, copia di nuovo il blocco.', 'static-bridge'), self::CLOUDFLARE_RECOMMENDED_CACHE_CONTROL)
                    . ($credentials_valid ? '' : ' ' . __('Mancano le credenziali in wp-config.php: lo svuotamento non parte finché non le definisci.', 'static-bridge')),
                !$credentials_valid
            );
        }
        if (!empty($settings['selective_shared_updates']) && !(new Static_Bridge_Dependency_Index())->install()) {
            $settings['selective_shared_updates'] = 0;
            $this->log_activity(
                __('Indice V2 non attivato.', 'static-bridge'),
                __('Le tabelle InnoDB dell’indice persistente non sono disponibili; gli aggiornamenti condivisi restano nella modalità prudenziale.', 'static-bridge'),
                true
            );
        }
        if (!empty($settings['shared_header_fragments'])) {
            $release = $this->current_release();
            $safe = $this->server_uses_nginx() && !empty($settings['incremental_enabled'])
                && !empty($settings['selective_shared_updates']) && $release
                && (new Static_Bridge_Header_Fragment_Index())->install()
                && $this->release_has_safe_ssi_source($release);
            if (!$safe) {
                $settings['shared_header_fragments'] = 0;
                $this->log_activity(
                    __('SSI header non attivato.', 'static-bridge'),
                    __('Serve Nginx, l’indice V2 e l’aggiornamento incrementale; inoltre la release attuale deve esistere e non contenere direttive SSI. Nessuna pagina è stata modificata.', 'static-bridge'),
                    true
                );
            } else {
                update_option('static_bridge_ssi_safe_release', basename($release), false);
                update_option('static_bridge_ssi_guard_enabled', 1, false);
                $this->log_activity(
                    __('Release attuale verificata per la preparazione SSI.', 'static-bridge'),
                    __('Nessuna direttiva SSI preesistente trovata negli HTML statici. Puoi installare e ricaricare il blocco Nginx aggiornato prima di avviare il prossimo export completo.', 'static-bridge')
                );
            }
        }
        update_option(self::SETTINGS_OPTION, $settings, false);
        $this->log_cdn_settings_changes($previous_settings, $this->settings());
        $this->log_guard_settings_changes($previous_settings, $this->settings());
        // «Importa i redirect di…» (2.5.0): what entered the rules just written, or why nothing did.
        // A choice that brings no redirect (Strict off, plugin not active…) says so and, if none was there before
        // either, asks for no copy of the block.
        if (!empty($previous_settings['import_redirects']) || !empty($settings['import_redirects'])) {
            $imported = array() !== $this->imported_redirects($this->plugin_redirects(false))['redirects'];
            $title = empty($settings['import_redirects']) ? __('Redirect importati tolti dalle regole del server.', 'static-bridge')
                : ($imported ? __('Redirect importati nelle regole del server.', 'static-bridge') : __('Nessun redirect importato nelle regole del server.', 'static-bridge'));
            $recopy = $this->server_uses_nginx() && ($imported || !empty($previous_settings['import_redirects']));
            $this->log_activity($title, implode(' ', $this->redirect_import_summary()) . ($recopy ? ' ' . __('Copia il blocco Nginx aggiornato e ricarica Nginx.', 'static-bridge') : ''));
        }
        $this->sync_scheduled_export($previous_settings, $schedule_invalid);
        $this->schedule_nightly_paths();
        // «Rigenera dopo gli aggiornamenti» turned off: its waiting export goes. Turned on, it waits for the next update:
        // the changes already noted keep their notice and its button.
        if (empty($settings['regenerate_after_updates'])) {
            wp_clear_scheduled_hook(self::AFTER_UPDATE_HOOK);
        }
        // «Non riscrivere le pagine identiche» turned off: the writes are no longer tracked, so its state goes and,
        // turned on again, it starts from the next full export.
        if (empty($settings['skip_identical_pages'])) {
            delete_option(self::UNSETTLED_ROUTES_OPTION);
        }
        if ($previous_settings['retention_enabled'] !== $settings['retention_enabled']
            || $previous_settings['retention_keep'] !== $settings['retention_keep']) {
            if (!empty($settings['retention_enabled'])) {
                $this->log_activity(
                    __('Conservazione delle release attivata.', 'static-bridge'),
                    sprintf(/* translators: %s: number of previous releases to keep */ __('Dopo ogni pubblicazione riuscita verranno conservate la release attiva e le %s release pronte più recenti; gli staging falliti o annullati vengono eliminati dopo un’ora. Le release protette non vengono mai toccate.', 'static-bridge'), number_format_i18n($settings['retention_keep']))
                );
            } else {
                wp_clear_scheduled_hook(self::RETENTION_HOOK);
                $this->log_activity(
                    __('Conservazione delle release disattivata.', 'static-bridge'),
                    __('Static Bridge non elimina release precedenti né staging.', 'static-bridge')
                );
            }
        }
        if (!$this->sync_strict_marker(!empty($settings['strict_mode']))) {
            $this->log_activity(__('Impostazioni salvate, ma il marcatore strict non è stato sincronizzato.', 'static-bridge'), __('Controlla permessi e tipo del percorso wp-content/static-bridge/.strict.', 'static-bridge'), true);
        }
        $rules_written = $this->update_routing_rules();
        if (!empty($settings['incremental_enabled']) && !empty($this->incremental_queue())) {
            $this->schedule_incremental_worker(0, true);
        }
        if (!$rules_written) {
            $this->log_activity(__('Impostazioni salvate, ma .htaccess non aggiornato.', 'static-bridge'), __('Il server non consente la scrittura del file .htaccess.', 'static-bridge'), true);
        } else {
            $this->log_activity(__('Impostazioni Static Bridge aggiornate.', 'static-bridge'));
        }
        // Routing or response headers changed: copies cached at the edge may no longer
        // match what the origin serves for the same URL.
        $current_settings = $this->settings();
        $edge_relevant = array('strict_mode', 'excluded_paths', 'woocommerce_enabled', 'static_cache_control', 'cloudflare_purge');
        foreach ($edge_relevant as $key) {
            if ($previous_settings[$key] !== $current_settings[$key]) {
                $this->queue_cloudflare_purge('everything', __('impostazioni di routing o cache modificate', 'static-bridge'));
                break;
            }
        }
        wp_safe_redirect(add_query_arg(array('page' => self::ADMIN_SLUG, 'tab' => 'settings', 'settings-updated' => '1'), admin_url('admin.php')));
        exit;
    }

    public function save_form_modes()
    {
        if (!current_user_can('manage_options')) {
            wp_die(esc_html__('Non hai i permessi necessari.', 'static-bridge'));
        }
        check_admin_referer('static_bridge_save_form_modes');

        $detected = $this->discover_form_pages();
        $allowed = array();
        foreach ($detected as $form_page) {
            $allowed[$form_page['path']] = $form_page;
        }

        $paths = isset($_POST['form_paths']) && is_array($_POST['form_paths']) ? array_values(wp_unslash($_POST['form_paths'])) : array();
        $modes = isset($_POST['form_modes']) && is_array($_POST['form_modes']) ? array_values(wp_unslash($_POST['form_modes'])) : array();
        $saved_modes = $this->merge_form_modes($detected, $paths, $modes, $this->form_modes());

        update_option(self::FORM_MODES_OPTION, $saved_modes, false);
        $rules_written = $this->update_routing_rules();
        if (!$rules_written) {
            $this->log_activity(__('Modalità dei moduli salvate, ma .htaccess non aggiornato.', 'static-bridge'), __('Il server non consente la scrittura del file .htaccess.', 'static-bridge'), true);
        } else {
            $this->log_activity(__('Modalità dei moduli Fluent Forms aggiornate.', 'static-bridge'));
        }
        $redirect_args = array('page' => self::ADMIN_SLUG, 'tab' => 'forms');
        $redirect_page = isset($_POST['forms-page']) && !is_array($_POST['forms-page']) ? absint(wp_unslash($_POST['forms-page'])) : 1;
        $redirect_pagination = $this->paginate_form_pages($detected, $redirect_page);
        $redirect_args['forms-page'] = $redirect_pagination['current_page'];
        $redirect_args[$rules_written ? 'forms-updated' : 'forms-rules-error'] = '1';
        wp_safe_redirect(add_query_arg($redirect_args, admin_url('admin.php')));
        exit;
    }

    /**
     * Keep All-in-One WP Migration from serializing current/ as a second copy
     * of a release. The immutable releases and the database release id are
     * migrated; after import we recreate this local symlink atomically.
     */
    public function exclude_ai1wm_current_pointer($exclude_filters)
    {
        if (!is_array($exclude_filters)) {
            return $exclude_filters;
        }
        $exclude_filters[] = 'static-bridge/current';
        $exclude_filters[] = trailingslashit(WP_CONTENT_DIR) . 'static-bridge/current';
        // Apache served copies are derived from the release and archives do not keep hard links.
        $exclude_filters[] = 'static-bridge/served';
        $exclude_filters[] = trailingslashit(WP_CONTENT_DIR) . 'static-bridge/served';
        return array_values(array_unique($exclude_filters));
    }

    /**
     * AIO restores files and the source database before firing this action.
     * Keep WordPress serving the frontend until the portable release and its
     * pointer have both been validated on the destination.
     */
    public function after_ai1wm_import($params = array())
    {
        if (!$this->sync_routing_enabled_marker(false) || !$this->sync_strict_marker(false)) {
            $this->log_activity(
                __('Importazione All-in-One completata, ma il routing statico non è stato disattivato in sicurezza.', 'static-bridge'),
                __('Controlla manualmente i marcatori wp-content/static-bridge/.enabled e .strict; WordPress deve restare il fallback finché la release non è verificata.', 'static-bridge'),
                true
            );
            return false;
        }

        $last_release = get_option('static_bridge_last_release', array());
        $release_id = is_array($last_release) && isset($last_release['id']) && is_string($last_release['id'])
            ? $last_release['id']
            : '';
        if ($this->imported_release_has_other_origin($release_id)) {
            // Canonical, hreflang, og:/twitter: and JSON-LD of this release name the domain it was exported on:
            // served here they would send search engines and link previews there. WordPress serves the site
            // until a full export on this domain.
            return false;
        }
        if (!$this->activate_imported_release($release_id)) {
            $this->log_activity(
                __('Importazione All-in-One completata; frontend lasciato dinamico.', 'static-bridge'),
                __('La release statica non è presente, non è completa o non dichiara URL interni trasferibili. Non è stata avviata una ristaticizzazione automatica; genera una release portabile in locale e ripeti il trasferimento.', 'static-bridge'),
                true
            );
            return false;
        }

        $this->remap_imported_incremental_queue();
        $settings = $this->settings();
        $strict_ok = $this->sync_strict_marker(!empty($settings['strict_mode']));
        $routing_ok = $this->sync_routing_enabled_marker(true);
        $rules_ok = $this->update_routing_rules();
        if (!$strict_ok || !$routing_ok || !$rules_ok) {
            // Do not leave an imported .enabled/.strict marker behind when the
            // destination cannot verify its routing state; WordPress is the
            // safe fallback until an administrator repairs the server rules.
            $this->sync_routing_enabled_marker(false);
            $this->sync_strict_marker(false);
        }
        $this->log_activity(
            __('Release statica ripristinata dopo l’importazione All-in-One.', 'static-bridge'),
            __('La release esistente è stata riattivata senza riesportare il sito. Le nuove pubblicazioni e modifiche continuano a usare la coda incrementale.', 'static-bridge'),
            !$strict_ok || !$routing_ok || !$rules_ok
        );
        if (!empty($settings['incremental_enabled']) && !empty($this->incremental_queue())) {
            $this->schedule_incremental_worker(0, true);
        }
        return $strict_ok && $routing_ok && $rules_ok;
    }

    /**
     * Recover an imported release on the next privileged admin request if the
     * migration tool restored WordPress before loading this plugin's import hook.
     */
    public function maybe_recover_imported_release()
    {
        if (!is_admin() || !current_user_can('manage_options')) {
            return false;
        }

        $root = $this->static_root();
        if (is_link($root) || (file_exists($root) && !is_dir($root))) {
            return false;
        }

        $enabled_marker = trailingslashit($root) . '.enabled';
        $current = trailingslashit($root) . 'current';
        if (is_link($enabled_marker) || !is_file($enabled_marker)
            || is_link($current) || file_exists($current)) {
            return false;
        }

        $last_release = get_option('static_bridge_last_release', array());
        $release_id = is_array($last_release) && isset($last_release['id']) && is_string($last_release['id'])
            ? $last_release['id']
            : '';
        if ('' === $release_id) {
            // A missing release record is normal on a fresh install. If a stale
            // marker exists, clear it quietly and keep WordPress as the frontend.
            $routing_disabled = $this->sync_routing_enabled_marker(false);
            $strict_disabled = $this->sync_strict_marker(false);
            if (!$routing_disabled || !$strict_disabled) {
                $this->log_activity(
                    __('Nessuna release statica disponibile; il frontend resta su WordPress.', 'static-bridge'),
                    __('Static Bridge ha rilevato un marcatore senza una release pubblicata e ha tentato di disattivare il routing statico.', 'static-bridge'),
                    true
                );
            }
            return false;
        }
        if ('' === $this->portable_release_directory($release_id)) {
            $routing_disabled = $this->sync_routing_enabled_marker(false);
            $strict_disabled = $this->sync_strict_marker(false);
            $this->log_activity(
                __('Release importata non valida; routing statico disattivato.', 'static-bridge'),
                __('Il puntatore corrente non è presente e la release indicata non ha superato la validazione. WordPress resta il fallback; controlla la release e crea una nuova pubblicazione portabile.', 'static-bridge'),
                !$routing_disabled || !$strict_disabled
            );
            return false;
        }

        return $this->after_ai1wm_import(array('admin_recovery' => true));
    }

    public function remember_incremental_old_archives($post_id, $data)
    {
        $post = get_post($post_id);
        if (!$post || 'publish' !== $post->post_status || !$this->is_public_incremental_post($post)
            || $this->is_shared_content_post_type($post->post_type)) {
            return;
        }
        $this->incremental_old_archive_urls[(int) $post_id] = $this->archive_urls_for_post($post);
        // Its neighbours before the change: a new date or a withdrawal changes their «previous» and «next» links.
        $this->old_adjacent_post_urls[(int) $post_id] = $this->adjacent_post_urls($post);
    }

    public function maybe_queue_incremental_post($post_id, $post, $update, $post_before)
    {
        if (empty($this->settings()['incremental_enabled']) || !$this->current_release() || !($post instanceof WP_Post)) {
            return;
        }
        if (wp_is_post_revision($post_id) || wp_is_post_autosave($post_id) || (defined('DOING_AUTOSAVE') && DOING_AUTOSAVE)) {
            return;
        }
        if (!$this->is_public_incremental_post($post) || $this->is_shared_content_post_type($post->post_type)) {
            return;
        }

        $was_published = $post_before instanceof WP_Post && 'publish' === $post_before->post_status;
        $is_published = 'publish' === $post->post_status;
        $old_url = $was_published ? get_permalink($post_before) : '';
        $new_url = $is_published ? get_permalink($post) : '';
        $old_path = $this->normalize_route_path($old_url);
        $new_path = $this->normalize_route_path($new_url);
        $archive_urls = isset($this->incremental_old_archive_urls[(int) $post_id])
            ? $this->incremental_old_archive_urls[(int) $post_id]
            : array();
        if ($was_published && empty($archive_urls)) {
            $archive_urls = $this->archive_urls_for_post($post_before);
        }

        if ($was_published && (!$is_published || ($old_path && $new_path && $old_path !== $new_path))) {
            $this->enqueue_incremental_url($old_url, $post_id, 'delete', array(), 'single');
        }
        if ($is_published) {
            $builders = $this->page_builders($post);
            if ('page' === $post->post_type || !empty($builders)) {
                delete_transient('static_bridge_incremental_query_pages');
            }
            $this->enqueue_incremental_url($new_url, $post_id, 'refresh', $builders, 'single');
            $archive_urls = array_merge($archive_urls, $this->archive_urls_for_post($post), $this->discover_query_page_urls());
        } elseif ($was_published) {
            // Unpublished, trashed or made private: the pages that list it must drop it too.
            $archive_urls = array_merge($archive_urls, $this->discover_query_page_urls());
        }
        if ($was_published || $is_published) {
            // 2.5.0: the previous and next posts, before and after the change (their links name this one), and
            // «Pagine da aggiornare a ogni pubblicazione». Never the post's own routes, which keep their single entry.
            $old_adjacent = isset($this->old_adjacent_post_urls[(int) $post_id])
                ? $this->old_adjacent_post_urls[(int) $post_id]
                : ($was_published ? $this->adjacent_post_urls($post_before) : array());
            $own_paths = array_filter(array($old_path, $new_path));
            $extra = array();
            foreach (array_merge($old_adjacent, $this->adjacent_post_urls($post), $this->publish_refresh_urls()) as $extra_url) {
                if (!in_array($this->normalize_route_path($extra_url), $own_paths, true)) {
                    $extra[] = $extra_url;
                }
            }
            $this->enqueue_incremental_urls(array_unique(array_merge($extra, $archive_urls)), $post_id, 'refresh', array(), 'dependent');
        }
        unset($this->incremental_old_archive_urls[(int) $post_id], $this->old_adjacent_post_urls[(int) $post_id]);
    }

    /**
     * The previous and next published posts of the same type, by date, overall and in the post's categories, as
     * the «previous» and «next» links of a theme name them (get_adjacent_post(), also with in_same_term). Read as an
     * anonymous visitor sees them: published, without a password, whoever is logged in. Only those with a copy in
     * the release are returned, as URLs: a neighbour without a copy has nothing stale. Hierarchical types (pages)
     * have no such links. At most four routes.
     */
    private function adjacent_post_urls($post)
    {
        if (!$post instanceof WP_Post || empty($post->ID) || empty($post->post_date) || 'page' === $post->post_type
            || !$this->is_public_incremental_post($post) || $this->is_shared_content_post_type($post->post_type)
            || empty($this->settings()['incremental_enabled']) || !$this->current_release()) {
            return array();
        }
        $type_object = get_post_type_object($post->post_type);
        if ($type_object && !empty($type_object->hierarchical)) {
            return array();
        }
        $term_ids = array();
        if (in_array('category', (array) get_object_taxonomies($post->post_type, 'names'), true)) {
            $terms = get_the_terms($post->ID, 'category');
            foreach (is_array($terms) ? $terms : array() as $term) {
                if (is_object($term) && !empty($term->term_id)) {
                    $term_ids[] = (int) $term->term_id;
                }
            }
        }
        $urls = array();
        foreach (array('before' => 'DESC', 'after' => 'ASC') as $side => $order) {
            $query = array(
                'post_type' => $post->post_type,
                'post_status' => 'publish',
                'has_password' => false,
                'posts_per_page' => 1,
                'orderby' => 'date',
                'order' => $order,
                'date_query' => array(array($side => (string) $post->post_date, 'inclusive' => false)),
                'post__not_in' => array((int) $post->ID),
                'fields' => 'ids',
                'no_found_rows' => true,
                'ignore_sticky_posts' => true,
                'suppress_filters' => true,
            );
            $queries = array($query);
            if (!empty($term_ids)) {
                $queries[] = $query + array('tax_query' => array(array('taxonomy' => 'category', 'field' => 'term_id', 'terms' => array_slice($term_ids, 0, 20), 'include_children' => false)));
            }
            foreach ($queries as $args) {
                foreach ((array) get_posts($args) as $neighbour_id) {
                    $neighbour = get_post((int) $neighbour_id);
                    if (!$neighbour || 'publish' !== $neighbour->post_status || !empty($neighbour->post_password)) {
                        continue;
                    }
                    $url = get_permalink($neighbour);
                    $path = $this->normalize_route_path($url);
                    if ('' !== $path && $this->static_file_exists_for_path($path)) {
                        $urls[$path] = $url;
                    }
                }
            }
        }
        return array_values($urls);
    }

    /**
     * Comments (2.5.0). WP calls wp_update_comment_count on every approve, unapprove, spam, trash, untrash and
     * delete, also when the number of approved comments stays the same (a pending comment marked as spam or
     * deleted): only a change of that number refreshes the post. A new comment waiting for moderation never
     * reaches here, because WP counts again only for an approved one.
     */
    public function maybe_queue_comment_count_change($post_id, $new = 0, $old = 0)
    {
        if ((int) $new !== (int) $old) {
            $this->queue_commented_post($post_id);
        }
    }

    /** An approved comment edited in place: the number stays, the text changes. A pending or spam one never queues. */
    public function maybe_queue_edited_comment($comment_id, $data = array())
    {
        if (!function_exists('wp_get_comment_status') || 'approved' !== wp_get_comment_status($comment_id)) {
            return;
        }
        $comment = get_comment($comment_id);
        if (is_object($comment) && !empty($comment->comment_post_ID)) {
            $this->queue_commented_post((int) $comment->comment_post_ID);
        }
    }

    /**
     * Queues the page of a commented post that has a copy, with its comment pages (/comment-page-N/) the release
     * has. The render is anonymous (no cookie of the commenter, no moderation link), so the copy shows only the
     * approved comments. A post without a copy is left alone: a comment does not create pages.
     */
    private function queue_commented_post($post_id)
    {
        if (empty($this->settings()['incremental_enabled']) || !$this->current_release()) {
            return false;
        }
        $post = get_post((int) $post_id);
        if (!$post instanceof WP_Post || 'publish' !== $post->post_status || !empty($post->post_password)
            || !$this->is_public_incremental_post($post) || $this->is_shared_content_post_type($post->post_type)) {
            return false;
        }
        $url = get_permalink($post);
        $path = $this->normalize_route_path($url);
        if ('' === $path || !$this->static_file_exists_for_path($path)) {
            return false;
        }
        $queued = $this->enqueue_incremental_url($url, (int) $post->ID, 'refresh', $this->page_builders($post), 'single');
        $comment_pages = $this->release_comment_page_urls($path);
        if (!empty($comment_pages)) {
            $this->enqueue_incremental_urls($comment_pages, (int) $post->ID, 'refresh', array(), 'dependent');
        }
        return $queued;
    }

    /** The /comment-page-N/ routes under $path that the current release has a copy of, at most MAX_COMMENT_PAGE_ROUTES. */
    private function release_comment_page_urls($path)
    {
        $release = $this->current_release();
        $relative = '' !== $release ? $this->relative_html_path(home_url($path)) : '';
        if (!is_string($relative) || ('index.html' !== $relative && '/index.html' !== substr($relative, -11))) {
            return array();
        }
        $directory = trailingslashit($release) . substr($relative, 0, -strlen('index.html'));
        $urls = array();
        foreach ((array) glob($directory . 'comment-page-*', GLOB_ONLYDIR) as $candidate) {
            $name = basename((string) $candidate);
            if (!preg_match('/\Acomment-page-[1-9][0-9]{0,5}\z/', $name) || is_link($candidate) || !is_file($candidate . '/index.html')) {
                continue;
            }
            $urls[] = home_url(trailingslashit($path) . $name . '/');
            if (count($urls) >= self::MAX_COMMENT_PAGE_ROUTES) {
                break;
            }
        }
        return $urls;
    }

    public function maybe_queue_shared_content_post($post_id, $post, $update, $post_before)
    {
        if (!($post instanceof WP_Post) || !$this->is_shared_content_post_type($post->post_type)) {
            return;
        }
        $was_published = $post_before instanceof WP_Post && 'publish' === $post_before->post_status;
        if ('publish' !== $post->post_status && !$was_published) {
            return;
        }
        if ($this->queue_known_dependents($post)) {
            return;
        }
        $dependency_id = 'elementor_library' === $post->post_type ? (string) $post_id : null;
        $this->queue_shared_output_refresh(__('Un template o componente globale condiviso è stato aggiornato.', 'static-bridge'), $dependency_id);
    }

    public function maybe_queue_shared_content_meta($meta_id, $post_id, $meta_key, $meta_value)
    {
        $post = get_post($post_id);
        if (!is_object($post) || empty($post->post_type) || 'publish' !== (isset($post->post_status) ? $post->post_status : '')
            || !$this->is_shared_content_post_type($post->post_type)) {
            return;
        }
        if ('elementor_library' === $post->post_type && !in_array((string) $meta_key, array(
            '_elementor_data',
            '_elementor_page_settings',
            '_elementor_conditions',
            '_elementor_conditions_v2',
            '_elementor_template_type',
            '_elementor_edit_mode',
        ), true)) {
            // Ignore editor locks, generated CSS/cache metadata, and version
            // bookkeeping: they do not change the rendered shared document.
            return;
        }
        if (in_array((string) $meta_key, array('_edit_lock', '_edit_last'), true)) {
            // Editor bookkeeping: opening a shared post in the editor changes nothing on the site.
            return;
        }
        if ('elementor_library' !== $post->post_type && $this->queue_known_dependents($post)) {
            return;
        }
        $elementor_global_change = 'elementor_library' === $post->post_type
            && in_array((string) $meta_key, array('_elementor_conditions', '_elementor_conditions_v2'), true);
        $dependency_id = 'elementor_library' === $post->post_type && !$elementor_global_change
            ? (string) $post_id
            : null;
        $this->queue_shared_output_refresh(
            $elementor_global_change
                ? __('Le condizioni di visualizzazione Elementor sono cambiate.', 'static-bridge')
                : __('I metadati di un template o componente globale condiviso sono stati aggiornati.', 'static-bridge'),
            $dependency_id
        );
    }

    public function maybe_queue_elementor_document($document, $data = array())
    {
        if (!is_object($document) || !method_exists($document, 'get_id')) {
            return;
        }
        $document_id = method_exists($document, 'get_main_id') ? $document->get_main_id() : $document->get_id();
        if (!is_numeric($document_id) || (int) $document_id < 1) {
            return;
        }
        $post = get_post((int) $document_id);
        if (!$post || 'elementor_library' !== $post->post_type || !in_array($post->post_status, array('publish', 'private'), true)) {
            return;
        }
        $this->queue_shared_output_refresh(__('Un documento Elementor è stato salvato.', 'static-bridge'), (string) $document_id);
    }

    public function maybe_queue_deleted_shared_content_post($post_id, $post)
    {
        if (!($post instanceof WP_Post) || 'publish' !== $post->post_status || !$this->is_shared_content_post_type($post->post_type)) {
            return;
        }
        $dependency_id = 'elementor_library' === $post->post_type ? (string) $post_id : null;
        $this->queue_shared_output_refresh(__('Un template o componente globale condiviso è stato eliminato.', 'static-bridge'), $dependency_id);
    }

    private function is_shared_content_post_type($post_type)
    {
        $post_types = array('wp_block', 'wp_template', 'wp_template_part', 'wp_navigation', 'wp_global_styles');
        foreach (array('bricks_template', 'kadence_element', 'elementor_library') as $builder_post_type) {
            if (function_exists('post_type_exists') && post_type_exists($builder_post_type)) {
                $post_types[] = $builder_post_type;
            }
        }
        $post_types = apply_filters('static_bridge_shared_content_post_types', $post_types);
        if (!is_array($post_types)) {
            return false;
        }
        foreach ($post_types as $type) {
            if (is_string($type) && preg_match('/^[A-Za-z0-9_-]{1,20}$/', $type) && $type === (string) $post_type) {
                return true;
            }
        }
        return false;
    }

    public function maybe_queue_customizer_shared_output($customizer = null)
    {
        $this->queue_shared_output_refresh(__('Le impostazioni globali del tema sono state aggiornate dal Customizer.', 'static-bridge'));
    }

    public function maybe_queue_bricks_global_option($option, $old_value = null, $new_value = null)
    {
        $global_options = array(
            'bricks_global_classes',
            'bricks_global_variables',
            'bricks_theme_styles',
            'bricks_color_palette',
            'bricks_breakpoints',
            'bricks_components',
            'bricks_pseudo_classes',
        );
        if (!is_string($option) || !in_array($option, $global_options, true)) {
            return;
        }
        $this->queue_shared_output_refresh(__('I dati globali di Bricks sono stati aggiornati.', 'static-bridge'));
    }

    /**
     * Etch keeps the CSS of every page in options, not in the posts: selectors (etch_styles), global stylesheets,
     * loop presets (etch_loops, before them etch_queries), the legacy component list and its settings. Its REST
     * routes and its CLI write them with update_option(), so these hooks see every save. Components are wp_block
     * posts with etch_* meta: maybe_queue_shared_content_meta() already covers them.
     */
    public function maybe_queue_etch_global_option($option, $old_value = null, $new_value = null)
    {
        $global_options = array('etch_styles', 'etch_global_stylesheets', 'etch_loops', 'etch_queries', 'etch_components', 'etch_settings');
        if (!is_string($option) || !in_array($option, $global_options, true)) {
            return;
        }
        // updated_option is the only hook registered with three arguments.
        if ('etch_settings' === $option && 3 === func_num_args()
            && $this->without_etch_ai_settings($old_value) === $this->without_etch_ai_settings($new_value)) {
            // Only the AI assistant settings (and its API key) changed: nothing a visitor sees.
            return;
        }
        $this->queue_shared_output_refresh(__('Stili, loop o impostazioni globali di Etch sono stati aggiornati.', 'static-bridge'));
    }

    private function without_etch_ai_settings($settings)
    {
        if (!is_array($settings)) {
            return $settings;
        }
        foreach (array_keys($settings) as $key) {
            if (is_string($key) && preg_match('/\A(?:ai_|experimental_ai\z)/', $key)) {
                unset($settings[$key]);
            }
        }
        ksort($settings);
        return $settings;
    }

    /**
     * The Complianz options to watch: COMPLIANZ_OPTIONS plus those of extensions that print into the banner or the
     * legal pages (filter `static_bridge_complianz_options`, e.g. Consenso Bridge). Only option names are kept.
     */
    private function complianz_options()
    {
        $options = apply_filters('static_bridge_complianz_options', self::COMPLIANZ_OPTIONS);
        $options = is_array($options) ? array_filter($options, 'is_string') : array();
        return array_values(array_unique(array_merge(self::COMPLIANZ_OPTIONS, $options)));
    }

    public function maybe_note_complianz_option($option)
    {
        if (is_string($option) && in_array($option, $this->complianz_options(), true)) {
            $this->note_complianz_change();
        }
    }

    /**
     * Complianz keeps its banners in a table of its own and has no save hook; the CSS regeneration closes every
     * save, but it also runs while a page renders. So this only takes note: maybe_queue_complianz_refresh() decides
     * at the end of the request, when options, banners and blocked scripts are all written.
     */
    public function note_complianz_change()
    {
        if (!$this->complianz_change_noted) {
            $this->complianz_change_noted = true;
            add_action('shutdown', array($this, 'maybe_queue_complianz_refresh'));
        }
    }

    /**
     * Filter of the Complianz admin REST actions, $data is passed through. The cookie and service tables print only
     * in the cookie policy and change no option, so these saves always refresh.
     */
    public function note_complianz_admin_action($data, $action = '')
    {
        if ('update_banner_data' === $action) {
            $this->note_complianz_change();
        } elseif (in_array($action, array('add_cookie', 'update_cookie', 'delete_cookie', 'update_service', 'delete_service'), true)) {
            $this->complianz_tables_changed = true;
            $this->note_complianz_change();
        }
        return $data;
    }

    public function maybe_queue_complianz_refresh()
    {
        $fingerprint = $this->complianz_fingerprint();
        if (!$this->complianz_tables_changed && $fingerprint === get_option(self::COMPLIANZ_FINGERPRINT_OPTION)) {
            return;
        }
        update_option(self::COMPLIANZ_FINGERPRINT_OPTION, $fingerprint, false);
        $this->queue_shared_output_refresh(__('Le impostazioni o il banner di Complianz sono cambiati.', 'static-bridge'));
    }

    private function complianz_fingerprint()
    {
        global $wpdb;
        $state = array();
        foreach ($this->complianz_options() as $option) {
            $state[$option] = get_option($option);
        }
        $table = $wpdb->prefix . 'cmplz_cookiebanners';
        $suppressed = $wpdb->suppress_errors(); // The table is gone once Complianz is uninstalled.
        // phpcs:ignore WordPress.DB.DirectDatabaseQuery, WordPress.DB.PreparedSQL.InterpolatedNotPrepared -- A table name; read once, at the end of a Complianz save.
        $state['banners'] = $wpdb->get_results("SELECT ID, banner_version FROM `{$table}` ORDER BY ID", ARRAY_N);
        $wpdb->suppress_errors($suppressed);
        return sha1(serialize($state));
    }

    /**
     * The actions that take note of a menu or widget change (2.5.0): LAYOUT_REFRESH_HOOKS through the filter
     * static_bridge_shared_refresh_hooks, so a theme or a plugin can add its own, like the «Purge All Hooks» of
     * LiteSpeed Cache. Only hook names are kept, at most MAX_LAYOUT_REFRESH_HOOKS, never one of Static Bridge (the
     * worker fires them while it renders); a value that is not a list keeps the default. An empty list turns the
     * menu and widget refresh off, options included. Read once per request.
     */
    private function layout_refresh_hooks()
    {
        if (is_array($this->layout_refresh_hooks_cache)) {
            return $this->layout_refresh_hooks_cache;
        }
        $hooks = apply_filters('static_bridge_shared_refresh_hooks', self::LAYOUT_REFRESH_HOOKS);
        $valid = array();
        foreach (is_array($hooks) ? $hooks : self::LAYOUT_REFRESH_HOOKS as $hook) {
            if (is_string($hook) && preg_match('/\A[A-Za-z0-9_\/.:-]{1,100}\z/D', $hook) && 0 !== stripos($hook, 'static_bridge')
                && !in_array($hook, $valid, true)) {
                $valid[] = $hook;
            }
            if (count($valid) >= self::MAX_LAYOUT_REFRESH_HOOKS) {
                break;
            }
        }
        $this->layout_refresh_hooks_cache = $valid;
        return $valid;
    }

    /** On init, once themes and plugins are loaded: each listed action takes note of a change. */
    public function register_layout_refresh_hooks()
    {
        foreach ($this->layout_refresh_hooks() as $hook) {
            add_action($hook, array($this, 'note_layout_change'), 10, 1);
        }
    }

    /**
     * added_option, updated_option and deleted_option: the widgets (sidebars_widgets and every widget_* option) and
     * the menu locations of the active theme (nav_menu_locations in its theme_mods, only when they change).
     */
    public function maybe_note_layout_option($option, $old_value = null, $new_value = null)
    {
        if (!is_string($option) || '' === $option) {
            return;
        }
        if ('sidebars_widgets' !== $option && 0 !== strpos($option, 'widget_')) {
            $arguments = func_num_args();
            if (0 !== strpos($option, 'theme_mods_') || $arguments < 2 || $option !== 'theme_mods_' . get_option('stylesheet')) {
                return;
            }
            $locations = static function ($mods) {
                $value = is_array($mods) && isset($mods['nav_menu_locations']) && is_array($mods['nav_menu_locations']) ? $mods['nav_menu_locations'] : array();
                ksort($value);
                return $value;
            };
            // added_option passes the new value second; updated_option the old one, then the new one.
            if ($locations(3 === $arguments ? $old_value : array()) == $locations(3 === $arguments ? $new_value : $old_value)) {
                return;
            }
        }
        if (!empty($this->layout_refresh_hooks())) {
            $this->note_layout_change();
        }
    }

    /**
     * Takes note only: the decision is at the end of the request (maybe_defer_layout_refresh), when the menu or the
     * widgets are all written, as for Complianz. Returns its argument, so a filter added to the list keeps working.
     */
    public function note_layout_change($value = null)
    {
        if (!$this->layout_change_noted) {
            $this->layout_change_noted = true;
            add_action('shutdown', array($this, 'maybe_defer_layout_refresh'));
        }
        return $value;
    }

    /**
     * Only someone who may edit menus and widgets (edit_theme_options) or WP-CLI changes them: a page render, a
     * visitor or a WP-Cron task of another plugin that writes a widget option never starts a refresh of the site.
     */
    private function may_note_layout_change()
    {
        if (defined('WP_CLI') && WP_CLI) {
            return true;
        }
        return function_exists('current_user_can') && current_user_can('edit_theme_options');
    }

    /** The menu and widget wait in seconds: LAYOUT_REFRESH_MIN_WAIT, or «Attesa dopo l'ultima modifica» when longer. */
    private function layout_refresh_wait()
    {
        return max(self::LAYOUT_REFRESH_MIN_WAIT, $this->incremental_wait_seconds());
    }

    /**
     * End of a request that changed a menu or a widget. A Customizer save already queued every route in this
     * request. Otherwise the change opens or moves the wait: a series of saves is one refresh, written in Attività
     * when the wait opens, with the reason.
     */
    public function maybe_defer_layout_refresh()
    {
        if (!$this->may_note_layout_change() || empty($this->settings()['incremental_enabled']) || !$this->current_release()
            || $this->shared_output_refresh_queued_this_request) {
            return;
        }
        $now = time();
        $state = get_option(self::LAYOUT_REFRESH_OPTION, false);
        // A state without its event (deactivated, or the event lost) starts a new wait.
        $waiting = is_array($state) && isset($state['first']) && (int) $state['first'] > 0 && (int) $state['first'] <= $now
            && wp_next_scheduled(self::LAYOUT_REFRESH_HOOK);
        update_option(self::LAYOUT_REFRESH_OPTION, array('first' => $waiting ? (int) $state['first'] : $now, 'last' => $now), false);
        $at = $this->schedule_layout_refresh();
        if (!$waiting) {
            $this->log_activity(
                sprintf(/* translators: %d: minutes */ __('Menu o widget modificati: le pagine statiche si aggiornano fra %d minuti, se nel frattempo non cambiano ancora.', 'static-bridge'), (int) ceil($this->layout_refresh_wait() / 60)),
                __('Un menu o un widget compare in tutte le pagine, che vanno rigenerate tutte: più salvataggi ravvicinati fanno un solo aggiornamento. Ogni modifica sposta l’attesa, ma dalla prima non si aspetta mai più del doppio. Per aggiornarle subito usa «Aggiorna tutte le pagine statiche» nella scheda Genera.', 'static-bridge'),
                $at < 1
            );
        }
    }

    /** Replaces the single event of the menu and widget refresh with one at the end of the wait. Returns its time, or 0. */
    private function schedule_layout_refresh()
    {
        $state = get_option(self::LAYOUT_REFRESH_OPTION, false);
        wp_clear_scheduled_hook(self::LAYOUT_REFRESH_HOOK);
        if (!is_array($state) || !isset($state['first'], $state['last'])) {
            return 0;
        }
        $at = max(time(), $this->layout_refresh_due($state));
        return false === wp_schedule_single_event($at, self::LAYOUT_REFRESH_HOOK) ? 0 : $at;
    }

    /** When the wait ends: the last change + the wait, never past the first + twice the wait; a future time counts as now. */
    private function layout_refresh_due($state)
    {
        $now = time();
        $wait = $this->layout_refresh_wait();
        $first = min($now, (int) $state['first']);
        $last = min($now, max($first, (int) $state['last']));
        return min($last + $wait, $first + 2 * $wait);
    }

    /**
     * Callback of the single event: the wait is over, so every route is queued once with the reason, and the queue
     * does not open «Attesa dopo l'ultima modifica» again (this wait already covered it). A change in the meantime
     * moved the event; an early call reschedules it.
     */
    public function run_layout_refresh()
    {
        $state = get_option(self::LAYOUT_REFRESH_OPTION, false);
        if (!is_array($state) || !isset($state['first'], $state['last'])) {
            return;
        }
        if ($this->layout_refresh_due($state) > time()) {
            $this->schedule_layout_refresh();
            return;
        }
        delete_option(self::LAYOUT_REFRESH_OPTION);
        $this->queue_after_own_wait = true;
        try {
            $this->queue_shared_output_refresh(__('Un menu o un widget è cambiato.', 'static-bridge'));
        } finally {
            $this->queue_after_own_wait = false;
        }
    }

    /** «Aggiorna tutte le pagine statiche» queued every route: a menu or widget refresh still waiting has nothing left to do. */
    private function cancel_layout_refresh()
    {
        wp_clear_scheduled_hook(self::LAYOUT_REFRESH_HOOK);
        if (false !== get_option(self::LAYOUT_REFRESH_OPTION, false)) {
            delete_option(self::LAYOUT_REFRESH_OPTION);
        }
    }

    /**
     * A shared post (a reusable block, a Histeon component) whose owner knows exactly which pages show it:
     * the filter returns their URLs and only those are regenerated. null (the default), a non-list or
     * too many URLs fall back to the full refresh, which is always correct.
     */
    private function queue_known_dependents($post)
    {
        if (empty($this->settings()['incremental_enabled']) || !$this->current_release()) {
            return false;
        }
        $urls = apply_filters('static_bridge_dependents_for_post', null, $post);
        if (!is_array($urls) || count($urls) > self::MAX_KNOWN_DEPENDENTS) {
            return false;
        }
        foreach ($urls as $url) {
            if (array() === $this->sanitize_public_urls(array($url))) {
                // One URL outside this site (or malformed): the answer is not trusted, refresh everything.
                return false;
            }
        }
        $normalized = $this->sanitize_public_urls($urls);
        $this->enqueue_incremental_urls($normalized, (int) $post->ID, 'refresh', array(), 'dependent');
        $this->log_activity(
            __('Componente condiviso aggiornato: rigenerate solo le pagine che lo usano.', 'static-bridge'),
            sprintf(/* translators: 1: post ID, 2: number of paths */ __('Contenuto %1$d: %2$d percorsi indicati dal plugin che lo gestisce.', 'static-bridge'), (int) $post->ID, count($normalized))
        );
        return true;
    }

    /**
     * Public URLs of this site only, normalized and without duplicates; anything else is dropped.
     *
     * @param array $urls
     * @return string[]
     */
    private function sanitize_public_urls($urls)
    {
        $out = array();
        foreach ($urls as $url) {
            if (!is_string($url) || strlen($url) > 2048) {
                continue;
            }
            if ('' !== $url && '/' === $url[0] && (strlen($url) < 2 || '/' !== $url[1])) {
                $url = home_url($url);
            }
            $normalized = $this->normalize_public_url($url);
            if ($normalized) {
                $out[$normalized] = $normalized;
            }
        }
        return array_values($out);
    }

    /**
     * Histeon (the visual builder, technical prefix xb) published a release. Pages it changed already arrive through
     * wp_after_insert_post; its styles and settings are options Static Bridge does not watch, and they
     * change every page.
     */
    public function maybe_queue_xb_release($release_id = 0, $docs = array())
    {
        if (!is_array($docs)) {
            return;
        }
        foreach ($docs as $doc) {
            if (in_array($doc, array('styles', 'settings'), true)) {
                $this->queue_shared_output_refresh(__('Stili o impostazioni globali di Histeon pubblicati.', 'static-bridge'));
                return;
            }
        }
    }

    /**
     * Public filter, read only: apply_filters('static_bridge_status', null) answers with what another plugin
     * (a builder showing where the static copy stands) may tell its administrators. Cheap: options only, no
     * file walks. Paths, settings and secrets are never part of it.
     */
    public function public_status($status = null)
    {
        $last = get_option('static_bridge_last_release', array());
        $last = is_array($last) ? $last : array();
        $job = get_option(self::JOB_OPTION, array());
        $export = is_array($job) && isset($job['status']) && in_array($job['status'], array('running', 'paused', 'failed', 'complete', 'cancelled'), true)
            ? $job['status'] : 'idle';
        if ('running' === $export && !$this->job_is_running()) {
            $export = 'paused';
        }
        $activity = get_option(self::ACTIVITY_OPTION, array());
        $latest = is_array($activity) && !empty($activity) ? end($activity) : null;
        $settings = $this->settings();
        return array(
            'version' => self::VERSION,
            'serving' => '' !== $this->current_release(),
            'incremental' => !empty($settings['incremental_enabled']),
            'pages' => isset($last['pages']) ? absint($last['pages']) : 0,
            'published_at' => isset($last['published_at']) ? absint($last['published_at']) : 0,
            'pending' => count($this->incremental_queue()),
            'export' => $export,
            'last' => is_array($latest) && isset($latest['message']) ? array(
                'message' => wp_strip_all_tags((string) $latest['message']),
                'time' => isset($latest['time']) ? wp_strip_all_tags((string) $latest['time']) : '',
                'error' => !empty($latest['error']),
            ) : null,
            'admin_url' => $this->tab_url('generate'),
        );
    }

    /**
     * Public action: do_action('static_bridge_queue_paths', array $paths_or_urls, string $reason).
     * Queues those routes of this site for regeneration (paths like /chi-siamo/ or full URLs of this site).
     */
    public function queue_public_paths($paths = array(), $reason = '')
    {
        if (!is_array($paths) || empty($this->settings()['incremental_enabled']) || !$this->current_release()) {
            return;
        }
        $urls = array_slice($this->sanitize_public_urls($paths), 0, self::MAX_KNOWN_DEPENDENTS);
        $this->enqueue_incremental_urls($urls, 0, 'refresh', array(), 'dependent');
        if (!empty($urls)) {
            $this->log_activity(
                __('Rigenerazione richiesta da un altro plugin.', 'static-bridge'),
                sprintf(/* translators: 1: reason for the regeneration (a sentence), 2: number of queued paths */ __('%1$s Percorsi accodati: %2$d.', 'static-bridge'), sanitize_text_field((string) $reason), count($urls))
            );
        }
    }

    private function queue_shared_output_refresh($reason, $dependency_id = null)
    {
        $has_dependency = is_string($dependency_id) && preg_match('/\A[A-Za-z0-9_-]{1,64}\z/D', $dependency_id);
        if ($this->shared_output_refresh_queued_this_request
            || ($has_dependency && isset($this->shared_dependency_ids_queued_this_request[$dependency_id]))
            || empty($this->settings()['incremental_enabled'])) {
            return false;
        }
        $release = $this->current_release();
        if ('' === $release) {
            return false;
        }
        // Each page it regenerates says why in Attività.
        update_option(self::SHARED_REFRESH_REASON_OPTION, wp_strip_all_tags((string) $reason), false);

        $release_id = basename($release);
        if ($has_dependency && $this->release_uses_header_fragments($release)
            && $this->is_elementor_header_document($dependency_id)
            && Static_Bridge_Header_Fragments::document_is_context_independent($dependency_id)) {
            $fragment_index = new Static_Bridge_Header_Fragment_Index();
            $fragment_count = $fragment_index->enqueue_document($release_id, $dependency_id);
            if (is_int($fragment_count) && $fragment_count > 0) {
                $this->shared_dependency_ids_queued_this_request[$dependency_id] = true;
                $this->schedule_incremental_worker_after_change();
                $this->log_activity(
                    __('Aggiornamento header Elementor accodato come frammento SSI.', 'static-bridge'),
                    sprintf(/* translators: 1: Elementor document ID, 2: number of queued context variants */ __('Documento %1$s: %2$d varianti di contesto accodate; le pagine statiche che le includono non verranno renderizzate né riscritte.', 'static-bridge'), sanitize_text_field($dependency_id), $fragment_count)
                );
                return true;
            }
        }
        if (!empty($this->settings()['selective_shared_updates'])) {
            $index = new Static_Bridge_Dependency_Index();
            if ($index->is_ready($release_id)) {
                $queued = $has_dependency
                    ? $index->enqueue_dependency($release_id, $dependency_id)
                    : $index->enqueue_all_routes($release_id);
                if (0 === $queued && $has_dependency) {
                    // A new or conditionally assigned template may have no old edges.
                    // Refresh every route rather than risk leaving newly affected HTML stale.
                    $queued = $index->enqueue_all_routes($release_id);
                    $reason = __('Nessuna dipendenza preesistente trovata; applicato il refresh completo prudenziale. ', 'static-bridge') . $reason;
                }
                if (is_int($queued) && $queued > 0) {
                    if ($has_dependency) {
                        $this->shared_dependency_ids_queued_this_request[$dependency_id] = true;
                    } else {
                        $this->shared_output_refresh_queued_this_request = true;
                    }
                    $this->schedule_incremental_worker_after_change();
                    $this->log_activity(
                        __('Aggiornamento V2 dei percorsi statici accodato.', 'static-bridge'),
                        sprintf(/* translators: 1: reason for the update (a sentence), 2: number of affected routes */ __('%1$s Route interessate da questa modifica: %2$d. La coda persistente evita di serializzare tutte le URL in wp_options.', 'static-bridge'), wp_strip_all_tags((string) $reason), $queued)
                    );
                    return true;
                }
                $index->mark_failed($release_id);
            }
        }

        $routes = $this->discover_current_release_routes($release);
        if (is_wp_error($routes)) {
            $this->log_activity(__('Aggiornamento dei componenti condivisi non messo in coda.', 'static-bridge'), $routes->get_error_message(), true);
            return false;
        }

        $refreshes = array();
        foreach ($routes as $path => $url) {
            $refreshes[sha1($path)] = array(
                'url' => $url,
                'path' => $path,
                'action' => 'refresh',
                'role' => 'dependent',
                'post_id' => 0,
                'builders' => array(),
                'shared_content' => 1,
                'queued_at' => time(),
                'token' => wp_generate_uuid4(),
                'attempts' => 0,
            );
        }
        $queued = count($refreshes);

        if ($queued > 0) {
            $this->change_incremental_queue(function ($queue) use ($refreshes) {
                foreach ($refreshes as $key => $refresh) {
                    $queue[$key] = $refresh;
                }
                return $queue;
            });
            $this->schedule_incremental_worker_after_change();
        }
        $this->shared_output_refresh_queued_this_request = true;
        $detail = sprintf(/* translators: 1: reason for the update (a sentence), 2: number of affected static paths */ __('%1$s Percorsi statici interessati: %2$d.', 'static-bridge'), wp_strip_all_tags((string) $reason), $queued);
        $this->log_activity(__('Aggiornamento incrementale dei percorsi statici dopo una modifica globale o condivisa.', 'static-bridge'), $detail);
        return true;
    }

    private function is_elementor_header_document($document_id)
    {
        if (!preg_match('/\A[1-9][0-9]{0,19}\z/D', (string) $document_id)) {
            return false;
        }
        $post = get_post((int) $document_id);
        return $post instanceof WP_Post && 'elementor_library' === $post->post_type
            && 'header' === (string) get_post_meta((int) $document_id, '_elementor_template_type', true);
    }

    private function discover_current_release_routes($release)
    {
        if ('' === (string) $release || $release !== $this->current_release()) {
            return new WP_Error('static_bridge_shared_release', __('La release statica corrente non è più valida.', 'static-bridge'));
        }
        $release_real = realpath($release);
        if (!$release_real || !is_dir($release_real)) {
            return new WP_Error('static_bridge_shared_release', __('La cartella della release statica non è accessibile.', 'static-bridge'));
        }

        $routes = array();
        $root_prefix = trailingslashit($release_real);
        try {
            $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($release_real, FilesystemIterator::SKIP_DOTS));
            foreach ($iterator as $file) {
                if ($file->isLink() || !$file->isFile() || 'html' !== strtolower($file->getExtension()) || 'index.html' !== $file->getFilename()) {
                    continue;
                }
                $file_real = realpath($file->getPathname());
                if (!$file_real || 0 !== strpos($file_real, $root_prefix)) {
                    continue;
                }
                $relative = str_replace(DIRECTORY_SEPARATOR, '/', substr($file_real, strlen($root_prefix)));
                $directory = dirname($relative);
                $route = '.' === $directory ? '/' : '/' . trim($directory, '/') . '/';
                $path = $this->normalize_route_path($route);
                $url = $this->normalize_public_url(home_url($route));
                $mapped = '' !== $url ? $this->relative_html_path($url) : new WP_Error('static_bridge_shared_route', 'invalid');
                if ('' === $path || !$url || is_wp_error($mapped) || $relative !== $mapped) {
                    continue;
                }
                $routes[$path] = $url;
                if (count($routes) > self::MAX_EXPORT_URLS) {
                    return new WP_Error('static_bridge_shared_limit', __('La release contiene più percorsi HTML del limite supportato per un aggiornamento condiviso; avvia una nuova esportazione completa.', 'static-bridge'));
                }
            }
        } catch (Throwable $exception) {
            return new WP_Error('static_bridge_shared_scan', __('Non è stato possibile leggere in sicurezza i percorsi HTML della release corrente.', 'static-bridge'));
        }
        return $routes;
    }

    public function maybe_queue_bricks_meta($meta_id, $post_id, $meta_key, $meta_value)
    {
        if (!in_array($meta_key, array('_bricks_page_content_2', '_bricks_page_content'), true)
            || empty($this->settings()['incremental_enabled']) || !$this->current_release()) {
            return;
        }
        $post = get_post($post_id);
        if (!$post || 'publish' !== $post->post_status || !$this->is_public_incremental_post($post)
            || $this->is_shared_content_post_type($post->post_type)) {
            return;
        }
        delete_transient('static_bridge_incremental_query_pages');
        $this->enqueue_incremental_url(get_permalink($post), $post_id, 'refresh', array('bricks'), 'single');
    }

    public function maybe_queue_deleted_post($post_id, $post)
    {
        if (empty($this->settings()['incremental_enabled']) || !$this->current_release()
            || !($post instanceof WP_Post) || !$this->is_public_incremental_post($post)) {
            return;
        }
        $url = get_permalink($post);
        $path = $this->normalize_route_path($url);
        if ('' === $path || !$this->static_file_exists_for_path($path)) {
            return;
        }
        $this->enqueue_incremental_url($url, $post_id, 'delete', array(), 'single');
        // 2.5.0: also its previous and next posts and «Pagine da aggiornare a ogni pubblicazione», never its own route.
        $extra = array();
        foreach (array_merge($this->adjacent_post_urls($post), $this->publish_refresh_urls()) as $extra_url) {
            if ($path !== $this->normalize_route_path($extra_url)) {
                $extra[] = $extra_url;
            }
        }
        $this->enqueue_incremental_urls(array_unique(array_merge($extra, $this->archive_urls_for_post($post), $this->discover_query_page_urls())), $post_id, 'refresh', array(), 'dependent');
    }

    private function archive_refresh_enabled()
    {
        $settings = $this->settings();
        return !empty($settings['incremental_enabled']) && !empty($settings['export_archives']) && (bool) $this->current_release();
    }

    /** The term's archive routes: page 1 to the last, and pages the release still has past it. */
    private function term_route_urls($term_id, $taxonomy)
    {
        if (!in_array($taxonomy, $this->archive_taxonomies(), true) || !function_exists('get_term')) {
            return array();
        }
        $term = get_term((int) $term_id, $taxonomy);
        $term_url = is_object($term) && !is_wp_error($term) ? get_term_link($term, $taxonomy) : '';
        if (!is_string($term_url) || '' === $term_url) {
            return array();
        }
        $pages = $this->term_archive_pages((int) $term_id, $taxonomy, isset($term->count) ? (int) $term->count : 0);
        return array_merge($this->archive_page_urls(array(array($term_url, $pages))), $this->release_archive_pages_beyond($term_url, $pages));
    }

    /** Queues $old_urls for removal where they are not among $new_urls, and $new_urls for refresh. */
    private function queue_moved_archive_routes($old_urls, $new_urls)
    {
        $new_paths = array();
        foreach ($new_urls as $url) {
            $new_paths[$this->normalize_route_path($url)] = true;
        }
        $this->enqueue_incremental_urls(array_filter($old_urls, function ($url) use ($new_paths) {
            return !isset($new_paths[$this->normalize_route_path($url)]);
        }), 0, 'delete', array(), 'dependent');
        $this->enqueue_incremental_urls($new_urls, 0, 'refresh', array(), 'dependent');
    }

    public function remember_incremental_old_term($term_id, $taxonomy)
    {
        if ($this->archive_refresh_enabled()) {
            $this->incremental_old_term_urls[(int) $term_id] = $this->term_route_urls((int) $term_id, (string) $taxonomy);
        }
    }

    public function maybe_queue_term_archive($term_id, $term_taxonomy_id, $taxonomy)
    {
        $old_urls = isset($this->incremental_old_term_urls[(int) $term_id]) ? $this->incremental_old_term_urls[(int) $term_id] : array();
        unset($this->incremental_old_term_urls[(int) $term_id]);
        if ($this->archive_refresh_enabled()) {
            $this->queue_moved_archive_routes($old_urls, $this->term_route_urls((int) $term_id, (string) $taxonomy));
        }
    }

    public function maybe_queue_deleted_term($term_id, $taxonomy)
    {
        if ($this->archive_refresh_enabled()) {
            $this->queue_moved_archive_routes($this->term_route_urls((int) $term_id, (string) $taxonomy), array());
        }
    }

    public function maybe_queue_author_archive($user_id, $old_user_data = null)
    {
        $author_types = $this->archive_post_types('author');
        if (!$this->archive_refresh_enabled() || empty($author_types) || !function_exists('count_user_posts')) {
            return;
        }
        $posts = (int) count_user_posts((int) $user_id, $author_types, true);
        if ($posts < 1) {
            return;
        }
        $pages = $this->archive_page_count($posts);
        $new_url = get_author_posts_url((int) $user_id);
        $old_nicename = is_object($old_user_data) && isset($old_user_data->user_nicename) ? (string) $old_user_data->user_nicename : '';
        $old_url = '' !== $old_nicename ? get_author_posts_url((int) $user_id, $old_nicename) : $new_url;
        if ($this->normalize_route_path($old_url) === $this->normalize_route_path($new_url)) {
            return;
        }
        $this->queue_moved_archive_routes(
            array_merge($this->archive_page_urls(array(array($old_url, $pages))), $this->release_archive_pages_beyond($old_url, $pages)),
            $this->archive_page_urls(array(array($new_url, $pages)))
        );
    }

    /** Posts per page, permalinks, the front page: every list changes, so every static route is rendered again. */
    public function maybe_queue_reading_option_refresh($old_value, $value, $option = '')
    {
        if ($old_value === $value || !$this->current_release()) {
            return;
        }
        if ('permalink_structure' === $option) {
            // The .htaccess rules follow the final slash of the permalinks (the Nginx block is pasted again).
            $this->update_routing_rules();
        }
        if (!$this->queue_shared_output_refresh(sprintf(/* translators: %s: WordPress option name */ __('L’impostazione %s di WordPress è cambiata.', 'static-bridge'), sanitize_key((string) $option)))) {
            return;
        }
        $this->log_activity(
            __('Impostazioni di lettura o permalink cambiate: avvia un export completo.', 'static-bridge'),
            __('Le pagine statiche esistenti vengono rigenerate e quelle diventate 404 o reindirizzate vengono rimosse; le route nuove (altre pagine /page/N/, i nuovi permalink) entrano con il prossimo export completo.', 'static-bridge'),
            true
        );
    }

    public function process_incremental_queue()
    {
        if (empty($this->settings()['incremental_enabled'])) {
            return;
        }
        if ($this->job_is_running()) {
            $this->schedule_incremental_worker(60);
            return;
        }
        // «Attesa dopo l'ultima modifica» (2.5.0): automatic updates wait for the edits to settle. A manual push
        // never waits: with one in the queue the worker takes the pushes only and comes back when the wait ends.
        $wait_remaining = $this->incremental_wait_remaining();
        if ($wait_remaining > 0 && !$this->incremental_queue_has_manual_push()) {
            $this->schedule_incremental_worker($wait_remaining, true);
            return;
        }
        $holding = $wait_remaining > 0;
        $incremental_lock = $this->acquire_incremental_lock();
        if (false === $incremental_lock) {
            $this->schedule_incremental_worker(20);
            return;
        }

        $this->processing_incremental_items = true;
        try {
            $release = $this->current_release();
            if (!$release) {
                $this->schedule_incremental_worker(60);
                return;
            }

            $started_at = microtime(true);
            $processed = 0;
            $release_id = basename($release);
            while ($processed < 20 && microtime(true) - $started_at < 45) {
                if (!$holding && $this->release_uses_header_fragments($release)) {
                    $fragment_index = new Static_Bridge_Header_Fragment_Index();
                    $fragment_item = $fragment_index->next_pending($release_id);
                    if (false === $fragment_item) {
                        $this->log_activity(
                            __('Coda header SSI non leggibile; il worker riproverà.', 'static-bridge'),
                            __('Non è stato possibile leggere o rivendicare una variante del frammento header.', 'static-bridge'),
                            true
                        );
                        $this->schedule_incremental_worker(60);
                        return;
                    }
                    if (is_array($fragment_item)) {
                        if ('retry' === $this->process_header_fragment_item($fragment_item, $release)) {
                            return;
                        }
                        $processed++;
                        continue;
                    }
                }
                if (!$holding && !empty($this->settings()['selective_shared_updates'])) {
                    $index = new Static_Bridge_Dependency_Index();
                    if ($index->is_ready($release_id)) {
                        $indexed_item = $index->next_pending($release_id);
                        if (false === $indexed_item) {
                            $index->mark_failed($release_id);
                            $this->log_activity(
                                __('Coda V2 non leggibile; attivato il fallback prudenziale.', 'static-bridge'),
                                __('L’indice persistente non ha restituito una route valida. Il refresh continuerà tramite la coda conservativa del plugin.', 'static-bridge'),
                                true
                            );
                            $this->shared_output_refresh_queued_this_request = false;
                            $this->queue_shared_output_refresh(__('Ripristino dopo errore di lettura della coda V2.', 'static-bridge'));
                        } elseif (is_array($indexed_item)) {
                            if ('retry' === $this->process_incremental_item((string) $indexed_item['_route_hash'], $indexed_item, $release)) {
                                return;
                            }
                            $processed++;
                            continue;
                        }
                    }
                }
                $queue = $this->incremental_queue();
                if ($holding) {
                    // Waiting: only the manual pushes, wherever a retry moved them in the queue.
                    $key = $this->first_manual_push_key($queue);
                    if (null === $key) {
                        break;
                    }
                    $item = $queue[$key];
                } else {
                    // Nothing new left (only routes waiting for a retry, or none): the next edit starts a new wait.
                    if (!$this->incremental_queue_has_fresh_item($queue)) {
                        $this->end_incremental_wait();
                    }
                    if (empty($queue)) {
                        break;
                    }
                    reset($queue);
                    $key = key($queue);
                    $item = current($queue);
                }
                if (!is_array($item) || empty($item['url']) || empty($item['token'])) {
                    // A malformed item: out of the queue, unless another request has replaced it meanwhile.
                    $this->change_incremental_queue(function ($queue) use ($key, $item) {
                        if (!array_key_exists($key, $queue) || $queue[$key] !== $item) {
                            return null;
                        }
                        unset($queue[$key]);
                        return $queue;
                    });
                    $processed++;
                    continue;
                }
                if ('retry' === $this->process_incremental_item($key, $item, $release)) {
                    return;
                }
                $processed++;
            }

            $wait_remaining = $this->incremental_wait_remaining();
            if ($wait_remaining > 0 && !$this->incremental_queue_has_manual_push()) {
                // The automatic updates still wait (or a new edit came meanwhile): back when the wait ends.
                $this->schedule_incremental_worker($wait_remaining, true);
                return;
            }

            $indexed_pending = !empty($this->settings()['selective_shared_updates'])
                ? (new Static_Bridge_Dependency_Index())->pending_count($release_id)
                : 0;
            $fragment_pending = $this->release_uses_header_fragments($release)
                ? (new Static_Bridge_Header_Fragment_Index())->pending_count($release_id)
                : 0;
            if (!empty($this->incremental_queue())) {
                $this->schedule_incremental_worker(0);
            } elseif ((is_int($indexed_pending) && $indexed_pending > 0)
                || (is_int($fragment_pending) && $fragment_pending > 0)) {
                $delays = array();
                if (is_int($indexed_pending) && $indexed_pending > 0) {
                    $delays[] = (new Static_Bridge_Dependency_Index())->next_pending_delay($release_id);
                }
                if (is_int($fragment_pending) && $fragment_pending > 0) {
                    $delays[] = (new Static_Bridge_Header_Fragment_Index())->next_pending_delay($release_id);
                }
                $delays = array_values(array_filter($delays, 'is_int'));
                if (empty($delays)) {
                    $this->log_activity(
                        __('Coda V2 in attesa non leggibile; il worker riproverà.', 'static-bridge'),
                        __('Non è stato possibile calcolare il prossimo orario di esecuzione della coda persistente o dei frammenti.', 'static-bridge'),
                        true
                    );
                    $delay = 60;
                } else {
                    $delay = min($delays);
                }
                $this->schedule_incremental_worker($delay);
            } elseif (false === $indexed_pending || false === $fragment_pending) {
                $this->log_activity(
                    __('Stato della coda V2 non leggibile; il worker riproverà.', 'static-bridge'),
                    __('La coda persistente o dei frammenti non è stata rimossa; è previsto un nuovo controllo.', 'static-bridge'),
                    true
                );
                $this->schedule_incremental_worker(60);
            }
        } finally {
            $this->processing_incremental_items = false;
            $this->release_incremental_lock($incremental_lock);
            // One Attività line for the pages of this run saved with cache signals (2.5.0).
            $this->flush_incremental_cache_signals();
            // One bounded API call here; larger purges continue in their own cron request.
            $this->run_cloudflare_purge(1);
        }
    }

    private function process_header_fragment_item($item, $release)
    {
        $release_id = basename((string) $release);
        $index = new Static_Bridge_Header_Fragment_Index();
        $document_id = (string) ($item['dependency_id'] ?? '');
        $expected_file = Static_Bridge_Header_Fragments::include_filename($document_id, (string) ($item['variant_id'] ?? ''));
        $expected_url = $this->normalize_public_url(home_url((string) ($item['representative_path'] ?? '')));
        if (!is_string($expected_file) || $expected_file !== (string) ($item['file_name'] ?? '')
            || empty($item['url']) || !$expected_url
            || $expected_url !== $this->normalize_public_url((string) $item['url'])) {
            return $this->retry_header_fragment_item($item, $release_id, __('Percorso o identità del frammento non validi.', 'static-bridge'));
        }
        $claimed = $index->claim_document_variants($release_id, $item);
        if (!is_array($claimed) || empty($claimed)) {
            return $this->retry_header_fragment_item($item, $release_id, __('Non è stato possibile acquisire in modo esclusivo tutte le varianti dell’header.', 'static-bridge'));
        }

        $updates = array();
        $updated_items = array();
        foreach ($claimed as $variant_item) {
            $variant_file = Static_Bridge_Header_Fragments::include_filename(
                (string) ($variant_item['dependency_id'] ?? ''),
                (string) ($variant_item['variant_id'] ?? '')
            );
            $variant_url = $this->normalize_public_url(home_url((string) ($variant_item['representative_path'] ?? '')));
            if (!is_string($variant_file) || $variant_file !== (string) ($variant_item['file_name'] ?? '')
                || !$variant_url || $variant_url !== $this->normalize_public_url((string) ($variant_item['url'] ?? ''))) {
                return $this->retry_header_fragment_items($claimed, $release_id, __('Percorso o identità di una variante dell’header non validi.', 'static-bridge'));
            }
            $result = $this->fetch_page((string) $variant_item['url'], 10);
            if (is_wp_error($result)) {
                return $this->retry_header_fragment_items($claimed, $release_id, $result->get_error_message());
            }
            $body = $this->rewrite_internal_origins_as_root_relative((string) $result['body']);
            $header = Static_Bridge_Header_Fragments::extract_unique_elementor_header($body);
            if (!is_array($header) || (string) $header['owner_id'] !== $document_id
                || Static_Bridge_Header_Fragments::contains_ssi_directive($header['markup'])
                || !Static_Bridge_Header_Fragments::document_is_context_independent($document_id)) {
                return $this->retry_header_fragment_items($claimed, $release_id, __('Un header aggiornato non corrisponde al documento indicizzato o contiene dati contestuali.', 'static-bridge'));
            }
            $updates[$variant_file] = $header['markup'];
            $updated_items[] = array('item' => $variant_item, 'markup_hash' => $header['markup_hash']);
        }

        $root = realpath((string) $release);
        if (!$root || $root !== $this->current_release()) {
            return $this->retry_header_fragment_items($claimed, $release_id, __('La release non è più quella attualmente pubblicata.', 'static-bridge'));
        }
        $published = $this->publish_header_fragment_snapshot($root, $document_id, $updates);
        if (is_wp_error($published)) {
            return $this->retry_header_fragment_items($claimed, $release_id, $published->get_error_message());
        }

        $incomplete = array();
        foreach ($updated_items as $updated) {
            if (!$index->complete($release_id, $updated['item'], (string) $updated['markup_hash'])) {
                $incomplete[] = $updated['item'];
            }
        }
        if (!empty($incomplete)) {
            $this->retry_header_fragment_items($incomplete, $release_id, __('Snapshot pubblicato; riconciliazione degli stati della coda ancora necessaria.', 'static-bridge'));
            $this->log_activity(
                __('Header aggiornato; stato della coda da riconciliare.', 'static-bridge'),
                sprintf(/* translators: %s: Elementor document ID */ __('Documento %s: tutte le varianti sono state pubblicate insieme; i record non confermati saranno riprovati.', 'static-bridge'), sanitize_text_field($document_id)),
                true
            );
            return 'retry';
        }
        $this->clear_failure_notice();
        // The pages are composed by SSI at request time: every cached page embeds the old header.
        $this->queue_cloudflare_purge('everything', __('header SSI aggiornato', 'static-bridge'));
        $this->log_activity(
            __('Header Elementor aggiornato atomicamente senza riscrivere le pagine.', 'static-bridge'),
            sprintf(/* translators: 1: Elementor document ID, 2: number of updated variants */ __('Documento %1$s · varianti aggiornate insieme: %2$d.', 'static-bridge'), sanitize_text_field($document_id), count($updated_items))
        );
        return 'done';
    }

    private function retry_header_fragment_item($item, $release_id, $message)
    {
        $index = new Static_Bridge_Header_Fragment_Index();
        return $this->retry_header_fragment_items(array($item), $release_id, $message, $index);
    }

    private function retry_header_fragment_items($items, $release_id, $message, $index = null)
    {
        $index = $index instanceof Static_Bridge_Header_Fragment_Index ? $index : new Static_Bridge_Header_Fragment_Index();
        $retry_failed = false;
        foreach ((array) $items as $item) {
            if (!is_array($item)) {
                $retry_failed = true;
                continue;
            }
            $attempts = isset($item['attempts']) ? (int) $item['attempts'] + 1 : 1;
            $delay = min(3600, 15 * (2 ** min(6, $attempts)));
            if (!$index->retry($release_id, $item, $message, $delay)) {
                $retry_failed = true;
            }
        }
        if ($retry_failed) {
            $this->log_activity(
                __('Retry del frammento header non registrato.', 'static-bridge'),
                sprintf(/* translators: 1: Elementor document ID, 2: error message */ __('Documento %1$s — %2$s', 'static-bridge'), sanitize_text_field((string) ($items[0]['dependency_id'] ?? '')), sanitize_text_field((string) $message)),
                true
            );
            $this->schedule_incremental_worker(60);
            return 'retry';
        }
        $attempts = isset($items[0]['attempts']) ? (int) $items[0]['attempts'] + 1 : 1;
        if (1 === $attempts || 3 === $attempts || 7 === $attempts) {
            $this->log_activity(
                __('Aggiornamento header SSI non riuscito; verrà riprovato.', 'static-bridge'),
                sprintf(/* translators: 1: Elementor document ID, 2: error message */ __('Documento %1$s — %2$s', 'static-bridge'), sanitize_text_field((string) ($items[0]['dependency_id'] ?? '')), sanitize_text_field((string) $message)),
                true
            );
        }
        if (self::INCREMENTAL_FAILURE_NOTICE_ATTEMPT === $attempts) {
            $this->notify_update_failure('incremental', sprintf(/* translators: 1: Elementor document ID, 2: error message */ __('Documento %1$s — %2$s', 'static-bridge'), sanitize_text_field((string) ($items[0]['dependency_id'] ?? '')), (string) $message));
        }
        $this->schedule_incremental_worker($delay);
        return 'retry';
    }

    private function process_incremental_item($key, $item, $release)
    {
        $url = $item['url'];
        $path = $this->normalize_route_path($url);
        $action = isset($item['action']) ? $item['action'] : 'refresh';
        $role = isset($item['role']) ? $item['role'] : 'single';
        $manual_push_token = isset($item['manual_push_token']) ? $this->sanitize_post_push_token($item['manual_push_token']) : '';
        if ('' === $path || ('refresh' === $action && $this->is_excluded_path($path))) {
            $action = 'delete';
        }
        if ('single' === $role && !empty($item['post_id']) && 'refresh' === $action) {
            $post = get_post((int) $item['post_id']);
            // A password-protected post is not public, as in the manual push and the full export
            // (hardening note 29 of the 3 November 2026 audit).
            // A translated route of the post (TranslatePress, static_bridge_translated_urls) is not its permalink:
            // compared with it, the translation was removed instead of refreshed (2.2.9 and 2.2.10).
            if (!$post || 'publish' !== $post->post_status || !empty($post->post_password)
                || (empty($item['translation']) && $path !== $this->normalize_route_path(get_permalink($post)))) {
                $action = 'delete';
            }
        }

        if ('delete' === $action) {
            $removed = $this->remove_incremental_page($release, $url);
            if (is_wp_error($removed)) {
                $this->retry_incremental_item($key, $item, $removed->get_error_message());
                return 'retry';
            }
            if (!empty($removed['deleted']) && !$this->update_incremental_manifest($release, -1)) {
                $this->retry_incremental_item($key, $item, __('File eliminato, ma manifest della release non aggiornabile.', 'static-bridge'));
                return 'retry';
            }
            // As for a written page: on Apache the removal reaches visitors only once the rules name a
            // copy without the route, so publish them before completing the item or purging the edge
            // (hardening note 28 of the 3 November 2026 audit).
            $this->update_routing_rules();
            if ($this->apache_serves_stale_copy()) {
                $this->retry_incremental_item($key, $item, __('Pagina tolta dalla release, ma le regole Apache in .htaccess non sono state aggiornate: i visitatori la vedono ancora.', 'static-bridge'));
                return 'retry';
            }
            $this->complete_incremental_item($key, $item);
            $this->clear_failure_notice();
            $this->queue_cloudflare_purge(array($url), __('route statica rimossa', 'static-bridge'));
            if ('' !== $manual_push_token) {
                $this->set_post_push_status($manual_push_token, 'failed', array('last_error' => __('Il contenuto non è più pubblicabile come pagina statica; la route statica è stata rimossa.', 'static-bridge')));
            }
            $this->log_activity(__('Pagina statica rimossa dopo modifica o rimozione del contenuto.', 'static-bridge'), $path);
            return 'done';
        }

        $result = $this->fetch_page($url, 10);
        if (is_wp_error($result)) {
            if ('' !== $manual_push_token && in_array($result->get_error_code(), array('static_bridge_redirect', 'static_bridge_redirect_unsafe'), true)) {
                $this->complete_incremental_item($key, $item);
                $this->set_post_push_status($manual_push_token, 'failed', array('last_error' => $result->get_error_message()));
                $this->log_activity(__('Push manuale non completato: la route reindirizza e non è stata scritta.', 'static-bridge'), $path . ' — ' . $result->get_error_message(), true);
                return 'done';
            }
            // A redirect does not go away by retrying: an author archive that an SEO plugin sends to the
            // homepage, a renamed term. Retried, it stayed first in the queue and blocked every route after it.
            if (in_array($result->get_error_code(), array('static_bridge_redirect', 'static_bridge_redirect_unsafe'), true)) {
                return $this->process_redirected_item($key, $item, $release, $result);
            }
            $http_status = 'static_bridge_http' === $result->get_error_code() ? (int) $result->get_error_data() : 0;
            // 401 and 403 too: the full export leaves out a route the anonymous render may not see, so the
            // incremental worker must not keep serving its earlier public copy (Histeon audit, 3 November 2026).
            if (in_array($http_status, array(401, 403, 404, 410), true)
                || ('static_bridge_http' === $result->get_error_code() && preg_match('/\b404\b/', $result->get_error_message()))) {
                $removed = $this->remove_incremental_page($release, $url);
                if (is_wp_error($removed) || (!empty($removed['deleted']) && !$this->update_incremental_manifest($release, -1))) {
                    $message = is_wp_error($removed) ? $removed->get_error_message() : __('Manifest della release non aggiornabile.', 'static-bridge');
                    $this->retry_incremental_item($key, $item, $message);
                    return 'retry';
                }
                $this->update_routing_rules();
                if ($this->apache_serves_stale_copy()) {
                    $this->retry_incremental_item($key, $item, __('Pagina tolta dalla release, ma le regole Apache in .htaccess non sono state aggiornate: i visitatori la vedono ancora.', 'static-bridge'));
                    return 'retry';
                }
                $this->complete_incremental_item($key, $item);
                $this->clear_failure_notice();
                $code = $http_status > 0 ? $http_status : 404;
                /* translators: %d: HTTP status code */
                $this->queue_cloudflare_purge(array($url), sprintf(__('route statica rimossa (%d)', 'static-bridge'), $code));
                if ('' !== $manual_push_token) {
                    /* translators: %d: HTTP status code */
                    $this->set_post_push_status($manual_push_token, 'failed', array('last_error' => sprintf(__('WordPress ha restituito %d; la pagina statica non è stata aggiornata.', 'static-bridge'), $code)));
                }
                /* translators: %d: HTTP status code */
                $this->log_activity(sprintf(__('URL statica rimossa: WordPress restituisce %d.', 'static-bridge'), $code), $path);
                return 'done';
            }
            // 5xx and network errors: retried with backoff, then dropped when the release still has
            // a copy of the route. A route without one stays queued: the queue keeps it dynamic, where once
            // dropped Strict would answer 404 for a page WordPress serves.
            $attempts = isset($item['attempts']) ? (int) $item['attempts'] : 0;
            if ($attempts + 1 >= self::MAX_INCREMENTAL_ATTEMPTS && !isset($item['_queue_backend']) && $this->static_file_exists_for_path($path)) {
                $this->complete_incremental_item($key, $item);
                $this->update_routing_rules();
                if ('' !== $manual_push_token) {
                    $this->set_post_push_status($manual_push_token, 'failed', array('last_error' => $result->get_error_message()));
                }
                $this->log_activity(
                    __('Aggiornamento incrementale abbandonato dopo troppi tentativi.', 'static-bridge'),
                    $path . ' — ' . $result->get_error_message() . ' ' . __('La copia statica precedente, se c’era, resta pubblicata fino al prossimo export completo.', 'static-bridge'),
                    true
                );
                return 'done';
            }
            $this->retry_incremental_item($key, $item, $result->get_error_message());
            return 'retry';
        }

        $prepared = $this->prepare_static_html($url, $result);
        if (is_wp_error($prepared)) {
            // Route the page to WordPress first, then remove the copy with stale nonces (Fluent Forms
            // record_fluent_forms_dynamic_route(), WooCommerce record_woocommerce_dynamic_route()).
            if (!$this->record_dynamic_route_for($prepared, $path)) {
                $this->retry_incremental_item($key, $item, __('Non è stato possibile registrare la pagina da servire in modo dinamico.', 'static-bridge'));
                return 'retry';
            }
            $this->update_routing_rules();
            $removed = $this->remove_incremental_page($release, $url);
            if (is_wp_error($removed) || (!empty($removed['deleted']) && !$this->update_incremental_manifest($release, -1))) {
                $this->retry_incremental_item($key, $item, is_wp_error($removed) ? $removed->get_error_message() : __('Manifest della release non aggiornabile.', 'static-bridge'));
                return 'retry';
            }
            $this->complete_incremental_item($key, $item);
            if ('' !== $manual_push_token) {
                $this->set_post_push_status($manual_push_token, 'failed', array('last_error' => $prepared->get_error_message()));
            }
            $this->log_activity(
                'static_bridge_woocommerce_dynamic' === $prepared->get_error_code()
                    ? __('Pagina del negozio servita da WordPress.', 'static-bridge')
                    : __('Pagina Fluent Forms servita da WordPress: markup non riconosciuto.', 'static-bridge'),
                $path . ' — ' . $prepared->get_error_message(),
                true
            );
            return 'done';
        }
        // «Non riscrivere le pagine identiche» (2.5.0, off by default): an automatic refresh whose final HTML is already
        // the file in the release, written and purged before, is not written again, and the edge is not purged. A
        // manual push always writes. null: the option is off, nothing is compared or tracked.
        $identical = $this->skip_identical_pages_enabled() ? ('' === $manual_push_token && $this->route_settled($release, $path)) : null;
        $write = $this->write_incremental_page($release, $url, $prepared, $identical);
        $unchanged = !is_wp_error($write) && !empty($write['unchanged']);
        $page_delta = !is_wp_error($write) && !empty($write['created']) ? 1 : 0;
        if ($page_delta) {
            $this->remember_incremental_added_route($path);
        }
        if (!is_wp_error($write) && !empty($this->settings()['selective_shared_updates'])) {
            $release_id = basename($release);
            $index = new Static_Bridge_Dependency_Index();
            if ($index->is_ready($release_id)
                && !$index->index_route($release_id, $path, $url, (string) $result['body'])) {
                $index->mark_failed($release_id);
                $this->log_activity(
                    __('Indice V2 reso incompleto dopo un aggiornamento incrementale.', 'static-bridge'),
                    __('La pagina è stata pubblicata; i prossimi aggiornamenti condivisi useranno il fallback completo.', 'static-bridge'),
                    true
                );
            }
        }
        $written_file_exists = !is_wp_error($write) && !empty($write['file']) && is_file($write['file']);
        $release_is_current = realpath($release) && realpath($release) === $this->current_release();
        // An unchanged page leaves the manifest alone: on Apache the served copy is not rebuilt for nothing.
        $manifest_updated = $written_file_exists && $release_is_current && ($unchanged || $this->update_incremental_manifest($release, $page_delta));
        if (!$written_file_exists || !$release_is_current || !$manifest_updated) {
            $message = is_wp_error($write)
                ? $write->get_error_message()
                : (!$written_file_exists
                    ? __('Il file statico non risulta presente dopo la scrittura.', 'static-bridge')
                    : (!$release_is_current ? __('La release è cambiata durante il push; l’aggiornamento verrà riprovato sulla versione attiva.', 'static-bridge') : __('Manifest della release non aggiornabile.', 'static-bridge')));
            $this->retry_incremental_item($key, $item, $message);
            return 'retry';
        }
        $this->forget_fluent_forms_dynamic_route($path);
        $this->forget_woocommerce_dynamic_route($path);
        // On Apache the page reaches visitors only when the rules name a copy that contains
        // it: publish them before reporting the push as completed or purging the edge.
        $this->update_routing_rules();
        if ($this->apache_serves_stale_copy()) {
            $this->retry_incremental_item($key, $item, __('Pagina scritta nella release, ma le regole Apache in .htaccess non sono state aggiornate: i visitatori vedono ancora la versione precedente.', 'static-bridge'));
            return 'retry';
        }
        $this->complete_incremental_item($key, $item);
        // The worker writes pages again: the next failure may e-mail the administrator again (2.5.0).
        $this->clear_failure_notice();
        if (!$unchanged) {
            $this->queue_cloudflare_purge(array($url), __('pagina statica aggiornata', 'static-bridge'));
        }
        if (null !== $identical) {
            // Written and purged: from now on an identical render of this route may be skipped.
            $this->settle_route($path);
        }
        $this->note_cache_signal($this->incremental_cache_signals, $url, $this->cache_signal_reason($prepared, isset($result['render_facts']) ? $result['render_facts'] : array()));
        if ('' !== $manual_push_token) {
            $this->set_post_push_status($manual_push_token, 'completed', array('last_error' => '', 'completed_at' => time()));
        }
        if ($unchanged) {
            $this->log_activity(__('Pagina statica invariata: non riscritta e senza svuotare la CDN.', 'static-bridge'), $path);
        } elseif (!empty($item['shared_content'])) {
            $shared_reason = (string) get_option(self::SHARED_REFRESH_REASON_OPTION, '');
            $this->log_activity(__('Pagina statica aggiornata dopo una modifica globale o condivisa.', 'static-bridge'), $path . ('' !== $shared_reason ? ' — ' . $shared_reason : ''));
        } else {
            $builder_label = !empty($item['builders']) ? ' · ' . implode(', ', array_map(array($this, 'builder_label'), $item['builders'])) : '';
            $this->log_activity(__('Pagina statica aggiornata in modo incrementale.', 'static-bridge'), $path . $builder_label);
        }
        return 'done';
    }

    private function process_redirected_item($key, $item, $release, $result)
    {
        $url = isset($item['url']) ? (string) $item['url'] : '';
        $path = $this->normalize_route_path($url);
        $target = 'static_bridge_redirect' === $result->get_error_code()
            ? $this->normalize_public_url($result->get_error_data())
            : '';
        $target_path = $target ? $this->normalize_route_path($target) : '';

        if ($target && '' !== $target_path && $target_path !== $path) {
            $target_key = sha1($target_path);
            $queue = $this->incremental_queue();
            if (!isset($queue[$target_key]) && !$this->enqueue_incremental_url($target, 0, 'refresh', array(), 'dependent')) {
                $this->retry_incremental_item($key, $item, __('La destinazione canonica non può essere accodata in sicurezza.', 'static-bridge'));
                return 'retry';
            }
            if (!empty($item['shared_content'])) {
                $this->change_incremental_queue(function ($queue) use ($target_key) {
                    if (!isset($queue[$target_key]) || !is_array($queue[$target_key])) {
                        return null;
                    }
                    $queue[$target_key]['shared_content'] = 1;
                    return $queue;
                });
            }
        } else {
            $target = '';
        }

        $removed = $this->remove_incremental_page($release, $url);
        if (is_wp_error($removed)) {
            $this->retry_incremental_item($key, $item, $removed->get_error_message());
            return 'retry';
        }
        if (!empty($removed['deleted']) && !$this->update_incremental_manifest($release, -1)) {
            $this->retry_incremental_item($key, $item, __('File con redirect rimosso, ma manifest della release non aggiornabile.', 'static-bridge'));
            return 'retry';
        }

        // Like the other removals (note 28): complete and purge only once Apache stops serving the copy.
        $this->update_routing_rules();
        if ($this->apache_serves_stale_copy()) {
            $this->retry_incremental_item($key, $item, __('Pagina tolta dalla release, ma le regole Apache in .htaccess non sono state aggiornate: i visitatori la vedono ancora.', 'static-bridge'));
            return 'retry';
        }
        $this->complete_incremental_item($key, $item);
        $this->queue_cloudflare_purge(array($url), __('copia statica rimossa per un redirect', 'static-bridge'));
        if ($target) {
            $this->log_activity(__('Copia statica rimossa per applicare il redirect canonico same-origin di WordPress.', 'static-bridge'), $path . ' → ' . $target_path);
        } else {
            $this->log_activity(__('Copia statica rimossa: WordPress reindirizza a una destinazione esterna o dinamica non seguita.', 'static-bridge'), $path, true);
        }
        return 'done';
    }

    private function is_public_incremental_post($post)
    {
        return $post instanceof WP_Post
            && 'attachment' !== $post->post_type
            && in_array($post->post_type, $this->exportable_public_post_types(), true);
    }

    private function exportable_public_post_types()
    {
        $post_types = get_post_types(array('public' => true, 'publicly_queryable' => true), 'names');
        if (!is_array($post_types)) {
            $post_types = array();
        }

        // Core pages are public and have rewrite routes, but WordPress marks the
        // built-in `page` post type as not publicly_queryable. Include that one
        // explicitly without broadening support to other non-queryable types.
        $public_post_types = get_post_types(array('public' => true), 'names');
        if (is_array($public_post_types) && isset($public_post_types['page'])) {
            $post_types['page'] = 'page';
        }

        unset($post_types['attachment']);
        return array_values(array_filter($post_types, function ($post_type) {
            return is_string($post_type) && (bool) preg_match('/^[A-Za-z0-9_-]{1,20}$/', $post_type);
        }));
    }

    private function enqueue_incremental_url($url, $post_id, $action, $builders, $role)
    {
        // Success is the route itself in the queue, not a count of one: with its translations (TranslatePress,
        // static_bridge_translated_urls) one route queues several. Counted, a redirect whose canonical target has
        // translations was never completed and queued the target again on every retry (doc 23, item 182).
        $normalized = is_string($url) ? $this->normalize_public_url($url) : false;
        if (!$normalized || $this->enqueue_incremental_urls(array($url), $post_id, $action, $builders, $role) < 1) {
            return false;
        }
        $queue = $this->incremental_queue();
        return isset($queue[sha1($this->normalize_route_path($normalized))]);
    }

    /**
     * Queues several routes with one option write, one routing update (when a route is removed or has no
     * file yet) and one worker schedule: a post change can name hundreds of list pages.
     */
    private function enqueue_incremental_urls($urls, $post_id, $action, $builders, $role)
    {
        $items = array();
        $queued = 0;
        $routing_paths = array();
        $originals = array();
        foreach ((array) $urls as $url) {
            if (is_string($url)) {
                $originals[$url] = true;
            }
        }
        foreach ($this->with_translated_urls((array) $urls) as $url) {
            $normalized = $this->normalize_public_url($url);
            if (!$normalized) {
                continue;
            }
            $path = $this->normalize_route_path($normalized);
            $key = sha1($path);
            $queue_item = array(
                'url' => $normalized,
                'path' => $path,
                'action' => in_array($action, array('refresh', 'delete'), true) ? $action : 'refresh',
                'role' => 'single' === $role ? 'single' : 'dependent',
                'post_id' => absint($post_id),
                'builders' => array_values(array_unique(array_map('sanitize_key', (array) $builders))),
                'queued_at' => time(),
                'token' => wp_generate_uuid4(),
                'attempts' => 0,
            );
            if (!isset($originals[$url])) {
                // The same content in another language: its route is not the post's permalink (doc 23, item 181).
                $queue_item['translation'] = 1;
            }
            $items[$key] = $queue_item;
            $queued++;
            if ('delete' === $action || !$this->static_file_exists_for_path($path)) {
                $routing_paths[] = $path;
            }
        }
        if (0 === $queued) {
            return 0;
        }
        // The routes are worked out before the lock; under it only the merge, keeping the push a route waits for.
        $this->change_incremental_queue(function ($queue) use ($items) {
            foreach ($items as $key => $queue_item) {
                $manual_push_token = isset($queue[$key]['manual_push_token'])
                    ? $this->sanitize_post_push_token($queue[$key]['manual_push_token'])
                    : '';
                if ('' !== $manual_push_token) {
                    $queue_item['manual_push_token'] = $manual_push_token;
                }
                $queue[$key] = $queue_item;
            }
            return $queue;
        });
        if (!empty($routing_paths) && !$this->update_routing_rules()) {
            $this->log_activity(__('Aggiornamento incrementale in coda, ma .htaccess non aggiornato.', 'static-bridge'), implode(', ', array_slice($routing_paths, 0, 10)), true);
        }
        $this->schedule_incremental_worker_after_change();
        return $queued;
    }

    /**
     * The same routes in the site's other languages, after each one. A translation plugin serves /en/… (with its own
     * translated slug) next to every page: a refresh that rewrote only the original left the translations stale until
     * the next full export. TranslatePress is read directly; another plugin answers the filter
     * static_bridge_translated_urls( string[] $urls, string $url ). Each answer goes through the same checks as any
     * queued URL, so a route of another site is dropped.
     *
     * @param array $urls
     * @return string[]
     */
    private function with_translated_urls($urls)
    {
        $out = array();
        foreach ($urls as $url) {
            if (is_string($url)) {
                $out[$url] = $url;
            }
        }
        $translatepress = $this->translatepress_languages();
        foreach (array_values($out) as $url) {
            $variants = array();
            foreach ($translatepress['languages'] as $language) {
                $variant = $translatepress['converter']->get_url_for_language($language, $url, '');
                if (is_string($variant) && '' !== $variant) {
                    $variants[] = $variant;
                }
            }
            $variants = apply_filters('static_bridge_translated_urls', $variants, $url);
            foreach (is_array($variants) ? array_slice(array_values($variants), 0, self::MAX_TRANSLATED_URLS) : array() as $variant) {
                if (is_string($variant)) {
                    $out[$variant] = $variant;
                }
            }
        }
        return array_values($out);
    }

    /**
     * TranslatePress's URL converter and the languages it publishes besides the default one, or none.
     *
     * @return array{converter: object|null, languages: string[]}
     */
    private function translatepress_languages()
    {
        $none = array('converter' => null, 'languages' => array());
        if (!class_exists('TRP_Translate_Press') || !method_exists('TRP_Translate_Press', 'get_trp_instance')) {
            return $none;
        }
        $trp = TRP_Translate_Press::get_trp_instance();
        if (!is_object($trp) || !method_exists($trp, 'get_component')) {
            return $none;
        }
        $converter = $trp->get_component('url_converter');
        $settings = $trp->get_component('settings');
        if (!is_object($converter) || !method_exists($converter, 'get_url_for_language') || !is_object($settings) || !method_exists($settings, 'get_settings')) {
            return $none;
        }
        $values = $settings->get_settings();
        $published = is_array($values) && isset($values['publish-languages']) && is_array($values['publish-languages']) ? $values['publish-languages'] : array();
        $default = is_array($values) && isset($values['default-language']) ? (string) $values['default-language'] : '';
        $languages = array();
        foreach ($published as $language) {
            if (is_string($language) && $language !== $default && preg_match('/^[A-Za-z]{2,3}(?:_[A-Za-z0-9]{2,8})*$/', $language)) {
                $languages[] = $language;
            }
        }
        return array('converter' => $converter, 'languages' => array_slice($languages, 0, self::MAX_TRANSLATED_URLS));
    }

    /**
     * The queue as the database has it now, never as this request first read it. WP keeps every option a request
     * reads in the request's own cache, and the worker runs for up to 45 seconds: until 2.5.0 a route queued
     * meanwhile by another request (an editor saving) was overwritten by the worker's next write of its old copy,
     * and never reached the static copy. Seen on a real site on 15 November 2026.
     */
    private function incremental_queue()
    {
        $this->forget_cached_option(self::INCREMENTAL_QUEUE_OPTION);
        $queue = get_option(self::INCREMENTAL_QUEUE_OPTION, array());
        return is_array($queue) ? $queue : array();
    }

    /**
     * One change of the queue, atomic across requests (2.5.0): a short row lock, the queue read from the database,
     * the change, the write. $change receives the queue and returns the new one, or null to leave it as it is.
     * Returns the queue after the change. Every write of the queue goes through here: reading it fresh is not
     * enough, two requests that read the same queue each write back their own and one of the two changes is lost.
     * A change inside a change (same request) runs under the outer lock. $change must only work on the array: the
     * routes are worked out before, so the lock is held for a few milliseconds. When it cannot be taken in about
     * two seconds the change is made anyway, on a fresh read: better a narrow race than a route never queued.
     */
    private function change_incremental_queue($change)
    {
        $token = false;
        $outer = !$this->changing_incremental_queue;
        if ($outer) {
            for ($attempt = 0; $attempt < self::INCREMENTAL_QUEUE_WRITE_LOCK_ATTEMPTS; $attempt++) {
                $token = $this->acquire_row_lock(self::INCREMENTAL_QUEUE_WRITE_LOCK_OPTION, self::INCREMENTAL_QUEUE_WRITE_LOCK_TTL);
                if (false !== $token) {
                    break;
                }
                usleep(50000);
            }
            $this->changing_incremental_queue = true;
        }
        try {
            $queue = $this->incremental_queue();
            $changed = call_user_func($change, $queue);
            if (is_array($changed)) {
                update_option(self::INCREMENTAL_QUEUE_OPTION, $changed, false);
                $queue = $changed;
            }
            return $queue;
        } finally {
            if ($outer) {
                $this->changing_incremental_queue = false;
                if (false !== $token) {
                    $this->release_row_lock(self::INCREMENTAL_QUEUE_WRITE_LOCK_OPTION, $token);
                }
            }
        }
    }

    private function schedule_incremental_worker($delay, $debounce = false)
    {
        if ($debounce) {
            wp_clear_scheduled_hook('static_bridge_process_incremental_queue');
        } elseif (wp_next_scheduled('static_bridge_process_incremental_queue')) {
            return;
        }
        wp_schedule_single_event(time() + absint($delay), 'static_bridge_process_incremental_queue');
    }

    private function retry_incremental_item($key, $item, $message)
    {
        if (!empty($item['manual_push_token'])) {
            $this->set_post_push_status($item['manual_push_token'], 'retrying', array('last_error' => sanitize_text_field($message)));
        }
        if (isset($item['_queue_backend']) && 'dependency-index' === $item['_queue_backend']) {
            $release_id = isset($item['_release_id']) ? (string) $item['_release_id'] : basename($this->current_release());
            $index = new Static_Bridge_Dependency_Index();
            $attempts = isset($item['attempts']) ? (int) $item['attempts'] + 1 : 1;
            $delay = min(3600, 15 * (2 ** min(6, $attempts)));
            $retried = $index->retry_queue_item($release_id, $item, $message, $delay);
            if (!$retried) {
                $index->mark_failed($release_id);
                $this->log_activity(__('Retry della coda V2 non registrato.', 'static-bridge'), $item['path'] . ' — ' . sanitize_text_field($message), true);
                return;
            }
            if (1 === $attempts || 3 === $attempts || 7 === $attempts) {
                $this->log_activity(__('Aggiornamento V2 non riuscito; verrà riprovato.', 'static-bridge'), $item['path'] . ' — ' . sanitize_text_field($message), true);
            }
            if (self::INCREMENTAL_FAILURE_NOTICE_ATTEMPT === $attempts) {
                $this->notify_update_failure('incremental', (string) $item['path'] . ' — ' . (string) $message);
            }
            $this->schedule_incremental_worker($delay);
            return;
        }
        $attempts = 0;
        $last_error = sanitize_text_field($message);
        $this->change_incremental_queue(function ($queue) use ($key, $item, $last_error, &$attempts) {
            if (!isset($queue[$key]) || !is_array($queue[$key]) || $queue[$key]['token'] !== $item['token']) {
                return null;
            }
            $retried = $queue[$key];
            $retried['attempts'] = isset($item['attempts']) ? (int) $item['attempts'] + 1 : 1;
            $retried['last_error'] = $last_error;
            // To the back of the queue: the worker takes the first item, so a route that keeps failing must not
            // hold back the routes queued after it.
            unset($queue[$key]);
            $queue[$key] = $retried;
            $attempts = $retried['attempts'];
            return $queue;
        });
        if (0 === $attempts) {
            // Queued again meanwhile by another request (a new token), or gone: nothing of this attempt to keep.
            $this->schedule_incremental_worker(1);
            return;
        }
        if (1 === $attempts || 3 === $attempts || 7 === $attempts) {
            $this->log_activity(__('Aggiornamento incrementale non riuscito; verrà riprovato.', 'static-bridge'), $item['path'] . ' — ' . $message, true);
        }
        $delay = min(3600, 15 * (2 ** min(6, $attempts)));
        if (!empty($item['manual_push_token'])) {
            // A push does not wait behind the end of a wait (2.5.0): its retry keeps its own delay.
            $this->schedule_incremental_worker_within($delay);
            return;
        }
        if (self::INCREMENTAL_FAILURE_NOTICE_ATTEMPT === $attempts) {
            // An automatic update failing for about half an hour does not fix itself (2.5.0).
            $this->notify_update_failure('incremental', (string) $item['path'] . ' — ' . (string) $message);
        }
        $this->schedule_incremental_worker($delay);
    }

    /**
     * Schedules the worker after an automatic change (a save, a term, a menu, static_bridge_queue_paths…): it
     * starts now, and with «Attesa dopo l'ultima modifica» the change also moves the wait forward (2.5.0).
     */
    private function schedule_incremental_worker_after_change()
    {
        $this->note_incremental_change();
        $this->schedule_incremental_worker(0, true);
    }

    /** Makes sure the worker runs within $delay seconds: an event planned later (the end of a wait) moves earlier. */
    private function schedule_incremental_worker_within($delay)
    {
        $next = wp_next_scheduled('static_bridge_process_incremental_queue');
        if (false !== $next && (int) $next <= time() + absint($delay)) {
            return;
        }
        $this->schedule_incremental_worker($delay, true);
    }

    /** Minutes of «Attesa dopo l'ultima modifica»: an integer in 0..120; text and negative numbers are 0 (off). */
    private function sanitize_incremental_wait($value)
    {
        if (is_string($value)) {
            $value = trim($value);
        }
        if (!is_numeric($value)) {
            return 0;
        }
        return max(0, min(self::INCREMENTAL_WAIT_MAX_MINUTES, (int) $value));
    }

    /** The wait in seconds, read from the stored settings without the filters of settings(). */
    private function incremental_wait_seconds()
    {
        $settings = get_option(self::SETTINGS_OPTION, array());
        return 60 * $this->sanitize_incremental_wait(is_array($settings) && isset($settings['incremental_wait']) ? $settings['incremental_wait'] : 0);
    }

    /**
     * Seconds the automatic updates still wait: until the last change + the wait, never past the first change
     * still waiting + twice the wait, so a site edited all the time still publishes. 0 means they run now.
     */
    private function incremental_wait_remaining()
    {
        $wait = $this->incremental_wait_seconds();
        $state = get_option(self::INCREMENTAL_WAIT_OPTION, false);
        if ($wait < 1 || !is_array($state) || !isset($state['first'], $state['last'])) {
            return 0;
        }
        $now = time();
        // A time in the future (a clock moved back) counts as now: the wait never grows past twice its length.
        $first = min($now, (int) $state['first']);
        $last = min($now, max($first, (int) $state['last']));
        return max(0, min($last + $wait, $first + 2 * $wait) - $now);
    }

    /** Records an automatic change for the wait: the first one starts it, each one moves it forward. */
    private function note_incremental_change()
    {
        // Routes the worker or a push queue (a redirect target, a fallback refresh) are not new edits; a menu or
        // widget refresh (2.5.0) has already waited at least as long.
        if ($this->processing_incremental_items || $this->queue_after_own_wait || $this->incremental_wait_seconds() < 1) {
            return;
        }
        $now = time();
        $state = get_option(self::INCREMENTAL_WAIT_OPTION, false);
        $first = is_array($state) && isset($state['first']) && (int) $state['first'] > 0 && (int) $state['first'] <= $now
            ? (int) $state['first']
            : $now;
        update_option(self::INCREMENTAL_WAIT_OPTION, array('first' => $first, 'last' => $now), false);
    }

    /** Ends the wait: the queue has nothing new left, or an administrator asked for the pages now. */
    private function end_incremental_wait()
    {
        if (false !== get_option(self::INCREMENTAL_WAIT_OPTION, false)) {
            delete_option(self::INCREMENTAL_WAIT_OPTION);
        }
    }

    private function first_manual_push_key($queue)
    {
        foreach ((array) $queue as $key => $item) {
            if (is_array($item) && !empty($item['manual_push_token']) && '' !== $this->sanitize_post_push_token($item['manual_push_token'])) {
                return $key;
            }
        }
        return null;
    }

    private function incremental_queue_has_manual_push()
    {
        return null !== $this->first_manual_push_key($this->incremental_queue());
    }

    /** Whether the queue holds a route not yet tried: the routes that failed wait for their retry anyway. */
    private function incremental_queue_has_fresh_item($queue)
    {
        foreach ((array) $queue as $item) {
            if (is_array($item) && empty($item['attempts'])) {
                return true;
            }
        }
        return false;
    }

    private function complete_incremental_item($key, $item)
    {
        if (!empty($item['url'])) {
            $this->purge_other_page_caches((string) $item['url']);
            // The public action for the other caches in front of the site (2.5.0), once the route is final.
            $this->announce_route_updated((string) $item['url']);
            update_option(self::LAST_PAGE_UPDATE_OPTION, array('path' => $this->normalize_route_path((string) $item['url']), 'at' => time()), false);
        }
        if (isset($item['_queue_backend']) && 'dependency-index' === $item['_queue_backend']) {
            $release_id = isset($item['_release_id']) ? (string) $item['_release_id'] : basename($this->current_release());
            if (!(new Static_Bridge_Dependency_Index())->complete_queue_item($release_id, $item)) {
                $this->log_activity(__('Aggiornamento V2 completato ma stato coda non aggiornato.', 'static-bridge'), $item['path'], true);
            }
            return;
        }
        // Only the item this run took: a route queued again meanwhile has a new token and stays for the next run.
        $this->change_incremental_queue(function ($queue) use ($key, $item) {
            if (!isset($queue[$key]) || !is_array($queue[$key]) || $queue[$key]['token'] !== $item['token']) {
                return null;
            }
            unset($queue[$key]);
            return $queue;
        });
    }

    /**
     * $identical (2.5.0, «Non riscrivere le pagine identiche»): null with the option off. true: a page whose final
     * HTML and .gz are already the ones in the release is not written again and comes back with 'unchanged'. Either
     * way, with the option on, a page about to be written is first marked unsettled (mark_route_unsettled()).
     */
    private function write_incremental_page($release, $url, $body, $identical = null)
    {
        // 2.5.0: no relative-date marker is ever written, whatever path the HTML took.
        $body = $this->strip_relative_date_markers($this->rewrite_internal_origins_as_root_relative((string) $body));
        $root = realpath($release);
        $relative = $this->relative_html_path($url);
        if (!$root || is_wp_error($relative) || !is_string($body) || '' === trim($body)) {
            return new WP_Error('static_bridge_incremental_path', __('Release, percorso o HTML non validi per la scrittura incrementale.', 'static-bridge'));
        }
        if ($this->release_uses_header_fragments($root)) {
            $body = $this->fragment_elementor_header($root, $url, $body);
            if (is_wp_error($body)) {
                return $body;
            }
        } elseif (!empty(get_option('static_bridge_ssi_guard_enabled'))
            && Static_Bridge_Header_Fragments::contains_ssi_directive($body)) {
            return new WP_Error('static_bridge_ssi_source', __('L’HTML contiene una direttiva SSI preesistente; la route non è stata sostituita.', 'static-bridge'));
        }
        $destination = trailingslashit($root) . $relative;
        if (true === $identical && $this->incremental_copy_identical($root, $destination, $body)) {
            return array('created' => false, 'file' => $destination, 'unchanged' => true);
        }
        $minimum_free_space = $this->minimum_free_disk_space_bytes();
        if (!$this->has_sufficient_export_disk_space($root, $minimum_free_space, strlen($body))) {
            return new WP_Error('static_bridge_disk_space', $this->insufficient_disk_space_message($minimum_free_space));
        }
        if (!wp_mkdir_p(dirname($destination))) {
            return new WP_Error('static_bridge_incremental_directory', __('Impossibile creare la cartella della pagina statica.', 'static-bridge'));
        }
        $parent = realpath(dirname($destination));
        if (!$parent || (0 !== strpos(trailingslashit($parent), trailingslashit($root)) && $parent !== $root)) {
            return new WP_Error('static_bridge_incremental_escape', __('Il percorso della pagina esce dalla release corrente.', 'static-bridge'));
        }
        $created = !file_exists($destination) && !is_link($destination);
        $temporary = $destination . '.tmp-' . strtolower(wp_generate_password(8, false, false));
        if (file_exists($temporary) || is_link($temporary)) {
            return new WP_Error('static_bridge_incremental_write', __('Scrittura temporanea della pagina non riuscita.', 'static-bridge'));
        }
        // Marked before the file changes: a write that never reaches its edge purge (a retry, a killed request) keeps
        // the route from being skipped later.
        if (null !== $identical && !$this->mark_route_unsettled($root, $this->normalize_route_path($url))) {
            return new WP_Error('static_bridge_incremental_write', __('Lo stato delle pagine da svuotare dalla CDN non si può salvare; la pagina non è stata sostituita.', 'static-bridge'));
        }
        $written = @file_put_contents($temporary, $body, LOCK_EX);
        if (strlen($body) !== $written) {
            if (file_exists($temporary) || is_link($temporary)) {
                @unlink($temporary);
            }
            return new WP_Error('static_bridge_incremental_write', __('Scrittura temporanea della pagina non riuscita.', 'static-bridge'));
        }
        @chmod($temporary, 0644);
        if (!$this->drop_precompressed_copy($destination)) {
            @unlink($temporary);
            return new WP_Error('static_bridge_incremental_publish', __('La copia compressa della pagina non si può togliere; la pagina non è stata sostituita.', 'static-bridge'));
        }
        if (!@rename($temporary, $destination)) {
            @unlink($temporary);
            return new WP_Error('static_bridge_incremental_publish', __('Sostituzione atomica della pagina non riuscita.', 'static-bridge'));
        }
        $this->write_precompressed_copy($destination, $body, $this->release_uses_header_fragments($root));
        return array('created' => $created, 'file' => $destination);
    }

    /**
     * Whether the page in the release is byte for byte $body, and its .gz is what write_precompressed_copy() would
     * leave now: the decompressed body with precompressed pages on, no .gz at all with them off. Anything that
     * cannot be read or checked is not identical, so the page is written as before.
     */
    private function incremental_copy_identical($root, $destination, $body)
    {
        clearstatcache(true, $destination);
        if (!is_file($destination) || is_link($destination) || filesize($destination) !== strlen($body)
            || strlen($body) > self::MAX_HTML_PAGE_SIZE) {
            return false;
        }
        $parent = realpath(dirname($destination));
        if (!$parent || (0 !== strpos(trailingslashit($parent), trailingslashit($root)) && $parent !== $root)) {
            return false;
        }
        $current = @file_get_contents($destination);
        if (!is_string($current) || $current !== $body) {
            return false;
        }
        $compressed = $destination . '.gz';
        clearstatcache(true, $compressed);
        $has_compressed = file_exists($compressed) || is_link($compressed);
        if (!$this->precompressed_pages_enabled($this->release_uses_header_fragments($root))) {
            return !$has_compressed;
        }
        if (!$has_compressed || is_link($compressed) || !is_file($compressed) || filesize($compressed) > self::MAX_HTML_PAGE_SIZE
            || !function_exists('gzdecode')) {
            return false;
        }
        $decoded = @gzdecode((string) @file_get_contents($compressed));
        return is_string($decoded) && $decoded === $body;
    }

    private function skip_identical_pages_enabled()
    {
        return !empty($this->settings()['skip_identical_pages']);
    }

    /**
     * A route may be skipped only when the full release in use was published with the option on (its export purged
     * the whole edge) and every write of the route since then reached its edge purge.
     */
    private function route_settled($release, $path)
    {
        $state = get_option(self::UNSETTLED_ROUTES_OPTION, array());
        return is_array($state) && isset($state['release']) && is_string($state['release']) && '' !== $state['release']
            && basename((string) $release) === $state['release'] && empty($state['overflow'])
            && isset($state['routes']) && is_array($state['routes']) && !isset($state['routes'][sha1((string) $path)]);
    }

    /** Before a write with the option on. False only when the state could not be saved: then nothing is written. */
    private function mark_route_unsettled($release, $path)
    {
        $state = get_option(self::UNSETTLED_ROUTES_OPTION, array());
        $state = is_array($state) ? $state : array();
        $routes = isset($state['routes']) && is_array($state['routes']) ? $state['routes'] : array();
        $key = sha1((string) $path);
        if (isset($routes[$key]) || !empty($state['overflow'])) {
            return true;
        }
        if (count($routes) >= self::MAX_UNSETTLED_ROUTES) {
            // Too many open writes to list: no route is skipped until the next full export.
            $state['overflow'] = 1;
        } else {
            $routes[$key] = time();
        }
        $state['routes'] = $routes;
        return update_option(self::UNSETTLED_ROUTES_OPTION, $state, false);
    }

    /** After the edge purge of a written route is queued. A failed save only keeps the route unsettled. */
    private function settle_route($path)
    {
        $state = get_option(self::UNSETTLED_ROUTES_OPTION, array());
        $key = sha1((string) $path);
        if (is_array($state) && isset($state['routes']) && is_array($state['routes']) && isset($state['routes'][$key])) {
            unset($state['routes'][$key]);
            update_option(self::UNSETTLED_ROUTES_OPTION, $state, false);
        }
    }

    /**
     * A full release published: with the option on, every route starts settled from that release (the export wrote
     * every page and purged the whole edge); with it off the state goes, so turning it on again waits for an export.
     */
    private function reset_unsettled_routes($release_id)
    {
        if ($this->skip_identical_pages_enabled() && is_string($release_id) && '' !== $release_id) {
            update_option(self::UNSETTLED_ROUTES_OPTION, array('release' => $release_id, 'routes' => array(), 'overflow' => 0), false);
        } else {
            delete_option(self::UNSETTLED_ROUTES_OPTION);
        }
    }

    private function remove_incremental_page($release, $url)
    {
        $root = realpath($release);
        $relative = $this->relative_html_path($url);
        if (!$root || is_wp_error($relative)) {
            return new WP_Error('static_bridge_incremental_delete_path', __('Release o percorso non validi per la rimozione incrementale.', 'static-bridge'));
        }
        $destination = trailingslashit($root) . $relative;
        $parent_path = dirname($destination);
        while ($root !== $parent_path && !file_exists($parent_path) && !is_link($parent_path)) {
            $next_parent = dirname($parent_path);
            if ($next_parent === $parent_path) {
                break;
            }
            $parent_path = $next_parent;
        }
        $parent = realpath($parent_path);
        if (!$parent || (0 !== strpos(trailingslashit($parent), trailingslashit($root)) && $parent !== $root)) {
            return new WP_Error('static_bridge_incremental_delete_escape', __('Il percorso da rimuovere esce dalla release corrente.', 'static-bridge'));
        }
        if (!is_file($destination) && !is_link($destination)) {
            $this->remove_dependency_index_route($release, $url);
            return array('deleted' => false);
        }
        if (!$this->drop_precompressed_copy($destination) || !@unlink($destination)) {
            return new WP_Error('static_bridge_incremental_delete', __('Rimozione della pagina statica non riuscita.', 'static-bridge'));
        }
        $this->remove_dependency_index_route($release, $url);
        return array('deleted' => true);
    }

    private function remove_dependency_index_route($release, $url)
    {
        if (empty($this->settings()['selective_shared_updates'])) {
            return;
        }
        $release_id = basename((string) $release);
        $index = new Static_Bridge_Dependency_Index();
        if ($index->is_ready($release_id) && !$index->remove_route($release_id, $this->normalize_route_path($url))) {
            $index->mark_failed($release_id);
            $this->log_activity(
                __('Indice V2 non aggiornato dopo la rimozione di una route.', 'static-bridge'),
                __('La route è stata rimossa dal file system; i prossimi aggiornamenti condivisi useranno il fallback completo.', 'static-bridge'),
                true
            );
        }
    }

    private function update_incremental_manifest($release, $page_delta = null)
    {
        $manifest_file = trailingslashit($release) . 'manifest.json';
        $manifest = is_readable($manifest_file) ? json_decode(file_get_contents($manifest_file), true) : null;
        if (!is_array($manifest)) {
            return false;
        }
        if (null === $page_delta) {
            $manifest['pages_saved'] = $this->count_html_files($release);
        } else {
            $manifest['pages_saved'] = max(0, (isset($manifest['pages_saved']) ? absint($manifest['pages_saved']) : 0) + (int) $page_delta);
        }
        $manifest['last_incremental_update_utc'] = gmdate('c');
        $manifest['incremental_updates'] = isset($manifest['incremental_updates']) ? absint($manifest['incremental_updates']) + 1 : 1;
        $temporary = $manifest_file . '.tmp-' . strtolower(wp_generate_password(8, false, false));
        $manifest_json = wp_json_encode($manifest, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES);
        if (!is_string($manifest_json) || file_exists($temporary) || is_link($temporary)
            || !$this->has_sufficient_export_disk_space(dirname($manifest_file), $this->minimum_free_disk_space_bytes(), strlen($manifest_json))) {
            return false;
        }
        $written = @file_put_contents($temporary, $manifest_json, LOCK_EX);
        if (strlen($manifest_json) !== $written) {
            if (file_exists($temporary) || is_link($temporary)) {
                @unlink($temporary);
            }
            return false;
        }
        @chmod($temporary, 0644);
        if (!@rename($temporary, $manifest_file)) {
            @unlink($temporary);
            return false;
        }
        return true;
    }

    private function archive_urls_for_post($post)
    {
        if (!$post instanceof WP_Post) {
            return array();
        }
        // Every list the post appears in, with all its pages: a new or removed post moves the whole list.
        // With "Archivi nell'export" off, page 1 of the post's own lists only, as up to 2.1.0.
        $full = !empty($this->settings()['export_archives']);
        $listed_types = $this->archive_post_types('front');
        $listed = in_array($post->post_type, $listed_types, true);
        $listed_pages = $listed ? $this->archive_page_count($this->published_post_count($listed_types)) : 1;
        $archives = array(array(home_url('/'), 'posts' === get_option('show_on_front') ? $listed_pages : 1));
        $posts_page_id = absint(get_option('page_for_posts'));
        if ($posts_page_id) {
            $archives[] = array(get_permalink($posts_page_id), $listed_pages);
        }
        // For `post` WordPress returns the home or the posts page, already above (and a static home has no /page/N/).
        $type_object = function_exists('get_post_type_object') ? get_post_type_object($post->post_type) : null;
        $archive_url = $type_object && !empty($type_object->has_archive) ? get_post_type_archive_link($post->post_type) : '';
        if ($archive_url) {
            $archives[] = array($archive_url, $this->archive_page_count($this->published_post_count(array($post->post_type)), array($post->post_type)));
        }
        $author_types = $this->archive_post_types('author');
        if (!empty($post->post_author) && in_array($post->post_type, $author_types, true)) {
            $author_posts = function_exists('count_user_posts') ? (int) count_user_posts((int) $post->post_author, $author_types, true) : 0;
            $archives[] = array(get_author_posts_url((int) $post->post_author), $this->archive_page_count($author_posts));
        }
        $taxonomies = get_object_taxonomies($post->post_type, 'names');
        foreach ($taxonomies as $taxonomy) {
            $taxonomy_object = get_taxonomy($taxonomy);
            if (!$taxonomy_object || empty($taxonomy_object->public)) {
                continue;
            }
            $terms = get_the_terms($post->ID, $taxonomy);
            if (!is_array($terms)) {
                continue;
            }
            // A parent category lists its children's posts too.
            $listed_terms = array();
            foreach ($terms as $term) {
                $listed_terms[(int) $term->term_id] = $term;
                if ($full && !empty($taxonomy_object->hierarchical) && function_exists('get_ancestors')) {
                    foreach (get_ancestors((int) $term->term_id, $taxonomy, 'taxonomy') as $ancestor_id) {
                        if (!isset($listed_terms[(int) $ancestor_id])) {
                            $listed_terms[(int) $ancestor_id] = get_term((int) $ancestor_id, $taxonomy);
                        }
                    }
                }
            }
            foreach ($listed_terms as $term) {
                if (!is_object($term) || is_wp_error($term)) {
                    continue;
                }
                $term_url = get_term_link($term, $taxonomy);
                if (!is_wp_error($term_url)) {
                    $archives[] = array($term_url, $this->term_archive_pages((int) $term->term_id, $taxonomy, isset($term->count) ? (int) $term->count : 0));
                }
            }
        }
        $date_types = $this->archive_post_types('date');
        if ($full && in_array($post->post_type, $date_types, true) && function_exists('get_day_link')
            && isset($post->post_date) && preg_match('/^(\d{4})-(\d{2})-(\d{2})/', (string) $post->post_date, $date)) {
            list(, $year, $month, $day) = array_map('intval', $date);
            $archives[] = array(get_year_link($year), $this->archive_page_count($this->date_archive_post_count($date_types, $year)));
            $archives[] = array(get_month_link($year, $month), $this->archive_page_count($this->date_archive_post_count($date_types, $year, $month)));
            $archives[] = array(get_day_link($year, $month, $day), $this->archive_page_count($this->date_archive_post_count($date_types, $year, $month, $day)));
        }
        // A language plugin adds the same lists in the post's language (/en/, /en/category/…). It can only add:
        // routes outside this site are dropped below, and at most MAX_ARCHIVE_URLS are taken.
        $added = apply_filters('static_bridge_archive_urls_for_post', array(), $post);
        if (is_array($added)) {
            foreach (array_slice(array_values(array_filter($added, 'is_string')), 0, self::MAX_ARCHIVE_URLS) as $added_url) {
                $archives[] = array($added_url, 1);
            }
        }
        // Pages first by number (all page 1s, then all page 2s…), so the cap keeps the most visible ones;
        // a page the release still has past the new last one is queued too, and removed when it is gone.
        $by_page = array();
        foreach ($archives as $archive) {
            if (!$full) {
                $archive[1] = 1;
            }
            $routes = array_merge($this->archive_page_urls(array($archive)), $full ? $this->release_archive_pages_beyond($archive[0], (int) $archive[1]) : array());
            foreach ($routes as $position => $url) {
                $by_page[$position][] = $url;
            }
        }
        ksort($by_page);
        $normalized = array();
        foreach ($by_page as $urls) {
            foreach ($urls as $url) {
                $normalized[$url] = $url;
            }
        }
        return array_slice(array_values($normalized), 0, self::MAX_INCREMENTAL_ARCHIVE_URLS);
    }

    private function discover_query_page_urls()
    {
        $cached = get_transient('static_bridge_incremental_query_pages');
        if (is_array($cached)) {
            return $cached;
        }
        $urls = array();
        $post_types = $this->exportable_public_post_types();
        $posts = get_posts(array(
            'post_type' => array_values($post_types),
            'post_status' => 'publish',
            'posts_per_page' => 500,
            'orderby' => 'modified',
            'order' => 'DESC',
            'no_found_rows' => true,
        ));
        $limit = max(1, min(500, (int) apply_filters('static_bridge_query_page_limit', 30)));
        foreach ($posts as $post) {
            if (!$this->post_has_query_loop($post)) {
                continue;
            }
            $url = $this->normalize_public_url(get_permalink($post));
            if ($url) {
                $urls[$url] = $url;
            }
            if (count($urls) >= $limit) {
                if (false === get_transient('static_bridge_query_page_limit_logged')) {
                    set_transient('static_bridge_query_page_limit_logged', 1, DAY_IN_SECONDS);
                    $this->log_activity(
                    __('Limite delle pagine-lista raggiunto.', 'static-bridge'),
                        sprintf(/* translators: %s: number of list pages */ __('Ogni modifica aggiorna solo le %s pagine con un elenco di contenuti modificate più di recente; le altre si aggiornano con l’export completo. Il limite si cambia con il filtro static_bridge_query_page_limit.', 'static-bridge'), number_format_i18n($limit))
                    );
                }
                break;
            }
        }
        $urls = array_values($urls);
        set_transient('static_bridge_incremental_query_pages', $urls, 5 * MINUTE_IN_SECONDS);
        return $urls;
    }

    private function post_has_query_loop($post)
    {
        if (!$post instanceof WP_Post) {
            return false;
        }
        $content = strtolower((string) $post->post_content);
        // Core blocks are saved without their namespace (<!-- wp:query -->, <!-- wp:latest-posts /-->).
        if (preg_match('~<!--\s*wp:(?:(?:core/)?(?:query|latest-posts|archives|categories|calendar)(?=\s|/?-->)|xb/loop|etch/loop|kadence/[a-z0-9_-]*(?:post|query)[a-z0-9_-]*)\b~i', $content)) {
            return true;
        }
        // WooCommerce blocks and shortcodes that show products with their price and stock (product collection,
        // single product, handpicked, best sellers…): a product change refreshes the page (2.2.13).
        if ($this->woocommerce_is_active() && preg_match('~<!--\s*wp:woocommerce/[a-z0-9-]*product[a-z0-9-]*\b|\[(?:products|product|product_page|product_category|sale_products|recent_products|featured_products|best_selling_products|top_rated_products|product_attribute|add_to_cart)[\s\]]~i', $content)) {
            return true;
        }
        // Builders whose lists are not visible in the post's own markup (a loop inside a component, data
        // read without a loop) answer for their pages.
        if (true === apply_filters('static_bridge_post_has_query_loop', false, $post)) {
            return true;
        }
        $bricks_content = get_post_meta($post->ID, '_bricks_page_content_2', true);
        if (empty($bricks_content)) {
            $bricks_content = get_post_meta($post->ID, '_bricks_page_content', true);
        }
        if (is_string($bricks_content)) {
            $decoded = json_decode($bricks_content, true);
            if (is_array($decoded)) {
                $bricks_content = $decoded;
            }
        }
        return $this->bricks_content_has_query($bricks_content);
    }

    private function bricks_content_has_query($value)
    {
        if (!is_array($value)) {
            return false;
        }
        if (isset($value['name']) && in_array(sanitize_key($value['name']), array('posts', 'query', 'related_posts'), true)) {
            return true;
        }
        if (isset($value['settings']) && is_array($value['settings'])) {
            foreach (array('hasLoop', 'useQuery', 'query') as $key) {
                if (!empty($value['settings'][$key])) {
                    return true;
                }
            }
        }
        foreach ($value as $child) {
            if (is_array($child) && $this->bricks_content_has_query($child)) {
                return true;
            }
        }
        return false;
    }

    private function page_builders($post)
    {
        if (!$post instanceof WP_Post) {
            return array();
        }
        $builders = array();
        foreach (array('_bricks_page_content_2', '_bricks_page_content') as $meta_key) {
            if (get_post_meta($post->ID, $meta_key, true)) {
                $builders[] = 'bricks';
                break;
            }
        }
        if (preg_match('~<!--\s*wp:kadence/[a-z0-9_-]+~i', (string) $post->post_content)) {
            $builders[] = 'kadence-blocks';
        }
        if (function_exists('wp_get_theme') && 'kadence' === wp_get_theme()->get_template()) {
            $builders[] = 'kadence-theme';
        }
        return array_values(array_unique($builders));
    }

    private function builder_label($builder)
    {
        $labels = array(
            'bricks' => __('Bricks', 'static-bridge'),
            'kadence-blocks' => __('Kadence Blocks', 'static-bridge'),
            'kadence-theme' => __('Kadence Theme', 'static-bridge'),
        );
        return isset($labels[$builder]) ? $labels[$builder] : sanitize_text_field($builder);
    }

    private function discover_builder_pages()
    {
        $pages = array();
        $post_types = $this->exportable_public_post_types();
        $posts = get_posts(array(
            'post_type' => array_values($post_types),
            'post_status' => 'publish',
            'posts_per_page' => 500,
            'orderby' => 'modified',
            'order' => 'DESC',
            'no_found_rows' => true,
        ));
        foreach ($posts as $post) {
            $builders = $this->page_builders($post);
            if (empty($builders)) {
                continue;
            }
            $url = $this->normalize_public_url(get_permalink($post));
            if (!$url) {
                continue;
            }
            $path = $this->normalize_route_path($url);
            $pages[$path] = array(
                'path' => $path,
                'builders' => $builders,
                'title' => get_the_title($post),
            );
            if (count($pages) >= 8) {
                break;
            }
        }
        return array_values($pages);
    }

    public function ajax_start()
    {
        $this->verify_export_ajax_request();
        $job = $this->start_export('admin');
        if (is_wp_error($job)) {
            $error_data = $job->get_error_data();
            wp_send_json_error(array('message' => $job->get_error_message()), is_array($error_data) && isset($error_data['status']) ? (int) $error_data['status'] : 500);
        }
        wp_send_json_success($this->job_response($job));
    }

    /**
     * Starts a full export (2.5.0: out of ajax_start(), for the schedule and WP-CLI too). No capability or nonce
     * here: the caller checks them (ajax_start(), handle_after_update()), or is WP-Cron or the shell. $origin is
     * 'admin', 'schedule', 'cli', 'notice' or 'update' and goes in the job as started_by. $background false leaves the background requests unarmed: the
     * synchronous WP-CLI export runs the steps itself. Returns the job, or a WP_Error whose data is
     * array('status' => HTTP code), with the same messages, codes and Attività rows as ajax_start() before 2.5.0.
     */
    private function start_export($origin, $background = true)
    {
        $origin = in_array($origin, array('admin', 'schedule', 'cli', 'notice', 'update'), true) ? $origin : 'admin';
        if ($this->job_is_running()) {
            return new WP_Error('static_bridge_export_running', __('È già in corso un’esportazione.', 'static-bridge'), array('status' => 409));
        }
        $previous_job = get_option(self::JOB_OPTION, array());
        if (is_array($previous_job) && isset($previous_job['status']) && 'paused' === $previous_job['status']) {
            return new WP_Error('static_bridge_export_paused', __('Esiste un’esportazione in pausa. Riprendila oppure annullala prima di avviare una nuova release.', 'static-bridge'), array('status' => 409));
        }
        if (is_array($previous_job) && isset($previous_job['status']) && 'running' === $previous_job['status']) {
            $this->close_incomplete_export_job($previous_job);
        }

        $shared_settings = $this->settings();
        if (!empty($shared_settings['shared_header_fragments'])) {
            $current_release = $this->current_release();
            $prepared_release = get_option('static_bridge_ssi_safe_release', '');
            if (!$current_release || !is_string($prepared_release) || basename($current_release) !== $prepared_release
                || !$this->verify_nginx_ssi_runtime($current_release)) {
                $message = __('Export SSI fermato in sicurezza: prima prepara la release attuale, installa e ricarica il blocco Nginx generato, poi ripeti il test. Nessuna nuova release è stata pubblicata.', 'static-bridge');
                $this->log_activity(__('Verifica runtime Nginx SSI non superata.', 'static-bridge'), $message, true);
                return new WP_Error('static_bridge_export_ssi_unsafe', $message, array('status' => 409));
            }
            update_option('static_bridge_ssi_last_probe', array('release' => basename($current_release), 'time' => time()), false);
        }

        $queue = $this->export_queue();
        if (!$queue->install()) {
            $message = __('Impossibile predisporre la coda indicizzata nel database. Nessuna release è stata creata.', 'static-bridge');
            $this->log_activity(__('Avvio esportazione non riuscito.', 'static-bridge'), $message, true);
            return new WP_Error('static_bridge_export_queue_unavailable', $message, array('status' => 500));
        }

        $release_id = gmdate('Ymd\THis\Z') . '-' . strtolower(wp_generate_password(5, false, false));
        $random_id = sha1(uniqid('', true));
        $job_id = function_exists('wp_generate_uuid4')
            ? wp_generate_uuid4()
            : substr($random_id, 0, 8) . '-' . substr($random_id, 8, 4) . '-4' . substr($random_id, 13, 3) . '-a' . substr($random_id, 17, 3) . '-' . substr($random_id, 20, 12);
        $release_root = $this->safe_release_root(true);
        if ('' === $release_root) {
            return new WP_Error('static_bridge_export_release_root', __('La cartella delle release non è sicura o non è scrivibile.', 'static-bridge'), array('status' => 500));
        }
        $stage = trailingslashit($release_root) . $release_id;
        if (file_exists($stage) || is_link($stage)) {
            return new WP_Error('static_bridge_export_stage_exists', __('La cartella generata per questa esportazione esiste già.', 'static-bridge'), array('status' => 409));
        }
        if (!wp_mkdir_p($stage)) {
            return new WP_Error('static_bridge_export_stage_unwritable', __('Non è possibile creare la cartella di esportazione.', 'static-bridge'), array('status' => 500));
        }

        $home_url = $this->normalize_public_url(home_url('/'));
        $initial_urls = $home_url ? array($home_url) : array();
        $queued = $queue->enqueue_batch($job_id, $initial_urls);
        if (false === $queued) {
            $message = __('Impossibile inizializzare la coda URL dell’esportazione.', 'static-bridge');
            $this->log_activity(__('Avvio esportazione non riuscito.', 'static-bridge'), $message, true);
            return new WP_Error('static_bridge_export_queue_insert', $message, array('status' => 500));
        }

        $dependency_index_active = false;
        if (!empty($this->settings()['selective_shared_updates'])) {
            $dependency_index_active = (new Static_Bridge_Dependency_Index())->begin_release($release_id);
            if (!$dependency_index_active) {
                $this->log_activity(
                    __('Export avviato senza indice V2.', 'static-bridge'),
                    __('La tabella InnoDB dell’indice non è disponibile; questa release resterà valida ma userà il refresh prudenziale dei componenti condivisi.', 'static-bridge'),
                    true
                );
            }
        }

        $header_fragments_active = !empty($shared_settings['shared_header_fragments']);
        if ($header_fragments_active && (!$dependency_index_active
            || !(new Static_Bridge_Header_Fragment_Index())->begin_release($release_id))) {
            $queue->delete_job($job_id);
            (new Static_Bridge_Header_Fragment_Index())->delete_release($release_id);
            if (is_dir($stage) && !is_link($stage)) {
                @rmdir($stage);
            }
            $message = __('Impossibile inizializzare l’indice InnoDB dei frammenti header; l’esportazione non è stata avviata.', 'static-bridge');
            $this->log_activity(__('Avvio export SSI non riuscito.', 'static-bridge'), $message, true);
            return new WP_Error('static_bridge_export_fragments_index', $message, array('status' => 500));
        }

        $job = array(
            'queue_version' => 1,
            'job_id' => $job_id,
            'status' => 'running',
            'release_id' => $release_id,
            'stage' => $stage,
            'portable_internal_urls' => 1,
            'discovery_source' => 'wordpress-keyset',
            'discovery_cursor' => 0,
            'discovery_complete' => false,
            'discovered' => (int) $queued,
            'started_at' => time(),
            'updated_at' => time(),
            'processed' => 0,
            'saved' => 0,
            'skipped' => 0,
            'route_errors' => 0,
            'pages_preserved' => 0,
            'dependency_index_active' => $dependency_index_active ? 1 : 0,
            'dependency_index_failed' => 0,
            'header_fragments_active' => $header_fragments_active ? 1 : 0,
            'guard_ssi_content' => !empty(get_option('static_bridge_ssi_guard_enabled')) || $this->nginx_ssi_enabled() ? 1 : 0,
            'issues' => array(),
            'limit_reached' => false,
            'current_url' => '',
            'started_by' => $origin,
        );
        update_option(self::JOB_OPTION, $job, false);
        $this->schedule_export_worker(5, true);
        if ($background) {
            $this->arm_export_continuation($job_id);
            $this->defer_export_continuation(true);
        }
        $origins = array(
            'admin' => __('scheda Genera', 'static-bridge'),
            'schedule' => __('export pianificato', 'static-bridge'),
            'cli' => 'WP-CLI',
            // 2.5.0: «Rigenera» in the notice after an update, and «Rigenera dopo gli aggiornamenti».
            'notice' => __('avviso dopo gli aggiornamenti', 'static-bridge'),
            'update' => __('rigenerazione dopo gli aggiornamenti', 'static-bridge'),
        );
        $this->log_activity(
            __('Esportazione avviata.', 'static-bridge'),
            __('Inventario WordPress per blocchi indicizzati; la scansione continua anche fuori dalla schermata admin tramite WP-Cron.', 'static-bridge')
                . ' ' . sprintf(/* translators: %s: who started the export (the Generate tab, the schedule, WP-CLI) */ __('Avviata da: %s.', 'static-bridge'), $origins[$origin])
        );
        return $job;
    }

    public function ajax_tick()
    {
        $this->verify_export_ajax_request();
        $job = get_option(self::JOB_OPTION, array());
        if (is_array($job) && !empty($job['queue_version'])) {
            $job = $this->run_export_queue_step();
            // Keeps a background request alive, so closing this tab does not stop the export.
            $this->defer_export_continuation(false);
            wp_send_json_success($this->job_response(is_array($job) ? $job : array()));
        }
        if (!is_array($job) || empty($job['status']) || 'running' !== $job['status']) {
            wp_send_json_error(array('message' => __('Non c’è un’esportazione in corso.', 'static-bridge')), 409);
        }
        // A running job without queue_version was started by a version before the export queue. Its
        // worker wrote rendered pages with no SSI guard and no rewrite step, so it is not resumed: the
        // job is closed and the administrator starts a new export (hardening note 34 of the 3 November
        // 2026 audit). Nothing is written and the release in use stays active.
        $job['status'] = 'failed';
        $job['updated_at'] = time();
        $job['issues'] = isset($job['issues']) && is_array($job['issues']) ? $job['issues'] : array();
        $job['issues'][] = array('url' => '', 'message' => __('Esportazione avviata da una versione precedente di Static Bridge: non viene ripresa. Avvia un nuovo export completo.', 'static-bridge'));
        update_option(self::JOB_OPTION, $job, false);
        $this->log_activity(__('Esportazione di una versione precedente chiusa senza scrivere pagine.', 'static-bridge'), __('Avvia un nuovo export completo; la release in uso resta attiva.', 'static-bridge'), true);
        wp_send_json_error(array('message' => __('Esportazione avviata da una versione precedente di Static Bridge: avvia un nuovo export completo.', 'static-bridge')), 409);
    }

    public function ajax_status()
    {
        $this->verify_export_ajax_request();
        $job = get_option(self::JOB_OPTION, array());
        if (is_array($job) && isset($job['status']) && 'running' === $job['status'] && !$this->job_is_running()) {
            $job = $this->close_incomplete_export_job($job);
        }
        wp_send_json_success($this->job_response(is_array($job) ? $job : array()));
    }

    public function ajax_resume()
    {
        $this->verify_export_ajax_request();
        $job = get_option(self::JOB_OPTION, array());
        if (!is_array($job) || !isset($job['status']) || 'paused' !== $job['status']) {
            wp_send_json_error(array('message' => __('Non c’è un’esportazione in pausa da riprendere.', 'static-bridge')), 409);
        }

        $lock_token = $this->acquire_export_worker_lock();
        if (false === $lock_token) {
            wp_send_json_error(array('message' => __('Un worker sta ancora terminando. Attendi qualche secondo e riprova.', 'static-bridge')), 409);
        }

        $job = get_option(self::JOB_OPTION, array());
        if (!$this->job_is_resumable($job)) {
            $this->release_export_worker_lock($lock_token);
            wp_send_json_error(array('message' => __('La sessione in pausa non supera i controlli di sicurezza o la sua coda non è disponibile. Nessuna release è stata pubblicata.', 'static-bridge')), 409);
        }

        $queue = $this->export_queue();
        $failed_row = $queue->next_pending((string) $job['job_id']);
        if (!is_array($failed_row)
            || !isset($failed_row['url'], $failed_row['url_hash'])
            || !hash_equals((string) $job['retry_url_hash'], (string) $failed_row['url_hash'])) {
            $this->release_export_worker_lock($lock_token);
            wp_send_json_error(array('message' => __('La URL fallita non è più la prima voce valida della coda; nessuna route è stata saltata.', 'static-bridge')), 409);
        }
        $last_error = __('Rendering WordPress non verificato dopo i tentativi della versione precedente.', 'static-bridge');
        foreach (array_reverse(isset($job['issues']) && is_array($job['issues']) ? $job['issues'] : array()) as $issue) {
            if (is_array($issue) && !empty($issue['retryable_transient'])
                && isset($issue['url'], $issue['message'])
                && hash_equals((string) $failed_row['url'], (string) $issue['url'])) {
                $last_error = (string) $issue['message'];
                break;
            }
        }
        $job['resume_retry_url_hash'] = $job['retry_url_hash'];
        $skipped = $this->skip_failed_export_queue_url($job, $queue, $failed_row, (string) $failed_row['url'], $last_error);
        if (is_wp_error($skipped)) {
            $this->release_export_worker_lock($lock_token);
            wp_send_json_error(array('message' => $skipped->get_error_message()), 500);
        }

        $job['status'] = 'running';
        $job['current_url'] = '';
        $job['updated_at'] = time();
        update_option(self::JOB_OPTION, $job, false);
        $this->schedule_export_worker(5, true);
        $this->release_export_worker_lock($lock_token);
        $this->arm_export_continuation((string) $job['job_id']);
        $this->defer_export_continuation(true);
        $this->log_activity(__('Esportazione ripresa dalla coda salvata.', 'static-bridge'), __('Lo staging esistente e gli URL già completati sono stati conservati.', 'static-bridge'));
        wp_send_json_success($this->job_response($job));
    }

    public function ajax_cancel()
    {
        $this->verify_export_ajax_request();
        $job = get_option(self::JOB_OPTION, array());
        if (!is_array($job) || !isset($job['status']) || !in_array($job['status'], array('running', 'paused'), true)) {
            wp_send_json_error(array('message' => __('Non c’è un’esportazione attiva da annullare.', 'static-bridge')), 409);
        }
        $lock_token = false;
        if (!empty($job['queue_version'])) {
            $lock_token = $this->acquire_export_worker_lock();
            if (false === $lock_token) {
                wp_send_json_error(array('message' => __('Il worker sta completando un piccolo blocco. Riprova ad annullare tra qualche secondo.', 'static-bridge')), 409);
            }
            $job = get_option(self::JOB_OPTION, array());
            if (!is_array($job) || !isset($job['status']) || !in_array($job['status'], array('running', 'paused'), true)) {
                $this->release_export_worker_lock($lock_token);
                wp_send_json_error(array('message' => __('L’esportazione non è più attiva.', 'static-bridge')), 409);
            }
        }
        $job['status'] = 'cancelled';
        $job['updated_at'] = time();
        $job['issues'] = isset($job['issues']) && is_array($job['issues']) ? $job['issues'] : array();
        $job['issues'][] = array('url' => '', 'message' => __('Esportazione annullata dall’utente. La release parziale resta in staging e non viene pubblicata né rimossa.', 'static-bridge'));
        update_option(self::JOB_OPTION, $job, false);
        if (!empty($job['queue_version']) && !empty($job['job_id'])) {
            $this->export_queue()->delete_job($job['job_id']);
            wp_clear_scheduled_hook('static_bridge_process_export_queue');
            delete_option(self::EXPORT_CONTINUE_OPTION);
            $this->release_export_worker_lock($lock_token);
        }
        $this->cleanup_dependency_index_for_job($job);
        $this->log_activity(__('Esportazione annullata.', 'static-bridge'), __('La release parziale resta in staging; la versione pubblicata non cambia.', 'static-bridge'));
        wp_send_json_success($this->job_response($job));
    }

    public function process_export_queue_cron()
    {
        $job = $this->run_export_queue_step();
        if (is_array($job) && isset($job['status']) && 'running' === $job['status']) {
            if (!empty($job['_waiting'])) {
                $this->schedule_export_worker((int) $job['_waiting'], true);
            } elseif (!empty($job['_worker_busy'])) {
                $lock = get_option(self::EXPORT_LOCK_OPTION, array());
                $delay = is_array($lock) && !empty($lock['expires'])
                    ? max(1, (int) $lock['expires'] - time() + 1)
                    : 5;
                $this->schedule_export_worker($delay, true);
            } else {
                $this->schedule_export_worker(5);
            }
            // WP-Cron runs only when someone loads WordPress, and visitors of a static site do not: a background
            // request keeps the export going (2.2.14).
            $this->send_export_continuation(false);
        }
        return $job;
    }

    /**
     * The background requests of this export start from here. Each request carries a single-use code (hop) that
     * send_export_continuation() replaces every time: a newer request retires every older one, so there is never
     * more than one chain, and a captured code stops working at the next hop.
     */
    private function arm_export_continuation($job_id)
    {
        update_option(self::EXPORT_CONTINUE_OPTION, array('job_id' => (string) $job_id, 'hop' => '', 'lease_until' => 0), false);
    }

    /**
     * Start the next background request of the running export, unless one sent in the last
     * EXPORT_CONTINUE_LEASE seconds is still alive ($force: the caller is the background request itself, or
     * the export has just started). Non-blocking, like WordPress' own spawn_cron(), to admin-ajax.php of this
     * site, through the render origin when one is set. Filter static_bridge_export_background_requests (true)
     * turns it off; WP-Cron then remains the only driver.
     */
    private function send_export_continuation($force)
    {
        if (!apply_filters('static_bridge_export_background_requests', true)) {
            return false;
        }
        $job = get_option(self::JOB_OPTION, array());
        $continue = get_option(self::EXPORT_CONTINUE_OPTION, array());
        if (!is_array($job) || 'running' !== ($job['status'] ?? '') || empty($job['job_id'])
            || !is_array($continue) || !isset($continue['job_id'])
            || !hash_equals((string) $continue['job_id'], (string) $job['job_id'])) {
            return false;
        }
        if (!$force && (int) ($continue['lease_until'] ?? 0) > time()) {
            return false;
        }
        $hop = bin2hex(random_bytes(32));
        update_option(self::EXPORT_CONTINUE_OPTION, array(
            'job_id' => (string) $job['job_id'],
            'hop' => $hop,
            'lease_until' => time() + self::EXPORT_CONTINUE_LEASE,
        ), false);

        $url = admin_url('admin-ajax.php');
        $args = array(
            // One second, not spawn_cron()'s 0.01: over HTTPS 10 ms often end before the TLS handshake and the
            // body are sent. The request is in the background, so the caller does not wait for its answer.
            'timeout' => 1,
            'blocking' => false,
            'redirection' => 0,
            'sslverify' => apply_filters('https_local_ssl_verify', false),
            'body' => array('action' => self::EXPORT_CONTINUE_ACTION, 'token' => $hop),
        );
        $connect_to = '' !== $this->settings()['render_origin'] ? $this->render_origin_connect_to($url) : '';
        $apply = function (&$handle, $parsed_args = array(), $request_url = '') use ($connect_to) {
            if ($this->same_site_url((string) $request_url)) {
                curl_setopt($handle, CURLOPT_CONNECT_TO, array($connect_to));
            }
        };
        if ('' !== $connect_to) {
            add_action('http_api_curl', $apply, 10, 3);
        }
        try {
            // 2.5.0: with the Basic Auth header when the site is behind one (self_request(), never a redirect).
            $this->self_request('POST', $url, $args);
        } finally {
            if ('' !== $connect_to) {
                remove_action('http_api_curl', $apply, 10);
            }
        }
        return true;
    }

    /**
     * The wp-admin tab and the page views send the background request only after they have answered: a
     * non-blocking wp_safe_remote_post() still waits up to its timeout, so the answer to the browser came a second
     * late, and a PHP-FPM worker killed in that second lost the start of the export (worker kill gate, 2.2.14).
     */
    private function defer_export_continuation($force)
    {
        if (null === $this->deferred_export_continuation) {
            add_action('shutdown', array($this, 'send_deferred_export_continuation'), PHP_INT_MAX);
            $this->deferred_export_continuation = false;
        }
        $this->deferred_export_continuation = $this->deferred_export_continuation || (bool) $force;
    }

    /** At the end of the request: the answer goes to the browser first (PHP-FPM, LiteSpeed), then the request. */
    public function send_deferred_export_continuation()
    {
        if (null === $this->deferred_export_continuation) {
            return;
        }
        $force = $this->deferred_export_continuation;
        $this->deferred_export_continuation = null;
        ignore_user_abort(true);
        if (function_exists('fastcgi_finish_request')) {
            fastcgi_finish_request();
        } elseif (function_exists('litespeed_finish_request')) {
            litespeed_finish_request();
        }
        $this->send_export_continuation($force);
    }

    /** True while $hop is the code of the last background request sent for the running export. */
    private function export_continuation_is_current($hop)
    {
        $continue = get_option(self::EXPORT_CONTINUE_OPTION, array());
        $job = get_option(self::JOB_OPTION, array());
        return is_array($continue) && isset($continue['hop'], $continue['job_id']) && is_string($continue['hop'])
            && '' !== $continue['hop'] && hash_equals($continue['hop'], $hop)
            && is_array($job) && 'running' === ($job['status'] ?? '')
            && hash_equals((string) $continue['job_id'], (string) ($job['job_id'] ?? ''));
    }

    /**
     * One background request: one worker step of the running export, a pause when the server asked to wait or
     * another worker holds the lock, then the next request. Only the code of the last request sent is accepted;
     * it is random, single-use, stored server-side and never shown in a page. A request that a newer one
     * replaced while it worked stops without sending another.
     */
    public function ajax_export_continue()
    {
        $hop = isset($_POST['token']) && is_string($_POST['token']) ? (string) wp_unslash($_POST['token']) : '';
        if (!preg_match('/\A[a-f0-9]{64}\z/', $hop) || !$this->export_continuation_is_current($hop)) {
            wp_send_json_error(null, 403);
        }
        ignore_user_abort(true);
        $job = $this->run_export_queue_step();
        if (is_array($job) && 'running' === ($job['status'] ?? '') && $this->export_continuation_is_current($hop)) {
            $pause = 0;
            if (!empty($job['_waiting'])) {
                $pause = (int) $job['_waiting'];
            } elseif (!empty($job['_worker_busy'])) {
                $lock = get_option(self::EXPORT_LOCK_OPTION, array());
                $pause = is_array($lock) && !empty($lock['expires']) ? (int) $lock['expires'] - time() + 1 : 5;
            }
            $pause = max(0, min(self::EXPORT_CONTINUE_MAX_SLEEP, $pause));
            if ($pause > 0) {
                sleep($pause);
            }
            if ($this->export_continuation_is_current($hop)) {
                $this->send_export_continuation(true);
            }
        } elseif (!is_array($job) || 'running' !== ($job['status'] ?? '')) {
            // The export is over: its code goes, unless another export has already armed its own.
            $continue = get_option(self::EXPORT_CONTINUE_OPTION, array());
            if (is_array($continue) && isset($continue['hop']) && is_string($continue['hop']) && hash_equals($continue['hop'], $hop)) {
                delete_option(self::EXPORT_CONTINUE_OPTION);
            }
        }
        wp_send_json_success();
    }

    /** A running export that has not moved for minutes: the administrator is told on every wp-admin page. */
    public function render_stalled_export_notice()
    {
        if (!current_user_can('manage_options')) {
            return;
        }
        $job = get_option(self::JOB_OPTION, array());
        if (!is_array($job) || 'running' !== ($job['status'] ?? '') || empty($job['queue_version'])) {
            return;
        }
        $idle = time() - max((int) ($job['updated_at'] ?? 0), (int) ($job['retry_not_before'] ?? 0));
        if ($idle < self::EXPORT_STALLED_AFTER) {
            return;
        }
        // Opening a wp-admin page restarts the background requests once their lease is over; the notice says what
        // to do if they cannot.
        $this->defer_export_continuation(false);
        echo '<div class="notice notice-warning"><p>' . esc_html(sprintf(
            /* translators: %s: number of minutes */
            __('Static Bridge: l’export completo è fermo da %s minuti e la nuova versione statica non è ancora pubblicata. Ho provato a farlo ripartire; se non avanza, apri Static Bridge e premi «Riprendi esportazione», poi esegui la Diagnostica (richieste del server a se stesso, WP-Cron).', 'static-bridge'),
            number_format_i18n((int) floor($idle / 60))
        )) . ' <a href="' . esc_url(admin_url('admin.php?page=' . self::ADMIN_SLUG)) . '">' . esc_html__('Apri Static Bridge', 'static-bridge') . '</a></p></div>';
    }

    /*
     * The WP-CLI commands (plugin/cli.php, 2.5.0) call the public cli_* methods below. They are hooked to nothing,
     * so no request reaches them; there is no capability or nonce because whoever has the shell is trusted, but the
     * content and the export still pass every check of the Generate tab and of the push.
     */

    /** What `wp static-bridge status` prints: release in use, last full export, incremental queue, link check, schedule. */
    public function cli_status()
    {
        $release = $this->current_release();
        $last = get_option('static_bridge_last_release', array());
        $last = is_array($last) ? $last : array();
        $job = get_option(self::JOB_OPTION, array());
        $job = is_array($job) ? $job : array();
        $status = isset($job['status']) && in_array($job['status'], array('running', 'paused', 'complete', 'failed', 'cancelled'), true)
            ? $job['status'] : 'idle';
        $response = $this->job_response($job);
        $issues = isset($job['issues']) && is_array($job['issues']) ? array_values($job['issues']) : array();
        $last_issue = empty($issues) ? null : $issues[count($issues) - 1];
        $message = (string) ($response['message'] ?? '');
        if ('' === $message && in_array($status, array('failed', 'cancelled'), true) && is_array($last_issue) && isset($last_issue['message'])) {
            $message = (!empty($last_issue['url']) && is_string($last_issue['url']) ? $last_issue['url'] . ' — ' : '') . (string) $last_issue['message'];
        }
        $queue = $this->incremental_queue();
        $retrying = 0;
        foreach ($queue as $item) {
            if (is_array($item) && (int) ($item['attempts'] ?? 0) > 0) {
                $retrying++;
            }
        }
        $wait = $this->incremental_wait_remaining();
        $settings = $this->settings();
        $next = 'off' !== $settings['scheduled_export'] ? (int) wp_next_scheduled(self::SCHEDULED_EXPORT_HOOK) : 0;
        return array(
            'version' => self::VERSION,
            'release' => array(
                'id' => '' !== $release ? basename($release) : '',
                'pages' => isset($last['pages']) ? absint($last['pages']) : 0,
                'published_at' => isset($last['published_at']) ? absint($last['published_at']) : 0,
            ),
            'export' => array(
                'status' => $status,
                'alive' => 'running' === $status && $this->job_is_running(),
                'started_by' => isset($job['started_by']) && is_string($job['started_by']) ? sanitize_key($job['started_by']) : '',
                'processed' => (int) ($response['processed'] ?? 0),
                'total' => (int) ($response['total'] ?? 0),
                'saved' => (int) ($response['saved'] ?? 0),
                'errors' => (int) ($response['routeErrors'] ?? 0),
                'pending' => (int) ($response['pending'] ?? 0),
                'started_at' => max(0, (int) ($job['started_at'] ?? 0)),
                'finished_at' => in_array($status, array('complete', 'failed', 'cancelled'), true) ? max(0, (int) ($job['updated_at'] ?? 0)) : 0,
                'message' => $this->failure_notice_text($message),
            ),
            'incremental' => array(
                'enabled' => !empty($settings['incremental_enabled']),
                'items' => count($queue),
                'retrying' => $retrying,
                'wait_until' => $wait > 0 ? time() + $wait : 0,
            ),
            'link_check' => $this->link_check_summary(),
            // 2.5.0: only the state of the two constants, never a value.
            'basic_auth' => $this->basic_auth_state(),
            'schedule' => array(
                'frequency' => $settings['scheduled_export'],
                'time' => $settings['scheduled_export_time'],
                'day' => (int) $settings['scheduled_export_day'],
                'next' => $next,
            ),
        );
    }

    /**
     * `wp static-bridge export`: start_export('cli'). With $background the background requests and WP-Cron finish
     * it, as after the Generate tab; without, the WP-CLI process runs the steps (cli_export_step()) and holds the
     * lease of the background requests, so the chain does not work on the same export at the same time.
     */
    public function cli_start_export($background = false)
    {
        $job = $this->start_export('cli', (bool) $background);
        if (is_wp_error($job)) {
            return $job;
        }
        if (!$background) {
            $this->hold_export_continuation_for_cli((string) $job['job_id']);
        }
        return $this->job_response($job);
    }

    /**
     * One worker step of the running export for the synchronous WP-CLI export, with the lease renewed first.
     * Returns job_response() plus `pause`: the seconds to wait before the next step (a 429/503 wait, or the worker
     * lock held by another request until it expires). A running export that is no longer alive is closed as
     * ajax_status() does.
     */
    public function cli_export_step()
    {
        $job = get_option(self::JOB_OPTION, array());
        if (is_array($job) && 'running' === ($job['status'] ?? '') && !empty($job['queue_version']) && !empty($job['job_id'])) {
            if (!$this->job_is_running()) {
                $job = $this->close_incomplete_export_job($job);
            } else {
                $this->hold_export_continuation_for_cli((string) $job['job_id']);
                $job = $this->run_export_queue_step();
            }
        }
        $job = is_array($job) ? $job : array();
        $response = $this->job_response($job);
        $pause = 0;
        if (!empty($job['_waiting'])) {
            $pause = (int) $job['_waiting'];
        } elseif (!empty($job['_worker_busy'])) {
            $lock = get_option(self::EXPORT_LOCK_OPTION, array());
            $pause = is_array($lock) && !empty($lock['expires']) ? (int) $lock['expires'] - time() + 1 : 5;
        }
        $response['pause'] = max(0, $pause);
        return $response;
    }

    /**
     * The synchronous WP-CLI export stops (Ctrl-C, an error) while its export runs: the export goes on as after
     * closing the Generate tab, with the background requests armed and sent now and WP-Cron in 5 seconds.
     */
    public function cli_hand_export_to_background()
    {
        $job = get_option(self::JOB_OPTION, array());
        if (!is_array($job) || 'running' !== ($job['status'] ?? '') || empty($job['queue_version']) || empty($job['job_id'])) {
            return false;
        }
        $this->schedule_export_worker(5, true);
        $this->arm_export_continuation((string) $job['job_id']);
        return $this->send_export_continuation(true);
    }

    /**
     * The WP-CLI process holds the lease of the background requests: no code (hop is empty, so
     * ajax_export_continue() accepts no request) and lease_until in EXPORT_CONTINUE_LEASE seconds, so a tick of the
     * Generate tab, WP-Cron or the stalled notice do not start a chain while the shell works. If the process dies,
     * the lease ends and the next one of them starts the chain again.
     */
    private function hold_export_continuation_for_cli($job_id)
    {
        update_option(self::EXPORT_CONTINUE_OPTION, array('job_id' => (string) $job_id, 'hop' => '', 'lease_until' => time() + self::EXPORT_CONTINUE_LEASE), false);
    }

    /**
     * `wp static-bridge push <id>`: the manual push of the editor and of the admin bar. static_bridge_can_push_post
     * does not apply (the shell is trusted), post_push_unavailable_reason() does: published, not password
     * protected, not excluded, incremental updates on, a release online. Returns {token, path, status, last_error}
     * or a WP_Error.
     */
    public function cli_push_post($post_id)
    {
        $post_id = absint($post_id);
        $post = $post_id > 0 ? get_post($post_id) : null;
        if (!($post instanceof WP_Post) && is_object($post)) {
            $post = new WP_Post($post);
        }
        if (!($post instanceof WP_Post)) {
            return new WP_Error('static_bridge_push_post_missing', __('Il contenuto richiesto non è disponibile.', 'static-bridge'));
        }
        // queue_manual_post_push() refuses with post_push_unavailable_reason(), as for the editor.
        $token = wp_generate_uuid4();
        $queued = $this->queue_manual_post_push($post, $token);
        if (is_wp_error($queued)) {
            $this->log_activity(__('Push statico non accodato.', 'static-bridge'), $queued->get_error_message(), true);
            return $queued;
        }
        $this->process_manual_post_push_now($post, $token);
        return array_merge(array('token' => $token, 'path' => $this->normalize_route_path(get_permalink($post))), $this->cli_push_status($token));
    }

    /** The state of a push as the editor reads it: queued, retrying, completed or failed, and the last error. */
    public function cli_push_status($token)
    {
        $record = $this->post_push_status_record($token);
        return array(
            'status' => is_array($record) && isset($record['status']) ? sanitize_key($record['status']) : 'unknown',
            'last_error' => is_array($record) && isset($record['last_error']) ? sanitize_text_field((string) $record['last_error']) : '',
        );
    }

    private function export_queue()
    {
        return new Static_Bridge_Export_Queue(isset($GLOBALS['wpdb']) ? $GLOBALS['wpdb'] : null);
    }

    private function schedule_export_worker($delay, $replace = false)
    {
        if ($replace) {
            wp_clear_scheduled_hook('static_bridge_process_export_queue');
        } elseif (wp_next_scheduled('static_bridge_process_export_queue')) {
            return;
        }
        wp_schedule_single_event(time() + absint($delay), 'static_bridge_process_export_queue');
    }

    /**
     * The export worker lock, decided by its database row and never by the request's option cache: add_option() is
     * an INSERT … ON DUPLICATE KEY UPDATE, so two requests arriving together (a tick of the page and a background
     * request) both «added» it and both ran a step of the same export (2.4.0). Here the row is read directly, an
     * expired one is removed only while it is still the row read, and the lock is an INSERT IGNORE: one request wins.
     */
    private function acquire_export_worker_lock()
    {
        return $this->acquire_row_lock(self::EXPORT_LOCK_OPTION, self::EXPORT_WORKER_LOCK_TTL);
    }

    private function release_export_worker_lock($token)
    {
        $this->release_row_lock(self::EXPORT_LOCK_OPTION, $token);
    }

    /**
     * The incremental worker lock, shared by the cron worker, the immediate push (wp-admin and MCP) and the release
     * cleanup. Until 2.4.0 it was a transient: get_transient() then set_transient() let two requests both take it,
     * and the cron worker deleted it in the end even when it belonged to another request, so a push and the worker
     * could render at the same time (2.4.1).
     */
    private function acquire_incremental_lock()
    {
        return $this->acquire_row_lock(self::INCREMENTAL_LOCK_OPTION, self::INCREMENTAL_LOCK_TTL);
    }

    private function release_incremental_lock($token)
    {
        $this->release_row_lock(self::INCREMENTAL_LOCK_OPTION, $token);
    }

    /** Whether a request holds the lock now (read from its row; an expired lock does not count). */
    private function row_lock_active($name)
    {
        global $wpdb;
        $raw = $wpdb->get_var($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name = %s LIMIT 1", $name));
        $lock = null === $raw ? null : maybe_unserialize($raw);
        return is_array($lock) && !empty($lock['expires']) && (int) $lock['expires'] > time();
    }

    /** A lock as an option row: the token of the request that took it, or false when another request holds it. */
    private function acquire_row_lock($name, $ttl)
    {
        global $wpdb;
        $raw = $wpdb->get_var($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name = %s LIMIT 1", $name));
        if (null !== $raw) {
            $existing = maybe_unserialize($raw);
            if (is_array($existing) && !empty($existing['expires']) && (int) $existing['expires'] > time()) {
                return false;
            }
            $wpdb->query($wpdb->prepare("DELETE FROM {$wpdb->options} WHERE option_name = %s AND option_value = %s", $name, $raw));
        }
        $token = function_exists('wp_generate_uuid4') ? wp_generate_uuid4() : sha1(uniqid('', true));
        $lock = array('token' => $token, 'expires' => time() + max(1, (int) $ttl));
        $inserted = $wpdb->query($wpdb->prepare("INSERT IGNORE INTO {$wpdb->options} (option_name, option_value, autoload) VALUES (%s, %s, %s)", $name, maybe_serialize($lock), 'off'));
        $this->forget_cached_option($name);
        return 1 === (int) $inserted ? $token : false;
    }

    private function release_row_lock($name, $token)
    {
        global $wpdb;
        $raw = $wpdb->get_var($wpdb->prepare("SELECT option_value FROM {$wpdb->options} WHERE option_name = %s LIMIT 1", $name));
        $lock = null === $raw ? null : maybe_unserialize($raw);
        if (is_array($lock) && isset($lock['token']) && is_string($token) && hash_equals((string) $lock['token'], $token)) {
            // Only the row this request wrote: a lock taken meanwhile by another request stays.
            $wpdb->query($wpdb->prepare("DELETE FROM {$wpdb->options} WHERE option_name = %s AND option_value = %s", $name, $raw));
        }
        $this->forget_cached_option($name);
    }

    /** After writing an option row directly, the request's caches must not answer with the old value. */
    private function forget_cached_option($name)
    {
        wp_cache_delete($name, 'options');
        $notoptions = wp_cache_get('notoptions', 'options');
        if (is_array($notoptions) && isset($notoptions[$name])) {
            unset($notoptions[$name]);
            wp_cache_set('notoptions', $notoptions, 'options');
        }
    }

    private function queue_job_is_current($job_id)
    {
        $current = get_option(self::JOB_OPTION, array());
        return is_array($current)
            && isset($current['queue_version'], $current['job_id'], $current['status'])
            && 1 === (int) $current['queue_version']
            && hash_equals((string) $job_id, (string) $current['job_id'])
            && 'running' === $current['status'];
    }

    private function run_export_queue_step()
    {
        $job = get_option(self::JOB_OPTION, array());
        if (!is_array($job) || empty($job['queue_version']) || 1 !== (int) $job['queue_version'] || empty($job['job_id'])) {
            return is_array($job) ? $job : array();
        }
        if ('running' !== (isset($job['status']) ? $job['status'] : '')) {
            return $job;
        }
        if (!preg_match('/^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/i', (string) $job['job_id'])) {
            return $this->fail_export_queue_job($job, '', __('Identificativo della coda non valido; nessun URL è stato elaborato.', 'static-bridge'));
        }
        if (!isset($job['discovered']) || !is_numeric($job['discovered'])
            || (float) $job['discovered'] < 0
            || (float) $job['discovered'] !== (float) (int) $job['discovered']) {
            return $this->fail_export_queue_job($job, '', __('Contatore degli URL scoperti non valido; la release parziale non verrà pubblicata.', 'static-bridge'));
        }
        $job['discovered'] = (int) $job['discovered'];
            if (isset($job['retry_url_hash']) || isset($job['retry_attempts'])) {
            if (!isset($job['retry_url_hash'], $job['retry_attempts'])
                || !is_string($job['retry_url_hash'])
                || !preg_match('/^[a-f0-9]{40}$/', $job['retry_url_hash'])
                || !is_numeric($job['retry_attempts'])
                || (float) $job['retry_attempts'] < 1
                || (float) $job['retry_attempts'] > self::MAX_EXPORT_HTTP_RETRIES
                || (float) $job['retry_attempts'] !== (float) (int) $job['retry_attempts']) {
                return $this->fail_export_queue_job($job, '', __('Contatore dei tentativi HTTP non valido; la release parziale non verrà pubblicata.', 'static-bridge'));
            }
        }
        if (isset($job['resume_retry_url_hash'])
            && (!is_string($job['resume_retry_url_hash']) || !preg_match('/^[a-f0-9]{40}$/', $job['resume_retry_url_hash']))) {
            return $this->fail_export_queue_job($job, '', __('Checkpoint di ripresa non valido; la release parziale non verrà pubblicata.', 'static-bridge'));
        }
        if ($job['discovered'] > self::MAX_QUEUE_EXPORT_URLS) {
            return $this->fail_export_queue_job($job, '', sprintf(/* translators: %s: maximum number of URLs per release */ __('Il sito supera il limite prudenziale di %s URL unici per release; quella parziale non verrà pubblicata.', 'static-bridge'), number_format_i18n(self::MAX_QUEUE_EXPORT_URLS)));
        }
        if (!$this->valid_release_stage($job)) {
            return $this->fail_export_queue_job($job, '', __('Cartella temporanea non valida o esterna alle release Static Bridge; nessun file è stato scritto.', 'static-bridge'));
        }
        if (!empty($job['updated_at']) && time() - (int) $job['updated_at'] > self::EXPORT_JOB_MAX_AGE) {
            return $this->fail_export_queue_job($job, '', __('Esportazione scaduta dopo sette giorni senza avanzamento.', 'static-bridge'));
        }

        if (isset($job['retry_not_before']) && is_numeric($job['retry_not_before'])) {
            // The server rate limited the export (HTTP 429/503): nothing is fetched until the wait is over.
            $wait = min(self::MAX_RATE_LIMIT_WAIT, (int) $job['retry_not_before'] - time());
            if ($wait > 0) {
                $job['_waiting'] = $wait;
                return $job;
            }
        }

        $lock_token = $this->acquire_export_worker_lock();
        if (false === $lock_token) {
            $job['_worker_busy'] = true;
            return $job;
        }
        // Keep a durable recovery event before doing work. If PHP-FPM kills this
        // request, the next cron run can resume after the worker lock expires.
        $this->schedule_export_worker(self::EXPORT_WORKER_WATCHDOG_DELAY, true);
        $fluent_forms_routing_changed = false;
        try {
            $job = get_option(self::JOB_OPTION, array());
            if (!is_array($job) || 'running' !== (isset($job['status']) ? $job['status'] : '') || empty($job['job_id'])) {
                wp_clear_scheduled_hook('static_bridge_process_export_queue');
                return is_array($job) ? $job : array();
            }
            $job_id = (string) $job['job_id'];
            if (!$this->valid_release_stage($job)) {
                return $this->fail_export_queue_job($job, '', __('Cartella temporanea di esportazione non più sicura.', 'static-bridge'));
            }
            $queue = $this->export_queue();
            if (!$queue->install()) {
                return $this->fail_export_queue_job($job, '', __('La tabella indicizzata della coda non è disponibile.', 'static-bridge'));
            }

            if (empty($job['discovery_complete']) && empty($job['archive_phase'])) {
                $discovery = $this->discover_wordpress_post_url_batch(isset($job['discovery_cursor']) ? (int) $job['discovery_cursor'] : 0);
                if (is_wp_error($discovery)) {
                    return $this->fail_export_queue_job($job, '', $discovery->get_error_message());
                }
                $inserted = $queue->enqueue_batch($job_id, $discovery['urls']);
                if (false === $inserted) {
                    return $this->fail_export_queue_job($job, '', __('Impossibile aggiungere un blocco di URL alla coda indicizzata.', 'static-bridge'));
                }
                $job['discovery_cursor'] = (int) $discovery['cursor'];
                if (!empty($discovery['complete'])) {
                    // The singles are inventoried: the archives follow, so a list no page links to
                    // is in the release too.
                    $job['archive_phase'] = 'terms';
                    $job['archive_cursor'] = 0;
                }
                $dynamic_urls = isset($discovery['dynamic_urls']) && is_array($discovery['dynamic_urls'])
                    ? array_values(array_unique($discovery['dynamic_urls']))
                    : array();
                foreach ($dynamic_urls as $dynamic_url) {
                    $job['processed'] = max(0, (int) (isset($job['processed']) ? $job['processed'] : 0)) + 1;
                    $job['skipped'] = max(0, (int) (isset($job['skipped']) ? $job['skipped'] : 0)) + 1;
                    $this->append_export_issue(
                        $job,
                        $dynamic_url,
                        __('Questa URL usa parametri query e resterà dinamica; imposta permalink leggibili per includere articoli e pagine nella versione statica.', 'static-bridge')
                    );
                }
                $job['discovered'] = max(0, (int) (isset($job['discovered']) ? $job['discovered'] : 0))
                    + (int) $inserted + count($dynamic_urls);
                $job['updated_at'] = time();
                update_option(self::JOB_OPTION, $job, false);
                if ($job['discovered'] > self::MAX_QUEUE_EXPORT_URLS) {
                    return $this->fail_export_queue_job($job, '', sprintf(/* translators: %s: maximum number of URLs per release */ __('Il sito supera il limite prudenziale di %s URL unici per release; quella parziale non verrà pubblicata.', 'static-bridge'), number_format_i18n(self::MAX_QUEUE_EXPORT_URLS)));
                }
            }
            // A few archive batches per worker step; one that fills a block ends the step's discovery.
            for ($archive_batches = 0; $archive_batches < 8 && empty($job['discovery_complete']) && !empty($job['archive_phase']); $archive_batches++) {
                $archives = $this->discover_wordpress_archive_url_batch((string) $job['archive_phase'], isset($job['archive_cursor']) ? (int) $job['archive_cursor'] : 0);
                if (is_wp_error($archives)) {
                    return $this->fail_export_queue_job($job, '', $archives->get_error_message());
                }
                $inserted = $queue->enqueue_batch($job_id, $archives['urls']);
                if (false === $inserted) {
                    return $this->fail_export_queue_job($job, '', __('Impossibile aggiungere un blocco di URL alla coda indicizzata.', 'static-bridge'));
                }
                $job['archive_phase'] = $archives['phase'];
                $job['archive_cursor'] = (int) $archives['cursor'];
                $job['discovery_complete'] = 'done' === $archives['phase'];
                $job['discovered'] = max(0, (int) (isset($job['discovered']) ? $job['discovered'] : 0)) + (int) $inserted;
                $job['updated_at'] = time();
                update_option(self::JOB_OPTION, $job, false);
                if ($job['discovered'] > self::MAX_QUEUE_EXPORT_URLS) {
                    return $this->fail_export_queue_job($job, '', sprintf(/* translators: %s: maximum number of URLs per release */ __('Il sito supera il limite prudenziale di %s URL unici per release; quella parziale non verrà pubblicata.', 'static-bridge'), number_format_i18n(self::MAX_QUEUE_EXPORT_URLS)));
                }
                if ((int) $inserted >= self::WORDPRESS_DISCOVERY_PAGE_SIZE) {
                    break;
                }
            }

            $batch_size = (int) apply_filters('static_bridge_export_batch_size', 40);
            $batch_size = max(1, min(80, $batch_size));
            $time_budget = (int) apply_filters('static_bridge_export_time_budget', 20);
            $time_budget = max(1, min(45, $time_budget));
            $php_request_budget = $this->safe_php_request_budget();
            if ($php_request_budget > 0) {
                $time_budget = min($time_budget, $php_request_budget);
            }
            $fetch_info = $this->export_fetch_info();
            $concurrency = $fetch_info['concurrency'];
            // Once the server has rate limited this export: one URL at a time, with a pause between them.
            $rate_limited = max(0, (int) ($job['rate_limited'] ?? 0));
            $pace = $rate_limited > 0 || !empty($job['recovery_round']) ? min(5, 1 + $rate_limited) : 0;
            if ($pace > 0) {
                $concurrency = 1;
            }
            // «Rallenta l'export se il server è lento» (2.5.0, off by default): see update_export_load_brake().
            $load_brake = !empty($this->settings()['export_load_brake']);
            $worker_started_at = microtime(true);
            $pending_rows = array();
            $pending_results = array();
            $pending_row_index = 0;
            for ($batch_index = 0; $batch_index < $batch_size; $batch_index++) {
                if (!$this->queue_job_is_current($job_id)) {
                    return get_option(self::JOB_OPTION, $job);
                }
                if ($pending_row_index >= count($pending_rows)) {
                    if ($batch_index > 0 && microtime(true) - $worker_started_at >= $time_budget) {
                        break;
                    }
                    $brake_level = $load_brake ? max(0, min(self::EXPORT_BRAKE_MAX_LEVEL, (int) ($job['load_brake'] ?? 0))) : 0;
                    // Braked: half the step at every level, one URL at a time; never less than one URL per step.
                    if ($brake_level > 0 && $batch_index >= max(1, $batch_size >> $brake_level)) {
                        break;
                    }
                    $pending_rows = array();
                    $pending_results = array();
                    $pending_row_index = 0;
                    $rows_to_fetch = min($brake_level > 0 ? 1 : $concurrency, $batch_size - $batch_index);
                    $pending_rows = $queue->next_pending_batch($job_id, $rows_to_fetch);
                    if (false === $pending_rows) {
                        return $this->fail_export_queue_job($job, '', __('Lettura del blocco di URL dalla coda indicizzata non riuscita.', 'static-bridge'));
                    }
                    if (empty($pending_rows)) {
                        break;
                    }
                    $fetch_urls = array();
                    foreach ($pending_rows as $pending_row) {
                        $fetch_urls[] = (string) $pending_row['url'];
                    }
                    $job['current_url'] = $fetch_urls[0];
                    update_option(self::JOB_OPTION, $job, false);
                    if ($pace > 0) {
                        // The pause also spans worker steps: the first fetch of a step waits for the last of the previous one.
                        $since_last = microtime(true) - (float) ($job['last_fetch_at'] ?? 0);
                        $wait = max(0.0, $pace - $since_last);
                        if ($batch_index > 0 && microtime(true) - $worker_started_at + $wait >= $time_budget) {
                            break;
                        }
                        if ($wait > 0) {
                            usleep((int) ($wait * 1000000));
                        }
                        $job['last_fetch_at'] = microtime(true);
                    }
                    if ($brake_level > 0) {
                        // The brake's pause after the last render, also across worker steps (at most the top level).
                        $brake_wait = min((float) self::EXPORT_BRAKE_MAX_LEVEL, max(0.0, (float) ($job['load_brake_resume_at'] ?? 0) - microtime(true)));
                        if ($batch_index > 0 && microtime(true) - $worker_started_at + $brake_wait >= $time_budget) {
                            break;
                        }
                        if ($brake_wait > 0) {
                            usleep((int) ($brake_wait * 1000000));
                        }
                    }
                    $fetch_started_at = microtime(true);
                    $pending_results = $this->fetch_pages($fetch_urls);
                    if ($load_brake) {
                        $this->update_export_load_brake($job, microtime(true) - $fetch_started_at);
                    }
                }
                $row = $pending_rows[$pending_row_index++];
                if (null === $row) {
                    break;
                }
                $url = (string) $row['url'];
                $job['current_url'] = $url;
                update_option(self::JOB_OPTION, $job, false);
                $result = isset($pending_results[$url])
                    ? $pending_results[$url]
                    : new WP_Error('static_bridge_batch_response_missing', __('La richiesta parallela non ha restituito una risposta per l’URL in coda.', 'static-bridge'));
                if (!$this->queue_job_is_current($job_id)) {
                    return get_option(self::JOB_OPTION, $job);
                }
                $this->clear_resumed_export_retry_issue($job, $url);
                if (is_wp_error($result) && $this->is_render_machinery_error($result)) {
                    $render_waits = max(0, (int) ($job['render_waits'] ?? 0)) + 1;
                    if ($render_waits <= self::MAX_EXPORT_RENDER_WAITS) {
                        // Not this page's fault: another render holds the lock, or the bypass of an earlier render is
                        // being restored. No attempt is used and nothing is skipped: the row stays pending for a later
                        // worker step. Past the limit the error follows the usual path.
                        $job['render_waits'] = $render_waits;
                        $job['current_url'] = $url;
                        $job['updated_at'] = time();
                        update_option(self::JOB_OPTION, $job, false);
                        break;
                    }
                }
                unset($job['render_waits']);
                if (is_wp_error($result) && $this->is_retryable_export_error($result)) {
                    $url_hash = sha1($url);
                    $retry_attempts = isset($job['retry_url_hash'], $job['retry_attempts'])
                        && hash_equals((string) $job['retry_url_hash'], $url_hash)
                        ? (int) $job['retry_attempts']
                        : 0;
                    $rate_limit = $this->is_rate_limited_export_error($result);
                    if ($retry_attempts < self::MAX_EXPORT_HTTP_RETRIES) {
                        $job['retry_url_hash'] = $url_hash;
                        $job['retry_attempts'] = $retry_attempts + 1;
                        $job['current_url'] = $url;
                        $job['updated_at'] = time();
                        if ($rate_limit) {
                            // Retry-After or a doubling pause; until then no worker fetches anything.
                            $job['rate_limited'] = max(0, (int) ($job['rate_limited'] ?? 0)) + 1;
                            $job['rate_limit_calm'] = 0;
                            $job['retry_not_before'] = time() + $this->rate_limit_wait($retry_attempts + 1, $this->export_retry_after[$url] ?? 0);
                        }
                        update_option(self::JOB_OPTION, $job, false);
                        // End this request so a slow URL is retried by a later worker
                        // request instead of consuming the whole batch or PHP timeout.
                        break;
                    }
                    if ($rate_limit && empty($job['recovery_round'])) {
                        // Still rate limited: set aside for the slow round at the end of the export instead of
                        // leaving the page out of the release (2.2.14).
                        if (!$queue->mark($job_id, $row['url_hash'], 'deferred')) {
                            return $this->fail_export_queue_job($job, $url, __('Non è stato possibile rinviare la URL rallentata dal server.', 'static-bridge'));
                        }
                        unset($job['retry_url_hash'], $job['retry_attempts']);
                        $job['current_url'] = '';
                        $job['updated_at'] = time();
                        update_option(self::JOB_OPTION, $job, false);
                        continue;
                    }
                    if ($rate_limit) {
                        $job['rate_limited_urls'] = array_slice(array_values(array_unique(array_merge((array) ($job['rate_limited_urls'] ?? array()), array($url)))), 0, 100);
                    }
                    $route_skip = $this->skip_failed_export_queue_url($job, $queue, $row, $url, $result->get_error_message());
                    if (is_wp_error($route_skip)) {
                        return $this->fail_export_queue_job($job, $url, $route_skip->get_error_message());
                    }
                    continue;
                }
                $job['processed'] = max(0, (int) (isset($job['processed']) ? $job['processed'] : 0)) + 1;
                if (!empty($job['rate_limited']) && !$this->is_rate_limited_export_error($result)) {
                    // 20 answers in a row without a rate limit: the server has recovered, the pace halves.
                    $job['rate_limit_calm'] = (int) ($job['rate_limit_calm'] ?? 0) + 1;
                    if ($job['rate_limit_calm'] >= 20) {
                        $job['rate_limited'] = intdiv((int) $job['rate_limited'], 2);
                        $job['rate_limit_calm'] = 0;
                    }
                }
                if (isset($job['retry_url_hash']) && hash_equals((string) $job['retry_url_hash'], sha1($url))) {
                    unset($job['retry_url_hash'], $job['retry_attempts']);
                }

                if (is_wp_error($result)) {
                    $code = $result->get_error_code();
                    if (in_array($code, array('static_bridge_redirect', 'static_bridge_redirect_unsafe'), true)) {
                        $redirect_target = 'static_bridge_redirect' === $code
                            ? $this->normalize_public_url($result->get_error_data())
                            : '';
                        if ($redirect_target) {
                            $redirect_added = $queue->enqueue_batch($job_id, array($redirect_target));
                            if (false === $redirect_added) {
                                return $this->fail_export_queue_job($job, $url, __('Non è stato possibile accodare la destinazione del reindirizzamento.', 'static-bridge'));
                            }
                            $job['discovered'] += (int) $redirect_added;
                            if ($job['discovered'] > self::MAX_QUEUE_EXPORT_URLS) {
                                return $this->fail_export_queue_job($job, $url, sprintf(/* translators: %s: maximum number of URLs per release */ __('Il sito supera il limite prudenziale di %s URL unici per release; quella parziale non verrà pubblicata.', 'static-bridge'), number_format_i18n(self::MAX_QUEUE_EXPORT_URLS)));
                            }
                            // A redirect inside the site (a plugin or a snippet that sends an old address to its new
                            // page) is followed, not a problem: the destination is in the queue. Only counted (2.4.1).
                            $job['redirects'] = max(0, (int) ($job['redirects'] ?? 0)) + 1;
                        } else {
                            $job['skipped']++;
                            $this->append_export_issue($job, $url, $result->get_error_message());
                        }
                        if (!$queue->mark($job_id, $row['url_hash'], 'skipped')) {
                            return $this->fail_export_queue_job($job, $url, __('Non è stato possibile registrare il reindirizzamento nella coda.', 'static-bridge'));
                        }
                    } elseif ($this->is_skippable_export_http_error($result)) {
                        // The inventory estimates the last /page/N/ of an archive from post counts; a page past
                        // the real last one is not a route, so it is not reported as an URL left out.
                        if (!$this->is_archive_page_past_end($url, $result)) {
                            $job['skipped']++;
                            $this->append_export_issue($job, $url, $result->get_error_message());
                        }
                        if (!$queue->mark($job_id, $row['url_hash'], 'skipped')) {
                            return $this->fail_export_queue_job($job, $url, __('Non è stato possibile registrare il 404 nella coda.', 'static-bridge'));
                        }
                    } elseif ($this->is_fatal_export_url_error($result)) {
                        return $this->fail_export_queue_job($job, $url, $result->get_error_message());
                    } else {
                        $route_skip = $this->skip_failed_export_queue_url($job, $queue, $row, $url, $result->get_error_message(), true);
                        if (is_wp_error($route_skip)) {
                            return $this->fail_export_queue_job($job, $url, $route_skip->get_error_message());
                        }
                        continue;
                    }
                } else {
                    $relative = $this->relative_html_path($url);
                    if (is_wp_error($relative)) {
                        $job['skipped']++;
                        $this->append_export_issue($job, $url, $relative->get_error_message());
                        if (!$queue->mark($job_id, $row['url_hash'], 'skipped')) {
                            return $this->fail_export_queue_job($job, $url, __('Non è stato possibile registrare un URL non esportabile.', 'static-bridge'));
                        }
                    } else {
                        $prepared = $this->prepare_static_html($url, $result);
                        if (is_wp_error($prepared)) {
                            // 'static_bridge_fluentforms_dynamic' (record_fluent_forms_dynamic_route()) or
                            // 'static_bridge_woocommerce_dynamic' (record_woocommerce_dynamic_route()): no file in this
                            // release, the route is recorded and routed to WordPress; the next export re-checks it.
                            $route_path = $this->normalize_route_path($url);
                            $fallback_known = isset($this->fluent_forms_dynamic_routes()[$route_path]) || isset($this->woocommerce_dynamic_routes()[$route_path]);
                            if (!$this->record_dynamic_route_for($prepared, $url)) {
                                return $this->fail_export_queue_job($job, $url, __('Non è stato possibile registrare la pagina da servire in modo dinamico; la release non verrà pubblicata.', 'static-bridge'));
                            }
                            // Route it to WordPress now: the current release may still hold a copy
                            // with the old markup, and this export may never publish.
                            $fluent_forms_routing_changed = $fluent_forms_routing_changed || !$fallback_known;
                            $job['skipped']++;
                            $this->append_export_issue($job, $url, $prepared->get_error_message());
                            $added = $queue->enqueue_batch($job_id, array_values(array_filter($this->extract_internal_links($result['body'], $url), array($this, 'within_archive_page_cap'))));
                            if (false === $added) {
                                return $this->fail_export_queue_job($job, $url, __('Non è stato possibile aggiungere i link interni scoperti alla coda.', 'static-bridge'));
                            }
                            $job['discovered'] += (int) $added;
                            if (!$queue->mark($job_id, $row['url_hash'], 'skipped')) {
                                return $this->fail_export_queue_job($job, $url, __('Non è stato possibile registrare la pagina dinamica nella coda.', 'static-bridge'));
                            }
                            $job['current_url'] = '';
                            $job['updated_at'] = time();
                            update_option(self::JOB_OPTION, $job, false);
                            continue;
                        }
                        $write = $this->write_export_page($job, $relative, $prepared, $url);
                        if (is_wp_error($write)) {
                            return $this->fail_export_queue_job($job, $url, $write->get_error_message());
                        }
                        if (!empty($job['dependency_index_active'])
                            && !(new Static_Bridge_Dependency_Index())->index_route(
                                (string) $job['release_id'],
                                $this->normalize_route_path($url),
                                $url,
                                (string) $result['body']
                            )) {
                            $job['dependency_index_failed'] = 1;
                        }
                        $job['saved']++;
                        // 2.5.0: saved as before; a «do not cache» signal or a stale nonce is only reported, once per job.
                        $this->note_cache_signal($job['cache_signals'], $url, $this->cache_signal_reason($prepared, isset($result['render_facts']) ? $result['render_facts'] : array()));
                        // The home page's headers, or those of the first page saved when the home is dynamic.
                        if (isset($result['security_headers']) && is_array($result['security_headers'])
                            && (!isset($job['security_headers']) || '/' === $this->normalize_route_path($url))) {
                            $job['security_headers'] = $result['security_headers'];
                        }
                        $links = array_values(array_filter($this->extract_internal_links($result['body'], $url), array($this, 'within_archive_page_cap')));
                        $added = $queue->enqueue_batch($job_id, $links);
                        if (false === $added) {
                            return $this->fail_export_queue_job($job, $url, __('Non è stato possibile aggiungere i link interni scoperti alla coda.', 'static-bridge'));
                        }
                        $job['discovered'] += (int) $added;
                        if ($job['discovered'] > self::MAX_QUEUE_EXPORT_URLS) {
                            return $this->fail_export_queue_job($job, $url, sprintf(/* translators: %s: maximum number of URLs per release */ __('Il sito supera il limite prudenziale di %s URL unici per release; quella parziale non verrà pubblicata.', 'static-bridge'), number_format_i18n(self::MAX_QUEUE_EXPORT_URLS)));
                        }
                        if (!$queue->mark($job_id, $row['url_hash'], 'done')) {
                            return $this->fail_export_queue_job($job, $url, __('La pagina è stata salvata ma non è stato possibile aggiornare lo stato della coda; la release non verrà pubblicata.', 'static-bridge'));
                        }
                    }
                }
                $job['current_url'] = '';
                $job['updated_at'] = time();
                update_option(self::JOB_OPTION, $job, false);
            }

            $pending = $queue->count_pending($job_id);
            if (false === $pending) {
                return $this->fail_export_queue_job($job, '', __('Conteggio della coda indicizzata non riuscito.', 'static-bridge'));
            }
            $job['updated_at'] = time();
            if (!empty($job['discovery_complete']) && 0 === (int) $pending && empty($job['recovery_round'])) {
                $deferred = $queue->count_deferred($job_id);
                if (false === $deferred) {
                    return $this->fail_export_queue_job($job, '', __('Conteggio delle URL rinviate non riuscito.', 'static-bridge'));
                }
                if ($deferred > 0) {
                    // One slow round for the URLs the server rate limited: a minute of rest, then one at a time.
                    if (false === $queue->requeue_deferred($job_id)) {
                        return $this->fail_export_queue_job($job, '', __('Non è stato possibile rimettere in coda le URL rinviate.', 'static-bridge'));
                    }
                    $job['recovery_round'] = 1;
                    $job['retry_not_before'] = time() + self::RATE_LIMIT_RECOVERY_DELAY;
                    update_option(self::JOB_OPTION, $job, false);
                    $this->schedule_export_worker(self::RATE_LIMIT_RECOVERY_DELAY, true);
                    $this->log_activity(
                        __('Giro di recupero delle pagine rallentate dal server.', 'static-bridge'),
                        sprintf(/* translators: %s: number of URLs */ _n('%s URL ha ricevuto HTTP 429 o 503 fino all’ultimo tentativo: fra un minuto viene riprovata lentamente, una alla volta.', '%s URL hanno ricevuto HTTP 429 o 503 fino all’ultimo tentativo: fra un minuto vengono riprovate lentamente, una alla volta.', $deferred, 'static-bridge'), number_format_i18n($deferred)),
                        true
                    );
                    return $job;
                }
            }
            if (!empty($job['discovery_complete']) && 0 === (int) $pending) {
                $job['status'] = 'complete';
                // One issue and one Attività line for the pages saved with cache signals, before the manifest is written.
                $cache_signals = $this->cache_signals_message(isset($job['cache_signals']) ? $job['cache_signals'] : array());
                if ('' !== $cache_signals) {
                    $this->append_export_issue($job, '', $cache_signals);
                    $this->log_activity(__('Pagine salvate con un segnale «non mettere in cache» o con nonce che scadono.', 'static-bridge'), $cache_signals, true);
                }
                $this->publish_release($job);
                if ('complete' !== $job['status']) {
                    $this->cleanup_dependency_index_for_job($job);
                }
                update_option(self::JOB_OPTION, $job, false);
                $queue->delete_job($job_id);
                wp_clear_scheduled_hook('static_bridge_process_export_queue');
                delete_option(self::EXPORT_CONTINUE_OPTION);
                if ('complete' === $job['status']) {
                    $this->forget_incremental_added_routes(isset($job['started_at']) ? (int) $job['started_at'] : 0);
                    $this->remember_rate_limited_routes($job);
                    $route_errors = max(0, (int) ($job['route_errors'] ?? 0));
                    $pages_preserved = max(0, (int) ($job['pages_preserved'] ?? 0));
                    $summary = sprintf(
                        /* translators: 1: number of published HTML pages, 2: number of previous copies kept, 3: number of URLs not updated */ __('%1$s pagine HTML pubblicate; %2$s copie precedenti mantenute; %3$s URL non aggiornate.', 'static-bridge'),
                        number_format_i18n($job['saved']),
                        number_format_i18n($pages_preserved),
                        number_format_i18n($job['skipped'])
                    );
                    if ($route_errors > 0) {
                        $summary .= ' ' . sprintf(/* translators: %s: number of page errors */ __('Errori di pagina registrati: %s. Dettagli in URL da controllare.', 'static-bridge'), number_format_i18n($route_errors));
                    }
                    $this->log_activity(
                        __('Pubblicazione completata.', 'static-bridge'),
                        $summary
                    );
                } else {
                    $this->log_activity(__('Esportazione completata, ma pubblicazione non riuscita.', 'static-bridge'), __('La versione precedente resta attiva. Controlla i permessi per creare collegamenti simbolici.', 'static-bridge'), true);
                }
                return $job;
            }
            update_option(self::JOB_OPTION, $job, false);
            if ('running' === $job['status']) {
                $this->schedule_export_worker(5, true);
            }
            return $job;
        } finally {
            if ($fluent_forms_routing_changed) {
                $this->update_routing_rules();
            }
            $this->release_export_worker_lock($lock_token);
        }
    }

    /** The URLs a published export could not render because of HTTP 429/503, for «Riprova queste» in Genera. */
    private function remember_rate_limited_routes($job)
    {
        $urls = $this->sanitize_public_urls(array_slice((array) ($job['rate_limited_urls'] ?? array()), 0, 100));
        if (empty($urls)) {
            delete_option(self::RATE_LIMITED_ROUTES_OPTION);
            return;
        }
        update_option(self::RATE_LIMITED_ROUTES_OPTION, array(
            'release' => (string) ($job['release_id'] ?? ''),
            'urls' => $urls,
            'at' => time(),
        ), false);
    }

    private function discover_wordpress_post_url_batch($after_id)
    {
        global $wpdb;
        if (!is_object($wpdb) || !isset($wpdb->posts) || !method_exists($wpdb, 'prepare') || !method_exists($wpdb, 'get_results') || !class_exists('WP_Post')) {
            return new WP_Error('static_bridge_discovery_db', __('La connessione WordPress non consente una scansione indicizzata dei contenuti.', 'static-bridge'));
        }
        $posts_table = (string) $wpdb->posts;
        if (!preg_match('/^[A-Za-z0-9_]+$/', $posts_table)) {
            return new WP_Error('static_bridge_discovery_table', __('Il nome della tabella contenuti non è valido.', 'static-bridge'));
        }
        $post_types = $this->exportable_public_post_types();
        if (empty($post_types)) {
            return array('urls' => array(), 'cursor' => (int) $after_id, 'complete' => true);
        }

        $placeholders = implode(',', array_fill(0, count($post_types), '%s'));
        $sql = "SELECT * FROM {$posts_table} WHERE post_status = 'publish' AND post_password = '' AND ID > %d AND post_type IN ({$placeholders}) ORDER BY ID ASC LIMIT %d";
        $arguments = array_merge(array((int) $after_id), $post_types, array(self::WORDPRESS_DISCOVERY_PAGE_SIZE));
        $rows = $wpdb->get_results($wpdb->prepare($sql, $arguments));
        if (!is_array($rows)) {
            return new WP_Error('static_bridge_discovery_query', __('La query a blocchi dell’inventario WordPress non è riuscita.', 'static-bridge'));
        }
        $cursor = (int) $after_id;
        $urls = array();
        $dynamic_urls = array();
        foreach ($rows as $row) {
            if (!is_object($row) || !isset($row->ID) || !is_numeric($row->ID) || (int) $row->ID < 1) {
                continue;
            }
            $post = new WP_Post(sanitize_post($row, 'raw'));
            $cursor = max($cursor, (int) $post->ID);
            $permalink = (string) get_permalink($post);
            $url = $this->normalize_public_url($permalink);
            if ($url) {
                $urls[$url] = $url;
                continue;
            }
            $parts = wp_parse_url($permalink);
            if ($this->same_site_url($permalink) && is_array($parts) && isset($parts['query'])) {
                $dynamic_urls[$permalink] = $permalink;
            }
        }
        return array(
            'urls' => array_values($urls),
            'dynamic_urls' => array_values($dynamic_urls),
            'cursor' => $cursor,
            'complete' => count($rows) < self::WORDPRESS_DISCOVERY_PAGE_SIZE,
        );
    }

    /**
     * Archive inventory of a full export, after the singles, one bounded batch per call. Phases in order:
     * terms (public taxonomies, empty terms too: WordPress answers them 200), front (home or posts page,
     * post type archives), authors, years, months, days, extra (static_bridge_export_urls and the routes
     * the incremental worker created since the last export), done. Each archive brings its /page/N/
     * routes. A route WordPress redirects or answers 404 is dropped by the render, as any other.
     */
    private function discover_wordpress_archive_url_batch($phase, $cursor)
    {
        global $wpdb;
        $phases = array('terms', 'front', 'authors', 'years', 'months', 'days', 'extra', 'done');
        $index = array_search($phase, $phases, true);
        if (false === $index || 'done' === $phase) {
            return array('urls' => array(), 'phase' => 'done', 'cursor' => 0);
        }
        $next = $phases[$index + 1];
        $finished = array('urls' => array(), 'phase' => $next, 'cursor' => 0);
        if ('extra' === $phase) {
            return array('urls' => $this->extra_export_urls(), 'phase' => 'done', 'cursor' => 0);
        }
        if (empty($this->settings()['export_archives'])) {
            return array('urls' => array(), 'phase' => 'extra', 'cursor' => 0);
        }
        $cursor = max(0, (int) $cursor);
        $limit = self::WORDPRESS_DISCOVERY_PAGE_SIZE;

        if ('front' === $phase) {
            $archives = array();
            $listed_types = $this->archive_post_types('front');
            $listed_pages = $this->archive_page_count($this->published_post_count($listed_types));
            if ('posts' === get_option('show_on_front')) {
                $archives[] = array(home_url('/'), $listed_pages);
            }
            $posts_page_id = absint(get_option('page_for_posts'));
            if ($posts_page_id && 'page' === get_option('show_on_front')) {
                $archives[] = array(get_permalink($posts_page_id), $listed_pages);
            }
            foreach ($this->exportable_public_post_types() as $post_type) {
                $object = function_exists('get_post_type_object') ? get_post_type_object($post_type) : null;
                if (!$object || empty($object->has_archive)) {
                    continue;
                }
                $archive_url = get_post_type_archive_link($post_type);
                if ($archive_url) {
                    $archives[] = array($archive_url, $this->archive_page_count($this->published_post_count(array($post_type)), array($post_type)));
                }
            }
            $finished['urls'] = $this->archive_page_urls($archives);
            return $finished;
        }

        if ('terms' === $phase) {
            $taxonomies = $this->archive_taxonomies();
            $table = $this->archive_table('term_taxonomy');
            if (empty($taxonomies) || '' === $table || !function_exists('get_term_link')) {
                return $finished;
            }
            $placeholders = implode(',', array_fill(0, count($taxonomies), '%s'));
            $rows = $wpdb->get_results($wpdb->prepare(
                "SELECT term_taxonomy_id, term_id, taxonomy, count FROM {$table} WHERE term_taxonomy_id > %d AND taxonomy IN ({$placeholders}) ORDER BY term_taxonomy_id ASC LIMIT %d",
                array_merge(array($cursor), $taxonomies, array($limit))
            ));
            if (!is_array($rows)) {
                return new WP_Error('static_bridge_discovery_terms', __('La query a blocchi dei termini per gli archivi non è riuscita.', 'static-bridge'));
            }
            $archives = array();
            foreach ($rows as $row) {
                $cursor = max($cursor, (int) $row->term_taxonomy_id);
                $term_url = get_term_link((int) $row->term_id, (string) $row->taxonomy);
                if (is_string($term_url)) {
                    $archives[] = array($term_url, $this->term_archive_pages((int) $row->term_id, (string) $row->taxonomy, (int) $row->count));
                }
            }
            $complete = count($rows) < $limit;
            return array('urls' => $this->archive_page_urls($archives), 'phase' => $complete ? $next : $phase, 'cursor' => $complete ? 0 : $cursor);
        }

        // Author and date archives list the post types of the main query (only `post` in WordPress).
        $posts_table = $this->archive_table('posts');
        $listed_types = $this->archive_post_types('authors' === $phase ? 'author' : 'date');
        if ('' === $posts_table || empty($listed_types)
            || ('authors' === $phase ? !function_exists('get_author_posts_url') : !function_exists('get_day_link'))) {
            return $finished;
        }
        $type_placeholders = implode(',', array_fill(0, count($listed_types), '%s'));
        $keys = array(
            'authors' => 'post_author',
            'years' => 'YEAR(post_date)',
            'months' => 'YEAR(post_date) * 100 + MONTH(post_date)',
            'days' => 'YEAR(post_date) * 10000 + MONTH(post_date) * 100 + DAYOFMONTH(post_date)',
        );
        $rows = $wpdb->get_results($wpdb->prepare(
            "SELECT {$keys[$phase]} AS archive_key, COUNT(*) AS posts FROM {$posts_table} WHERE post_status = 'publish' AND post_type IN ({$type_placeholders}) GROUP BY archive_key HAVING archive_key > %d ORDER BY archive_key ASC LIMIT %d",
            array_merge($listed_types, array($cursor, $limit))
        ));
        if (!is_array($rows)) {
            return new WP_Error('static_bridge_discovery_dates', __('La query a blocchi degli archivi per autore e per data non è riuscita.', 'static-bridge'));
        }
        $archives = array();
        foreach ($rows as $row) {
            $key = (int) $row->archive_key;
            $cursor = max($cursor, $key);
            if ($key < 1) {
                continue;
            }
            if ('authors' === $phase) {
                $archive_url = get_author_posts_url($key);
            } elseif ('years' === $phase) {
                $archive_url = get_year_link($key);
            } elseif ('months' === $phase) {
                $archive_url = get_month_link(intdiv($key, 100), $key % 100);
            } else {
                $archive_url = get_day_link(intdiv($key, 10000), intdiv($key, 100) % 100, $key % 100);
            }
            $archives[] = array($archive_url, $this->archive_page_count((int) $row->posts));
        }
        $complete = count($rows) < $limit;
        return array('urls' => $this->archive_page_urls($archives), 'phase' => $complete ? $next : $phase, 'cursor' => $complete ? 0 : $cursor);
    }

    /** Routes other plugins add to a full export (Lingua: /en/category/…) and those created incrementally. */
    private function extra_export_urls()
    {
        $urls = array();
        $added = apply_filters('static_bridge_export_urls', array());
        $candidates = is_array($added) ? array_slice(array_values(array_filter($added, 'is_string')), 0, self::MAX_QUEUE_EXPORT_URLS) : array();
        foreach (array_keys($this->incremental_added_routes()) as $path) {
            $candidates[] = home_url($path);
        }
        foreach ($candidates as $candidate) {
            $url = $this->normalize_public_url($candidate);
            if ($url) {
                $urls[$url] = $url;
            }
        }
        return array_values($urls);
    }

    /**
     * Routes the incremental worker created in the current release, path => time. A full export seeds
     * them, so a list written by the worker is not dropped by the next export when no page links to it.
     */
    private function incremental_added_routes()
    {
        $routes = get_option(self::INCREMENTAL_ADDED_ROUTES_OPTION, array());
        return is_array($routes) ? $routes : array();
    }

    private function remember_incremental_added_route($path)
    {
        $path = $this->normalize_route_path($path);
        if ('' === $path) {
            return;
        }
        $routes = $this->incremental_added_routes();
        unset($routes[$path]);
        $routes[$path] = time();
        if (count($routes) > self::MAX_INCREMENTAL_ADDED_ROUTES) {
            $routes = array_slice($routes, -self::MAX_INCREMENTAL_ADDED_ROUTES, null, true);
        }
        update_option(self::INCREMENTAL_ADDED_ROUTES_OPTION, $routes, false);
    }

    /** After a full export, keep only the routes created while it ran: it may not have seen them. */
    private function forget_incremental_added_routes($before)
    {
        $routes = array_filter($this->incremental_added_routes(), function ($time) use ($before) {
            return (int) $time >= (int) $before;
        });
        if (empty($routes)) {
            delete_option(self::INCREMENTAL_ADDED_ROUTES_OPTION);
        } else {
            update_option(self::INCREMENTAL_ADDED_ROUTES_OPTION, $routes, false);
        }
    }

    private function archive_table($name)
    {
        global $wpdb;
        $table = is_object($wpdb) && isset($wpdb->{$name}) ? (string) $wpdb->{$name} : '';
        return method_exists($wpdb, 'get_results') && preg_match('/^[A-Za-z0-9_]+$/', $table) ? $table : '';
    }

    private function archive_taxonomies()
    {
        $taxonomies = function_exists('get_taxonomies') ? get_taxonomies(array('public' => true, 'publicly_queryable' => true), 'names') : array();
        return array_values(array_filter(is_array($taxonomies) ? $taxonomies : array(), function ($taxonomy) {
            return is_string($taxonomy) && (bool) preg_match('/^[A-Za-z0-9_-]{1,32}$/', $taxonomy);
        }));
    }

    /** Post types the home, author and date archives list ($context: front, author, date). */
    private function archive_post_types($context)
    {
        $types = apply_filters('static_bridge_archive_post_types', array('post'), $context);
        return array_values(array_intersect(is_array($types) ? $types : array(), $this->exportable_public_post_types()));
    }

    /** Posts and pages changed after the current release was published (the plugin was off, or a restore). */
    private function content_changes_since_release()
    {
        global $wpdb;
        $last = get_option('static_bridge_last_release', array());
        $published_at = is_array($last) && isset($last['published_at']) ? (int) $last['published_at'] : 0;
        $post_types = $this->exportable_public_post_types();
        if ($published_at <= 0 || empty($post_types) || !is_object($wpdb) || !isset($wpdb->posts)) {
            return 0;
        }
        $placeholders = implode(',', array_fill(0, count($post_types), '%s'));
        $since = gmdate('Y-m-d H:i:s', $published_at);
        // wp_publish_post() (a scheduled post going live) changes the status without touching post_modified.
        $count = $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$wpdb->posts} WHERE (post_modified_gmt > %s OR (post_status = 'publish' AND post_date_gmt > %s)) AND post_status NOT IN ('auto-draft', 'inherit') AND post_type IN ($placeholders)",
            array_merge(array($since, $since), $post_types)
        ));
        // A new permalink structure moves every route without changing any post.
        $structure_changed = isset($last['permalink_structure']) && (string) $last['permalink_structure'] !== (string) get_option('permalink_structure', '');
        return max(0, (int) $count) + ($structure_changed ? 1 : 0);
    }

    /**
     * The public content at deactivation, by ID. Reactivation compares it with the content public then
     * and so finds what was deleted, withdrawn or moved meanwhile even when its route is gone (doc 23,
     * item 169). Nothing is stored without a release or past DEACTIVATION_SNAPSHOT_LIMIT posts.
     */
    private function remember_public_content_at_deactivation()
    {
        delete_option(self::DEACTIVATION_SNAPSHOT_OPTION);
        $release = $this->current_release();
        $ids = '' !== $release ? $this->public_content_ids() : null;
        if (is_array($ids)) {
            update_option(self::DEACTIVATION_SNAPSHOT_OPTION, array('release' => basename($release), 'at' => time(), 'ids' => implode(',', $ids)), false);
        }
    }

    /** IDs of the public posts and pages (published, without a password); null when unreadable or too many. */
    private function public_content_ids()
    {
        global $wpdb;
        if (!is_object($wpdb) || !isset($wpdb->posts) || !method_exists($wpdb, 'prepare') || !method_exists($wpdb, 'get_col')
            || !preg_match('/^[A-Za-z0-9_]+$/', (string) $wpdb->posts)) {
            return null;
        }
        $post_types = $this->exportable_public_post_types();
        if (empty($post_types)) {
            return array();
        }
        $placeholders = implode(',', array_fill(0, count($post_types), '%s'));
        $ids = $wpdb->get_col($wpdb->prepare(
            "SELECT ID FROM {$wpdb->posts} WHERE post_status = 'publish' AND post_password = '' AND post_type IN ($placeholders) ORDER BY ID ASC LIMIT %d",
            array_merge($post_types, array(self::DEACTIVATION_SNAPSHOT_LIMIT + 1))
        ));
        if (!is_array($ids) || count($ids) > self::DEACTIVATION_SNAPSHOT_LIMIT) {
            return null;
        }
        return array_values(array_unique(array_filter(array_map('absint', $ids))));
    }

    /**
     * On reactivation, removes from the current release the static copies of the content that stopped
     * being public while the plugin was off (draft, pending, scheduled, private, password, trash, deleted):
     * no hook saw those changes, and the release would serve the copies again (doc 23, item 169).
     *
     * Candidates are the posts changed after the release that are not public now, and the posts public at
     * deactivation that no longer are. A copy is looked for at the route the post had when public (for a
     * trashed post, with the slug it had before the trash) and at its translations. What cannot be settled
     * goes into `unresolved`, and the caller keeps the routing off until a full export: a post deleted
     * meanwhile (its route is gone with it), a post public at deactivation whose copy is not at its route
     * (moved meanwhile), a copy or a manifest that cannot be written.
     *
     * @return array{removed: string[], unresolved: string[], deleted: int, dependents: string[]}
     */
    private function remove_withdrawn_static_copies($release)
    {
        global $wpdb;
        $result = array('removed' => array(), 'unresolved' => array(), 'deleted' => 0, 'dependents' => array());
        $post_types = $this->exportable_public_post_types();
        if ('' === (string) $release || empty($post_types) || !is_object($wpdb) || !isset($wpdb->posts)
            || !method_exists($wpdb, 'prepare') || !method_exists($wpdb, 'get_col') || !preg_match('/^[A-Za-z0-9_]+$/', (string) $wpdb->posts)) {
            return $result;
        }
        $last = get_option('static_bridge_last_release', array());
        $since = is_array($last) && isset($last['published_at']) ? (int) $last['published_at'] : 0;
        $candidates = array();
        if ($since > 0) {
            $placeholders = implode(',', array_fill(0, count($post_types), '%s'));
            $changed = $wpdb->get_col($wpdb->prepare(
                "SELECT ID FROM {$wpdb->posts} WHERE post_modified_gmt > %s AND (post_status NOT IN ('publish', 'auto-draft', 'inherit') OR post_password <> '') AND post_type IN ($placeholders) ORDER BY ID ASC LIMIT %d",
                array_merge(array(gmdate('Y-m-d H:i:s', $since)), $post_types, array(self::WITHDRAWN_ON_ACTIVATION_LIMIT + 1))
            ));
            foreach (is_array($changed) ? $changed : array() as $post_id) {
                $candidates[absint($post_id)] = false;
            }
        }
        $snapshot = get_option(self::DEACTIVATION_SNAPSHOT_OPTION, array());
        if (is_array($snapshot) && isset($snapshot['release'], $snapshot['ids']) && basename((string) $release) === (string) $snapshot['release']) {
            $public_now = $this->public_content_ids();
            if (null === $public_now) {
                $result['unresolved'][] = __('contenuti pubblici non confrontabili con quelli alla disattivazione', 'static-bridge');
                return $result;
            }
            $was_public = array_filter(array_map('absint', explode(',', (string) $snapshot['ids'])));
            foreach (array_diff($was_public, $public_now) as $post_id) {
                $candidates[(int) $post_id] = true;
            }
        }
        unset($candidates[0]);
        if (count($candidates) > self::WITHDRAWN_ON_ACTIVATION_LIMIT) {
            $result['unresolved'][] = sprintf(/* translators: %s: maximum number of posts */ __('più di %s contenuti non più pubblici', 'static-bridge'), number_format_i18n(self::WITHDRAWN_ON_ACTIVATION_LIMIT));
            return $result;
        }
        $incremental = !empty($this->settings()['incremental_enabled']);
        $to_remove = array();
        $dependents = array();
        foreach ($candidates as $post_id => $was_public) {
            $post = get_post($post_id);
            if (!is_object($post) || empty($post->ID)) {
                $result['deleted']++;
                $result['unresolved'][] = '#' . $post_id;
                continue;
            }
            if ('publish' === $post->post_status && '' === (string) $post->post_password && in_array($post->post_type, $post_types, true)) {
                continue;
            }
            $former = $this->former_route_paths($post);
            $found = array();
            $excluded = false;
            foreach ($this->with_translated_urls(array_map('home_url', $former['paths'])) as $url) {
                $path = $this->normalize_route_path($url);
                if ('' === $path) {
                    continue;
                }
                $excluded = $excluded || $this->is_excluded_path($path);
                if ($this->static_file_exists_for_path($path)) {
                    $found[$path] = $url;
                }
            }
            if (empty($found)) {
                // Public at deactivation but no copy at its route: it moved while the plugin was off, unless it
                // was never exported (an excluded route, or published after the release without incremental updates).
                $published_after = isset($post->post_date_gmt) && $since > 0 && (string) $post->post_date_gmt > gmdate('Y-m-d H:i:s', $since);
                if ($was_public && !$excluded && ($incremental || !$published_after)) {
                    $result['unresolved'][] = '#' . $post_id;
                }
                continue;
            }
            $to_remove = array_merge($to_remove, $found);
            $dependents = array_merge($dependents, $this->archive_urls_for_post($former['post']));
        }
        $deleted_files = 0;
        foreach ($to_remove as $path => $url) {
            $removed = $this->remove_incremental_page($release, $url);
            if (is_wp_error($removed)) {
                $result['unresolved'][] = $path;
                continue;
            }
            if (!empty($removed['deleted'])) {
                $deleted_files++;
                $result['removed'][] = $url;
            }
        }
        // On Apache a new served copy follows a changed manifest: unchanged, the rules would keep the copy with the pages.
        if ($deleted_files > 0 && !$this->update_incremental_manifest($release, -$deleted_files)) {
            $result['unresolved'][] = 'manifest.json';
        }
        if (!empty($result['removed']) || $result['deleted'] > 0) {
            $dependents = array_merge($dependents, array(home_url('/')), $this->discover_query_page_urls());
            $result['dependents'] = array_values(array_unique(array_filter($dependents, 'is_string')));
        }
        return $result;
    }

    /**
     * The routes $post had while public: its permalink as published (for a trashed post with the slug it had
     * before the trash) and its permalink now, which a private or password-protected post keeps.
     *
     * @return array{paths: string[], post: object}
     */
    private function former_route_paths($post)
    {
        $public = clone $post;
        $public->post_status = 'publish';
        $public->post_password = '';
        if ('trash' === $post->post_status) {
            $desired = get_post_meta((int) $post->ID, '_wp_desired_post_slug', true);
            $public->post_name = is_string($desired) && '' !== $desired
                ? $desired
                : (string) preg_replace('/__trashed(?:-[0-9]+)?$/', '', (string) $post->post_name);
        }
        $paths = array();
        foreach (array(get_permalink($public), get_permalink($post)) as $url) {
            $path = is_string($url) ? $this->normalize_route_path($url) : '';
            if ('' !== $path) {
                $paths[$path] = $path;
            }
        }
        return array('paths' => array_values($paths), 'post' => $public);
    }

    /** True while the current release must not be served static: see ROUTING_HOLD_OPTION. */
    private function routing_held()
    {
        $hold = get_option(self::ROUTING_HOLD_OPTION, array());
        if (!is_array($hold) || empty($hold['release'])) {
            return false;
        }
        $release = $this->current_release();
        return '' !== $release && basename($release) === (string) $hold['release'];
    }

    private function stale_release_pending()
    {
        $stale = get_option(self::STALE_RELEASE_OPTION, array());
        return is_array($stale) && !empty($stale['release']) && (bool) $this->current_release();
    }

    public function render_stale_release_notice()
    {
        if (current_user_can('manage_options') && $this->routing_held()) {
            echo '<div class="notice notice-error"><p>' . esc_html__('Static Bridge non serve pagine statiche: mentre il plugin era disattivato un contenuto pubblico è stato eliminato o spostato, e la sua copia statica potrebbe essere ancora nell’ultimo export. Il sito resta gestito da WordPress finché non avvii un export completo.', 'static-bridge')
                . ' <a href="' . esc_url(admin_url('admin.php?page=' . self::ADMIN_SLUG)) . '">' . esc_html__('Apri Static Bridge', 'static-bridge') . '</a></p></div>';
            return;
        }
        if (!current_user_can('manage_options') || !$this->stale_release_pending()) {
            return;
        }
        $stale = get_option(self::STALE_RELEASE_OPTION, array());
        $changes = max(1, (int) ($stale['changes'] ?? 1));
        echo '<div class="notice notice-warning"><p>' . esc_html(sprintf(
            /* translators: %s: number of changed posts and pages */
            _n('Static Bridge serve le pagine dell’ultimo export, ma %s contenuto è cambiato mentre il plugin era disattivato. La modalità strict resta spenta finché non avvii un export completo.', 'Static Bridge serve le pagine dell’ultimo export, ma %s contenuti sono cambiati mentre il plugin era disattivato. La modalità strict resta spenta finché non avvii un export completo.', $changes, 'static-bridge'),
            number_format_i18n($changes)
        )) . ' <a href="' . esc_url(admin_url('admin.php?page=' . self::ADMIN_SLUG)) . '">' . esc_html__('Apri Static Bridge', 'static-bridge') . '</a></p></div>';
    }

    private function published_post_count($post_types)
    {
        $count = 0;
        foreach ((array) $post_types as $post_type) {
            $counts = function_exists('wp_count_posts') ? wp_count_posts($post_type) : null;
            $count += is_object($counts) && isset($counts->publish) ? (int) $counts->publish : 0;
        }
        return $count;
    }

    /** Pages of an archive listing $posts posts, capped by static_bridge_archive_max_pages (default 100). */
    private function archive_page_count($posts, $post_types = array())
    {
        $per_page = $this->archive_per_page($post_types);
        if ($per_page < 1) {
            return 1;
        }
        $max = (int) apply_filters('static_bridge_archive_max_pages', self::DEFAULT_ARCHIVE_MAX_PAGES);
        return max(1, min(max(1, $max), (int) ceil(max(0, (int) $posts) / $per_page)));
    }

    /**
     * Items on one page of a list of these post types. WooCommerce lists products with its own number per page
     * (loop_shop_per_page, 16 by default), a block theme with the one of its product block: the smaller of the two
     * gives every page that may exist, and a page past the last answers 404 and is never written.
     */
    private function archive_per_page($post_types)
    {
        $per_page = (int) get_option('posts_per_page', 10);
        if (in_array('product', (array) $post_types, true) && function_exists('wc_get_default_products_per_row') && function_exists('wc_get_default_product_rows_per_page')) {
            $shop_per_page = (int) apply_filters('loop_shop_per_page', wc_get_default_products_per_row() * wc_get_default_product_rows_per_page());
            if ($shop_per_page > 0 && ($per_page < 1 || $shop_per_page < $per_page)) {
                $per_page = $shop_per_page;
            }
        }
        return $per_page;
    }

    /** A category also lists the posts of its descendants: count them once each. */
    private function term_archive_pages($term_id, $taxonomy, $count)
    {
        global $wpdb;
        $taxonomy_object = function_exists('get_taxonomy') ? get_taxonomy($taxonomy) : null;
        $children = $taxonomy_object && !empty($taxonomy_object->hierarchical) && function_exists('get_term_children')
            ? get_term_children((int) $term_id, $taxonomy)
            : array();
        $relationships = $this->archive_table('term_relationships');
        $term_taxonomy = $this->archive_table('term_taxonomy');
        $posts_table = $this->archive_table('posts');
        $object_types = $taxonomy_object && isset($taxonomy_object->object_type)
            ? array_values(array_intersect((array) $taxonomy_object->object_type, $this->exportable_public_post_types()))
            : array();
        if (!is_array($children) || empty($children) || '' === $relationships || '' === $term_taxonomy || '' === $posts_table || empty($object_types)) {
            return $this->archive_page_count($count, $object_types);
        }
        $term_ids = array_slice(array_values(array_unique(array_map('intval', array_merge(array($term_id), $children)))), 0, 1000);
        $sql = "SELECT COUNT(DISTINCT tr.object_id) FROM {$relationships} tr"
            . " INNER JOIN {$term_taxonomy} tt ON tt.term_taxonomy_id = tr.term_taxonomy_id"
            . " INNER JOIN {$posts_table} p ON p.ID = tr.object_id"
            . ' WHERE tt.taxonomy = %s AND tt.term_id IN (' . implode(',', array_fill(0, count($term_ids), '%d')) . ')'
            . " AND p.post_status = 'publish' AND p.post_type IN (" . implode(',', array_fill(0, count($object_types), '%s')) . ')';
        $total = $wpdb->get_var($wpdb->prepare($sql, array_merge(array($taxonomy), $term_ids, $object_types)));
        return $this->archive_page_count(is_numeric($total) ? max((int) $total, (int) $count) : $count, $object_types);
    }

    private function date_archive_post_count($post_types, $year, $month = 0, $day = 0)
    {
        global $wpdb;
        $posts_table = $this->archive_table('posts');
        if ('' === $posts_table || empty($post_types) || !method_exists($wpdb, 'get_var')) {
            return 0;
        }
        $start = gmmktime(0, 0, 0, $month ? $month : 1, $day ? $day : 1, $year);
        $end = $day ? gmmktime(0, 0, 0, $month, $day + 1, $year) : ($month ? gmmktime(0, 0, 0, $month + 1, 1, $year) : gmmktime(0, 0, 0, 1, 1, $year + 1));
        $total = $wpdb->get_var($wpdb->prepare(
            "SELECT COUNT(*) FROM {$posts_table} WHERE post_status = 'publish' AND post_type IN (" . implode(',', array_fill(0, count($post_types), '%s')) . ') AND post_date >= %s AND post_date < %s',
            array_merge(array_values($post_types), array(gmdate('Y-m-d H:i:s', $start), gmdate('Y-m-d H:i:s', $end)))
        ));
        return is_numeric($total) ? (int) $total : 0;
    }

    /** WordPress's search base (/search/term/): search results are always dynamic. */
    private function search_base()
    {
        global $wp_rewrite;
        $base = is_object($wp_rewrite) && isset($wp_rewrite->search_base) ? (string) $wp_rewrite->search_base : 'search';
        return preg_match('/^[A-Za-z0-9_-]{1,64}$/', $base) ? $base : 'search';
    }

    /**
     * With permalinks ending in a slash, /x is WordPress's 301 to /x/: the server rules serve only /x/,
     * so the redirect (and a language plugin's prefix) is not skipped by a copy.
     */
    private function routes_require_trailing_slash()
    {
        $structure = (string) get_option('permalink_structure', '');
        return '' === $structure || '/' === substr($structure, -1);
    }

    /** The URL WordPress links for a route path (/x/ or /x, as the permalink structure says): what a probe must request. */
    private function route_url($path)
    {
        $path = '/' . ltrim((string) $path, '/');
        if ('/' !== $path) {
            $path = $this->routes_require_trailing_slash() ? trailingslashit($path) : untrailingslashit($path);
        }
        return home_url($path);
    }

    /** Permalinks like /%postname%.html (no trailing slash then): a .html route is a page, not a file. */
    private function routes_end_in_html()
    {
        return '.html' === strtolower(substr((string) get_option('permalink_structure', ''), -5));
    }

    /** The extension test that sends files to WordPress; in .html mode it leaves .html routes alone. */
    private function file_extension_pattern()
    {
        return $this->routes_end_in_html() ? '\\.(?!html$)[A-Za-z0-9]{1,8}$' : '\\.[A-Za-z0-9]{1,8}$';
    }

    private function pagination_base()
    {
        global $wp_rewrite;
        $base = is_object($wp_rewrite) && isset($wp_rewrite->pagination_base) ? (string) $wp_rewrite->pagination_base : 'page';
        return preg_match('/^[A-Za-z0-9_-]{1,64}$/', $base) ? $base : 'page';
    }

    /** Page 1 and /page/2/…/page/N/ of each archive; array($url, $pages) pairs in, unique URLs out. */
    private function archive_page_urls($archives)
    {
        $urls = array();
        foreach ($archives as $archive) {
            $base = $this->normalize_public_url($archive[0]);
            if (!$base) {
                continue;
            }
            $urls[$base] = $base;
            for ($page = 2; $page <= (int) $archive[1]; $page++) {
                $url = $this->normalize_public_url(trailingslashit($base) . $this->pagination_base() . '/' . $page . '/');
                if ($url) {
                    $urls[$url] = $url;
                }
            }
        }
        return array_values($urls);
    }

    /** Pages of $base_url in the current release past $pages: refreshed, they are removed if gone. */
    private function release_archive_pages_beyond($base_url, $pages)
    {
        $release = $this->current_release();
        $base = $this->normalize_public_url($base_url);
        $relative = $release && $base ? $this->relative_html_path($base) : '';
        if (!$release || !$base || is_wp_error($relative)) {
            return array();
        }
        $directory = trailingslashit($release) . ('index.html' === $relative ? '' : trailingslashit(dirname($relative))) . $this->pagination_base();
        $entries = is_dir($directory) && !is_link($directory) ? scandir($directory) : false;
        $urls = array();
        foreach (is_array($entries) ? $entries : array() as $entry) {
            if (preg_match('/^[1-9][0-9]{0,5}$/', $entry) && (int) $entry > $pages && is_file($directory . '/' . $entry . '/index.html')) {
                $url = $this->normalize_public_url(trailingslashit($base) . $this->pagination_base() . '/' . $entry . '/');
                if ($url) {
                    $urls[(int) $entry] = $url;
                }
            }
        }
        ksort($urls);
        return array_slice(array_values($urls), 0, self::DEFAULT_ARCHIVE_MAX_PAGES);
    }

    /** A linked /page/N/ beyond static_bridge_archive_max_pages stays dynamic, so endless pagination cannot fill the queue. */
    private function within_archive_page_cap($url)
    {
        if (!preg_match('~/' . preg_quote($this->pagination_base(), '~') . '/([1-9][0-9]*)/?$~', (string) wp_parse_url((string) $url, PHP_URL_PATH), $match)) {
            return true;
        }
        $max = (int) apply_filters('static_bridge_archive_max_pages', self::DEFAULT_ARCHIVE_MAX_PAGES);
        return strlen($match[1]) <= 6 && (int) $match[1] <= max(1, $max);
    }

    private function is_archive_page_past_end($url, $error)
    {
        $status = is_wp_error($error) ? $error->get_error_data() : null;
        $not_found = is_numeric($status) ? 404 === (int) $status : (is_wp_error($error) && preg_match('/\b404\b/', $error->get_error_message()));
        return $not_found && (bool) preg_match(
            '~/' . preg_quote($this->pagination_base(), '~') . '/[1-9][0-9]*/?$~',
            (string) wp_parse_url((string) $url, PHP_URL_PATH)
        );
    }

    /**
     * Precompressed copies (2.3.0): with the option on and without SSI header fragments, index.html.gz sits next to
     * index.html and the web server hands it to clients that accept gzip. A .gz is never older than its page: every
     * writer removes it before replacing the page and writes it again after, so a crash in between leaves no .gz.
     */
    private function precompressed_pages_enabled($header_fragments = false)
    {
        return !$header_fragments && !$this->nginx_ssi_enabled() && function_exists('gzencode')
            && !$this->server_compresses_static_files() && !empty($this->settings()['precompressed_pages']);
    }

    /**
     * LiteSpeed (Enterprise and OpenLiteSpeed) compresses static files itself, with gzip and Brotli, and keeps the
     * compressed copy: a .gz of ours adds nothing there, and OpenLiteSpeed ignores the <If> and Header directives
     * that would serve it with Content-Encoding.
     */
    private function server_compresses_static_files()
    {
        return in_array($this->web_server_kind(), array('openlitespeed', 'litespeed'), true);
    }

    /** Removes the .gz of a page (a link as a link). False only when one is there and cannot be removed. */
    private function drop_precompressed_copy($html_path)
    {
        $compressed = $html_path . '.gz';
        if (!file_exists($compressed) && !is_link($compressed)) {
            return true;
        }
        return @unlink($compressed) && !file_exists($compressed) && !is_link($compressed);
    }

    /** Writes index.html.gz after its page, with a temporary file and rename(); on any failure there is simply no .gz. */
    private function write_precompressed_copy($html_path, $body, $header_fragments = false)
    {
        if (!$this->precompressed_pages_enabled($header_fragments)) {
            return false;
        }
        $compressed = gzencode((string) $body, 9);
        $temporary = $html_path . '.gz.tmp-' . strtolower(wp_generate_password(8, false, false));
        if (!is_string($compressed) || file_exists($temporary) || is_link($temporary)) {
            return false;
        }
        if (strlen($compressed) !== @file_put_contents($temporary, $compressed, LOCK_EX)) {
            @unlink($temporary);
            return false;
        }
        @chmod($temporary, 0644);
        if (!@rename($temporary, $html_path . '.gz')) {
            @unlink($temporary);
            return false;
        }
        return true;
    }

    private function write_export_page($job, $relative, $body, $url = '')
    {
        // 2.5.0: no relative-date marker is ever written, whatever path the HTML took.
        $body = $this->strip_relative_date_markers($this->rewrite_internal_origins_as_root_relative((string) $body));
        $stage_root = realpath($job['stage']);
        if (!$stage_root) {
            return new WP_Error('static_bridge_stage_missing', __('La cartella temporanea non è più disponibile.', 'static-bridge'));
        }
        if (!empty($job['header_fragments_active'])) {
            $body = $this->fragment_elementor_header($stage_root, $url, $body);
            if (is_wp_error($body)) {
                return $body;
            }
        } elseif (!empty($job['guard_ssi_content']) && Static_Bridge_Header_Fragments::contains_ssi_directive($body)) {
            return new WP_Error('static_bridge_ssi_source', __('La route contiene una direttiva SSI non generata da Static Bridge; la release non verrà pubblicata.', 'static-bridge'));
        }
        $minimum_free_space = $this->minimum_free_disk_space_bytes();
        if (!$this->has_sufficient_export_disk_space($stage_root, $minimum_free_space, strlen($body))) {
            return new WP_Error('static_bridge_disk_space', $this->insufficient_disk_space_message($minimum_free_space));
        }
        $destination = trailingslashit($stage_root) . $relative;
        if (!wp_mkdir_p(dirname($destination))) {
            return new WP_Error('static_bridge_directory_write', __('Non è stato possibile creare la cartella HTML nella release.', 'static-bridge'));
        }
        $parent = realpath(dirname($destination));
        $inside_stage = $parent && (0 === strpos(trailingslashit($parent), trailingslashit($stage_root)) || $parent === $stage_root);
        $temporary = $destination . '.tmp-' . strtolower(wp_generate_password(8, false, false));
        $written = $inside_stage && !is_link($temporary)
            ? @file_put_contents($temporary, $body, LOCK_EX)
            : false;
        $write_ok = strlen($body) === $written;
        if ($write_ok) {
            @chmod($temporary, 0644);
            $write_ok = $this->drop_precompressed_copy($destination) && @rename($temporary, $destination);
        }
        if (!$write_ok) {
            if (file_exists($temporary) || is_link($temporary)) {
                @unlink($temporary);
            }
            return new WP_Error('static_bridge_write', __('Scrittura sicura del file HTML non riuscita.', 'static-bridge'));
        }
        $this->write_precompressed_copy($destination, $body, !empty($job['header_fragments_active']));
        return true;
    }

    /** Replace only a verified Elementor header and publish its fragment safely. */
    private function fragment_elementor_header($release_root, $url, $body)
    {
        if (!is_string($body) || Static_Bridge_Header_Fragments::contains_ssi_directive($body)) {
            return new WP_Error('static_bridge_ssi_source', __('HTML o contenuto Elementor contiene una direttiva SSI preesistente; il file non è stato pubblicato.', 'static-bridge'));
        }
        $header = Static_Bridge_Header_Fragments::extract_unique_elementor_header($body);
        if (!is_array($header)) {
            if (preg_match('~\bdata-elementor-type\s*=\s*(["\'])header\1~i', $body)
                || false !== strpos($body, 'elementor-location-header')) {
                return new WP_Error('static_bridge_ssi_header_ambiguous', __('L’header Elementor non è univoco o non è estraibile senza alterare l’HTML; la route non è stata pubblicata.', 'static-bridge'));
            }
            return $body;
        }

        $route_path = $this->normalize_route_path($url);
        if ('' === $route_path) {
            return new WP_Error('static_bridge_ssi_header_path', __('Il percorso di contesto dell’header non è valido.', 'static-bridge'));
        }
        if (!Static_Bridge_Header_Fragments::document_is_context_independent($header['owner_id'])) {
            // Keep the route self-contained; later saves use the ordinary
            // dependency fan-out because this document is not fragment-safe.
            return $body;
        }
        $fragment_index = new Static_Bridge_Header_Fragment_Index();
        $variant = $fragment_index->register_variant(basename($release_root), $header['owner_id'], $header['markup'], $route_path);
        if (!is_array($variant) || empty($variant['file_name'])) {
            return new WP_Error('static_bridge_ssi_index', __('Non è stato possibile registrare in modo sicuro la variante dell’header.', 'static-bridge'));
        }

        $write_result = $this->write_header_fragment_file(
            $release_root,
            $header['owner_id'],
            (string) $variant['file_name'],
            (string) $header['markup'],
            (string) $variant['markup_hash']
        );
        if (is_wp_error($write_result)) {
            return $write_result;
        }

        $transformed = Static_Bridge_Header_Fragments::replace_header_with_include(
            $body,
            $header,
            $header['owner_id'],
            $variant['variant_id']
        );
        if (!is_string($transformed)) {
            return new WP_Error('static_bridge_ssi_transform', __('La conversione dell’header in include SSI non ha superato la verifica byte-per-byte.', 'static-bridge'));
        }
        return $transformed;
    }

    /** Write a new, immutable variant into a staged or currently active generation. */
    private function write_header_fragment_file($release_root, $document_id, $file_name, $markup, $markup_hash)
    {
        $release_root = realpath((string) $release_root);
        $expected_file = Static_Bridge_Header_Fragments::include_filename((string) $document_id, (string) $markup_hash);
        if (!$release_root || !is_string($expected_file) || $expected_file !== (string) $file_name
            || !is_string($markup) || '' === $markup || Static_Bridge_Header_Fragments::contains_ssi_directive($markup)) {
            return new WP_Error('static_bridge_ssi_file', __('Identità o contenuto del frammento Elementor non validi.', 'static-bridge'));
        }
        $headers_root = trailingslashit($release_root) . 'fragments/headers';
        $document_directory = trailingslashit($headers_root) . $document_id;
        $generations_directory = trailingslashit($document_directory) . 'generations';
        foreach (array($headers_root, $document_directory, $generations_directory) as $directory) {
            if (is_link($directory) || (file_exists($directory) && !is_dir($directory))) {
                return new WP_Error('static_bridge_ssi_path', __('Il percorso delle varianti header non è una directory sicura.', 'static-bridge'));
            }
            if (!is_dir($directory) && !wp_mkdir_p($directory)) {
                return new WP_Error('static_bridge_ssi_directory', __('Non è possibile creare la directory delle varianti header.', 'static-bridge'));
            }
            $real_directory = realpath($directory);
            if (!$real_directory || (0 !== strpos(trailingslashit($real_directory), trailingslashit($release_root))
                && $real_directory !== $release_root)) {
                return new WP_Error('static_bridge_ssi_escape', __('La directory delle varianti header esce dalla release.', 'static-bridge'));
            }
        }

        $lock = $this->acquire_header_fragment_lock($document_directory);
        if (!is_resource($lock)) {
            return new WP_Error('static_bridge_ssi_lock', __('Non è stato possibile bloccare in modo esclusivo il documento header.', 'static-bridge'));
        }
        try {
            $current_link = trailingslashit($document_directory) . 'current';
            if (file_exists($current_link) || is_link($current_link)) {
                if (!is_link($current_link)) {
                    return new WP_Error('static_bridge_ssi_pointer', __('Il puntatore della generazione header non è un collegamento simbolico.', 'static-bridge'));
                }
                $target = readlink($current_link);
                if (!is_string($target) || !preg_match('~\Agenerations/(?:initial|generation-[a-f0-9]{24})\z~D', $target)) {
                    return new WP_Error('static_bridge_ssi_pointer', __('Il puntatore della generazione header esce dal percorso privato.', 'static-bridge'));
                }
                $active_directory = realpath(trailingslashit($document_directory) . $target);
            } else {
                if ($release_root === $this->current_release()) {
                    return new WP_Error('static_bridge_ssi_pointer', __('Manca il puntatore attivo delle varianti header della release pubblicata.', 'static-bridge'));
                }
                $initial_directory = trailingslashit($generations_directory) . 'initial';
                if (is_link($initial_directory) || (file_exists($initial_directory) && !is_dir($initial_directory))) {
                    return new WP_Error('static_bridge_ssi_pointer', __('La generazione iniziale header non è sicura.', 'static-bridge'));
                }
                if (!is_dir($initial_directory) && !wp_mkdir_p($initial_directory)) {
                    return new WP_Error('static_bridge_ssi_directory', __('Non è possibile creare la generazione iniziale header.', 'static-bridge'));
                }
                $active_directory = realpath($initial_directory);
            }
            $real_generations = realpath($generations_directory);
            if (!$active_directory || !$real_generations || dirname($active_directory) !== $real_generations
                || is_link($active_directory)) {
                return new WP_Error('static_bridge_ssi_pointer', __('La generazione header attiva non è una directory diretta e verificabile.', 'static-bridge'));
            }
            $destination = trailingslashit($active_directory) . $file_name;
            if (is_link($destination) || (file_exists($destination) && !is_file($destination))) {
                return new WP_Error('static_bridge_ssi_file', __('Il file della variante header esistente non è regolare.', 'static-bridge'));
            }
            if (is_file($destination)) {
                $current_hash = @hash_file('sha256', $destination);
                if (is_string($current_hash) && hash_equals((string) $markup_hash, $current_hash)) {
                    return true;
                }
            }
            $temporary = $destination . '.tmp-' . strtolower(wp_generate_password(12, false, false));
            if (file_exists($temporary) || is_link($temporary)) {
                return new WP_Error('static_bridge_ssi_write', __('Il percorso temporaneo della variante header esiste già.', 'static-bridge'));
            }
            $handle = @fopen($temporary, 'x');
            if (!is_resource($handle)) {
                return new WP_Error('static_bridge_ssi_write', __('Scrittura completa della variante header non riuscita.', 'static-bridge'));
            }
            $offset = 0;
            $length = strlen($markup);
            while ($offset < $length) {
                $written = @fwrite($handle, substr($markup, $offset));
                if (false === $written || 0 === $written) {
                    fclose($handle);
                    if (is_file($temporary) && !is_link($temporary)) {
                        @unlink($temporary);
                    }
                    return new WP_Error('static_bridge_ssi_write', __('Scrittura completa della variante header non riuscita.', 'static-bridge'));
                }
                $offset += $written;
            }
            $flushed = @fflush($handle);
            fclose($handle);
            if (!$flushed) {
                if (is_file($temporary) && !is_link($temporary)) {
                    @unlink($temporary);
                }
                return new WP_Error('static_bridge_ssi_write', __('Flush della variante header non riuscito.', 'static-bridge'));
            }
            @chmod($temporary, 0644);
            if (!@rename($temporary, $destination)) {
                @unlink($temporary);
                return new WP_Error('static_bridge_ssi_publish', __('Pubblicazione atomica della variante header non riuscita.', 'static-bridge'));
            }
            return true;
        } finally {
            $this->release_header_fragment_lock($lock);
        }
    }

    /** Build all variants off-path, then switch one document pointer atomically. */
    private function publish_header_fragment_snapshot($release_root, $document_id, $updates)
    {
        $release_root = realpath((string) $release_root);
        if (!$release_root || !$this->valid_header_fragment_document_id($document_id) || !is_array($updates) || empty($updates)) {
            return new WP_Error('static_bridge_ssi_snapshot', __('Dati del nuovo snapshot header non validi.', 'static-bridge'));
        }
        $document_directory = trailingslashit($release_root) . 'fragments/headers/' . $document_id;
        $generations_directory = trailingslashit($document_directory) . 'generations';
        $current_link = trailingslashit($document_directory) . 'current';
        $real_document = realpath($document_directory);
        $real_generations = realpath($generations_directory);
        if (!$real_document || !$real_generations || dirname($real_document) !== realpath($release_root . '/fragments/headers')
            || dirname($real_generations) !== $real_document || is_link($document_directory) || is_link($generations_directory)
            || !is_link($current_link)) {
            return new WP_Error('static_bridge_ssi_snapshot_path', __('Il puntatore corrente delle varianti header manca o non è sicuro.', 'static-bridge'));
        }
        $lock = $this->acquire_header_fragment_lock($real_document);
        if (!is_resource($lock)) {
            return new WP_Error('static_bridge_ssi_lock', __('Non è stato possibile acquisire il lock per lo snapshot header.', 'static-bridge'));
        }

        $new_directory = '';
        $temporary_link = '';
        $published = false;
        try {
            $old_target = readlink($current_link);
            if (!is_string($old_target) || !preg_match('~\Agenerations/(?:initial|generation-[a-f0-9]{24})\z~D', $old_target)) {
                return new WP_Error('static_bridge_ssi_snapshot_path', __('Il puntatore corrente header non risolve a una generazione verificata.', 'static-bridge'));
            }
            $old_directory = realpath(trailingslashit($real_document) . $old_target);
            if (!$old_directory || dirname($old_directory) !== $real_generations || is_link($old_directory)) {
                return new WP_Error('static_bridge_ssi_snapshot_path', __('La generazione corrente header non è una directory privata diretta.', 'static-bridge'));
            }

            $expected_pattern = '/\Aelementor-' . preg_quote((string) $document_id, '/') . '-[a-f0-9]{64}\.html\z/D';
            $source_names = @scandir($old_directory);
            if (!is_array($source_names)) {
                return new WP_Error('static_bridge_ssi_snapshot_read', __('Impossibile leggere la generazione header corrente.', 'static-bridge'));
            }
            $sources = array();
            $total_bytes = 0;
            foreach ($source_names as $name) {
                if ('.' === $name || '..' === $name) {
                    continue;
                }
                $source = trailingslashit($old_directory) . $name;
                if (!preg_match($expected_pattern, $name) || is_link($source) || !is_file($source)
                    || filesize($source) > Static_Bridge_Header_Fragments::MAX_HTML_BYTES) {
                    return new WP_Error('static_bridge_ssi_snapshot_read', __('La generazione header contiene un file inatteso o non sicuro.', 'static-bridge'));
                }
                $contents = @file_get_contents($source);
                if (!is_string($contents) || Static_Bridge_Header_Fragments::contains_ssi_directive($contents)) {
                    return new WP_Error('static_bridge_ssi_snapshot_read', __('La generazione header contiene SSI annidato o non leggibile.', 'static-bridge'));
                }
                $sources[$name] = $contents;
                $total_bytes += strlen($contents);
            }
            foreach ($updates as $name => $contents) {
                if (!is_string($name) || !preg_match($expected_pattern, $name) || !is_string($contents)
                    || '' === $contents || strlen($contents) > Static_Bridge_Header_Fragments::MAX_HTML_BYTES
                    || Static_Bridge_Header_Fragments::contains_ssi_directive($contents)) {
                    return new WP_Error('static_bridge_ssi_snapshot_input', __('Lo snapshot contiene una variante header non valida o una direttiva SSI.', 'static-bridge'));
                }
                $total_bytes += strlen($contents);
                $sources[$name] = $contents;
            }
            if (empty($sources) || !$this->has_sufficient_export_disk_space($release_root, $this->minimum_free_disk_space_bytes(), $total_bytes)) {
                return new WP_Error('static_bridge_ssi_snapshot_space', $this->insufficient_disk_space_message($this->minimum_free_disk_space_bytes()));
            }

            $generation_name = 'generation-' . bin2hex(random_bytes(12));
            $new_directory = trailingslashit($real_generations) . $generation_name;
            if (file_exists($new_directory) || is_link($new_directory) || !@mkdir($new_directory, 0755)) {
                return new WP_Error('static_bridge_ssi_snapshot_create', __('Non è possibile creare una nuova generazione isolata per l’header.', 'static-bridge'));
            }
            foreach ($sources as $name => $contents) {
                $destination = trailingslashit($new_directory) . $name;
                $handle = @fopen($destination, 'x');
                if (!is_resource($handle)) {
                    return new WP_Error('static_bridge_ssi_snapshot_write', __('Creazione di una variante dello snapshot non riuscita.', 'static-bridge'));
                }
                $offset = 0;
                $length = strlen($contents);
                while ($offset < $length) {
                    $written = @fwrite($handle, substr($contents, $offset));
                    if (false === $written || 0 === $written) {
                        fclose($handle);
                        return new WP_Error('static_bridge_ssi_snapshot_write', __('Scrittura completa di una variante dello snapshot non riuscita.', 'static-bridge'));
                    }
                    $offset += $written;
                }
                $flushed = @fflush($handle);
                fclose($handle);
                if (!$flushed || !@chmod($destination, 0644)) {
                    return new WP_Error('static_bridge_ssi_snapshot_write', __('Flush o permessi dello snapshot header non riusciti.', 'static-bridge'));
                }
            }

            $temporary_link = trailingslashit($real_document) . 'current.new-' . bin2hex(random_bytes(8));
            if (file_exists($temporary_link) || is_link($temporary_link)
                || !@symlink('generations/' . $generation_name, $temporary_link)) {
                return new WP_Error('static_bridge_ssi_snapshot_link', __('Non è possibile predisporre il puntatore temporaneo header.', 'static-bridge'));
            }
            if (readlink($current_link) !== $old_target || !@rename($temporary_link, $current_link)) {
                return new WP_Error('static_bridge_ssi_snapshot_swap', __('Il puntatore header è cambiato durante la preparazione o non è stato sostituito atomicamente.', 'static-bridge'));
            }
            $temporary_link = '';
            $published = true;
            return true;
        } finally {
            if ('' !== $temporary_link && is_link($temporary_link)) {
                @unlink($temporary_link);
            }
            if (!$published && '' !== $new_directory && is_dir($new_directory) && !is_link($new_directory)) {
                $files = @scandir($new_directory);
                if (is_array($files)) {
                    foreach ($files as $name) {
                        if ('.' !== $name && '..' !== $name && preg_match($expected_pattern, $name)) {
                            $path = trailingslashit($new_directory) . $name;
                            if (is_file($path) && !is_link($path)) {
                                @unlink($path);
                            }
                        }
                    }
                }
                @rmdir($new_directory);
            }
            $this->release_header_fragment_lock($lock);
        }
    }

    private function acquire_header_fragment_lock($document_directory)
    {
        $real_directory = realpath((string) $document_directory);
        if (!$real_directory || !is_dir($real_directory) || is_link($document_directory)) {
            return false;
        }
        $path = trailingslashit((string) $document_directory) . '.static-bridge.lock';
        if (is_link($path) || (file_exists($path) && !is_file($path))) {
            return false;
        }
        $before = @lstat($path);
        if (is_array($before) && 0100000 !== (((int) ($before['mode'] ?? 0)) & 0170000)) {
            return false;
        }
        $handle = @fopen($path, 'c+b');
        if (!is_resource($handle) || !@flock($handle, LOCK_EX)) {
            if (is_resource($handle)) {
                fclose($handle);
            }
            return false;
        }
        $opened = @fstat($handle);
        $after = @lstat($path);
        $real_path = realpath($path);
        if (!is_array($opened) || !is_array($after)
            || 0100000 !== (((int) ($opened['mode'] ?? 0)) & 0170000)
            || 0100000 !== (((int) ($after['mode'] ?? 0)) & 0170000)
            || (int) ($opened['dev'] ?? -1) !== (int) ($after['dev'] ?? -2)
            || (int) ($opened['ino'] ?? -1) !== (int) ($after['ino'] ?? -2)
            || !$real_path || dirname($real_path) !== $real_directory) {
            @flock($handle, LOCK_UN);
            fclose($handle);
            return false;
        }
        return $handle;
    }

    private function release_header_fragment_lock($handle)
    {
        if (is_resource($handle)) {
            @flock($handle, LOCK_UN);
            fclose($handle);
        }
    }

    private function valid_header_fragment_document_id($document_id)
    {
        return is_string($document_id) && (bool) preg_match('/\A[A-Za-z0-9_-]{1,64}\z/D', $document_id);
    }

    private function prepare_header_fragment_pointers($release_id, $release_root)
    {
        $index = new Static_Bridge_Header_Fragment_Index();
        $documents = $index->documents((string) $release_id);
        $root = realpath((string) $release_root);
        if (!is_array($documents) || !$root) {
            return false;
        }
        foreach ($documents as $document_id) {
            $document_directory = trailingslashit($root) . 'fragments/headers/' . $document_id;
            $generations_directory = trailingslashit($document_directory) . 'generations';
            $current_link = trailingslashit($document_directory) . 'current';
            $real_document = realpath($document_directory);
            $real_generations = realpath($generations_directory);
            if (!$real_document || !$real_generations || dirname($real_generations) !== $real_document
                || is_link($document_directory) || is_link($generations_directory)) {
                return false;
            }
            if (is_link($current_link)) {
                $target = readlink($current_link);
                $active = is_string($target) && preg_match('~\Agenerations/(?:initial|generation-[a-f0-9]{24})\z~D', $target)
                    ? realpath(trailingslashit($real_document) . $target)
                    : false;
                if (!$active || dirname($active) !== $real_generations || is_link($active)) {
                    return false;
                }
                continue;
            }
            if (file_exists($current_link) || is_link($current_link)) {
                return false;
            }
            $initial = trailingslashit($real_generations) . 'initial';
            if (!is_dir($initial) || is_link($initial)) {
                return false;
            }
            $files = glob(trailingslashit($initial) . 'elementor-' . $document_id . '-*.html');
            if (!is_array($files) || empty($files)) {
                return false;
            }
            foreach ($files as $file) {
                if (is_link($file) || !is_file($file)
                    || !preg_match('/\Aelementor-' . preg_quote($document_id, '/') . '-[a-f0-9]{64}\.html\z/D', basename($file))) {
                    return false;
                }
            }
            $temporary = trailingslashit($real_document) . 'current.new-' . bin2hex(random_bytes(8));
            if (file_exists($temporary) || is_link($temporary)
                || !@symlink('generations/initial', $temporary)
                || !@rename($temporary, $current_link)) {
                if (is_link($temporary)) {
                    @unlink($temporary);
                }
                return false;
            }
        }
        return true;
    }

    private function release_uses_header_fragments($release)
    {
        $release = realpath((string) $release);
        if (!$release) {
            return false;
        }
        $manifest_path = trailingslashit($release) . 'manifest.json';
        if (!is_file($manifest_path) || is_link($manifest_path) || !is_readable($manifest_path)) {
            return false;
        }
        $size = filesize($manifest_path);
        if (false === $size || $size < 2 || $size > 5242880) {
            return false;
        }
        $manifest = json_decode((string) file_get_contents($manifest_path), true);
        return is_array($manifest) && !empty($manifest['ssi_header_fragments'])
            && 1 === (int) $manifest['ssi_header_fragments'];
    }

    /**
     * Make same-site links portable across local/live hostnames. Preserve the
     * path, query and fragment; external domains remain unchanged. Only an
     * origin configured by WordPress is eligible for rewriting.
     *
     * Canonical, alternate (hreflang, feeds) and shortlink links, Open Graph and
     * Twitter meta tags and JSON-LD scripts keep the absolute URLs WordPress wrote:
     * search engines want an absolute canonical and @id, and link previews
     * (og:image) are not shown with a path (2.2.14).
     *
     * What a visitor reads or copies keeps the absolute URL too: text between tags (an address printed under an
     * article, a citation, <code>, <pre>, <title>, <textarea>), the readable attributes of
     * READABLE_URL_ATTRIBUTES, the value of a visible <input>, and the meta description and microdata (2.4.3).
     * What the browser loads or follows (href, src, srcset, action, style, data-* of lazy loaders, inline scripts
     * and styles, comments) still becomes root-relative.
     */
    private function rewrite_internal_origins_as_root_relative($html)
    {
        if (!is_string($html) || '' === $html) {
            return (string) $html;
        }
        $kept = array();
        // The placeholder is a tag of its own, so the text after it keeps the same left neighbour ('>').
        $marker = '<sb-keep-' . bin2hex(random_bytes(8)) . '-';
        $keep = static function ($match) use (&$kept, $marker) {
            $key = $marker . count($kept) . '>';
            $kept[$key] = $match[0];
            return $key;
        };
        $protected = preg_replace_callback(
            '~<script\b[^>]*\btype\s*=\s*(["\']?)application/ld\+json\1[^>]*>.*?</script\s*>~is',
            $keep,
            $html
        );
        if (is_string($protected)) {
            $protected = preg_replace_callback('~<(?:link|meta)\b[^>]*>~i', function ($match) use ($keep) {
                return $this->is_absolute_url_tag($match[0]) ? $keep($match) : $match[0];
            }, $protected);
        }
        if (is_string($protected)) {
            $protected = $this->keep_readable_urls($protected, $keep);
        }
        if (!is_string($protected)) {
            // A backtracking limit on a huge page: '' as when the rewrite itself fails, which the writers refuse.
            return '';
        }
        $rewritten = $this->rewrite_internal_origins_in_text($protected);
        return empty($kept) ? $rewritten : strtr($rewritten, $kept);
    }

    /**
     * Put aside, with $keep, what a visitor reads or copies: text runs between tags, the content of <title> and
     * <textarea>, and readable attribute values. Tags, comments, <script> and <style> are left for the rewrite.
     * Only pieces with a '/' are put aside, since an origin cannot be written without one. Returns null when a
     * pattern fails, which the caller turns into a refused page.
     */
    private function keep_readable_urls($html, callable $keep)
    {
        $text = static function ($piece) use ($keep) {
            return false === strpos($piece, '/') ? $piece : $keep(array($piece));
        };
        $length = strlen($html);
        $out = '';
        $offset = 0;
        while ($offset < $length) {
            $open = strpos($html, '<', $offset);
            if (false === $open) {
                $out .= $text(substr($html, $offset));
                break;
            }
            if ($open > $offset) {
                $out .= $text(substr($html, $offset, $open - $offset));
            }
            if (0 === substr_compare($html, '<!--', $open, 4)) {
                $close = strpos($html, '-->', $open + 4);
                $end = false === $close ? $length : $close + 3;
                $out .= substr($html, $open, $end - $open);
                $offset = $end;
                continue;
            }
            $found = preg_match('~\G<([A-Za-z][^\s/>]*+)(?:[^>"\']++|"[^"]*+"|\'[^\']*+\')*+>~', $html, $tag, 0, $open);
            if (false === $found) {
                return null;
            }
            if (1 !== $found) {
                if (preg_match('~\G<[/!?]~', $html, $unused, 0, $open)) {
                    // End tag, doctype or processing instruction: no readable text inside.
                    $close = strpos($html, '>', $open);
                    $end = false === $close ? $length : $close + 1;
                    $out .= substr($html, $open, $end - $open);
                    $offset = $end;
                } else {
                    // A '<' that opens no tag is text; the run continues after it.
                    $out .= '<';
                    $offset = $open + 1;
                }
                continue;
            }
            $name = strtolower($tag[1]);
            $end = $open + strlen($tag[0]);
            if ('script' === $name || 'style' === $name) {
                $closing = $this->closing_tag_position($html, $name, $end);
                $closing = false === $closing ? $length : strpos($html, '>', $closing);
                $closing = false === $closing ? $length : $closing + 1;
                $out .= substr($html, $open, $closing - $open);
                $offset = $closing;
                continue;
            }
            $readable = $this->keep_readable_attributes($tag[0], $name, $keep);
            if (!is_string($readable)) {
                return null;
            }
            $out .= $readable;
            $offset = $end;
            if ('title' === $name || 'textarea' === $name) {
                $closing = $this->closing_tag_position($html, $name, $end);
                $closing = false === $closing ? $length : $closing;
                if ($closing > $end) {
                    $out .= $text(substr($html, $end, $closing - $end));
                }
                $offset = $closing;
            }
        }
        return $out;
    }

    /** Offset of the '</name' that closes a raw text element (script, style, title, textarea), or false. */
    private function closing_tag_position($html, $name, $offset)
    {
        $length = strlen($name) + 2;
        while (false !== ($position = stripos($html, '</' . $name, $offset))) {
            $next = substr($html, $position + $length, 1);
            if ('' === $next || 1 !== preg_match('~[A-Za-z0-9_-]~', $next)) {
                return $position;
            }
            $offset = $position + $length;
        }
        return false;
    }

    /**
     * The tag with its readable attribute values put aside: READABLE_URL_ATTRIBUTES on any element and `value`
     * on an <input> that is not hidden (a hidden value is sent, not read). Null when the pattern fails.
     */
    private function keep_readable_attributes($tag, $name, callable $keep)
    {
        if (false === strpos($tag, '/') || false === strpos($tag, '=')) {
            return $tag;
        }
        $visible_input = 'input' === $name && 'hidden' !== $this->tag_attribute($tag, 'type');
        return preg_replace_callback(
            '~(\s)([^\s"\'>/=]+)(\s*=\s*)("[^"]*"|\'[^\']*\'|[^\s"\'>]+)~',
            static function ($match) use ($keep, $visible_input) {
                $attribute = strtolower($match[2]);
                $readable = in_array($attribute, self::READABLE_URL_ATTRIBUTES, true) || ($visible_input && 'value' === $attribute);
                if (!$readable || false === strpos($match[4], '/')) {
                    return $match[0];
                }
                return $match[1] . $match[2] . $match[3] . $keep(array($match[4]));
            },
            $tag
        );
    }

    /** The decoded, lowercased value of an attribute of a tag, or '' when it is missing. */
    private function tag_attribute($tag, $name)
    {
        return preg_match('~\s' . preg_quote($name, '~') . '\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s"\'>]+))~i', $tag, $value)
            ? strtolower(trim(html_entity_decode($value[1] . ($value[2] ?? '') . ($value[3] ?? ''), ENT_QUOTES)))
            : '';
    }

    /**
     * A <link> or <meta> tag whose URL must stay absolute in the static copy. The meta description is read in
     * search results and microdata (itemprop) is structured data like JSON-LD, so both stay absolute (2.4.3).
     */
    private function is_absolute_url_tag($tag)
    {
        if (0 === stripos($tag, '<link')) {
            return (bool) array_intersect(preg_split('/\s+/', $this->tag_attribute($tag, 'rel')), array('canonical', 'alternate', 'shortlink'));
        }
        foreach (array($this->tag_attribute($tag, 'property'), $this->tag_attribute($tag, 'name')) as $name) {
            if (0 === strpos($name, 'og:') || 0 === strpos($name, 'twitter:') || 'description' === $name) {
                return true;
            }
        }
        return 1 === preg_match('~\sitemprop\s*=~i', $tag);
    }

    private function rewrite_internal_origins_in_text($html)
    {

        $home = function_exists('home_url') ? home_url('/') : '';
        $home_parts = is_string($home) ? wp_parse_url($home) : false;
        if (!is_array($home_parts) || empty($home_parts['host'])
            || !isset($home_parts['scheme']) || !in_array(strtolower((string) $home_parts['scheme']), array('http', 'https'), true)) {
            return $html;
        }

        $origins = array($home_parts);
        if (function_exists('site_url')) {
            $site = site_url('/');
            $site_parts = is_string($site) ? wp_parse_url($site) : false;
            if (is_array($site_parts) && !empty($site_parts['host'])
                && strtolower((string) $site_parts['host']) === strtolower((string) $home_parts['host'])
                && (int) (isset($site_parts['port']) ? $site_parts['port'] : 0) === (int) (isset($home_parts['port']) ? $home_parts['port'] : 0)
                && isset($site_parts['scheme']) && in_array(strtolower((string) $site_parts['scheme']), array('http', 'https'), true)) {
                $origins[] = $site_parts;
            }
        }

        $authorities = array();
        foreach ($origins as $parts) {
            $host = strtolower((string) $parts['host']);
            $port = isset($parts['port']) ? (int) $parts['port'] : 0;
            $authority = $host . ($port > 0 ? ':' . $port : '');
            $authorities[$authority] = true;
            if (0 === $port) {
                $authorities[$host . ':80'] = true;
                $authorities[$host . ':443'] = true;
            }
        }

        foreach (array_keys($authorities) as $authority) {
            // WordPress/plugin inline JSON often escapes URL slashes as `\/`.
            // Match both encodings while leaving the path bytes untouched.
            $slash = '(?:\\\\?\\/)';
            $origin = '(?<![A-Za-z0-9._-])(?:https?:)?' . $slash . '{2}' . preg_quote($authority, '~');
            $path_pattern = '~' . $origin . '(?=' . $slash . ')~i';
            $root_pattern = '~' . $origin . '(?=$|[?#"\'<>\\s])~i';
            $html = preg_replace($path_pattern, '', $html);
            $html = preg_replace($root_pattern, '/', $html);
        }
        return is_string($html) ? $html : '';
    }

    private function portable_release_directory($release_id)
    {
        if (!is_string($release_id) || !preg_match('/^[A-Za-z0-9_-]{1,100}$/', $release_id)) {
            return '';
        }
        $release_root = $this->safe_release_root(false);
        if ('' === $release_root) {
            return '';
        }
        $directory = trailingslashit($release_root) . $release_id;
        if (is_link($directory) || !is_dir($directory)) {
            return '';
        }
        $real = realpath($directory);
        $manifest_file = trailingslashit($directory) . 'manifest.json';
        $ready_file = trailingslashit($directory) . '.ready';
        if (!$real || dirname($real) !== $release_root || is_link($manifest_file) || !is_file($manifest_file)
            || is_link($ready_file) || !is_file($ready_file)) {
            return '';
        }
        $manifest_size = @filesize($manifest_file);
        if (false === $manifest_size || $manifest_size < 2 || $manifest_size > 5242880 || !is_readable($manifest_file)) {
            return '';
        }
        $manifest_json = @file_get_contents($manifest_file);
        $manifest = is_string($manifest_json) ? json_decode($manifest_json, true) : null;
        if (!is_array($manifest) || !isset($manifest['release'], $manifest['portable_internal_urls'], $manifest['pages_saved'])
            || $release_id !== $manifest['release'] || 1 !== (int) $manifest['portable_internal_urls']
            || !is_numeric($manifest['pages_saved']) || (int) $manifest['pages_saved'] < 1) {
            return '';
        }
        return $real;
    }

    /** scheme://host[:port] of home_url(), '' when WordPress has none usable. */
    private function home_origin()
    {
        $parts = wp_parse_url(home_url('/'));
        if (!is_array($parts) || empty($parts['host']) || !isset($parts['scheme'])
            || !in_array(strtolower((string) $parts['scheme']), array('http', 'https'), true)) {
            return '';
        }
        return strtolower($parts['scheme'] . '://' . $parts['host']) . (isset($parts['port']) ? ':' . (int) $parts['port'] : '');
    }

    /**
     * A release exported on another domain (2.2.14 and later record it as absolute_url_origin) keeps that origin
     * in canonical, hreflang, og:/twitter: and JSON-LD, which stay absolute. It is not activated: the
     * administrator is told to export again on this domain. Releases without the field are fully root-relative.
     */
    private function imported_release_has_other_origin($release_id)
    {
        $directory = $this->portable_release_directory($release_id);
        $manifest = '' !== $directory ? json_decode((string) @file_get_contents($directory . '/manifest.json'), true) : null;
        $origin = is_array($manifest) && isset($manifest['absolute_url_origin']) && is_string($manifest['absolute_url_origin'])
            ? $manifest['absolute_url_origin'] : '';
        if ('' === $origin || $origin === $this->home_origin()) {
            return false;
        }
        $this->log_activity(
            __('Release importata da un altro dominio: frontend lasciato dinamico.', 'static-bridge'),
            sprintf(/* translators: 1: origin of the export, 2: origin of this site */ __('Canonical, hreflang, Open Graph, Twitter e JSON-LD della release indicano %1$s invece di %2$s, quindi la release non è stata attivata e WordPress serve il sito. Avvia un export completo su questo sito.', 'static-bridge'), esc_url_raw($origin), esc_url_raw($this->home_origin())),
            true
        );
        return true;
    }

    /** Switch current to an already validated, immutable imported release. */
    private function activate_imported_release($release_id)
    {
        $release_directory = $this->portable_release_directory($release_id);
        $release_root = $this->safe_release_root(false);
        if ('' === $release_directory || '' === $release_root) {
            return false;
        }

        $root = $this->static_root();
        $current = trailingslashit($root) . 'current';
        clearstatcache(true, $current);
        if (is_link($current)) {
            $existing = realpath($current);
            if (!$existing || dirname($existing) !== $release_root) {
                return false;
            }
            if ($existing !== $release_directory && !@unlink($current)) {
                return false;
            }
            if ($existing === $release_directory) {
                return true;
            }
        } elseif (file_exists($current)) {
            // Never recursively delete a directory created by a migration or
            // replace an unexpected file while repairing the release pointer.
            return false;
        }

        $temporary = trailingslashit($root) . 'current.import-' . strtolower(wp_generate_password(8, false, false));
        if (file_exists($temporary) || is_link($temporary)
            || !@symlink('releases/' . $release_id, $temporary)
            || !@rename($temporary, $current)) {
            if (is_link($temporary) || file_exists($temporary)) {
                @unlink($temporary);
            }
            return false;
        }

        $manifest_json = @file_get_contents(trailingslashit($release_directory) . 'manifest.json');
        $manifest = is_string($manifest_json) ? json_decode($manifest_json, true) : array();
        update_option('static_bridge_last_release', array(
            'id' => $release_id,
            'published_at' => time(),
            'pages' => isset($manifest['pages_saved']) ? absint($manifest['pages_saved']) : 0,
            'skipped' => isset($manifest['pages_skipped']) ? absint($manifest['pages_skipped']) : 0,
        ), false);
        return $this->current_release() === $release_directory;
    }

    private function remap_imported_incremental_queue()
    {
        $changed = false;
        $this->change_incremental_queue(function ($queue) use (&$changed) {
            foreach ($queue as $key => $item) {
                if (!is_array($item) || empty($item['path']) || !is_string($item['path'])) {
                    continue;
                }
                $path = $this->normalize_route_path(home_url($item['path']));
                if ('' === $path || $path !== $item['path']) {
                    continue;
                }
                $url = $this->normalize_public_url(home_url($path));
                if ($url && isset($item['url']) && $item['url'] !== $url) {
                    $queue[$key]['url'] = $url;
                    $changed = true;
                }
            }
            return $changed ? $queue : null;
        });
        return $changed;
    }

    private function minimum_free_disk_space_bytes()
    {
        $minimum = apply_filters('static_bridge_min_free_space_bytes', self::MIN_FREE_DISK_SPACE_BYTES);
        if (!is_numeric($minimum) || (float) $minimum < 0) {
            return self::MIN_FREE_DISK_SPACE_BYTES;
        }
        return min((float) PHP_INT_MAX, (float) $minimum);
    }

    private function insufficient_disk_space_message($minimum_free_space)
    {
        return sprintf(
            /* translators: %s: minimum free disk space in MiB */ __('Spazio disco insufficiente o non verificabile: export fermato mantenendo almeno %s MiB liberi. La release corrente non viene sostituita.', 'static-bridge'),
            number_format_i18n((float) $minimum_free_space / 1048576, 0)
        );
    }

    private function has_sufficient_export_disk_space($stage_root, $minimum_free_space, $additional_bytes)
    {
        if (!is_string($stage_root) || '' === $stage_root || !is_dir($stage_root) || !function_exists('disk_free_space')) {
            return false;
        }
        $free_bytes = @disk_free_space($stage_root);
        if (false === $free_bytes || !is_numeric($free_bytes)) {
            return false;
        }
        $required_bytes = (float) $minimum_free_space + max(0, (int) $additional_bytes);
        return (float) $free_bytes >= $required_bytes;
    }

    private function append_export_issue(&$job, $url, $message)
    {
        $job['issues'] = isset($job['issues']) && is_array($job['issues']) ? $job['issues'] : array();
        $job['issues'][] = array('url' => (string) $url, 'message' => (string) $message);
        if (count($job['issues']) > 100) {
            $job['issues'] = array_slice($job['issues'], -100);
        }
    }

    private function fail_export_queue_job($job, $url, $message)
    {
        if (!is_array($job)) {
            $job = array();
        }
        $job['status'] = 'failed';
        $job['updated_at'] = time();
        $this->append_export_issue($job, $url, $message);
        update_option(self::JOB_OPTION, $job, false);
        delete_option(self::EXPORT_CONTINUE_OPTION);
        if (!empty($job['job_id'])) {
            $this->export_queue()->delete_job($job['job_id']);
        }
        $this->cleanup_dependency_index_for_job($job);
        wp_clear_scheduled_hook('static_bridge_process_export_queue');
        $this->log_activity(__('Esportazione interrotta: release non pubblicata.', 'static-bridge'), ('' !== (string) $url ? (string) $url . ' — ' : '') . (string) $message, true);
        return $job;
    }

    private function cleanup_dependency_index_for_job($job)
    {
        if (!is_array($job) || empty($job['dependency_index_active']) || empty($job['release_id'])
            || !class_exists('Static_Bridge_Dependency_Index')) {
            return true;
        }
        $index = new Static_Bridge_Dependency_Index();
        $clean = $index->delete_release((string) $job['release_id']);
        if (!empty($job['header_fragments_active'])
            && !(new Static_Bridge_Header_Fragment_Index())->delete_release((string) $job['release_id'])) {
            $clean = false;
        }
        if ($clean) {
            return true;
        }
        $this->log_activity(
            __('Pulizia degli indici V2 della release non riuscita.', 'static-bridge'),
            __('La release statica non è stata attivata; alcuni record di indice incompleti potrebbero restare nel database.', 'static-bridge'),
            true
        );
        return false;
    }

    private function pause_export_queue_job($job, $url, $message)
    {
        if (!is_array($job)) {
            $job = array();
        }
        $job['status'] = 'paused';
        $job['current_url'] = (string) $url;
        $job['resume_retry_url_hash'] = sha1((string) $url);
        $job['updated_at'] = time();
        $this->append_export_issue($job, $url, $message);
        $last_issue = count($job['issues']) - 1;
        if (isset($job['issues'][$last_issue]) && is_array($job['issues'][$last_issue])) {
            $job['issues'][$last_issue]['retryable_transient'] = true;
        }
        update_option(self::JOB_OPTION, $job, false);
        wp_clear_scheduled_hook('static_bridge_process_export_queue');
        delete_option(self::EXPORT_CONTINUE_OPTION);
        $this->log_activity(
            __('Esportazione in pausa: release non pubblicata.', 'static-bridge'),
            ('' !== (string) $url ? (string) $url . ' — ' : '') . (string) $message . ' ' . __('La coda e lo staging sono conservati per consentire la ripresa.', 'static-bridge'),
            true
        );
        return $job;
    }

    /** Skip one exhausted route, retaining its last known-good HTML when safe. */
    private function skip_failed_export_queue_url(&$job, $queue, $row, $url, $message, $already_processed = false)
    {
        if (!is_array($job) || !is_array($row) || empty($job['job_id'])
            || !isset($row['url'], $row['url_hash']) || !is_string($row['url']) || !is_string($row['url_hash'])
            || !preg_match('/\A[a-f0-9]{40}\z/D', $row['url_hash']) || !is_string($url)
            || !hash_equals($row['url'], $url) || !hash_equals($row['url_hash'], sha1($url))) {
            return new WP_Error('static_bridge_route_skip_state', __('Lo stato della URL non è valido; non posso continuare in sicurezza.', 'static-bridge'));
        }

        if (isset($job['retry_url_hash']) && is_string($job['retry_url_hash'])
            && hash_equals($job['retry_url_hash'], sha1($url))) {
            $job['resume_retry_url_hash'] = $job['retry_url_hash'];
        }
        $this->clear_resumed_export_retry_issue($job, $url);

        $previous = $this->preserve_previous_export_route($job, $url);
        if (is_wp_error($previous)) {
            return $previous;
        }
        $preserved = is_array($previous) && !empty($previous['preserved']);
        $previous_body = $preserved && isset($previous['body']) ? (string) $previous['body'] : '';

        if ($preserved && !empty($job['dependency_index_active'])
            && !(new Static_Bridge_Dependency_Index())->index_route(
                (string) $job['release_id'],
                $this->normalize_route_path($url),
                $url,
                $previous_body
            )) {
            $job['dependency_index_failed'] = 1;
        }
        if ($preserved) {
            $links = array_values(array_filter($this->extract_internal_links($previous_body, $url), array($this, 'within_archive_page_cap')));
            $added = $queue->enqueue_batch((string) $job['job_id'], $links);
            if (false === $added) {
                return new WP_Error('static_bridge_route_skip_queue', __('Non è stato possibile accodare i link della copia statica precedente.', 'static-bridge'));
            }
            $job['discovered'] = max(0, (int) ($job['discovered'] ?? 0)) + (int) $added;
            if ($job['discovered'] > self::MAX_QUEUE_EXPORT_URLS) {
                return new WP_Error('static_bridge_route_skip_limit', sprintf(/* translators: %s: maximum number of URLs per release */ __('Il sito supera il limite prudenziale di %s URL unici dopo il recupero della route precedente.', 'static-bridge'), number_format_i18n(self::MAX_QUEUE_EXPORT_URLS)));
            }
        }

        if (!$queue->mark((string) $job['job_id'], (string) $row['url_hash'], 'skipped')) {
            return new WP_Error('static_bridge_route_skip_mark', __('Non è stato possibile registrare la URL come saltata nella coda.', 'static-bridge'));
        }

        if (!$already_processed) {
            $job['processed'] = max(0, (int) ($job['processed'] ?? 0)) + 1;
        }
        $job['skipped'] = max(0, (int) ($job['skipped'] ?? 0)) + 1;
        $job['route_errors'] = max(0, (int) ($job['route_errors'] ?? 0)) + 1;
        if ($preserved) {
            $job['saved'] = max(0, (int) ($job['saved'] ?? 0)) + 1;
            $job['pages_preserved'] = max(0, (int) ($job['pages_preserved'] ?? 0)) + 1;
        }

        $issue_message = (string) $message;
        $issue_message .= $preserved
            ? ' ' . __('La copia statica precedente è stata mantenuta; l’export prosegue.', 'static-bridge')
            : ' ' . __('Non esiste una copia statica precedente utilizzabile; questa route è stata omessa dalla nuova release.', 'static-bridge');
        $this->append_export_issue($job, $url, $issue_message);
        $last_issue = count($job['issues']) - 1;
        if (isset($job['issues'][$last_issue]) && is_array($job['issues'][$last_issue])) {
            $job['issues'][$last_issue]['type'] = 'route_error';
            $job['issues'][$last_issue]['previous_copy_preserved'] = $preserved ? 1 : 0;
        }

        unset($job['retry_url_hash'], $job['retry_attempts'], $job['resume_retry_url_hash']);
        $job['current_url'] = '';
        $job['updated_at'] = time();
        update_option(self::JOB_OPTION, $job, false);
        $this->log_activity(
            __('Errore su una pagina; export proseguito.', 'static-bridge'),
            $url . ' — ' . $issue_message,
            true
        );

        return true;
    }

    /**
     * The markup of one SSI header fragment of a release, only when every step is the one the export wrote:
     * `fragments/headers/<document>/current` a symlink to `generations/initial` or `generations/generation-<24 hex>`,
     * no other symlink, every folder where it should be, a regular file of 1 byte to MAX_HTML_BYTES without SSI
     * directives whose SHA-256 is the variant in its name. Null otherwise. The preservation of a failed page and the
     * link check (2.5.0) read fragments only through here.
     */
    private function verified_header_fragment($root, $document_id, $file_name, $variant_id)
    {
        $document_id = (string) $document_id;
        $file_name = (string) $file_name;
        $variant_id = (string) $variant_id;
        if (!preg_match('~\A[A-Za-z0-9_-]{1,64}\z~D', $document_id) || !preg_match('~\A[a-f0-9]{64}\z~D', $variant_id)
            || !hash_equals('elementor-' . $document_id . '-' . $variant_id . '.html', $file_name)) {
            return null;
        }
        $document_directory = trailingslashit((string) $root) . 'fragments/headers/' . $document_id;
        $current_link = trailingslashit($document_directory) . 'current';
        $target = is_link($current_link) ? readlink($current_link) : false;
        if (!is_string($target) || !preg_match('~\Agenerations/(?:initial|generation-[a-f0-9]{24})\z~D', $target)) {
            return null;
        }
        $real_document = realpath($document_directory);
        $generations = realpath(trailingslashit($document_directory) . 'generations');
        $generation = realpath(trailingslashit($document_directory) . $target);
        $fragment = trailingslashit((string) $generation) . $file_name;
        if (!$real_document || !$generations || !$generation
            || dirname($real_document) !== realpath($root . '/fragments/headers')
            || dirname($generations) !== $real_document || dirname($generation) !== $generations
            || is_link($document_directory) || is_link($fragment)
            || !is_file($fragment) || !is_readable($fragment)) {
            return null;
        }
        $fragment_size = filesize($fragment);
        $markup = false === $fragment_size || $fragment_size < 1 || $fragment_size > Static_Bridge_Header_Fragments::MAX_HTML_BYTES
            ? false
            : @file_get_contents($fragment);
        if (!is_string($markup) || '' === $markup || Static_Bridge_Header_Fragments::contains_ssi_directive($markup)
            || !hash_equals($variant_id, hash('sha256', $markup))) {
            return null;
        }
        return $markup;
    }

    /** Read only an in-root last-known-good page and its verified SSI header variants. */
    private function preserve_previous_export_route($job, $url)
    {
        if (!$this->valid_release_stage($job)) {
            return new WP_Error('static_bridge_route_preserve_stage', __('La cartella della nuova release non supera il controllo di sicurezza.', 'static-bridge'));
        }
        $current = $this->current_release();
        $relative = $this->relative_html_path($url);
        if (!$current || is_wp_error($relative) || !is_string($relative)) {
            return array('preserved' => false, 'body' => '');
        }
        $source = trailingslashit($current) . $relative;
        $source_real = realpath($source);
        $current_prefix = trailingslashit($current);
        if (is_link($source) || !$source_real || 0 !== strpos($source_real, $current_prefix)
            || !is_file($source_real) || !is_readable($source_real)) {
            return array('preserved' => false, 'body' => '');
        }
        $size = filesize($source_real);
        if (false === $size || $size < 1 || $size > self::MAX_HTML_PAGE_SIZE) {
            return array('preserved' => false, 'body' => '');
        }
        $body = @file_get_contents($source_real);
        if (!is_string($body) || '' === $body) {
            return array('preserved' => false, 'body' => '');
        }

        $fragments = array();
        if (Static_Bridge_Header_Fragments::contains_ssi_directive($body)) {
            if (empty($job['header_fragments_active'])
                || !preg_match_all(
                    '~<!--#include\s+virtual="/wp-content/static-bridge/current/fragments/headers/([A-Za-z0-9_-]{1,64})/current/(elementor-[A-Za-z0-9_-]{1,64}-([a-f0-9]{64})\.html)"\s+-->~',
                    $body,
                    $matches,
                    PREG_SET_ORDER
                ) || empty($matches)) {
                return array('preserved' => false, 'body' => '');
            }
            $without_includes = preg_replace(
                '~<!--#include\s+virtual="/wp-content/static-bridge/current/fragments/headers/[A-Za-z0-9_-]{1,64}/current/elementor-[A-Za-z0-9_-]{1,64}-[a-f0-9]{64}\.html"\s+-->~',
                '',
                $body
            );
            if (!is_string($without_includes) || Static_Bridge_Header_Fragments::contains_ssi_directive($without_includes)) {
                return array('preserved' => false, 'body' => '');
            }
            foreach ($matches as $match) {
                $document_id = (string) ($match[1] ?? '');
                $file_name = (string) ($match[2] ?? '');
                $variant_id = (string) ($match[3] ?? '');
                if ('' === $document_id || !hash_equals('elementor-' . $document_id . '-' . $variant_id . '.html', $file_name)) {
                    return array('preserved' => false, 'body' => '');
                }
                $markup = $this->verified_header_fragment($current, $document_id, $file_name, $variant_id);
                if (null === $markup) {
                    return array('preserved' => false, 'body' => '');
                }
                $fragments[$document_id . '/' . $file_name] = array(
                    'document_id' => $document_id,
                    'file_name' => $file_name,
                    'variant_id' => $variant_id,
                    'markup' => $markup,
                );
            }
        }

        $fragment_bytes = 0;
        foreach ($fragments as $fragment) {
            $fragment_bytes += strlen($fragment['markup']);
        }
        $stage_root = realpath(isset($job['stage']) ? (string) $job['stage'] : '');
        if (!$stage_root || !$this->has_sufficient_export_disk_space(
            $stage_root,
            $this->minimum_free_disk_space_bytes(),
            strlen($body) + $fragment_bytes
        )) {
            return new WP_Error('static_bridge_route_preserve_space', $this->insufficient_disk_space_message($this->minimum_free_disk_space_bytes()));
        }

        if (!empty($fragments)) {
            $fragment_index = new Static_Bridge_Header_Fragment_Index();
            $route_path = $this->normalize_route_path($url);
            foreach ($fragments as $fragment) {
                $variant = $fragment_index->register_variant(
                    (string) $job['release_id'],
                    $fragment['document_id'],
                    $fragment['markup'],
                    $route_path
                );
                if (!is_array($variant) || !isset($variant['file_name'], $variant['markup_hash'])
                    || !hash_equals($fragment['file_name'], (string) $variant['file_name'])
                    || !hash_equals($fragment['variant_id'], (string) $variant['markup_hash'])) {
                    return new WP_Error('static_bridge_route_preserve_fragment_index', __('Non è stato possibile indicizzare in modo sicuro l’header della copia precedente.', 'static-bridge'));
                }
                $written_fragment = $this->write_header_fragment_file(
                    $stage_root,
                    $fragment['document_id'],
                    $fragment['file_name'],
                    $fragment['markup'],
                    $fragment['variant_id']
                );
                if (is_wp_error($written_fragment)) {
                    return $written_fragment;
                }
            }
        }

        $destination = trailingslashit($stage_root) . $relative;
        if (is_link($destination) || file_exists($destination) || !wp_mkdir_p(dirname($destination))) {
            return new WP_Error('static_bridge_route_preserve_path', __('Non è stato possibile predisporre il percorso della copia statica precedente.', 'static-bridge'));
        }
        $parent = realpath(dirname($destination));
        if (!$parent || (0 !== strpos(trailingslashit($parent), trailingslashit($stage_root)) && $parent !== $stage_root)) {
            return new WP_Error('static_bridge_route_preserve_escape', __('Il percorso della copia precedente esce dalla nuova release.', 'static-bridge'));
        }
        $temporary = $destination . '.tmp-' . strtolower(wp_generate_password(12, false, false));
        if (file_exists($temporary) || is_link($temporary)) {
            return new WP_Error('static_bridge_route_preserve_temp', __('Il percorso temporaneo della copia precedente esiste già.', 'static-bridge'));
        }
        $written = @file_put_contents($temporary, $body, LOCK_EX);
        $write_ok = strlen($body) === $written;
        if ($write_ok) {
            @chmod($temporary, 0644);
            $write_ok = @rename($temporary, $destination);
        }
        if (!$write_ok) {
            if (file_exists($temporary) || is_link($temporary)) {
                @unlink($temporary);
            }
            return new WP_Error('static_bridge_route_preserve_write', __('Scrittura atomica della copia statica precedente non riuscita.', 'static-bridge'));
        }
        $this->write_precompressed_copy($destination, $body, !empty($job['header_fragments_active']));

        return array('preserved' => true, 'body' => $body);
    }

    private function is_fatal_export_url_error($error)
    {
        return is_wp_error($error)
            && in_array($error->get_error_code(), array('static_bridge_unsafe_page', 'static_bridge_unsafe_request', 'static_bridge_render_origin_unavailable'), true);
    }

    private function clear_resumed_export_retry_issue(&$job, $url)
    {
        if (!isset($job['resume_retry_url_hash'])
            || !is_string($job['resume_retry_url_hash'])
            || !hash_equals($job['resume_retry_url_hash'], sha1((string) $url))) {
            return;
        }
        $issues = isset($job['issues']) && is_array($job['issues']) ? $job['issues'] : array();
        for ($index = count($issues) - 1; $index >= 0; $index--) {
            if (is_array($issues[$index])
                && !empty($issues[$index]['retryable_transient'])
                && isset($issues[$index]['url'])
                && hash_equals((string) $issues[$index]['url'], (string) $url)) {
                array_splice($issues, $index, 1);
                break;
            }
        }
        $job['issues'] = $issues;
        unset($job['resume_retry_url_hash']);
    }

    public function ajax_diagnostic_start()
    {
        $this->verify_ajax_request();
        if ($this->diagnostic_is_running()) {
            wp_send_json_error(array('message' => __('È già in corso una diagnostica.', 'static-bridge')), 409);
        }

        $target_url = '';
        if (isset($_POST['target_url'])) {
            if (!is_string($_POST['target_url'])) {
                wp_send_json_error(array('message' => __('Il percorso per il confronto mirato non è valido.', 'static-bridge')), 400);
            }
            $target_input = trim((string) wp_unslash($_POST['target_url']));
            if ('' !== $target_input) {
                $target_url = $this->normalize_diagnostic_target_url($target_input);
                if ('' === $target_url) {
                    wp_send_json_error(array('message' => __('Inserisci un percorso pubblico valido o un URL HTTP(S) dello stesso dominio, senza query o frammento.', 'static-bridge')), 400);
                }
            }
        }

        $release = $this->current_release();
        $run = array(
            'id' => wp_generate_uuid4(),
            'status' => 'running',
            'started_at' => time(),
            'updated_at' => time(),
            'release' => $release ? basename($release) : '',
            'steps' => $this->diagnostic_plan($release, $target_url),
            'cursor' => 0,
            'results' => array(),
        );
        update_option(self::DIAGNOSTIC_OPTION, $run, false);
        $this->log_activity(__('Diagnostica Static Bridge avviata.', 'static-bridge'));
        wp_send_json_success($this->diagnostic_response($run));
    }

    public function ajax_diagnostic_tick()
    {
        $this->verify_ajax_request();
        $run = get_option(self::DIAGNOSTIC_OPTION, array());
        if (!is_array($run) || empty($run['status'])) {
            wp_send_json_error(array('message' => __('Non è disponibile una diagnostica da riprendere.', 'static-bridge')), 409);
        }
        if ('running' !== $run['status']) {
            wp_send_json_success($this->diagnostic_response($run));
        }
        $steps_valid = isset($run['steps']) && is_array($run['steps']) && !empty($run['steps']);
        $results_valid = isset($run['results']) && is_array($run['results']);
        $cursor_valid = isset($run['cursor']) && is_numeric($run['cursor']) && 0 <= (int) $run['cursor'];
        if ($steps_valid && $cursor_valid) {
            $cursor_valid = (int) $run['cursor'] <= count($run['steps']);
        }
        if (!$steps_valid || !$results_valid || !$cursor_valid) {
            if (!$steps_valid) {
                $run['steps'] = array(array('id' => 'diagnostic-plan', 'label' => __('Sessione diagnostica incompleta', 'static-bridge')));
            }
            if (!$results_valid) {
                $run['results'] = array();
            }
            $run['results'][] = $this->diagnostic_result(
                'diagnostic-plan',
                __('Sessione diagnostica incompleta', 'static-bridge'),
                'fail',
                __('La sessione salvata non contiene una lista valida di controlli; non è stato possibile riprenderla.', 'static-bridge'),
                __('Avvia una nuova verifica dalla scheda Diagnostica.', 'static-bridge'),
                'settings'
            );
            $run['cursor'] = count($run['steps']);
            $run['status'] = 'failed';
            $run['completed_at'] = time();
            $run['updated_at'] = time();
            $run['summary'] = $this->diagnostic_summary($run['results']);
            update_option(self::DIAGNOSTIC_OPTION, $run, false);
            $this->save_diagnostic_history($run);
            $this->log_activity(__('La sessione diagnostica precedente era incompleta.', 'static-bridge'), __('La sessione è stata chiusa senza ripetere richieste; puoi avviare una nuova verifica.', 'static-bridge'), true);
            wp_send_json_success($this->diagnostic_response($run));
        }
        if (!empty($run['updated_at']) && time() - (int) $run['updated_at'] > 3600) {
            $run['status'] = 'failed';
            $run['results'][] = $this->diagnostic_result(
                'diagnostic-timeout',
                __('Durata del test', 'static-bridge'),
                'fail',
                __('La verifica è rimasta inattiva per oltre un’ora ed è stata chiusa.', 'static-bridge'),
                __('Avvia un nuovo test dalla scheda Diagnostica.', 'static-bridge'),
                'settings'
            );
            $run['completed_at'] = time();
            $run['updated_at'] = time();
            $run['summary'] = $this->diagnostic_summary($run['results']);
            update_option(self::DIAGNOSTIC_OPTION, $run, false);
            $this->save_diagnostic_history($run);
            wp_send_json_success($this->diagnostic_response($run));
        }

        $steps = isset($run['steps']) && is_array($run['steps']) ? $run['steps'] : array();
        $cursor = isset($run['cursor']) ? (int) $run['cursor'] : 0;
        if (isset($steps[$cursor])) {
            $run['results'][] = $this->run_diagnostic_step($steps[$cursor], $run);
            $run['cursor'] = $cursor + 1;
        }
        $run['updated_at'] = time();

        if ($run['cursor'] >= count($steps)) {
            $run['summary'] = $this->diagnostic_summary($run['results']);
            $run['status'] = !empty($run['summary']['failed']) ? 'failed' : (!empty($run['summary']['warning']) ? 'warning' : 'passed');
            $run['completed_at'] = time();
            $this->save_diagnostic_history($run);
            $this->log_activity(
                __('Diagnostica Static Bridge completata.', 'static-bridge'),
                sprintf(
                    /* translators: 1: errors, 2: warnings, 3: passed checks (each already counted, e.g. "1 errore"). */
                    __('%1$s, %2$s, %3$s.', 'static-bridge'),
                    sprintf(/* translators: %s: number of errors */ _n('%s errore', '%s errori', (int) $run['summary']['failed'], 'static-bridge'), number_format_i18n($run['summary']['failed'])),
                    sprintf(/* translators: %s: number of warnings */ _n('%s avviso', '%s avvisi', (int) $run['summary']['warning'], 'static-bridge'), number_format_i18n($run['summary']['warning'])),
                    sprintf(/* translators: %s: number of passed checks */ _n('%s controllo superato', '%s controlli superati', (int) $run['summary']['passed'], 'static-bridge'), number_format_i18n($run['summary']['passed']))
                ),
                !empty($run['summary']['failed'])
            );
        }

        update_option(self::DIAGNOSTIC_OPTION, $run, false);
        wp_send_json_success($this->diagnostic_response($run));
    }

    /** The stored results of the Server tab, normalized. */
    private function server_check_state()
    {
        $state = get_option(self::SERVER_CHECK_OPTION, array());
        if (!is_array($state)) {
            $state = array();
        }
        return array(
            'started_at' => isset($state['started_at']) ? (int) $state['started_at'] : 0,
            'completed_at' => isset($state['completed_at']) ? (int) $state['completed_at'] : 0,
            'results' => isset($state['results']) && is_array($state['results']) ? $state['results'] : array(),
        );
    }

    private function server_check_module()
    {
        return new Static_Bridge_Server_Check(array(
            'nginx' => $this->server_uses_nginx(),
            'cloudflare_purge' => !empty($this->cloudflare_purge_config()['ready']),
            'aruba_purge' => Static_Bridge_Server_Tuning::aruba_purge_available(),
            'home' => home_url('/'),
            'request' => function ($url, $args) {
                return $this->self_request_follow($url, (array) $args);
            },
            // 2.5.0: the WP-Cron check names the late events of Static Bridge.
            'cron_hooks' => $this->cron_hook_labels(),
        ));
    }

    public function ajax_server_check_start()
    {
        $this->verify_ajax_request();
        update_option(self::SERVER_CHECK_OPTION, array('started_at' => time(), 'completed_at' => 0, 'results' => array()), false);
        $checks = array();
        foreach (Static_Bridge_Server_Check::checks() as $id => $label) {
            $checks[] = array('id' => $id, 'label' => $label);
        }
        wp_send_json_success(array('checks' => $checks));
    }

    /** One check per request: each may wait for a few HTTP responses of the site. */
    public function ajax_server_check_step()
    {
        $this->verify_ajax_request();
        $id = isset($_POST['check']) && is_string($_POST['check']) ? sanitize_key(wp_unslash($_POST['check'])) : '';
        $checks = Static_Bridge_Server_Check::checks();
        if (!isset($checks[$id])) {
            wp_send_json_error(array('message' => __('Controllo sconosciuto.', 'static-bridge')), 400);
        }
        try {
            $result = $this->server_check_module()->run($id);
        } catch (Throwable $error) {
            $result = Static_Bridge_Server_Check::result($id, 'skip', __('Il controllo si è interrotto per un errore imprevisto.', 'static-bridge'), __('Ripeti il controllo; se si ripete, guarda il log degli errori di PHP.', 'static-bridge'));
        }
        $state = $this->server_check_state();
        if (0 === $state['started_at']) {
            $state['started_at'] = time();
        }
        $state['results'][$id] = $result;
        $done = 0 === count(array_diff(array_keys($checks), array_keys($state['results'])));
        if ($done) {
            $state['completed_at'] = time();
        }
        update_option(self::SERVER_CHECK_OPTION, $state, false);
        wp_send_json_success(array(
            'result' => $result,
            'done' => $done,
            'note' => $done ? sprintf(/* translators: %s: date and time of the last check */ __('Ultimo controllo: %s', 'static-bridge'), $this->format_site_datetime($state['completed_at'])) : '',
        ));
    }

    /** The single actions of the Server tab: the .htaccess block and the object cache, each on or off. */
    public function handle_server_tuning()
    {
        if (!current_user_can('manage_options')) {
            wp_die(esc_html__('Non hai i permessi necessari.', 'static-bridge'), '', array('response' => 403));
        }
        check_admin_referer('static_bridge_server_tuning');
        $feature = isset($_POST['feature']) && is_string($_POST['feature']) ? sanitize_key(wp_unslash($_POST['feature'])) : '';
        $enable = isset($_POST['enable']) && '1' === (string) wp_unslash($_POST['enable']);
        if ('htaccess' === $feature) {
            $outcome = $this->set_server_htaccess_block($enable);
            $done = $enable ? __('Compressione e cache dei file attivate nel file .htaccess.', 'static-bridge') : __('Blocco di compressione e cache tolto dal file .htaccess.', 'static-bridge');
        } elseif ('object-cache' === $feature) {
            if ($enable) {
                $service = null;
                foreach (Static_Bridge_Server_Check::object_cache_services() as $candidate) {
                    if ($candidate['reachable']) {
                        $service = $candidate;
                        break;
                    }
                }
                $outcome = Static_Bridge_Object_Cache::install((array) $service, function ($url, $args) {
                    return $this->self_request('GET', $url, (array) $args);
                });
                $done = sprintf(/* translators: 1: Redis or Memcached, 2: address */ __('Object cache attiva: %1$s su %2$s.', 'static-bridge'), $service['name'] ?? '', $service['where'] ?? '');
            } else {
                $outcome = Static_Bridge_Object_Cache::remove();
                $done = __('Object cache di Static Bridge tolta: WordPress usa di nuovo il database.', 'static-bridge');
            }
        } else {
            wp_die(esc_html__('Azione sconosciuta.', 'static-bridge'), '', array('response' => 400));
        }
        if (is_wp_error($outcome)) {
            $notice = array('status' => 'error', 'message' => $outcome->get_error_message());
            $this->log_activity(__('Scheda Server: modifica non applicata.', 'static-bridge'), $outcome->get_error_message(), true);
        } else {
            $notice = array('status' => 'success', 'message' => $done);
            $this->log_activity(__('Scheda Server:', 'static-bridge') . ' ' . $done);
        }
        update_option(self::SERVER_TUNING_NOTICE_OPTION, $notice, false);
        // The checks run again when the tab opens, so they show the change.
        $state = $this->server_check_state();
        $state['completed_at'] = 0;
        update_option(self::SERVER_CHECK_OPTION, $state, false);
        wp_safe_redirect($this->tab_url('server'));
        exit;
    }

    /**
     * Writes or removes the compression and file-cache block, then asks the site for a page and a file:
     * a server that refuses these directives in .htaccess answers 500 everywhere, and the block goes away.
     *
     * @return true|WP_Error
     */
    private function set_server_htaccess_block($enable)
    {
        if ($enable && $this->server_uses_nginx()) {
            return new WP_Error('static_bridge_server_block_nginx', __('Nginx non legge il file .htaccess: copia i blocchi mostrati nella scheda nella configurazione di Nginx.', 'static-bridge'));
        }
        if ($enable && 'openlitespeed' === $this->web_server_kind()) {
            return new WP_Error('static_bridge_server_block_openlitespeed', __('OpenLiteSpeed ignora questo blocco del file .htaccess: comprime da solo i file statici, e la loro scadenza nel browser si imposta nel WebAdmin.', 'static-bridge'));
        }
        $htaccess = trailingslashit(ABSPATH) . '.htaccess';
        $written = Static_Bridge_Server_Tuning::write_htaccess_block($htaccess, $enable);
        if (is_wp_error($written) || !$enable) {
            return $written;
        }
        $home_host = strtolower((string) wp_parse_url(home_url('/'), PHP_URL_HOST));
        foreach (array(home_url('/'), includes_url('css/dashicons.min.css')) as $url) {
            // 2.5.0: behind Basic Auth the header goes along and the redirects are followed only on this site.
            $response = $this->self_request_follow($url, array(
                'timeout' => 15,
                'redirection' => 3,
                'limit_response_size' => 65536,
                'sslverify' => !preg_match('/(?:\.local|\.test|\.localhost)$/i', $home_host),
            ));
            $status = is_wp_error($response) ? 0 : (int) wp_remote_retrieve_response_code($response);
            if ($status >= 500) {
                Static_Bridge_Server_Tuning::write_htaccess_block($htaccess, false);
                return new WP_Error('static_bridge_server_block_refused', sprintf(
                    /* translators: %s: HTTP status code */
                    __('Con queste regole il server ha risposto HTTP %s: non le accetta nel file .htaccess. Il blocco è stato tolto subito; chiedi all’hosting di attivare compressione e cache.', 'static-bridge'),
                    $status
                ));
            }
        }
        return true;
    }

    /** The card with what Static Bridge can change on this server. */
    private function render_server_tuning_card()
    {
        $nginx = $this->server_uses_nginx();
        $htaccess = trailingslashit(ABSPATH) . '.htaccess';
        $block_active = !$nginx && is_readable($htaccess) && Static_Bridge_Server_Tuning::htaccess_has_block((string) file_get_contents($htaccess));
        $dropin = Static_Bridge_Object_Cache::dropin_state();
        $service = null;
        if ('ours' !== $dropin) {
            foreach (Static_Bridge_Server_Check::object_cache_services() as $candidate) {
                if ($candidate['reachable']) {
                    $service = $candidate;
                    break;
                }
            }
        }
        $object_cache_reason = 'ours' === $dropin ? '' : Static_Bridge_Object_Cache::unavailable_reason($service);
        $form = function ($feature, $enable, $label, $primary = false) {
            ?>
            <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="sb-server-tuning-form">
                <input type="hidden" name="action" value="static_bridge_server_tuning">
                <input type="hidden" name="feature" value="<?php echo esc_attr($feature); ?>">
                <input type="hidden" name="enable" value="<?php echo $enable ? '1' : '0'; ?>">
                <?php wp_nonce_field('static_bridge_server_tuning'); ?>
                <button type="submit" class="button<?php echo $primary ? ' button-primary sb-primary-button' : ''; ?>"><?php echo esc_html($label); ?></button>
            </form>
            <?php
        };
        ?>
        <section class="sb-card sb-server-tuning-card">
            <div class="sb-card-heading"><div><p class="sb-eyebrow"><?php esc_html_e('COSA PUÒ FARE STATIC BRIDGE', 'static-bridge'); ?></p><h2><?php esc_html_e('Interventi a un clic', 'static-bridge'); ?></h2></div></div>
            <p class="sb-card-copy"><?php esc_html_e('Ogni intervento si attiva e si toglie da qui, e si toglie anche disattivando Static Bridge. Dopo ogni modifica i controlli qui sopra ripartono da soli.', 'static-bridge'); ?></p>

            <div class="sb-server-tuning-item">
                <h3><?php esc_html_e('Compressione e cache dei file', 'static-bridge'); ?></h3>
                <?php if ($nginx) : ?>
                    <p><?php esc_html_e('Nginx non legge il file .htaccess: copia il primo blocco nel blocco http della configurazione e il secondo nel blocco server del sito, poi verifica con nginx -t e ricarica Nginx. Le pagine HTML restano fuori: la loro cache resta quella di Static Bridge.', 'static-bridge'); ?></p>
                    <?php foreach (Static_Bridge_Server_Tuning::nginx_snippets() as $context => $snippet) : ?>
                        <textarea class="large-text code" rows="<?php echo 'http' === $context ? 11 : 2; ?>" readonly aria-label="<?php echo esc_attr('http' === $context ? __('Blocco per il contesto http di Nginx', 'static-bridge') : __('Riga per il blocco server del sito', 'static-bridge')); ?>"><?php echo esc_textarea($snippet); ?></textarea>
                    <?php endforeach; ?>
                <?php elseif ('openlitespeed' === $this->web_server_kind()) : ?>
                    <p><?php esc_html_e('OpenLiteSpeed comprime da solo HTML, CSS e JavaScript, con gzip e Brotli, e del file .htaccess usa solo le regole di riscrittura: il blocco di Static Bridge qui non avrebbe effetto. La scadenza di CSS, JavaScript, immagini e font nel browser si imposta nel WebAdmin (Virtual Host → General → Expires Settings).', 'static-bridge'); ?></p>
                    <?php if ($block_active) : ?>
                        <?php $form('htaccess', false, __('Togli il blocco', 'static-bridge')); ?>
                    <?php endif; ?>
                <?php elseif ($block_active) : ?>
                    <p><span class="sb-status-pill is-published"><span></span><?php esc_html_e('Attive', 'static-bridge'); ?></span> <?php esc_html_e('Il blocco «StaticBridge-Server» del file .htaccess comprime HTML, CSS e JavaScript e fa tenere al browser CSS, JavaScript, immagini e font. Le pagine HTML non hanno una scadenza: la loro cache resta quella di Static Bridge.', 'static-bridge'); ?></p>
                    <?php $form('htaccess', false, __('Togli il blocco', 'static-bridge')); ?>
                <?php else : ?>
                    <p><?php esc_html_e('Aggiunge al file .htaccess un blocco che comprime HTML, CSS e JavaScript e fa tenere al browser CSS, JavaScript, immagini e font per 30 giorni (i font per un anno). Le pagine HTML restano fuori. Se il server non accetta queste regole, Static Bridge se ne accorge subito e toglie il blocco.', 'static-bridge'); ?></p>
                    <?php $form('htaccess', true, __('Attiva compressione e cache dei file', 'static-bridge'), true); ?>
                <?php endif; ?>
            </div>

            <div class="sb-server-tuning-item">
                <h3><?php esc_html_e('Object cache', 'static-bridge'); ?></h3>
                <?php if ('ours' === $dropin) : ?>
                    <p><span class="sb-status-pill <?php echo wp_using_ext_object_cache() ? 'is-published' : 'is-warning'; ?>"><span></span><?php echo wp_using_ext_object_cache() ? esc_html__('Attiva', 'static-bridge') : esc_html__('Servizio non raggiungibile', 'static-bridge'); ?></span>
                        <?php echo wp_using_ext_object_cache()
                            ? esc_html__('WordPress tiene in Redis o Memcached i dati che altrimenti chiederebbe ogni volta al database.', 'static-bridge')
                            : esc_html__('Il drop-in è installato ma il servizio non risponde: WordPress lavora come senza cache, con i dati nel database, e riprova ogni minuto.', 'static-bridge'); ?></p>
                    <?php $form('object-cache', false, __('Togli l’object cache', 'static-bridge')); ?>
