                    <p><span class="sb-status-pill is-published"><span></span><?php esc_html_e('Attivo', 'static-bridge'); ?></span> <?php esc_html_e('Il plugin Aruba HiSpeed Cache è attivo: dopo ogni pubblicazione e ogni pagina aggiornata, Static Bridge svuota la cache di Aruba, così i visitatori vedono subito la versione nuova.', 'static-bridge'); ?></p>
                </div>
            <?php endif; ?>
        </section>
        <?php
    }

    private function render_server_check_result($result)
    {
        if (!is_array($result)) {
            return;
        }
        $status = isset($result['status']) && in_array($result['status'], Static_Bridge_Server_Check::STATUSES, true) ? $result['status'] : 'skip';
        $icons = array('pass' => 'dashicons-yes-alt', 'tip' => 'dashicons-lightbulb', 'warning' => 'dashicons-warning', 'skip' => 'dashicons-minus');
        ?>
        <article class="sb-diagnostic-result is-<?php echo esc_attr($status); ?>">
            <span class="sb-diagnostic-icon dashicons <?php echo esc_attr($icons[$status]); ?>" aria-hidden="true"></span>
            <div class="sb-diagnostic-result-content">
                <div class="sb-diagnostic-result-heading"><strong><?php echo esc_html(isset($result['label']) ? $result['label'] : __('Controllo', 'static-bridge')); ?></strong><span class="sb-diagnostic-status"><?php echo esc_html(Static_Bridge_Server_Check::status_label($status)); ?></span></div>
                <p><?php echo esc_html(isset($result['summary']) ? $result['summary'] : ''); ?></p>
                <?php if (!empty($result['remediation'])) : ?><p class="sb-diagnostic-remediation"><?php echo esc_html($result['remediation']); ?></p><?php endif; ?>
            </div>
        </article>
        <?php
    }

    /**
     * Until the first check of the server, a pointer to the Server tab on the dashboard and the plugins screen.
     * Not on Static Bridge's own page: the tab is in its menu, and its notices (export, retention) come first there.
     */
    public function render_server_check_notice()
    {
        if (!current_user_can('manage_options') || !function_exists('get_current_screen')) {
            return;
        }
        $screen = get_current_screen();
        if (!$screen || !in_array((string) $screen->id, array('dashboard', 'plugins'), true)) {
            return;
        }
        if (0 !== $this->server_check_state()['completed_at']) {
            return;
        }
        ?>
        <div class="notice notice-info"><p><?php esc_html_e('Static Bridge può controllare cosa offre il server (compressione, cache, PHP, object cache) e dirti cosa conviene attivare. Il controllo legge soltanto e dura pochi secondi.', 'static-bridge'); ?> <a class="button button-small" href="<?php echo esc_url($this->tab_url('server')); ?>"><?php esc_html_e('Apri la scheda Server', 'static-bridge'); ?></a></p></div>
        <?php
    }

    public function ajax_diagnostic_status()
    {
        $this->verify_ajax_request();
        $run = get_option(self::DIAGNOSTIC_OPTION, array());
        wp_send_json_success($this->diagnostic_response(is_array($run) ? $run : array()));
    }

    public function export_diagnostic_log()
    {
        if (!current_user_can('manage_options')) {
            wp_die(esc_html__('Non hai i permessi necessari.', 'static-bridge'));
        }
        check_admin_referer('static_bridge_export_diagnostics');

        $payload = array(
            'plugin' => array('name' => 'Static Bridge', 'version' => self::VERSION),
            'site' => array('home_url' => home_url('/')),
            'exported_at_utc' => gmdate('c'),
            'latest_run' => get_option(self::DIAGNOSTIC_OPTION, array()),
            'history' => get_option(self::DIAGNOSTIC_HISTORY_OPTION, array()),
            'activity' => get_option(self::ACTIVITY_OPTION, array()),
            'export_job' => $this->diagnostic_export_job_snapshot(),
        );
        nocache_headers();
        header('Content-Type: application/json; charset=utf-8');
        header('Content-Disposition: attachment; filename="static-bridge-diagnostics-' . gmdate('Ymd-His') . '.json"');
        echo wp_json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE);
        exit;
    }

    private function diagnostic_export_job_snapshot()
    {
        $job = get_option(self::JOB_OPTION, array());
        if (!is_array($job) || empty($job)) {
            return array('status' => 'unavailable');
        }

        $status = isset($job['status']) && is_string($job['status']) ? sanitize_key($job['status']) : 'unknown';
        $allowed_statuses = array('idle', 'running', 'retrying', 'paused', 'failed', 'cancelled', 'complete');
        if (!in_array($status, $allowed_statuses, true)) {
            $status = 'unknown';
        }

        $snapshot = array(
            'status' => $status,
            'queue_version' => isset($job['queue_version']) ? absint($job['queue_version']) : 0,
            'job_id' => isset($job['job_id']) && is_string($job['job_id']) ? substr(sanitize_text_field($job['job_id']), 0, 36) : '',
            'release' => isset($job['release_id']) && is_string($job['release_id']) ? sanitize_file_name($job['release_id']) : (isset($job['release']) && is_string($job['release']) ? sanitize_file_name($job['release']) : ''),
            'started_at' => isset($job['started_at']) && is_numeric($job['started_at']) ? (int) $job['started_at'] : 0,
            'updated_at' => isset($job['updated_at']) && is_numeric($job['updated_at']) ? (int) $job['updated_at'] : 0,
            'discovery_complete' => !empty($job['discovery_complete']),
            'discovery_cursor' => isset($job['discovery_cursor']) && is_numeric($job['discovery_cursor']) ? max(0, (int) $job['discovery_cursor']) : 0,
            'discovered' => isset($job['discovered']) && is_numeric($job['discovered']) ? max(0, (int) $job['discovered']) : 0,
            'processed' => isset($job['processed']) && is_numeric($job['processed']) ? max(0, (int) $job['processed']) : 0,
            'saved' => isset($job['saved']) && is_numeric($job['saved']) ? max(0, (int) $job['saved']) : 0,
            'skipped' => isset($job['skipped']) && is_numeric($job['skipped']) ? max(0, (int) $job['skipped']) : 0,
            'pages_preserved' => isset($job['pages_preserved']) && is_numeric($job['pages_preserved']) ? max(0, (int) $job['pages_preserved']) : 0,
            'route_errors' => isset($job['route_errors']) && is_numeric($job['route_errors']) ? max(0, (int) $job['route_errors']) : 0,
            'retry_attempts' => isset($job['retry_attempts']) && is_numeric($job['retry_attempts']) ? max(0, (int) $job['retry_attempts']) : 0,
            'worker_busy' => !empty($job['_worker_busy']),
            'current_url' => isset($job['current_url']) && is_string($job['current_url']) ? $this->normalize_diagnostic_target_url($job['current_url']) : '',
        );

        if (isset($job['pending']) && is_array($job['pending'])) {
            $snapshot['pending'] = count($job['pending']);
        } elseif (!empty($job['job_id']) && class_exists('Static_Bridge_Export_Queue')) {
            $wpdb = isset($GLOBALS['wpdb']) ? $GLOBALS['wpdb'] : null;
            $pending = (new Static_Bridge_Export_Queue($wpdb))->count_pending((string) $job['job_id']);
            $snapshot['pending'] = false === $pending ? null : (int) $pending;
        } else {
            $snapshot['pending'] = null;
        }

        $snapshot['issues'] = array();
        $issues = isset($job['issues']) && is_array($job['issues']) ? array_slice($job['issues'], -10) : array();
        foreach ($issues as $issue) {
            if (!is_array($issue)) {
                continue;
            }
            $message = isset($issue['message']) && is_string($issue['message']) ? wp_strip_all_tags($issue['message']) : '';
            $snapshot['issues'][] = array(
                'url' => isset($issue['url']) && is_string($issue['url']) ? $this->normalize_diagnostic_target_url($issue['url']) : '',
                'message' => substr($message, 0, 1200),
                'retryable_transient' => !empty($issue['retryable_transient']),
                'type' => isset($issue['type']) && is_string($issue['type']) ? sanitize_key($issue['type']) : '',
                'previous_copy_preserved' => !empty($issue['previous_copy_preserved']),
            );
        }

        return $snapshot;
    }

    private function diagnostic_plan($release, $target_url = '')
    {
        $steps = array(
            array('id' => 'release-files', 'type' => 'release', 'label' => __('File della release attiva', 'static-bridge')),
            array('id' => 'rewrite-rules', 'type' => 'rewrite', 'label' => __('Regole del server web', 'static-bridge')),
            array('id' => 'basic-auth', 'type' => 'basic-auth', 'label' => __('Basic Auth del web server', 'static-bridge')),
            array('id' => 'render-origin', 'type' => 'render-origin', 'label' => __('Rendering HTTP dal processo PHP', 'static-bridge')),
            array('id' => 'cloudflare-edge', 'type' => 'cloudflare-edge', 'label' => __('Cloudflare davanti al sito', 'static-bridge')),
            array('id' => 'cloudflare-markup', 'type' => 'cloudflare-markup', 'label' => __('Markup Cloudflare nelle copie salvate', 'static-bridge')),
            array('id' => 'wordpress-inventory', 'type' => 'inventory', 'label' => __('Inventario WordPress', 'static-bridge')),
            array('id' => 'security-origin', 'type' => 'security-origin', 'label' => __('Sicurezza richieste in uscita', 'static-bridge')),
        );
        $failed_export_url = $this->diagnostic_retryable_export_url();
        if ('' !== $failed_export_url) {
            $steps[] = array(
                'id' => 'render-failed-url',
                'type' => 'render-failed-url',
                'label' => __('URL dell’ultimo errore transitorio di export', 'static-bridge'),
                'url' => $failed_export_url,
            );
        }
        $steps[] = array('id' => 'security-release-access', 'type' => 'security-release-access', 'label' => __('Protezione delle release precedenti', 'static-bridge'));
        if ($release && is_file(trailingslashit($release) . 'index.html')) {
            $steps[] = array('id' => 'static-home', 'type' => 'static', 'label' => __('Homepage statica', 'static-bridge'), 'path' => '/', 'file' => 'index.html');
            $steps[] = array('id' => 'security-headers', 'type' => 'security-headers', 'label' => __('Intestazioni di sicurezza sulle pagine statiche', 'static-bridge'));
            $steps[] = array('id' => 'seo-absolute-urls', 'type' => 'seo-absolute-urls', 'label' => __('Canonical e anteprime come le vede un visitatore', 'static-bridge'));
            // 2.5.0: one copy for every device; a theme that writes another HTML for phones loses its version.
            $steps[] = array('id' => 'mobile-html', 'type' => 'mobile-html', 'label' => __('Home da computer e da telefono', 'static-bridge'));
            if (class_exists('COMPLIANZ') && function_exists('cmplz_get_cookiebanner')) {
                $steps[] = array('id' => 'complianz-banner', 'type' => 'complianz-banner', 'label' => __('Banner e policy di Complianz nelle pagine statiche', 'static-bridge'));
            }
        }

        $samples = array();
        if ($release && is_dir($release)) {
            try {
                $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($release, FilesystemIterator::SKIP_DOTS));
                foreach ($iterator as $file) {
                    if (!$file->isFile() || 'html' !== strtolower($file->getExtension())) {
                        continue;
                    }
                    $relative = ltrim(str_replace(DIRECTORY_SEPARATOR, '/', substr($file->getPathname(), strlen(trailingslashit($release)))), '/');
                    if ('index.html' === $relative) {
                        continue;
                    }
                    $directory = dirname($relative);
                    $path = '/' . ('.' === $directory ? '' : trim($directory, '/') . '/');
                    if ($this->is_excluded_path($path)) {
                        continue;
                    }
                    $samples[$path] = $relative;
                    if (count($samples) >= 3) {
                        break;
                    }
                }
            } catch (Exception $exception) {
                // The release integrity check reports filesystem problems separately.
            }
        }
        foreach ($samples as $path => $relative) {
            $steps[] = array('id' => 'static-' . substr(md5($path), 0, 8), 'type' => 'static', 'label' => sprintf(/* translators: %s: page path */ __('Pagina statica %s', 'static-bridge'), $path), 'path' => $path, 'file' => $relative);
        }

        if ('' !== (string) $target_url) {
            $target_url = $this->normalize_diagnostic_target_url($target_url);
            if ('' !== $target_url) {
                $steps[] = array(
                    'id' => 'static-route-target',
                    'type' => 'static-route-parity',
                    'label' => __('Confronto mirato HTML: file statico, WordPress e risposta pubblica', 'static-bridge'),
                    'url' => $target_url,
                );
                $steps[] = array(
                    'id' => 'static-parity-target',
                    'type' => 'static-parity',
                    'label' => __('Confronto mirato delle immagini', 'static-bridge'),
                    'url' => $target_url,
                );
            }
        }

        $steps[] = array('id' => 'wp-admin', 'type' => 'admin');
        $steps[] = array('id' => 'wp-login', 'type' => 'login');
        $steps[] = array('id' => 'rest-api', 'type' => 'rest');
        $steps[] = array('id' => 'feed', 'type' => 'feed');
        $steps[] = array('id' => 'query-bypass', 'type' => 'bypass');
        // 2.5.0: with «Ignora i parametri di tracciamento» a query of tracking parameters gets the copy.
        if (array() !== $this->tracking_param_names()) {
            $steps[] = array('id' => 'tracking-query', 'type' => 'tracking-query');
        }
        // 2.5.0: «Cookie che mandano a WP», and whether one of them is probably on every visitor.
        if (array() !== $this->dynamic_cookie_names()) {
            $steps[] = array('id' => 'dynamic-cookies', 'type' => 'dynamic-cookies');
        }
        if ($this->server_uses_nginx()) {
            // The Nginx block is copied by hand: check the guards that a partial copy loses.
            // On Apache the generated .htaccess is checked by the rewrite-rules step instead.
            $steps[] = array('id' => 'logged-in-bypass', 'type' => 'cookie-bypass');
            $steps[] = array('id' => 'post-bypass', 'type' => 'post-bypass');
            // 2.5.0 (D5): the block in use is the one these settings make, imported redirects included.
            $steps[] = array('id' => 'nginx-rules', 'type' => 'nginx-rules');
        }

        foreach (array_slice($this->settings()['excluded_paths'], 0, 5) as $index => $path) {
            $steps[] = array('id' => 'dynamic-' . $index, 'type' => 'dynamic', 'path' => $path);
        }
        foreach (array_slice($this->discover_form_pages(), 0, 8) as $index => $form_page) {
            $steps[] = array(
                'id' => 'form-' . substr(md5($form_page['path']), 0, 10),
                'type' => 'form',
                'path' => $form_page['path'],
                'mode' => $form_page['mode'],
                'file_exists' => $form_page['file_exists'],
                'index' => $index + 1,
            );
        }
        foreach ($this->discover_builder_pages() as $builder_page) {
            $steps[] = array(
                'id' => 'builder-' . substr(md5($builder_page['path']), 0, 10),
                'type' => 'builder-page',
                'path' => $builder_page['path'],
                'builders' => $builder_page['builders'],
                'title' => $builder_page['title'],
            );
        }
        $steps[] = array('id' => 'incremental-queue', 'type' => 'incremental-queue');
        if ($this->woocommerce_is_active()) {
            // 2.2.13: the transactional pages and /wc-api/ stay with WordPress whatever the switch says.
            if (empty($this->settings()['woocommerce_enabled'])) {
                $steps[] = array('id' => 'woocommerce-disabled', 'type' => 'woocommerce-disabled');
            }
            $woocommerce_pages = $this->woocommerce_pages();
            if (empty($woocommerce_pages)) {
                $steps[] = array('id' => 'woocommerce-pages', 'type' => 'woocommerce-missing');
            } else {
                foreach ($woocommerce_pages as $index => $woocommerce_page) {
                    $steps[] = array(
                        'id' => 'woocommerce-' . $index,
                        'type' => 'woocommerce-route',
                        'path' => $woocommerce_page['path'],
                        'label' => $woocommerce_page['label'],
                    );
                }
            }
            $steps[] = array('id' => 'woocommerce-endpoints', 'type' => 'woocommerce-endpoint', 'path' => '/wc-api/static-bridge-diagnostic/');
            if (!empty($this->settings()['woocommerce_enabled'])) {
                // The Store API nonces, the catalog, the pages kept with WordPress, the store settings.
                $steps[] = array('id' => 'woocommerce-store-api', 'type' => 'woocommerce-store-api');
                $steps[] = array('id' => 'woocommerce-catalog', 'type' => 'woocommerce-catalog');
                $steps[] = array('id' => 'woocommerce-dynamic-pages', 'type' => 'woocommerce-dynamic');
                $steps[] = array('id' => 'woocommerce-settings', 'type' => 'woocommerce-settings');
            }
        }
        if (!empty($this->settings()['strict_mode']) && $release) {
            $steps[] = array('id' => 'strict-404', 'type' => 'strict');
        } else {
            $steps[] = array('id' => 'strict-404', 'type' => 'skip-strict');
        }
        return $steps;
    }

    private function diagnostic_has_exclusion_rules($contents)
    {
        if (!is_string($contents)) {
            return false;
        }
        $paths = array();
        $exclude_home = false;
        foreach ($this->routing_excluded_paths() as $path) {
            if ('/' === $path) {
                $exclude_home = true;
                continue;
            }
            $path = trim($path, '/');
            if ('' !== $path) {
                $paths[] = preg_quote($path, '~');
            }
        }
        if (empty($paths) && !$exclude_home) {
            return true;
        }
        if (!empty($paths)) {
            $expected = 'RewriteCond %{REQUEST_URI} !^/(?:' . implode('|', $paths) . ')(?:/|$) [NC]';
            if (false === strpos($contents, $expected)) {
                return false;
            }
        }
        return !$exclude_home || false !== strpos($contents, 'RewriteCond %{REQUEST_URI} !^/$');
    }

    private function diagnostic_static_route_parity_result($id, $label, $url, $file, $release, $public_response)
    {
        $status = wp_remote_retrieve_response_code($public_response);
        $body = wp_remote_retrieve_body($public_response);
        $content_type = (string) wp_remote_retrieve_header($public_response, 'content-type');
        if (200 !== $status || ('' !== $content_type && false === stripos($content_type, 'text/html'))) {
            $result_status = (300 <= $status && $status < 400) || in_array($status, array(401, 403, 404, 410), true) ? 'warning' : 'fail';
            $location = (string) wp_remote_retrieve_header($public_response, 'location');
            return $this->diagnostic_result(
                $id,
                $label,
                $result_status,
                sprintf(/* translators: 1: HTTP status code, 2: redirect location in parentheses or empty, 3: Content-Type */ __('Risposta pubblica HTTP %1$s%2$s, Content-Type %3$s; il confronto dei contenuti non è stato eseguito.', 'static-bridge'), $status, '' !== $location ? ' (' . $location . ')' : '', '' !== $content_type ? $content_type : __('non indicato', 'static-bridge')),
                __('La verifica non ha modificato la release. Controlla la route e ripeti il confronto quando restituisce HTML pubblico.', 'static-bridge'),
                'settings',
                $url
            );
        }

        $release_real = realpath((string) $release);
        $file_real = realpath((string) $file);
        if (!$release_real || !$file_real || 0 !== strpos($file_real, trailingslashit($release_real))
            || is_link($file) || !is_file($file_real) || !is_readable($file_real)) {
            return $this->diagnostic_result($id, $label, 'fail', __('Il file HTML da confrontare non è un file regolare leggibile dentro la release attesa.', 'static-bridge'), __('Verifica la release attiva e i permessi dei file statici.', 'static-bridge'), 'generate', $url);
        }

        $file_size = filesize($file_real);
        if (false === $file_size || $file_size > self::MAX_HTML_PAGE_SIZE) {
            return $this->diagnostic_result($id, $label, 'fail', __('Il file HTML della release supera il limite di lettura sicura.', 'static-bridge'), __('Controlla la dimensione della pagina e ripeti la verifica.', 'static-bridge'), 'generate', $url);
        }
        $file_html = @file_get_contents($file_real);
        if (!is_string($file_html)) {
            return $this->diagnostic_result($id, $label, 'fail', __('Non è stato possibile leggere il file HTML della release.', 'static-bridge'), __('Controlla i permessi della release attiva.', 'static-bridge'), 'generate', $url);
        }

        $file_comparable = $this->diagnostic_parity_body($file_html, $release_real);
        $public_comparable = $this->diagnostic_parity_body($body, $release_real);
        $file_hash = hash('sha256', $file_comparable['body']);
        $public_hash = hash('sha256', $public_comparable['body']);
        $file_fingerprint = substr($file_hash, 0, 12) . '/' . strlen($file_comparable['body']) . 'B';
        $public_fingerprint = substr($public_hash, 0, 12) . '/' . strlen($public_comparable['body']) . 'B';
        $ssi_unexpanded = $this->release_uses_header_fragments($release_real)
            && class_exists('Static_Bridge_Header_Fragments')
            && Static_Bridge_Header_Fragments::contains_ssi_directive($body);

        if ($ssi_unexpanded) {
            return $this->diagnostic_result(
                $id,
                $label,
                'fail',
                sprintf(/* translators: 1: fingerprint of the release file, 2: fingerprint of the public response */ __('La risposta pubblica contiene ancora una direttiva SSI non elaborata. Impronte SHA-256/byte: file %1$s; pubblico %2$s.', 'static-bridge'), $file_fingerprint, $public_fingerprint),
                __('Abilita SSI sul percorso statico o disattiva i frammenti SSI; non rigenerare finché il server non elabora gli include.', 'static-bridge'),
                'settings',
                $url
            );
        }

        if ($file_comparable['complete'] && $public_comparable['complete']
            && hash_equals($file_hash, $public_hash)) {
            return $this->diagnostic_result(
                $id,
                $label,
                'pass',
                sprintf(/* translators: 1: fingerprint of the release file, 2: URL */ __('La risposta pubblica coincide con il file della release dopo la normalizzazione SSI (%1$s; %2$s).', 'static-bridge'), $file_fingerprint, $url),
                '',
                '',
                $url
            );
        }

        if ($this->job_is_running()) {
            return $this->diagnostic_result(
                $id,
                $label,
                'warning',
                sprintf(/* translators: 1: fingerprint of the release file, 2: fingerprint of the public response */ __('Parità non verificata mentre è in corso un export: file %1$s, pubblico %2$s. Il rendering WordPress fresco è stato saltato per non interferire con il job.', 'static-bridge'), $file_fingerprint, $public_fingerprint),
                __('Attendi il completamento o l’arresto del job e ripeti la diagnostica.', 'static-bridge'),
                '',
                $url
            );
        }

        $fresh = $this->fetch_page($url, 15);
        if (is_wp_error($fresh)) {
            $error_code = $fresh->get_error_code();
            $error_data = $fresh->get_error_data();
            $is_missing_or_redirect = ('static_bridge_http' === $error_code && in_array((int) $error_data, array(404, 410), true))
                || 'static_bridge_redirect' === $error_code;
            $summary = sprintf(
                /* translators: 1: fingerprint of the release file, 2: fingerprint of the public response, 3: error message */ __('Parità fallita: file %1$s, risposta pubblica %2$s. Non è stato possibile ottenere il rendering WordPress fresco: %3$s', 'static-bridge'),
                $file_fingerprint,
                $public_fingerprint,
                $fresh->get_error_message()
            );
            return $this->diagnostic_result(
                $id,
                $label,
                $is_missing_or_redirect ? 'warning' : 'fail',
                $summary,
                __('Controlla routing, cache/proxy e raggiungibilità del rendering WordPress. Il file statico non è stato sostituito.', 'static-bridge'),
                'settings',
                $url
            );
        }

        $current_release = $this->current_release();
        if (!$current_release || $current_release !== $release_real) {
            return $this->diagnostic_result($id, $label, 'warning', __('La release è cambiata durante il controllo: confronto annullato per non mischiare versioni.', 'static-bridge'), __('Attendi la fine della pubblicazione e ripeti la diagnostica.', 'static-bridge'), '', $url);
        }

        $fresh_comparable = $this->diagnostic_parity_body($fresh['body'], $release_real);
        $fresh_hash = hash('sha256', $fresh_comparable['body']);
        $fresh_fingerprint = substr($fresh_hash, 0, 12) . '/' . strlen($fresh_comparable['body']) . 'B';
        if ($file_comparable['complete'] && $public_comparable['complete'] && $fresh_comparable['complete']
            && hash_equals($public_hash, $fresh_hash) && !hash_equals($file_hash, $public_hash)) {
            $detail = __('La risposta pubblica coincide con WordPress aggiornato, non con il file statico: il routing non sta consegnando la copia della release.', 'static-bridge');
            $remediation = __('Verifica che Apache applichi davvero le regole Static Bridge e che non ci sia una cache che instrada la route verso WordPress.', 'static-bridge');
        } elseif ($file_comparable['complete'] && $public_comparable['complete'] && $fresh_comparable['complete']
            && hash_equals($file_hash, $fresh_hash) && !hash_equals($file_hash, $public_hash)) {
            $detail = __('Il file statico coincide con il rendering WordPress aggiornato, ma la risposta pubblica è diversa: probabile cache, proxy o trasformazione intermedia.', 'static-bridge');
            $remediation = __('Controlla cache del server/proxy/CDN e trasformazioni HTML; non rigenerare la release finché il livello che serve la route non è verificato.', 'static-bridge');
        } else {
            $detail = __('File, risposta pubblica e rendering WordPress non coincidono; la causa non è attribuibile con certezza al solo export.', 'static-bridge');
            $remediation = __('Confronta cache/proxy, routing Apache e template/plugin che generano markup variabile. Il controllo non ha pubblicato né modificato file.', 'static-bridge');
        }
        if (!$file_comparable['complete'] || !$public_comparable['complete'] || !$fresh_comparable['complete']) {
            $detail .= ' ' . __('La normalizzazione SSI è incompleta; questa impronta non certifica la parità dell’header condiviso.', 'static-bridge');
        }
        $detail .= sprintf(/* translators: 1: fingerprint of the release file, 2: fingerprint of the public response, 3: fingerprint of the fresh WordPress rendering */ __(' Impronte SHA-256/byte: file %1$s; pubblico %2$s; WordPress %3$s.', 'static-bridge'), $file_fingerprint, $public_fingerprint, $fresh_fingerprint);
        $cache_headers = $this->diagnostic_cache_headers($public_response);
        $detail .= ' ' . sprintf(
            /* translators: %s: list of cache headers */ __('Header di cache esposti dalla risposta: %s.', 'static-bridge'),
            !empty($cache_headers) ? implode('; ', $cache_headers) : __('nessuno tra quelli controllati', 'static-bridge')
        );

        return $this->diagnostic_result($id, $label, 'fail', $detail, $remediation, 'settings', $url);
    }

    /**
     * 2.5.0: the response carries X-Static-Bridge-Route: static, the marker of the copy (and of the Strict 404). The
     * Nginx block always sends it, the Apache rules with mod_headers: on Apache its absence proves nothing, so the
     * checks that want the copy keep comparing the content, and only those that want WP use it.
     */
    private function diagnostic_served_static($response)
    {
        $value = wp_remote_retrieve_header($response, 'x-static-bridge-route');
        foreach (is_array($value) ? $value : array($value) as $one) {
            if (is_string($one) && 'static' === strtolower(trim($one))) {
                return true;
            }
        }
        return false;
    }

    /** 2.5.0: a request that must reach WP got the copy on Apache (the marker of the rules says so). */
    private function diagnostic_apache_served_static($id, $label, $url)
    {
        return $this->diagnostic_result($id, $label, 'fail', __('Il server web ha servito la copia statica (intestazione X-Static-Bridge-Route) a una richiesta che deve arrivare a WP.', 'static-bridge'), $this->diagnostic_apache_static_remediation(), 'settings', $url);
    }

    private function diagnostic_apache_static_remediation()
    {
        return __('Salva di nuovo le Impostazioni e controlla il passo «Regole del server web»; se le regole sono giuste, cerca la cache o la regola davanti a WP che serve la copia.', 'static-bridge');
    }

    private function diagnostic_cache_headers($response)
    {
        $headers = array();
        foreach (array('x-static-bridge-route', 'age', 'cache-control', 'cf-cache-status', 'x-cache', 'x-cache-status', 'x-proxy-cache', 'x-litespeed-cache', 'via') as $name) {
            $value = wp_remote_retrieve_header($response, $name);
            if (is_array($value)) {
                $value = implode(', ', array_map('strval', $value));
            }
            if (!is_string($value) || '' === trim($value)) {
                continue;
            }
            $headers[] = $name . '=' . substr(wp_strip_all_tags(trim($value)), 0, 120);
        }
        return $headers;
    }

    private function diagnostic_static_route_step($step, $run)
    {
        $id = isset($step['id']) ? $step['id'] : 'static-route-target';
        $url = isset($step['url']) ? $this->normalize_diagnostic_target_url((string) $step['url']) : '';
        $label = isset($step['label']) ? $step['label'] : __('Confronto mirato della route statica', 'static-bridge');
        if ('' === $url) {
            return $this->diagnostic_result($id, $label, 'fail', __('Il percorso del confronto non è valido.', 'static-bridge'), __('Inserisci una route pubblica dello stesso dominio senza query o frammento.', 'static-bridge'), 'settings');
        }
        $release = $this->current_release();
        if (!$release || empty($run['release']) || basename($release) !== (string) $run['release']) {
            return $this->diagnostic_result($id, $label, 'warning', __('La release attiva è assente o è cambiata dall’avvio della diagnostica; confronto non eseguito.', 'static-bridge'), __('Avvia una nuova verifica quando non sono in corso pubblicazioni.', 'static-bridge'), '', $url);
        }
        $relative = $this->relative_html_path($url);
        if (is_wp_error($relative)) {
            return $this->diagnostic_result($id, $label, 'fail', $relative->get_error_message(), __('Controlla il percorso indicato.', 'static-bridge'), 'settings', $url);
        }
        $file = trailingslashit($release) . $relative;
        $public = $this->remote_get($url, 15, self::MAX_HTML_PAGE_SIZE);
        if (is_wp_error($public)) {
            return $this->diagnostic_result($id, $label, 'fail', $public->get_error_message(), __('Verifica TLS, DNS e raggiungibilità della route dal processo PHP.', 'static-bridge'), 'settings', $url);
        }
        $status = wp_remote_retrieve_response_code($public);
        if ($this->server_uses_nginx() && 200 === $status
            && 'static' !== strtolower((string) wp_remote_retrieve_header($public, 'x-static-bridge-route'))) {
            return $this->diagnostic_result($id, $label, 'fail', __('Nginx non ha confermato il routing statico per la route mirata.', 'static-bridge'), __('Controlla il blocco Nginx e l’header X-Static-Bridge-Route.', 'static-bridge'), 'settings', $url);
        }
        return $this->diagnostic_static_route_parity_result($id, $label, $url, $file, $release, $public);
    }

    private function run_diagnostic_step($step, $run)
    {
        $type = isset($step['type']) ? $step['type'] : '';
        $id = isset($step['id']) ? $step['id'] : 'unknown';
        switch ($type) {
            case 'release':
                $release = $this->current_release();
                $manifest_path = $release ? trailingslashit($release) . 'manifest.json' : '';
                $manifest = $manifest_path && is_readable($manifest_path) ? json_decode(file_get_contents($manifest_path), true) : null;
                $html_count = $release ? $this->count_html_files($release) : 0;
                if (!$release || empty($run['release']) || basename($release) !== $run['release'] || !is_file($release . '/.ready') || !is_array($manifest)) {
                    return $this->diagnostic_result($id, __('File della release attiva', 'static-bridge'), 'fail', __('Release corrente, marcatore .ready o manifest.json mancanti/non validi.', 'static-bridge'), __('Controlla la cartella delle versioni e rigenera il sito statico.', 'static-bridge'), 'generate');
                }
                $manifest_count = isset($manifest['pages_saved']) ? (int) $manifest['pages_saved'] : 0;
                if ($html_count !== $manifest_count || $html_count < 1) {
                    return $this->diagnostic_result($id, __('File della release attiva', 'static-bridge'), 'fail', sprintf(/* translators: 1: number of pages in the manifest, 2: number of HTML files found */ __('Manifest: %1$s pagine; file HTML trovati: %2$s.', 'static-bridge'), $manifest_count, $html_count), __('Rigenera la release e verifica i permessi di scrittura dello spazio statico.', 'static-bridge'), 'generate');
                }
                return $this->diagnostic_result($id, __('File della release attiva', 'static-bridge'), 'pass', sprintf(/* translators: %s: number of HTML pages */ __('%s pagine HTML e manifest coerenti.', 'static-bridge'), number_format_i18n($html_count)));

            case 'rewrite':
                if ($this->server_uses_nginx()) {
                    $release = $this->current_release();
                    if (!$release) {
                        return $this->diagnostic_result($id, __('Regole del server web', 'static-bridge'), 'skip', __('Nessuna release statica attiva: il routing Nginx sarà verificabile dopo la prima generazione completa.', 'static-bridge'), __('Genera prima una release di prova e ripeti la diagnostica end-to-end.', 'static-bridge'), 'generate');
                    }
                    $probe = $this->nginx_route_probe($release);
                    if (true === $probe) {
                        return $this->diagnostic_result($id, __('Regole del server web', 'static-bridge'), 'pass', __('Nginx ha instradato una pagina al file statico: header di routing e hash SHA-256 verificati.', 'static-bridge'));
                    }
                    return $this->diagnostic_result($id, __('Regole del server web', 'static-bridge'), 'fail', __('Nginx non sta servendo una pagina dalla release Static Bridge verificabile.', 'static-bridge'), __('Installa il blocco Nginx mostrato in Impostazioni, includi gli attuali percorsi dinamici e ricarica Nginx; poi ripeti la diagnostica.', 'static-bridge'), 'settings');
                }
                $file = trailingslashit(ABSPATH) . '.htaccess';
                $contents = is_readable($file) ? file_get_contents($file) : false;
                $begin = is_string($contents) ? strpos($contents, '# BEGIN Static Bridge') : false;
                $end = is_string($contents) ? strpos($contents, '# END Static Bridge') : false;
                $wp_marker = is_string($contents) ? strpos($contents, '# BEGIN WordPress') : false;
                $required = is_string($contents)
                    && false !== $begin && false !== $end && $end > $begin
                    && (false !== strpos($contents, 'wp-content/static-bridge/current/index.html -f')
                        || preg_match('~wp-content/static-bridge/served/[0-9]{8}T[0-9]{6}Z-[a-f0-9]{8}/index\.html -f~', $contents))
                    && false !== strpos($contents, 'static-bridge/releases')
                    && false !== strpos($contents, 'static-bridge/current/(?:manifest')
                    && false !== strpos($contents, $this->apache_query_condition() . "\n")
                    && ('' === $this->dynamic_cookie_pattern() || false !== strpos($contents, 'RewriteCond %{HTTP_COOKIE} !' . $this->dynamic_cookie_pattern() . ' [NC]'))
                    && false !== strpos($contents, 'RewriteCond %{HTTP_COOKIE} !(?:wordpress_logged_in_')
                    && false !== strpos($contents, 'RewriteCond %{REQUEST_METHOD} ^(?:GET|HEAD)$')
                    && false !== strpos($contents, 'wp-admin|wp-content|wp-includes|wp-json')
                    && $this->diagnostic_has_exclusion_rules($contents)
                    && (false === $wp_marker || $begin < $wp_marker);
                if (!empty($this->settings()['strict_mode'])) {
                    $required = $required && false !== strpos($contents, 'wp-content/static-bridge/.strict -f');
                }
                if (!$required) {
                    return $this->diagnostic_result($id, __('Regole del server web', 'static-bridge'), 'fail', __('Blocco Static Bridge assente, incompleto o posizionato dopo le regole WordPress.', 'static-bridge'), __('Salva di nuovo le Impostazioni; controlla che Apache consenta .htaccess e mod_rewrite.', 'static-bridge'), 'settings');
                }
                if ($this->apache_serves_stale_copy()) {
                    return $this->diagnostic_result($id, __('Regole del server web', 'static-bridge'), 'fail', __('Le regole Apache servono una copia precedente della release: le ultime pubblicazioni non sono visibili.', 'static-bridge'), __('Controlla che .htaccess sia scrivibile e salva di nuovo le Impostazioni; il plugin riprova anche da solo.', 'static-bridge'), 'settings');
                }
                if ('openlitespeed' === $this->web_server_kind()) {
                    // OpenLiteSpeed serves current/ by design (served_copies_enabled()); what matters is a restart.
                    $loaded = $this->openlitespeed_rules_loaded();
                    if (is_wp_error($loaded)) {
                        return $this->diagnostic_result($id, __('Regole del server web', 'static-bridge'), 'warning', $loaded->get_error_message(), __('Salva di nuovo le Impostazioni, riavvia OpenLiteSpeed e ripeti la Diagnostica.', 'static-bridge'), 'settings');
                    }
                    if (!$loaded) {
                        return $this->diagnostic_result($id, __('Regole del server web', 'static-bridge'), 'fail', __('OpenLiteSpeed usa ancora le regole che aveva al suo ultimo avvio: legge il file .htaccess solo quando parte, quindi le ultime regole di Static Bridge non valgono ancora. Finché non riparte i visitatori ricevono le pagine di WP o le regole precedenti.', 'static-bridge'), __('Riavvia OpenLiteSpeed (Graceful Restart dal WebAdmin o dal pannello dell’hosting, oppure lswsctrl restart) e ripeti la Diagnostica. Serve dopo il primo export e dopo ogni salvataggio delle Impostazioni che cambia le regole.', 'static-bridge'), 'settings');
                    }
                    return $this->diagnostic_result($id, __('Regole del server web', 'static-bridge'), 'pass', __('OpenLiteSpeed applica le regole attuali di Static Bridge (verificato con una richiesta di prova); serve current/, che si aggiorna senza riavvii.', 'static-bridge'));
                }
                if ($this->current_release() && false !== strpos($contents, 'wp-content/static-bridge/current/index.html -f')) {
                    return $this->diagnostic_result($id, __('Regole del server web', 'static-bridge'), 'warning', __('Le regole Apache servono current/ invece di una copia immutabile: durante una pubblicazione Apache può raramente inviare una pagina troncata.', 'static-bridge'), __('Controlla il Registro (spazio disco, permessi di wp-content/static-bridge/served, costante STATIC_BRIDGE_APACHE_SERVED_COPIES) e salva di nuovo le Impostazioni.', 'static-bridge'), 'settings');
                }
                return $this->diagnostic_result($id, __('Regole del server web', 'static-bridge'), 'pass', __('Blocco presente e precede le regole WordPress; backend ed eccezioni sono esclusi dal routing statico.', 'static-bridge'));

            case 'security-origin':
                $parts = wp_parse_url(home_url('/'));
                $scheme = isset($parts['scheme']) ? strtolower($parts['scheme']) : 'https';
                $host = isset($parts['host']) ? $parts['host'] : '';
                $home_port = isset($parts['port']) ? (int) $parts['port'] : 0;
                $alternate_scheme = ('https' === $scheme ? 'http' : 'https') . '://' . $host . ($home_port ? ':' . $home_port : '');
                $alternate_port = $scheme . '://' . $host . ':' . ($home_port ? $home_port + 1 : ('https' === $scheme ? 444 : 81));
                $external_host = $scheme . '://' . $host . '.attacker.invalid/';
                $cases = array(
                    $this->same_site_url(home_url('/static-bridge-security-check/')),
                    !$this->same_site_url($external_host),
                    !$this->same_site_url($alternate_scheme . '/'),
                    !$this->same_site_url($alternate_port . '/'),
                    !$this->same_site_url($scheme . '://user@' . $host . ($home_port ? ':' . $home_port : '') . '/'),
                );
                if (in_array(false, $cases, true)) {
                    return $this->diagnostic_result($id, __('Sicurezza richieste in uscita', 'static-bridge'), 'fail', __('Il controllo dell’origine non ha respinto uno o più URL alterati (host, schema, porta o credenziali).', 'static-bridge'), __('Aggiorna Static Bridge e ripeti i test di sicurezza prima di esportare.', 'static-bridge'), 'settings');
                }
                return $this->diagnostic_result($id, __('Sicurezza richieste in uscita', 'static-bridge'), 'pass', __('Le richieste sono limitate a schema, host e porta dell’origine WordPress; redirect HTTP disabilitati e risposte limitate in dimensione.', 'static-bridge'));

            case 'basic-auth':
                return $this->diagnostic_basic_auth_step($id);

            case 'render-origin':
                return $this->diagnostic_render_origin_step($id);

            case 'cloudflare-edge':
                return $this->diagnostic_cloudflare_edge_step($id);

            case 'cloudflare-markup':
                return $this->diagnostic_cloudflare_markup_step($id);

            case 'seo-absolute-urls':
                return $this->diagnostic_seo_absolute_urls_step($id);

            case 'mobile-html':
                return $this->diagnostic_mobile_html_step($id);

            case 'render-failed-url':
                return $this->diagnostic_failed_export_url_step($id, isset($step['url']) ? $step['url'] : '');

            case 'inventory':
                return $this->diagnostic_inventory_step($id);

            case 'security-release-access':
                $release = $this->current_release();
                $is_current_release = (bool) $release;
                if (!$release) {
                    $release_root = $this->safe_release_root(false);
                    $candidates = '' !== $release_root ? glob(trailingslashit($release_root) . '*', GLOB_ONLYDIR) : false;
                    if (is_array($candidates)) {
                        rsort($candidates, SORT_STRING);
                        foreach ($candidates as $candidate) {
                            if (is_link($candidate)) {
                                continue;
                            }
                            $candidate_real = realpath($candidate);
                            if (!$candidate_real || dirname($candidate_real) !== $release_root
                                || !preg_match('/^[A-Za-z0-9_-]{1,100}$/', basename($candidate_real))) {
                                continue;
                            }
                            if (is_file($candidate_real . '/manifest.json') || is_file($candidate_real . '/index.html')) {
                                $release = $candidate_real;
                                break;
                            }
                        }
                    }
                }
                if (!$release) {
                    return $this->diagnostic_result($id, __('Protezione delle release precedenti', 'static-bridge'), 'skip', __('Nessuna release attiva o archiviata con file HTML o manifest da verificare.', 'static-bridge'));
                }
                $release_id = basename($release);
                if (!preg_match('/^[A-Za-z0-9_-]{1,100}$/', $release_id)) {
                    return $this->diagnostic_result($id, __('Protezione delle release precedenti', 'static-bridge'), 'fail', __('Il nome della release da verificare non è valido.', 'static-bridge'), __('Controlla la cartella delle versioni e ripeti la diagnostica.', 'static-bridge'), 'settings');
                }
                $artifacts = array();
                foreach (array('manifest.json', 'index.html') as $artifact) {
                    if (is_file(trailingslashit($release) . $artifact)) {
                        $artifacts[] = $artifact;
                    }
                }
                if (empty($artifacts)) {
                    if ($is_current_release) {
                        return $this->diagnostic_result($id, __('Protezione delle release precedenti', 'static-bridge'), 'fail', __('La release attiva non contiene manifest.json né index.html: non è possibile verificarne la protezione HTTP.', 'static-bridge'), __('Ripara o rigenera la release e ripeti la diagnostica.', 'static-bridge'), 'generate');
                    }
                    return $this->diagnostic_result($id, __('Protezione delle release precedenti', 'static-bridge'), 'skip', __('La cartella archivio non contiene file HTML o manifest da verificare.', 'static-bridge'));
                }
                $checked = array();
                foreach ($artifacts as $artifact) {
                    $url = home_url('/wp-content/static-bridge/releases/' . rawurlencode($release_id) . '/' . rawurlencode($artifact));
                    $response = $this->remote_get($url, 10, 262144);
                    if (is_wp_error($response)) {
                        return $this->diagnostic_result($id, __('Protezione delle release precedenti', 'static-bridge'), 'fail', $response->get_error_message(), __('Verifica dal browser che file HTML e manifest delle release non siano accessibili direttamente; controlla le regole del server web.', 'static-bridge'), 'settings', $url);
                    }
                    $status = wp_remote_retrieve_response_code($response);
                    if (!in_array($status, array(403, 404), true)) {
                        return $this->diagnostic_result($id, __('Protezione delle release precedenti', 'static-bridge'), 'fail', sprintf(/* translators: 1: file name, 2: HTTP status code */ __('Il file %1$s risponde HTTP %2$s: i contenuti della release possono essere esposti direttamente.', 'static-bridge'), $artifact, $status), __('Blocca l’accesso diretto a /wp-content/static-bridge/releases/ sul server web e ripeti il test.', 'static-bridge'), 'settings', $url);
                    }
                    $checked[] = sprintf('%1$s: HTTP %2$s', $artifact, $status);
                }
                return $this->diagnostic_result($id, __('Protezione delle release precedenti', 'static-bridge'), 'pass', sprintf(/* translators: 1: release ID, 2: list of checked files with their HTTP status */ __('File della release %1$s non accessibili direttamente (%2$s).', 'static-bridge'), $release_id, implode(', ', $checked)), '', '', $url);

            case 'static':
                $label = isset($step['label']) ? $step['label'] : __('Pagina statica', 'static-bridge');
                $path = isset($step['path']) ? $step['path'] : '/';
                $file = trailingslashit($this->static_root()) . 'releases/' . sanitize_file_name($run['release']) . '/' . ltrim($step['file'], '/');
                if (!is_readable($file)) {
                    return $this->diagnostic_result($id, $label, 'fail', __('Il file HTML della release non è leggibile.', 'static-bridge'), __('Rigenera la release e verifica i permessi della cartella statica.', 'static-bridge'), 'generate', home_url($path));
                }
                $response = $this->remote_get($this->route_url($path), 15);
                if (is_wp_error($response)) {
                    return $this->diagnostic_result($id, $label, 'fail', $response->get_error_message(), __('Verifica DNS locale, certificato del dominio e routing Apache; poi ripeti il test.', 'static-bridge'), 'settings', home_url($path));
                }
                $status = wp_remote_retrieve_response_code($response);
                $body = wp_remote_retrieve_body($response);
                $content_type = (string) wp_remote_retrieve_header($response, 'content-type');
                if ($this->server_uses_nginx() && 'static' !== strtolower((string) wp_remote_retrieve_header($response, 'x-static-bridge-route'))) {
                    if (200 === $status && ('' === $content_type || false !== stripos($content_type, 'text/html'))) {
                        return $this->diagnostic_result($id, $label, 'fail', __('La risposta non contiene il marcatore del routing statico Nginx.', 'static-bridge'), __('Controlla la location @static_bridge e che l’header X-Static-Bridge-Route sia presente solo sul percorso statico.', 'static-bridge'), 'settings', home_url($path));
                    }
                }
                return $this->diagnostic_static_route_parity_result($id, $label, $this->route_url($path), $file, $this->current_release(), $response);

            case 'security-headers':
                return $this->diagnostic_security_headers_step($id);

            case 'complianz-banner':
                return $this->diagnostic_complianz_step($id);

            case 'static-parity':
                return $this->diagnostic_static_parity_step($step, $run);

            case 'static-route-parity':
                return $this->diagnostic_static_route_step($step, $run);

            case 'builder-page':
                $path = isset($step['path']) ? $step['path'] : '/';
                $url = $this->route_url($path);
                $builders = isset($step['builders']) ? array_map(array($this, 'builder_label'), (array) $step['builders']) : array();
                $label = sprintf(/* translators: 1: page builder names, 2: page title or path */ __('Rendering statico %1$s: %2$s', 'static-bridge'), implode(', ', $builders), isset($step['title']) ? $step['title'] : $path);
                $relative = $this->relative_html_path($url);
                $file = is_wp_error($relative) ? '' : trailingslashit($this->static_root()) . 'releases/' . sanitize_file_name($run['release']) . '/' . $relative;
                if ('' === $file || !is_readable($file)) {
                    return $this->diagnostic_result($id, $label, 'warning', __('La pagina del builder non è ancora presente nella release attiva.', 'static-bridge'), __('Esegui una generazione completa oppure salva di nuovo la pagina per accodarne l’aggiornamento incrementale.', 'static-bridge'), 'generate', $url);
                }
                $response = $this->remote_get($url, 15);
                if (is_wp_error($response)) {
                    return $this->diagnostic_result($id, $label, 'fail', $response->get_error_message(), __('Verifica che il rendering WordPress e gli asset del builder siano raggiungibili.', 'static-bridge'), 'settings', $url);
                }
                $status = wp_remote_retrieve_response_code($response);
                $body = wp_remote_retrieve_body($response);
                if ($this->server_uses_nginx() && 200 === $status && 'static' !== strtolower((string) wp_remote_retrieve_header($response, 'x-static-bridge-route'))) {
                    return $this->diagnostic_result($id, $label, 'fail', __('Nginx non ha marcato la risposta come HTML statico.', 'static-bridge'), __('Controlla il blocco Nginx e rigenera se l’URL non è più presente nella release.', 'static-bridge'), 'settings', $url);
                }
                return $this->diagnostic_static_route_parity_result($id, $label, $url, $file, $this->current_release(), $response);

            case 'incremental-queue':
                $queue = $this->incremental_queue();
                if (empty($this->settings()['incremental_enabled'])) {
                    return $this->diagnostic_result($id, __('Aggiornamenti incrementali', 'static-bridge'), empty($queue) ? 'skip' : 'warning', empty($queue) ? __('Automatismo disattivato nelle Impostazioni.', 'static-bridge') : sprintf(/* translators: %s: number of queued paths */ _n('Automatismo disattivato con %s percorso ancora in coda.', 'Automatismo disattivato con %s percorsi ancora in coda.', count($queue), 'static-bridge'), number_format_i18n(count($queue))), __('Riattiva l’opzione o avvia una generazione completa.', 'static-bridge'), 'settings');
                }
                if (empty($queue)) {
                    return $this->diagnostic_result($id, __('Aggiornamenti incrementali', 'static-bridge'), 'pass', __('Automatismo attivo; non ci sono URL in attesa.', 'static-bridge'));
                }
                if (!wp_next_scheduled('static_bridge_process_incremental_queue')) {
                    return $this->diagnostic_result($id, __('Aggiornamenti incrementali', 'static-bridge'), 'fail', sprintf(/* translators: %s: number of queued URLs */ __('%s URL in coda senza evento WP-Cron pianificato.', 'static-bridge'), number_format_i18n(count($queue))), __('Verifica WP-Cron o abilita un cron di sistema; salva nuovamente un articolo per riprogrammare la coda.', 'static-bridge'), 'settings');
                }
                return $this->diagnostic_result($id, __('Aggiornamenti incrementali', 'static-bridge'), 'pass', sprintf(/* translators: %1$s: number of queued URLs */ __('%1$s URL in coda; WP-Cron pianificato per l’elaborazione.', 'static-bridge'), number_format_i18n(count($queue))));

            case 'admin':
                $response = $this->remote_get(admin_url(), 15);
                if (is_wp_error($response)) {
                    return $this->diagnostic_result($id, __('wp-admin sul dominio', 'static-bridge'), 'fail', $response->get_error_message(), __('Verifica il routing WordPress e che wp-admin non venga catturato dalle regole statiche.', 'static-bridge'), 'settings', admin_url());
                }
                $status = wp_remote_retrieve_response_code($response);
                $location = (string) wp_remote_retrieve_header($response, 'location');
                if ($this->diagnostic_served_static($response)) {
                    return $this->server_uses_nginx()
                        ? $this->diagnostic_result($id, __('wp-admin sul dominio', 'static-bridge'), 'fail', __('Nginx ha instradato wp-admin alla release statica.', 'static-bridge'), __('Controlla le esclusioni Nginx e ricarica la configurazione.', 'static-bridge'), 'settings', admin_url())
                        : $this->diagnostic_apache_served_static($id, __('wp-admin sul dominio', 'static-bridge'), admin_url());
                }
                if ($status >= 200 && $status < 400 && ('' === $location || false !== strpos($location, 'wp-login.php') || false !== strpos($location, 'wp-admin'))) {
                    return $this->diagnostic_result($id, __('wp-admin sul dominio', 'static-bridge'), 'pass', sprintf(/* translators: 1: HTTP status code, 2: note about the expected redirect to login, or empty */ __('HTTP %1$s: backend raggiungibile%2$s.', 'static-bridge'), $status, $status >= 300 ? __('; reindirizzamento al login atteso', 'static-bridge') : ''), '', '', admin_url());
                }
                return $this->diagnostic_result($id, __('wp-admin sul dominio', 'static-bridge'), 'fail', sprintf(/* translators: %s: HTTP status code */ __('Risposta HTTP %s o reindirizzamento inatteso.', 'static-bridge'), $status), __('Escludi wp-admin dal routing statico e controlla le regole del server.', 'static-bridge'), 'settings', admin_url());

            case 'cookie-bypass':
            case 'post-bypass':
                $is_post = 'post-bypass' === $step['type'];
                $label = $is_post ? __('Richiesta POST alla homepage', 'static-bridge') : __('Visitatore con cookie di accesso', 'static-bridge');
                if (!$this->current_release()) {
                    return $this->diagnostic_result($id, $label, 'skip', __('Nessuna release statica attiva: il controllo sarà possibile dopo la prima generazione completa.', 'static-bridge'));
                }
                $response = $this->remote_get(home_url('/'), 15, self::MAX_HTTP_RESPONSE_SIZE, false, $is_post
                    ? array('method' => 'POST')
                    // A cookie name WordPress never issues: it matches the guard's prefix but authenticates nobody.
                    : array('headers' => array('Cookie' => 'wordpress_logged_in_static_bridge_diagnostic=1')));
                if (is_wp_error($response)) {
                    return $this->diagnostic_result($id, $label, 'fail', $response->get_error_message(), __('Verifica che il dominio sia raggiungibile dal processo PHP e ripeti la diagnostica.', 'static-bridge'));
                }
                if ('static' === strtolower((string) wp_remote_retrieve_header($response, 'x-static-bridge-route'))) {
                    return $this->diagnostic_result(
                        $id,
                        $label,
                        'fail',
                        $is_post
                            ? __('Nginx ha servito la copia statica a una richiesta POST: gli invii verso le pagine non raggiungerebbero WordPress.', 'static-bridge')
                            : __('Nginx ha servito la copia statica a una richiesta con cookie di accesso WordPress: gli utenti connessi vedrebbero le pagine statiche.', 'static-bridge'),
                        $is_post
                            ? __('Reinstalla il blocco Nginx mostrato in Impostazioni: manca la condizione sul metodo della richiesta (solo GET e HEAD).', 'static-bridge')
                            : __('Reinstalla il blocco Nginx mostrato in Impostazioni: manca la condizione sui cookie di accesso.', 'static-bridge'),
                        'settings'
                    );
                }
                return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: %s: HTTP status code */ __('Richiesta gestita da WordPress, non dalla copia statica (HTTP %s).', 'static-bridge'), wp_remote_retrieve_response_code($response)));
            case 'login':
                return $this->diagnostic_http_step($id, __('Login WordPress', 'static-bridge'), home_url('/wp-login.php'), 'login');

            case 'rest':
                return $this->diagnostic_http_step($id, __('REST API WordPress', 'static-bridge'), home_url('/wp-json/'), 'json');

            case 'feed':
                return $this->diagnostic_http_step($id, __('Feed RSS', 'static-bridge'), home_url('/feed/'), 'feed');

            case 'bypass':
                // 2.5.0: with the tracking parameters ignored, one of them next to a parameter WP reads still reaches WP.
                $url = home_url('/') . '?' . ('' !== $this->diagnostic_tracking_query() ? $this->diagnostic_tracking_query() . '&' : '') . 'static_bridge_bypass=1';
                return $this->diagnostic_http_step($id, __('Query string dinamica', 'static-bridge'), $url, 'html');

            case 'tracking-query':
                return $this->diagnostic_tracking_query_step($id, $run);

            case 'dynamic-cookies':
                return $this->diagnostic_dynamic_cookies_step($id);

            case 'nginx-rules':
                return $this->diagnostic_nginx_rules_step($id);

            case 'dynamic':
                $path = isset($step['path']) ? $step['path'] : '/';
                $url = $this->route_url($path);
                $rules = is_readable(trailingslashit(ABSPATH) . '.htaccess') ? file_get_contents(trailingslashit(ABSPATH) . '.htaccess') : '';
                if (!$this->server_uses_nginx() && !$this->diagnostic_has_exclusion_rules($rules)) {
                    return $this->diagnostic_result($id, sprintf(/* translators: %s: path */ __('Percorso dinamico %s', 'static-bridge'), $path), 'fail', __('La regola Apache delle esclusioni configurate non è presente.', 'static-bridge'), __('Salva di nuovo le Impostazioni e verifica che Static Bridge gestisca il blocco .htaccess.', 'static-bridge'), 'settings', $url);
                }
                $response = $this->remote_get($url, 15);
                if (is_wp_error($response)) {
                    return $this->diagnostic_result($id, sprintf(/* translators: %s: path */ __('Percorso dinamico %s', 'static-bridge'), $path), 'fail', $response->get_error_message(), __('Verifica che il percorso esista e resti escluso dalla generazione statica.', 'static-bridge'), 'settings', $url);
                }
                $status = wp_remote_retrieve_response_code($response);
                if ($this->diagnostic_served_static($response)) {
                    return $this->server_uses_nginx()
                        ? $this->diagnostic_result($id, sprintf(/* translators: %s: path */ __('Percorso dinamico %s', 'static-bridge'), $path), 'fail', __('Nginx ha servito una release statica invece di passare il percorso a WordPress.', 'static-bridge'), __('Rigenera il blocco Nginx dalle impostazioni e aggiungi il percorso dinamico, poi ricarica Nginx.', 'static-bridge'), 'settings', $url)
                        : $this->diagnostic_apache_served_static($id, sprintf(/* translators: %s: path */ __('Percorso dinamico %s', 'static-bridge'), $path), $url);
                }
                if ($status >= 200 && $status < 400) {
                    $server_label = $this->server_uses_nginx() ? __('esclusione Nginx configurata', 'static-bridge') : __('esclusione Apache configurata', 'static-bridge');
                    return $this->diagnostic_result($id, sprintf(/* translators: %s: path */ __('Percorso dinamico %s', 'static-bridge'), $path), 'pass', sprintf(/* translators: 1: HTTP status code, 2: “Nginx exclusion configured” or “Apache exclusion configured” */ __('HTTP %1$s; %2$s e risposta WordPress dinamica raggiungibile.', 'static-bridge'), $status, $server_label), '', '', $url);
                }
                if ($status < 500) {
                    return $this->diagnostic_result($id, sprintf(/* translators: %s: path */ __('Percorso dinamico %s', 'static-bridge'), $path), 'warning', sprintf(/* translators: %s: HTTP status code */ __('WordPress risponde HTTP %s; il routing dinamico è raggiungibile, ma il percorso non restituisce una pagina valida.', 'static-bridge'), $status), __('Controlla che l’URL sia corretto e che la pagina o il modulo esista.', 'static-bridge'), 'settings', $url);
                }
                return $this->diagnostic_result($id, sprintf(/* translators: %s: path */ __('Percorso dinamico %s', 'static-bridge'), $path), 'fail', sprintf(/* translators: %s: HTTP status code */ __('Risposta HTTP %s.', 'static-bridge'), $status), __('Controlla plugin e template che gestiscono questo percorso.', 'static-bridge'), 'settings', $url);

            case 'form':
                $path = isset($step['path']) ? $step['path'] : '/';
                $url = $this->route_url($path);
                $label = sprintf(/* translators: %s: page path */ __('Fluent Forms: %s', 'static-bridge'), $path);
                $response = $this->remote_get($url, 15);
                if (is_wp_error($response)) {
                    return $this->diagnostic_result($id, $label, 'fail', $response->get_error_message(), __('Verifica che il percorso sia raggiungibile e che Fluent Forms sia attivo.', 'static-bridge'), 'settings', $url);
                }
                $status = wp_remote_retrieve_response_code($response);
                $body = wp_remote_retrieve_body($response);
                $content_type = strtolower((string) wp_remote_retrieve_header($response, 'content-type'));
                if ($status < 200 || $status >= 400 || ('' !== $content_type && false === strpos($content_type, 'text/html'))) {
                    return $this->diagnostic_result($id, $label, 'fail', sprintf(/* translators: 1: HTTP status code, 2: Content-Type */ __('La pagina del modulo risponde HTTP %1$s; Content-Type %2$s.', 'static-bridge'), $status, '' !== $content_type ? $content_type : __('non indicato', 'static-bridge')), __('Controlla URL, template e routing Static Bridge.', 'static-bridge'), 'settings', $url);
                }
                $has_form = false !== stripos($body, 'fluentform') || (bool) preg_match('/data-form_id\s*=\s*["\']\d+["\']/i', $body);
                if (!$has_form) {
                    return $this->diagnostic_result($id, $label, 'fail', __('Pagina raggiungibile, ma il markup Fluent Forms non compare nella risposta HTML.', 'static-bridge'), __('Verifica lo shortcode o il blocco nella pagina, quindi ricarica la scheda Moduli.', 'static-bridge'), 'settings', $url);
                }
                $mode = isset($step['mode']) ? $step['mode'] : 'static';
                if ('dynamic' === $mode) {
                    $rules = is_readable(trailingslashit(ABSPATH) . '.htaccess') ? file_get_contents(trailingslashit(ABSPATH) . '.htaccess') : '';
                    if (!$this->server_uses_nginx() && !$this->diagnostic_has_exclusion_rules($rules)) {
                        return $this->diagnostic_result($id, $label, 'fail', __('Il modulo è raggiungibile, ma le regole delle pagine dinamiche non risultano attive.', 'static-bridge'), __('Salva di nuovo la modalità nella scheda Moduli e verifica .htaccess.', 'static-bridge'), 'forms', $url);
                    }
                    if ($this->diagnostic_served_static($response)) {
                        return $this->server_uses_nginx()
                            ? $this->diagnostic_result($id, $label, 'fail', __('Nginx ha servito la pagina del modulo dalla release invece di mantenerla dinamica.', 'static-bridge'), __('Rigenera il blocco Nginx dalle impostazioni e ricarica Nginx.', 'static-bridge'), 'settings', $url)
                            : $this->diagnostic_apache_served_static($id, $label, $url);
                    }
                    return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: %1$s: HTTP status code */ __('HTTP %1$s; pagina WordPress dinamica e markup Fluent Forms presente. Nessun invio è stato eseguito.', 'static-bridge'), $status), '', '', $url);
                }
                if (empty($step['file_exists'])) {
                    return $this->diagnostic_result($id, $label, 'warning', __('Il modulo è raggiungibile con il fallback WordPress, ma la copia statica non esiste ancora.', 'static-bridge'), __('Genera una nuova release: il routing passerà alla copia statica al termine della pubblicazione.', 'static-bridge'), 'generate', $url);
                }
                $relative = $this->relative_html_path($url);
                $file = is_wp_error($relative) ? '' : trailingslashit($this->current_release()) . $relative;
                $actual_hash = hash('sha256', $body);
                $expected_hash = $file && is_readable($file) ? @hash_file('sha256', $file) : '';
                if (!is_string($expected_hash) || '' === $expected_hash || !hash_equals($expected_hash, $actual_hash)) {
                    return $this->diagnostic_result($id, $label, 'fail', __('Il markup è presente, ma la risposta pubblica non coincide con il file HTML statico attivo.', 'static-bridge'), __('Controlla routing e cache oppure rigenera la release.', 'static-bridge'), 'generate', $url);
                }
                if ($this->server_uses_nginx() && 'static' !== strtolower((string) wp_remote_retrieve_header($response, 'x-static-bridge-route'))) {
                    return $this->diagnostic_result($id, $label, 'fail', __('Il markup corrisponde al file, ma Nginx non ha confermato il routing statico.', 'static-bridge'), __('Installa o aggiorna il blocco Nginx mostrato nelle Impostazioni e ricarica il server.', 'static-bridge'), 'settings', $url);
                }
                if (false === stripos($body, 'admin-ajax.php')) {
                    return $this->diagnostic_result($id, $label, 'warning', __('La copia statica corrisponde al file, ma non è stato trovato l’endpoint AJAX WordPress nel markup.', 'static-bridge'), __('Verifica gli script Fluent Forms e l’endpoint configurato dal plugin. Il test non invia dati.', 'static-bridge'), 'forms', $url);
                }
                return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: %1$s: HTTP status code */ __('HTTP %1$s; HTML statico verificato con SHA-256 e endpoint AJAX WordPress presente. Nessun invio è stato eseguito.', 'static-bridge'), $status), '', '', $url);

            case 'woocommerce-route':
                $path = isset($step['path']) ? $step['path'] : '/';
                $url = $this->route_url($path);
                $label = sprintf(/* translators: 1: page name (Cart, Checkout, My account), 2: path */ __('WooCommerce: %1$s (%2$s)', 'static-bridge'), isset($step['label']) ? $step['label'] : __('pagina transazionale', 'static-bridge'), $path);
                if (!$this->woocommerce_is_active()) {
                    return $this->diagnostic_result($id, $label, 'skip', __('Integrazione WooCommerce non attiva; controllo non applicabile.', 'static-bridge'));
                }
                if (!$this->is_excluded_path($path)) {
                    return $this->diagnostic_result($id, $label, 'fail', __('Il percorso non risulta escluso dall’esportazione statica.', 'static-bridge'), __('Salva le Impostazioni con l’integrazione WooCommerce attiva.', 'static-bridge'), 'settings', $url);
                }
                $rules = is_readable(trailingslashit(ABSPATH) . '.htaccess') ? file_get_contents(trailingslashit(ABSPATH) . '.htaccess') : '';
                if (!$this->server_uses_nginx() && !$this->diagnostic_has_exclusion_rules($rules)) {
                    return $this->diagnostic_result($id, $label, 'fail', __('Le regole Apache non contengono le esclusioni WooCommerce attese.', 'static-bridge'), __('Salva di nuovo le Impostazioni e verifica che .htaccess sia scrivibile.', 'static-bridge'), 'settings', $url);
                }
                $response = $this->remote_get($url, 15);
                if (is_wp_error($response)) {
                    return $this->diagnostic_result($id, $label, 'fail', $response->get_error_message(), __('Verifica che la pagina WooCommerce sia pubblicata e raggiungibile.', 'static-bridge'), 'settings', $url);
                }
                $status = wp_remote_retrieve_response_code($response);
                if ($this->diagnostic_served_static($response)) {
                    return $this->server_uses_nginx()
                        ? $this->diagnostic_result($id, $label, 'fail', __('Nginx ha servito una pagina WooCommerce transazionale dalla release statica.', 'static-bridge'), __('Rigenera il blocco Nginx con l’integrazione WooCommerce attiva e ricarica Nginx.', 'static-bridge'), 'settings', $url)
                        : $this->diagnostic_apache_served_static($id, $label, $url);
                }
                if ($status < 200 || $status >= 400) {
                    return $this->diagnostic_result($id, $label, 'fail', sprintf(/* translators: %s: HTTP status code */ __('La pagina transazionale risponde HTTP %s.', 'static-bridge'), $status), __('Controlla la pagina configurata in WooCommerce e il relativo endpoint.', 'static-bridge'), 'settings', $url);
                }
                return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: %1$s: HTTP status code */ __('HTTP %1$s; percorso escluso dalla release statica e servito dal routing WordPress.', 'static-bridge'), $status), '', '', $url);

            case 'woocommerce-disabled':
                return $this->diagnostic_result($id, __('Integrazione WooCommerce', 'static-bridge'), 'warning', __('WooCommerce è attivo ma l’integrazione è stata spenta: carrello, checkout, account e /wc-api/ restano a WordPress, ma prezzi, saldi e scorte del catalogo statico non si aggiornano e i nonce della Store API non vengono rinnovati.', 'static-bridge'), __('Accendi «Integrazione WooCommerce» in Impostazioni, salva e avvia un export completo.', 'static-bridge'), 'settings');

            case 'woocommerce-endpoint':
                $path = isset($step['path']) ? $step['path'] : '/wc-api/static-bridge-diagnostic/';
                $url = $this->route_url($path);
                $label = __('WooCommerce: risposte dei pagamenti (/wc-api/)', 'static-bridge');
                if (!$this->woocommerce_is_active()) {
                    return $this->diagnostic_result($id, $label, 'skip', __('Integrazione WooCommerce non attiva; controllo non applicabile.', 'static-bridge'));
                }
                if (!$this->is_excluded_path($path)) {
                    return $this->diagnostic_result($id, $label, 'fail', __('/wc-api/ non è escluso dalla copia statica.', 'static-bridge'), __('Salva le Impostazioni con l’integrazione WooCommerce attiva.', 'static-bridge'), 'settings', $url);
                }
                $rules = is_readable(trailingslashit(ABSPATH) . '.htaccess') ? file_get_contents(trailingslashit(ABSPATH) . '.htaccess') : '';
                if (!$this->server_uses_nginx() && !$this->diagnostic_has_exclusion_rules($rules)) {
                    return $this->diagnostic_result($id, $label, 'fail', __('Le regole Apache non escludono /wc-api/ e /wc-auth/.', 'static-bridge'), __('Salva di nuovo le Impostazioni e verifica che .htaccess sia scrivibile.', 'static-bridge'), 'settings', $url);
                }
                $response = $this->remote_get($url, 15);
                if (is_wp_error($response)) {
                    return $this->diagnostic_result($id, $label, 'fail', $response->get_error_message(), __('Verifica che il sito risponda agli indirizzi /wc-api/.', 'static-bridge'), 'settings', $url);
                }
                $status = (int) wp_remote_retrieve_response_code($response);
                if ($this->diagnostic_served_static($response)) {
                    return $this->diagnostic_result($id, $label, 'fail', sprintf(/* translators: %s: HTTP status code */ __('Il server ha risposto a /wc-api/ dalla copia statica (HTTP %s): i ritorni dei pagamenti non arriverebbero a WooCommerce.', 'static-bridge'), $status), $this->server_uses_nginx() ? __('Ricopia il blocco Nginx mostrato in Impostazioni e ricarica Nginx.', 'static-bridge') : $this->diagnostic_apache_static_remediation(), 'settings', $url);
                }
                // WooCommerce answers an unknown /wc-api/ name with "-1" (HTTP 400): it reached WordPress.
                if ('-1' === trim((string) wp_remote_retrieve_body($response)) || 200 === $status || 400 === $status) {
                    return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: %s: HTTP status code */ __('HTTP %s da WooCommerce: le richieste e i ritorni dei gateway di pagamento arrivano a WordPress.', 'static-bridge'), $status), '', '', $url);
                }
                return $this->diagnostic_result($id, $label, 404 === $status ? 'fail' : 'warning', sprintf(/* translators: %s: HTTP status code */ __('/wc-api/ risponde HTTP %s invece di arrivare a WooCommerce.', 'static-bridge'), $status), __('Controlla le regole del server e i plugin di sicurezza davanti a /wc-api/.', 'static-bridge'), 'settings', $url);

            case 'woocommerce-store-api':
                $label = __('WooCommerce: Store API (mini-carrello, carrello e checkout a blocchi)', 'static-bridge');
                if (!$this->woocommerce_integration_enabled()) {
                    return $this->diagnostic_result($id, $label, 'skip', __('Integrazione WooCommerce non attiva; controllo non applicabile.', 'static-bridge'));
                }
                $url = function_exists('rest_url') ? rest_url('wc/store/v1/cart') : home_url('/wp-json/wc/store/v1/cart');
                $response = $this->remote_get($url, 15);
                if (is_wp_error($response)) {
                    return $this->diagnostic_result($id, $label, 'fail', $response->get_error_message(), __('Verifica che la REST API di WordPress sia raggiungibile.', 'static-bridge'), 'settings', $url);
                }
                $status = (int) wp_remote_retrieve_response_code($response);
                $cart = json_decode((string) wp_remote_retrieve_body($response), true);
                $nonce = wp_remote_retrieve_header($response, 'nonce');
                if (200 === $status && is_array($cart) && array_key_exists('items', $cart) && is_string($nonce) && '' !== $nonce
                    && 'static' !== strtolower((string) wp_remote_retrieve_header($response, 'x-static-bridge-route'))) {
                    return $this->diagnostic_result($id, $label, 'pass', __('La Store API risponde da WordPress con un nonce fresco; le pagine statiche ricevono quelli nuovi da assets/woocommerce-static.js.', 'static-bridge'), '', '', $url);
                }
                return $this->diagnostic_result($id, $label, 'fail', sprintf(/* translators: %s: HTTP status code */ __('La Store API risponde HTTP %s senza il carrello o senza il nonce.', 'static-bridge'), $status), __('Controlla plugin di sicurezza, firewall o cache davanti a /wp-json/wc/store/: deve restare dinamica.', 'static-bridge'), 'settings', $url);

            case 'woocommerce-catalog':
                $label = __('WooCommerce: catalogo aggiornato', 'static-bridge');
                if (!$this->woocommerce_integration_enabled()) {
                    return $this->diagnostic_result($id, $label, 'skip', __('Integrazione WooCommerce non attiva; controllo non applicabile.', 'static-bridge'));
                }
                if (empty($this->settings()['incremental_enabled'])) {
                    return $this->diagnostic_result($id, $label, 'warning', __('Aggiornamenti incrementali spenti: prezzi, saldi e scorte del catalogo statico restano quelli dell’ultima generazione.', 'static-bridge'), __('Accendi gli aggiornamenti incrementali in Impostazioni, oppure avvia un export completo dopo ogni cambio del catalogo.', 'static-bridge'), 'settings');
                }
                $release = $this->current_release();
                if (!$release) {
                    return $this->diagnostic_result($id, $label, 'skip', __('Nessuna release pubblicata da confrontare.', 'static-bridge'));
                }
                $queued = array();
                foreach ($this->incremental_queue() as $item) {
                    if (is_array($item) && !empty($item['url'])) {
                        $queued[$this->normalize_route_path($item['url'])] = true;
                    }
                }
                $dynamic = $this->woocommerce_dynamic_routes();
                $checked = 0;
                $stale = array();
                foreach (get_posts(array('post_type' => 'product', 'post_status' => 'publish', 'posts_per_page' => 5, 'orderby' => 'modified', 'order' => 'DESC', 'no_found_rows' => true)) as $product) {
                    $path = $this->normalize_route_path(get_permalink($product));
                    if ('' === $path || isset($queued[$path]) || isset($dynamic[$path]) || $this->is_excluded_path($path) || !empty($product->post_password)) {
                        continue;
                    }
                    $checked++;
                    $relative = $this->relative_html_path(home_url($path));
                    $file = is_wp_error($relative) ? '' : trailingslashit($release) . $relative;
                    $modified = strtotime((string) $product->post_modified_gmt . ' UTC');
                    if ('' === $file || !is_file($file)) {
                        $stale[] = sprintf(/* translators: %s: path */ __('%s (nessuna copia)', 'static-bridge'), $path);
                    } elseif ($modified && filemtime($file) + 1 < $modified) {
                        $stale[] = $path;
                    }
                }
                if (empty($stale)) {
                    return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: %d: number of products */ __('Le copie dei prodotti modificati più di recente sono aggiornate o in coda (%d controllati).', 'static-bridge'), $checked));
                }
                return $this->diagnostic_result($id, $label, 'warning', sprintf(/* translators: %s: comma-separated paths */ __('Copie più vecchie dell’ultima modifica del prodotto: %s.', 'static-bridge'), implode(', ', $stale)), __('Rigenera la pagina con il push del prodotto o avvia un export completo. Se succede spesso, controlla che WP-Cron giri con un cron di sistema e che nessun plugin cambi i prodotti direttamente nel database.', 'static-bridge'), 'generate');

            case 'woocommerce-dynamic':
                $label = __('WooCommerce: pagine lasciate a WordPress', 'static-bridge');
                if (!$this->woocommerce_integration_enabled()) {
                    return $this->diagnostic_result($id, $label, 'skip', __('Integrazione WooCommerce non attiva; controllo non applicabile.', 'static-bridge'));
                }
                $routes = $this->woocommerce_dynamic_routes();
                if (empty($routes)) {
                    return $this->diagnostic_result($id, $label, 'pass', __('Nessuna pagina del negozio lasciata a WordPress oltre a carrello, checkout e account.', 'static-bridge'));
                }
                $listed = array();
                foreach (array_slice($routes, 0, 5, true) as $path => $info) {
                    $listed[] = $path . ' (' . $info['reason'] . ')';
                }
                $with_nonces = count(array_filter($routes, function ($info) {
                    return !empty($info['actions']);
                }));
                if ($with_nonces > 0) {
                    return $this->diagnostic_result($id, $label, 'warning', sprintf(/* translators: 1: number of pages, 2: number of pages with nonces, 3: list of pages with reasons */ __('%1$d pagine servite da WordPress, %2$d per nonce che Static Bridge non sa rinnovare: %3$s.', 'static-bridge'), count($routes), $with_nonces, implode('; ', $listed)), __('Funzionano, ma senza i vantaggi della copia statica. Se il nonce viene da un plugin (pagamenti, liste dei desideri, confronto) chiedi se può non stamparlo ai visitatori anonimi, oppure, se scaduto non rompe niente, dichiaralo con il filtro static_bridge_static_nonce_actions.', 'static-bridge'));
                }
                return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: 1: number of pages, 2: list of pages with reasons */ __('%1$d pagine servite da WordPress come vuole WooCommerce: %2$s.', 'static-bridge'), count($routes), implode('; ', $listed)));

            case 'woocommerce-settings':
                $label = __('WooCommerce: impostazioni del negozio', 'static-bridge');
                if (!$this->woocommerce_integration_enabled()) {
                    return $this->diagnostic_result($id, $label, 'skip', __('Integrazione WooCommerce non attiva; controllo non applicabile.', 'static-bridge'));
                }
                $problems = array();
                if ('yes' === get_option('woocommerce_coming_soon')) {
                    $problems[] = __('il negozio è in modalità «Prossimamente»: le copie statiche mostrano la pagina d’attesa', 'static-bridge');
                }
                $address = get_option('woocommerce_default_customer_address');
                if ('geolocation_ajax' === $address) {
                    $problems[] = __('la geolocalizzazione «con supporto della cache» aggiunge ?v=… agli indirizzi, e ogni pagina con la query va a WordPress', 'static-bridge');
                } elseif ('geolocation' === $address && 'yes' === get_option('woocommerce_calc_taxes')) {
                    $problems[] = __('le tasse dipendono dalla posizione del cliente: la copia statica mostra i prezzi per il paese del negozio', 'static-bridge');
                }
                if (empty($problems)) {
                    return $this->diagnostic_result($id, $label, 'pass', __('Nessuna impostazione del negozio in contrasto con le copie statiche.', 'static-bridge'));
                }
                return $this->diagnostic_result($id, $label, 'warning', ucfirst(implode('; ', $problems)) . '.', __('Cambia queste impostazioni in WooCommerce → Impostazioni, oppure aggiungi ai percorsi dinamici le pagine interessate.', 'static-bridge'), 'settings');

            case 'woocommerce-missing':
                return $this->diagnostic_result($id, __('Integrazione WooCommerce', 'static-bridge'), 'warning', __('Interruttore attivo, ma non sono state trovate pagine Carrello, Checkout o Account pubblicate.', 'static-bridge'), __('Configura e pubblica le pagine WooCommerce, poi salva di nuovo le Impostazioni.', 'static-bridge'), 'settings');

            case 'strict':
                $path = '/static-bridge-diagnostic-' . strtolower(wp_generate_password(10, false, false)) . '/';
                $url = $this->route_url($path);
                $response = $this->remote_get($url, 15);
                if (is_wp_error($response)) {
                    return $this->diagnostic_result($id, __('Modalità strict: pagina inesistente', 'static-bridge'), 'fail', $response->get_error_message(), __('Verifica il routing strict e il funzionamento del server locale.', 'static-bridge'), 'settings', $url);
                }
                $status = wp_remote_retrieve_response_code($response);
                if (404 === $status) {
                    return $this->diagnostic_result($id, __('Modalità strict: pagina inesistente', 'static-bridge'), 'pass', __('Una URL non pubblicata restituisce HTTP 404 come previsto.', 'static-bridge'), '', '', $url);
                }
                return $this->diagnostic_result($id, __('Modalità strict: pagina inesistente', 'static-bridge'), 'fail', sprintf(/* translators: %s: HTTP status code */ __('La URL non pubblicata restituisce HTTP %s invece di 404.', 'static-bridge'), $status), __('Controlla il marcatore .strict e le regole Apache; oppure disattiva strict se vuoi il fallback WordPress.', 'static-bridge'), 'settings', $url);

            case 'skip-strict':
                return $this->diagnostic_result($id, __('Modalità strict: pagina inesistente', 'static-bridge'), 'skip', __('Controllo non applicabile: modalità strict disattivata.', 'static-bridge'));
        }
        return $this->diagnostic_result($id, __('Controllo diagnostico', 'static-bridge'), 'skip', __('Controllo sconosciuto ignorato.', 'static-bridge'));
    }

    private function diagnostic_http_step($id, $label, $url, $expected)
    {
        $response = $this->remote_get($url, 15);
        if (is_wp_error($response)) {
            return $this->diagnostic_result($id, $label, 'fail', $response->get_error_message(), __('Verifica che WordPress gestisca questo endpoint e che le regole statiche lo escludano.', 'static-bridge'), 'settings', $url);
        }
        $status = wp_remote_retrieve_response_code($response);
        $body = wp_remote_retrieve_body($response);
        $content_type = strtolower((string) wp_remote_retrieve_header($response, 'content-type'));
        $valid = $status >= 200 && $status < 400;
        if ($this->diagnostic_served_static($response)) {
            $valid = false;
        }
        if ('json' === $expected) {
            $valid = $valid && false !== strpos($content_type, 'application/json') && null !== json_decode($body, true);
        } elseif ('feed' === $expected) {
            $valid = $valid && (false !== strpos($body, '<rss') || false !== strpos($body, '<feed') || false !== strpos($body, '<rdf:rdf'));
        } elseif ('login' === $expected || 'html' === $expected) {
            $valid = $valid && ('' === $content_type || false !== strpos($content_type, 'text/html'));
        }
        if (!$valid) {
            $status_name = 'feed' === $expected ? 'warning' : 'fail';
            $remediation = 'feed' === $expected
                ? __('Il feed può essere disabilitato intenzionalmente. Se serve, riattiva i feed o verifica il plugin SEO.', 'static-bridge')
                : __('Controlla le regole di esclusione e la risposta dell’endpoint WordPress.', 'static-bridge');
            return $this->diagnostic_result($id, $label, $status_name, sprintf(/* translators: 1: HTTP status code, 2: Content-Type */ __('Risposta non valida: HTTP %1$s, Content-Type %2$s.', 'static-bridge'), $status, '' !== $content_type ? $content_type : __('non indicato', 'static-bridge')), $remediation, 'settings', $url);
        }
        return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: %s: HTTP status code */ __('Endpoint dinamico raggiungibile: HTTP %s.', 'static-bridge'), $status), '', '', $url);
    }

    /**
     * 2.5.0: the home through WP (the render with the bypass, as for the copy) as a computer and as a phone
     * (DIAGNOSTIC_MOBILE_USER_AGENT). The copy is one, rendered as a computer: if WP gives a phone another HTML, the
     * theme or a plugin decides in PHP (wp_is_mobile()) and phones will get the computer's version. Compared after
     * diagnostic_comparable_html(); when they differ, a second render as a computer tells a page that changes at
     * every request from one that changes with the device. Never a «fail»: a «warning» at most.
     */
    private function diagnostic_mobile_html_step($id)
    {
        $label = __('Home da computer e da telefono', 'static-bridge');
        $url = home_url('/');
        if ($this->job_is_running()) {
            return $this->diagnostic_result($id, $label, 'skip', __('Confronto saltato mentre è in corso un export, per non rallentarlo: ripeti la Diagnostica alla fine.', 'static-bridge'), '', '', $url);
        }
        $renders = array();
        foreach (array('computer' => '', 'phone' => self::DIAGNOSTIC_MOBILE_USER_AGENT, 'computer-again' => '') as $key => $user_agent) {
            if ('computer-again' === $key && $renders['computer'] === $renders['phone']) {
                break;
            }
            $page = $this->fetch_page($url, 10, $user_agent);
            if (is_wp_error($page)) {
                return $this->diagnostic_result($id, $label, 'skip', sprintf(/* translators: %s: error message */ __('Non è stato possibile chiedere la home a WP: %s', 'static-bridge'), $page->get_error_message()), '', '', $url);
            }
            $nonces = isset($page['render_facts']['nonces']) && is_array($page['render_facts']['nonces']) ? $page['render_facts']['nonces'] : array();
            $renders[$key] = $this->diagnostic_comparable_html($page['body'], $nonces);
        }
        if ($renders['computer'] === $renders['phone'] || (isset($renders['computer-again']) && $renders['computer-again'] === $renders['phone'])) {
            return $this->diagnostic_result($id, $label, 'pass', __('WP dà la stessa home a un computer e a un telefono: la copia statica, che è una sola, va bene per tutti e due.', 'static-bridge'), '', '', $url);
        }
        if ($renders['computer'] !== $renders['computer-again']) {
            return $this->diagnostic_result($id, $label, 'skip', __('La home cambia a ogni richiesta anche da computer, quindi il confronto con il telefono non dice niente.', 'static-bridge'), '', '', $url);
        }
        return $this->diagnostic_result(
            $id,
            $label,
            'warning',
            sprintf(
                /* translators: 1: size in bytes of the home for a phone, 2: size in bytes of the home for a computer */
                __('WP dà a un telefono una home diversa da quella di un computer (%1$s byte al telefono, %2$s al computer, tolte le parti che cambiano a ogni richiesta): il tema o un plugin sceglie l’HTML in PHP, per esempio con wp_is_mobile(). La copia statica è una sola e si genera come da computer, quindi i telefoni riceveranno la versione da computer.', 'static-bridge'),
                number_format_i18n(strlen($renders['phone'])),
                number_format_i18n(strlen($renders['computer']))
            ),
            __('Se la versione per i telefoni serve, spegni nel tema o nel plugin l’opzione che la produce (un tema responsive si adatta con il CSS) oppure escludi dalla copia le pagine che ne hanno bisogno. Se la differenza non conta, ignora questo avviso.', 'static-bridge'),
            '',
            $url
        );
    }

    /**
     * 2.5.0: the HTML of a render without what changes at every request, for a comparison: comments (timings,
     * cache notes), the nonces of the render (render_facts), nonce attributes and values of a key that names a
     * nonce, Unix timestamps and clock times. Only for comparing: the copy is never written from this.
     */
    private function diagnostic_comparable_html($html, $nonces = array())
    {
        $html = (string) $html;
        foreach ((array) $nonces as $value) {
            if (is_string($value) && preg_match('/\A[a-f0-9]{8,32}\z/', $value)) {
                $html = str_replace($value, 'NONCE', $html);
            }
        }
        $patterns = array(
            '~<!--.*?-->~s' => '',
            '~\bnonce\s*=\s*(["\'])[^"\']*\1~i' => 'nonce=""',
            '~(nonce["\']?\s*[:=]\s*["\']?)[A-Za-z0-9+/=_-]{6,128}~i' => '$1NONCE',
            '~\b1[0-9]{9}(?:[0-9]{3})?(?:\.[0-9]+)?\b~' => 'TIME',
            '~\b[0-9]{1,2}:[0-9]{2}(?::[0-9]{2})?\b~' => 'TIME',
        );
        foreach ($patterns as $pattern => $replacement) {
            $replaced = preg_replace($pattern, $replacement, $html);
            if (is_string($replaced)) {
                $html = $replaced;
            }
        }
        return $html;
    }

    /**
     * 2.5.0: a query of two tracking parameters for the Diagnostica (utm_source and the next name, a prefix
     * completed with «source»), '' with «Ignora i parametri di tracciamento» off.
     */
    private function diagnostic_tracking_query()
    {
        $pairs = array();
        foreach (array_slice($this->tracking_param_names(), 0, 2) as $name) {
            $pairs[] = ('*' === substr($name, -1) ? substr($name, 0, -1) . 'source' : $name) . '=static-bridge-diagnostic';
        }
        return implode('&', $pairs);
    }

    /**
     * 2.5.0: with «Ignora i parametri di tracciamento» the home with two tracking parameters is the copy: on Nginx
     * with X-Static-Bridge-Route, everywhere with the body of the file. A home excluded or without a copy: skip.
     * The opposite (a tracking parameter next to another one reaches WP) is the step query-bypass.
     */
    private function diagnostic_tracking_query_step($id, $run)
    {
        $label = __('Parametri di tracciamento', 'static-bridge');
        $query = $this->diagnostic_tracking_query();
        $url = home_url('/') . '?' . $query;
        $release = $this->current_release();
        $file = $release && !empty($run['release']) ? trailingslashit($this->static_root()) . 'releases/' . sanitize_file_name($run['release']) . '/index.html' : '';
        if ('' === $query || '' === $file || !is_readable($file) || in_array('/', $this->routing_excluded_paths(), true)) {
            return $this->diagnostic_result($id, $label, 'skip', __('La home non ha una copia statica servibile: il controllo dei parametri di tracciamento usa la home.', 'static-bridge'), '', '', $url);
        }
        $response = $this->remote_get($url, 15);
        if (is_wp_error($response)) {
            return $this->diagnostic_result($id, $label, 'fail', $response->get_error_message(), __('Verifica che il dominio sia raggiungibile dal processo PHP e ripeti la diagnostica.', 'static-bridge'), '', $url);
        }
        $remedy = $this->server_uses_nginx()
            ? __('Copia il blocco Nginx aggiornato da Impostazioni e ricarica Nginx.', 'static-bridge')
            : __('Salva di nuovo le Impostazioni e controlla il passo «Regole del server web».', 'static-bridge');
        $summary = __('La home con soli parametri di tracciamento non è stata servita dalla copia statica: quelle visite vanno a WP.', 'static-bridge');
        if ($this->server_uses_nginx() && 'static' !== strtolower((string) wp_remote_retrieve_header($response, 'x-static-bridge-route'))) {
            return $this->diagnostic_result($id, $label, 'warning', $summary, $remedy, 'settings', $url);
        }
        $parity = $this->diagnostic_static_route_parity_result($id, $label, $url, $file, $release, $response);
        if ('pass' !== $parity['status']) {
            return $this->diagnostic_result($id, $label, 'warning', $summary . ' ' . $parity['summary'], $remedy, 'settings', $url);
        }
        return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: %s: query string */ __('La home con %s risponde con il file della copia statica.', 'static-bridge'), '?' . $query), '', '', $url);
    }

    /**
     * 2.5.0: «Cookie che mandano a WP». Warns about a name that probably every visitor has, by one of two simple
     * criteria: WP sets it on the home of an anonymous visitor (Set-Cookie of a request without cookies, through
     * WP with ?static_bridge_bypass=1), or it is in COMMON_VISITOR_COOKIES (statistics, consent banners, language,
     * PHP session). A cookie set by a script in the browser is seen only by the second. On Nginx the home with the
     * first cookie must reach WP: the block is copied by hand.
     */
    private function diagnostic_dynamic_cookies_step($id)
    {
        $label = __('Cookie che mandano a WP', 'static-bridge');
        $names = $this->dynamic_cookie_names();
        if (empty($names)) {
            return $this->diagnostic_result($id, $label, 'skip', __('Nessun cookie configurato.', 'static-bridge'));
        }
        // 2.5.0: on Apache too, where the rules send X-Static-Bridge-Route with mod_headers (without it, no marker).
        if ($this->current_release()) {
            $probe = '*' === substr($names[0], -1) ? substr($names[0], 0, -1) . 'static_bridge_diagnostic' : $names[0];
            $response = $this->remote_get(home_url('/'), 15, self::MAX_HTTP_RESPONSE_SIZE, false, array('headers' => array('Cookie' => $probe . '=1')));
            if (!is_wp_error($response) && $this->diagnostic_served_static($response)) {
                return $this->server_uses_nginx()
                    ? $this->diagnostic_result($id, $label, 'fail',
                        sprintf(/* translators: %s: cookie name */ __('Nginx ha servito la copia statica a una richiesta con il cookie %s, che dovrebbe mandarla a WP.', 'static-bridge'), $probe),
                        __('Copia il blocco Nginx aggiornato da Impostazioni e ricarica Nginx.', 'static-bridge'), 'settings')
                    : $this->diagnostic_apache_served_static($id, $label, home_url('/'));
            }
        }
        $common = array();
        foreach ($names as $name) {
            foreach (self::COMMON_VISITOR_COOKIES as $common_name) {
                if ($this->cookie_names_overlap($name, $common_name)) {
                    $common[$name] = $name;
                    break;
                }
            }
        }
        $set_by_wp = array();
        $response = $this->remote_get(home_url('/') . '?static_bridge_bypass=1', 15, 262144);
        if (!is_wp_error($response)) {
            $headers = wp_remote_retrieve_header($response, 'set-cookie');
            foreach (is_array($headers) ? $headers : preg_split('/\r\n|\r|\n/', (string) $headers) as $header) {
                $cookie = trim((string) strtok((string) $header, '='));
                foreach ($names as $name) {
                    if ('' !== $cookie && false !== strpos((string) $header, '=') && $this->cookie_names_overlap($name, $cookie)) {
                        $set_by_wp[$name] = $name;
                    }
                }
            }
        }
        if (empty($common) && empty($set_by_wp)) {
            return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: %s: list of cookie names */ __('Vanno a WP i visitatori con: %s. Nessuno di questi sembra un cookie che hanno tutti.', 'static-bridge'), implode(', ', $names)));
        }
        $parts = array();
        if (!empty($set_by_wp)) {
            $parts[] = sprintf(/* translators: %s: list of cookie names */ __('WP li dà a ogni visitatore della home: %s.', 'static-bridge'), implode(', ', $set_by_wp));
        }
        if (!empty($common)) {
            $parts[] = sprintf(/* translators: %s: list of cookie names */ __('Di solito li hanno quasi tutti i visitatori (statistiche, banner dei cookie, lingua, sessione): %s.', 'static-bridge'), implode(', ', $common));
        }
        return $this->diagnostic_result($id, $label, 'warning',
            __('Alcuni cookie che mandano a WP sono probabilmente di tutti: la copia statica non servirebbe quasi a nessuno.', 'static-bridge') . ' ' . implode(' ', $parts),
            __('Togli quei nomi dal campo «Cookie che mandano a WP» nelle Impostazioni, salvo che tu voglia davvero mandare a WP chi li ha.', 'static-bridge'), 'settings');
    }

    /**
     * 2.5.0 (D5): on Nginx the block is copied by hand, and an option turned on or off afterwards, or redirects that
     * changed (imported from another plugin or given with static_bridge_redirects), leave the server with the rules of
     * before while every other step passes. A page served as the copy carries X-Static-Bridge-Rules, the fingerprints
     * of the block it came from (nginx_router_block()): compared with the block these settings make now. Nothing is
     * read outside the site: one request to a page of the copy, as the step «Regole del server web» makes.
     */
    private function diagnostic_nginx_rules_step($id)
    {
        $label = __('Blocco Nginx in uso', 'static-bridge');
        $remedy = __('Copia di nuovo il blocco Nginx da Impostazioni al posto di quello che c’è sul server, ricarica Nginx e ripeti la Diagnostica.', 'static-bridge');
        $release = $this->current_release();
        $response = $release ? $this->nginx_route_probe($release, true) : false;
        if (!is_array($response)) {
            return $this->diagnostic_result($id, $label, 'skip', __('Nginx non serve ancora la copia statica: questo controllo si fa quando passa il passo «Regole del server web».', 'static-bridge'));
        }
        $served = wp_remote_retrieve_header($response, 'x-static-bridge-rules');
        $served = strtolower(trim((string) (is_array($served) ? end($served) : $served)));
        if ('' === $served) {
            return $this->diagnostic_result($id, $label, 'warning', __('Nginx serve la copia con un blocco di una versione precedente di Static Bridge: non si può sapere se segue le Impostazioni di adesso.', 'static-bridge'), $remedy, 'settings');
        }
        $expected = $this->nginx_rules_fingerprint();
        if (hash_equals($expected, $served)) {
            return $this->diagnostic_result($id, $label, 'pass', __('Nginx usa il blocco che corrisponde alle Impostazioni di adesso, redirect compresi.', 'static-bridge'));
        }
        list($served_rules, $served_redirects) = array_pad(explode('-', $served, 2), 2, '');
        list($rules, $redirects) = array_pad(explode('-', $expected, 2), 2, '');
        $parts = array();
        if ($served_rules !== $rules) {
            $parts[] = __('Le Impostazioni sono cambiate dopo l’ultima copia del blocco Nginx, per esempio un’opzione accesa o spenta: il server segue ancora le regole di prima.', 'static-bridge');
        }
        if ($served_redirects !== $redirects) {
            if ('0' === $served_redirects) {
                $parts[] = __('Nel blocco Nginx in uso mancano i redirect di adesso, importati da un altro plugin o dati con il filtro static_bridge_redirects.', 'static-bridge');
            } elseif ('0' === $redirects) {
                $parts[] = __('Il blocco Nginx in uso fa ancora dei redirect che adesso non ci sono più.', 'static-bridge');
            } else {
                $parts[] = __('I redirect sono cambiati dopo l’ultima copia del blocco Nginx, per esempio quelli importati da un altro plugin: il server fa ancora quelli di prima.', 'static-bridge');
            }
        }
        return $this->diagnostic_result($id, $label, 'warning', implode(' ', $parts), $remedy, 'settings');
    }

    /** Two cookie names, each exact or a prefix with «*», that can name the same cookie, without regard to case. */
    private function cookie_names_overlap($left, $right)
    {
        $left_prefix = '*' === substr((string) $left, -1);
        $right_prefix = '*' === substr((string) $right, -1);
        $left = strtolower(rtrim((string) $left, '*'));
        $right = strtolower(rtrim((string) $right, '*'));
        if ('' === $left || '' === $right) {
            return false;
        }
        if (!$left_prefix && !$right_prefix) {
            return $left === $right;
        }
        return ($left_prefix && 0 === strpos($right, $left)) || ($right_prefix && 0 === strpos($left, $right));
    }

    /**
     * 2.5.0: the Basic Auth of the web server. The home without credentials, then, when the constants are valid,
     * with them: both through remote_get() (same site, no redirect, the public path). The results name the
     * constants, never a value.
     */
    private function diagnostic_basic_auth_step($id)
    {
        $label = __('Basic Auth del web server', 'static-bridge');
        $home = home_url('/');
        $state = $this->basic_auth_state();
        $without = $this->remote_get($home, 15, 65536, false, array('basic_auth' => false));
        if (is_wp_error($without)) {
            return $this->diagnostic_result($id, $label, 'warning', sprintf(/* translators: %s: error message */ __('La home non ha risposto alla richiesta senza credenziali: %s', 'static-bridge'), $without->get_error_message()), __('Controlla il passo «Rendering HTTP dal processo PHP»: il processo PHP deve raggiungere il sito.', 'static-bridge'), '', $home);
        }
        $status = (int) wp_remote_retrieve_response_code($without);
        $asks = 401 === $status;
        $constants = __('Le costanti si chiamano STATIC_BRIDGE_BASIC_AUTH_USER e STATIC_BRIDGE_BASIC_AUTH_PASSWORD.', 'static-bridge');
        if ('invalid' === $state) {
            return $this->diagnostic_result(
                $id,
                $label,
                $asks ? 'fail' : 'warning',
                __('Le costanti di Basic Auth in wp-config.php non sono valide: Static Bridge non manda credenziali.', 'static-bridge')
                    . ($asks ? ' ' . __('Il sito risponde HTTP 401 senza credenziali: rendering, export e Diagnostica non lo raggiungono.', 'static-bridge') : ''),
                __('Definisci in wp-config.php tutte e due le costanti come testo: un nome utente non vuoto, senza «:» e senza caratteri di controllo, e una password senza caratteri di controllo (a capo, tabulazioni, NUL).', 'static-bridge') . ' ' . $constants,
                '',
                $home
            );
        }
        if ('off' === $state) {
            if ($asks) {
                return $this->diagnostic_result(
                    $id,
                    $label,
                    'fail',
                    __('La home risponde HTTP 401 senza credenziali: il web server chiede Basic Auth, e il plugin non può renderizzare le pagine né far proseguire l’export a scheda chiusa.', 'static-bridge'),
                    __('Aggiungi a wp-config.php il nome utente e la password di Basic Auth: Static Bridge li manda solo nelle richieste al sito stesso.', 'static-bridge') . ' ' . $constants,
                    '',
                    $home
                );
            }
            return $this->diagnostic_result($id, $label, 'skip', sprintf(/* translators: %s: HTTP status code */ __('Il sito non chiede Basic Auth (HTTP %s senza credenziali): nessuna credenziale serve.', 'static-bridge'), $status), '', '', $home);
        }
        if (!$asks) {
            return $this->diagnostic_result(
                $id,
                $label,
                'warning',
                sprintf(/* translators: %s: HTTP status code */ __('Le costanti di Basic Auth sono definite, ma il sito non chiede Basic Auth (HTTP %s senza credenziali): non servono.', 'static-bridge'), $status),
                __('Se la protezione del web server è stata tolta, puoi togliere le due costanti da wp-config.php.', 'static-bridge'),
                '',
                $home
            );
        }
        $with = $this->remote_get($home, 15, 65536);
        if (is_wp_error($with)) {
            return $this->diagnostic_result($id, $label, 'fail', sprintf(/* translators: %s: error message */ __('La home non ha risposto alla richiesta con le credenziali: %s', 'static-bridge'), $with->get_error_message()), '', '', $home);
        }
        $status = (int) wp_remote_retrieve_response_code($with);
        if (401 === $status) {
            return $this->diagnostic_result(
                $id,
                $label,
                'fail',
                __('Il sito risponde HTTP 401 anche con le credenziali di wp-config.php: nome utente o password sbagliati.', 'static-bridge'),
                __('Correggi in wp-config.php le costanti con il nome utente e la password del web server.', 'static-bridge') . ' ' . $constants,
                '',
                $home
            );
        }
        if ($status >= 200 && $status < 400) {
            return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: %s: HTTP status code */ __('Basic Auth attiva: senza credenziali il sito risponde HTTP 401, con le credenziali di wp-config.php HTTP %s.', 'static-bridge'), $status), '', '', $home);
        }
        return $this->diagnostic_result(
            $id,
            $label,
            'fail',
            sprintf(/* translators: %s: HTTP status code */ __('Con le credenziali di wp-config.php il sito risponde HTTP %s.', 'static-bridge'), $status),
            __('Il web server accetta la richiesta ma la home non risponde come dovrebbe: guarda il log degli errori del server.', 'static-bridge'),
            '',
            $home
        );
    }

    private function diagnostic_render_origin_step($id)
    {
        $home = $this->fetch_page(home_url('/'));
        if (is_wp_error($home)) {
            return $this->diagnostic_result(
                $id,
                __('Rendering HTTP dal processo PHP', 'static-bridge'),
                'fail',
                sprintf(/* translators: %s: error message */ __('Il processo PHP non riesce a renderizzare la home tramite HTTP: %s', 'static-bridge'), $home->get_error_message()),
                __('Verifica che PHP-FPM possa raggiungere il dominio WordPress tramite DNS/hosts e TLS; controlla redirect, firewall, proxy, cache e plugin di sicurezza. Non avviare un export massivo finché questo test non passa.', 'static-bridge'),
                'settings',
                home_url('/')
            );
        }
        return $this->diagnostic_result(
            $id,
            __('Rendering HTTP dal processo PHP', 'static-bridge'),
            'pass',
            sprintf(/* translators: %s: response size in bytes */ __('Home renderizzata dal processo PHP (%s byte); il recupero HTML necessario all’export è raggiungibile.', 'static-bridge'), number_format_i18n(strlen($home['body'])))
                . ('' !== $this->settings()['render_origin'] ? ' ' . sprintf(/* translators: %s: IP address, with optional port */ __('Connessione diretta all’indirizzo di origine %s.', 'static-bridge'), $this->settings()['render_origin']) : ''),
            '',
            '',
            home_url('/')
        );
    }

    private function diagnostic_retryable_export_url()
    {
        $job = get_option(self::JOB_OPTION, array());
        if (!is_array($job)
            || !isset($job['status'], $job['issues'])
            || !in_array($job['status'], array('failed', 'paused'), true)
            || !is_array($job['issues'])) {
            return '';
        }

        for ($index = count($job['issues']) - 1; $index >= 0; $index--) {
            $issue = $job['issues'][$index];
            if (!is_array($issue) || empty($issue['url']) || !is_string($issue['url'])) {
                continue;
            }
            $message = isset($issue['message']) && is_string($issue['message']) ? $issue['message'] : '';
            $is_transient = !empty($issue['retryable_transient'])
                || (bool) preg_match('/(?:\bcurl error (?:6|7|28)\b|\b(?:operation )?timed out\b|\bconnection (?:refused|reset)\b|\bHTTP (?:408|425|429|5[0-9]{2})\b)/i', $message);
            if (!$is_transient) {
                continue;
            }

            $url = $this->normalize_public_url($issue['url']);
            if ('' !== $url) {
                return $url;
            }
        }
        return '';
    }

    private function diagnostic_failed_export_url_step($id, $url)
    {
        $label = __('URL dell’ultimo errore transitorio di export', 'static-bridge');
        $url = $this->normalize_public_url($url);
        if ('' === $url) {
            return $this->diagnostic_result(
                $id,
                $label,
                'fail',
                __('La URL salvata non è più una rotta pubblica same-origin; nessuna richiesta è stata inviata.', 'static-bridge'),
                __('Controlla il registro dell’export e non inserire URL esterne come target di diagnostica.', 'static-bridge'),
                'settings'
            );
        }

        $result = $this->fetch_page($url);
        if (is_wp_error($result)) {
            $status = 'fail';
            $summary = sprintf(/* translators: %s: error message */ __('Il test HTTP mirato non è riuscito: %s', 'static-bridge'), $result->get_error_message());
            $remediation = __('Confronta questa singola richiesta con i log PHP, Nginx e del firewall applicativo. La release non è stata modificata.', 'static-bridge');
            if ('static_bridge_http' === $result->get_error_code()) {
                $http_status = $result->get_error_data();
                if (is_numeric($http_status) && in_array((int) $http_status, array(401, 403, 404, 410), true)) {
                    $status = 'warning';
                    $summary = sprintf(/* translators: %s: HTTP status code */ __('La URL ora risponde HTTP %s e, come nell’export, viene esclusa; il timeout precedente non è stato riprodotto.', 'static-bridge'), (int) $http_status);
                    $remediation = __('Verifica se il contenuto è ancora pubblico e se WAF o regole del server stanno filtrando questa rotta.', 'static-bridge');
                }
            } elseif ('static_bridge_redirect' === $result->get_error_code()) {
                $status = 'warning';
                $summary = sprintf(/* translators: %s: error message with the redirect destination */ __('La URL ora reindirizza: %s. La destinazione non è stata seguita durante il test.', 'static-bridge'), $result->get_error_message());
                $remediation = __('Controlla la destinazione canonica; l’export la accoderà solo se resta una rotta pubblica dello stesso sito.', 'static-bridge');
            }

            return $this->diagnostic_result($id, $label, $status, $summary, $remediation, 'settings', $url);
        }

        return $this->diagnostic_result(
            $id,
            $label,
            'pass',
            sprintf(/* translators: %s: response size in bytes */ __('Il loopback PHP ha ricevuto HTML valido (%s byte); il timeout precedente non è stato riprodotto. Il test non ha modificato la release.', 'static-bridge'), number_format_i18n(strlen($result['body']))),
            '',
            '',
            $url
        );
    }

    private function diagnostic_inventory_step($id)
    {
        $inventory = $this->discover_wordpress_post_url_batch(0);
        if (is_wp_error($inventory)) {
            return $this->diagnostic_result(
                $id,
                __('Inventario WordPress', 'static-bridge'),
                'fail',
                $inventory->get_error_message(),
                __('Verifica la connessione MySQL, la tabella dei contenuti e la query indicizzata. La sitemap SEO non sostituisce l’inventario WordPress e non è richiesta.', 'static-bridge'),
                'settings'
            );
        }
        return $this->diagnostic_result(
            $id,
            __('Inventario WordPress', 'static-bridge'),
            'pass',
            sprintf(/* translators: 1: number of URLs in the first batch, 2: batch size */ __('Query per chiave primaria riuscita: %1$s URL nel primo blocco (massimo %2$s). L’export continua a blocchi; la sitemap SEO non è necessaria.', 'static-bridge'), number_format_i18n(count($inventory['urls'])), number_format_i18n(self::WORDPRESS_DISCOVERY_PAGE_SIZE)),
            '',
            '',
            home_url('/')
        );
    }

    private function normalize_diagnostic_target_url($target)
    {
        if (!is_string($target) || '' === trim($target) || strlen($target) > 2048) {
            return '';
        }
        $target = trim($target);
        if (preg_match('~[\x00-\x20\x7f\\\\]~', $target)
            || false !== strpos($target, '?') || false !== strpos($target, '#')) {
            return '';
        }

        if ('/' === substr($target, 0, 1) && '//' !== substr($target, 0, 2)) {
            $url = home_url($target);
        } elseif (preg_match('~^https?://~i', $target)) {
            $url = $target;
        } else {
            return '';
        }

        return $this->normalize_public_url($url);
    }

    private function diagnostic_parity_body($html, $release)
    {
        if (!$this->release_uses_header_fragments($release)) {
            return array('body' => (string) $html, 'complete' => true);
        }

        $html = (string) $html;
        $directive_pattern = '~<!--\s*#include\s+virtual="/wp-content/static-bridge/current/fragments/headers/[A-Za-z0-9_-]{1,64}/current/elementor-[A-Za-z0-9_-]{1,64}-[a-f0-9]{64}\.html"\s+-->~';
        $html = preg_replace($directive_pattern, '', $html);
        if (!is_string($html)) {
            return array('body' => '', 'complete' => false);
        }

        if (!class_exists('Static_Bridge_Header_Fragments')) {
            return array('body' => $html, 'complete' => false);
        }
        $header = Static_Bridge_Header_Fragments::extract_unique_elementor_header($html);
        if (is_array($header) && isset($header['start'], $header['end'])
            && 0 <= (int) $header['start'] && (int) $header['end'] >= (int) $header['start']) {
            $html = substr($html, 0, (int) $header['start']) . substr($html, (int) $header['end']);
        } elseif (preg_match('/data-elementor-type\\s*=\\s*["\\\']header["\\\']/i', $html)) {
            return array('body' => $html, 'complete' => false);
        }

        return array('body' => $html, 'complete' => true);
    }

    private function diagnostic_image_inventory($html, $base_url)
    {
        $inventory = array('images' => array(), 'tags' => 0, 'references' => 0, 'unresolved' => 0, 'truncated' => false);
        $html = (string) $html;
        $offset = 0;
        $length = strlen($html);
        $limit = 2000;
        while ($offset < $length && preg_match('~<img\b[^>]*>~i', $html, $tag_match, PREG_OFFSET_CAPTURE, $offset)) {
            if ($inventory['tags'] >= $limit) {
                $inventory['truncated'] = true;
                break;
            }
            $tag = $tag_match[0][0];
            $offset = $tag_match[0][1] + strlen($tag);
            $inventory['tags']++;

            $attributes = array();
            if (preg_match_all('~([a-zA-Z_:][a-zA-Z0-9_.:-]*)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s>]+))~is', $tag, $attribute_matches, PREG_SET_ORDER)) {
                foreach ($attribute_matches as $attribute) {
                    $value = isset($attribute[2]) && '' !== $attribute[2]
                        ? $attribute[2]
                        : (isset($attribute[3]) && '' !== $attribute[3] ? $attribute[3] : (isset($attribute[4]) ? $attribute[4] : ''));
                    $attributes[strtolower($attribute[1])] = html_entity_decode($value, ENT_QUOTES | ENT_HTML5, 'UTF-8');
                }
            }

            $source = '';
            foreach (array('data-lazy-src', 'data-src', 'data-original', 'src') as $attribute_name) {
                if (empty($attributes[$attribute_name])) {
                    continue;
                }
                $candidate = trim($attributes[$attribute_name]);
                if (preg_match('~^(?:data|blob|javascript):~i', $candidate)) {
                    continue;
                }
                $source = $candidate;
                break;
            }
            if ('' === $source) {
                foreach (array('data-srcset', 'srcset') as $attribute_name) {
                    if (empty($attributes[$attribute_name])) {
                        continue;
                    }
                    $candidates = explode(',', $attributes[$attribute_name]);
                    $first = trim(isset($candidates[0]) ? $candidates[0] : '');
                    $source = '' !== $first ? preg_replace('/\\s+[^\\s]+$/', '', $first) : '';
                    if ('' !== $source && !preg_match('~^(?:data|blob|javascript):~i', $source)) {
                        break;
                    }
                    $source = '';
                }
            }
            if ('' === $source) {
                $inventory['unresolved']++;
                continue;
            }

            if (0 === strpos($source, '//')) {
                $base_scheme = wp_parse_url($base_url, PHP_URL_SCHEME);
                $absolute = ($base_scheme ? $base_scheme : (is_ssl() ? 'https' : 'http')) . ':' . $source;
            } else {
                $absolute = $this->absolute_url($source, $base_url);
            }
            $parts = wp_parse_url($absolute);
            if (!is_array($parts) || empty($parts['host']) || !isset($parts['scheme'])
                || !in_array(strtolower($parts['scheme']), array('http', 'https'), true)
                || isset($parts['user']) || isset($parts['pass'])) {
                $inventory['unresolved']++;
                continue;
            }
            $host = strtolower(rtrim($parts['host'], '.'));
            $scheme = strtolower($parts['scheme']);
            $raw_port = isset($parts['port']) ? (int) $parts['port'] : 0;
            $port = $raw_port && !(('https' === $scheme && 443 === $raw_port) || ('http' === $scheme && 80 === $raw_port))
                ? ':' . $raw_port
                : '';
            $path = isset($parts['path']) && '' !== $parts['path'] ? rawurldecode($parts['path']) : '/';
            if (false !== strpos($path, "\0") || false !== strpos($path, "\n") || false !== strpos($path, "\r")) {
                $inventory['unresolved']++;
                continue;
            }
            $key = '//' . $host . $port . $path;
            $inventory['images'][$key] = isset($inventory['images'][$key]) ? $inventory['images'][$key] + 1 : 1;
            $inventory['references']++;
        }

        return $inventory;
    }

    private function diagnostic_static_parity_step($step, $run)
    {
        $id = isset($step['id']) ? $step['id'] : 'static-parity-target';
        $label = isset($step['label']) ? $step['label'] : __('Confronto mirato delle immagini', 'static-bridge');
        $url = isset($step['url']) ? $this->normalize_diagnostic_target_url((string) $step['url']) : '';
        if ('' === $url) {
            return $this->diagnostic_result($id, $label, 'fail', __('Il percorso del confronto mirato non è valido.', 'static-bridge'), __('Inserisci una route pubblica dello stesso dominio, senza query o frammento.', 'static-bridge'), 'settings');
        }
        if ($this->job_is_running()) {
            return $this->diagnostic_result($id, $label, 'skip', __('Confronto rinviato: è in corso un export completo. Nessun file o marker è stato toccato.', 'static-bridge'), __('Attendi la fine dell’export e avvia una nuova diagnostica.', 'static-bridge'), '', $url);
        }

        $release = $this->current_release();
        $expected_release = isset($run['release']) ? (string) $run['release'] : '';
        if (!$release || '' === $expected_release || basename($release) !== $expected_release) {
            return $this->diagnostic_result($id, $label, 'warning', __('La release attiva è assente o è cambiata dall’avvio della diagnostica; confronto non eseguito.', 'static-bridge'), __('Avvia una nuova verifica quando non sono in corso pubblicazioni.', 'static-bridge'), 'generate', $url);
        }

        $relative = $this->relative_html_path($url);
        if (is_wp_error($relative)) {
            return $this->diagnostic_result($id, $label, 'fail', $relative->get_error_message(), __('Controlla il percorso indicato.', 'static-bridge'), 'settings', $url);
        }
        $file = trailingslashit($release) . $relative;
        $release_prefix = trailingslashit($release);
        $real_file = realpath($file);
        if (is_link($file) || !$real_file || 0 !== strpos($real_file, $release_prefix) || !is_file($real_file) || !is_readable($real_file)) {
            return $this->diagnostic_result($id, $label, 'fail', __('La route indicata non ha un file HTML regolare e leggibile nella release attiva.', 'static-bridge'), __('Verifica che la pagina sia inclusa nella release corrente; se manca, rigenera o aggiorna la sola pagina.', 'static-bridge'), 'generate', $url);
        }
        $file_size = filesize($real_file);
        if (false === $file_size || $file_size > self::MAX_HTML_PAGE_SIZE) {
            return $this->diagnostic_result($id, $label, 'fail', __('Il file HTML della route supera il limite di lettura sicura.', 'static-bridge'), __('Controlla la dimensione della pagina e ripeti la verifica.', 'static-bridge'), 'generate', $url);
        }
        $static_html = @file_get_contents($real_file);
        if (!is_string($static_html)) {
            return $this->diagnostic_result($id, $label, 'fail', __('Non è stato possibile leggere il file HTML della release.', 'static-bridge'), __('Controlla i permessi della release attiva.', 'static-bridge'), 'generate', $url);
        }

        $public_response = $this->remote_get($url, 15, self::MAX_HTML_PAGE_SIZE);
        if (is_wp_error($public_response)) {
            return $this->diagnostic_result($id, $label, 'fail', $public_response->get_error_message(), __('Verifica TLS, DNS e raggiungibilità della route dal processo PHP.', 'static-bridge'), 'settings', $url);
        }
        $public_status = wp_remote_retrieve_response_code($public_response);
        $public_type = (string) wp_remote_retrieve_header($public_response, 'content-type');
        if (404 === $public_status || ($public_status >= 300 && $public_status < 400)) {
            $location = (string) wp_remote_retrieve_header($public_response, 'location');
            $detail = sprintf(/* translators: 1: HTTP status code, 2: redirect location in parentheses or empty */ __('Confronto non eseguito: la route pubblica risponde HTTP %1$s%2$s. Questo avviso diagnostico non interrompe né modifica un export.', 'static-bridge'), $public_status, '' !== $location ? ' (' . $location . ')' : '');
            return $this->diagnostic_result($id, $label, 'warning', $detail, __('Verifica che il percorso sia quello canonico e raggiungibile, poi ripeti il confronto.', 'static-bridge'), '', $url);
        }
        if (200 !== $public_status || ('' !== $public_type && false === stripos($public_type, 'text/html'))) {
            return $this->diagnostic_result($id, $label, 'fail', sprintf(/* translators: 1: HTTP status code, 2: Content-Type */ __('La risposta pubblica non è HTML confrontabile: HTTP %1$s, Content-Type %2$s.', 'static-bridge'), $public_status, '' !== $public_type ? $public_type : __('non indicato', 'static-bridge')), __('Controlla URL, routing e cache del server.', 'static-bridge'), 'settings', $url);
        }

        $fresh = $this->fetch_page($url, 15);
        if (is_wp_error($fresh)) {
            $error_code = $fresh->get_error_code();
            $error_data = $fresh->get_error_data();
            $is_missing_or_redirect = in_array($error_code, array('static_bridge_http', 'static_bridge_redirect'), true)
                && (404 === (int) $error_data || 'static_bridge_redirect' === $error_code);
            return $this->diagnostic_result(
                $id,
                $label,
                $is_missing_or_redirect ? 'warning' : 'fail',
                sprintf(/* translators: %s: error message */ __('Il rendering WordPress fresco non è stato verificato: %s', 'static-bridge'), $fresh->get_error_message()),
                __('Verifica che la route esista e che il server confermi X-Static-Bridge-Render; il file statico non è stato sostituito.', 'static-bridge'),
                'settings',
                $url
            );
        }
        $current_after_fetch = $this->current_release();
        if (!$current_after_fetch || $current_after_fetch !== $release) {
            return $this->diagnostic_result($id, $label, 'warning', __('La release è cambiata durante il confronto; risultati scartati per evitare di confrontare versioni diverse.', 'static-bridge'), __('Attendi la fine della pubblicazione e ripeti la diagnostica.', 'static-bridge'), 'generate', $url);
        }

        $public_html = wp_remote_retrieve_body($public_response);
        $ssi_unexpanded = $this->release_uses_header_fragments($release)
            && class_exists('Static_Bridge_Header_Fragments')
            && Static_Bridge_Header_Fragments::contains_ssi_directive($public_html);
        $static_comparable = $this->diagnostic_parity_body($static_html, $release);
        $public_comparable = $this->diagnostic_parity_body($public_html, $release);
        $fresh_comparable = $this->diagnostic_parity_body($fresh['body'], $release);
        $inventories = array(
            'release' => $this->diagnostic_image_inventory($static_comparable['body'], $url),
            'public' => $this->diagnostic_image_inventory($public_comparable['body'], $url),
            'wordpress' => $this->diagnostic_image_inventory($fresh_comparable['body'], $url),
        );
        $keys = array_unique(array_merge(
            array_keys($inventories['release']['images']),
            array_keys($inventories['public']['images']),
            array_keys($inventories['wordpress']['images'])
        ));
        sort($keys, SORT_STRING);
        $differences = array();
        foreach ($keys as $key) {
            $counts = array(
                'release' => isset($inventories['release']['images'][$key]) ? (int) $inventories['release']['images'][$key] : 0,
                'public' => isset($inventories['public']['images'][$key]) ? (int) $inventories['public']['images'][$key] : 0,
                'wordpress' => isset($inventories['wordpress']['images'][$key]) ? (int) $inventories['wordpress']['images'][$key] : 0,
            );
            if (count(array_unique(array_values($counts))) > 1) {
                $differences[] = sprintf(
                    /* translators: 1: image URL, 2: count in the release files, 3: count in the public response, 4: count in WordPress */
                    __('%1$s (file %2$d, pubblico %3$d, WordPress %4$d)', 'static-bridge'),
                    $key, $counts['release'], $counts['public'], $counts['wordpress']);
            }
        }

        $totals = array();
        foreach ($inventories as $name => $inventory) {
            $totals[$name] = (int) $inventory['references'];
        }
        $incomplete = !$static_comparable['complete'] || !$public_comparable['complete'] || !$fresh_comparable['complete'];
        foreach ($inventories as $inventory) {
            $incomplete = $incomplete || !empty($inventory['truncated']) || !empty($inventory['unresolved']);
        }
        $nginx_route_ok = !$this->server_uses_nginx()
            || 'static' === strtolower((string) wp_remote_retrieve_header($public_response, 'x-static-bridge-route'));
        $status = !empty($differences) || !$nginx_route_ok || $ssi_unexpanded ? 'fail' : ($incomplete ? 'warning' : 'pass');
        $summary = sprintf(
            /* translators: 1: images in the static file, 2: images in the public response, 3: images in the fresh WordPress rendering */ __('Fonti img riconosciute: file %1$d, pubblico %2$d, WordPress aggiornato %3$d.', 'static-bridge'),
            $totals['release'],
            $totals['public'],
            $totals['wordpress']
        );
        if (!empty($differences)) {
            $visible = array_slice($differences, 0, 4);
            $summary .= ' ' . sprintf(/* translators: %s: list of differences */ __('Differenze: %s.', 'static-bridge'), implode('; ', $visible));
            if (count($differences) > count($visible)) {
                $summary .= ' ' . sprintf(/* translators: %d: number of further differences */ __('Altre differenze: %d.', 'static-bridge'), count($differences) - count($visible));
            }
        } elseif ('pass' === $status) {
            $summary .= ' ' . __('I tre livelli contengono le stesse immagini, con la stessa frequenza.', 'static-bridge');
        }
        if (!$nginx_route_ok) {
            $summary .= ' ' . __('Nginx non ha confermato che la risposta pubblica provenga dalla route statica.', 'static-bridge');
        }
        if ($ssi_unexpanded) {
            $summary .= ' ' . __('La risposta pubblica contiene ancora una direttiva SSI: l’header condiviso non è stato elaborato dal server.', 'static-bridge');
        }
        if ($incomplete) {
            $summary .= ' ' . __('Inventario parziale: alcune immagini non hanno una sorgente HTML riconosciuta, il limite di 2.000 elementi è stato raggiunto o un header SSI non è stato isolato.', 'static-bridge');
        }

        $remediation = '';
        if (!empty($differences)) {
            $remediation = __('Se file e WordPress differiscono, la release della pagina è obsoleta: aggiorna la singola pagina o rigenera la route. Se differisce solo la risposta pubblica dal file, controlla cache/proxy e routing del server. Il confronto non pubblica né sostituisce alcun file.', 'static-bridge');
        } elseif (!$nginx_route_ok) {
            $remediation = __('Controlla che Nginx instradi la route alla release attiva e che l’header X-Static-Bridge-Route sia impostato solo per le risposte statiche.', 'static-bridge');
        } elseif ($ssi_unexpanded) {
            $remediation = __('Verifica la configurazione SSI del server e ripeti il controllo. La route statica e i contenuti WordPress non sono stati modificati.', 'static-bridge');
        } elseif ($incomplete) {
            $remediation = __('Il controllo non può certificare ogni immagine della pagina; verifica anche immagini inserite via CSS o JavaScript e ripeti il test dopo aver risolto eventuali avvisi SSI.', 'static-bridge');
        }

        return $this->diagnostic_result($id, $label, $status, $summary, $remediation, !empty($differences) ? 'generate' : 'settings', $url);
    }

    private function diagnostic_result($id, $label, $status, $summary, $remediation = '', $action = '', $url = '')
    {
        $allowed_statuses = array('pass', 'warning', 'fail', 'skip');
        if (!in_array($status, $allowed_statuses, true)) {
            $status = 'warning';
        }
        $allowed_actions = array('forms', 'settings', 'generate');
        return array(
            'id' => sanitize_key($id),
            'label' => wp_strip_all_tags($label),
            'status' => $status,
            'status_label' => $this->diagnostic_status_label($status),
            'summary' => wp_strip_all_tags($summary),
            'remediation' => wp_strip_all_tags($remediation),
            'action' => in_array($action, $allowed_actions, true) ? $action : '',
            'url' => esc_url_raw($url),
        );
    }

    private function diagnostic_status_label($status)
    {
        $labels = array(
            'running' => __('In corso', 'static-bridge'),
            'passed' => __('Regolare', 'static-bridge'),
            'warning' => __('Con avvisi', 'static-bridge'),
            'failed' => __('Problemi rilevati', 'static-bridge'),
            'pass' => __('Superato', 'static-bridge'),
            'fail' => __('Errore', 'static-bridge'),
            'skip' => __('Saltato', 'static-bridge'),
        );
        return isset($labels[$status]) ? $labels[$status] : __('Non disponibile', 'static-bridge');
    }

    private function diagnostic_summary($results)
    {
        $counts = array('passed' => 0, 'warning' => 0, 'failed' => 0, 'skipped' => 0);
        foreach ((array) $results as $result) {
            if (!isset($result['status'])) {
                continue;
            }
            if ('pass' === $result['status']) {
                $counts['passed']++;
            } elseif ('warning' === $result['status']) {
                $counts['warning']++;
            } elseif ('fail' === $result['status']) {
                $counts['failed']++;
            } else {
                $counts['skipped']++;
            }
        }
        $status = $counts['failed'] ? 'failed' : ($counts['warning'] ? 'warning' : 'passed');
        $counts['label'] = sprintf(
            /* translators: 1: passed, 2: warnings, 3: errors (each already counted, e.g. "1 errore"). */
            __('%1$s · %2$s · %3$s', 'static-bridge'),
            sprintf(/* translators: %s: number of passed checks */ _n('%s superato', '%s superati', (int) $counts['passed'], 'static-bridge'), number_format_i18n($counts['passed'])),
            sprintf(/* translators: %s: number of warnings */ _n('%s avviso', '%s avvisi', (int) $counts['warning'], 'static-bridge'), number_format_i18n($counts['warning'])),
            sprintf(/* translators: %s: number of errors */ _n('%s errore', '%s errori', (int) $counts['failed'], 'static-bridge'), number_format_i18n($counts['failed']))
        );
        $counts['status'] = $status;
        return $counts;
    }

    private function diagnostic_response($run)
    {
        $results = isset($run['results']) && is_array($run['results']) ? $run['results'] : array();
        $steps = isset($run['steps']) && is_array($run['steps']) ? $run['steps'] : array();
        $total = count($steps);
        $completed = count($results);
        $summary = isset($run['summary']) && is_array($run['summary']) ? $run['summary'] : $this->diagnostic_summary($results);
        $status = isset($run['status']) ? $run['status'] : 'idle';
        $next = isset($steps[$completed]) ? $steps[$completed] : array();
        return array(
            'id' => isset($run['id']) ? $run['id'] : '',
            'status' => $status,
            'total' => $total,
            'completed' => $completed,
            'progress' => $total ? (int) floor(($completed / $total) * 100) : 0,
            'current' => isset($next['label']) ? $next['label'] : (isset($next['path']) ? $next['path'] : ''),
            'results' => $results,
            'summary' => $summary,
        );
    }

    private function save_diagnostic_history($run)
    {
        $history = get_option(self::DIAGNOSTIC_HISTORY_OPTION, array());
        if (!is_array($history)) {
            $history = array();
        }
        array_unshift($history, array(
            'id' => isset($run['id']) ? $run['id'] : '',
            'status' => isset($run['status']) ? $run['status'] : 'warning',
            'time' => $this->format_site_datetime(isset($run['completed_at']) ? $run['completed_at'] : time()),
            'summary' => isset($run['summary']) ? $run['summary'] : array(),
        ));
        update_option(self::DIAGNOSTIC_HISTORY_OPTION, array_slice($history, 0, 20), false);
    }

    /** What needs attention comes first; each group keeps the order of the checks. */
    private function diagnostic_results_by_severity($results)
    {
        $rank = array('fail' => 0, 'warning' => 1);
        $severity = function ($result) use ($rank) {
            $status = is_array($result) && isset($result['status']) ? $result['status'] : 'warning';
            return in_array($status, array('pass', 'skip'), true) ? 2 : ($rank[$status] ?? 1);
        };
        $sorted = array_values($results);
        usort($sorted, function ($a, $b) use ($severity) {
            return $severity($a) <=> $severity($b);
        });
        return $sorted;
    }

    private function render_diagnostic_result($result)
    {
        if (!is_array($result)) {
            return;
        }
        $status = isset($result['status']) && in_array($result['status'], array('pass', 'warning', 'fail', 'skip'), true) ? $result['status'] : 'warning';
        $action = isset($result['action']) && in_array($result['action'], array('forms', 'settings', 'generate'), true) ? $result['action'] : '';
        $url = 'forms' === $action ? $this->tab_url('forms') : ('settings' === $action ? $this->tab_url('settings') : ('generate' === $action ? $this->tab_url('generate') : ''));
        ?>
        <article class="sb-diagnostic-result is-<?php echo esc_attr($status); ?>">
            <span aria-hidden="true" class="sb-diagnostic-icon dashicons <?php echo 'pass' === $status ? 'dashicons-yes-alt' : ('fail' === $status ? 'dashicons-dismiss' : ('warning' === $status ? 'dashicons-warning' : 'dashicons-minus')); ?>" aria-hidden="true"></span>
            <div class="sb-diagnostic-result-content">
                <div class="sb-diagnostic-result-heading"><strong><?php echo esc_html(isset($result['label']) ? $result['label'] : __('Controllo', 'static-bridge')); ?></strong><span class="sb-diagnostic-status"><?php echo esc_html(isset($result['status_label']) ? $result['status_label'] : $this->diagnostic_status_label($status)); ?></span></div>
                <p><?php echo esc_html(isset($result['summary']) ? $result['summary'] : ''); ?></p>
                <?php if (!empty($result['url'])) : ?><code class="sb-diagnostic-url"><?php echo esc_html($result['url']); ?></code><?php endif; ?>
                <?php if (!empty($result['remediation'])) : ?><p class="sb-diagnostic-remediation"><?php echo esc_html($result['remediation']); ?><?php if ($url) : ?> <a href="<?php echo esc_url($url); ?>"><?php echo 'forms' === $action ? esc_html__('Apri Moduli', 'static-bridge') : ('settings' === $action ? esc_html__('Apri Impostazioni', 'static-bridge') : esc_html__('Apri Genera', 'static-bridge')); ?> →</a><?php endif; ?></p><?php endif; ?>
            </div>
        </article>
        <?php
    }

    private function diagnostic_is_running()
    {
        $run = get_option(self::DIAGNOSTIC_OPTION, array());
        if (!is_array($run) || !isset($run['status'], $run['updated_at'], $run['steps'], $run['cursor'], $run['results'])) {
            return false;
        }
        if ('running' !== $run['status'] || !is_array($run['steps']) || empty($run['steps']) || !is_array($run['results']) || !is_numeric($run['cursor'])) {
            return false;
        }
        $cursor = (int) $run['cursor'];
        return 0 <= $cursor && $cursor <= count($run['steps']) && time() - (int) $run['updated_at'] < 3600;
    }

    private function verify_ajax_request()
    {
        if (!current_user_can('manage_options')) {
            wp_send_json_error(array('message' => __('Non hai i permessi necessari.', 'static-bridge')), 403);
        }
        check_ajax_referer(self::AJAX_NONCE, 'nonce');
    }

    /** The AJAX actions of the full export (start, tick, status, resume, cancel): the export capability, then the nonce. */
    private function verify_export_ajax_request()
    {
        if (!$this->can_run_exports()) {
            wp_send_json_error(array('message' => __('Non hai i permessi necessari.', 'static-bridge')), 403);
        }
        check_ajax_referer(self::AJAX_NONCE, 'nonce');
    }

    /**
     * Who may launch, resume and cancel a full export and read Attività besides an administrator (2.5.0):
     * static_bridge_export_capability, manage_options by default. A value that is not a capability name (a non
     * string, an empty one, spaces or other characters) means manage_options.
     */
    private function export_capability()
    {
        $capability = apply_filters('static_bridge_export_capability', 'manage_options');
        return is_string($capability) && preg_match('/\A[A-Za-z0-9_-]{1,64}\z/', $capability) ? $capability : 'manage_options';
    }

    /** An administrator, or a user with the export capability. Settings, Server and the other tabs stay manage_options. */
    private function can_run_exports()
    {
        return current_user_can('manage_options') || current_user_can($this->export_capability());
    }

    private function server_uses_nginx()
    {
        $server_software = isset($_SERVER['SERVER_SOFTWARE']) ? strtolower((string) $_SERVER['SERVER_SOFTWARE']) : '';
        return false !== strpos($server_software, 'nginx');
    }

    /**
     * 'openlitespeed', 'litespeed', 'nginx', 'apache' or 'other'. A web request reads its own server variables
     * (LSWS_EDITION tells OpenLiteSpeed from LiteSpeed Enterprise, which both say "LiteSpeed") and remembers the
     * answer when it changes; WP-CLI and the system cron have no server and use the last one remembered.
     */
    private function web_server_kind()
    {
        $software = isset($_SERVER['SERVER_SOFTWARE']) ? strtolower(trim((string) $_SERVER['SERVER_SOFTWARE'])) : '';
        $edition = isset($_SERVER['LSWS_EDITION']) ? strtolower(trim((string) $_SERVER['LSWS_EDITION'])) : '';
        $kinds = array('openlitespeed', 'litespeed', 'nginx', 'apache', 'other');
        $stored = get_option(self::WEB_SERVER_OPTION, '');
        if ('' === $software && '' === $edition) {
            return in_array($stored, $kinds, true) ? $stored : 'other';
        }
        if (0 === strpos($edition, 'openlitespeed')) {
            $kind = 'openlitespeed';
        } elseif ('' !== $edition || false !== strpos($software, 'litespeed')) {
            $kind = 'litespeed';
        } elseif (false !== strpos($software, 'nginx')) {
            $kind = 'nginx';
        } elseif (false !== strpos($software, 'apache')) {
            $kind = 'apache';
        } else {
            $kind = 'other';
        }
        if ($stored !== $kind) {
            update_option(self::WEB_SERVER_OPTION, $kind, true);
        }
        return $kind;
    }

    private function nginx_regex_literal($value)
    {
        $literal = '';
        $value = (string) $value;
        for ($index = 0, $length = strlen($value); $index < $length; $index++) {
            $character = $value[$index];
            if (preg_match('/[A-Za-z0-9_\/-]/', $character)) {
                $literal .= $character;
            } else {
                $literal .= '\\x' . strtoupper(bin2hex($character));
            }
        }
        return $literal;
    }

    private function release_has_safe_ssi_source($release)
    {
        $root = realpath((string) $release);
        $release_root = $this->safe_release_root(false);
        if (!$root || '' === $release_root || $root !== $this->current_release()
            || dirname($root) !== $release_root || is_link($release)) {
            return false;
        }
        $allow_generated_includes = $this->release_uses_header_fragments($root);
        $iterator = new RecursiveIteratorIterator(
            new RecursiveDirectoryIterator($root, FilesystemIterator::SKIP_DOTS),
            RecursiveIteratorIterator::LEAVES_ONLY
        );
        $scanned = 0;
        try {
            foreach ($iterator as $file) {
                if ($file->isLink()) {
                    $path = str_replace(DIRECTORY_SEPARATOR, '/', $file->getPathname());
                    $relative = ltrim(substr($path, strlen(str_replace(DIRECTORY_SEPARATOR, '/', trailingslashit($root)))), '/');
                    if (!preg_match('~\Afragments/headers/([A-Za-z0-9_-]{1,64})/current\z~D', $relative, $link_match)) {
                        return false;
                    }
                    $document_directory = $root . '/fragments/headers/' . $link_match[1];
                    $target = readlink($file->getPathname());
                    $generations = realpath($document_directory . '/generations');
                    $generation = is_string($target)
                        && preg_match('~\Agenerations/(?:initial|generation-[a-f0-9]{24})\z~D', $target)
                        ? realpath($document_directory . '/' . $target)
                        : false;
                    if (!$generations || !$generation || dirname($generation) !== $generations || is_link($generation)) {
                        return false;
                    }
                    continue;
                }
                if (!$file->isFile() || 'html' !== strtolower($file->getExtension())) {
                    continue;
                }
                if (++$scanned > self::MAX_QUEUE_EXPORT_URLS || $file->getSize() > self::MAX_HTML_PAGE_SIZE) {
                    return false;
                }
                $html = @file_get_contents($file->getPathname());
                if (!is_string($html)) {
                    return false;
                }
                if (!Static_Bridge_Header_Fragments::contains_ssi_directive($html)) {
                    continue;
                }
                if (!$allow_generated_includes
                    || !preg_match_all(
                        '~<!--#include\s+virtual="/wp-content/static-bridge/current/fragments/headers/([A-Za-z0-9_-]{1,64})/current/(elementor-[A-Za-z0-9_-]{1,64}-[a-f0-9]{64}\.html)"\s+-->~',
                        $html,
                        $matches
                    ) || 1 !== count($matches[1])) {
                    return false;
                }
                $without_includes = preg_replace(
                    '~<!--#include\s+virtual="/wp-content/static-bridge/current/fragments/headers/[A-Za-z0-9_-]{1,64}/current/elementor-[A-Za-z0-9_-]{1,64}-[a-f0-9]{64}\.html"\s+-->~',
                    '',
                    $html
                );
                if (!is_string($without_includes) || Static_Bridge_Header_Fragments::contains_ssi_directive($without_includes)) {
                    return false;
                }
                foreach ($matches[1] as $match_index => $document_id) {
                    $filename = (string) ($matches[2][$match_index] ?? '');
                    if (0 !== strpos($filename, 'elementor-' . $document_id . '-')) {
                        return false;
                    }
                    $document_directory = $root . '/fragments/headers/' . $document_id;
                    $current_link = $document_directory . '/current';
                    $target = is_link($current_link) ? readlink($current_link) : false;
                    if (!is_string($target)
                        || !preg_match('~\Agenerations/(?:initial|generation-[a-f0-9]{24})\z~D', $target)) {
                        return false;
                    }
                    $generation = realpath($document_directory . '/' . $target);
                    $generations = realpath($document_directory . '/generations');
                    if (!$generation || !$generations || dirname($generation) !== $generations
                        || is_link($generation)) {
                        return false;
                    }
                    $fragment = trailingslashit($generation) . $filename;
                    if (is_link($fragment) || !is_file($fragment) || filesize($fragment) > self::MAX_HTML_PAGE_SIZE) {
                        return false;
                    }
                    $fragment_html = @file_get_contents($fragment);
                    if (!is_string($fragment_html) || Static_Bridge_Header_Fragments::contains_ssi_directive($fragment_html)) {
                        return false;
                    }
                }
            }
        } catch (Throwable $exception) {
            return false;
        }
        return $scanned > 0;
    }

    private function nginx_ssi_enabled()
    {
        $release = $this->current_release();
        if (!$release) {
            return false;
        }
        if ($this->release_uses_header_fragments($release)) {
            return true;
        }
        $prepared_release = get_option('static_bridge_ssi_safe_release', '');
        return !empty($this->settings()['shared_header_fragments'])
            && is_string($prepared_release) && basename($release) === $prepared_release;
    }

    /** Test the installed server rules with an ephemeral, non-sensitive SSI route. */
    private function verify_nginx_ssi_runtime($release)
    {
        $root = realpath((string) $release);
        if (!$root || $root !== $this->current_release() || !$this->nginx_ssi_enabled()
            || !function_exists('wp_safe_remote_get') || !function_exists('wp_remote_retrieve_body')) {
            return false;
        }
        try {
            $token = bin2hex(random_bytes(12));
        } catch (Throwable $exception) {
            return false;
        }
        $route_path = '_static-bridge-ssi-probe-' . $token;
        $route_url = $this->route_url('/' . $route_path . '/');
        $route_relative = $this->relative_html_path($route_url);
        $variant = hash('sha256', 'static-bridge-ssi-probe:' . $token);
        $document_id = 'ssi-probe-' . substr($token, 0, 24);
        $filename = Static_Bridge_Header_Fragments::include_filename($document_id, $variant);
        $include_uri = Static_Bridge_Header_Fragments::include_uri($document_id, $variant);
        if (is_wp_error($route_relative) || !is_string($filename) || !is_string($include_uri)) {
            return false;
        }
        $route_file = trailingslashit($root) . $route_relative;
        $route_directory = dirname($route_file);
        $fragments_parent = trailingslashit($root) . 'fragments';
        $headers_directory = trailingslashit($root) . 'fragments/headers';
        $document_directory = trailingslashit($headers_directory) . $document_id;
        $generations_directory = trailingslashit($document_directory) . 'generations';
        $generation_name = 'generation-' . substr($token, 0, 24);
        $generation_directory = trailingslashit($generations_directory) . $generation_name;
        $current_link = trailingslashit($document_directory) . 'current';
        $fragment_file = trailingslashit($generation_directory) . $filename;
        if (is_link($route_directory) || is_link($headers_directory)
            || file_exists($route_file) || is_link($route_file)
            || file_exists($document_directory) || is_link($document_directory)) {
            return false;
        }

        $route_directory_created = false;
        $fragments_parent_created = false;
        $headers_directory_created = false;
        $document_directory_created = false;
        $generations_directory_created = false;
        $generation_directory_created = false;
        $current_link_created = false;
        $route_written = false;
        $fragment_written = false;
        $write_new_file = static function ($path, $contents) {
            $handle = @fopen($path, 'x');
            if (!is_resource($handle)) {
                return false;
            }
            $offset = 0;
            $length = strlen($contents);
            while ($offset < $length) {
                $written = fwrite($handle, substr($contents, $offset));
                if (false === $written || 0 === $written) {
                    fclose($handle);
                    return false;
                }
                $offset += $written;
            }
            $ok = fflush($handle);
            fclose($handle);
            if ($ok) {
                @chmod($path, 0644);
            }
            return $ok;
        };
        try {
            if (!is_dir($route_directory)) {
                $route_directory_created = wp_mkdir_p($route_directory);
                if (!$route_directory_created) {
                    return false;
                }
            }
            if (!is_dir($fragments_parent)) {
                $fragments_parent_created = wp_mkdir_p($fragments_parent);
                if (!$fragments_parent_created) {
                    return false;
                }
            }
            if (!is_dir($headers_directory)) {
                $headers_directory_created = wp_mkdir_p($headers_directory);
                if (!$headers_directory_created) {
                    return false;
                }
            }
            $document_directory_created = wp_mkdir_p($document_directory);
            $generations_directory_created = wp_mkdir_p($generations_directory);
            $generation_directory_created = @mkdir($generation_directory, 0755);
            if (!$document_directory_created || !$generations_directory_created || !$generation_directory_created) {
                return false;
            }
            $real_route_directory = realpath($route_directory);
            $real_fragments_parent = realpath($fragments_parent);
            $real_headers_directory = realpath($headers_directory);
            $real_document_directory = realpath($document_directory);
            $real_generations_directory = realpath($generations_directory);
            $real_generation_directory = realpath($generation_directory);
            if (!$real_route_directory || !$real_headers_directory || !$real_document_directory
                || !$real_generations_directory || !$real_generation_directory || !$real_fragments_parent
                || (0 !== strpos(trailingslashit($real_route_directory), trailingslashit($root)) && $real_route_directory !== $root)
                || dirname($real_headers_directory) !== $real_fragments_parent
                || dirname($real_document_directory) !== $real_headers_directory
                || dirname($real_generations_directory) !== $real_document_directory
                || dirname($real_generation_directory) !== $real_generations_directory) {
                return false;
            }
            if (!@symlink('generations/' . $generation_name, $current_link)) {
                return false;
            }
            $current_link_created = true;
            $route_body = 'SB-SSI-BEGIN-' . $token . '<!--#include virtual="' . $include_uri . '" -->SB-SSI-END-' . $token;
            $fragment_body = 'SB-SSI-FRAGMENT-' . $token;
            $fragment_written = $write_new_file($fragment_file, $fragment_body);
            if (!$fragment_written) {
                return false;
            }
            $route_written = $write_new_file($route_file, $route_body);
            if (!$route_written) {
                return false;
            }

            // 2.5.0: both requests through self_request(), with the Basic Auth header when the site has one.
            $response = $this->self_request('GET', $route_url, array(
                'timeout' => 6,
                'redirection' => 0,
                'limit_response_size' => 8192,
                'headers' => array('Cache-Control' => 'no-cache, no-store'),
            ));
            if (is_wp_error($response) || 200 !== (int) wp_remote_retrieve_response_code($response)) {
                return false;
            }
            $body = (string) wp_remote_retrieve_body($response);
            $cache_control = strtolower((string) wp_remote_retrieve_header($response, 'cache-control'));
            $etag = (string) wp_remote_retrieve_header($response, 'etag');
            $route_header = strtolower((string) wp_remote_retrieve_header($response, 'x-static-bridge-route'));
            $direct_fragment = $this->self_request('GET', home_url($include_uri), array(
                'timeout' => 6,
                'redirection' => 0,
                'limit_response_size' => 8192,
            ));
            return 'static' === $route_header
                && 'SB-SSI-BEGIN-' . $token . $fragment_body . 'SB-SSI-END-' . $token === $body
                && false !== strpos($cache_control, 'no-store')
                && '' === $etag
                && !is_wp_error($direct_fragment)
                && 404 === (int) wp_remote_retrieve_response_code($direct_fragment);
        } catch (Throwable $exception) {
            return false;
        } finally {
            if ($route_written && is_file($route_file) && !is_link($route_file)) {
                @unlink($route_file);
            }
            if ($fragment_written && is_file($fragment_file) && !is_link($fragment_file)) {
                @unlink($fragment_file);
            }
            if ($current_link_created && is_link($current_link)
                && readlink($current_link) === 'generations/' . $generation_name) {
                @unlink($current_link);
            }
            if ($generation_directory_created && is_dir($generation_directory) && !is_link($generation_directory)) {
                @rmdir($generation_directory);
            }
            if ($generations_directory_created && is_dir($generations_directory) && !is_link($generations_directory)) {
                @rmdir($generations_directory);
            }
            if ($document_directory_created && is_dir($document_directory) && !is_link($document_directory)) {
                @rmdir($document_directory);
            }
            if ($route_directory_created && is_dir($route_directory) && !is_link($route_directory)) {
                @rmdir($route_directory);
            }
            if ($headers_directory_created && is_dir($headers_directory) && !is_link($headers_directory)) {
                @rmdir($headers_directory);
            }
            if ($fragments_parent_created && is_dir($fragments_parent) && !is_link($fragments_parent)) {
                @rmdir($fragments_parent);
            }
        }
    }

    private function nginx_router_block()
    {
        $ssi_enabled = $this->nginx_ssi_enabled();
        $ssi_directives = $ssi_enabled
            ? "    ssi on;\n    ssi_types text/html;\n    ssi_silent_errors off;\n    ssi_last_modified off;\n    etag off;\n    add_header Cache-Control \"no-store, max-age=0\" always;\n    add_header Pragma \"no-cache\" always;\n"
            : "    ssi off;\n";
        // Optional CDN header. With SSI the composed pages already carry no-store.
        $cache_control = $ssi_enabled ? '' : $this->settings()['static_cache_control'];
        $static_cache_header = '' !== $cache_control ? '    add_header Cache-Control "' . $cache_control . "\" always;\n" : '';
        // Precompressed pages (2.3.0): index.html.gz next to the file try_files names, with Vary: Accept-Encoding.
        if ($this->precompressed_pages_enabled($ssi_enabled)) {
            $static_cache_header .= "    gzip_static on;\n    gzip_vary on;\n";
        }
        // A location with its own add_header inherits none from the server block, so the site's
        // security headers are repeated here, as the render of the home page sent them.
        foreach ($this->security_headers() as $name => $value) {
            $static_cache_header .= '    add_header ' . $name . ' ' . $this->quoted_header_value($value) . " always;\n";
        }
        // With Strict active every static route is answered by @static_bridge_strict, so a
        // missing file gets its own location to carry no-store (always: a CDN must not keep the 404).
        $strict_missing = '@static_bridge_strict_missing';
        $strict_missing_location = "location @static_bridge_strict_missing {\n"
            . "    error_page 404 =404;\n"
            . "    add_header X-Static-Bridge-Route static always;\n"
            . '    add_header Cache-Control "' . self::STRICT_404_CACHE_CONTROL . "\" always;\n"
            . "    return 404;\n"
            . "}\n";
        $session_cookies = 'wordpress_logged_in_|comment_author_|wp-postpass_|woocommerce_items_in_cart|woocommerce_cart_hash|wp_woocommerce_session_';
        // 2.5.0, both off by default and then as before: a query made only of tracking parameters gets the copy (the
        // file served never depends on it), and the cookies of «Cookie che mandano a WP» send to WP. The two
        // expressions hold only [A-Za-z0-9_-] names and fixed characters, never a quote or a space.
        $tracking = $this->tracking_query_pattern();
        $query_rule = '' === $tracking ? "    if (\$args != \"\") { return 418; }\n" : '    if ($args !~ "' . $tracking . "\") { return 418; }\n";
        $cookies = $this->dynamic_cookie_pattern();
        $cookie_rule = '' === $cookies ? '' : '    if ($http_cookie ~* "' . $cookies . "\") { return 418; }\n";
        // Only the form WordPress links to is static; the other one gets WordPress's 301.
        $slash_rule = $this->routes_require_trailing_slash() ? "    if (\$uri !~ \"/\$\") { return 418; }\n" : "    if (\$uri ~ \"/\$\") { return 418; }\n";
        $private_files_location = $ssi_enabled
            ? "location ^~ /wp-content/static-bridge/ {\n    internal;\n    try_files \$uri =404;\n    ssi off;\n}\n\n"
            : "location ^~ /wp-content/static-bridge/ { deny all; }\n\n";
        // The same list as the Apache guard and the link check after a publication (2.5.0).
        $dynamic_route_rules = '';
        foreach ($this->server_dynamic_route_patterns($this->nginx_regex_literal($this->search_base())) as $pattern) {
            $dynamic_route_rules .= '    if ($uri ~* "' . $pattern . "\") { return 418; }\n";
        }
        $dynamic_rules = array();
        $root_dynamic_rule = '';
        foreach ($this->routing_excluded_paths() as $path) {
            $path = trim((string) $path, '/');
            if ('' === $path) {
                $root_dynamic_rule = "    if (\$uri = \"/\") { return 418; }\n";
                $dynamic_rules[] = '    if ($uri = "/") { return 418; }';
                continue;
            }
            $dynamic_rules[] = '    if ($uri ~* "^/' . $this->nginx_regex_literal($path) . '(?:/|$)") { return 418; }';
        }
        if (empty($dynamic_rules)) {
            $dynamic_rules[] = '    # Nessun percorso dinamico aggiuntivo configurato.';
        }
        // The domains of other languages (static_bridge_hosts) reach this WordPress too: never the main site's copy.
        $hosts = $this->other_language_hosts_pattern();
        $host_rule = '' === $hosts ? '' : '    if ($host ~* "' . $hosts . "\") { return 418; }\n";
        if ('' !== $host_rule) {
            $root_dynamic_rule .= $host_rule;
            $dynamic_rules[] = rtrim($host_rule, "\n");
        }
        // Redirects of other plugins (static_bridge_redirects): exact locations, a real 301/302 also in Strict. The
        // query goes along, as with Apache's RewriteRule: `?format=markdown` (2.5.0) reaches the target page.
        // `absolute_redirect off` (Nginx 1.11.8) keeps the Location a path, as WP sends it: without it Nginx builds
        // a URL from its own scheme and listening port, which behind a proxy or a TLS terminator are not the
        // visitor's (seen on a real site: https://example.test/old/ went to http://example.test:10068/new/).
        $redirect_locations = '';
        foreach ($this->plugin_redirects() as $from => $redirect) {
            foreach (array($from, $from . '/') as $location) {
                $redirect_locations .= 'location = ' . $location . ' { absolute_redirect off; return ' . $redirect['status'] . ' ' . $redirect['to'] . '$is_args$args' . "; }\n";
            }
        }
        if ('' !== $redirect_locations) {
            $redirect_locations = "# Reindirizzamenti di altri plugin (static_bridge_redirects).\n" . $redirect_locations . "\n";
        }

        $head = "# Static Bridge - da inserire nel blocco server {}.\n"
            . "# Sostituisce la location / esistente; conserva la location PHP e @wperror.\n"
            . $private_files_location
            . "location ^~ /wp-content/ai1wm-backups/ { deny all; }\n\n";
        $rules = "location = / {\n"
            . $ssi_directives
            . "    if (\$request_method !~ ^(?:GET|HEAD)\$) { return 418; }\n"
            . $query_rule
            . "    if (\$http_cookie ~* \"" . $session_cookies . "\") { return 418; }\n"
            . $cookie_rule
            . $root_dynamic_rule
            . "    if (!-f \$document_root/wp-content/static-bridge/.enabled) { return 418; }\n"
            . "    if (-f \$document_root/wp-content/static-bridge/.strict) { return 419; }\n"
            . "    add_header X-Static-Bridge-Route static always;\n"
            . $static_cache_header
            . "    try_files /wp-content/static-bridge/current/index.html @wperror;\n"
            . "}\n\n"
            . "location / {\n"
            . "    ssi off;\n"
            . "    try_files \$uri \$uri/ @static_bridge;\n"
            . "}\n\n"
            . "location @static_bridge {\n"
            . $ssi_directives
            . "    if (\$request_method !~ ^(?:GET|HEAD)\$) { return 418; }\n"
            . $query_rule
            . "    if (\$http_cookie ~* \"" . $session_cookies . "\") { return 418; }\n"
            . $cookie_rule
            . $dynamic_route_rules
            // Strict answers routes only: /favicon.ico, /.well-known/… and other files stay with WordPress.
            . "    if (\$uri ~ \"" . $this->file_extension_pattern() . "\") { return 418; }\n"
            . "    if (\$uri ~* \"^/\\.well-known/\") { return 418; }\n"
            . $slash_rule
            . implode("\n", $dynamic_rules) . "\n"
            . "    if (!-f \$document_root/wp-content/static-bridge/.enabled) { return 418; }\n"
            . "    if (-f \$document_root/wp-content/static-bridge/.strict) { return 419; }\n"
            . "    add_header X-Static-Bridge-Route static always;\n"
            . $static_cache_header
            . "    try_files /wp-content/static-bridge/current\$uri/index.html @wperror;\n"
            . "}\n\n"
            . "error_page 418 = @wperror;\n"
            . "error_page 419 = @static_bridge_strict;\n"
            . "location @static_bridge_strict {\n"
            . $ssi_directives
            . "    error_page 404 =404;\n"
            . "    add_header X-Static-Bridge-Route static always;\n"
            . $static_cache_header
            . "    try_files /wp-content/static-bridge/current\$uri/index.html " . $strict_missing . ";\n"
            . "}\n"
            . $strict_missing_location;

        // 2.5.0 (D5): the block is copied by hand, so it says which block it is. Every response it marks as the copy
        // also carries X-Static-Bridge-Rules, two fingerprints: the rules without the redirects, then the redirects
        // («0» when there are none). The Diagnostica compares them with the block these settings make now
        // (diagnostic_nginx_rules_step()): an option turned on or off, or redirects that changed, after the last copy.
        $fingerprint = substr(hash('sha256', $head . $rules), 0, 12) . '-'
            . ('' === $redirect_locations ? '0' : substr(hash('sha256', $redirect_locations), 0, 12));
        $marker = "    add_header X-Static-Bridge-Route static always;\n";
        $rules = str_replace($marker, $marker . '    add_header X-Static-Bridge-Rules ' . $fingerprint . " always;\n", $rules);
        return $head . $redirect_locations . $rules;
    }

    /** The X-Static-Bridge-Rules value of the block these settings make now (see nginx_router_block()). */
    private function nginx_rules_fingerprint()
    {
        return preg_match('/^    add_header X-Static-Bridge-Rules ([0-9a-f]{12}-(?:0|[0-9a-f]{12})) always;$/m', $this->nginx_router_block(), $match) ? $match[1] : '';
    }

    /**
     * True when Nginx served one of up to four pages of $release from the file (route marker and SHA-256 of the body).
     * $marked_response (2.5.0): the first response with the route marker instead, whatever its body (SSI composes it),
     * or false.
     */
    private function nginx_route_probe($release, $marked_response = false)
    {
        if (!$release || !is_dir($release)) {
            return false;
        }
        $candidates = array();
        if (is_readable(trailingslashit($release) . 'index.html') && !$this->is_excluded_path('/')) {
            $candidates['/'] = trailingslashit($release) . 'index.html';
        }
        try {
            $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($release, FilesystemIterator::SKIP_DOTS));
            foreach ($iterator as $file) {
                if (!$file->isFile() || 'html' !== strtolower($file->getExtension())) {
                    continue;
                }
                $relative = ltrim(str_replace(DIRECTORY_SEPARATOR, '/', substr($file->getPathname(), strlen(trailingslashit($release)))), '/');
                if ('index.html' === $relative) {
                    continue;
                }
                $directory = dirname($relative);
                $path = '/' . ('.' === $directory ? '' : trim($directory, '/') . '/');
                if (!$this->is_excluded_path($path)) {
                    $candidates[$path] = $file->getPathname();
                }
                if (count($candidates) >= 4) {
                    break;
                }
            }
        } catch (Exception $exception) {
            return false;
        }
        foreach ($candidates as $path => $file) {
            $response = $this->remote_get($this->route_url($path), 15, self::MAX_HTTP_RESPONSE_SIZE, true);
            if (is_wp_error($response) || 200 !== wp_remote_retrieve_response_code($response)) {
                continue;
            }
            if ($marked_response && 'static' === strtolower((string) wp_remote_retrieve_header($response, 'x-static-bridge-route'))) {
                return $response;
            }
            $expected_hash = @hash_file('sha256', $file);
            if (!$marked_response && 'static' === strtolower((string) wp_remote_retrieve_header($response, 'x-static-bridge-route'))
                && is_string($expected_hash)
                && hash_equals($expected_hash, hash('sha256', wp_remote_retrieve_body($response)))) {
                return true;
            }
        }
        return false;
    }

    private function export_http_batch_available()
    {
        if (!extension_loaded('curl')
            || !function_exists('curl_multi_init')
            || !class_exists('WpOrg\\Requests\\Requests')
            || !method_exists('WpOrg\\Requests\\Requests', 'request_multiple')
            || !class_exists('WpOrg\\Requests\\Transport\\Curl')
            || !method_exists('WpOrg\\Requests\\Transport\\Curl', 'request_multiple')
            || !class_exists('WpOrg\\Requests\\Proxy\\Http')
            || !method_exists('WpOrg\\Requests\\Proxy\\Http', 'curl_before_send')
            || !class_exists('WP_HTTP_Requests_Hooks')
            || !class_exists('WP_HTTP_Requests_Response')
            || !function_exists('wp_http_validate_url')
            || !function_exists('has_filter')
            || !function_exists('has_action')) {
            return false;
        }

        // Requests exposes these hooks around the shared multi handle. A plugin
        // using them expects control over transport setup, so retain the standard path.
        foreach (array('requests-curl.before_multi_add', 'requests-curl.before_multi_exec', 'requests-curl.after_multi_exec', 'http_api_curl') as $hook) {
            if (false !== has_action($hook)) {
                return false;
            }
        }

        return true;
    }

    private function export_http_batch_unavailable_reason()
    {
        if (!extension_loaded('curl') || !function_exists('curl_multi_init')) {
            return 'curl_multi_unavailable';
        }
        if (!class_exists('WpOrg\\Requests\\Requests')
            || !method_exists('WpOrg\\Requests\\Requests', 'request_multiple')
            || !class_exists('WpOrg\\Requests\\Transport\\Curl')
            || !method_exists('WpOrg\\Requests\\Transport\\Curl', 'request_multiple')
            || !class_exists('WpOrg\\Requests\\Proxy\\Http')
            || !method_exists('WpOrg\\Requests\\Proxy\\Http', 'curl_before_send')
            || !class_exists('WP_HTTP_Requests_Hooks')
            || !class_exists('WP_HTTP_Requests_Response')
            || !class_exists('WP_Http')
            || !class_exists('WP_HTTP_Proxy')
            || !function_exists('wp_http_validate_url')
            || !function_exists('has_filter')
            || !function_exists('has_action')) {
            return 'wordpress_requests_api_unavailable';
        }
        foreach (array('requests-curl.before_multi_add', 'requests-curl.before_multi_exec', 'requests-curl.after_multi_exec', 'http_api_curl') as $hook) {
            if (false !== has_action($hook)) {
                return 'http_api_curl' === $hook ? 'wordpress_http_curl_hook' : 'third_party_multi_transport_hook';
            }
        }
        return '';
    }

    private function export_fetch_info()
    {
        // One loopback request per PHP-FPM worker is the safe default on shared
        // hosting. Administrators may opt into parallel fetches with the filter.
        $requested = (int) apply_filters('static_bridge_export_concurrency', 1);
        $requested = max(1, min(8, $requested));
        $unavailable_reason = $this->export_http_batch_unavailable_reason();
        if (1 === $requested) {
            return array('concurrency' => 1, 'mode' => 'sequential', 'reason' => 'configured_sequential');
        }
        if ('' !== $unavailable_reason) {
            return array('concurrency' => 1, 'mode' => 'sequential', 'reason' => $unavailable_reason);
        }
        return array('concurrency' => $requested, 'mode' => 'parallel', 'reason' => 'ready');
    }

    private function fetch_pages($urls, $timeout = self::DEFAULT_EXPORT_HTTP_TIMEOUT)
    {
        $timeout = max(5, min(self::DEFAULT_EXPORT_HTTP_TIMEOUT, (int) $timeout));
        $fetch_urls = array();
        $results = array();
        foreach ((array) $urls as $url) {
            $url = (string) $url;
            if (!$this->normalize_public_url($url)) {
                $results[$url] = new WP_Error('static_bridge_unsafe_page', __('URL non valida o non appartenente al sito configurato.', 'static-bridge'));
                continue;
            }
            $fetch_urls[$url] = '';
        }

        if (empty($fetch_urls)) {
            return $results;
        }
        return array_merge($results, $this->fetch_verified_renders(array_keys($fetch_urls), $timeout, true));
    }

    /** $user_agent (2.5.0, the Diagnostica): another user agent for this render; '' is the one of remote_get(). */
    private function fetch_page($url, $timeout = self::DEFAULT_EXPORT_HTTP_TIMEOUT, $user_agent = '')
    {
        if (!$this->normalize_public_url($url)) {
            return new WP_Error('static_bridge_unsafe_page', __('URL non valida o non appartenente al sito configurato.', 'static-bridge'));
        }
        $results = $this->fetch_verified_renders(array((string) $url), $timeout, false, (string) $user_agent);
        return $results[(string) $url];
    }

    private function fetch_verified_renders($urls, $timeout, $batch, $user_agent = '')
    {
        // First pass: the static files stay where they are. The render request carries a
        // query string and a logged-in-prefixed cookie, so the plugin's Nginx block and
        // .htaccess route it to WordPress while anonymous visitors keep reading the
        // release. Removing a file the server may be serving makes Apache answer 403/404
        // between its -f check and the open. Only a route whose guarded request did not
        // reach WordPress (a server or rule set that ignores the guard) is retried with
        // its static file suspended, as before 2.0.15.
        $results = array();
        $pending = array_values($urls);
        $render_request = '' === $user_agent ? array() : array('user-agent' => $user_agent);
        foreach (array(false, true) as $suspend_static) {
            if (empty($pending)) {
                break;
            }
            // An export step (a batch) waits briefly for a render in progress; a single render answers busy at once.
            $context = $this->begin_dynamic_render_bypass($pending, $suspend_static, $batch ? self::EXPORT_RENDER_LOCK_WAIT : 0);
            if (is_wp_error($context)) {
                foreach ($pending as $url) {
                    $results[$url] = $context;
                }
                break;
            }

            $token = $context['transaction']['token'];
            $fetch_urls = array();
            foreach ($pending as $url) {
                $fetch_urls[$url] = add_query_arg(array(
                    'static_bridge_bypass' => '1',
                    'static_bridge_render' => $token,
                ), $url);
            }

            $retry = array();
            $restore_error = null;
            try {
                if ($batch) {
                    $responses = $this->remote_get_batch(array_values($fetch_urls), $timeout, self::MAX_HTML_PAGE_SIZE);
                } else {
                    $responses = array();
                    foreach ($fetch_urls as $fetch_url) {
                        $responses[$fetch_url] = $this->remote_get($fetch_url, $this->safe_export_request_timeout($timeout), self::MAX_HTML_PAGE_SIZE, true, $render_request);
                    }
                }
                foreach ($fetch_urls as $url => $fetch_url) {
                    $response = isset($responses[$fetch_url])
                        ? $responses[$fetch_url]
                        : new WP_Error('static_bridge_batch_response_missing', __('Risposta HTTP assente per una pagina richiesta.', 'static-bridge'));
                    if (!$suspend_static && $this->render_missed_wordpress($response, $token)) {
                        $retry[] = $url;
                    }
                    $verified = $this->verify_dynamic_render_response($response, $token);
                    $results[$url] = is_wp_error($verified) ? $verified : $this->parse_fetched_page($url, $verified, $token);
                }
            } finally {
                $restore_error = $this->end_dynamic_render_bypass($context);
            }

            if (is_wp_error($restore_error)) {
                foreach ($fetch_urls as $url => $unused) {
                    $results[$url] = $restore_error;
                }
                break;
            }
            $pending = $retry;
        }
        return $results;
    }

    private function render_missed_wordpress($response, $token)
    {
        // WordPress marks every response to an active render token (including its own
        // 404 page). A 2xx or 404 without that proof came from the static router, a
        // static Strict 404 or a cache in front of WordPress.
        if (is_wp_error($response) || is_wp_error($this->cdn_challenge_error($response))) {
            return false;
        }
        $status = (int) wp_remote_retrieve_response_code($response);
        if (!(($status >= 200 && $status < 300) || 404 === $status)) {
            return false;
        }
        $received_token = wp_remote_retrieve_header($response, 'x-static-bridge-render');
        if (is_array($received_token)) {
            $received_token = 1 === count($received_token) ? reset($received_token) : '';
        }
        if (is_string($received_token) && '' !== $received_token && hash_equals((string) $token, trim($received_token))) {
            return false;
        }
        return false === strpos(wp_remote_retrieve_body($response), '<!--static-bridge-render:' . $token . '-->');
    }

    private function verify_dynamic_render_response($response, $token)
    {
        if (is_wp_error($response)) {
            return $response;
        }
        $challenge = $this->cdn_challenge_error($response);
        if (is_wp_error($challenge)) {
            return $challenge;
        }
        $status = wp_remote_retrieve_response_code($response);
        if ($status >= 300 && $status < 400) {
            // Redirects contain no page body to publish. Keep the existing, strict
            // same-origin redirect validation and canonical-route handling.
            return $response;
        }
        if (in_array((int) $status, array(401, 403, 404, 410, 429, 503), true)) {
            // These responses are never published as HTML. Let the export worker
            // apply its explicit per-URL skip policy instead of misclassifying an
            // ordinary missing/private page as a broken fresh-render handshake.
            // 429/503 usually come from a CDN in front of WordPress, without the
            // render proof: they are rate limits, waited out with Retry-After (2.2.14).
            return $response;
        }
        $received_token = wp_remote_retrieve_header($response, 'x-static-bridge-render');
        if (is_array($received_token)) {
            $received_token = 1 === count($received_token) ? reset($received_token) : '';
        }
        if (!preg_match('/^[a-f0-9]{48}$/', $token)) {
            return new WP_Error('static_bridge_render_unverified', __('Il token di rendering non supera la verifica di formato; la route esistente è stata lasciata intatta.', 'static-bridge'));
        }
        $header_verified = is_string($received_token) && '' !== $received_token && hash_equals($token, trim($received_token));
        $body_marker = '<!--static-bridge-render:' . $token . '-->';
        $body_verified = false !== strpos(wp_remote_retrieve_body($response), $body_marker);
        if (!$header_verified && !$body_verified) {
            $route_header = wp_remote_retrieve_header($response, 'x-static-bridge-route');
            if (is_array($route_header)) {
                $route_header = 1 === count($route_header) ? reset($route_header) : '';
            }
            $cache_details = array();
            foreach (array('age', 'x-cache', 'cf-cache-status', 'x-proxy-cache', 'cache-control') as $header_name) {
                $value = wp_remote_retrieve_header($response, $header_name);
                if (is_array($value)) {
                    $value = 1 === count($value) ? reset($value) : '';
                }
                if (is_string($value) && '' !== trim($value)) {
                    $cache_details[] = $header_name . '=' . substr(sanitize_text_field($value), 0, 80);
                }
            }
            $cache_details = empty($cache_details) ? __('non indicato', 'static-bridge') : implode(', ', $cache_details);
            $body_hash = substr(hash('sha256', wp_remote_retrieve_body($response)), 0, 12);
            return new WP_Error(
                'static_bridge_render_unverified',
                sprintf(
                    /* translators: 1: HTTP status code, 2: value of the server route header, 3: cache headers, 4: SHA-256 hash of the response */ __('Rendering WordPress non verificato (HTTP %1$s; route server: %2$s; cache: %3$s; SHA-256 risposta: %4$s). La risposta potrebbe provenire da una cache che ignora il token o che rimuove gli header; la route statica è stata ripristinata e non sovrascritta.', 'static-bridge'),
                    wp_remote_retrieve_response_code($response),
                    is_string($route_header) && '' !== $route_header ? substr(sanitize_text_field($route_header), 0, 40) : __('non indicata', 'static-bridge'),
                    $cache_details,
                    $body_hash
                )
            );
        }
        return $response;
    }

    /**
     * Cloudflare marks a challenge or block with cf-mitigated. Such a response (often a
     * 403) says nothing about the route: it must be retried, never skipped as an expected
     * 403 that would drop the route from the next release.
     */
    private function cdn_challenge_error($response)
    {
        $mitigated = wp_remote_retrieve_header($response, 'cf-mitigated');
        if (is_array($mitigated)) {
            $mitigated = implode(', ', array_map('strval', $mitigated));
        }
        if (!is_string($mitigated) || '' === trim($mitigated)) {
            return null;
        }
        return new WP_Error(
            'static_bridge_cdn_challenge',
            sprintf(
                /* translators: 1: value of the cf-mitigated header, 2: HTTP status code */ __('Cloudflare ha fermato il rendering interno con una verifica (cf-mitigated: %1$s, HTTP %2$s); la route esistente non è stata modificata. Imposta un indirizzo di origine per il rendering in Impostazioni o escludi le richieste del server da WAF/Bot Fight Mode.', 'static-bridge'),
                substr(sanitize_text_field($mitigated), 0, 40),
                (int) wp_remote_retrieve_response_code($response)
            )
        );
    }

    private function mark_verified_render_uncacheable()
    {
        if ('' !== $this->dynamic_render_response_token() && !defined('DONOTCACHEPAGE')) {
            define('DONOTCACHEPAGE', true);
        }
    }

    public function start_dynamic_render_body_proof()
    {
        $token = $this->dynamic_render_response_token();
        if ('' === $token || !function_exists('ob_start')) {
            return;
        }
        ob_start(function ($html) use ($token) {
            return $this->append_dynamic_render_body_proof($html, $token);
        });
        // «Date relative aggiornate nel browser» (2.5.0): only in this verified render, never for a visitor.
        if ($this->relative_dates_enabled()) {
            add_filter('human_time_diff', array($this, 'mark_relative_date'), PHP_INT_MAX, 4);
        }
    }

    /** The raw setting, without settings() and its filters: read only by a verified render. */
    private function relative_dates_enabled()
    {
        $settings = get_option(self::SETTINGS_OPTION, array());
        return is_array($settings) && !empty($settings['relative_dates']);
    }

    /**
     * Filter human_time_diff (last priority, 4 arguments) during a verified render: the text inside invisible
     * markers that carry $from and $to, when $to is now. Anything else comes back unchanged.
     */
    public function mark_relative_date($since, $diff = 0, $from = 0, $to = 0)
    {
        if (!is_string($since) || '' === $since || false !== strpos($since, '<')
            || $this->has_relative_date_markers($since)) {
            return $since;
        }
        foreach (array($from, $to) as $value) {
            if (!(is_int($value) || (is_string($value) && preg_match('/\A[0-9]{1,12}\z/', $value))
                || (is_float($value) && $value >= 0 && floor($value) === $value))) {
                return $since;
            }
        }
        $from = (int) $from;
        $to = (int) $to;
        if ($from < 0 || $from > 999999999999 || abs($to - time()) > self::RELATIVE_DATE_NOW_TOLERANCE) {
            return $since;
        }
        return self::RELATIVE_DATE_OPEN . $from . self::RELATIVE_DATE_SEPARATOR . $to . self::RELATIVE_DATE_SEPARATOR
            . $since . self::RELATIVE_DATE_CLOSE;
    }

    private function append_dynamic_render_body_proof($html, $token)
    {
        if (!is_string($html) || '' === $html || !preg_match('/^[a-f0-9]{48}$/', (string) $token)
            || !hash_equals((string) $token, $this->dynamic_render_response_token())) {
            return $html;
        }
        $marker = '<!--static-bridge-render:' . $token . '-->';
        // What the render carried (nonces, a cart page, a private page), bound to the token: parse_fetched_page()
        // takes it out before anything is written.
        if (false !== strpos($html, $marker)) {
            return $html;
        }
        $facts = '<!--static-bridge-facts:' . $token . ':' . base64_encode((string) wp_json_encode($this->render_facts($html))) . '-->';
        return $html . $facts . $marker;
    }

    private function dynamic_render_response_token()
    {
        if (!isset($_GET['static_bridge_bypass'], $_GET['static_bridge_render'])
            || '1' !== (string) wp_unslash($_GET['static_bridge_bypass'])) {
            return '';
        }
        $token = strtolower(trim((string) wp_unslash($_GET['static_bridge_render'])));
        if (!preg_match('/^[a-f0-9]{48}$/', $token)) {
            return '';
        }
        $transaction = get_option(self::RENDER_BYPASS_OPTION, array());
        if (!is_array($transaction) || empty($transaction['token'])
            || !is_string($transaction['token']) || !hash_equals($transaction['token'], $token)) {
            return '';
        }
        if (empty($transaction['routes']) || !is_array($transaction['routes'])) {
            return '';
        }
        // The route the loopback asked for, or REQUEST_URI as another plugin left it (2.2.4).
        $request_uris = array(isset($_SERVER['REQUEST_URI']) ? (string) $_SERVER['REQUEST_URI'] : '/');
        if (null !== $this->request_uri_at_load) {
            $request_uris[] = $this->request_uri_at_load;
        }
        foreach ($request_uris as $request_uri) {
            $request_path = wp_parse_url($request_uri, PHP_URL_PATH);
            $route = $this->normalize_route_path(is_string($request_path) ? $request_path : '/');
            if ('' !== $route && in_array($route, $transaction['routes'], true)) {
                return $token;
            }
        }
        return '';
    }

    public function mark_dynamic_render_response()
    {
        $token = $this->dynamic_render_response_token();
        if ('' === $token) {
            return;
        }
        if (headers_sent()) {
            return;
        }
        header('X-Static-Bridge-Render: ' . $token, true);
        header('Cache-Control: no-cache, no-store, must-revalidate, max-age=0', true);
        header('Pragma: no-cache', true);
        header('Expires: Wed, 11 Jan 1984 05:00:00 GMT', true);
    }

    /**
     * «Versione Markdown delle pagine» (2.5.0): the raw setting, read without settings() and its filters, because the
     * public site asks for it (wp_head, determine_current_user).
     */
    private function markdown_pages_enabled()
    {
        $settings = get_option(self::SETTINGS_OPTION, array());
        return is_array($settings) && !empty($settings['markdown_pages']);
    }

    /** ?format=markdown in the query string, exactly: the cheap test that comes before anything else. */
    private function markdown_format_asked()
    {
        return isset($_GET['format']) && is_string($_GET['format']) && self::MARKDOWN_FORMAT === $_GET['format'];
    }

    /**
     * A GET or HEAD of the public site with ?format=markdown and the setting on. Never wp-admin, admin-ajax.php,
     * WP-Cron, WP-CLI, XML-RPC or the REST API (/wp-json/ or ?rest_route=), where a «format» argument is someone else's.
     */
    private function is_markdown_request()
    {
        if (!$this->markdown_format_asked()) {
            return false;
        }
        $method = isset($_SERVER['REQUEST_METHOD']) ? strtoupper((string) $_SERVER['REQUEST_METHOD']) : 'GET';
        if ('GET' !== $method && 'HEAD' !== $method) {
            return false;
        }
        if (is_admin() || (defined('DOING_AJAX') && DOING_AJAX) || (defined('DOING_CRON') && DOING_CRON)
            || (defined('WP_CLI') && WP_CLI) || (defined('XMLRPC_REQUEST') && XMLRPC_REQUEST)
            || (defined('REST_REQUEST') && REST_REQUEST) || isset($_GET['rest_route'])) {
            return false;
        }
        $path = isset($_SERVER['REQUEST_URI']) ? (string) wp_parse_url((string) $_SERVER['REQUEST_URI'], PHP_URL_PATH) : '/';
        $prefix = function_exists('rest_get_url_prefix') ? trim((string) rest_get_url_prefix(), '/') : 'wp-json';
        if ('' !== $prefix && preg_match('~^/' . preg_quote($prefix, '~') . '(?:/|$)~i', $path)) {
            return false;
        }
        return $this->markdown_pages_enabled();
    }

    /**
     * determine_current_user, last: a Markdown request is answered as to an anonymous visitor, whatever cookie it
     * carries, so the query, the plugins that hide content and the_content see no user. Other requests unchanged.
     */
    public function markdown_request_user($user_id)
    {
        if (!$this->markdown_format_asked()) {
            return $user_id;
        }
        if ($this->markdown_user_check) {
            // A callback of get_option() asked for the user again while the setting was read: anonymous is the safe answer.
            return 0;
        }
        $this->markdown_user_check = true;
        try {
            return $this->is_markdown_request() ? 0 : $user_id;
        } finally {
            $this->markdown_user_check = false;
        }
    }

    /**
     * template_redirect (MARKDOWN_PRIORITY, after redirect_canonical and the plugins that answer instead of the page,
     * such as a maintenance mode): the Markdown version or a plain 404, then the request ends. Other requests unchanged.
     */
    public function maybe_serve_markdown()
    {
        $response = $this->markdown_response();
        if (null === $response) {
            return;
        }
        // What another plugin buffered (a minifier, a page cache) is not part of this answer.
        while (ob_get_level() > 0) {
            if (!@ob_end_clean()) {
                break;
            }
        }
        if (!headers_sent()) {
            foreach (array('Expires', 'Pragma', 'Last-Modified', 'ETag', 'Link', 'X-Pingback') as $name) {
                header_remove($name);
            }
            status_header($response['status']);
            foreach ($response['headers'] as $name => $value) {
                header($name . ': ' . $value, true);
            }
        }
        if (!isset($_SERVER['REQUEST_METHOD']) || 'HEAD' !== strtoupper((string) $_SERVER['REQUEST_METHOD'])) {
            echo $response['body']; // phpcs:ignore WordPress.Security.EscapeOutput -- text/markdown or text/plain with nosniff, never HTML.
        }
        exit;
    }

    /**
     * The answer to a Markdown request, array('status', 'headers', 'body'), or null when the request is not one. The
     * page is the one WP resolved, always for an anonymous visitor; everything that is not a public content is a 404
     * in plain text that does not say why.
     */
    private function markdown_response()
    {
        if (!$this->is_markdown_request()) {
            return null;
        }
        // Page caches (WP Super Cache, W3 Total Cache, LiteSpeed Cache, WP Rocket) must not keep it in place of the page.
        if (!defined('DONOTCACHEPAGE')) {
            define('DONOTCACHEPAGE', true);
        }
        if (0 !== (int) get_current_user_id() && function_exists('wp_set_current_user')) {
            wp_set_current_user(0);
        }
        $target = $this->markdown_target();
        $document = null === $target ? null : $this->markdown_document($target);
        $common = array('X-Robots-Tag' => 'noindex', 'X-Content-Type-Options' => 'nosniff');
        if (null === $document) {
            return array(
                'status' => 404,
                'headers' => array('Content-Type' => 'text/plain; charset=utf-8', 'Cache-Control' => self::STRICT_404_CACHE_CONTROL) + $common,
                'body' => __('Pagina non trovata.', 'static-bridge') . "\n",
            );
        }
        return array(
            'status' => 200,
            'headers' => array(
                'Content-Type' => 'text/markdown; charset=utf-8',
                'Cache-Control' => $this->markdown_cache_control(),
                'Link' => '<' . $target['url'] . '>; rel="canonical"',
            ) + $common,
            'body' => $document,
        );
    }

    /**
     * What a Markdown request may show: array('post' => the WP_Post, or null for a home page that lists posts, 'url'
     * => its canonical URL), or null for anything that is not one public content: drafts, private, password,
     * attachments, archives, search, 404, feeds, embeds, previews, paged views, the WooCommerce cart, checkout and
     * account, and what the filter static_bridge_markdown_enabled does not allow with true.
     */
    private function markdown_target()
    {
        foreach (array('is_admin', 'is_feed', 'is_search', 'is_404', 'is_attachment', 'is_embed', 'is_preview', 'is_trackback',
            'is_robots', 'is_favicon', 'is_paged', 'is_customize_preview') as $conditional) {
            if (function_exists($conditional) && $conditional()) {
                return null;
            }
        }
        if (function_exists('get_query_var') && ((int) get_query_var('page') > 1 || (int) get_query_var('cpage') > 0)) {
            return null;
        }
        $post = null;
        if (is_singular()) {
            $post = get_queried_object();
            if (!$this->markdown_post_is_public($post)) {
                return null;
            }
        } elseif (!(is_front_page() && is_home())) {
            return null;
        }
        if ($this->markdown_shop_session_page($post)) {
            return null;
        }
        try {
            $allowed = apply_filters('static_bridge_markdown_enabled', true, $post);
        } catch (Throwable $error) {
            return null;
        }
        if (true !== $allowed) {
            return null;
        }
        $url = $this->markdown_canonical_url($post);
        return '' === $url ? null : array('post' => $post, 'url' => $url);
    }

    /** A published content without password, of a public type that is not an attachment or a shared template. */
    private function markdown_post_is_public($post)
    {
        return $post instanceof WP_Post
            && 'publish' === get_post_status($post)
            && '' === (string) $post->post_password
            && 'attachment' !== $post->post_type
            && !$this->is_shared_content_post_type($post->post_type)
            && in_array($post->post_type, $this->exportable_public_post_types(), true)
            && (!function_exists('is_post_type_viewable') || is_post_type_viewable($post->post_type));
    }

    /** The WooCommerce cart, checkout and account pages: what they show belongs to one visitor's session. */
    private function markdown_shop_session_page($post)
    {
        foreach (array('is_cart', 'is_checkout', 'is_account_page') as $conditional) {
            if (function_exists($conditional) && $conditional()) {
                return true;
            }
        }
        if ($post instanceof WP_Post && function_exists('wc_get_page_id')) {
            foreach (array('cart', 'checkout', 'myaccount') as $page) {
                if ((int) wc_get_page_id($page) === (int) $post->ID) {
                    return true;
                }
            }
        }
        return false;
    }

    /**
     * The canonical URL: wp_get_canonical_url() (which SEO plugins filter) when it stays on this site, otherwise the
     * permalink, or the home page for a list of posts; '' when it is not a URL of this site that a header can carry.
     */
    private function markdown_canonical_url($post)
    {
        $url = null === $post ? home_url('/') : get_permalink($post);
        if (null !== $post && function_exists('wp_get_canonical_url')) {
            $canonical = wp_get_canonical_url($post);
            if (is_string($canonical) && $this->same_site_url($canonical)) {
                $url = $canonical;
            }
        }
        if (!is_string($url) || !$this->same_site_url($url) || preg_match('~[\x00-\x20\x7F<>"\\\\]~', $url)) {
            return '';
        }
        return $url;
    }

    /**
     * The Markdown of the target: a YAML front matter (title, url, lang, modified) and the text of the page, from its
     * copy in the current release when a fresh one exists, otherwise from the_content (or, for a home page that
     * lists posts, from the list); then the filter static_bridge_markdown. Null without the module, or when the HTML
     * shows a PHP or database error or the Basic Auth credentials, as a static copy would refuse it.
     */
    private function markdown_document(array $target)
    {
        if (!class_exists('Static_Bridge_Markdown') && is_readable(__DIR__ . '/markdown.php')) {
            require_once __DIR__ . '/markdown.php';
        }
        if (!class_exists('Static_Bridge_Markdown')) {
            return null;
        }
        $post = $target['post'];
        $deadline = microtime(true) + Static_Bridge_Markdown::TIME_BUDGET;
        $html = $this->markdown_release_html($target);
        if (null === $html) {
            $html = null === $post ? $this->markdown_home_list_html() : $this->markdown_content_html($post);
        }
        if (!is_string($html) || '' !== $this->php_error_output_in($html) || $this->basic_auth_echo_in($html)) {
            return null;
        }
        $converted = Static_Bridge_Markdown::convert($html, array(
            'url' => $target['url'],
            'origin' => untrailingslashit(home_url('/')),
            'deadline' => $deadline,
        ));
        $language_tag = '/^[A-Za-z]{2,8}(?:-[A-Za-z0-9]{1,8}){0,5}$/';
        $lang = preg_match($language_tag, $converted['lang']) ? $converted['lang'] : (string) get_bloginfo('language');
        $document = "---\n"
            . 'title: ' . $this->yaml_string($this->markdown_plain_text(null === $post ? get_bloginfo('name') : get_the_title($post))) . "\n"
            . 'url: ' . $this->yaml_string($target['url']) . "\n"
            . 'lang: ' . $this->yaml_string(preg_match($language_tag, $lang) ? $lang : '') . "\n"
            . 'modified: ' . $this->yaml_string($this->markdown_modified($post)) . "\n"
            . "---\n\n"
            . $converted['markdown'];
        try {
            $filtered = apply_filters('static_bridge_markdown', $document, $post);
        } catch (Throwable $error) {
            $filtered = $document;
        }
        if (is_string($filtered) && '' !== $filtered && strlen($filtered) <= Static_Bridge_Markdown::MAX_DOCUMENT_BYTES
            && preg_match('//u', $filtered)) {
            $document = $filtered;
        }
        return $document;
    }

    /**
     * The HTML of the target's copy in the current release, or null: no release, a path kept with WP (excluded, a
     * form, the editor checkbox), a symlink anywhere below the release, a file outside it, empty or larger than
     * Static_Bridge_Markdown::MAX_HTML_BYTES, or older than the last change of the content (the_content has the
     * newer text until the queue rewrites the copy).
     */
    private function markdown_release_html(array $target)
    {
        $release = $this->current_release();
        if ('' === $release) {
            return null;
        }
        $route = $this->normalize_route_path($target['url']);
        $relative = $this->relative_html_path($target['url']);
        if ('' === $route || is_wp_error($relative) || $this->is_excluded_path($route)) {
            return null;
        }
        $file = $release;
        foreach (explode('/', $relative) as $segment) {
            $file .= '/' . $segment;
            if (is_link($file)) {
                return null;
            }
        }
        clearstatcache(true, $file);
        $real = realpath($file);
        $size = @filesize($file);
        if (!is_file($file) || !$real || 0 !== strpos($real, trailingslashit($release)) || false === $size || $size < 1
            || $size > Static_Bridge_Markdown::MAX_HTML_BYTES) {
            return null;
        }
        if ($target['post'] instanceof WP_Post) {
            $written = @filemtime($file);
            if (false === $written || (int) get_post_modified_time('U', true, $target['post']) > (int) $written) {
                return null;
            }
        }
        $html = @file_get_contents($real);
        return is_string($html) && '' !== $html ? $html : null;
    }

    /**
     * The content passed through the_content as its page shows it, with the title as <h1>. Output a shortcode echoes
     * is dropped, an exception gives null, the global post is restored.
     */
    private function markdown_content_html($post)
    {
        $previous = isset($GLOBALS['post']) ? $GLOBALS['post'] : null;
        $GLOBALS['post'] = $post;
        setup_postdata($post);
        $level = ob_get_level();
        ob_start();
        try {
            $content = apply_filters('the_content', get_the_content(null, false, $post));
        } catch (Throwable $error) {
            $content = null;
        } finally {
            while (ob_get_level() > $level) {
                ob_end_clean();
            }
            $GLOBALS['post'] = $previous;
            wp_reset_postdata();
        }
        if (!is_string($content)) {
            return null;
        }
        return '<main><h1>' . esc_html($this->markdown_plain_text(get_the_title($post))) . '</h1>' . $content . '</main>';
    }

    /** A home page that lists posts and has no copy: the site name, its tagline and the public posts of the page as links. */
    private function markdown_home_list_html()
    {
        global $wp_query;
        $items = '';
        $posts = isset($wp_query) && is_object($wp_query) && isset($wp_query->posts) && is_array($wp_query->posts) ? $wp_query->posts : array();
        foreach ($posts as $post) {
            $url = $this->markdown_post_is_public($post) ? get_permalink($post) : '';
            if (is_string($url) && '' !== $url && $this->same_site_url($url)) {
                $items .= '<li><a href="' . esc_url($url) . '">' . esc_html($this->markdown_plain_text(get_the_title($post))) . '</a></li>';
            }
        }
        $description = $this->markdown_plain_text(get_bloginfo('description'));
        return '<main><h1>' . esc_html($this->markdown_plain_text(get_bloginfo('name'))) . '</h1>'
            . ('' === $description ? '' : '<p>' . esc_html($description) . '</p>')
            . ('' === $items ? '' : '<ul>' . $items . '</ul>') . '</main>';
    }

    /** ISO 8601 in UTC of the content's last change (for a list of posts, of the last post), or ''. */
    private function markdown_modified($post)
    {
        if (null !== $post) {
            $time = get_post_modified_time('U', true, $post);
        } else {
            $last = function_exists('get_lastpostmodified') ? get_lastpostmodified('gmt') : false;
            $time = is_string($last) && '' !== $last ? strtotime($last . ' UTC') : false;
        }
        return is_numeric($time) && (int) $time > 0 ? gmdate('c', (int) $time) : '';
    }

    /** Text without tags, entities, control characters or runs of spaces. */
    private function markdown_plain_text($text)
    {
        $text = html_entity_decode(wp_strip_all_tags((string) $text), ENT_QUOTES | ENT_HTML5, 'UTF-8');
        return trim((string) preg_replace('/[\s\x{0000}-\x{001F}\x{007F}-\x{009F}]+/u', ' ', $text));
    }

    /** A YAML double-quoted scalar: the JSON string, which YAML reads the same, with invalid UTF-8 replaced. */
    private function yaml_string($value)
    {
        $encoded = wp_json_encode((string) $value, JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE | JSON_INVALID_UTF8_SUBSTITUTE);
        return is_string($encoded) ? $encoded : '""';
    }

    /** Cache-Control of a Markdown answer: public for MARKDOWN_MAX_AGE seconds, or what static_bridge_markdown_max_age says (0 to 86400). */
    private function markdown_cache_control()
    {
        try {
            $max_age = apply_filters('static_bridge_markdown_max_age', self::MARKDOWN_MAX_AGE);
        } catch (Throwable $error) {
            $max_age = self::MARKDOWN_MAX_AGE;
        }
        if (!is_int($max_age) || $max_age < 0 || $max_age > 86400) {
            $max_age = self::MARKDOWN_MAX_AGE;
        }
        return 0 === $max_age ? 'no-cache, max-age=0' : 'public, max-age=' . $max_age;
    }

    /**
     * wp_head (9): with the setting on, on a page a Markdown request would answer, <link rel="alternate"
     * type="text/markdown"> to its ?format=markdown. A copy written after the setting is on carries it too, absolute
     * like the other rel="alternate" links (is_absolute_url_tag()).
     */
    public function print_markdown_alternate_link()
    {
        if (is_admin() || !$this->markdown_pages_enabled()) {
            return;
        }
        $target = $this->markdown_target();
        if (null === $target) {
            return;
        }
        echo '<link rel="alternate" type="text/markdown" href="' . esc_url(add_query_arg('format', self::MARKDOWN_FORMAT, $target['url'])) . '" />' . "\n";
    }

    /** $wait: seconds to wait for a lock another render holds (an export step); 0 answers busy at once. */
    private function acquire_render_bypass_lock($wait = 0)
    {
        $static_root = $this->static_root();
        $content_root = realpath(WP_CONTENT_DIR);
        if (!$content_root || is_link($static_root) || (file_exists($static_root) && !is_dir($static_root))) {
            return new WP_Error('static_bridge_render_storage', __('La cartella delle copie statiche non è nel percorso previsto.', 'static-bridge'));
        }
        $root = trailingslashit($content_root) . 'static-bridge';
        if (file_exists($static_root) && realpath($static_root) !== $root) {
            return new WP_Error('static_bridge_render_storage', __('La cartella delle copie statiche non è nel percorso previsto.', 'static-bridge'));
        }

        $lock_directory = realpath(sys_get_temp_dir());
        if (!$lock_directory) {
            return new WP_Error('static_bridge_render_lock', __('La cartella temporanea del server non è disponibile per il lock.', 'static-bridge'));
        }
        $lock_path = trailingslashit($lock_directory) . 'static-bridge-render-' . substr(hash('sha256', $root), 0, 24) . '.lock';
        if (is_link($lock_path) || (file_exists($lock_path) && !is_file($lock_path))) {
            return new WP_Error('static_bridge_render_lock', __('Il lock del rendering interno non è un file regolare; il push è stato fermato.', 'static-bridge'));
        }
        $handle = @fopen($lock_path, 'c');
        if (!is_resource($handle)) {
            return new WP_Error('static_bridge_render_lock', __('Impossibile creare il lock del rendering interno.', 'static-bridge'));
        }
        @chmod($lock_path, 0600);
        $deadline = microtime(true) + max(0, (float) $wait);
        while (!@flock($handle, LOCK_EX | LOCK_NB)) {
            if (microtime(true) >= $deadline) {
                fclose($handle);
                $handle = null;
                break;
            }
            usleep(100000);
        }
        if (!is_resource($handle)) {
            return new WP_Error('static_bridge_render_busy', __('Un altro rendering Static Bridge è in corso; nessuna pagina è stata modificata.', 'static-bridge'));
        }
        return array('root' => $root, 'handle' => $handle);
    }

    private function release_render_bypass_lock($handle)
    {
        if (is_resource($handle)) {
            @flock($handle, LOCK_UN);
            fclose($handle);
        }
    }

    /**
     * The render transaction as its row holds it now. Every request reads the option at init
     * (recover_interrupted_render_bypass()), often while another render owns it; after that render ends, the
     * request's option cache still answered with the old transaction, so delete_option() and update_option() found no
     * row to change and the new transaction could not be saved (2.4.1: «Impossibile salvare la transazione di
     * sicurezza del rendering» on an immediate push). Read under the render lock only.
     */
    private function render_bypass_transaction_row()
    {
        $this->forget_cached_option(self::RENDER_BYPASS_OPTION);
        return get_option(self::RENDER_BYPASS_OPTION, false);
    }

    private function begin_dynamic_render_bypass($urls, $suspend_static = false, $lock_wait = 0)
    {
        $lock = $this->acquire_render_bypass_lock($lock_wait);
        if (is_wp_error($lock)) {
            return $lock;
        }

        $existing = $this->render_bypass_transaction_row();
        if (is_array($existing)) {
            $recovered = $this->restore_render_bypass_transaction($existing, $lock['root']);
            if (is_wp_error($recovered)) {
                $this->release_render_bypass_lock($lock['handle']);
                return $recovered;
            }
        }

        try {
            $token = bin2hex(random_bytes(24));
        } catch (Throwable $exception) {
            $this->release_render_bypass_lock($lock['handle']);
            return new WP_Error('static_bridge_render_token', __('Non è stato possibile creare un token sicuro per verificare il rendering.', 'static-bridge'));
        }

        $release = $this->current_release();
        $release_id = $release ? basename($release) : '';
        if ('' !== $release_id && !preg_match('/^[A-Za-z0-9_-]{1,100}$/', $release_id)) {
            $this->release_render_bypass_lock($lock['handle']);
            return new WP_Error('static_bridge_render_release', __('La release corrente non ha un identificativo valido.', 'static-bridge'));
        }

        $routes = array();
        $files = array();
        foreach ((array) $urls as $url) {
            $normalized = $this->normalize_public_url((string) $url);
            $route = $normalized ? $this->normalize_route_path($normalized) : '';
            if ('' === $route) {
                $this->release_render_bypass_lock($lock['handle']);
                return new WP_Error('static_bridge_render_route', __('Una route non può essere messa in bypass in sicurezza.', 'static-bridge'));
            }
            if (!in_array($route, $routes, true)) {
                $routes[] = $route;
            }
            if (!$release || !$suspend_static) {
                continue;
            }

            $relative = $this->relative_html_path($normalized);
            if (is_wp_error($relative)) {
                $this->release_render_bypass_lock($lock['handle']);
                return $relative;
            }
            $target = trailingslashit($release) . $relative;
            $parent = realpath(dirname($target));
            if (!$parent || (0 !== strpos(trailingslashit($parent), trailingslashit($release)) && $parent !== $release)) {
                if (!file_exists($target) && !is_link($target)) {
                    continue;
                }
                $this->release_render_bypass_lock($lock['handle']);
                return new WP_Error('static_bridge_render_path', __('La cartella della route statica non è all’interno della release attiva.', 'static-bridge'));
            }
            if (!file_exists($target) && !is_link($target)) {
                continue;
            }
            if (is_link($target) || !is_file($target)) {
                $this->release_render_bypass_lock($lock['handle']);
                return new WP_Error('static_bridge_render_file', __('Il file della route statica non è regolare; il push è stato fermato senza modificarlo.', 'static-bridge'));
            }
            if (filesize($target) > self::MAX_HTML_PAGE_SIZE) {
                $this->release_render_bypass_lock($lock['handle']);
                return new WP_Error('static_bridge_render_file', __('Il file statico supera il limite consentito per il bypass interno.', 'static-bridge'));
            }
            $backup = basename($target) . '.sb-render-' . $token . '-' . count($files) . '.bak';
            if (file_exists(dirname($target) . '/' . $backup) || is_link(dirname($target) . '/' . $backup)) {
                $this->release_render_bypass_lock($lock['handle']);
                return new WP_Error('static_bridge_render_backup', __('È già presente un file temporaneo di rendering con lo stesso identificativo.', 'static-bridge'));
            }
            $files[] = array('route' => $route, 'backup' => $backup);
        }

        $markers = array();
        foreach ($suspend_static ? array('strict' => '.strict') : array() as $name => $filename) {
            $path = trailingslashit($lock['root']) . $filename;
            if (is_link($path) || (file_exists($path) && !is_file($path))) {
                $this->release_render_bypass_lock($lock['handle']);
                return new WP_Error('static_bridge_render_marker', __('Un marker di routing non è un file regolare; il rendering è stato fermato.', 'static-bridge'));
            }
            $exists = is_file($path);
            $contents = $exists ? @file_get_contents($path) : '';
            if (!is_string($contents) || strlen($contents) > 4096) {
                $this->release_render_bypass_lock($lock['handle']);
                return new WP_Error('static_bridge_render_marker', __('Impossibile leggere in sicurezza un marker di routing.', 'static-bridge'));
            }
            $markers[$name] = array(
                'exists' => $exists,
                'contents' => $contents,
                'mode' => $exists ? (fileperms($path) & 0777) : 0644,
            );
        }

        $transaction = array(
            'token' => $token,
            'started_at' => time(),
            'release_id' => $release_id,
            'routes' => $routes,
            'suspended' => (bool) $suspend_static,
            'files' => $files,
            'markers' => $markers,
        );
        update_option(self::RENDER_BYPASS_OPTION, $transaction, false);
        $stored = $this->render_bypass_transaction_row();
        if (!is_array($stored) || empty($stored['token']) || !hash_equals($token, (string) $stored['token'])) {
            $this->release_render_bypass_lock($lock['handle']);
            return new WP_Error('static_bridge_render_transaction', __('Impossibile salvare la transazione di sicurezza del rendering.', 'static-bridge'));
        }

        if ($release) {
            foreach ($files as $entry) {
                $relative = $this->relative_html_path(home_url($entry['route']));
                $target = trailingslashit($release) . $relative;
                $backup = dirname($target) . '/' . $entry['backup'];
                if (!@rename($target, $backup)) {
                    $this->restore_render_bypass_transaction($transaction, $lock['root']);
                    $this->release_render_bypass_lock($lock['handle']);
                    return new WP_Error('static_bridge_render_suspend', __('Impossibile sospendere temporaneamente la route statica esistente.', 'static-bridge'));
                }
            }
        }

        foreach ($suspend_static ? array('strict' => '.strict') : array() as $name => $filename) {
            // Keep normal static routing enabled for every unaffected route. Only
            // Strict mode must be lifted while the requested file is temporarily
            // absent, otherwise the server would return a static 404 instead of
            // falling through to WordPress for this one render request.
            if ('strict' === $name && !empty($markers[$name]['exists'])
                && !@unlink(trailingslashit($lock['root']) . $filename)) {
                $this->restore_render_bypass_transaction($transaction, $lock['root']);
                $this->release_render_bypass_lock($lock['handle']);
                return new WP_Error('static_bridge_render_suspend', __('Impossibile sospendere temporaneamente Strict; la route non è stata aggiornata.', 'static-bridge'));
            }
        }

        return array('transaction' => $transaction, 'lock' => $lock['handle'], 'root' => $lock['root']);
    }

    private function end_dynamic_render_bypass($context)
    {
        if (!is_array($context) || !isset($context['transaction'], $context['lock'], $context['root'])) {
            if (is_array($context) && isset($context['lock'])) {
                $this->release_render_bypass_lock($context['lock']);
            }
            return new WP_Error('static_bridge_render_transaction', __('Contesto di rendering incompleto; la route non è stata pubblicata.', 'static-bridge'));
        }
        $transaction = $this->render_bypass_transaction_row();
        if (!is_array($transaction) || empty($transaction['token'])
            || !hash_equals((string) $context['transaction']['token'], (string) $transaction['token'])) {
            $this->release_render_bypass_lock($context['lock']);
            return new WP_Error('static_bridge_render_transaction', __('La transazione di rendering è cambiata prima del ripristino; la route non è stata pubblicata.', 'static-bridge'));
        }
        $result = $this->restore_render_bypass_transaction($transaction, $context['root']);
        $this->release_render_bypass_lock($context['lock']);
        return $result;
    }

    private function restore_render_bypass_transaction($transaction, $root)
    {
        if (!is_array($transaction) || empty($transaction['token'])
            || !preg_match('/^[a-f0-9]{48}$/', (string) $transaction['token'])
            || !is_string($root)) {
            return new WP_Error('static_bridge_render_recovery', __('Transazione di rendering non valida; il risultato non può essere pubblicato.', 'static-bridge'));
        }

        $content_root = realpath(WP_CONTENT_DIR);
        $expected_root = $content_root ? trailingslashit($content_root) . 'static-bridge' : '';
        if ('' === $expected_root || $root !== $expected_root
            || (file_exists($root) && (is_link($root) || realpath($root) !== $root))) {
            return new WP_Error('static_bridge_render_recovery', __('La cartella statica non supera la verifica del percorso; il routing resta gestito da WordPress.', 'static-bridge'));
        }

        $release_root = $this->safe_release_root(false);
        $release_id = isset($transaction['release_id']) ? (string) $transaction['release_id'] : '';
        $release = '';
        if ('' !== $release_id) {
            if ('' === $release_root || !preg_match('/^[A-Za-z0-9_-]{1,100}$/', $release_id)) {
                return new WP_Error('static_bridge_render_recovery', __('Release del rendering non verificabile: il sito resta instradato su WordPress.', 'static-bridge'));
            }
            $candidate = trailingslashit($release_root) . $release_id;
            $release = realpath($candidate);
            if (!$release || dirname($release) !== $release_root || is_link($candidate)) {
                return new WP_Error('static_bridge_render_recovery', __('Release del rendering non più disponibile: il sito resta instradato su WordPress.', 'static-bridge'));
            }
        }

        $file_errors = array();
        foreach (isset($transaction['files']) && is_array($transaction['files']) ? $transaction['files'] : array() as $entry) {
            $route = isset($entry['route']) ? $this->normalize_route_path((string) $entry['route']) : '';
            $backup_name = isset($entry['backup']) ? (string) $entry['backup'] : '';
            if (!$release || '' === $route || !preg_match('/^index\.html\.sb-render-' . preg_quote($transaction['token'], '/') . '-[0-9]{1,5}\.bak$/', $backup_name)) {
                $file_errors[] = __('Un file di recovery non supera la validazione del percorso.', 'static-bridge');
                continue;
            }
            $relative = $this->relative_html_path(home_url($route));
            if (is_wp_error($relative)) {
                $file_errors[] = $relative->get_error_message();
                continue;
            }
            $target = trailingslashit($release) . $relative;
            $parent = realpath(dirname($target));
            if (!$parent || (0 !== strpos(trailingslashit($parent), trailingslashit($release)) && $parent !== $release)) {
                $file_errors[] = __('La cartella della route di recovery non è nella release registrata.', 'static-bridge');
                continue;
            }
            $backup = dirname($target) . '/' . $backup_name;
            if (is_link($target) || is_link($backup)) {
                $file_errors[] = __('Un file della route di recovery è diventato un collegamento simbolico.', 'static-bridge');
                continue;
            }
            if (is_file($backup)) {
                if (file_exists($target) || !@rename($backup, $target)) {
                    $file_errors[] = __('La route statica esiste già o non può essere ripristinata dal backup temporaneo.', 'static-bridge');
                    continue;
                }
            } elseif (!is_file($target)) {
                $file_errors[] = __('Sono assenti sia la route originale sia il suo backup temporaneo.', 'static-bridge');
            }
        }

        if (!empty($file_errors)) {
            return new WP_Error('static_bridge_render_recovery', implode(' ', array_unique($file_errors)) . ' ' . __('Strict resta disattivato per consentire al server il fallback WordPress sulla route sospesa.', 'static-bridge'));
        }

        foreach (array('strict' => '.strict') as $name => $filename) {
            $marker = trailingslashit($root) . $filename;
            $state = isset($transaction['markers'][$name]) && is_array($transaction['markers'][$name])
                ? $transaction['markers'][$name]
                : array('exists' => false, 'contents' => '');
            if (is_link($marker) || (file_exists($marker) && !is_file($marker))) {
                return new WP_Error('static_bridge_render_recovery', __('Un marker non può essere ripristinato in sicurezza; il routing resta gestito da WordPress.', 'static-bridge'));
            }
            if (!empty($state['exists'])) {
                $contents = isset($state['contents']) && is_string($state['contents']) ? $state['contents'] : '';
                if (is_file($marker)) {
                    $current_contents = @file_get_contents($marker);
                    if (!is_string($current_contents) || !hash_equals($contents, $current_contents)) {
                        return new WP_Error('static_bridge_render_recovery', __('Un marker è stato modificato durante il rendering; il ripristino automatico non lo sovrascrive.', 'static-bridge'));
                    }
                    continue;
                }
                $handle = @fopen($marker, 'x');
                if (!is_resource($handle)) {
                    return new WP_Error('static_bridge_render_recovery', __('Impossibile ripristinare un marker; il routing resta gestito da WordPress.', 'static-bridge'));
                }
                $written = 0 === strlen($contents) ? 0 : fwrite($handle, $contents);
                $ok = 0 === strlen($contents) || strlen($contents) === $written;
                fclose($handle);
                if (!$ok) {
                    @unlink($marker);
                    return new WP_Error('static_bridge_render_recovery', __('Scrittura di un marker incompleta; il routing resta gestito da WordPress.', 'static-bridge'));
                }
                $mode = isset($state['mode']) && is_numeric($state['mode']) ? (int) $state['mode'] & 0777 : 0644;
                if (!@chmod($marker, $mode)) {
                    return new WP_Error('static_bridge_render_recovery', __('Il marker è stato ricreato ma i permessi originali non sono ripristinabili.', 'static-bridge'));
                }
            }
        }

        delete_option(self::RENDER_BYPASS_OPTION);
        return true;
    }

    private function recover_interrupted_render_bypass()
    {
        $transaction = get_option(self::RENDER_BYPASS_OPTION, false);
        if (!is_array($transaction)) {
            return;
        }
        $lock = $this->acquire_render_bypass_lock();
        if (is_wp_error($lock)) {
            return;
        }
        try {
            $current = $this->render_bypass_transaction_row();
            if (is_array($current)) {
                $result = $this->restore_render_bypass_transaction($current, $lock['root']);
                if (is_wp_error($result) && empty($current['recovery_reported'])) {
                    $current['recovery_reported'] = 1;
                    update_option(self::RENDER_BYPASS_OPTION, $current, false);
                    $this->log_activity(__('Recupero rendering incompleto: la route non è stata aggiornata.', 'static-bridge'), $result->get_error_message(), true);
                }
            }
        } finally {
            $this->release_render_bypass_lock($lock['handle']);
        }
    }

    private function safe_php_request_budget()
    {
        $execution_limit = (int) ini_get('max_execution_time');
        if ($execution_limit < 1) {
            return 0;
        }

        $safety_margin = max(5, min(10, (int) ceil($execution_limit / 3)));
        return max(1, $execution_limit - $safety_margin);
    }

    private function safe_export_request_timeout($timeout)
    {
        $timeout = max(1, min(self::DEFAULT_EXPORT_HTTP_TIMEOUT, (int) $timeout));
        $php_request_budget = $this->safe_php_request_budget();
        if ($php_request_budget > 0) {
            $timeout = min($timeout, $php_request_budget);
        }

        return max(1, $timeout);
    }

    private function parse_fetched_page($url, $response, $render_token = '')
    {
        if (is_wp_error($response)) {
            return $response;
        }
        $status = wp_remote_retrieve_response_code($response);
        if ($status >= 300 && $status < 400) {
            $location = wp_remote_retrieve_header($response, 'location');
            $absolute = '' !== (string) $location ? $this->absolute_url($location, $url) : '';
            $target = $absolute ? $this->normalize_redirect_target($absolute) : '';
            if ($target) {
                return new WP_Error(
                    'static_bridge_redirect',
                    sprintf(/* translators: %s: redirect destination URL */ __('Redirect interno verso %s; verrà elaborata la destinazione canonica.', 'static-bridge'), $target),
                    $target
                );
            }
            return new WP_Error('static_bridge_redirect_unsafe', __('Redirect esterno, dinamico o non valido; la destinazione non è stata seguita.', 'static-bridge'));
        }
        if ($status < 200 || $status >= 300) {
            if (in_array((int) $status, array(429, 503), true)) {
                $this->export_retry_after[(string) $url] = $this->retry_after_seconds(wp_remote_retrieve_header($response, 'retry-after'));
            }
            return new WP_Error('static_bridge_http', sprintf(/* translators: %s: HTTP status code */ __('Risposta HTTP %s.', 'static-bridge'), $status), (int) $status);
        }
        $content_type = wp_remote_retrieve_header($response, 'content-type');
        if (is_string($content_type) && '' !== $content_type && false === stripos($content_type, 'text/html')) {
            return new WP_Error('static_bridge_type', sprintf(/* translators: %s: Content-Type */ __('Tipo di contenuto non HTML: %s.', 'static-bridge'), $content_type));
        }
        $body = wp_remote_retrieve_body($response);
        if ('' === trim($body)) {
            return new WP_Error('static_bridge_empty_page', __('La risposta HTML è vuota.', 'static-bridge'));
        }
        if (strlen($body) >= self::MAX_HTML_PAGE_SIZE) {
            return new WP_Error('static_bridge_page_too_large', __('La pagina supera il limite di 5 MiB o la risposta è stata troncata; non è stata pubblicata.', 'static-bridge'));
        }
        $php_error = $this->php_error_output_in($body);
        if ('' !== $php_error) {
            return new WP_Error(
                'static_bridge_php_error_output',
                sprintf(
                    /* translators: %s: kind of message, as PHP prints it (Warning, Notice, Deprecated…), or Xdebug, or database */
                    __('La pagina mostra un errore di PHP o del database (%s), con percorsi dei file o query del server; non è stata pubblicata. Spegni la visualizzazione degli errori (WP_DEBUG_DISPLAY o display_errors) e correggi l’errore.', 'static-bridge'),
                    $php_error
                )
            );
        }
        if ($this->basic_auth_echo_in($body)) {
            // 2.5.0: the page shows the credentials the request carried (phpinfo(), a dump of the request headers).
            return new WP_Error('static_bridge_basic_auth_echo', __('La pagina mostra le credenziali di Basic Auth che Static Bridge ha mandato nella richiesta (per esempio una pagina phpinfo() o di debug); non è stata pubblicata.', 'static-bridge'));
        }
        list($body, $render_facts) = $this->extract_render_facts($body, $render_token);
        $body = $this->strip_render_bypass_parameters($body, $render_token);
        // 2.5.0: the markers of mark_relative_date() become spans in the text, and go everywhere else.
        $body = $this->relative_dates_static_html($body);
        return array('body' => $body, 'security_headers' => $this->security_headers_from_response($response), 'render_facts' => $render_facts);
    }

    /**
     * 2.5.0: true when the HTML holds the Basic Auth credentials of wp-config.php: the base64 value of the header,
     * user:password, or the password itself when it has at least 8 characters (a shorter one is too likely to be an
     * ordinary word). Such a page would hand them to every visitor of the static copy. False when Basic Auth is off.
     */
    private function basic_auth_echo_in($html)
    {
        $credentials = $this->basic_auth_credentials();
        if ('on' !== $credentials['state'] || '' === (string) $html) {
            return false;
        }
        $pair = $credentials['user'] . ':' . $credentials['password'];
        return false !== strpos($html, base64_encode($pair)) || false !== strpos($html, $pair)
            || (strlen($credentials['password']) >= 8 && false !== strpos($html, $credentials['password']));
    }

    /**
     * The kind of error message the page prints (Warning, Notice, Deprecated, Fatal error…, Xdebug, or database), ''
     * when none. With display_errors on, PHP writes the message with the path of a server file into the HTML; with
     * WP_DEBUG on, wpdb prints a failed query with its table names. On WP only that request sees it, in a static copy
     * every visitor does, for weeks. What a page shows as text (code samples, a textarea, scripts, styles, comments)
     * is left out, so an article that quotes a PHP error is not one.
     */
    private function php_error_output_in($html)
    {
        if (!is_string($html) || '' === $html
            || (false === stripos($html, ' on line') && false === stripos($html, 'xdebug-error') && false === stripos($html, 'wpdberror'))) {
            return '';
        }
        $scan = preg_replace('~<(pre|code|textarea|script|style|xmp)\b[^>]*>.*?</\1\s*>|<!--.*?-->~is', ' ', $html);
        if (!is_string($scan)) {
            // The cleaning failed (PCRE limits): look at the whole page. A false alarm keeps the page with WP.
            $scan = $html;
        }
        if (preg_match('~<(?:table|div|font|span)\b[^>]*\bclass\s*=\s*["\'][^"\']*\bxdebug-error\b~i', $scan)) {
            return 'Xdebug';
        }
        // wpdb::print_error(): <div id="error"><p class="wpdberror"><strong>WordPress database error:</strong> […]<br /><code>SQL</code></p></div>
        if (preg_match('~<p\b[^>]*\bclass\s*=\s*["\']wpdberror["\']~i', $scan)) {
            return 'database';
        }
        $path = '(?:<b>)?[^\r\n<>"\']{1,512}?\.(?:php|phtml|inc)(?:</b>)?[ \t]+on[ \t]+line[ \t]+(?:<b>)?\d';
        if (preg_match('~(?:\A|[\r\n>])[ \t]*(?:<b>[ \t]*)?(?:PHP[ \t]+)?(Fatal error|Parse error|Recoverable fatal error|Catchable fatal error|Warning|Notice|Deprecated|Strict Standards)(?:[ \t]*</b>)?[ \t]*:[ \t]+[^\r\n]{1,1000}?[ \t]in[ \t]+' . $path . '~i', $scan, $match)) {
            return ucfirst(strtolower($match[1]));
        }
        // An uncaught exception: the message spans the stack trace and ends with «thrown in … on line N».
        if (preg_match('~(?:\A|[\r\n>])[ \t]*thrown[ \t]+in[ \t]+' . $path . '~i', $scan)) {
            return 'Fatal error';
        }
        return '';
    }

    /**
     * «Date relative aggiornate nel browser» (2.5.0), on the HTML of a verified render. A marker of
     * mark_relative_date() in a visible text run of the body becomes <span data-sb-since data-sb-to>; in a tag, a
     * comment, <title>, <script>, <style>, <textarea> and the other raw text elements only the text stays. Then the
     * final check removes every marker left, in any form. With at least one span the page gets one deferred
     * assets/relative-dates.js. A page without markers comes back byte for byte.
     */
    private function relative_dates_static_html($html)
    {
        if (!is_string($html) || !$this->has_relative_date_markers($html)) {
            return $html;
        }
        $spans = 0;
        $converted = false !== strpos($html, "\xF4\x8F\xBF") ? $this->relative_date_markup($html) : null;
        if (is_array($converted)) {
            list($html, $spans) = $converted;
        }
        // Final check: a marker left (an encoded form, a scan that failed) never reaches a release.
        $html = $this->strip_relative_date_markers($html);
        if ($spans < 1 || false !== strpos($html, 'id="static-bridge-relative-dates"')) {
            return $html;
        }
        $tag = '<script id="static-bridge-relative-dates" src="'
            . esc_url(plugin_dir_url(__FILE__) . 'assets/relative-dates.js?ver=' . self::VERSION)
            . '" defer></script>';
        foreach (array('~</head\s*>~i', '~</body\s*>~i') as $closing) {
            if (preg_match($closing, $html, $match, PREG_OFFSET_CAPTURE)) {
                return substr($html, 0, $match[0][1]) . $tag . substr($html, $match[0][1]);
            }
        }
        return $html . $tag;
    }

    /**
     * The HTML with the markers of the visible text runs turned into spans and every other marker removed, and the
     * number of spans; null when the tag pattern fails (the caller then removes every marker). The same scan as
     * keep_readable_urls(): text runs, comments, tags, raw text elements up to their closing tag.
     */
    private function relative_date_markup($html)
    {
        $length = strlen($html);
        // Text before <body> is not visible text; a document without a <body> tag is all body.
        $in_body = false === stripos($html, '<body');
        $spans = 0;
        $out = '';
        $offset = 0;
        while ($offset < $length) {
            $open = strpos($html, '<', $offset);
            $run_end = false === $open ? $length : $open;
            if ($run_end > $offset) {
                $run = substr($html, $offset, $run_end - $offset);
                $out .= $in_body ? $this->relative_date_text($run, $spans) : $this->strip_relative_date_markers($run);
            }
            if (false === $open) {
                break;
            }
            if (0 === substr_compare($html, '<!--', $open, 4)) {
                $close = strpos($html, '-->', $open + 4);
                $end = false === $close ? $length : $close + 3;
                $out .= $this->strip_relative_date_markers(substr($html, $open, $end - $open));
                $offset = $end;
                continue;
            }
            $found = preg_match('~\G<([A-Za-z][^\s/>]*+)(?:[^>"\']++|"[^"]*+"|\'[^\']*+\')*+>~', $html, $tag, 0, $open);
            if (false === $found) {
                return null;
            }
            if (1 !== $found) {
                if (preg_match('~\G<[/!?]~', $html, $unused, 0, $open)) {
                    $close = strpos($html, '>', $open);
                    $end = false === $close ? $length : $close + 1;
                    $out .= $this->strip_relative_date_markers(substr($html, $open, $end - $open));
                    $offset = $end;
                } else {
                    $out .= '<';
                    $offset = $open + 1;
                }
                continue;
            }
            $name = strtolower($tag[1]);
            $end = $open + strlen($tag[0]);
            // Attributes: the marker goes, the text stays.
            $out .= $this->strip_relative_date_markers($tag[0]);
            $offset = $end;
            if ('body' === $name) {
                $in_body = true;
            }
            if (in_array($name, array('script', 'style', 'title', 'textarea', 'xmp', 'iframe', 'noembed', 'noframes', 'noscript', 'plaintext'), true)) {
                $closing = $this->closing_tag_position($html, $name, $end);
                $closing = false === $closing ? $length : $closing;
                $out .= $this->strip_relative_date_markers(substr($html, $end, $closing - $end));
                $offset = $closing;
            }
        }
        return array($out, $spans);
    }

    /**
     * One visible text run: each well-formed, not nested marker with valid numbers becomes
     * <span data-sb-since="from" data-sb-to="to">text</span> and adds 1 to $spans. A broken marker (no close, a
     * stray close or separator, numbers that are not 1-12 digits) and both markers of a nested pair are removed,
     * and their text stays.
     */
    private function relative_date_text($text, &$spans)
    {
        if (false === strpos($text, "\xF4\x8F\xBF")) {
            return $this->strip_relative_date_markers($text);
        }
        $open = preg_quote(self::RELATIVE_DATE_OPEN, '~');
        $separator = preg_quote(self::RELATIVE_DATE_SEPARATOR, '~');
        $close = preg_quote(self::RELATIVE_DATE_CLOSE, '~');
        $plain = '(?:(?!' . $open . '|' . $separator . '|' . $close . ')[\s\S]){0,64}?';
        $found = preg_match_all(
            '~' . $open . '(?:([0-9]{1,12})' . $separator . '([0-9]{1,12})' . $separator . '|' . $plain . $separator . $plain . $separator . '|[0-9]{0,12})'
            . '|' . $separator . '|' . $close . '~',
            $text,
            $tokens,
            PREG_SET_ORDER | PREG_OFFSET_CAPTURE
        );
        if (!$found) {
            return $this->strip_relative_date_markers($text);
        }
        $edits = array();
        $stack = array();
        foreach ($tokens as $token) {
            $piece = $token[0][0];
            $at = $token[0][1];
            if (0 === strpos($piece, self::RELATIVE_DATE_OPEN)) {
                if (!empty($stack)) {
                    $stack[count($stack) - 1]['nested'] = true;
                }
                $valid = isset($token[2]) && -1 !== $token[1][1] && -1 !== $token[2][1];
                $stack[] = array('at' => $at, 'length' => strlen($piece), 'from' => $valid ? $token[1][0] : null, 'to' => $valid ? $token[2][0] : null, 'nested' => false);
                continue;
            }
            if (self::RELATIVE_DATE_SEPARATOR === $piece) {
                $edits[$at] = array(strlen($piece), '');
                continue;
            }
            $marker = array_pop($stack);
            if (null === $marker) {
                $edits[$at] = array(strlen($piece), '');
            } elseif (null !== $marker['from'] && !$marker['nested'] && empty($stack)) {
                $edits[$marker['at']] = array($marker['length'], '<span data-sb-since="' . (int) $marker['from'] . '" data-sb-to="' . (int) $marker['to'] . '">');
                $edits[$at] = array(strlen($piece), '</span>');
                $spans++;
            } else {
                $edits[$marker['at']] = array($marker['length'], '');
                $edits[$at] = array(strlen($piece), '');
            }
        }
        foreach ($stack as $marker) {
            $edits[$marker['at']] = array($marker['length'], '');
        }
        ksort($edits);
        $out = '';
        $offset = 0;
        foreach ($edits as $at => $edit) {
            $out .= substr($text, $offset, $at - $offset) . $edit[1];
            $offset = $at + $edit[0];
        }
        return $this->strip_relative_date_markers($out . substr($text, $offset));
    }

    /**
     * The regex for one marker character in every form a page can carry it: raw UTF-8, JSON \u escapes (also with
     * the backslash escaped again), numeric character references and percent-encoding (also double). $n is '1'
     * (open), '2' (separator), '3' (close) or '[1-3]' (any); used with the i flag and without u.
     */
    private function relative_date_char_pattern($n)
    {
        $raw = '[1-3]' === $n ? '[\xB1-\xB3]' : '\xB' . $n;
        $decimal = '[1-3]' === $n ? '[7-9]' : (string) (6 + (int) $n);
        return '(?:\xF4\x8F\xBF' . $raw . '|\\\\+udbff\\\\+udff' . $n . '|&#x0*10fff' . $n . ';?|&#0*111409' . $decimal . ';?'
            . '|%(?:25)*F4%(?:25)*8F%(?:25)*BF%(?:25)*B' . $n . ')';
    }

    /** True when the string carries a relative-date marker character in any form of relative_date_char_pattern(). */
    private function has_relative_date_markers($html)
    {
        if (!is_string($html) || '' === $html
            || (false === strpos($html, "\xF4\x8F\xBF") && false === stripos($html, 'udbff') && false === stripos($html, '10fff')
                && false === strpos($html, '111409') && false === stripos($html, '%F4%') && false === stripos($html, '%25F4'))) {
            return false;
        }
        return 1 === preg_match('~' . $this->relative_date_char_pattern('[1-3]') . '~i', $html);
    }

    /**
     * Every relative-date marker removed, in every form: an opening one with the numbers after it, separators and
     * closes; the text stays. Used on every part that is not a visible text run and, before a page is written, on
     * the whole page. If the pattern fails, the plain forms go with str_ireplace().
     */
    private function strip_relative_date_markers($html)
    {
        if (!$this->has_relative_date_markers($html)) {
            return $html;
        }
        $separator = $this->relative_date_char_pattern('2');
        $stripped = preg_replace(
            '~' . $this->relative_date_char_pattern('1') . '[0-9]{0,12}(?:' . $separator . '[0-9]{0,12}' . $separator . ')?|'
                . $separator . '|' . $this->relative_date_char_pattern('3') . '~i',
            '',
            $html
        );
        if (is_string($stripped)) {
            return $stripped;
        }
        $plain = array();
        foreach (array(1, 2, 3) as $n) {
            $plain[] = "\xF4\x8F\xBF" . chr(0xB0 + $n);
            $plain[] = '\udbff\udff' . $n;
            $plain[] = '&#x10fff' . $n . ';';
            $plain[] = '&#111409' . (6 + $n) . ';';
            $plain[] = '%F4%8F%BF%B' . $n;
        }
        return str_ireplace($plain, '', $html);
    }

    /** The whitelisted security headers of a rendered page that a static copy can repeat as they are. */
    private function security_headers_from_response($response)
    {
        $headers = array();
        foreach (self::SECURITY_HEADER_NAMES as $name) {
            $value = wp_remote_retrieve_header($response, strtolower($name));
            if (is_array($value)) {
                // Repeated with different values: which one the browser applies is not ours to choose.
                $value = 1 === count(array_unique(array_map('strval', $value))) ? (string) reset($value) : '';
            }
            $value = trim((string) $value);
            if ($this->valid_security_header($name, $value)) {
                $headers[$name] = $value;
            }
        }
        return $headers;
    }

    private function valid_security_header($name, $value)
    {
        if (!in_array($name, self::SECURITY_HEADER_NAMES, true) || !is_string($value) || '' === $value || strlen($value) > 2048) {
            return false;
        }
        // Printable ASCII only, and nothing the quoted Apache or Nginx value would read as syntax: a
        // backslash escapes, % is an Apache format specifier, $ an Nginx variable. Double quotes (origins in
        // Permissions-Policy) are written escaped by quoted_header_value().
        if (!preg_match('/^[\x21-\x7E][\x20-\x7E]*$/', $value) || preg_match('/[\\\\%$]/', $value)) {
            return false;
        }
        // A nonce is new on every render: frozen in a static copy it would no longer protect anything.
        return !('Content-Security-Policy' === $name && false !== stripos($value, "'nonce-"));
    }

    /** A validated header value inside double quotes, for the Apache and Nginx configuration. */
    private function quoted_header_value($value)
    {
        return '"' . str_replace('"', '\\"', (string) $value) . '"';
    }

    /** The headers the rules repeat: those of the last full export, then the static_bridge_security_headers filter. */
    private function security_headers()
    {
        $stored = get_option(self::SECURITY_HEADERS_OPTION, array());
        $headers = apply_filters('static_bridge_security_headers', is_array($stored) ? $stored : array());
        $valid = array();
        foreach (is_array($headers) ? $headers : array() as $name => $value) {
            foreach (self::SECURITY_HEADER_NAMES as $known) {
                if (is_string($name) && 0 === strcasecmp($name, $known) && is_string($value) && $this->valid_security_header($known, trim($value))) {
                    $valid[$known] = trim($value);
                }
            }
        }
        return $valid;
    }

    /** Stores the headers captured by a full export; true when they changed (the Nginx block then changes too). */
    private function store_security_headers($job)
    {
        if (!isset($job['security_headers']) || !is_array($job['security_headers'])) {
            // A job that saved no page with the 2.2.1 worker (one started before the update): keep the previous headers.
            return false;
        }
        $captured = $job['security_headers'];
        $headers = array();
        foreach ($captured as $name => $value) {
            if (is_string($name) && is_string($value) && $this->valid_security_header($name, $value)) {
                $headers[$name] = $value;
            }
        }
        $previous = get_option(self::SECURITY_HEADERS_OPTION, array());
        if (is_array($previous) && $previous === $headers) {
            return false;
        }
        update_option(self::SECURITY_HEADERS_OPTION, $headers, false);
        return true;
    }

    private function strip_render_bypass_parameters($html, $render_token)
    {
        $html = (string) $html;
        // Query separators as WordPress prints them: raw, &amp; and the numeric
        // entities esc_url() emits (&#038;), e.g. in the comment "cancel reply" link.
        $sep = '(?:&amp;|&#0*38;|&#x0*26;|&)';
        $end = '(?=["\'<>\s#]|$)';
        // A GET form that repeats the query as hidden fields (the WooCommerce ordering form, wc_query_string_form_fields())
        // would send the render parameters from the static page (2.2.13).
        $html = preg_replace('~<input\b[^>]*\bname\s*=\s*(["\']?)static_bridge_(?:bypass|render)\1[\s/>][^>]*>?~i', '', $html);
        if (is_string($render_token) && preg_match('/^[a-f0-9]{48}$/', $render_token)) {
            $token = preg_quote($render_token, '~');
            $html = str_replace('<!--static-bridge-render:' . $render_token . '-->', '', $html);
            $html = preg_replace('~\?static_bridge_bypass=1' . $sep . 'static_bridge_render=' . $token . $end . '~i', '', $html);
            $html = preg_replace('~' . $sep . 'static_bridge_render=' . $token . '(?=' . $sep . '|["\'<>\s#]|$)~i', '', $html);
            $html = preg_replace('~\?static_bridge_render=' . $token . $end . '~i', '', $html);
            $html = preg_replace('~\?static_bridge_render=' . $token . $sep . '~i', '?', $html);
        }
        $html = preg_replace('~\?static_bridge_bypass=1' . $sep . '(?=[^"\'<>\s]*=)~i', '?', $html);
        $html = preg_replace('~' . $sep . 'static_bridge_bypass=1(?=' . $sep . '|["\'<>\s#]|$)~i', '', $html);
        $html = preg_replace('~\?static_bridge_bypass=1' . $end . '~i', '', $html);
        // The current URL percent-encoded inside another URL, once or twice
        // (sharer.php?u=…%3Fstatic_bridge_bypass%3D1%26…, Bricks Post Sharing; 2.2.5).
        foreach (array('%', '%25') as $pct) {
            $html = $this->strip_encoded_render_bypass_parameters($html, $render_token, $pct);
        }
        // Whatever form is left, the token itself never reaches a static page.
        return is_string($render_token) && preg_match('/^[a-f0-9]{48}$/', $render_token) ? str_ireplace($render_token, '', $html) : $html;
    }

    /** The same cleanup for a query percent-encoded once ($pct "%") or twice ($pct "%25"). */
    private function strip_encoded_render_bypass_parameters($html, $render_token, $pct)
    {
        $p = preg_quote($pct, '~');
        $q = $p . '3F';
        $eq = $p . '3D';
        // "&" and its HTML entities, percent-encoded.
        $sep = $p . '26(?:amp' . $p . '3B|' . $p . '23(?:0*38|x0*26)' . $p . '3B)?';
        // The encoded value ends where the encoded query stops: not an unreserved character, and not an escape of
        // this level other than "#" (an escape of a lower level, like %26 after a %2526 query, belongs to the outer URL).
        $end = '(?![A-Za-z0-9._\\~+-]|' . $p . '(?!23))';
        if (is_string($render_token) && preg_match('/^[a-f0-9]{48}$/', $render_token)) {
            $token = preg_quote($render_token, '~');
            $html = preg_replace('~' . $q . 'static_bridge_bypass' . $eq . '1' . $sep . 'static_bridge_render' . $eq . $token . $end . '~i', '', $html);
            $html = preg_replace('~' . $sep . 'static_bridge_render' . $eq . $token . '(?=' . $sep . '|' . $end . ')~i', '', $html);
            $html = preg_replace('~' . $q . 'static_bridge_render' . $eq . $token . $end . '~i', '', $html);
            $html = preg_replace('~(' . $q . ')static_bridge_render' . $eq . $token . $sep . '~i', '$1', $html);
        }
        $html = preg_replace('~(' . $q . ')static_bridge_bypass' . $eq . '1' . $sep . '(?=[A-Za-z0-9._\\~+%-]*?' . $eq . ')~i', '$1', $html);
        $html = preg_replace('~' . $sep . 'static_bridge_bypass' . $eq . '1(?=' . $sep . '|' . $end . ')~i', '', $html);
        return preg_replace('~' . $q . 'static_bridge_bypass' . $eq . '1' . $end . '~i', '', $html);
    }

    private function render_request_headers($url)
    {
        $headers = array(
            'Accept' => 'text/html,application/xml;q=0.9,*/*;q=0.8',
            'Cache-Control' => 'no-cache, no-store, max-age=0',
            'Pragma' => 'no-cache',
        );

        if (!$this->same_site_url($url)) {
            return $headers;
        }

        $parts = wp_parse_url((string) $url);
        $query = array();
        if (is_array($parts) && !empty($parts['query'])) {
            parse_str((string) $parts['query'], $query);
        }
        $token = isset($query['static_bridge_render']) && is_string($query['static_bridge_render'])
            ? strtolower($query['static_bridge_render'])
            : '';
        if (!isset($query['static_bridge_bypass']) || !is_string($query['static_bridge_bypass']) || '1' !== $query['static_bridge_bypass']
            || !preg_match('/^[a-f0-9]{48}$/', $token)) {
            return $headers;
        }

        $transaction = get_option(self::RENDER_BYPASS_OPTION, array());
        $path = isset($parts['path']) ? $this->normalize_route_path((string) $parts['path']) : '';
        if (!is_array($transaction) || empty($transaction['token']) || !is_string($transaction['token'])
            || !hash_equals($transaction['token'], $token)
            || '' === $path || empty($transaction['routes']) || !in_array($path, $transaction['routes'], true)) {
            return $headers;
        }

        // A non-authenticating cookie with WordPress' logged-in prefix makes
        // WordPress-aware caches and Static Bridge rewrite rules select the PHP
        // path. Never reuse the site's actual authentication-cookie name.
        $cookie_name = 'wordpress_logged_in_static_bridge_bypass';
        while (defined('LOGGED_IN_COOKIE') && hash_equals((string) constant('LOGGED_IN_COOKIE'), $cookie_name)) {
            $cookie_name .= '_internal';
        }
        $headers['Cookie'] = $cookie_name . '=' . $token;
        $headers['X-Static-Bridge-Render-Bypass'] = $token;
        return $headers;
    }

    private function remote_get_batch($urls, $timeout, $response_limit = self::MAX_HTTP_RESPONSE_SIZE)
    {
        $urls = array_values(array_unique(array_map('strval', (array) $urls)));
        $timeout = $this->safe_export_request_timeout($timeout);
        $response_limit = max(1024, min(self::MAX_HTTP_RESPONSE_SIZE, (int) $response_limit));
        if (count($urls) < 2 || !$this->export_http_batch_available()) {
            $responses = array();
            foreach ($urls as $url) {
                $responses[$url] = $this->remote_get($url, $timeout, $response_limit, true);
            }
            return $responses;
        }
        $render_origin = '' !== $this->settings()['render_origin'];
        $render_origin_ca = $render_origin ? $this->render_origin_ca_file() : '';
        $origin_applied = array();

        $home_host = strtolower((string) wp_parse_url(home_url('/'), PHP_URL_HOST));
        $local_suffix = (bool) preg_match('/(?:\\.local|\\.test|\\.localhost)$/i', $home_host);
        $http = new WP_Http();
        $requests = array();
        $request_urls = array();
        $request_args = array();
        $request_actual_urls = array();
        $responses = array();

        foreach ($urls as $source_url) {
            $url = $source_url;
            if (!$this->same_site_url($url)) {
                $responses[$source_url] = new WP_Error('static_bridge_unsafe_request', __('Richiesta HTTP bloccata: l’URL non appartiene all’origine WordPress configurata.', 'static-bridge'));
                continue;
            }
            $multi_connect_to = $render_origin ? $this->render_origin_connect_to($url) : '';
            if ($render_origin) {
                $unavailable = $this->render_origin_unavailable_reason($url);
                if ('' === $multi_connect_to || '' !== $unavailable) {
                    $responses[$source_url] = new WP_Error('static_bridge_render_origin_unavailable', '' !== $unavailable ? $unavailable : __('Indirizzo di origine per il rendering non applicabile a questo URL.', 'static-bridge'));
                    continue;
                }
            }

            $defaults = array(
                'method' => 'GET',
                'timeout' => apply_filters('http_request_timeout', 5, $url),
                'redirection' => apply_filters('http_request_redirection_count', 5, $url),
                'httpversion' => apply_filters('http_request_version', '1.0', $url),
                'user-agent' => apply_filters('http_headers_useragent', 'WordPress/' . get_bloginfo('version') . '; ' . get_bloginfo('url'), $url),
                'reject_unsafe_urls' => apply_filters('http_request_reject_unsafe_urls', false, $url),
                'blocking' => true,
                'headers' => array(),
                'cookies' => array(),
                'body' => null,
                'compress' => false,
                'decompress' => true,
                'sslverify' => true,
                'sslcertificates' => ABSPATH . WPINC . '/certificates/ca-bundle.crt',
                'stream' => false,
                'filename' => null,
                'limit_response_size' => null,
            );
            $args = array(
                'timeout' => $timeout,
                'redirection' => 0,
                'limit_response_size' => $response_limit,
                'sslverify' => !$local_suffix,
                'headers' => $this->render_request_headers($url),
                'user-agent' => 'Static-Bridge/' . self::VERSION . '; ' . home_url('/'),
                'reject_unsafe_urls' => true,
            );
            if ('' !== $render_origin_ca) {
                $args['sslcertificates'] = $render_origin_ca;
            }
            $parsed_args = wp_parse_args($args, $defaults);
            $parsed_args = apply_filters('http_request_args', $parsed_args, $url);
            $parsed_args['timeout'] = $this->safe_export_request_timeout(isset($parsed_args['timeout']) ? $parsed_args['timeout'] : $timeout);
            if (!isset($parsed_args['_redirection'])) {
                $parsed_args['_redirection'] = $parsed_args['redirection'];
            }
            $pre = apply_filters('pre_http_request', false, $parsed_args, $url);
            if (false !== $pre) {
                $responses[$source_url] = $pre;
                continue;
            }

            if (!empty($parsed_args['reject_unsafe_urls'])) {
                $url = wp_http_validate_url($url);
            }
            if (function_exists('wp_kses_bad_protocol') && $url) {
                $url = wp_kses_bad_protocol($url, array('http', 'https', 'ssl'));
            }
            $parsed_url = parse_url($url);
            if (empty($url) || empty($parsed_url['scheme'])) {
                $error = new WP_Error('http_request_failed', __('A valid URL was not provided.', 'static-bridge'));
                do_action('http_api_debug', $error, 'response', 'WpOrg\\Requests\\Requests', $parsed_args, $url);
                $responses[$source_url] = $error;
                continue;
            }
            if ($http->block_request($url)) {
                $error = new WP_Error('http_request_not_executed', sprintf(/* translators: %s: URL */ __('User has blocked requests through HTTP to the URL: %s.', 'static-bridge'), $url));
                do_action('http_api_debug', $error, 'response', 'WpOrg\\Requests\\Requests', $parsed_args, $url);
                $responses[$source_url] = $error;
                continue;
            }

            if ($parsed_args['stream']) {
                if (empty($parsed_args['filename'])) {
                    $parsed_args['filename'] = get_temp_dir() . basename($url);
                }
                $parsed_args['blocking'] = true;
                if (!wp_is_writable(dirname($parsed_args['filename']))) {
                    $error = new WP_Error('http_request_failed', __('Destination directory for file streaming does not exist or is not writable.', 'static-bridge'));
                    do_action('http_api_debug', $error, 'response', 'WpOrg\\Requests\\Requests', $parsed_args, $url);
                    $responses[$source_url] = $error;
                    continue;
                }
            }

            $headers = $parsed_args['headers'];
            if (null === $headers) {
                $headers = array();
            } elseif (!is_array($headers)) {
                $processed_headers = WP_Http::processHeaders($headers);
                $headers = $processed_headers['headers'];
            }
            $options = array(
                'timeout' => $parsed_args['timeout'],
                'useragent' => $parsed_args['user-agent'],
                'blocking' => $parsed_args['blocking'],
                'hooks' => new WP_HTTP_Requests_Hooks($url, $parsed_args),
            );
            $options['hooks']->register('requests.before_redirect', array('WP_Http', 'browser_redirect_compatibility'));
            if (function_exists('wp_kses_bad_protocol') && $parsed_args['reject_unsafe_urls']) {
                $options['hooks']->register('requests.before_redirect', array('WP_Http', 'validate_redirects'));
            }
            if ($parsed_args['stream']) {
                $options['filename'] = $parsed_args['filename'];
            }
            if (empty($parsed_args['redirection'])) {
                $options['follow_redirects'] = false;
            } else {
                $options['redirects'] = $parsed_args['redirection'];
            }
            if (isset($parsed_args['limit_response_size'])) {
                $options['max_bytes'] = $parsed_args['limit_response_size'];
            }
            if (!empty($parsed_args['cookies'])) {
                $options['cookies'] = WP_Http::normalize_cookies($parsed_args['cookies']);
            }
            if ('HEAD' !== $parsed_args['method'] && 'GET' !== $parsed_args['method']) {
                $options['data_format'] = 'body';
            }
            if (!$parsed_args['sslverify']) {
                $options['verify'] = false;
                $options['verifyname'] = false;
            } else {
                $options['verify'] = $parsed_args['sslcertificates'];
            }
            $options['verify'] = apply_filters('https_ssl_verify', $options['verify'], $url);

            $proxy = new WP_HTTP_Proxy();
            if ($proxy->is_enabled() && $proxy->send_through_proxy($url)) {
                $options['proxy'] = new WpOrg\Requests\Proxy\Http($proxy->host() . ':' . $proxy->port());
                if ($proxy->use_authentication()) {
                    $options['proxy']->use_authentication = true;
                    $options['proxy']->user = $proxy->username();
                    $options['proxy']->pass = $proxy->password();
                }
            }

            // Requests' Curl multi transport does not run curl.before_send, where
            // it normally applies TLS verification and proxy options. Apply those
            // security-critical settings before each handle joins the multi stack.
            $multi_verification = isset($options['verify']) ? $options['verify'] : true;
            $multi_proxy = isset($options['proxy']) ? $options['proxy'] : false;
            $origin_applied[$source_url] = false;
            $options['hooks']->register('curl.before_multi_add', static function (&$handle) use ($multi_verification, $multi_proxy, $multi_connect_to, $source_url, &$origin_applied) {
                if (false === $multi_verification) {
                    $verify_host_set = curl_setopt($handle, CURLOPT_SSL_VERIFYHOST, 0);
                    $verify_peer_set = curl_setopt($handle, CURLOPT_SSL_VERIFYPEER, 0);
                    if (!$verify_host_set || !$verify_peer_set) {
                        throw new RuntimeException(__('Configurazione TLS della richiesta parallela non riuscita.', 'static-bridge'));
                    }
                } elseif (is_string($multi_verification)) {
                    if (!curl_setopt($handle, CURLOPT_CAINFO, $multi_verification)) {
                        throw new RuntimeException(__('Configurazione del certificato TLS della richiesta parallela non riuscita.', 'static-bridge'));
                    }
                }

                if ($multi_proxy instanceof WpOrg\Requests\Proxy\Http) {
                    $multi_proxy->curl_before_send($handle);
                }
                // Same origin mapping as remote_get(): only the TCP destination changes.
                if ('' !== $multi_connect_to) {
                    if (!curl_setopt($handle, CURLOPT_CONNECT_TO, array($multi_connect_to))) {
                        throw new RuntimeException(__('Configurazione dell’indirizzo di origine della richiesta parallela non riuscita.', 'static-bridge'));
                    }
                    $origin_applied[$source_url] = true;
                }
            });

            // 2.5.0: Basic Auth for the URL actually sent, never in $parsed_args (filters, http_api_debug).
            list($headers, $options) = $this->self_request_auth_options($url, $headers, $options);

            $request_id = count($request_urls);
            $request_urls[$request_id] = $source_url;
            $request_args[$request_id] = $parsed_args;
            $request_actual_urls[$request_id] = $url;
            $requests[$request_id] = array(
                'url' => $url,
                'headers' => $headers,
                'data' => $parsed_args['body'],
                'type' => $parsed_args['method'],
                'options' => $options,
            );
        }

        if (empty($requests)) {
            return $responses;
        }

        mbstring_binary_safe_encoding();
        $request_responses = array();
        $request_exception = null;
        try {
            $request_responses = WpOrg\Requests\Requests::request_multiple(
                $requests,
                array('transport' => 'WpOrg\\Requests\\Transport\\Curl')
            );
        } catch (\Throwable $exception) {
            $request_exception = $exception;
        } finally {
            reset_mbstring_encoding();
        }

        foreach ($request_urls as $request_id => $source_url) {
            if ($request_exception) {
                $response = new WP_Error('http_request_failed', $request_exception->getMessage());
            } else {
                $request_response = isset($request_responses[$request_id]) ? $request_responses[$request_id] : null;
                if ($request_response instanceof WpOrg\Requests\Exception) {
                    $response = new WP_Error('http_request_failed', $request_response->getMessage());
                } elseif ($request_response instanceof WpOrg\Requests\Response) {
                    $filename = isset($request_args[$request_id]['filename']) ? $request_args[$request_id]['filename'] : null;
                    $http_response = new WP_HTTP_Requests_Response($request_response, $filename);
                    $response = $http_response->to_array();
                    $response['http_response'] = $http_response;
                } else {
                    $response = new WP_Error('http_request_failed', __('La richiesta HTTP parallela non ha prodotto una risposta valida.', 'static-bridge'));
                }
            }
            if ($render_origin && !is_wp_error($response) && empty($origin_applied[$source_url])) {
                $response = new WP_Error('static_bridge_render_origin_unapplied', __('La richiesta parallela non ha applicato l’indirizzo di origine; la risposta è stata scartata.', 'static-bridge'));
            }
            $responses[$source_url] = $response;
            if (empty($request_args[$request_id]['blocking'])) {
                $responses[$source_url] = array(
                    'headers' => array(),
                    'body' => '',
                    'response' => array('code' => false, 'message' => false),
                    'cookies' => array(),
                    'http_response' => null,
                );
            }
            $response_args = isset($request_args[$request_id]) ? $request_args[$request_id] : array();
            $debug_url = isset($request_actual_urls[$request_id]) ? $request_actual_urls[$request_id] : $source_url;
            do_action('http_api_debug', $response, 'response', 'WpOrg\\Requests\\Requests', $response_args, $debug_url);
        }

        return $responses;
    }

    private function is_skippable_export_http_error($error)
    {
        if (!is_wp_error($error) || 'static_bridge_http' !== $error->get_error_code()) {
            return false;
        }
        $status = $error->get_error_data();
        if (is_numeric($status)) {
            return in_array((int) $status, array(401, 403, 404, 410), true);
        }
        return (bool) preg_match('/\b404\b/', $error->get_error_message());
    }

    /**
     * Errors of the render machinery, not of a page: they come before any request (lock, recovery of an earlier
     * bypass, token, current release, the suspended files) or from restoring the bypass, and hit every URL of a batch.
     */
    private function is_render_machinery_error($error)
    {
        return is_wp_error($error) && in_array($error->get_error_code(), array(
            'static_bridge_render_busy', 'static_bridge_render_recovery', 'static_bridge_render_transaction',
            'static_bridge_render_bypass_transaction', 'static_bridge_render_token', 'static_bridge_render_release',
            'static_bridge_render_lock', 'static_bridge_render_storage', 'static_bridge_render_marker',
            'static_bridge_render_backup', 'static_bridge_render_suspend', 'static_bridge_render_file',
        ), true);
    }

    private function is_retryable_export_error($error)
    {
        if (!is_wp_error($error)) {
            return false;
        }
        if (in_array($error->get_error_code(), array('static_bridge_render_unverified', 'static_bridge_render_busy', 'static_bridge_cdn_challenge', 'static_bridge_render_origin_unapplied'), true)) {
            return true;
        }
        if ('http_request_failed' === $error->get_error_code()) {
            return true;
        }
        if ('static_bridge_http' !== $error->get_error_code()) {
            return false;
        }
        $status = $error->get_error_data();
        return is_numeric($status) && in_array((int) $status, array(408, 429, 500, 502, 503, 504), true);
    }

    /** HTTP 429 (Too Many Requests) or 503: the server or a CDN in front of it asks to slow down. */
    private function is_rate_limited_export_error($error)
    {
        return is_wp_error($error) && 'static_bridge_http' === $error->get_error_code()
            && is_numeric($error->get_error_data()) && in_array((int) $error->get_error_data(), array(429, 503), true);
    }

    /** Retry-After in seconds (delta-seconds or HTTP-date), 0 when absent or unusable, at most MAX_RATE_LIMIT_WAIT. */
    private function retry_after_seconds($value)
    {
        if (is_array($value)) {
            $value = 1 === count($value) ? reset($value) : '';
        }
        $value = trim((string) $value);
        if ('' === $value || strlen($value) > 64) {
            return 0;
        }
        if (preg_match('/\A[0-9]{1,9}\z/', $value)) {
            return min(self::MAX_RATE_LIMIT_WAIT, (int) $value);
        }
        // An HTTP-date starts with the day name (RFC 9110); strtotime() alone would take '-5' as a time zone.
        $at = preg_match('/\A[A-Za-z]{3}/', $value) ? strtotime($value) : false;
        return false === $at ? 0 : max(0, min(self::MAX_RATE_LIMIT_WAIT, $at - time()));
    }

    /** Wait before retry $attempt (1, 2…) of a rate-limited URL: Retry-After, but at least 10 s doubling each time. */
    private function rate_limit_wait($attempt, $retry_after)
    {
        $backoff = 10 * (2 ** max(0, min(5, (int) $attempt - 1)));
        return max(1, min(self::MAX_RATE_LIMIT_WAIT, max((int) $retry_after, $backoff)));
    }

    /** «Rallenta l'export se il server è lento» (2.5.0): seconds a render may take, filter from 1 to 60 (3). */
    private function export_slow_render_seconds()
    {
        return max(1, min(60, (int) apply_filters('static_bridge_export_slow_render_seconds', 3)));
    }

    /**
     * After every block of renders of the export, with the option on. Slower than the threshold: one level up (at
     * most EXPORT_BRAKE_MAX_LEVEL). EXPORT_BRAKE_CALM blocks in a row within it: one level down. At level N the step
     * takes at most batch_size / 2^N URLs (never fewer than one), one at a time, and waits N seconds after each
     * render. Attività says when the brake starts and when the export is back to normal, not at every level.
     */
    private function update_export_load_brake(&$job, $seconds)
    {
        $threshold = $this->export_slow_render_seconds();
        $before = max(0, min(self::EXPORT_BRAKE_MAX_LEVEL, (int) ($job['load_brake'] ?? 0)));
        $level = $before;
        if ($seconds > $threshold) {
            $level = min(self::EXPORT_BRAKE_MAX_LEVEL, $level + 1);
            $job['load_brake_calm'] = 0;
        } elseif ($level > 0) {
            $calm = max(0, (int) ($job['load_brake_calm'] ?? 0)) + 1;
            if ($calm >= self::EXPORT_BRAKE_CALM) {
                $level--;
                $calm = 0;
            }
            $job['load_brake_calm'] = $calm;
        }
        if ($level > 0) {
            $job['load_brake'] = $level;
            $job['load_brake_resume_at'] = microtime(true) + $level;
        } else {
            unset($job['load_brake'], $job['load_brake_calm'], $job['load_brake_resume_at']);
        }
        if (0 === $before && $level > 0) {
            $this->log_activity(
                __('Export rallentato: il server risponde lentamente.', 'static-bridge'),
                sprintf(/* translators: 1: seconds taken, 2: threshold in seconds */ __('WP ha impiegato %1$s secondi a rendere una pagina (soglia: %2$s). L’export fa meno pagine per passo, una alla volta, con una pausa dopo ognuna, finché le risposte tornano entro la soglia.', 'static-bridge'), number_format_i18n((float) $seconds, 1), number_format_i18n($threshold)),
                true
            );
        } elseif ($before > 0 && 0 === $level) {
            $this->log_activity(
                __('Export di nuovo a velocità normale.', 'static-bridge'),
                sprintf(/* translators: 1: number of answers, 2: threshold in seconds */ __('%1$s risposte di fila entro la soglia di %2$s secondi.', 'static-bridge'), number_format_i18n(self::EXPORT_BRAKE_CALM), number_format_i18n($threshold))
            );
        }
    }

    /**
     * 2.5.0: the Basic Auth of the web server in front of this site (a staging protected by AuthType Basic or
     * auth_basic), from the constants STATIC_BRIDGE_BASIC_AUTH_USER and STATIC_BRIDGE_BASIC_AUTH_PASSWORD of
     * wp-config.php only: never an option, a setting or a form. array('state' => 'off'|'invalid'|'on'), with 'user'
     * and 'password' only when 'on'. Read once per request.
     */
    private function basic_auth_credentials()
    {
        if (!is_array($this->basic_auth)) {
            $this->basic_auth = $this->basic_auth_from(
                defined('STATIC_BRIDGE_BASIC_AUTH_USER') ? constant('STATIC_BRIDGE_BASIC_AUTH_USER') : null,
                defined('STATIC_BRIDGE_BASIC_AUTH_PASSWORD') ? constant('STATIC_BRIDGE_BASIC_AUTH_PASSWORD') : null
            );
        }
        return $this->basic_auth;
    }

    /**
     * The state of the two constants (null: not defined). Both missing: 'off'. Only one, a value that is not a
     * string, an empty user name, a user name with ':' (RFC 7617 splits at the first colon) or a control character,
     * a password with a control character (CR, LF, NUL, DEL…, which would break or split the header): 'invalid', and
     * no header is ever sent. The password may be empty and may contain ':'.
     */
    private function basic_auth_from($user, #[\SensitiveParameter] $password)
    {
        if (null === $user && null === $password) {
            return array('state' => 'off');
        }
        if (!is_string($user) || !is_string($password) || '' === $user
            || false !== strpos($user, ':') || preg_match('/[\x00-\x1F\x7F]/', $user . $password)) {
            return array('state' => 'invalid');
        }
        return array('state' => 'on', 'user' => $user, 'password' => $password);
    }

    /** 'on', 'off' or 'invalid': what the Diagnostica and `wp static-bridge status` may say, never a value. */
    private function basic_auth_state()
    {
        return $this->basic_auth_credentials()['state'];
    }

    /**
     * The only place that builds the Basic Auth header: array('Authorization' => 'Basic …') for a URL of this site
     * (same scheme, host and port as home_url(), same_site_url()) when the constants are valid, array() for every
     * other URL (Cloudflare, the release updater, another host, scheme or port, a URL with user:pass@) and when the
     * constants are missing or invalid. The callers send it only with redirection 0: self_request(),
     * self_request_follow(), and remote_get_batch() through self_request_auth_options().
     */
    private function self_request_auth_headers($url)
    {
        $credentials = $this->basic_auth_credentials();
        if ('on' !== $credentials['state'] || !$this->same_site_url((string) $url)) {
            return array();
        }
        return array('Authorization' => 'Basic ' . base64_encode($credentials['user'] . ':' . $credentials['password']));
    }

    /**
     * cron_request (2.5.0): spawn_cron() starts WP-Cron with a loopback to wp-cron.php that, behind Basic Auth,
     * would get 401, so incremental updates, the scheduled export and the link check would wait for a system cron.
     * The header goes only to a URL of this site (self_request_auth_headers()), and with it the loopback never
     * follows a redirect. Without valid constants, or for a URL another plugin moved elsewhere, nothing changes.
     */
    public function add_basic_auth_to_cron_request($cron_request)
    {
        if (!is_array($cron_request) || !isset($cron_request['url']) || !is_string($cron_request['url'])) {
            return $cron_request;
        }
        $auth = $this->self_request_auth_headers($cron_request['url']);
        if (empty($auth)) {
            return $cron_request;
        }
        $args = isset($cron_request['args']) && is_array($cron_request['args']) ? $cron_request['args'] : array();
        $args['headers'] = array_merge(isset($args['headers']) && is_array($args['headers']) ? $args['headers'] : array(), $auth);
        $args['redirection'] = 0;
        $cron_request['args'] = $args;
        return $cron_request;
    }

    /**
     * A request of the plugin to this site through WordPress' safe HTTP API, with the Basic Auth header when
     * self_request_auth_headers() gives one ($basic_auth false: never, for the Diagnostica's request without it).
     * With the header the request never follows a redirect: redirection is 0 in the arguments and, while it runs, a
     * last http_request_args filter puts it back to 0 for this URL, should another plugin's filter raise it.
     */
    private function self_request($method, $url, array $args, $basic_auth = true)
    {
        $auth = $basic_auth ? $this->self_request_auth_headers($url) : array();
        $send = static function () use ($method, $url, &$args) {
            return 'POST' === $method ? wp_safe_remote_post($url, $args) : wp_safe_remote_get($url, $args);
        };
        if (empty($auth)) {
            return $send();
        }
        $args['headers'] = array_merge(isset($args['headers']) && is_array($args['headers']) ? $args['headers'] : array(), $auth);
        $args['redirection'] = 0;
        $no_redirects = static function ($parsed_args, $request_url = '') use ($url) {
            if (is_array($parsed_args) && (string) $request_url === (string) $url) {
                $parsed_args['redirection'] = 0;
            }
            return $parsed_args;
        };
        add_filter('http_request_args', $no_redirects, PHP_INT_MAX, 2);
        try {
            return $send();
        } finally {
            remove_filter('http_request_args', $no_redirects, PHP_INT_MAX);
        }
    }

    /**
     * For the requests that follow redirects as a browser does (the Server tab's checks, the test of the .htaccess
     * block): up to $args['redirection'] of them. Without the Basic Auth header WordPress follows them, as before.
     * With it the client never follows: each Location is followed here, only while it stays on this site, as a new
     * self_request() that decides on the header again; a redirect to another host is the answer.
     */
    private function self_request_follow($url, array $args)
    {
        if (empty($this->self_request_auth_headers($url))) {
            return wp_safe_remote_get($url, $args);
        }
        $redirects = max(0, (int) ($args['redirection'] ?? 0));
        $args['redirection'] = 0;
        for ($hop = 0; ; $hop++) {
            $response = $this->self_request('GET', $url, $args);
            if (is_wp_error($response) || $hop >= $redirects) {
                return $response;
            }
            $status = (int) wp_remote_retrieve_response_code($response);
            $location = wp_remote_retrieve_header($response, 'location');
            $location = is_array($location) ? (string) reset($location) : (string) $location;
            if ($status < 300 || $status > 399 || '' === trim($location)) {
                return $response;
            }
            $next = $this->absolute_url(trim($location), $url);
            if ('' === $next || !$this->same_site_url($next)) {
                return $response;
            }
            $url = $next;
        }
    }

    /**
     * remote_get_batch(): the Requests multi transport does not go through self_request(). The header joins the
     * headers of the handle for the URL actually sent, after WordPress' filters, and turns following redirects off.
     *
     * @return array{0: array, 1: array} headers and options
     */
    private function self_request_auth_options($url, array $headers, array $options)
    {
        $auth = $this->self_request_auth_headers($url);
        if (!empty($auth)) {
            $headers = array_merge($headers, $auth);
            $options['follow_redirects'] = false;
            unset($options['redirects']);
        }
        return array($headers, $options);
    }

    /**
     * $via_render_origin: internal requests (rendering, origin routing
     * probe) connect to the configured origin address instead of public DNS. Diagnostics
     * that describe what visitors receive keep the public path.
     */
    private function remote_get($url, $timeout, $response_limit = self::MAX_HTTP_RESPONSE_SIZE, $via_render_origin = false, $request = array())
    {
        if (!$this->same_site_url($url)) {
            return new WP_Error('static_bridge_unsafe_request', __('Richiesta HTTP bloccata: l’URL non appartiene all’origine WordPress configurata.', 'static-bridge'));
        }
        $timeout = $this->safe_export_request_timeout($timeout);
        $home_host = strtolower((string) wp_parse_url(home_url('/'), PHP_URL_HOST));
        $local_suffix = (bool) preg_match('/(?:\.local|\.test|\.localhost)$/i', $home_host);
        $response_limit = max(1024, min(self::MAX_HTTP_RESPONSE_SIZE, (int) $response_limit));
        $args = array(
            'timeout' => $timeout,
            // Never follow redirects in the HTTP client. The page exporter inspects a
            // Location response separately and queues only normalized public same-origin URLs.
            'redirection' => 0,
            'limit_response_size' => $response_limit,
            'sslverify' => !$local_suffix,
            'headers' => $this->render_request_headers($url),
            'user-agent' => 'Static-Bridge/' . self::VERSION . '; ' . home_url('/'),
        );
        // Diagnostic probes only: extra headers (a synthetic cookie), an empty POST or (2.5.0) another user agent.
        if (!empty($request['headers']) && is_array($request['headers'])) {
            $args['headers'] = array_merge($args['headers'], $request['headers']);
        }
        if (isset($request['user-agent']) && is_string($request['user-agent']) && preg_match('/\A[\x20-\x7E]{1,300}\z/', $request['user-agent'])) {
            $args['user-agent'] = $request['user-agent'];
        }
        $is_post = isset($request['method']) && 'POST' === $request['method'];
        if ($is_post) {
            $args['body'] = '';
        }
        // 2.5.0: the Basic Auth header comes from self_request(); only the Diagnostica asks once without it.
        $basic_auth = !array_key_exists('basic_auth', (array) $request) || false !== $request['basic_auth'];
        $send = function () use ($url, &$args, $is_post, $basic_auth) {
            return $this->self_request($is_post ? 'POST' : 'GET', $url, $args, $basic_auth);
        };
        if (!$via_render_origin || '' === $this->settings()['render_origin']) {
            return $send();
        }

        $connect_to = $this->render_origin_connect_to($url);
        $unavailable = $this->render_origin_unavailable_reason($url);
        if ('' === $connect_to || '' !== $unavailable) {
            return new WP_Error('static_bridge_render_origin_unavailable', '' !== $unavailable ? $unavailable : __('Indirizzo di origine per il rendering non applicabile a questo URL.', 'static-bridge'));
        }
        $ca_file = $this->render_origin_ca_file();
        if ('' !== $ca_file) {
            $args['sslcertificates'] = $ca_file;
        }
        // cURL's CONNECT_TO only replaces the TCP destination of a matching host:port:
        // the URL, Host header, TLS SNI and certificate verification stay the site's.
        // The action exists only for this call: a permanent http_api_curl hook would
        // also disable the parallel transport (export_http_batch_available()).
        $applied = false;
        $apply = function (&$handle, $parsed_args = array(), $request_url = '') use ($connect_to, &$applied) {
            if ($this->same_site_url((string) $request_url) && curl_setopt($handle, CURLOPT_CONNECT_TO, array($connect_to))) {
                $applied = true;
            }
        };
        add_action('http_api_curl', $apply, 10, 3);
        try {
            $response = $send();
        } finally {
            remove_action('http_api_curl', $apply, 10);
        }
        if (!$applied) {
            // The request did not go through WordPress' cURL transport (another transport
            // or a pre_http_request filter): its response may come from the public edge.
            return new WP_Error('static_bridge_render_origin_unapplied', __('La richiesta interna non è passata dal trasporto cURL di WordPress, quindi l’indirizzo di origine non è stato applicato; la risposta è stata scartata.', 'static-bridge'));
        }
        return $response;
    }

    /** Literal IPv4 or bracketed IPv6 address with an optional port; '' disables the option. */
    private function sanitize_render_origin($value)
    {
        $invalid = new WP_Error('static_bridge_render_origin_invalid', __('Usa un indirizzo IP letterale con porta facoltativa, ad esempio 127.0.0.1, 203.0.113.10:8443 o [2001:db8::1]:443. Nomi host, URL e indirizzi non instradabili non sono ammessi.', 'static-bridge'));
        if (!is_string($value)) {
            return $invalid;
        }
        $value = trim($value);
        if ('' === $value) {
            return '';
        }
        $octet = '(?:25[0-5]|2[0-4][0-9]|1[0-9][0-9]|[1-9]?[0-9])';
        if (preg_match('/^(' . $octet . '(?:\.' . $octet . '){3})(?::([0-9]{1,5}))?$/D', $value, $match)) {
            $address = $match[1];
            $port = isset($match[2]) ? $match[2] : '';
            $packed = inet_pton($address);
        } elseif (preg_match('/^\[([0-9a-fA-F:]{2,39})\](?::([0-9]{1,5}))?$/D', $value, $match)
            && false !== filter_var($match[1], FILTER_VALIDATE_IP, FILTER_FLAG_IPV6)) {
            $packed = inet_pton($match[1]);
            $address = '[' . inet_ntop($packed) . ']';
            $port = isset($match[2]) ? $match[2] : '';
        } else {
            return $invalid;
        }
        if (false === $packed || '' === (string) $packed) {
            return $invalid;
        }
        if ('' !== $port && ((int) $port < 1 || (int) $port > 65535 || (string) (int) $port !== $port)) {
            return $invalid;
        }
        $first = ord($packed[0]);
        if (4 === strlen($packed)) {
            // 0.0.0.0/8, link-local 169.254/16 (cloud metadata), multicast and reserved/broadcast.
            if (0 === $first || $first >= 224 || (169 === $first && 254 === ord($packed[1]))) {
                return $invalid;
            }
        } else {
            $unspecified = str_repeat("\0", 16) === $packed;
            $link_local = 0xfe === $first && 0x80 === (ord($packed[1]) & 0xc0);
            $multicast = 0xff === $first;
            $mapped = str_repeat("\0", 10) . "\xff\xff" === substr($packed, 0, 12);
            if ($unspecified || $link_local || $multicast || $mapped) {
                return $invalid;
            }
        }
        return $address . ('' !== $port ? ':' . (int) $port : '');
    }

    /** "host:port:origin-address:origin-port" for CURLOPT_CONNECT_TO, or '' when not applicable. */
    private function render_origin_connect_to($url)
    {
        $origin = $this->settings()['render_origin'];
        if ('' === $origin || !$this->same_site_url($url)) {
            return '';
        }
        $parts = wp_parse_url((string) $url);
        $scheme = strtolower((string) $parts['scheme']);
        $port = isset($parts['port']) ? (int) $parts['port'] : ('https' === $scheme ? 443 : 80);
        $host = rtrim(strtolower((string) $parts['host']), '.');
        // $origin is already normalized: "a.b.c.d[:port]" or "[v6][:port]".
        $separator = '[' === $origin[0] ? strpos($origin, ']') + 1 : strpos($origin, ':');
        if (false === $separator || $separator >= strlen($origin)) {
            $address = $origin;
            $origin_port = 0;
        } else {
            $address = substr($origin, 0, $separator);
            $origin_port = (int) substr($origin, $separator + 1);
        }
        return $host . ':' . $port . ':' . $address . ':' . ($origin_port > 0 ? $origin_port : $port);
    }

    /** Why the origin address cannot be applied safely to this URL ('' when it can). */
    private function render_origin_unavailable_reason($url)
    {
        if (!function_exists('curl_init') || !function_exists('curl_setopt') || !defined('CURLOPT_CONNECT_TO')) {
            return __('L’indirizzo di origine richiede l’estensione PHP cURL con supporto CURLOPT_CONNECT_TO; il rendering non è stato eseguito per non passare dal DNS pubblico.', 'static-bridge');
        }
        if ('https' === strtolower((string) wp_parse_url((string) $url, PHP_URL_SCHEME)) && function_exists('curl_version')) {
            $version = curl_version();
            if (is_array($version) && isset($version['features']) && defined('CURL_VERSION_SSL') && !($version['features'] & CURL_VERSION_SSL)) {
                return __('cURL non supporta HTTPS su questo server: l’indirizzo di origine non può essere usato.', 'static-bridge');
            }
        }
        if (class_exists('WP_HTTP_Proxy')) {
            $proxy = new WP_HTTP_Proxy();
            if ($proxy->is_enabled() && $proxy->send_through_proxy($url)) {
                return __('Le richieste di WordPress passano da un proxy (WP_PROXY_HOST): l’indirizzo di origine non può essere applicato in modo verificabile.', 'static-bridge');
            }
        }
        return '';
    }

    /** Optional CA bundle for the origin certificate (e.g. Cloudflare Origin CA), from wp-config.php. */
    private function render_origin_ca_file()
    {
        if (!defined('STATIC_BRIDGE_RENDER_ORIGIN_CA')) {
            return '';
        }
        $file = constant('STATIC_BRIDGE_RENDER_ORIGIN_CA');
        if (!is_string($file) || '' === $file || is_link($file) || !is_file($file) || !is_readable($file)) {
            return '';
        }
        $real = realpath($file);
        return is_string($real) ? $real : '';
    }

    /**
     * Same-site links of a page: <a href> and the <link rel="next|prev"> of paginated lists. The DOM and
     * the regex branch (PHP without ext-dom) find the same links, so a release does not depend on the build.
     */
    private function extract_internal_links($html, $base_url, $force_regex = false)
    {
        $urls = array();
        foreach ($this->html_link_hrefs($html, $force_regex) as $href) {
            $absolute = $this->link_href_url($href, $base_url);
            if ('' === $absolute) {
                continue;
            }
            $normalized = $this->normalize_public_url($absolute);
            if ($normalized && !isset($urls[$normalized])) {
                $urls[$normalized] = true;
            }
        }
        return array_keys($urls);
    }

    /**
     * The href of the links of a page, as written: every <a href> and, for the export crawl, every <link href> whose
     * rel says next or prev; for the link check after a publication (2.5.0, $areas) every <area href> instead of the
     * <link> ones, since a visitor follows those. DOMDocument when there is ext-dom, the same links with a regular
     * expression otherwise.
     *
     * @return string[]
     */
    private function html_link_hrefs($html, $force_regex = false, $areas = false)
    {
        $hrefs = array();
        if (class_exists('DOMDocument') && !$force_regex) {
            $previous = libxml_use_internal_errors(true);
            $dom = new DOMDocument();
            $loaded = $dom->loadHTML('<?xml encoding="utf-8" ?>' . $html, LIBXML_NONET | LIBXML_NOWARNING | LIBXML_NOERROR);
            libxml_clear_errors();
            libxml_use_internal_errors($previous);
            if ($loaded) {
                foreach ($dom->getElementsByTagName('a') as $anchor) {
                    if ($anchor->hasAttribute('href')) {
                        $hrefs[] = $anchor->getAttribute('href');
                    }
                }
                if ($areas) {
                    foreach ($dom->getElementsByTagName('area') as $area) {
                        if ($area->hasAttribute('href')) {
                            $hrefs[] = $area->getAttribute('href');
                        }
                    }
                } else {
                    foreach ($dom->getElementsByTagName('link') as $link) {
                        if ($link->hasAttribute('href') && preg_match('~(?:^|\s)(?:next|prev)(?:\s|$)~i', $link->getAttribute('rel'))) {
                            $hrefs[] = $link->getAttribute('href');
                        }
                    }
                }
            }
        } elseif (preg_match_all('~<(a|link|area)\s[^>]*>~is', $html, $tags, PREG_SET_ORDER)) {
            foreach ($tags as $tag) {
                $attributes = array();
                if (preg_match_all('~(?<![\w-])(href|rel)\s*=\s*(?:"([^"]*)"|\'([^\']*)\'|([^\s"\'>]+))~i', $tag[0], $pairs, PREG_SET_ORDER)) {
                    foreach ($pairs as $pair) {
                        $name = strtolower($pair[1]);
                        if (!isset($attributes[$name])) {
                            $attributes[$name] = isset($pair[4]) ? $pair[4] : (isset($pair[3]) && '' !== $pair[3] ? $pair[3] : $pair[2]);
                        }
                    }
                }
                if (!isset($attributes['href'])) {
                    continue;
                }
                $tag_name = strtolower($tag[1]);
                if ('a' === $tag_name || ('area' === $tag_name && $areas)
                    || ('link' === $tag_name && !$areas && preg_match('~(?:^|\s)(?:next|prev)(?:\s|$)~i', isset($attributes['rel']) ? $attributes['rel'] : ''))) {
                    $hrefs[] = $attributes['href'];
                }
            }
        }
        return $hrefs;
    }

    /**
     * The absolute URL an href of a page leads to, without its fragment (/category/x/#content is /category/x/), or ''
     * for an empty href, a fragment alone, mailto:, tel:, javascript:, data: and JSON. The origin is not checked here.
     */
    private function link_href_url($href, $base_url)
    {
        $href = trim(html_entity_decode((string) $href, ENT_QUOTES | ENT_HTML5, 'UTF-8'));
        $fragment = strpos($href, '#');
        if (false !== $fragment && 0 !== $fragment) {
            $href = substr($href, 0, $fragment);
        }
        if ('' === $href || 0 === strpos($href, '#') || preg_match('~^(?:mailto|tel|javascript|data):~i', $href)) {
            return '';
        }
        if (preg_match('~^\s*\{.*\}\s*$~s', $href)) {
            return '';
        }
        $absolute = $this->absolute_url($href, $base_url);
        return $absolute ? (string) $absolute : '';
    }

    private function absolute_url($href, $base_url)
    {
        $parts = wp_parse_url($href);
        if (!$parts) {
            return '';
        }
        if (!empty($parts['host'])) {
            return $href;
        }
        if (0 === strpos($href, '//')) {
            $scheme = wp_parse_url($base_url, PHP_URL_SCHEME);
            return ($scheme ? $scheme : (is_ssl() ? 'https' : 'http')) . ':' . $href;
        }
        if (0 === strpos($href, '/')) {
            return home_url($href);
        }
        $base_path = (string) wp_parse_url($base_url, PHP_URL_PATH);
        $directory = '/' === substr($base_path, -1) ? $base_path : dirname($base_path);
        $resolved_path = trailingslashit('/' === $directory ? '' : $directory) . (isset($parts['path']) ? $parts['path'] : '');
        $absolute = home_url('/' . ltrim($resolved_path, '/'));
        if (isset($parts['query'])) {
            $absolute .= '?' . $parts['query'];
        }
        if (isset($parts['fragment'])) {
            $absolute .= '#' . $parts['fragment'];
        }
        return $absolute;
    }

    private function normalize_public_url($url)
    {
        if (!$this->same_site_url($url)) {
            return '';
        }
        $parts = wp_parse_url($url);
        if (!$parts || !empty($parts['query']) || !empty($parts['fragment'])) {
            return '';
        }
        $path = isset($parts['path']) ? rawurldecode($parts['path']) : '/';
        if (false !== strpos($path, "\0") || preg_match('~(^|/)\.\.?(/|$)~', $path)) {
            return '';
        }
        // A route ends like the permalink structure (user_trailingslashit): with or without the slash,
        // and with .html when the structure does; any other extension is a file, not a route.
        $html_routes = $this->routes_end_in_html();
        if ('/' !== $path && preg_match('~\.[a-z0-9]{1,8}$~i', $path) && !($html_routes && preg_match('~[^/]\.html$~', $path))) {
            return '';
        }
        if ('/' !== $path) {
            $path = $this->routes_require_trailing_slash() ? trailingslashit($path) : untrailingslashit($path);
        }
        $candidate = home_url($path);
        if ($this->is_excluded_path($path)) {
            return '';
        }
        return $candidate;
    }

    private function normalize_redirect_target($url)
    {
        $parts = wp_parse_url((string) $url);
        if (!is_array($parts) || !$this->same_site_url($url) || isset($parts['fragment'])) {
            return '';
        }

        if (isset($parts['query'])) {
            $query = array();
            parse_str((string) $parts['query'], $query);
            $valid_bypass = isset($query['static_bridge_bypass']) && '1' === (string) $query['static_bridge_bypass'];
            $valid_keys = array('static_bridge_bypass');
            if (isset($query['static_bridge_render'])) {
                $valid_keys[] = 'static_bridge_render';
                $valid_bypass = $valid_bypass && is_string($query['static_bridge_render'])
                    && (bool) preg_match('/^[a-f0-9]{48}$/', $query['static_bridge_render']);
            }
            $query_keys = array_keys($query);
            sort($query_keys);
            sort($valid_keys);
            if (!$valid_bypass || $query_keys !== $valid_keys) {
                return '';
            }
            $query_position = strrpos((string) $url, '?');
            if (false === $query_position) {
                return '';
            }
            $url = substr((string) $url, 0, $query_position);
        }

        return $this->normalize_public_url($url);
    }

    private function same_site_url($url)
    {
        $candidate = wp_parse_url((string) $url);
        $home = wp_parse_url(home_url('/'));
        if (!is_array($candidate) || !is_array($home) || empty($candidate['host']) || empty($home['host'])) {
            return false;
        }
        if (isset($candidate['user']) || isset($candidate['pass'])) {
            return false;
        }

        $candidate_scheme = isset($candidate['scheme']) ? strtolower($candidate['scheme']) : '';
        $home_scheme = isset($home['scheme']) ? strtolower($home['scheme']) : '';
        if (!in_array($candidate_scheme, array('http', 'https'), true) || $candidate_scheme !== $home_scheme) {
            return false;
        }

        $candidate_host = rtrim(strtolower($candidate['host']), '.');
        $home_host = rtrim(strtolower($home['host']), '.');
        $default_port = 'https' === $home_scheme ? 443 : 80;
        $candidate_port = isset($candidate['port']) ? (int) $candidate['port'] : $default_port;
        $home_port = isset($home['port']) ? (int) $home['port'] : $default_port;

        return '' !== $candidate_host && $candidate_host === $home_host && $candidate_port === $home_port;
    }

    private function is_excluded_path($path)
    {
        $path = '/' . ltrim($path, '/');
        $built_in = array(
            '~^/(?:wp-admin|wp-content|wp-includes|wp-json)(?:/|$)~i',
            '~^/(?:wp-login|wp-cron|wp-comments-post|wp-signup|wp-activate|wp-mail|wp-trackback|xmlrpc)\.php(?:/|$)~i',
            '~^/wp-[^/]+(?:/|$)~i',
            '~(?:^|/)(?:feed|comments/feed)(?:/|$)~i',
            // Feeds in short form: /rss2/, /atom/, /category/x/rdf/.
            '~^/(?:.+/)?(?:rss|rss2|atom|rdf)/?$~i',
            '~^/' . preg_quote($this->search_base(), '~') . '(?:/|$)~i',
            '~^/(?:[^/]*sitemap[^/]*\.(?:xml|xsl)|robots\.txt)$~i',
            // Cloudflare's own endpoints (email protection, challenges): answered at the edge, 404 at the origin.
            '~^/cdn-cgi(?:/|$)~i',
        );
        foreach ($built_in as $pattern) {
            if (preg_match($pattern, $path)) {
                return true;
            }
        }
        foreach ($this->settings()['excluded_paths'] as $excluded) {
            $excluded = $this->normalize_route_path($excluded);
            if ('/' === $excluded) {
                if ('/' === trailingslashit($path)) {
                    return true;
                }
                continue;
            }
            if (0 === strpos(trailingslashit($path), $excluded)) {
                return true;
            }
        }
        return false;
    }

    private function relative_html_path($url)
    {
        if (!$this->same_site_url($url)) {
            return new WP_Error('static_bridge_path_origin', __('L’URL del file HTML non appartiene all’origine configurata.', 'static-bridge'));
        }
        $path = (string) wp_parse_url($url, PHP_URL_PATH);
        // Split before decoding, so an encoded slash stays inside its segment and is refused below.
        $segments = array_filter(explode('/', trim($path, '/')), 'strlen');
        $safe_segments = array();
        foreach ($segments as $segment) {
            $segment = rawurldecode($segment);
            if ('.' === $segment || '..' === $segment || false !== strpos($segment, "\0")) {
                return new WP_Error('static_bridge_path', __('Il percorso URL contiene segmenti non sicuri.', 'static-bridge'));
            }
            // The decoded bytes as they are: Apache ($1) and Nginx ($uri) look up the decoded path, so
            // sanitize_file_name() would move /tag/pdf/ to tag/unnamed-file.pdf/. Whatever a file name
            // cannot hold safely stays dynamic: separators, controls, whitespace, %, ?, #, a leading dot
            // (.htaccess, .well-known), invalid UTF-8, more than 255 bytes.
            if (strlen($segment) > 255 || '.' === $segment[0] || !preg_match('//u', $segment) || preg_match('~[\x00-\x20\x7F/\\\\%?#]~', $segment)) {
                return new WP_Error('static_bridge_path', __('Il percorso URL non può essere convertito in un nome file sicuro.', 'static-bridge'));
            }
            $safe_segments[] = $segment;
        }
        if (empty($safe_segments)) {
            return 'index.html';
        }
        return implode('/', $safe_segments) . '/index.html';
    }

    /**
     * Why an export saved nothing, with the reason most pages had: the page shows only the last issues, so «nessuna
     * pagina salvata» alone read as an error of its own when every page had been kept dynamic (2.4.1).
     */
    private function no_page_saved_message($job)
    {
        $processed = max(0, (int) ($job['processed'] ?? 0));
        $reasons = array();
        foreach (isset($job['issues']) && is_array($job['issues']) ? $job['issues'] : array() as $issue) {
            if (is_array($issue) && !empty($issue['url']) && isset($issue['message']) && is_string($issue['message']) && '' !== $issue['message']) {
                $reasons[$issue['message']] = ($reasons[$issue['message']] ?? 0) + 1;
            }
        }
        if ($processed < 1 || empty($reasons)) {
            return __('Nessuna pagina HTML è stata salvata: la versione attuale non viene sostituita.', 'static-bridge');
        }
        arsort($reasons);
        $reason = (string) key($reasons);
        return sprintf(
            /* translators: 1: number of pages processed, 2: number of pages with the most frequent reason, 3: that reason */
            _n(
                'Nessuna pagina HTML è stata salvata: %1$s pagina elaborata, nessuna diventata statica. Il motivo più frequente (%2$s): «%3$s» La versione attuale non viene sostituita.',
                'Nessuna pagina HTML è stata salvata: %1$s pagine elaborate, nessuna diventata statica. Il motivo più frequente (%2$s): «%3$s» La versione attuale non viene sostituita.',
                $processed,
                'static-bridge'
            ),
            number_format_i18n($processed),
            number_format_i18n((int) current($reasons)),
            $reason
        );
    }

    private function publish_release(&$job)
    {
        if (!$this->valid_release_stage($job)) {
            $job['status'] = 'failed';
            $job['issues'][] = array('url' => '', 'message' => __('Cartella temporanea non valida o esterna a wp-content/static-bridge/releases; la versione attuale non viene sostituita.', 'static-bridge'));
            return;
        }
        if (empty($job['saved'])) {
            $job['status'] = 'failed';
            $job['issues'][] = array('url' => '', 'message' => $this->no_page_saved_message($job));
            return;
        }
        if (!empty($job['header_fragments_active'])
            && !$this->prepare_header_fragment_pointers((string) $job['release_id'], (string) $job['stage'])) {
            $job['status'] = 'failed';
            $job['issues'][] = array('url' => '', 'message' => __('Non è stato possibile preparare in modo sicuro i puntatori atomici dei frammenti header; la versione attuale non viene sostituita.', 'static-bridge'));
            $this->log_activity(
                __('Pubblicazione SSI annullata: snapshot header incompleto.', 'static-bridge'),
                __('La release precedente rimane attiva; nessun percorso con un header parziale è stato messo online.', 'static-bridge'),
                true
            );
            return;
        }
        $manifest = array(
            'release' => $job['release_id'],
            'created_utc' => gmdate('c'),
            'pages_saved' => (int) $job['saved'],
            'pages_skipped' => (int) $job['skipped'],
            'pages_preserved' => max(0, (int) ($job['pages_preserved'] ?? 0)),
            'route_errors' => max(0, (int) ($job['route_errors'] ?? 0)),
            'redirects_followed' => max(0, (int) ($job['redirects'] ?? 0)),
            'portable_internal_urls' => !empty($job['portable_internal_urls']) ? 1 : 0,
            // Canonical, hreflang, og:/twitter: and JSON-LD keep this origin (2.2.14).
            'absolute_url_origin' => $this->home_origin(),
            'ssi_header_fragments' => !empty($job['header_fragments_active']) ? 1 : 0,
            'security_headers' => isset($job['security_headers']) && is_array($job['security_headers']) ? $job['security_headers'] : array(),
            'issues' => $job['issues'],
        );
        $manifest_json = wp_json_encode($manifest, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES);
        $manifest_file = trailingslashit($job['stage']) . 'manifest.json';
        $ready_file = trailingslashit($job['stage']) . '.ready';
        $manifest_temporary = $manifest_file . '.tmp-' . strtolower(wp_generate_password(8, false, false));
        $minimum_free_space = $this->minimum_free_disk_space_bytes();
        if (!is_string($manifest_json) || file_exists($manifest_file) || is_link($manifest_file)
            || file_exists($ready_file) || is_link($ready_file)
            || file_exists($manifest_temporary) || is_link($manifest_temporary)
            || !$this->has_sufficient_export_disk_space(realpath($job['stage']), $minimum_free_space, strlen($manifest_json))) {
            $job['status'] = 'failed';
            $job['issues'][] = array('url' => '', 'message' => __('Spazio disco insufficiente o percorso manifest non sicuro; la versione attuale non viene sostituita.', 'static-bridge'));
            return;
        }
        $manifest_written = @file_put_contents($manifest_temporary, $manifest_json, LOCK_EX);
        if (strlen($manifest_json) !== $manifest_written) {
            if (file_exists($manifest_temporary) || is_link($manifest_temporary)) {
                @unlink($manifest_temporary);
            }
            $job['status'] = 'failed';
            $job['issues'][] = array('url' => '', 'message' => __('Scrittura completa del manifest non riuscita; la versione attuale non viene sostituita.', 'static-bridge'));
            return;
        }
        @chmod($manifest_temporary, 0644);
        if (!@rename($manifest_temporary, $manifest_file)) {
            if (file_exists($manifest_temporary) || is_link($manifest_temporary)) {
                @unlink($manifest_temporary);
            }
            $job['status'] = 'failed';
            $job['issues'][] = array('url' => '', 'message' => __('Scrittura atomica del manifest non riuscita; la versione attuale non viene sostituita.', 'static-bridge'));
            return;
        }

        if (!empty($job['dependency_index_active'])) {
            $index = new Static_Bridge_Dependency_Index();
            $index_ready = empty($job['dependency_index_failed'])
                && $index->finish_release((string) $job['release_id'], (int) $job['saved']);
            if ($index_ready) {
                $this->log_activity(
                    __('Indice V2 pronto per la nuova release.', 'static-bridge'),
                    sprintf(/* translators: %s: number of indexed routes */ __('Route indicizzate: %s. Le modifiche ai documenti Elementor riconosciuti potranno usare il fan-out selettivo.', 'static-bridge'), number_format_i18n((int) $job['saved']))
                );
            } else {
                $index->mark_failed((string) $job['release_id']);
                if (!empty($job['header_fragments_active'])) {
                    $job['status'] = 'failed';
                    $job['issues'][] = array('url' => '', 'message' => __('Indice V2 incompleto: una release con frammenti SSI non viene pubblicata senza l’indice route completo.', 'static-bridge'));
                    $this->log_activity(
                        __('Pubblicazione SSI annullata: indice V2 incompleto.', 'static-bridge'),
                        __('La release precedente rimane attiva; nessun HTML con include SSI è stato messo online.', 'static-bridge'),
                        true
                    );
                    return;
                }
                $this->log_activity(
                    __('Release pubblicata senza indice V2 completo.', 'static-bridge'),
                    __('La copia statica è valida; gli aggiornamenti dei componenti useranno il fallback prudenziale completo finché l’indice non sarà ricostruito.', 'static-bridge'),
                    true
                );
            }
        }

        // .ready is the commit marker for the whole release, not just its
        // HTML/manifest. Publish it only after the optional dependency index
        // has reached its terminal state so a crash cannot leave a seemingly
        // complete release with an unfinished index.
        if (file_exists($ready_file) || is_link($ready_file)) {
            $job['status'] = 'failed';
            $job['issues'][] = array('url' => '', 'message' => __('Il marcatore .ready esiste già o non è sicuro; la versione attuale non viene sostituita.', 'static-bridge'));
            return;
        }
        $ready_handle = @fopen($ready_file, 'x');
        if (!is_resource($ready_handle)) {
            $job['status'] = 'failed';
            $job['issues'][] = array('url' => '', 'message' => __('Creazione atomica del marcatore .ready non riuscita; la versione attuale non viene sostituita.', 'static-bridge'));
            return;
        }
        $ready_closed = @fclose($ready_handle);
        if (!$ready_closed || !@chmod($ready_file, 0644) || !is_file($ready_file) || is_link($ready_file)) {
            if (is_file($ready_file) && !is_link($ready_file)) {
                @unlink($ready_file);
            }
            $job['status'] = 'failed';
            $job['issues'][] = array('url' => '', 'message' => __('Verifica del marcatore .ready non riuscita; la versione attuale non viene sostituita.', 'static-bridge'));
            return;
        }

        $root = $this->static_root();
        $link = trailingslashit($root) . 'current';
        $temporary = trailingslashit($root) . 'current.new-' . strtolower(wp_generate_password(8, false, false));
        $relative_target = 'releases/' . $job['release_id'];
        if ((file_exists($link) || is_link($link)) && (!is_link($link) || !$this->current_release())) {
            $job['status'] = 'failed';
            $job['issues'][] = array('url' => '', 'message' => __('Il collegamento current esistente non è sicuro; la versione attuale non viene sostituita.', 'static-bridge'));
            return;
        }
        if (file_exists($temporary) || is_link($temporary)) {
            $job['status'] = 'failed';
            $job['issues'][] = array('url' => '', 'message' => __('Il percorso temporaneo current.new esiste già; la versione attuale non viene sostituita.', 'static-bridge'));
            return;
        }
        if (!@symlink($relative_target, $temporary)) {
            $job['status'] = 'failed';
            $job['issues'][] = array('url' => '', 'message' => __('Il server non consente di creare il collegamento simbolico della pubblicazione.', 'static-bridge'));
            return;
        }
        if (!@rename($temporary, $link)) {
            @unlink($temporary);
            $job['status'] = 'failed';
            $job['issues'][] = array('url' => '', 'message' => __('Attivazione atomica della nuova versione non riuscita.', 'static-bridge'));
            return;
        }
        update_option('static_bridge_last_release', array(
            'id' => $job['release_id'],
            'published_at' => time(),
            'pages' => (int) $job['saved'],
            'skipped' => (int) $job['skipped'],
            'preserved' => max(0, (int) ($job['pages_preserved'] ?? 0)),
            'route_errors' => max(0, (int) ($job['route_errors'] ?? 0)),
            'permalink_structure' => (string) get_option('permalink_structure', ''),
        ), false);
        // Before the rules below are written: Apache repeats the new headers at once.
        if ($this->store_security_headers($job) && $this->server_uses_nginx()) {
            $this->log_activity(
                __('Le intestazioni di sicurezza del sito sono cambiate.', 'static-bridge'),
                __('Copia il blocco Nginx aggiornato e ricarica Nginx: fino ad allora le pagine statiche inviano quelle precedenti.', 'static-bridge'),
                true
            );
        }
        if (!empty($job['dependency_index_active'])) {
            $index = new Static_Bridge_Dependency_Index();
            if (!$index->purge_except((string) $job['release_id'])) {
                $this->log_activity(
                    __('Release V2 pubblicata; pulizia degli indici precedenti non completata.', 'static-bridge'),
                    __('La pubblicazione resta attiva. Gli indici storici saranno conservati finché non sarà possibile ripetere la pulizia.', 'static-bridge'),
                    true
                );
            }
        }
        if (!empty($job['header_fragments_active'])
            && !(new Static_Bridge_Header_Fragment_Index())->purge_except((string) $job['release_id'])) {
            $this->log_activity(
                __('Release SSI pubblicata; pulizia degli indici header precedenti non completata.', 'static-bridge'),
                __('La pubblicazione resta attiva. Gli indici di release precedenti saranno conservati finché non sarà possibile ripetere la pulizia.', 'static-bridge'),
                true
            );
        }
        $this->prune_fluent_forms_dynamic_routes();
        $this->prune_woocommerce_dynamic_routes();
        delete_option(self::STALE_RELEASE_OPTION);
        delete_option(self::ROUTING_HOLD_OPTION);
        if (!$this->sync_strict_marker(!empty($this->settings()['strict_mode']))) {
            $this->log_activity(__('Release pubblicata, ma la modalità strict non è stata sincronizzata.', 'static-bridge'), __('Controlla wp-content/static-bridge/.strict; il fallback WordPress resta disponibile.', 'static-bridge'), true);
        }
        if ($this->server_uses_nginx()) {
            // A fresh Nginx install intentionally has no routing marker until
            // there is a verified current release. Arm it only after the
            // atomic current-pointer swap above has succeeded.
            if (!$this->sync_routing_enabled_marker(true)) {
                $this->log_activity(
                    __('Release pubblicata, ma il routing Nginx non è stato attivato.', 'static-bridge'),
                    __('La release è valida ma il frontend resta dinamico. Controlla wp-content/static-bridge/.enabled e i permessi della cartella; ripeti la pubblicazione dopo averli corretti.', 'static-bridge'),
                    true
                );
            }
        } elseif (!$this->update_routing_rules()) {
            $this->log_activity(__('Release pubblicata; regole per i moduli non aggiornate.', 'static-bridge'), __('La pagina resta instradata in modo dinamico finché non è possibile aggiornare .htaccess.', 'static-bridge'), true);
        }
        // Every route may have changed: purge the whole zone (opt-in, in its own request).
        $this->queue_cloudflare_purge('everything', __('nuova release completa pubblicata', 'static-bridge'));
        // «Non riscrivere le pagine identiche» (2.5.0): every route of this release is written and purged.
        $this->reset_unsettled_routes((string) $job['release_id']);
        // Opt-in retention runs later in its own request, under its own
        // locks, so workers that resolved the previous current can finish.
        $this->schedule_release_retention();
        // With Strict a linked route without a copy answers 404: the links are checked later, in their own requests.
        $this->schedule_link_check(self::LINK_CHECK_DELAY);
        // Public action for other plugins; a failing listener never undoes a published release.
        try {
            do_action('static_bridge_release_published', (string) $job['release_id'], (int) $job['saved']);
        } catch (Throwable $e) {
            $this->log_activity(__('Release pubblicata; un plugin in ascolto ha generato un errore.', 'static-bridge'), sanitize_text_field($e->getMessage()), true);
        }
    }

    /**
     * update_option_static_bridge_job (2.5.0). Every path that ends a full export (published, failed at any step,
     * cancelled, closed as incomplete) saves the job with its final status, so the end of an export is seen here,
     * once: a job saved again with the same final status is not a new end.
     */
    public function handle_export_job_saved($old_value, $value)
    {
        $final = array('complete', 'failed', 'cancelled');
        if (!is_array($value) || !isset($value['status']) || !in_array($value['status'], $final, true)) {
            return;
        }
        $job_id = isset($value['job_id']) ? (string) $value['job_id'] : '';
        if (is_array($old_value) && isset($old_value['status']) && in_array($old_value['status'], $final, true)
            && (isset($old_value['job_id']) ? (string) $old_value['job_id'] : '') === $job_id) {
            return;
        }
        // Called inside update_option() of the export: nothing here may break the export that just ended.
        try {
            $this->export_finished($value);
        } catch (Throwable $e) {
            $this->log_activity(__('Fine dell’esportazione non notificata: errore interno.', 'static-bridge'), sanitize_text_field($e->getMessage()), true);
        }
    }

    /** The e-mail of a failed export, the reset after a published one, and the public action static_bridge_export_finished. */
    private function export_finished($job)
    {
        $status = (string) $job['status'];
        $issues = isset($job['issues']) && is_array($job['issues']) ? array_values($job['issues']) : array();
        $last_issue = empty($issues) ? null : $issues[count($issues) - 1];
        $route_errors = max(0, (int) ($job['route_errors'] ?? 0));
        if ('complete' === $status) {
            $message = $route_errors > 0
                ? sprintf(/* translators: %s: number of URLs with errors */ __('Versione pubblicata con errori su %s URL.', 'static-bridge'), number_format_i18n($route_errors))
                : __('Versione pubblicata.', 'static-bridge');
        } else {
            // The step that ended the export adds its reason last (fail_export_queue_job(), publish_release(), cancel).
            $message = is_array($last_issue) && isset($last_issue['message']) ? (string) $last_issue['message'] : '';
            if (is_array($last_issue) && !empty($last_issue['url']) && is_string($last_issue['url'])) {
                $message = $last_issue['url'] . ' — ' . $message;
            }
        }
        $summary = array(
            'job_id' => isset($job['job_id']) ? (string) $job['job_id'] : '',
            'release_id' => 'complete' === $status && isset($job['release_id']) ? (string) $job['release_id'] : '',
            'saved' => max(0, (int) ($job['saved'] ?? 0)),
            'failed' => $route_errors,
            'skipped' => max(0, (int) ($job['skipped'] ?? 0)),
            'preserved' => max(0, (int) ($job['pages_preserved'] ?? 0)),
            'started_at' => max(0, (int) ($job['started_at'] ?? 0)),
            'finished_at' => max(0, (int) ($job['updated_at'] ?? time())),
            'message' => $this->failure_notice_text($message),
        );
        if ('complete' === $status) {
            $this->clear_failure_notice();
            // After an update (2.5.0): what changed before this export started is in the release now.
            $this->forget_changes_before($summary['started_at']);
        } elseif ('failed' === $status) {
            $this->notify_update_failure('export', '' !== $summary['message'] ? $summary['message'] : __('Esportazione interrotta: release non pubblicata.', 'static-bridge'));
        }
        // Public action for other plugins, once per export; a failing listener changes nothing of the result.
        try {
            do_action('static_bridge_export_finished', $status, $summary);
        } catch (Throwable $e) {
            $this->log_activity(__('Esportazione conclusa; un plugin in ascolto ha generato un errore.', 'static-bridge'), sanitize_text_field($e->getMessage()), true);
        }
    }

    /**
     * «Avvisami per email se un aggiornamento fallisce» (2.5.0, off by default): one e-mail to the administrator
     * (or to a valid address of the filter static_bridge_failure_email_recipient) until a full export publishes or
     * an incremental update completes. $kind is 'export' or 'incremental'. Every e-mail sent or not sent is in Attività.
     */
    private function notify_update_failure($kind, $error)
    {
        $settings = get_option(self::SETTINGS_OPTION, array());
        if (!is_array($settings) || empty($settings['failure_email']) || false !== get_option(self::FAILURE_NOTICE_OPTION, false)) {
            return false;
        }
        $kind = in_array($kind, array('export', 'schedule', 'incremental'), true) ? $kind : 'incremental';
        $export = 'incremental' !== $kind;
        // Written first: a second failure meanwhile, or a mail server that fails, never sends a second e-mail.
        update_option(self::FAILURE_NOTICE_OPTION, array('at' => time(), 'what' => $kind, 'sent' => 0), false);
        $whats = array(
            'export' => __('l’export completo è finito con un errore e la nuova versione non è stata pubblicata.', 'static-bridge'),
            // 2.5.0: «Export completo pianificato» refused to start (not a running or paused export: those are skipped).
            'schedule' => __('l’export completo pianificato non è partito e la versione online non è stata aggiornata.', 'static-bridge'),
            'incremental' => __('l’aggiornamento automatico di una pagina non riesce da circa mezz’ora.', 'static-bridge'),
        );
        $what = $whats[$kind];
        $admin = get_option('admin_email', '');
        $admin = is_string($admin) && is_email($admin) ? $admin : '';
        $recipient = apply_filters('static_bridge_failure_email_recipient', $admin);
        $recipient = is_string($recipient) && is_email($recipient) ? $recipient : $admin;
        if ('' === $recipient) {
            $this->log_activity(__('Avviso per email non inviato: l’indirizzo dell’amministratore non è valido.', 'static-bridge'), ucfirst($what), true);
            return false;
        }
        $site = trim(html_entity_decode(wp_strip_all_tags((string) get_option('blogname', '')), ENT_QUOTES, 'UTF-8'));
        if ('' === $site) {
            $site = (string) wp_parse_url(home_url('/'), PHP_URL_HOST);
        }
        $subject = sprintf(
            /* translators: 1: site name, 2: what failed */
            __('[%1$s] Static Bridge: %2$s', 'static-bridge'),
            $site,
            'schedule' === $kind ? __('export completo pianificato non avviato', 'static-bridge')
                : ($export ? __('export completo non riuscito', 'static-bridge') : __('aggiornamento automatico non riuscito', 'static-bridge'))
        );
        $body = implode("\n", array(
            sprintf(/* translators: %s: site name */ __('Static Bridge non è riuscito ad aggiornare la copia statica di %s.', 'static-bridge'), $site),
            '',
            sprintf(/* translators: %s: what failed (a sentence) */ __('Che cosa: %s', 'static-bridge'), $what),
            sprintf(/* translators: %s: error message */ __('Errore: %s', 'static-bridge'), $this->failure_notice_text($error)),
            '',
            __('La versione statica già online resta pubblicata. I dettagli sono in Static Bridge, scheda Attività:', 'static-bridge'),
            $this->tab_url('activity'),
            '',
            __('Non riceverai altri avvisi finché un export completo o un aggiornamento non andrà a buon fine.', 'static-bridge'),
        ));
        try {
            $sent = (bool) wp_mail($recipient, str_replace(array("\r", "\n"), ' ', $subject), $body);
        } catch (Throwable $e) {
            $sent = false;
        }
        if (!$sent) {
            $this->log_activity(__('Avviso per email non inviato: wp_mail non è riuscita.', 'static-bridge'), ucfirst($what), true);
            return false;
        }
        update_option(self::FAILURE_NOTICE_OPTION, array('at' => time(), 'what' => $kind, 'sent' => 1), false);
        $this->log_activity(__('Avviso per email inviato all’amministratore.', 'static-bridge'), ucfirst($what) . ' ' . __('Non partono altri avvisi finché un aggiornamento non riesce.', 'static-bridge'));
        return true;
    }

    /** Static Bridge works again: the next failure may e-mail the administrator. */
    private function clear_failure_notice()
    {
        if (false !== get_option(self::FAILURE_NOTICE_OPTION, false)) {
            delete_option(self::FAILURE_NOTICE_OPTION);
        }
    }

    /** An error message for an e-mail or another plugin: plain text on one line, server folders as wp-content/…. */
    private function failure_notice_text($message)
    {
        $text = wp_strip_all_tags((string) $message);
        $roots = array();
        if (defined('WP_CONTENT_DIR')) {
            $roots[rtrim((string) WP_CONTENT_DIR, '/\\')] = 'wp-content';
        }
        if (defined('ABSPATH')) {
            $roots[rtrim((string) ABSPATH, '/\\') . '/'] = '';
        }
        foreach ($roots as $root => $replacement) {
            if (strlen($root) > 1) {
                $text = str_replace($root, $replacement, $text);
            }
        }
        $text = trim((string) preg_replace('/\s+/u', ' ', $text));
        return function_exists('mb_substr') ? mb_substr($text, 0, 500) : substr($text, 0, 500);
    }

    private function job_response($job)
    {
        if (is_array($job) && !empty($job['queue_version']) && !empty($job['job_id'])) {
            $queue = $this->export_queue();
            $pending = $queue->install() ? $queue->count_pending($job['job_id']) : 0;
            $pending = false === $pending ? 0 : (int) $pending;
            $processed = max(0, (int) (isset($job['processed']) ? $job['processed'] : 0));
            $total = $processed + $pending;
            $discovered = max(0, (int) (isset($job['discovered']) ? $job['discovered'] : 0));
            $reported_total = max($total, $discovered);
            $complete_discovery = !empty($job['discovery_complete']);
            $progress = $reported_total > 0 ? min(100, (int) floor(($processed / $reported_total) * 100)) : 0;
            if ('running' === (isset($job['status']) ? $job['status'] : '') && !$complete_discovery && $progress > 95) {
                $progress = 95;
            }
            $fetch_info = $this->export_fetch_info();
            return array(
                'status' => isset($job['status']) ? $job['status'] : 'idle',
                'processed' => $processed,
                'total' => $reported_total,
                'saved' => isset($job['saved']) ? (int) $job['saved'] : 0,
                'skipped' => isset($job['skipped']) ? (int) $job['skipped'] : 0,
                'preserved' => max(0, (int) ($job['pages_preserved'] ?? 0)),
                'routeErrors' => max(0, (int) ($job['route_errors'] ?? 0)),
                'pending' => $pending,
                'discoveryComplete' => $complete_discovery,
                'currentUrl' => isset($job['current_url']) ? $job['current_url'] : '',
                'fetchMode' => $fetch_info['mode'],
                'fetchConcurrency' => $fetch_info['concurrency'],
                'fetchModeReason' => $fetch_info['reason'],
                'workerBusy' => !empty($job['_worker_busy']),
                'waiting' => max(0, (int) ($job['_waiting'] ?? 0)),
                'recoveryRound' => !empty($job['recovery_round']),
                'retryCount' => isset($job['retry_attempts']) ? (int) $job['retry_attempts'] : 0,
                'issues' => isset($job['issues']) && is_array($job['issues']) ? array_slice($job['issues'], -10) : array(),
                'progress' => $progress,
                'message' => 'complete' === (isset($job['status']) ? $job['status'] : '')
                    ? (max(0, (int) ($job['route_errors'] ?? 0)) > 0
                        ? sprintf(/* translators: %s: number of URLs with errors */ __('Versione pubblicata con errori su %s URL.', 'static-bridge'), number_format_i18n(max(0, (int) $job['route_errors'])))
                        : __('Versione pubblicata.', 'static-bridge'))
                    : ('paused' === (isset($job['status']) ? $job['status'] : '') ? __('Esportazione in pausa: coda e staging conservati.', 'static-bridge') : ''),
            );
        }
        $pending = isset($job['pending']) && is_array($job['pending']) ? count($job['pending']) : 0;
        $processed = isset($job['processed']) ? (int) $job['processed'] : 0;
        $total = $processed + $pending;
        $fetch_info = $this->export_fetch_info();
        return array(
            'status' => isset($job['status']) ? $job['status'] : 'idle',
            'processed' => $processed,
            'total' => $total,
            'saved' => isset($job['saved']) ? (int) $job['saved'] : 0,
            'skipped' => isset($job['skipped']) ? (int) $job['skipped'] : 0,
            'preserved' => max(0, (int) ($job['pages_preserved'] ?? 0)),
            'routeErrors' => max(0, (int) ($job['route_errors'] ?? 0)),
            'pending' => $pending,
            'currentUrl' => isset($job['current_url']) ? $job['current_url'] : '',
            'fetchMode' => $fetch_info['mode'],
            'fetchConcurrency' => $fetch_info['concurrency'],
            'fetchModeReason' => $fetch_info['reason'],
            'retryCount' => 0,
            'issues' => isset($job['issues']) ? array_slice($job['issues'], -10) : array(),
            'progress' => $total > 0 ? min(100, (int) floor(($processed / $total) * 100)) : 0,
            'message' => 'complete' === (isset($job['status']) ? $job['status'] : '') ? __('Versione pubblicata.', 'static-bridge') : '',
        );
    }

    private function job_is_running()
    {
        $job = get_option(self::JOB_OPTION, array());
        if (is_array($job) && !empty($job['queue_version'])) {
            if (1 !== (int) $job['queue_version']
                || !isset($job['job_id'], $job['status'], $job['started_at'], $job['updated_at'], $job['discovery_cursor'], $job['discovery_complete'], $job['discovered'], $job['processed'], $job['saved'], $job['skipped'], $job['issues'])
                || !preg_match('/^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/i', (string) $job['job_id'])
                || 'running' !== $job['status']
                || !is_array($job['issues'])
                || !is_numeric($job['started_at'])
                || !is_numeric($job['updated_at'])
                || !is_numeric($job['discovery_cursor'])
                || !is_numeric($job['discovered'])
                || !is_numeric($job['processed'])
                || !is_numeric($job['saved'])
                || !is_numeric($job['skipped'])) {
                return false;
            }
            $age = time() - (int) $job['updated_at'];
            return $age >= 0 && $age < self::EXPORT_JOB_MAX_AGE && $this->valid_release_stage($job);
        }
        if (!is_array($job)
            || !isset($job['status'], $job['release_id'], $job['stage'], $job['started_at'], $job['updated_at'], $job['pending'], $job['seen'], $job['processed'], $job['saved'], $job['skipped'], $job['issues'])
            || 'running' !== $job['status']
            || !is_array($job['pending'])
            || empty($job['pending'])
            || count($job['pending']) > self::MAX_EXPORT_URLS
            || !is_array($job['seen'])
            || empty($job['seen'])
            || count($job['seen']) > self::MAX_EXPORT_URLS
            || !is_array($job['issues'])
            || !is_numeric($job['started_at'])
            || !is_numeric($job['updated_at'])
            || !is_numeric($job['processed'])
            || !is_numeric($job['saved'])
            || !is_numeric($job['skipped'])) {
            return false;
        }
        $age = time() - (int) $job['updated_at'];
        return $age >= 0 && $age < 3600 && $this->valid_release_stage($job);
    }

    private function job_is_resumable($job = null)
    {
        if (null === $job) {
            $job = get_option(self::JOB_OPTION, array());
        }
        if (!is_array($job)
            || !isset($job['queue_version'], $job['job_id'], $job['status'], $job['release_id'], $job['stage'], $job['started_at'], $job['updated_at'], $job['discovery_cursor'], $job['discovery_complete'], $job['discovered'], $job['processed'], $job['saved'], $job['skipped'], $job['issues'], $job['current_url'], $job['retry_url_hash'], $job['retry_attempts'])
            || 1 !== (int) $job['queue_version']
            || 'paused' !== $job['status']
            || !preg_match('/^[a-f0-9]{8}-(?:[a-f0-9]{4}-){3}[a-f0-9]{12}$/i', (string) $job['job_id'])
            || !is_array($job['issues'])
            || !is_string($job['current_url'])
            || '' === $job['current_url']
            || !is_string($job['retry_url_hash'])
            || !preg_match('/^[a-f0-9]{40}$/', $job['retry_url_hash'])
            || !is_numeric($job['retry_attempts'])
            || (int) $job['retry_attempts'] !== self::MAX_EXPORT_HTTP_RETRIES
            || (float) $job['retry_attempts'] !== (float) (int) $job['retry_attempts']) {
            return false;
        }
        foreach (array('started_at', 'updated_at', 'discovery_cursor', 'discovered', 'processed', 'saved', 'skipped') as $field) {
            if (!is_numeric($job[$field]) || (float) $job[$field] < 0 || (float) $job[$field] !== (float) (int) $job[$field]) {
                return false;
            }
        }
        if (!is_bool($job['discovery_complete']) && !in_array($job['discovery_complete'], array(0, 1, '0', '1'), true)) {
            return false;
        }
        $age = time() - (int) $job['updated_at'];
        if ($age < 0 || $age >= self::EXPORT_JOB_MAX_AGE || !$this->valid_release_stage($job)) {
            return false;
        }

        $stage = realpath($job['stage']);
        if (!$stage || file_exists($stage . '/.ready') || is_link($stage . '/.ready')) {
            return false;
        }
        $current = $this->current_release();
        if ($current && $current === $stage) {
            return false;
        }

        $queue = $this->export_queue();
        if (!$queue->install()) {
            return false;
        }
        $pending = $queue->count_pending($job['job_id']);
        $row = $queue->next_pending($job['job_id']);
        if (false === $pending || $pending < 1 || !is_array($row)
            || !isset($row['url_hash'], $row['url'])
            || !is_string($row['url'])
            || !hash_equals((string) $job['retry_url_hash'], (string) $row['url_hash'])
            || !hash_equals((string) $job['retry_url_hash'], sha1($row['url']))
            || !hash_equals((string) $job['current_url'], $row['url'])) {
            return false;
        }
        $normalized = $this->normalize_public_url($row['url']);
        return is_string($normalized) && hash_equals($row['url'], $normalized);
    }

    private function job_release_is_current($job)
    {
        if (!is_array($job) || !$this->valid_release_stage($job)) {
            return false;
        }
        $stage = realpath((string) $job['stage']);
        $current = $this->current_release();
        return $stage && $current && $stage === $current
            && basename($current) === (string) $job['release_id'];
    }

    /** Reconcile the filesystem commit if PHP stopped just after current.swap. */
    private function recover_interrupted_release_publication(&$job)
    {
        if (!$this->job_release_is_current($job) || !empty($job['header_fragments_active'])) {
            return false;
        }

        $release_id = (string) $job['release_id'];
        $release = realpath((string) $job['stage']);
        $manifest_file = trailingslashit($release) . 'manifest.json';
        $ready_file = trailingslashit($release) . '.ready';
        if (!is_file($manifest_file) || is_link($manifest_file)
            || !is_file($ready_file) || is_link($ready_file)) {
            return false;
        }
        $manifest_json = @file_get_contents($manifest_file);
        $manifest = is_string($manifest_json) ? json_decode($manifest_json, true) : null;
        $saved = isset($job['saved']) && is_int($job['saved']) ? $job['saved'] : -1;
        $skipped = isset($job['skipped']) && is_int($job['skipped']) ? $job['skipped'] : -1;
        if (!is_array($manifest)
            || $release_id !== (string) ($manifest['release'] ?? '')
            || $saved < 1 || !isset($manifest['pages_saved']) || !is_int($manifest['pages_saved']) || $saved !== $manifest['pages_saved']
            || $skipped < 0 || !isset($manifest['pages_skipped']) || !is_int($manifest['pages_skipped']) || $skipped !== $manifest['pages_skipped']
            || !isset($manifest['portable_internal_urls']) || 1 !== $manifest['portable_internal_urls']
            || !isset($manifest['ssi_header_fragments']) || 0 !== $manifest['ssi_header_fragments']) {
            return false;
        }

        if (!empty($job['dependency_index_active']) && empty($job['dependency_index_failed'])
            && !(new Static_Bridge_Dependency_Index())->is_ready($release_id)) {
            return false;
        }

        update_option('static_bridge_last_release', array(
            'id' => $release_id,
            'published_at' => time(),
            'pages' => $saved,
            'skipped' => $skipped,
            'permalink_structure' => (string) get_option('permalink_structure', ''),
        ), false);
        $this->store_security_headers($job);
        delete_option(self::STALE_RELEASE_OPTION);
        delete_option(self::ROUTING_HOLD_OPTION);
        $job['status'] = 'complete';
        $job['updated_at'] = time();
        $job['recovered_after_publication'] = 1;
        update_option(self::JOB_OPTION, $job, false);

        if (!empty($job['queue_version']) && !empty($job['job_id'])) {
            if (!$this->export_queue()->delete_job((string) $job['job_id'])) {
                $this->log_activity(
                    __('Release recuperata; coda residua da controllare.', 'static-bridge'),
                    __('La release valida è già attiva. La pulizia delle righe temporanee della coda non è riuscita.', 'static-bridge'),
                    true
                );
            }
            wp_clear_scheduled_hook('static_bridge_process_export_queue');
        }

        if (!empty($job['dependency_index_active'])) {
            $index = new Static_Bridge_Dependency_Index();
            if (!$index->purge_except($release_id)) {
                $this->log_activity(
                    __('Release recuperata; pulizia degli indici precedenti incompleta.', 'static-bridge'),
                    __('La release corrente e il suo indice sono stati preservati; gli indici storici richiedono una nuova verifica.', 'static-bridge'),
                    true
                );
            }
        }
        if (!$this->sync_strict_marker(!empty($this->settings()['strict_mode']))) {
            $this->log_activity(__('Release recuperata, modalità strict da verificare.', 'static-bridge'), __('Il fallback WordPress resta disponibile finché il marcatore strict non è coerente.', 'static-bridge'), true);
        }
        if (!$this->update_routing_rules()) {
            $this->log_activity(__('Release recuperata, regole di routing da verificare.', 'static-bridge'), __('La release è valida; controlla la configurazione del server e il fallback WordPress.', 'static-bridge'), true);
        }
        if (!empty($this->settings()['incremental_enabled']) && !empty($this->incremental_queue())) {
            $this->schedule_incremental_worker(0, true);
        }
        $this->log_activity(
            __('Pubblicazione interrotta riconciliata.', 'static-bridge'),
            sprintf(/* translators: 1: release ID, 2: number of pages */ __('La release %1$s era già stata attivata atomicamente; lo stato del job è stato recuperato (%2$s pagine).', 'static-bridge'), $release_id, number_format_i18n($saved))
        );
        return true;
    }

    private function close_incomplete_export_job($job)
    {
        if (!is_array($job) || !isset($job['status']) || 'running' !== $job['status']) {
            return is_array($job) ? $job : array();
        }
        if ($this->recover_interrupted_release_publication($job)) {
            return $job;
        }
        $already_current = $this->job_release_is_current($job);
        $message = $already_current
            ? __('La current punta già alla release del job, ma i metadati non superano il controllo automatico. La release e i relativi indici sono stati preservati per evitare una rimozione incoerente; verifica la diagnostica prima di intervenire.', 'static-bridge')
            : __('La sessione salvata era incompleta, scaduta o non sicura; nessuna nuova release è stata attivata. Avvia una nuova esportazione.', 'static-bridge');
        $job['status'] = 'failed';
        $job['updated_at'] = time();
        $job['issues'] = isset($job['issues']) && is_array($job['issues']) ? $job['issues'] : array();
        $job['issues'][] = array('url' => '', 'message' => $message);
        update_option(self::JOB_OPTION, $job, false);
        if (!empty($job['queue_version']) && !empty($job['job_id'])) {
            $this->export_queue()->delete_job($job['job_id']);
            wp_clear_scheduled_hook('static_bridge_process_export_queue');
        }
        if (!$already_current) {
            $this->cleanup_dependency_index_for_job($job);
        }
        $this->log_activity(__('Sessione di esportazione incompleta chiusa.', 'static-bridge'), $message, true);
        return $job;
    }

    /** Queue one deferred retention run; a no-op while retention is disabled. */
    private function schedule_release_retention($delay = self::RETENTION_DELAY)
    {
        if (empty($this->settings()['retention_enabled'])) {
            return false;
        }
        wp_clear_scheduled_hook(self::RETENTION_HOOK);
        return false !== wp_schedule_single_event(time() + max(60, absint($delay)), self::RETENTION_HOOK);
    }

    public function process_release_retention_cron()
    {
        $previous = get_option(self::RETENTION_LAST_OPTION, array());
        $result = $this->apply_release_retention('cron');
        if ('busy' === $result['status']) {
            $retries = is_array($previous) && 'busy' === ($previous['status'] ?? '') && 'cron' === ($previous['trigger'] ?? '')
                ? (int) ($previous['busy_retries'] ?? 0) + 1
                : 1;
            $result['busy_retries'] = $retries;
            update_option(self::RETENTION_LAST_OPTION, $result, false);
            if ($retries <= self::RETENTION_MAX_BUSY_RETRIES) {
                $this->schedule_release_retention();
            }
        } elseif ('partial' === $result['status']) {
            $this->schedule_release_retention(60);
        }
    }

    public function handle_apply_retention()
    {
        if (!current_user_can('manage_options')) {
            wp_die(esc_html__('Non hai i permessi necessari.', 'static-bridge'), '', array('response' => 403));
        }
        check_admin_referer('static_bridge_apply_retention');
        $result = $this->apply_release_retention('manual');
        wp_safe_redirect(add_query_arg(array('page' => self::ADMIN_SLUG, 'tab' => 'versions', 'retention-run' => $result['status']), admin_url('admin.php')));
        exit;
    }

    /*
     * The link check after a publication (2.5.0). With Strict a public route without a copy answers 404 from the
     * server, so a page of the release that links such a route sends the visitor to a 404. The export keeps nothing
     * that could say it: its queue rows are deleted when the release is published, they never say which page links
     * which route, the crawl drops the links that the export exclusions refuse, and incremental updates change the
     * release afterwards. So the check reads the HTML of the current release from disk, in chunks, in WP-Cron, and
     * decides each link with the lists that write the server rules. It writes only its report.
     */

    /** True when the .strict marker is there: Strict as the server applies it, not only the setting. */
    private function strict_marker_active()
    {
        $root = $this->static_root();
        $marker = $root . '/.strict';
        clearstatcache(true, $marker);
        return !is_link($root) && is_dir($root) && !is_link($marker) && is_file($marker);
    }

    /**
     * A new link check of the current release in $delay seconds, with an empty report. Without a release or without
     * the .strict marker there is nothing to check: a check still waiting stops.
     *
     * @return string 'queued', 'no_release', 'strict_off' or 'failed'.
     */
    private function schedule_link_check($delay = 0)
    {
        $release = $this->current_release();
        $refused = '' === $release ? 'no_release' : ($this->strict_marker_active() ? '' : 'strict_off');
        wp_clear_scheduled_hook(self::LINK_CHECK_HOOK);
        if ('' !== $refused) {
            $report = get_option(self::LINK_CHECK_OPTION, array());
            if (is_array($report) && in_array($report['status'] ?? '', array('queued', 'running'), true)) {
                $report['status'] = 'stopped';
                $report['reason'] = $refused;
                $report['finished_at'] = time();
                update_option(self::LINK_CHECK_OPTION, $report, false);
            }
            return $refused;
        }
        update_option(self::LINK_CHECK_OPTION, array(
            'release' => basename($release),
            'status' => 'queued',
            'reason' => '',
            'queued_at' => time(),
            'started_at' => 0,
            'finished_at' => 0,
            'cursor' => null,
            'pages' => 0,
            'links' => 0,
            'total' => 0,
            'capped' => false,
            'broken' => array(),
            'counted' => array(),
        ), false);
        return false === wp_schedule_single_event(time() + max(0, (int) $delay), self::LINK_CHECK_HOOK) ? 'failed' : 'queued';
    }

    /** WP-Cron callback of static_bridge_link_check: one chunk, then the next event, or the result in Attività. */
    public function run_link_check()
    {
        $report = get_option(self::LINK_CHECK_OPTION, array());
        if (!is_array($report) || !in_array($report['status'] ?? '', array('queued', 'running'), true)) {
            return;
        }
        $lock = $this->acquire_row_lock(self::LINK_CHECK_LOCK, 120);
        if (false === $lock) {
            // Another request is reading a chunk: make sure the rest still has a run.
            if (!wp_next_scheduled(self::LINK_CHECK_HOOK)) {
                wp_schedule_single_event(time() + 30, self::LINK_CHECK_HOOK);
            }
            return;
        }
        try {
            // Read again under the lock: the chunk before may have just saved its cursor.
            $report = get_option(self::LINK_CHECK_OPTION, array());
            if (!is_array($report) || !in_array($report['status'] ?? '', array('queued', 'running'), true)) {
                return;
            }
            $report = $this->link_check_step($report);
            update_option(self::LINK_CHECK_OPTION, $report, false);
            if ('running' === $report['status']) {
                wp_schedule_single_event(time() + self::LINK_CHECK_NEXT_DELAY, self::LINK_CHECK_HOOK);
            } elseif ('complete' === $report['status']) {
                $this->log_link_check_result($report);
            } else {
                $reasons = array(
                    'release_changed' => __('La versione controllata non è più quella online; una nuova versione pubblicata con la modalità strict ha il suo controllo.', 'static-bridge'),
                    'strict_off' => __('La modalità strict è spenta: le rotte senza copia statica le serve WordPress.', 'static-bridge'),
                );
                $this->log_activity(__('Controllo dei link fermato prima della fine.', 'static-bridge'), $reasons[$report['reason'] ?? ''] ?? '');
            }
        } finally {
            $this->release_row_lock(self::LINK_CHECK_LOCK, $lock);
        }
    }

    /** The row in Attività of a finished check: an error when at least one linked route answers 404. */
    private function log_link_check_result($report)
    {
        $total = max(0, (int) ($report['total'] ?? 0));
        $detail = sprintf(
            /* translators: 1: release id, 2: number of pages read */
            __('Versione %1$s: %2$s pagine lette.', 'static-bridge'),
            (string) ($report['release'] ?? ''),
            number_format_i18n(max(0, (int) ($report['pages'] ?? 0)))
        );
        if (0 === $total) {
            $this->log_activity(__('Controllo dei link completato: ogni rotta linkata ha una copia statica o la serve WordPress.', 'static-bridge'), $detail);
            return;
        }
        $this->log_activity(
            sprintf(
                /* translators: %s: number of routes */
                _n('Controllo dei link: %s rotta linkata senza copia statica risponde 404.', 'Controllo dei link: %s rotte linkate senza copia statica rispondono 404.', $total, 'static-bridge'),
                $this->link_check_total_label($report)
            ),
            $detail . ' ' . __('L’elenco, con le pagine che le linkano, è nella scheda Genera.', 'static-bridge'),
            true
        );
    }

    /** The number of broken routes, with «+» when the count stopped at its cap. */
    private function link_check_total_label($report)
    {
        return number_format_i18n(max(0, (int) ($report['total'] ?? 0))) . (empty($report['capped']) ? '' : '+');
    }

    /**
     * One chunk of the check: at most $max_pages pages and LINK_CHECK_TIME_BUDGET seconds, from the cursor on. Stops
     * the check when the release is no longer the current one or the .strict marker is gone.
     */
    private function link_check_step($report, $max_pages = self::LINK_CHECK_BATCH_PAGES)
    {
        $release = $this->current_release();
        if ('' === $release || basename($release) !== (string) ($report['release'] ?? '')) {
            return array_merge($report, array('status' => 'stopped', 'reason' => 'release_changed', 'finished_at' => time()));
        }
        if (!$this->strict_marker_active()) {
            return array_merge($report, array('status' => 'stopped', 'reason' => 'strict_off', 'finished_at' => time()));
        }
        if ('queued' === $report['status']) {
            $report['status'] = 'running';
            $report['started_at'] = time();
        }
        foreach (array('pages', 'links', 'total') as $counter) {
            $report[$counter] = max(0, (int) ($report[$counter] ?? 0));
        }
        $report['broken'] = isset($report['broken']) && is_array($report['broken']) ? $report['broken'] : array();
        $report['counted'] = isset($report['counted']) && is_array($report['counted']) ? $report['counted'] : array();
        $cursor = isset($report['cursor']) && is_array($report['cursor']) ? array_values(array_map('strval', $report['cursor'])) : null;
        $budget = self::LINK_CHECK_TIME_BUDGET;
        $php_budget = $this->safe_php_request_budget();
        if ($php_budget > 0) {
            $budget = min($budget, $php_budget);
        }
        $deadline = microtime(true) + $budget;
        $rules = $this->link_check_rules();
        $broken = array();
        $fragment_hrefs = array();
        $read = 0;
        $complete = true;
        foreach ($this->link_check_walk($release, array(), $cursor) as $segments) {
            if ($read >= max(1, (int) $max_pages) || microtime(true) >= $deadline) {
                $complete = false;
                break;
            }
            $read++;
            $report['cursor'] = $segments;
            $report['pages']++;
            $html = $this->link_check_read_page($release, $segments);
            if (null === $html) {
                continue;
            }
            $page = $this->link_check_page_route($segments, $rules['slash']);
            if ('' === $this->link_check_route($this->link_check_route_url($page), $rules)) {
                // A page the rules send to WP (an exclusion added after the export): no visitor sees this copy.
                continue;
            }
            $seen = array();
            $hrefs = $this->html_link_hrefs($html, false, true);
            // On Nginx the header of an Elementor page can be an SSI fragment (scheda 68): the visitor sees its
            // links too, so they count as links of this page. A fragment is read once per block.
            foreach ($this->link_check_fragment_keys($html) as $key) {
                if (!array_key_exists($key, $fragment_hrefs)) {
                    list($document_id, $file_name) = explode('/', $key, 2);
                    $markup = $this->verified_header_fragment($release, $document_id, $file_name, substr($file_name, -69, 64));
                    $fragment_hrefs[$key] = null === $markup ? array() : $this->html_link_hrefs($markup, false, true);
                }
                $hrefs = array_merge($hrefs, $fragment_hrefs[$key]);
            }
            foreach ($hrefs as $href) {
                $url = $this->link_href_url($href, $this->link_check_route_url($page));
                $route = '' === $url ? '' : $this->link_check_route($url, $rules);
                if ('' === $route || isset($seen[$route])) {
                    continue;
                }
                $seen[$route] = true;
                $report['links']++;
                if (!isset($broken[$route])) {
                    $broken[$route] = !$this->static_file_exists_for_path($route);
                }
                if ($broken[$route]) {
                    $this->link_check_record($report, $route, $page);
                }
            }
        }
        if ($complete) {
            $report['status'] = 'complete';
            $report['finished_at'] = time();
            $report['counted'] = array();
        }
        return $report;
    }

    /**
     * The SSI header fragments a page of the release includes, as `<document>/<file>` keys: only the directive the
     * export writes (Static_Bridge_Header_Fragments::include_uri()), at most 8 per page.
     *
     * @return string[]
     */
    private function link_check_fragment_keys($html)
    {
        if (false === strpos((string) $html, '#include') || !preg_match_all(
            '~<!--#include\s+virtual="/wp-content/static-bridge/current/fragments/headers/([A-Za-z0-9_-]{1,64})/current/(elementor-[A-Za-z0-9_-]{1,64}-[a-f0-9]{64}\.html)"\s+-->~',
            (string) $html,
            $matches,
            PREG_SET_ORDER
        )) {
            return array();
        }
        $keys = array();
        foreach ($matches as $match) {
            $keys[$match[1] . '/' . $match[2]] = true;
            if (count($keys) >= 8) {
                break;
            }
        }
        return array_keys($keys);
    }

    /** What the server rules decide without the copy, read once per chunk from the lists that write them. */
    private function link_check_rules()
    {
        return array(
            'dynamic' => $this->server_dynamic_route_patterns(),
            'files' => $this->file_extension_pattern(),
            'excluded' => $this->routing_excluded_paths(),
            'redirects' => $this->plugin_redirects(),
            'slash' => $this->routes_require_trailing_slash(),
            // 2.5.0: a query made only of tracking parameters gets the copy, as in the rules; '' with the setting off.
            'query' => $this->tracking_query_pattern(),
        );
    }

    /**
     * The route a link of a page asks for, in the form WP links it, when the server rules would answer it from the
     * copy or with the Strict 404; '' when the link leaves the site, has a query (it reaches WP; 2.5.0: unless it is
     * made only of tracking parameters, as the rules decide), or the rules send it to WP anyway: the paths of WP,
     * feeds, sitemaps, search, files, /.well-known/, every exclusion of the rules (manual, forms, editor,
     * WooCommerce, filter, incremental queue) and the redirects of other plugins.
     */
    private function link_check_route($url, $rules)
    {
        if (!$this->same_site_url($url)) {
            return '';
        }
        $parts = wp_parse_url($url);
        $tracking = isset($rules['query']) ? (string) $rules['query'] : '';
        if (!is_array($parts) || (isset($parts['query']) && '' !== $parts['query']
            && ('' === $tracking || !preg_match('#' . $tracking . '#', $parts['query'])))) {
            return '';
        }
        $path = isset($parts['path']) && '' !== $parts['path'] ? rawurldecode($parts['path']) : '/';
        $path = '/' . ltrim($path, '/');
        if (false !== strpos($path, "\0") || preg_match('~(^|/)\.\.?(/|$)~', $path)) {
            return '';
        }
        foreach ($rules['dynamic'] as $pattern) {
            if (preg_match('~' . $pattern . '~i', $path)) {
                return '';
            }
        }
        // As the Strict rule: /.well-known/ and files stay with WP. /cdn-cgi/ is answered by Cloudflare's edge.
        if (preg_match('~^/\.well-known/~i', $path) || preg_match('~' . $rules['files'] . '~', $path) || preg_match('~^/cdn-cgi(?:/|$)~i', $path)) {
            return '';
        }
        // The other form of the slash reaches WP, which redirects to the form the rules serve.
        if ('/' !== $path) {
            $path = $rules['slash'] ? trailingslashit($path) : untrailingslashit($path);
        }
        foreach ($rules['excluded'] as $excluded) {
            $excluded = trim((string) $excluded, '/');
            if ('' === $excluded) {
                if ('/' === $path) {
                    return '';
                }
                continue;
            }
            if (preg_match('~^/' . preg_quote($excluded, '~') . '(?:/|$)~i', $path)) {
                return '';
            }
        }
        if ('/' !== $path && isset($rules['redirects'][untrailingslashit($path)])) {
            return '';
        }
        return $path;
    }

    /** A broken route in the report: the first LINK_CHECK_MAX_LISTED with their pages, then only counted. */
    private function link_check_record(&$report, $route, $page)
    {
        if (isset($report['broken'][$route])) {
            if (count($report['broken'][$route]) < self::LINK_CHECK_MAX_SOURCES && !in_array($page, $report['broken'][$route], true)) {
                $report['broken'][$route][] = $page;
            }
            return;
        }
        $hash = substr(sha1($route), 0, 12);
        if (isset($report['counted'][$hash])) {
            return;
        }
        if (count($report['broken']) < self::LINK_CHECK_MAX_LISTED) {
            $report['broken'][$route] = array($page);
        } elseif (count($report['counted']) < self::LINK_CHECK_MAX_COUNTED) {
            $report['counted'][$hash] = 1;
        } else {
            $report['capped'] = true;
            return;
        }
        $report['total']++;
    }

    /**
     * The folders of the pages of a release after $cursor (null: from the start), in a fixed order: a folder's page
     * before its subfolders, subfolders sorted byte by byte. Never follows a symlink and skips the folders whose
     * pages all come before the cursor, so a chunk does not read the release again from the start.
     *
     * @return Generator<string[]> The path segments of each folder with an index.html.
     */
    private function link_check_walk($directory, array $segments, $cursor)
    {
        $page = $directory . '/index.html';
        if ((null === $cursor || $this->link_check_compare($segments, $cursor) > 0) && !is_link($page) && is_file($page)) {
            yield $segments;
        }
        $entries = @scandir($directory, SCANDIR_SORT_NONE);
        if (!is_array($entries)) {
            return;
        }
        sort($entries, SORT_STRING);
        foreach ($entries as $entry) {
            $entry = (string) $entry;
            if ('' === $entry || '.' === $entry[0]) {
                continue;
            }
            $child = $directory . '/' . $entry;
            if (is_link($child) || !is_dir($child)) {
                continue;
            }
            $child_segments = $segments;
            $child_segments[] = $entry;
            if (null !== $cursor && $this->link_check_compare($child_segments, $cursor) < 0
                && $child_segments !== array_slice($cursor, 0, count($child_segments))) {
                continue;
            }
            yield from $this->link_check_walk($child, $child_segments, $cursor);
        }
    }

    /** Compares two lists of path segments in the order of link_check_walk(): -1, 0 or 1. */
    private function link_check_compare(array $left, array $right)
    {
        $length = min(count($left), count($right));
        for ($i = 0; $i < $length; $i++) {
            $compared = strcmp((string) $left[$i], (string) $right[$i]);
            if (0 !== $compared) {
                return $compared < 0 ? -1 : 1;
            }
        }
        return count($left) <=> count($right);
    }

    /** The HTML of one page of the release, or null when it is a symlink, outside the release, empty or too large. */
    private function link_check_read_page($release, array $segments)
    {
        $file = $release . '/' . (empty($segments) ? '' : implode('/', $segments) . '/') . 'index.html';
        if (is_link($file) || !is_file($file)) {
            return null;
        }
        $size = @filesize($file);
        $real = realpath($file);
        if (false === $size || $size < 1 || $size > self::MAX_HTML_PAGE_SIZE || !$real || 0 !== strpos($real, trailingslashit($release))) {
            return null;
        }
        $html = @file_get_contents($real);
        return is_string($html) ? $html : null;
    }

    /** The route of a page of the release from its folder, in the form WP links it. */
    private function link_check_page_route(array $segments, $slash)
    {
        if (empty($segments)) {
            return '/';
        }
        return '/' . implode('/', $segments) . ($slash ? '/' : '');
    }

    /** The URL of a decoded route, with each segment encoded again. */
    private function link_check_route_url($route)
    {
        $route = (string) $route;
        $trimmed = trim($route, '/');
        if ('' === $trimmed) {
            return home_url('/');
        }
        return home_url('/' . implode('/', array_map('rawurlencode', explode('/', $trimmed))) . ('/' === substr($route, -1) ? '/' : ''));
    }

    /** The last check, as `wp static-bridge status` says it: release, state, pages read, broken routes. */
    private function link_check_summary()
    {
        $report = get_option(self::LINK_CHECK_OPTION, array());
        if (!is_array($report) || empty($report['release'])) {
            return array('release' => '', 'status' => 'none', 'pages' => 0, 'broken' => 0, 'capped' => false, 'finished_at' => 0);
        }
        return array(
            'release' => (string) $report['release'],
            'status' => in_array($report['status'] ?? '', array('queued', 'running', 'complete', 'stopped'), true) ? (string) $report['status'] : 'none',
            'pages' => max(0, (int) ($report['pages'] ?? 0)),
            'broken' => max(0, (int) ($report['total'] ?? 0)),
            'capped' => !empty($report['capped']),
            'finished_at' => max(0, (int) ($report['finished_at'] ?? 0)),
        );
    }

    /** Genera, «Controlla di nuovo i link»: a new check of the current release (manage_options and nonce). */
    public function handle_link_check()
    {
        if (!current_user_can('manage_options')) {
            wp_die(esc_html__('Non hai i permessi necessari.', 'static-bridge'), '', array('response' => 403));
        }
        check_admin_referer('static_bridge_link_check');
        $status = $this->schedule_link_check(0);
        wp_safe_redirect(add_query_arg(array('page' => self::ADMIN_SLUG, 'tab' => 'generate', 'link-check' => $status), admin_url('admin.php')));
        exit;
    }

    /** Genera: the card of the link check of the current release, with the button for an administrator. */
    private function render_link_check_card($release, $full_access)
    {
        if ('' === (string) $release) {
            return;
        }
        $strict = $this->strict_marker_active();
        $report = get_option(self::LINK_CHECK_OPTION, array());
        $report = is_array($report) && basename((string) $release) === (string) ($report['release'] ?? '') ? $report : array();
        $status = (string) ($report['status'] ?? '');
        $total = max(0, (int) ($report['total'] ?? 0));
        $broken = isset($report['broken']) && is_array($report['broken']) ? $report['broken'] : array();
        ?>
        <section class="sb-card sb-link-check-card" id="sb-link-check">
            <?php if (!$strict) : ?>
                <h2><?php esc_html_e('Controllo dei link', 'static-bridge'); ?></h2>
                <p><?php esc_html_e('Il controllo dei link serve solo con la modalità strict: senza, una rotta che non ha una copia statica la serve WordPress, e nessun link interno porta a un 404 del server.', 'static-bridge'); ?></p>
            <?php elseif ('complete' === $status && $total > 0) : ?>
                <h2><?php echo esc_html(sprintf(/* translators: %s: number of routes */ _n('%s rotta linkata senza copia statica', '%s rotte linkate senza copia statica', $total, 'static-bridge'), $this->link_check_total_label($report))); ?></h2>
                <p><?php esc_html_e('Con la modalità strict il server risponde 404 a queste rotte, e le pagine indicate le linkano. Se una rotta deve restare a WordPress, escludila nelle Impostazioni; altrimenti correggi il link o avvia un export completo.', 'static-bridge'); ?></p>
                <ul class="sb-path-list sb-link-check-list">
                    <?php foreach ($broken as $route => $pages) : ?>
                        <li><code><?php echo esc_html((string) $route); ?></code> — <?php esc_html_e('linkata da', 'static-bridge'); ?>
                            <?php foreach (array_values((array) $pages) as $index => $page) : ?><?php echo $index > 0 ? ', ' : ' '; ?><a href="<?php echo esc_url($this->link_check_route_url($page)); ?>" target="_blank" rel="noopener noreferrer"><?php echo esc_html((string) $page); ?></a><?php endforeach; ?>
                        </li>
                    <?php endforeach; ?>
                </ul>
                <?php if ($total > count($broken)) : ?>
                    <p><?php echo esc_html(sprintf(/* translators: %s: number of routes listed */ __('Sono elencate le prime %s.', 'static-bridge'), number_format_i18n(count($broken)))); ?></p>
                <?php endif; ?>
                <p class="sb-action-note"><?php echo esc_html(sprintf(/* translators: 1: number of pages read, 2: date and time */ __('%1$s pagine lette, controllo finito il %2$s.', 'static-bridge'), number_format_i18n((int) ($report['pages'] ?? 0)), $this->format_site_datetime((int) ($report['finished_at'] ?? 0)))); ?></p>
            <?php elseif ('complete' === $status) : ?>
                <h2><?php esc_html_e('Nessun link interno rotto', 'static-bridge'); ?></h2>
                <p><?php echo esc_html(sprintf(/* translators: 1: number of pages read, 2: date and time */ __('%1$s pagine lette, controllo finito il %2$s: ogni rotta linkata ha una copia statica o la serve WordPress.', 'static-bridge'), number_format_i18n((int) ($report['pages'] ?? 0)), $this->format_site_datetime((int) ($report['finished_at'] ?? 0)))); ?></p>
            <?php elseif (in_array($status, array('queued', 'running'), true)) : ?>
                <h2><?php esc_html_e('Controllo dei link in corso', 'static-bridge'); ?></h2>
                <p><?php echo esc_html(sprintf(/* translators: %s: number of pages read */ __('%s pagine lette finora. Il controllo gira in background, a blocchi; ricarica la pagina per vedere l’esito.', 'static-bridge'), number_format_i18n((int) ($report['pages'] ?? 0)))); ?></p>
            <?php else : ?>
                <h2><?php esc_html_e('Controllo dei link', 'static-bridge'); ?></h2>
                <p><?php esc_html_e('Questa versione non è stata controllata fino in fondo. Il controllo parte da solo dopo ogni export completo pubblicato con la modalità strict: legge le pagine della versione e cerca i link interni a rotte senza copia statica, che il server farebbe rispondere 404.', 'static-bridge'); ?></p>
            <?php endif; ?>
            <?php if ($strict && $full_access) : ?>
                <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>">
                    <input type="hidden" name="action" value="static_bridge_link_check">
                    <?php wp_nonce_field('static_bridge_link_check'); ?>
                    <button type="submit" class="button"><span class="dashicons dashicons-admin-links" aria-hidden="true"></span> <?php esc_html_e('Controlla di nuovo i link', 'static-bridge'); ?></button>
                </form>
            <?php endif; ?>
        </section>
        <?php
    }

    /** How many folders a cleanup from «Versioni» would delete now (one previous release kept); no sizes, for the notice. */
    private function release_cleanup_count()
    {
        $plan = $this->release_retention_plan(self::RETENTION_NEW_SITE_KEEP);
        if (empty($plan['ok'])) {
            return 0;
        }
        return count(array_filter($plan['entries'], function ($entry) {
            return 'delete' === $entry['action'];
        }));
    }

    /** The «Versioni» tab: every folder of releases/ as a block, what may go and why the rest stays. */
    private function render_versions_tab($settings)
    {
