                    <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>" class="sb-card-actions" data-sb-confirm="<?php echo esc_attr(sprintf(/* translators: %s: number of folders */ _n('Eliminare %s versione che non serve? Non si può annullare.', 'Eliminare %s versioni che non servono? Non si può annullare.', $inventory['cleanup'], 'static-bridge'), number_format_i18n($inventory['cleanup']))); ?>">
                        <input type="hidden" name="action" value="static_bridge_cleanup_releases">
                        <?php wp_nonce_field('static_bridge_cleanup_releases'); ?>
                        <button type="submit" class="button"><?php echo esc_html(sprintf(/* translators: 1: number of folders, 2: size */ _n('Elimina %1$s versione che non serve (%2$s)', 'Elimina le %1$s versioni che non servono (%2$s)', $inventory['cleanup'], 'static-bridge'), number_format_i18n($inventory['cleanup']), $size($inventory['deletable_bytes']))); ?></button>
