                                    <button type="submit" class="button button-link-delete"><?php esc_html_e('Elimina', 'static-bridge'); ?></button>
                                </form>
                            <?php else : ?>
                                <p class="sb-version-reason"><span class="dashicons dashicons-lock" aria-hidden="true"></span> <?php echo esc_html('' !== $item['reason'] ? $item['reason'] : __('Non si elimina da qui', 'static-bridge')); ?></p>
                            <?php endif; ?>
                        </article>
                    <?php endforeach; ?>
                </div>
                <p class="description"><?php esc_html_e('Ogni eliminazione rifà i controlli al momento, sotto lock: la versione online e quelle protette (ripristino dopo un’importazione, export in corso o in pausa, indici V2 e SSI) non si eliminano mai. Niente fuori da releases/ viene toccato.', 'static-bridge'); ?></p>
            <?php endif; ?>
            <?php if (is_array($last) && !empty($last['message'])) : ?>
                <p class="description"><?php echo esc_html(sprintf(/* translators: 1: automatic or manual, 2: date and time, 3: result message */ __('Ultima pulizia (%1$s, %2$s): %3$s', 'static-bridge'), 'cron' === ($last['trigger'] ?? '') ? __('automatica', 'static-bridge') : __('manuale', 'static-bridge'), $this->format_site_datetime((int) ($last['time'] ?? 0)), $last['message'])); ?></p>
            <?php endif; ?>
        </section>
        <?php
    }

    /** «Versioni»: delete one release, staging or interrupted deletion (a POST from the tab, with its own nonce). */
    public function handle_delete_release()
    {
        if (!current_user_can('manage_options')) {
            wp_die(esc_html__('Non hai i permessi necessari.', 'static-bridge'), '', array('response' => 403));
        }
        $name = isset($_POST['release']) ? (string) wp_unslash($_POST['release']) : '';
        // Only a direct child of releases/ by its own name: no separator, no dot segment, no other folder.
        if (!preg_match('/\A[A-Za-z0-9_-]{1,100}(?:\.sb-retention-[a-f0-9]{12})?\z/D', $name)) {
            wp_die(esc_html__('Versione non valida.', 'static-bridge'), '', array('response' => 400));
        }
        check_admin_referer('static_bridge_delete_release_' . $name);
        $result = $this->apply_release_retention('versions', array($name));
        wp_safe_redirect(add_query_arg(array('page' => self::ADMIN_SLUG, 'tab' => 'versions', 'versions-run' => $result['status']), admin_url('admin.php')));
        exit;
    }

    /** «Versioni»: delete everything the plan does not keep, also with retention off (one previous release stays). */
    public function handle_cleanup_releases()
    {
        if (!current_user_can('manage_options')) {
            wp_die(esc_html__('Non hai i permessi necessari.', 'static-bridge'), '', array('response' => 403));
        }
        check_admin_referer('static_bridge_cleanup_releases');
        $result = $this->apply_release_retention('versions');
        wp_safe_redirect(add_query_arg(array('page' => self::ADMIN_SLUG, 'tab' => 'versions', 'versions-run' => $result['status']), admin_url('admin.php')));
        exit;
    }

    /** «Versioni» on a site upgraded with retention off: turn it on, keeping one previous release, and clean up soon. */
    public function handle_enable_retention()
    {
        if (!current_user_can('manage_options')) {
            wp_die(esc_html__('Non hai i permessi necessari.', 'static-bridge'), '', array('response' => 403));
        }
        check_admin_referer('static_bridge_enable_retention');
        $stored = get_option(self::SETTINGS_OPTION, array());
        $stored = is_array($stored) ? $stored : array();
        $stored['retention_enabled'] = 1;
        $stored['retention_keep'] = self::RETENTION_NEW_SITE_KEEP;
        update_option(self::SETTINGS_OPTION, $stored, false);
        $this->log_activity(
            __('Conservazione delle release attivata da Versioni.', 'static-bridge'),
            __('Dopo ogni pubblicazione riuscita restano la versione online, una precedente e quelle protette; le altre e gli staging falliti o annullati vengono eliminati.', 'static-bridge')
        );
        $this->schedule_release_retention(60);
        wp_safe_redirect(add_query_arg(array('page' => self::ADMIN_SLUG, 'tab' => 'versions', 'retention-enabled' => 1), admin_url('admin.php')));
        exit;
    }

    /**
     * «Versioni»: the plan with, for each entry, its state, pages, size and whether it may be deleted by hand.
     * Sizes walk the folder without following links, within a short budget; those of releases that no longer
     * change (not online) are kept in a transient by name and .ready time.
     *
     * @return array{ok: bool, error: string, current: string, keep: int, items: array, deletable: int, deletable_bytes: int, total_bytes: int, sized: bool}
     */
    private function release_inventory()
    {
        $settings = $this->settings();
        $keep = empty($settings['retention_enabled']) ? self::RETENTION_NEW_SITE_KEEP : $settings['retention_keep'];
        $plan = $this->release_retention_plan($keep);
        $inventory = array('ok' => !empty($plan['ok']), 'error' => (string) $plan['error'], 'current' => (string) $plan['current'], 'keep' => $keep,
            'items' => array(), 'deletable' => 0, 'deletable_bytes' => 0, 'total_bytes' => 0, 'sized' => true, 'cleanup' => 0);
        if (empty($plan['ok'])) {
            return $inventory;
        }
        $release_root = $this->safe_release_root(false);
        $job = get_option(self::JOB_OPTION, array());
        $job_stage = is_array($job) && isset($job['stage']) && is_string($job['stage']) ? basename($job['stage']) : '';
        $job_status = is_array($job) ? (string) ($job['status'] ?? '') : '';
        $cache = get_transient(self::RELEASE_SIZES_TRANSIENT);
        $cache = is_array($cache) ? $cache : array();
        $fresh_cache = array();
        $deadline = microtime(true) + 3;
        foreach ($plan['entries'] as $entry) {
            $path = $release_root . '/' . $entry['name'];
            $item = $entry + array('state' => 'other', 'pages' => null, 'bytes' => null, 'deletable' => false);
            if ($entry['name'] === $plan['current']) {
                $item['state'] = 'online';
            } elseif ('ready' === $entry['kind']) {
                $item['state'] = 'previous';
            } elseif ('staging' === $entry['kind']) {
                $item['state'] = $entry['name'] === $job_stage && in_array($job_status, array('running', 'paused'), true) ? $job_status : 'staging';
            } elseif ('trash' === $entry['kind']) {
                $item['state'] = 'trash';
            }
            if ('ready' === $entry['kind'] || 'staging' === $entry['kind']) {
                $manifest = @file_get_contents($path . '/manifest.json', false, null, 0, 1048576);
                $manifest = is_string($manifest) ? json_decode($manifest, true) : null;
                if (is_array($manifest) && isset($manifest['pages_saved'])) {
                    $item['pages'] = max(0, (int) $manifest['pages_saved']);
                }
            }
            if ('ignored' !== $entry['kind']) {
                $cache_key = $entry['name'] . '|' . (int) $entry['time'];
                if ('online' !== $item['state'] && 'ready' === $entry['kind'] && isset($cache[$cache_key]) && is_int($cache[$cache_key])) {
                    $item['bytes'] = $cache[$cache_key];
                } elseif (microtime(true) < $deadline) {
                    $bytes = $this->release_tree_bytes($path, $deadline);
                    $item['bytes'] = $bytes;
                    if (null !== $bytes && 'online' !== $item['state'] && 'ready' === $entry['kind']) {
                        $fresh_cache[$cache_key] = $bytes;
                    }
                }
                if (null === $item['bytes']) {
                    $inventory['sized'] = false;
                }
                if ('ready' === $entry['kind'] && isset($cache[$cache_key]) && !isset($fresh_cache[$cache_key])) {
                    $fresh_cache[$cache_key] = $cache[$cache_key];
                }
            }
            $item['deletable'] = $this->release_entry_deletable($entry, $plan['current']);
            $inventory['total_bytes'] += (int) $item['bytes'];
            if ('delete' === $entry['action']) {
                $inventory['cleanup']++;
                $inventory['deletable_bytes'] += (int) $item['bytes'];
            }
            if ($item['deletable']) {
                $inventory['deletable']++;
            }
            $inventory['items'][] = $item;
        }
        if ($fresh_cache !== $cache) {
            set_transient(self::RELEASE_SIZES_TRANSIENT, array_slice($fresh_cache, -200, null, true), DAY_IN_SECONDS);
        }
        // Online first, then an export that goes on, the previous versions from the newest, the leftovers last.
        $rank = array_flip(array('online', 'running', 'paused', 'previous', 'staging', 'trash', 'other'));
        usort($inventory['items'], function ($left, $right) use ($rank) {
            return array($rank[$left['state']] ?? 9, $right['time'], $right['name']) <=> array($rank[$right['state']] ?? 9, $left['time'], $left['name']);
        });
        return $inventory;
    }

    /** Bytes of the regular files under $directory, never following a link; null when $deadline passes first. */
    private function release_tree_bytes($directory, $deadline, $depth = 0)
    {
        if ($depth > 64 || is_link($directory) || !is_dir($directory)) {
            return 0;
        }
        $names = @scandir($directory);
        if (!is_array($names)) {
            return 0;
        }
        $bytes = 0;
        foreach ($names as $name) {
            if ('.' === $name || '..' === $name) {
                continue;
            }
            if (microtime(true) >= $deadline) {
                return null;
            }
            $path = $directory . '/' . $name;
            $stat = @lstat($path);
            if (!is_array($stat)) {
                continue;
            }
            $type = $stat['mode'] & 0170000;
            if (0040000 === $type) {
                $inner = $this->release_tree_bytes($path, $deadline, $depth + 1);
                if (null === $inner) {
                    return null;
                }
                $bytes += $inner;
            } elseif (0100000 === $type) {
                $bytes += (int) $stat['size'];
            }
        }
        return $bytes;
    }

    /**
     * Read-only retention decision for every entry of the release root. Only
     * entries positively identified as an expired plugin release, an
     * abandoned plugin staging folder or this routine's own interrupted trash
     * are marked for deletion; everything else is kept or ignored.
     */
    private function release_retention_plan($keep)
    {
        $keep = $this->sanitize_retention_keep($keep);
        $plan = array('ok' => false, 'error' => '', 'current' => '', 'keep' => $keep, 'entries' => array());
        $release_root = $this->safe_release_root(false);
        if ('' === $release_root) {
            $plan['error'] = __('La cartella delle release manca, non è nel percorso previsto o è un collegamento simbolico.', 'static-bridge');
            return $plan;
        }
        $current = $this->current_release();
        if ('' === $current) {
            $plan['error'] = __('Il puntatore current non indica una release valida: senza una release attiva verificata non viene eliminato nulla.', 'static-bridge');
            return $plan;
        }
        $current_id = basename($current);
        $plan['current'] = $current_id;

        $dependency_keys = (new Static_Bridge_Dependency_Index())->referenced_release_keys();
        $fragment_keys = (new Static_Bridge_Header_Fragment_Index())->referenced_release_keys();
        if (!is_array($dependency_keys) || !is_array($fragment_keys)) {
            $plan['error'] = __('Gli indici V2 o dei frammenti header non sono leggibili: impossibile escludere le release ancora referenziate.', 'static-bridge');
            return $plan;
        }
        $dependency_keys = array_flip($dependency_keys);
        $fragment_keys = array_flip($fragment_keys);

        $protected = array();
        $protect = function ($release_id, $reason) use (&$protected) {
            if (is_string($release_id) && '' !== $release_id && !isset($protected[$release_id])) {
                $protected[$release_id] = $reason;
            }
        };
        $last_release = get_option('static_bridge_last_release', array());
        if (is_array($last_release)) {
            $protect($last_release['id'] ?? '', __('Release registrata per il ripristino dopo l’importazione All-in-One', 'static-bridge'));
        }
        $job = get_option(self::JOB_OPTION, array());
        // Only an export that can still go on needs its folder: a failed or cancelled one never resumes.
        if (is_array($job) && in_array($job['status'] ?? '', array('running', 'paused'), true)) {
            $job_reason = __('Cartella dell’esportazione in corso o in pausa', 'static-bridge');
            $protect($job['release_id'] ?? '', $job_reason);
            if (isset($job['stage']) && is_string($job['stage'])) {
                $protect(basename($job['stage']), $job_reason);
            }
        }
        $render_transaction = get_option(self::RENDER_BYPASS_OPTION, false);
        if (is_array($render_transaction)) {
            $protect($render_transaction['release_id'] ?? '', __('Release di una transazione di rendering in corso', 'static-bridge'));
        }
        $ssi_reason = __('Release di riferimento per la verifica SSI', 'static-bridge');
        $protect(get_option('static_bridge_ssi_safe_release', ''), $ssi_reason);
        $ssi_probe = get_option('static_bridge_ssi_last_probe', array());
        if (is_array($ssi_probe)) {
            $protect($ssi_probe['release'] ?? '', $ssi_reason);
        }

        $names = @scandir($release_root);
        if (!is_array($names)) {
            $plan['error'] = __('Impossibile leggere la cartella delle release.', 'static-bridge');
            return $plan;
        }
        $now = time();
        $ranked = array();
        foreach ($names as $name) {
            if ('.' === $name || '..' === $name) {
                continue;
            }
            $path = $release_root . '/' . $name;
            clearstatcache(true, $path);
            $entry = array('name' => $name, 'kind' => 'ignored', 'time' => 0, 'action' => 'ignore', 'reason' => '', 'protected' => false);
            $is_trash = (bool) preg_match('/\A([A-Za-z0-9_-]{1,100})\.sb-retention-[a-f0-9]{12}\z/D', $name, $trash_match);
            if (is_link($path) || !is_dir($path) || realpath($path) !== $path
                || (!$is_trash && !preg_match('/\A[A-Za-z0-9_-]{1,100}\z/D', $name))) {
                $entry['reason'] = __('Non creato da Static Bridge o collegamento simbolico: ignorato', 'static-bridge');
                $plan['entries'][] = $entry;
                continue;
            }
            $stat = @lstat($path);
            $entry['time'] = is_array($stat) ? (int) $stat['mtime'] : 0;
            if ($is_trash) {
                $entry['kind'] = 'trash';
                if ($name === $current_id || $trash_match[1] === $current_id) {
                    $entry['action'] = 'keep';
                    $entry['protected'] = true;
                    $entry['reason'] = __('Release attiva (current)', 'static-bridge');
                } else {
                    $entry['action'] = 'delete';
                    $entry['reason'] = __('Eliminazione interrotta da completare', 'static-bridge');
                }
                $plan['entries'][] = $entry;
                continue;
            }
            $ready_file = $path . '/.ready';
            if (is_link($ready_file) || (file_exists($ready_file) && !is_file($ready_file))) {
                $entry['reason'] = __('Marcatore .ready non regolare: ignorato', 'static-bridge');
                $plan['entries'][] = $entry;
                continue;
            }
            $entry['kind'] = is_file($ready_file) ? 'ready' : 'staging';
            if ('ready' === $entry['kind']) {
                $ready_stat = @lstat($ready_file);
                $entry['time'] = is_array($ready_stat) ? (int) $ready_stat['mtime'] : 0;
            }
            $entry['action'] = 'keep';
            $entry['protected'] = true;
            $key = hash('sha256', $name);
            if ($name === $current_id) {
                $entry['reason'] = __('Release attiva (current)', 'static-bridge');
            } elseif (isset($protected[$name])) {
                $entry['reason'] = $protected[$name];
            } elseif (isset($dependency_keys[$key])) {
                $entry['reason'] = __('Referenziata dall’indice dipendenze V2', 'static-bridge');
            } elseif (isset($fragment_keys[$key])) {
                $entry['reason'] = __('Referenziata dall’indice dei frammenti header SSI', 'static-bridge');
            } elseif ($entry['time'] <= 0) {
                $entry['reason'] = __('Data non verificabile: conservata', 'static-bridge');
            } elseif ('staging' === $entry['kind']) {
                $entry['protected'] = false;
                if ($now - $entry['time'] < self::RETENTION_STAGING_GRACE) {
                    $entry['reason'] = __('Staging recente (meno di un’ora): conservato', 'static-bridge');
                } else {
                    $entry['action'] = 'delete';
                    $entry['reason'] = __('Staging abbandonato senza marcatore .ready', 'static-bridge');
                }
            } else {
                $entry['protected'] = false;
                $ranked[] = count($plan['entries']);
            }
            $plan['entries'][] = $entry;
        }

        // Newest ready releases first; IDs begin with a UTC timestamp, so the
        // name breaks ties between releases committed in the same second.
        usort($ranked, function ($left, $right) use ($plan) {
            $a = $plan['entries'][$left];
            $b = $plan['entries'][$right];
            return $a['time'] === $b['time'] ? strcmp($b['name'], $a['name']) : $b['time'] <=> $a['time'];
        });
        foreach ($ranked as $position => $entry_index) {
            if ($position < $keep) {
                $plan['entries'][$entry_index]['reason'] = sprintf(/* translators: %s: number of previous releases to keep */ __('Tra le %s release pronte più recenti', 'static-bridge'), number_format_i18n($keep));
            } else {
                $plan['entries'][$entry_index]['action'] = 'delete';
                $plan['entries'][$entry_index]['reason'] = __('Release precedente oltre il limite di conservazione', 'static-bridge');
            }
        }
        usort($plan['entries'], function ($left, $right) {
            return strcmp($right['name'], $left['name']);
        });
        $plan['ok'] = true;
        return $plan;
    }

    /**
     * Apply the retention plan under the export worker lock, the render lock
     * and the incremental worker lock. Any active export, render transaction,
     * diagnostic or unsafe pointer makes the run stop without deleting.
     */
    private function apply_release_retention($trigger = 'manual', $only = array())
    {
        $settings = $this->settings();
        $only = array_values(array_unique(array_filter(array_map('strval', (array) $only))));
        $result = array(
            'status' => 'disabled',
            'trigger' => in_array($trigger, array('cron', 'manual', 'versions'), true) ? $trigger : 'manual',
            'time' => time(),
            // From «Versioni» the cleanup also runs with retention off, keeping one previous release.
            'keep' => empty($settings['retention_enabled']) ? self::RETENTION_NEW_SITE_KEEP : $settings['retention_keep'],
            'deleted' => array(),
            'failed' => array(),
            'refused' => array(),
            'only' => !empty($only),
            'bytes' => 0,
            'message' => '',
        );
        if (empty($settings['retention_enabled']) && 'versions' !== $result['trigger']) {
            $result['message'] = __('Conservazione delle release disattivata: nessuna cartella è stata eliminata.', 'static-bridge');
            return $result;
        }

        $export_lock = $this->acquire_export_worker_lock();
        if (false === $export_lock) {
            return $this->finish_release_retention($result, 'busy', __('Un worker di esportazione è attivo.', 'static-bridge'));
        }
        $render_lock = null;
        $incremental_lock = '';
        try {
            $job = get_option(self::JOB_OPTION, array());
            if (is_array($job) && isset($job['status']) && 'running' === $job['status']) {
                return $this->finish_release_retention($result, 'busy', __('È in corso un’esportazione completa.', 'static-bridge'));
            }
            if (false !== $this->render_bypass_transaction_row()) {
                return $this->finish_release_retention($result, 'busy', __('Una transazione di rendering non è ancora conclusa.', 'static-bridge'));
            }
            if ($this->diagnostic_is_running()) {
                return $this->finish_release_retention($result, 'busy', __('È in corso una diagnostica.', 'static-bridge'));
            }
            $render_lock = $this->acquire_render_bypass_lock();
            if (is_wp_error($render_lock)) {
                $message = 'static_bridge_render_busy' === $render_lock->get_error_code()
                    ? __('Un rendering interno è in corso.', 'static-bridge')
                    : $render_lock->get_error_message();
                $status = 'static_bridge_render_busy' === $render_lock->get_error_code() ? 'busy' : 'error';
                $render_lock = null;
                return $this->finish_release_retention($result, $status, $message);
            }
            $incremental_lock = $this->acquire_incremental_lock();
            if (false === $incremental_lock) {
                $incremental_lock = '';
                return $this->finish_release_retention($result, 'busy', __('Il worker incrementale o un push è in esecuzione.', 'static-bridge'));
            }

            $plan = $this->release_retention_plan($result['keep']);
            if (empty($plan['ok'])) {
                return $this->finish_release_retention($result, 'error', $plan['error']);
            }
            $release_root = $this->safe_release_root(false);
            $deadline = microtime(true) + self::RETENTION_TIME_BUDGET;
            $status = 'complete';
            $planned = array();
            foreach ($plan['entries'] as $entry) {
                $planned[$entry['name']] = $entry;
            }
            foreach ($only as $name) {
                // A name the plan does not know (gone, invented, outside releases/) or a protected one: never deleted.
                if (!isset($planned[$name]) || !$this->release_entry_deletable($planned[$name], $plan['current'])) {
                    $result['refused'][] = isset($planned[$name]) && '' !== $planned[$name]['reason']
                        ? array('name' => $name, 'reason' => $planned[$name]['reason'])
                        : array('name' => $name, 'reason' => __('Non è una versione di Static Bridge in questa cartella', 'static-bridge'));
                }
            }
            foreach ($plan['entries'] as $entry) {
                if (!empty($only)) {
                    if (!in_array($entry['name'], $only, true) || !$this->release_entry_deletable($entry, $plan['current'])) {
                        continue;
                    }
                } elseif ('delete' !== $entry['action']) {
                    continue;
                }
                if (microtime(true) >= $deadline) {
                    $status = 'partial';
                    break;
                }
                $outcome = $this->delete_retention_entry($release_root, $entry['name'], $plan['current'], $deadline, $result['bytes']);
                if ('done' === $outcome) {
                    $result['deleted'][] = $entry['name'];
                } elseif ('timeout' === $outcome) {
                    $status = 'partial';
                    break;
                } else {
                    $result['failed'][] = $entry['name'];
                }
            }
            return $this->finish_release_retention($result, $status, '');
        } finally {
            if ('' !== $incremental_lock) {
                $this->release_incremental_lock($incremental_lock);
            }
            if (is_array($render_lock)) {
                $this->release_render_bypass_lock($render_lock['handle']);
            }
            $this->release_export_worker_lock($export_lock);
        }
    }

    /** One entry of the plan someone may delete by hand: a release, a staging or a trash, never protected or online. */
    private function release_entry_deletable($entry, $current_id)
    {
        return is_array($entry) && in_array($entry['kind'] ?? '', array('ready', 'staging', 'trash'), true)
            && empty($entry['protected']) && '' !== (string) $current_id && ($entry['name'] ?? '') !== $current_id;
    }

    /**
     * Move one direct child of the release root to a private trash name, then
     * delete it without following symlinks. Returns done, timeout or failed.
     */
    private function delete_retention_entry($release_root, $name, $current_id, $deadline, &$bytes)
    {
        $is_trash = (bool) preg_match('/\A([A-Za-z0-9_-]{1,100})\.sb-retention-[a-f0-9]{12}\z/D', (string) $name, $trash_match);
        if ('' === $release_root || ('' === $current_id)
            || (!$is_trash && !preg_match('/\A[A-Za-z0-9_-]{1,100}\z/D', (string) $name))
            || $name === $current_id || ($is_trash && $trash_match[1] === $current_id)) {
            return 'failed';
        }
        // Re-resolve both roots: the plan was computed a moment ago.
        if ($this->safe_release_root(false) !== $release_root) {
            return 'failed';
        }
        $current = $this->current_release();
        $path = $release_root . '/' . $name;
        clearstatcache(true, $path);
        if ('' === $current || basename($current) !== $current_id || $current === $path
            || is_link($path) || !is_dir($path) || realpath($path) !== $path) {
            return 'failed';
        }
        $trash = $path;
        if (!$is_trash) {
            $trash = $path . '.sb-retention-' . bin2hex(random_bytes(6));
            if (file_exists($trash) || is_link($trash) || !@rename($path, $trash)) {
                return 'failed';
            }
        }
        clearstatcache(true, $trash);
        if (is_link($trash) || !is_dir($trash) || realpath($trash) !== $trash || dirname($trash) !== $release_root) {
            return 'failed';
        }
        return $this->remove_retention_tree($trash, $deadline, $bytes, 0);
    }

    private function remove_retention_tree($directory, $deadline, &$bytes, $depth)
    {
        if ($depth > 64) {
            return 'failed';
        }
        $names = @scandir($directory);
        if (!is_array($names)) {
            return 'failed';
        }
        foreach ($names as $name) {
            if ('.' === $name || '..' === $name) {
                continue;
            }
            if (microtime(true) >= $deadline) {
                return 'timeout';
            }
            $child = $directory . '/' . $name;
            clearstatcache(true, $child);
            if (is_link($child)) {
                // Remove the link itself; its target is never visited.
                if (!@unlink($child)) {
                    return 'failed';
                }
                continue;
            }
            if (is_dir($child)) {
                if (realpath($child) !== $child) {
                    return 'failed';
                }
                $outcome = $this->remove_retention_tree($child, $deadline, $bytes, $depth + 1);
                if ('done' !== $outcome) {
                    return $outcome;
                }
                continue;
            }
            $stat = @lstat($child);
            if (!@unlink($child)) {
                return 'failed';
            }
            // A file still linked from an Apache served copy frees nothing yet.
            $bytes += is_array($stat) && (int) $stat['nlink'] <= 1 ? (int) $stat['size'] : 0;
        }
        return @rmdir($directory) ? 'done' : 'failed';
    }

    private function finish_release_retention($result, $status, $message)
    {
        $result['status'] = $status;
        $deleted = count($result['deleted']);
        $mebibytes = number_format_i18n($result['bytes'] / 1048576, 1);
        $listed = implode(', ', array_slice($result['deleted'], 0, 10)) . ($deleted > 10 ? ', …' : '');
        if ('busy' === $status) {
            $result['message'] = sprintf(/* translators: %s: reason (a sentence) */ __('Pulizia rinviata: %s Nessuna cartella è stata eliminata.', 'static-bridge'), $message);
            $this->log_activity(__('Pulizia release rinviata.', 'static-bridge'), $result['message']);
        } elseif ('error' === $status) {
            $result['message'] = sprintf(/* translators: %s: reason (a sentence) */ __('Pulizia non eseguita: %s Nessuna cartella è stata eliminata.', 'static-bridge'), $message);
            $this->log_activity(__('Pulizia release non eseguita.', 'static-bridge'), $result['message'], true);
        } else {
            $result['message'] = 0 === $deleted
                ? (!empty($result['refused']) ? __('Nessuna cartella eliminata.', 'static-bridge') : sprintf(/* translators: %s: number of previous releases to keep */ __('Nessuna cartella da eliminare. Conservate la release attiva, le %s release pronte più recenti e tutte le release protette.', 'static-bridge'), number_format_i18n($result['keep'])))
                : (!empty($result['only'])
                    ? sprintf(/* translators: 1: number of deleted folders, 2: list of folder names, 3: freed space in MiB */ __('Eliminate %1$s cartelle (%2$s), circa %3$s MiB liberati.', 'static-bridge'), number_format_i18n($deleted), $listed, $mebibytes)
                    : sprintf(/* translators: 1: number of deleted folders, 2: list of folder names, 3: freed space in MiB, 4: number of previous releases to keep */ __('Eliminate %1$s cartelle (%2$s), circa %3$s MiB liberati. Conservate la release attiva, le %4$s release pronte più recenti e tutte le release protette.', 'static-bridge'), number_format_i18n($deleted), $listed, $mebibytes, number_format_i18n($result['keep'])));
            if ('partial' === $status) {
                $result['message'] .= ' ' . __('Tempo disponibile esaurito: la pulizia riprenderà con la prossima esecuzione.', 'static-bridge');
            }
            if (!empty($result['failed'])) {
                $result['message'] .= ' ' . sprintf(/* translators: %s: comma-separated list of folders */ __('Non eliminate per un controllo di sicurezza o un permesso mancante: %s.', 'static-bridge'), implode(', ', array_slice($result['failed'], 0, 10)));
            }
            foreach (array_slice((array) ($result['refused'] ?? array()), 0, 10) as $refused) {
                $result['message'] .= ' ' . sprintf(/* translators: 1: folder name, 2: reason */ __('%1$s non è stata eliminata: %2$s.', 'static-bridge'), $refused['name'], $refused['reason']);
            }
            if ($deleted > 0 || !empty($result['failed']) || !empty($result['refused']) || 'partial' === $status || 'cron' !== $result['trigger']) {
                $this->log_activity(
                    'partial' === $status ? __('Pulizia release parziale.', 'static-bridge') : __('Pulizia release completata.', 'static-bridge'),
                    $result['message'],
                    !empty($result['failed'])
                );
            }
        }
        update_option(self::RETENTION_LAST_OPTION, $result, false);
        return $result;
    }

    /**
     * Cloudflare Cache Rule expression (Rules language) that mirrors the routing guard:
     * only anonymous GET/HEAD requests without a query string for route-like paths,
     * never wp-admin/REST/assets/feeds or the configured dynamic paths.
     */
    private function cloudflare_cache_rule_expression()
    {
        $quote = static function ($value) {
            return '"' . str_replace(array('\\', '"'), array('\\\\', '\\"'), (string) $value) . '"';
        };
        $host = rtrim(strtolower((string) wp_parse_url(home_url('/'), PHP_URL_HOST)), '.');
        $conditions = array(
            'http.host eq ' . $quote($host),
            'http.request.method in {"GET" "HEAD"}',
            'http.request.uri.query eq ""',
            // Static routes are directories: wp-login.php, xmlrpc.php, sitemaps,
            // robots.txt and assets never end with a slash.
            'ends_with(http.request.uri.path, "/")',
        );
        foreach (array('wordpress_logged_in_', 'comment_author_', 'wp-postpass_', 'woocommerce_items_in_cart', 'woocommerce_cart_hash', 'wp_woocommerce_session_') as $cookie) {
            $conditions[] = 'not (http.cookie contains ' . $quote($cookie) . ')';
        }
        // «Cookie che mandano a WP» (2.5.0): the name anywhere in the header, as for the six above. It can match a
        // value too: that visit then reaches the origin, whose rules compare the name only. The query stays «eq ""»
        // also with the tracking parameters: those visits reach the origin, which answers with the file.
        foreach ($this->dynamic_cookie_names() as $cookie) {
            $conditions[] = 'not (http.cookie contains ' . $quote(rtrim($cookie, '*')) . ')';
        }
        foreach (array('/wp-admin/', '/wp-json/', '/wp-content/', '/wp-includes/') as $prefix) {
            $conditions[] = 'not starts_with(lower(http.request.uri.path), ' . $quote($prefix) . ')';
        }
        $conditions[] = 'not (lower(http.request.uri.path) contains "/feed/")';
        $paths = $this->settings()['excluded_paths'];
        if ($this->fluent_forms_nonce_refresh_enabled()) {
            // Fluent Forms routes kept WordPress-dynamic embed per-request nonces.
            $paths = array_merge($paths, array_keys($this->fluent_forms_dynamic_routes()));
        }
        if ($this->woocommerce_is_active()) {
            $paths = array_merge($paths, array_keys($this->woocommerce_dynamic_routes()));
        }
        foreach ($paths as $path) {
            $path = $this->normalize_route_path($path);
            if ('' === $path) {
                continue;
            }
            $conditions[] = '/' === $path
                ? 'http.request.uri.path ne "/"'
                : 'not starts_with(lower(http.request.uri.path), ' . $quote(strtolower($path)) . ')';
        }
        return '(' . implode(' and ', array_unique($conditions)) . ')';
    }

    /** Validation state of Cloudflare credentials, without ever returning them. */
    private function cloudflare_credential_state($zone, $token)
    {
        $zone = is_string($zone) ? $zone : '';
        $token = is_string($token) ? $token : '';
        return array(
            'zone' => '' === $zone ? 'missing' : (preg_match('/^[a-f0-9]{32}$/D', $zone) ? 'valid' : 'invalid'),
            'token' => '' === $token ? 'missing' : (preg_match('/^[A-Za-z0-9_-]{20,256}$/D', $token) ? 'valid' : 'invalid'),
        );
    }

    /** Zone ID and API token come only from wp-config.php constants, never from options. */
    private function cloudflare_credentials()
    {
        $zone = defined('STATIC_BRIDGE_CLOUDFLARE_ZONE_ID') ? constant('STATIC_BRIDGE_CLOUDFLARE_ZONE_ID') : '';
        $token = defined('STATIC_BRIDGE_CLOUDFLARE_API_TOKEN') ? constant('STATIC_BRIDGE_CLOUDFLARE_API_TOKEN') : '';
        $zone = is_string($zone) ? trim($zone) : '';
        $token = is_string($token) ? trim($token) : '';
        $state = $this->cloudflare_credential_state($zone, $token);
        return array(
            'zone' => $zone,
            'token' => $token,
            'valid' => 'valid' === $state['zone'] && 'valid' === $state['token'],
        );
    }

    /** Displayable purge configuration (no secrets). */
    private function cloudflare_purge_config()
    {
        $credentials = $this->cloudflare_credentials();
        $state = $this->cloudflare_credential_state($credentials['zone'], $credentials['token']);
        $enabled = !empty($this->settings()['cloudflare_purge']);
        return array(
            'enabled' => $enabled,
            'zone' => $state['zone'],
            'token' => $state['token'],
            'ready' => $enabled && $credentials['valid'],
        );
    }

    private function cloudflare_pending_purge()
    {
        $pending = get_option(self::CLOUDFLARE_PURGE_OPTION, array());
        if (!is_array($pending)) {
            $pending = array();
        }
        return array(
            'everything' => !empty($pending['everything']),
            'urls' => isset($pending['urls']) && is_array($pending['urls']) ? $pending['urls'] : array(),
            'attempts' => isset($pending['attempts']) ? max(0, (int) $pending['attempts']) : 0,
            'reasons' => isset($pending['reasons']) && is_array($pending['reasons']) ? array_values($pending['reasons']) : array(),
        );
    }

    /**
     * Records URLs (or 'everything') to purge and schedules the purge in its own request.
     * Does nothing unless the option is enabled and the wp-config credentials are valid.
     */
    private function queue_cloudflare_purge($targets, $reason)
    {
        // The public actions static_bridge_route_updated and static_bridge_all_routes_updated (2.5.0) go with every
        // purge of the caches in front of the site, configured or not; a route the worker just completed was announced.
        if ('everything' === $targets) {
            $this->announce_all_routes_updated($reason);
        } else {
            foreach ((array) $targets as $announced_url) {
                $this->announce_route_updated((string) $announced_url, true);
            }
        }
        // Aruba's HiSpeed Cache, through its own plugin, at the same moments as Cloudflare.
        $aruba = Static_Bridge_Server_Tuning::purge_aruba($targets);
        if (false === $aruba) {
            $this->log_activity(__('Svuotamento della cache HiSpeed di Aruba non riuscito.', 'static-bridge'), wp_strip_all_tags((string) $reason), true);
        } elseif (true === $aruba && 'everything' === $targets) {
            $this->log_activity(__('Cache HiSpeed di Aruba svuotata.', 'static-bridge'), wp_strip_all_tags((string) $reason));
        }
        if (!$this->cloudflare_purge_config()['ready']) {
            return false;
        }
        $pending = $this->cloudflare_pending_purge();
        $added = false;
        if ('everything' === $targets) {
            $added = !$pending['everything'];
            $pending['everything'] = true;
            $pending['urls'] = array();
        } elseif (!$pending['everything']) {
            foreach ((array) $targets as $url) {
                $url = (string) $url;
                $parts = wp_parse_url($url);
                if (!is_array($parts) || isset($parts['query']) || isset($parts['fragment']) || !$this->same_site_url($url)) {
                    continue;
                }
                if (!isset($pending['urls'][$url])) {
                    $pending['urls'][$url] = 1;
                    $added = true;
                }
            }
            if (count($pending['urls']) > self::CLOUDFLARE_PURGE_MAX_URLS) {
                $pending['everything'] = true;
                $pending['urls'] = array();
            }
        }
        if (!$added) {
            return false;
        }
        $pending['attempts'] = 0;
        $pending['reasons'] = array_slice(array_values(array_unique(array_merge($pending['reasons'], array(wp_strip_all_tags((string) $reason))))), -5);
        update_option(self::CLOUDFLARE_PURGE_OPTION, $pending, false);
        if (!wp_next_scheduled(self::CLOUDFLARE_PURGE_HOOK)) {
            wp_schedule_single_event(time(), self::CLOUDFLARE_PURGE_HOOK);
        }
        return true;
    }

    public function process_cloudflare_purge_cron()
    {
        $this->run_cloudflare_purge();
    }

    /**
     * Sends pending purges (at most $max_requests API calls in this request). A failure
     * is a warning: the work is kept for a bounded number of retries, never thrown.
     */
    private function run_cloudflare_purge($max_requests = 3)
    {
        $pending = $this->cloudflare_pending_purge();
        if (!$pending['everything'] && empty($pending['urls'])) {
            return array('status' => 'idle');
        }
        if (!$this->cloudflare_purge_config()['ready']) {
            delete_option(self::CLOUDFLARE_PURGE_OPTION);
            return array('status' => 'disabled');
        }
        if ($this->apache_serves_stale_copy()) {
            // Purging now would let the edge fetch the previous copy again: publish the rules first.
            $this->update_routing_rules();
            if ($this->apache_serves_stale_copy()) {
                if (!wp_next_scheduled(self::CLOUDFLARE_PURGE_HOOK)) {
                    wp_schedule_single_event(time() + 30, self::CLOUDFLARE_PURGE_HOOK);
                }
                return array('status' => 'waiting');
            }
        }
        $lock = wp_generate_uuid4();
        if (get_transient(self::CLOUDFLARE_PURGE_LOCK)) {
            // Another request is purging: make sure the remaining work still has a run.
            if (!wp_next_scheduled(self::CLOUDFLARE_PURGE_HOOK)) {
                wp_schedule_single_event(time() + 30, self::CLOUDFLARE_PURGE_HOOK);
            }
            return array('status' => 'busy');
        }
        set_transient(self::CLOUDFLARE_PURGE_LOCK, $lock, 120);
        try {
            $started = microtime(true);
            $budget = $this->safe_php_request_budget();
            $remaining = array_keys($pending['urls']);
            $purged = 0;
            $error = null;
            if ($pending['everything']) {
                $result = $this->cloudflare_purge_request(array('purge_everything' => true));
                if (is_wp_error($result)) {
                    $error = $result;
                }
            } else {
                $requests = 0;
                while (!empty($remaining) && $requests < max(1, (int) $max_requests)) {
                    if ($requests > 0 && $budget > 0 && microtime(true) - $started + self::CLOUDFLARE_PURGE_TIMEOUT >= $budget) {
                        break;
                    }
                    $batch = array_slice($remaining, 0, self::CLOUDFLARE_PURGE_BATCH);
                    $result = $this->cloudflare_purge_request(array('files' => $batch));
                    $requests++;
                    if (is_wp_error($result)) {
                        $error = $result;
                        break;
                    }
                    $purged += count($batch);
                    $remaining = array_slice($remaining, count($batch));
                }
            }
            $reasons = implode('; ', $pending['reasons']);

            if (null === $error) {
                if (!$pending['everything'] && !empty($remaining)) {
                    $pending['urls'] = array_fill_keys($remaining, 1);
                    update_option(self::CLOUDFLARE_PURGE_OPTION, $pending, false);
                    wp_clear_scheduled_hook(self::CLOUDFLARE_PURGE_HOOK);
                    wp_schedule_single_event(time(), self::CLOUDFLARE_PURGE_HOOK);
                } else {
                    delete_option(self::CLOUDFLARE_PURGE_OPTION);
                }
                $message = $pending['everything']
                    ? __('Cache Cloudflare svuotata per l’intera zona.', 'static-bridge')
                    : sprintf(/* translators: %s: number of purged URLs */ __('Cache Cloudflare svuotata per %s URL.', 'static-bridge'), number_format_i18n($purged));
                $this->log_activity($message, $reasons);
                return $this->record_cloudflare_purge_status(empty($remaining) || $pending['everything'] ? 'ok' : 'partial', $message, $purged, $pending['everything']);
            }

            $attempts = $pending['attempts'] + 1;
            $detail = $error->get_error_message();
            if ($attempts >= self::CLOUDFLARE_PURGE_MAX_ATTEMPTS) {
                delete_option(self::CLOUDFLARE_PURGE_OPTION);
                $message = sprintf(/* translators: 1: number of attempts, 2: error message (a sentence) */ __('Svuotamento della cache Cloudflare abbandonato dopo %1$s tentativi: %2$s Svuota manualmente la cache (pulsante in Impostazioni o dashboard Cloudflare) per non servire copie superate.', 'static-bridge'), number_format_i18n($attempts), $detail);
                $this->log_activity(__('Svuotamento cache Cloudflare non riuscito.', 'static-bridge'), $message, true);
                return $this->record_cloudflare_purge_status('failed', $message, $purged, $pending['everything']);
            }
            $delay = 60 * $attempts;
            $pending['attempts'] = $attempts;
            if (!$pending['everything']) {
                $pending['urls'] = array_fill_keys($remaining, 1);
            }
            update_option(self::CLOUDFLARE_PURGE_OPTION, $pending, false);
            wp_clear_scheduled_hook(self::CLOUDFLARE_PURGE_HOOK);
            wp_schedule_single_event(time() + $delay, self::CLOUDFLARE_PURGE_HOOK);
            $message = sprintf(/* translators: 1: attempt number, 2: maximum number of attempts, 3: error message (a sentence), 4: seconds before the next attempt */ __('Tentativo %1$s di %2$s non riuscito: %3$s Nuovo tentativo tra %4$s secondi; la pubblicazione resta valida.', 'static-bridge'), number_format_i18n($attempts), number_format_i18n(self::CLOUDFLARE_PURGE_MAX_ATTEMPTS), $detail, number_format_i18n($delay));
            $this->log_activity(__('Svuotamento cache Cloudflare non riuscito; verrà ripetuto.', 'static-bridge'), $message, true);
            return $this->record_cloudflare_purge_status('failed', $message, $purged, $pending['everything']);
        } catch (Throwable $exception) {
            $message = sprintf(/* translators: %s: error message */ __('Errore inatteso durante lo svuotamento della cache Cloudflare: %s', 'static-bridge'), $this->redact_cloudflare_secret(sanitize_text_field($exception->getMessage())));
            $this->log_activity(__('Svuotamento cache Cloudflare non riuscito.', 'static-bridge'), $message, true);
            return $this->record_cloudflare_purge_status('failed', $message, 0, $pending['everything']);
        } finally {
            if ($lock === get_transient(self::CLOUDFLARE_PURGE_LOCK)) {
                delete_transient(self::CLOUDFLARE_PURGE_LOCK);
            }
        }
    }

    private function record_cloudflare_purge_status($status, $message, $count, $everything)
    {
        $record = array(
            'time' => time(),
            'status' => $status,
            'message' => wp_strip_all_tags($message),
            'count' => (int) $count,
            'everything' => (bool) $everything,
        );
        update_option(self::CLOUDFLARE_PURGE_STATUS_OPTION, $record, false);
        return $record;
    }

    private function redact_cloudflare_secret($text)
    {
        $token = $this->cloudflare_credentials()['token'];
        return '' !== $token ? str_replace($token, '[token]', (string) $text) : (string) $text;
    }

    /** One purge_cache API call. Returns true or a WP_Error whose message never contains the token. */
    private function cloudflare_purge_request($payload, $timeout = self::CLOUDFLARE_PURGE_TIMEOUT)
    {
        $credentials = $this->cloudflare_credentials();
        if (!$credentials['valid']) {
            return new WP_Error('static_bridge_cloudflare_credentials', __('Zone ID o token Cloudflare assenti o non validi in wp-config.php.', 'static-bridge'));
        }
        $response = wp_safe_remote_post(self::CLOUDFLARE_API_BASE . $credentials['zone'] . '/purge_cache', array(
            'timeout' => max(1, (int) $timeout),
            'redirection' => 0,
            'limit_response_size' => 65536,
            'user-agent' => 'Static-Bridge/' . self::VERSION,
            'headers' => array(
                'Authorization' => 'Bearer ' . $credentials['token'],
                'Content-Type' => 'application/json',
            ),
            'body' => wp_json_encode($payload),
        ));
        if (is_wp_error($response)) {
            return new WP_Error('static_bridge_cloudflare_purge', sprintf(/* translators: %s: error message */ __('API Cloudflare non raggiungibile (%s).', 'static-bridge'), substr($this->redact_cloudflare_secret(sanitize_text_field($response->get_error_message())), 0, 200)));
        }
        $status = (int) wp_remote_retrieve_response_code($response);
        $data = json_decode(wp_remote_retrieve_body($response), true);
        if ($status >= 200 && $status < 300 && is_array($data) && true === ($data['success'] ?? null)) {
            return true;
        }
        $detail = '';
        if (is_array($data) && !empty($data['errors'][0]) && is_array($data['errors'][0])) {
            $detail = sprintf(' — %1$s %2$s', isset($data['errors'][0]['code']) ? (int) $data['errors'][0]['code'] : '', isset($data['errors'][0]['message']) ? substr(sanitize_text_field((string) $data['errors'][0]['message']), 0, 160) : '');
        } elseif (!is_array($data)) {
            $detail = ' — ' . __('risposta non JSON', 'static-bridge');
        }
        return new WP_Error('static_bridge_cloudflare_purge', $this->redact_cloudflare_secret(sprintf(/* translators: 1: HTTP status code, 2: error detail returned by Cloudflare, or empty */ __('Cloudflare ha rifiutato lo svuotamento (HTTP %1$s%2$s).', 'static-bridge'), $status, $detail)));
    }

    /** Synchronous purge of the whole zone (deactivation, where no cron hook will run later). */
    private function cloudflare_purge_everything_now($reason)
    {
        if (!$this->cloudflare_purge_config()['ready']) {
            return null;
        }
        delete_option(self::CLOUDFLARE_PURGE_OPTION);
        $result = $this->cloudflare_purge_request(array('purge_everything' => true));
        if (is_wp_error($result)) {
            $message = $result->get_error_message() . ' ' . __('Svuota manualmente la cache Cloudflare: potrebbe ancora servire HTML statico.', 'static-bridge');
            $this->log_activity(__('Svuotamento cache Cloudflare non riuscito.', 'static-bridge'), $message, true);
            return $this->record_cloudflare_purge_status('failed', $message, 0, true);
        }
        $message = __('Cache Cloudflare svuotata per l’intera zona.', 'static-bridge');
        $this->log_activity($message, $reason);
        return $this->record_cloudflare_purge_status('ok', $message, 0, true);
    }

    /** Genera: «Aggiorna tutte le pagine statiche» and «Riprova queste» (the URLs an export left out for HTTP 429/503). */
    public function handle_refresh_request()
    {
        if (!current_user_can('manage_options')) {
            wp_die(esc_html__('Non hai i permessi necessari.', 'static-bridge'), '', array('response' => 403));
        }
        check_admin_referer('static_bridge_refresh');
        $scope = isset($_POST['scope']) && 'rate_limited' === sanitize_key(wp_unslash($_POST['scope'])) ? 'rate_limited' : 'all';
        $result = $this->request_static_refresh($scope, array(), 'rate_limited' === $scope
            ? __('Riprova delle pagine rallentate dal server durante l’export.', 'static-bridge')
            : __('Richiesta manuale dalla pagina Genera.', 'static-bridge'));
        wp_safe_redirect(add_query_arg(array('page' => self::ADMIN_SLUG, 'tab' => 'generate', 'refresh' => $result['status']), admin_url('admin.php')));
        exit;
    }

    /**
     * POST /wp-json/static-bridge/v1/refresh for deploy scripts (an administrator, with an Application Password):
     * {"scope":"all"} regenerates every static page, {"scope":"paths","paths":["/a/","/b/"]} only those. Clearing
     * another page cache does not update the static copies, which are served first.
     */
    public function register_rest_routes()
    {
        register_rest_route('static-bridge/v1', '/refresh', array(
            'methods' => 'POST',
            'callback' => array($this, 'rest_refresh'),
            'permission_callback' => static function () {
                return current_user_can('manage_options');
            },
            'args' => array(
                'scope' => array('type' => 'string', 'enum' => array('all', 'paths'), 'default' => 'all'),
                'paths' => array('type' => 'array', 'items' => array('type' => 'string', 'maxLength' => 2048), 'maxItems' => self::MAX_KNOWN_DEPENDENTS, 'default' => array()),
                'reason' => array('type' => 'string', 'maxLength' => 200, 'default' => ''),
            ),
        ));
    }

    public function rest_refresh($request)
    {
        if (!current_user_can('manage_options')) {
            return new WP_Error('static_bridge_forbidden', __('Non hai i permessi necessari.', 'static-bridge'), array('status' => 403));
        }
        $scope = 'paths' === $request->get_param('scope') ? 'paths' : 'all';
        $paths = $request->get_param('paths');
        if ('paths' === $scope && (!is_array($paths) || empty($paths) || count($paths) > self::MAX_KNOWN_DEPENDENTS)) {
            return new WP_Error('static_bridge_paths', sprintf(/* translators: %d: maximum number of paths */ __('Indica da 1 a %d percorsi del sito.', 'static-bridge'), self::MAX_KNOWN_DEPENDENTS), array('status' => 400));
        }
        $reason = sanitize_text_field((string) $request->get_param('reason'));
        $result = $this->request_static_refresh($scope, 'paths' === $scope ? $paths : array(),
            sprintf(/* translators: %s: reason given by the caller */ __('Richiesta REST: %s', 'static-bridge'), '' !== $reason ? $reason : __('nessun motivo indicato', 'static-bridge')));
        $codes = array('queued' => 202, 'nothing' => 200, 'no_release' => 409, 'incremental_off' => 409, 'failed' => 500);
        return new WP_REST_Response($result, $codes[$result['status']] ?? 500);
    }

    /**
     * Queue regenerated copies without a full export. $scope: 'all' (every static route, as a shared component
     * save does), 'paths' (the given URLs or root-relative paths of this site) or 'rate_limited' (the routes the
     * last export could not render). Returns status 'queued', 'nothing', 'no_release', 'incremental_off' or
     * 'failed', with the number of routes when known. Callers check the capability first.
     */
    private function request_static_refresh($scope, $paths = array(), $reason = '')
    {
        if (!$this->current_release()) {
            return array('status' => 'no_release', 'queued' => 0);
        }
        if (empty($this->settings()['incremental_enabled'])) {
            return array('status' => 'incremental_off', 'queued' => 0);
        }
        $reason = sanitize_text_field((string) $reason);
        if ('all' === $scope) {
            if (!$this->queue_shared_output_refresh('' !== $reason ? $reason : __('Rigenerazione di tutte le pagine statiche richiesta.', 'static-bridge'))) {
                return array('status' => 'failed', 'queued' => 0);
            }
            $this->end_incremental_wait();
            $this->cancel_layout_refresh();
            return array('status' => 'queued', 'queued' => -1);
        }
        if ('rate_limited' === $scope) {
            $stored = get_option(self::RATE_LIMITED_ROUTES_OPTION, array());
            $paths = is_array($stored) && isset($stored['urls']) && is_array($stored['urls']) ? $stored['urls'] : array();
        }
        $urls = array_slice($this->sanitize_public_urls(is_array($paths) ? $paths : array()), 0, self::MAX_KNOWN_DEPENDENTS);
        if (empty($urls)) {
            if ('rate_limited' === $scope) {
                delete_option(self::RATE_LIMITED_ROUTES_OPTION);
            }
            return array('status' => 'nothing', 'queued' => 0);
        }
        $queued = $this->enqueue_incremental_urls($urls, 0, 'refresh', array(), 'dependent');
        if ($queued < 1) {
            return array('status' => 'failed', 'queued' => 0);
        }
        // Asked by an administrator or a deploy script: the pages do not wait for the last edit (2.5.0).
        $this->end_incremental_wait();
        if ('rate_limited' === $scope) {
            delete_option(self::RATE_LIMITED_ROUTES_OPTION);
        }
        $this->log_activity(
            __('Rigenerazione di pagine statiche accodata.', 'static-bridge'),
            sprintf(/* translators: 1: reason for the regeneration (a sentence), 2: number of queued paths */ __('%1$s Percorsi accodati: %2$d.', 'static-bridge'), $reason, (int) $queued)
        );
        return array('status' => 'queued', 'queued' => (int) $queued);
    }

    public function handle_cloudflare_purge()
    {
        if (!current_user_can('manage_options')) {
            wp_die(esc_html__('Non hai i permessi necessari.', 'static-bridge'), '', array('response' => 403));
        }
        check_admin_referer('static_bridge_cloudflare_purge');
        $status = 'disabled';
        if ($this->cloudflare_purge_config()['ready']) {
            $this->queue_cloudflare_purge('everything', __('richiesta manuale', 'static-bridge'));
            $result = $this->run_cloudflare_purge(1);
            $status = isset($result['status']) ? $result['status'] : 'failed';
        }
        wp_safe_redirect(add_query_arg(array('page' => self::ADMIN_SLUG, 'tab' => 'settings', 'cloudflare-purge' => $status), admin_url('admin.php')));
        exit;
    }

    /**
     * The public action static_bridge_route_updated (2.5.0): the page served at $url changed (written, removed, or
     * moved between the copy and WP), and what the server serves is already final. For the caches Static Bridge does
     * not know (Varnish, the cache of a hosting, another plugin), so they forget that address. $url is a full
     * address of this site without query or fragment; anything else is not announced. The worker announces a route
     * when it completes it and then purges the edge: $from_edge_purge consumes that announcement instead of
     * repeating it. A listener that throws changes nothing and leaves one line in Attività per request.
     */
    private function announce_route_updated($url, $from_edge_purge = false)
    {
        $parts = wp_parse_url($url);
        if (!is_array($parts) || isset($parts['query']) || isset($parts['fragment']) || !$this->same_site_url($url)) {
            return;
        }
        if ($from_edge_purge && isset($this->announced_routes[$url])) {
            unset($this->announced_routes[$url]);
            return;
        }
        if (!$from_edge_purge) {
            $this->announced_routes[$url] = true;
        }
        try {
            do_action('static_bridge_route_updated', $url);
        } catch (Throwable $e) {
            $this->log_route_announcement_failure($e);
        }
    }

    /**
     * The public action static_bridge_all_routes_updated (2.5.0): every route may have changed (a full export
     * published, routing settings saved, an SSI header updated, a manual purge), with the reason as a sentence.
     */
    private function announce_all_routes_updated($reason)
    {
        try {
            do_action('static_bridge_all_routes_updated', wp_strip_all_tags((string) $reason));
        } catch (Throwable $e) {
            $this->log_route_announcement_failure($e);
        }
    }

    private function log_route_announcement_failure($error)
    {
        if (!$this->route_announcement_failed) {
            $this->route_announcement_failed = true;
            $this->log_activity(__('Un plugin in ascolto degli aggiornamenti delle pagine ha generato un errore.', 'static-bridge'), sanitize_text_field($error->getMessage()), true);
        }
    }

    /** The static home page carries the security headers the rendered one sends (mod_headers, Nginx block). */
    /**
     * After a page is regenerated or removed, the copy other page caches keep of it goes too (WP Super Cache,
     * LiteSpeed Cache). Which caches run next to Static Bridge is told by check_page_cache_plugins() of the
     * Server tab (server-check.php).
     */
    private function purge_other_page_caches($url)
    {
        if (!apply_filters('static_bridge_purge_other_page_caches', true) || !$this->normalize_public_url((string) $url)) {
            return;
        }
        if (function_exists('wpsc_delete_url_cache')) {
            wpsc_delete_url_cache((string) $url);
        }
        if (defined('LSCWP_V')) {
            do_action('litespeed_purge_url', (string) $url);
        }
    }

    /** canonical, og:url, og:image, twitter:image, hreflang and the first JSON-LD @id of a page. */
    private function seo_absolute_urls($html)
    {
        $found = array();
        if (preg_match_all('~<(?:link|meta)\b[^>]*>~i', (string) $html, $tags)) {
            foreach ($tags[0] as $tag) {
                $value = preg_match('~\s(?:href|content)\s*=\s*(?:"([^"]*)"|\'([^\']*)\')~i', $tag, $match) ? html_entity_decode($match[1] . ($match[2] ?? ''), ENT_QUOTES) : '';
                if ('' === $value) {
                    continue;
                }
                if (preg_match('~\srel\s*=\s*["\']?canonical\b~i', $tag)) {
                    $found['canonical'] = $value;
                } elseif (preg_match('~\shreflang\s*=\s*["\']?([A-Za-z0-9_-]{1,20})~i', $tag, $language)) {
                    $found['hreflang ' . strtolower($language[1])] = $value;
                } elseif (preg_match('~\s(?:property|name)\s*=\s*["\']?(og:url|og:image|twitter:image)["\'\s>]~i', $tag, $name)) {
                    $found[strtolower($name[1])] = $found[strtolower($name[1])] ?? $value;
                }
            }
        }
        if (preg_match('~<script\b[^>]*application/ld\+json[^>]*>.*?"@id"\s*:\s*"([^"]{1,2048})"~is', (string) $html, $ld)) {
            $found['JSON-LD @id'] = str_replace('\\/', '/', $ld[1]);
        }
        return $found;
    }

    /** The static home page against WordPress: same absolute canonical, previews and structured data. */
    private function diagnostic_seo_absolute_urls_step($id)
    {
        $label = __('Canonical e anteprime come le vede un visitatore', 'static-bridge');
        $file = trailingslashit($this->current_release()) . 'index.html';
        $static = is_file($file) && !is_link($file) && filesize($file) <= self::MAX_HTML_PAGE_SIZE ? $this->seo_absolute_urls((string) file_get_contents($file)) : array();
        $rendered = $this->fetch_page(home_url('/'), 15);
        if (is_wp_error($rendered)) {
            return $this->diagnostic_result($id, $label, 'skip', sprintf(/* translators: %s: error message */ __('WordPress non ha reso la homepage per il confronto: %s', 'static-bridge'), $rendered->get_error_message()));
        }
        $dynamic = $this->seo_absolute_urls(isset($rendered['body']) ? (string) $rendered['body'] : '');
        if (empty($dynamic) && empty($static)) {
            return $this->diagnostic_result($id, $label, 'skip', __('La homepage non dichiara canonical, Open Graph né dati strutturati.', 'static-bridge'));
        }
        $relative = array();
        $different = array();
        foreach ($static as $name => $value) {
            if (!preg_match('~\Ahttps?://~i', $value)) {
                $relative[] = $name;
            }
        }
        foreach (array_unique(array_merge(array_keys($static), array_keys($dynamic))) as $name) {
            if (($static[$name] ?? '') !== ($dynamic[$name] ?? '') && !in_array($name, $relative, true)) {
                $different[] = $name;
            }
        }
        if (!empty($relative)) {
            return $this->diagnostic_result($id, $label, 'fail',
                sprintf(/* translators: %s: list of tags */ __('Nella homepage statica questi indirizzi non sono completi: %s. WhatsApp, Facebook e Telegram non mostrano l’anteprima e Google riceve un canonical relativo.', 'static-bridge'), implode(', ', $relative)),
                __('La copia è stata generata prima della 2.2.14: avvia un export completo o «Aggiorna tutte le pagine statiche».', 'static-bridge'), 'generate');
        }
        if (!empty($different)) {
            return $this->diagnostic_result($id, $label, 'warning',
                sprintf(/* translators: %s: list of tags */ __('La homepage statica e WordPress non coincidono in: %s.', 'static-bridge'), implode(', ', $different)),
                __('Se hai cambiato il plugin SEO, l’immagine di condivisione o l’indirizzo del sito, rigenera le pagine statiche.', 'static-bridge'), 'generate');
        }
        return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: %s: list of tags */ __('Uguali e completi nella copia statica e in WordPress: %s.', 'static-bridge'), implode(', ', array_keys($dynamic))));
    }

    /** The home page in the release against Complianz now: a stale banner_version or policy id means a save was missed. */
    private function diagnostic_complianz_step($id)
    {
        $label = __('Banner e policy di Complianz nelle pagine statiche', 'static-bridge');
        $file = trailingslashit($this->current_release()) . 'index.html';
        $html = is_readable($file) ? (string) file_get_contents($file) : '';
        if (!preg_match('/"banner_version":"?(\d+)/', $html, $banner_version) || !preg_match('/"current_policy_id":"?(\d+)/', $html, $policy_id)) {
            return $this->diagnostic_result($id, $label, 'skip', __('La homepage statica non contiene il banner di Complianz.', 'static-bridge'));
        }
        $banner_id = preg_match('/"user_banner_id":"?(\d+)/', $html, $user_banner) ? (int) $user_banner[1] : cmplz_get_default_banner_id();
        $banner = cmplz_get_cookiebanner($banner_id);
        $live_policy = get_option('complianz_active_policy_id', 1);
        $in_step = (int) $banner_version[1] === (int) $banner->banner_version && (int) $policy_id[1] === (int) $live_policy;
        // Complianz's safe mode turns its cookie blocker off: the banner still asks, but scripts and embeds that set
        // cookies run before the answer, in the static pages as in the dynamic ones. Only the owner can decide.
        if ($in_step && function_exists('cmplz_get_option') && cmplz_get_option('safe_mode')) {
            return $this->diagnostic_result($id, $label, 'warning',
                __('Complianz è in modalità sicura: il blocco di cookie e script è spento. Il banner chiede il consenso, ma gli script e i contenuti incorporati che usano cookie partono prima della risposta, anche nelle pagine statiche.', 'static-bridge'),
                __('Se la modalità sicura non serve più, spegnila in Complianz → Strumenti → Supporto, poi controlla il sito con il banner. Static Bridge rigenera da solo le pagine al salvataggio.', 'static-bridge'));
        }
        if ($in_step) {
            return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: 1: banner version, 2: consent policy number */ __('Versione del banner %1$d e policy %2$d uguali a quelle di Complianz.', 'static-bridge'), (int) $banner->banner_version, (int) $live_policy));
        }
        $message = sprintf(/* translators: 1: banner version in the static page, 2: current banner version, 3: policy number in the static page, 4: current policy number */ __('Homepage statica: banner %1$d, policy %3$d. Complianz: banner %2$d, policy %4$d. Finché non coincidono i visitatori vedono il banner vecchio e chi ha già scelto non riceve la nuova richiesta di consenso.', 'static-bridge'), (int) $banner_version[1], (int) $banner->banner_version, (int) $policy_id[1], (int) $live_policy);
        if (!empty($this->incremental_queue())) {
            return $this->diagnostic_result($id, $label, 'warning', $message, __('L’aggiornamento dei percorsi statici è in coda: ricontrolla quando è finito.', 'static-bridge'), 'generate');
        }
        return $this->diagnostic_result($id, $label, 'warning', $message, __('Avvia una generazione completa. Con gli aggiornamenti incrementali attivi non dovrebbe servire: se succede ancora, il salvataggio è passato da una strada che Static Bridge non vede.', 'static-bridge'), 'generate');
    }

    private function diagnostic_security_headers_step($id)
    {
        $label = __('Intestazioni di sicurezza sulle pagine statiche', 'static-bridge');
        $expected = $this->security_headers();
        if (empty($expected)) {
            return $this->diagnostic_result($id, $label, 'skip', __('Nell’ultimo export completo la home renderizzata non inviava intestazioni di sicurezza da ripetere (X-Frame-Options, X-Content-Type-Options, Referrer-Policy, Permissions-Policy, Strict-Transport-Security, Content-Security-Policy senza nonce).', 'static-bridge'));
        }
        $url = home_url('/');
        $response = $this->remote_get($url, 15, 262144);
        if (is_wp_error($response)) {
            return $this->diagnostic_result($id, $label, 'warning', $response->get_error_message(), __('Verifica che il dominio sia raggiungibile dal processo PHP e ripeti la diagnostica.', 'static-bridge'), 'settings', $url);
        }
        $missing = array();
        foreach ($expected as $name => $value) {
            if ('' === trim(implode(', ', (array) wp_remote_retrieve_header($response, strtolower($name))))) {
                $missing[] = $name;
            }
        }
        if (empty($missing)) {
            return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: %s: list of HTTP header names */ __('La home pubblica invia %s.', 'static-bridge'), implode(', ', array_keys($expected))), '', '', $url);
        }
        return $this->diagnostic_result($id, $label, 'warning',
            sprintf(/* translators: %s: list of HTTP header names */ __('La home pubblica non invia %s, che WordPress invia sulle pagine dinamiche.', 'static-bridge'), implode(', ', $missing)),
            $this->server_uses_nginx()
                ? __('Copia il blocco Nginx aggiornato da Impostazioni e ricarica Nginx.', 'static-bridge')
                : ('openlitespeed' === $this->web_server_kind()
                    ? __('OpenLiteSpeed ignora le direttive Header del file .htaccess: aggiungi al virtual host il contesto mostrato in Impostazioni → OpenLiteSpeed e riavvia il server.', 'static-bridge')
                    : __('Attiva il modulo Apache mod_headers (a2enmod headers) o aggiungi le intestazioni nella configurazione del server.', 'static-bridge')),
            'settings', $url);
    }

    private function diagnostic_cloudflare_edge_step($id)
    {
        $label = __('Cloudflare davanti al sito', 'static-bridge');
        $url = home_url('/');
        $response = $this->remote_get($url, 15, 262144);
        if (is_wp_error($response)) {
            return $this->diagnostic_result($id, $label, 'warning', sprintf(/* translators: %s: error message */ __('Risposta pubblica della home non disponibile: %s', 'static-bridge'), $response->get_error_message()), __('Verifica DNS e TLS del dominio dal server; le altre verifiche indicano se il rendering è comunque raggiungibile.', 'static-bridge'), 'settings', $url);
        }
        $header = function ($name) use ($response) {
            $value = wp_remote_retrieve_header($response, $name);
            if (is_array($value)) {
                $value = implode(', ', array_map('strval', $value));
            }
            return is_string($value) ? substr(sanitize_text_field($value), 0, 80) : '';
        };
        $ray = $header('cf-ray');
        $mitigated = $header('cf-mitigated');
        $cache_status = strtoupper($header('cf-cache-status'));
        if ('' === $ray && 'cloudflare' !== strtolower($header('server')) && '' === $mitigated) {
            return $this->diagnostic_result($id, $label, 'skip', __('Cloudflare non rilevato: la risposta pubblica della home non contiene cf-ray.', 'static-bridge'), '', '', $url);
        }
        $settings = $this->settings();
        $purge = $this->cloudflare_purge_config();
        $observed = sprintf('cf-ray=%1$s; cf-cache-status=%2$s; HTTP %3$s', '' !== $ray ? $ray : '—', '' !== $cache_status ? $cache_status : '—', (int) wp_remote_retrieve_response_code($response));
        if ('' !== $mitigated) {
            return $this->diagnostic_result($id, $label, 'fail',
                sprintf(/* translators: 1: value of the cf-mitigated header, 2: observed Cloudflare headers and HTTP status */ __('Cloudflare ha risposto al processo PHP con una verifica (cf-mitigated: %1$s; %2$s). Con il percorso pubblico export e push verrebbero bloccati.', 'static-bridge'), $mitigated, $observed),
                __('Imposta un indirizzo di origine per il rendering (Impostazioni → Cloudflare e CDN) oppure crea in Cloudflare una regola WAF che salti le verifiche per l’IP del server.', 'static-bridge'), 'settings', $url);
        }
        $findings = array();
        $remediation = array();
        if ('' === $settings['render_origin']) {
            $findings[] = __('Il rendering interno passa da Cloudflare (nessun indirizzo di origine).', 'static-bridge');
            $remediation[] = __('Imposta un indirizzo di origine per il rendering: WAF, Bot Fight Mode e funzioni che riscrivono l’HTML (Rocket Loader, Email Obfuscation) non toccheranno più le copie salvate.', 'static-bridge');
        }
        if ('HIT' === $cache_status && !$purge['ready']) {
            $findings[] = __('La home è servita dalla cache Cloudflare (cf-cache-status HIT) ma lo svuotamento automatico non è attivo.', 'static-bridge');
            $remediation[] = __('Attiva lo svuotamento (purge) Cloudflare con Zone ID e token in wp-config.php, oppure rimuovi la regola che mette in cache l’HTML.', 'static-bridge');
        }
        $last = get_option(self::CLOUDFLARE_PURGE_STATUS_OPTION, array());
        if ($purge['ready'] && is_array($last) && 'failed' === ($last['status'] ?? '')) {
            $findings[] = __('L’ultimo svuotamento della cache Cloudflare non è riuscito.', 'static-bridge');
            $remediation[] = __('Controlla Zone ID, token (permesso Cache Purge) e Attività; poi usa “Svuota ora la cache Cloudflare”.', 'static-bridge');
        }
        if (!empty($findings)) {
            return $this->diagnostic_result($id, $label, 'warning', sprintf(/* translators: %s: observed Cloudflare headers and HTTP status */ __('Cloudflare rilevato (%s).', 'static-bridge'), $observed) . ' ' . implode(' ', $findings), implode(' ', $remediation), 'settings', $url);
        }
        return $this->diagnostic_result($id, $label, 'pass', sprintf(
            /* translators: 1: observed Cloudflare headers and HTTP status, 2: origin IP address, 3: “active” or “not active” */ __('Cloudflare rilevato (%1$s); rendering tramite origine %2$s; svuotamento automatico: %3$s.', 'static-bridge'),
            $observed,
            $settings['render_origin'],
            $purge['ready'] ? __('attivo', 'static-bridge') : __('non attivo', 'static-bridge')
        ), '', '', $url);
    }

    /** Markup that Cloudflare adds at the edge and that must not be stored in a release. */
    private function diagnostic_cloudflare_markup_step($id)
    {
        $label = __('Markup Cloudflare nelle copie salvate', 'static-bridge');
        $release = $this->current_release();
        if (!$release) {
            return $this->diagnostic_result($id, $label, 'skip', __('Nessuna release attiva da controllare.', 'static-bridge'));
        }
        $features = array(
            'Rocket Loader' => array('rocket-loader.min.js', 'data-cf-settings=', '~type=["\'][0-9a-f]{12,}-text/javascript~i'),
            'Email Obfuscation' => array('__cf_email__', 'data-cfemail=', '/cdn-cgi/l/email-protection', 'email-decode.min.js'),
            __('Verifica/Bot', 'static-bridge') => array('/cdn-cgi/challenge-platform/'),
            'Web Analytics' => array('static.cloudflareinsights.com/beacon'),
            '/cdn-cgi/' => array('/cdn-cgi/'),
        );
        $found = array();
        $files = 0;
        $scanned = 0;
        try {
            $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($release, FilesystemIterator::SKIP_DOTS));
            foreach ($iterator as $file) {
                if (!$file->isFile() || $file->isLink() || 'html' !== strtolower($file->getExtension())) {
                    continue;
                }
                if (++$scanned > 5000) {
                    break;
                }
                $html = @file_get_contents($file->getPathname(), false, null, 0, self::MAX_HTML_PAGE_SIZE);
                if (!is_string($html)) {
                    continue;
                }
                $relative = ltrim(str_replace(DIRECTORY_SEPARATOR, '/', substr($file->getPathname(), strlen(trailingslashit($release)))), '/');
                $directory = dirname($relative);
                $path = '/' . ('.' === $directory ? '' : trim($directory, '/') . '/');
                $matched = false;
                foreach ($features as $feature => $needles) {
                    foreach ($needles as $needle) {
                        $hit = '~' === $needle[0] ? (bool) preg_match($needle, $html) : false !== strpos($html, $needle);
                        if ($hit) {
                            $found[$feature][] = $path;
                            $matched = true;
                            break;
                        }
                    }
                }
                $files += $matched ? 1 : 0;
            }
        } catch (Exception $exception) {
            return $this->diagnostic_result($id, $label, 'warning', __('La release attiva non è leggibile per il controllo del markup.', 'static-bridge'));
        }
        if (empty($found)) {
            return $this->diagnostic_result($id, $label, 'pass', sprintf(/* translators: %s: number of HTML files */ __('Nessun markup aggiunto da Cloudflare (/cdn-cgi/, Rocket Loader, Email Obfuscation) in %s file HTML.', 'static-bridge'), number_format_i18n(min($scanned, 5000))));
        }
        $parts = array();
        foreach ($found as $feature => $paths) {
            $parts[] = sprintf('%1$s: %2$s (%3$s)', $feature, number_format_i18n(count($paths)), implode(', ', array_slice($paths, 0, 5)));
        }
        return $this->diagnostic_result($id, $label, 'warning',
            sprintf(/* translators: 1: number of files, 2: list of the Cloudflare features found */ __('Markup aggiunto da Cloudflare salvato in %1$s file della release. %2$s', 'static-bridge'), number_format_i18n($files), implode('; ', $parts)),
            __('Queste copie dipendono da script /cdn-cgi/ che esistono solo dietro Cloudflare e vengono rielaborate di nuovo all’edge. Imposta un indirizzo di origine per il rendering (o disattiva Rocket Loader ed Email Obfuscation per il sito) e rigenera la release.', 'static-bridge'),
            'settings');
    }

    /**
     * «Ignora i parametri di tracciamento» and «Cookie che mandano a WP» (2.5.0) change the routing guard: Apache
     * gets it with the .htaccess just written, Nginx only when the block is copied again.
     */
    private function log_guard_settings_changes($previous, $current)
    {
        $nginx = $this->server_uses_nginx() ? ' ' . __('Copia il blocco Nginx aggiornato e ricarica Nginx.', 'static-bridge') : '';
        if ($previous['ignore_tracking_params'] !== $current['ignore_tracking_params']) {
            $this->log_activity(
                !empty($current['ignore_tracking_params']) ? __('Parametri di tracciamento ignorati dalle regole del server.', 'static-bridge') : __('Parametri di tracciamento di nuovo mandati a WP.', 'static-bridge'),
                (!empty($current['ignore_tracking_params'])
                    ? sprintf(/* translators: %s: list of query parameter names */ __('Un indirizzo con solo questi parametri riceve la copia statica: %s.', 'static-bridge'), implode(', ', $this->tracking_param_names()))
                    : __('Ogni indirizzo con una query string va di nuovo a WP.', 'static-bridge')) . $nginx
            );
        }
        if ($previous['dynamic_cookies'] !== $current['dynamic_cookies']) {
            $this->log_activity(
                __('Cookie che mandano a WP aggiornati.', 'static-bridge'),
                (empty($current['dynamic_cookies']) ? __('nessuno', 'static-bridge') : implode(', ', $current['dynamic_cookies']))
                    . ' — ' . __('Se usi la regola di cache di Cloudflare, incolla di nuovo quella mostrata nelle Impostazioni.', 'static-bridge') . $nginx
            );
        }
    }

    /** Edge-cache consequences of a settings change, logged in Attività. */
    private function log_cdn_settings_changes($previous, $current)
    {
        if ($previous['render_origin'] !== $current['render_origin']) {
            $this->log_activity(
                '' !== $current['render_origin'] ? __('Rendering tramite indirizzo di origine attivato.', 'static-bridge') : __('Rendering tramite indirizzo di origine disattivato.', 'static-bridge'),
                '' !== $current['render_origin']
                    ? sprintf(/* translators: %s: origin IP address, with optional port */ __('Export e push si collegano a %s mantenendo dominio, Host, SNI e verifica TLS. Esegui la Diagnostica per verificarlo.', 'static-bridge'), $current['render_origin'])
                    : __('Le richieste interne tornano a usare il DNS pubblico del dominio.', 'static-bridge')
            );
        }
        if ($previous['static_cache_control'] !== $current['static_cache_control']) {
            $this->log_activity(
                __('Cache-Control delle pagine statiche aggiornato.', 'static-bridge'),
                ('' !== $current['static_cache_control'] ? $current['static_cache_control'] : __('nessun header', 'static-bridge'))
                    . ($this->server_uses_nginx() ? ' — ' . __('Copia il blocco Nginx aggiornato e ricarica Nginx.', 'static-bridge') : '')
            );
        }
        if ($previous['cloudflare_purge'] !== $current['cloudflare_purge']) {
            $config = $this->cloudflare_purge_config();
            $this->log_activity(
                !empty($current['cloudflare_purge']) ? __('Svuotamento automatico della cache Cloudflare attivato.', 'static-bridge') : __('Svuotamento automatico della cache Cloudflare disattivato.', 'static-bridge'),
                !empty($current['cloudflare_purge']) && !$config['ready'] ? __('Definisci STATIC_BRIDGE_CLOUDFLARE_ZONE_ID e STATIC_BRIDGE_CLOUDFLARE_API_TOKEN in wp-config.php: senza credenziali valide nessuna richiesta viene inviata.', 'static-bridge') : '',
                !empty($current['cloudflare_purge']) && !$config['ready']
            );
        }
    }

    private function settings()
    {
        $settings = get_option(self::SETTINGS_OPTION, array());
        if (!is_array($settings)) {
            $settings = array();
        }
        // Contents excluded with the editor checkbox (2.5.0) come from one option: no permalink is built here.
        $paths = array_merge($this->manual_excluded_paths(), $this->managed_dynamic_form_paths(), $this->editor_excluded_paths());
        $woocommerce_enabled = $this->woocommerce_integration_enabled();
        $paths = array_merge($paths, $this->woocommerce_dynamic_paths());
        // Other plugins keep more routes dynamic (Lingua: /en/iscriviti/ next to /iscriviti/). A callback that
        // reads the settings again (static_bridge_status) gets them without its own additions, not a loop.
        $added = array();
        if (!$this->filtering_excluded_paths) {
            $this->filtering_excluded_paths = true;
            try {
                $added = apply_filters('static_bridge_excluded_paths', array(), $paths);
            } finally {
                $this->filtering_excluded_paths = false;
            }
        }
        foreach (is_array($added) ? array_slice(array_values(array_filter($added, 'is_string')), 0, 500) : array() as $added_path) {
            $added_path = $this->normalize_route_path($added_path);
            if ('' !== $added_path && '/' !== $added_path) {
                $paths[] = $added_path;
            }
        }
        return array(
            'strict_mode' => isset($settings['strict_mode']) ? (int) (bool) $settings['strict_mode'] : 0,
            'excluded_paths' => array_values(array_unique($paths)),
            'woocommerce_enabled' => $woocommerce_enabled,
            'incremental_enabled' => isset($settings['incremental_enabled']) ? (int) (bool) $settings['incremental_enabled'] : 1,
            // 2.5.0, both off by default: an installed site keeps working as before.
            'incremental_wait' => $this->sanitize_incremental_wait(isset($settings['incremental_wait']) ? $settings['incremental_wait'] : 0),
            'failure_email' => isset($settings['failure_email']) ? (int) (bool) $settings['failure_email'] : 0,
            // «Date relative aggiornate nel browser» (2.5.0), off by default: it changes the HTML of the copies.
            'relative_dates' => isset($settings['relative_dates']) ? (int) (bool) $settings['relative_dates'] : 0,
            // «Versione Markdown delle pagine» (2.5.0), off by default: a new answer and a new <link> in the pages.
            'markdown_pages' => isset($settings['markdown_pages']) ? (int) (bool) $settings['markdown_pages'] : 0,
            // «Rigenera dopo gli aggiornamenti» (2.5.0), off by default: a full export after every update weighs on the server.
            'regenerate_after_updates' => isset($settings['regenerate_after_updates']) ? (int) (bool) $settings['regenerate_after_updates'] : 0,
            // «Non riscrivere le pagine identiche» and «Rallenta l'export se il server è lento» (2.5.0), off by default:
            // fewer edge purges, a slower export.
            'skip_identical_pages' => isset($settings['skip_identical_pages']) ? (int) (bool) $settings['skip_identical_pages'] : 0,
            'export_load_brake' => isset($settings['export_load_brake']) ? (int) (bool) $settings['export_load_brake'] : 0,
            // «Export completo pianificato» (2.5.0), off by default; a stored value that no longer passes is the default.
            'scheduled_export' => $this->sanitize_scheduled_export_frequency($settings['scheduled_export'] ?? null) ?? 'off',
            'scheduled_export_time' => $this->sanitize_scheduled_export_time($settings['scheduled_export_time'] ?? null) ?? self::SCHEDULED_EXPORT_DEFAULT_TIME,
            'scheduled_export_day' => $this->sanitize_scheduled_export_day($settings['scheduled_export_day'] ?? null) ?? self::SCHEDULED_EXPORT_DEFAULT_DAY,
            'export_archives' => isset($settings['export_archives']) ? (int) (bool) $settings['export_archives'] : 1,
            'selective_shared_updates' => isset($settings['selective_shared_updates']) ? (int) (bool) $settings['selective_shared_updates'] : 0,
            'shared_header_fragments' => isset($settings['shared_header_fragments']) ? (int) (bool) $settings['shared_header_fragments'] : 0,
            'retention_enabled' => isset($settings['retention_enabled']) ? (int) (bool) $settings['retention_enabled'] : 0,
            'retention_keep' => $this->sanitize_retention_keep(isset($settings['retention_keep']) ? $settings['retention_keep'] : self::RETENTION_DEFAULT_KEEP),
            'render_origin' => $this->stored_setting_or_empty($settings, 'render_origin', 'sanitize_render_origin'),
            'static_cache_control' => $this->stored_setting_or_empty($settings, 'static_cache_control', 'sanitize_static_cache_control'),
            'cloudflare_purge' => isset($settings['cloudflare_purge']) ? (int) (bool) $settings['cloudflare_purge'] : 0,
            'precompressed_pages' => isset($settings['precompressed_pages']) ? (int) (bool) $settings['precompressed_pages'] : 0,
            // «Ignora i parametri di tracciamento» and «Cookie che mandano a WP» (2.5.0), off and empty by default:
            // they change the server rules.
            'ignore_tracking_params' => isset($settings['ignore_tracking_params']) ? (int) (bool) $settings['ignore_tracking_params'] : 0,
            'dynamic_cookies' => $this->sanitize_dynamic_cookie_names(isset($settings['dynamic_cookies']) ? $settings['dynamic_cookies'] : array())['names'],
            // «Importa i redirect di…» (2.5.0), none by default: the chosen plugins' redirects enter the server rules.
            'import_redirects' => $this->sanitize_redirect_import_sources(isset($settings['import_redirects']) ? $settings['import_redirects'] : array()),
            // «Pagine da aggiornare a ogni pubblicazione» and «… ogni notte» (2.5.0), empty by default.
            'publish_paths' => $this->stored_refresh_paths($settings, 'publish_paths'),
            'nightly_paths' => $this->stored_refresh_paths($settings, 'nightly_paths'),
        );
    }

    /** A stored string setting that no longer passes its validator is treated as unset. */
    private function stored_setting_or_empty($settings, $key, $sanitizer)
    {
        if (!isset($settings[$key]) || !is_string($settings[$key])) {
            return '';
        }
        $value = $this->$sanitizer($settings[$key]);
        return is_wp_error($value) ? '' : $value;
    }

    /** Number of ready releases kept besides current: an integer in 1..20. */
    private function sanitize_retention_keep($value)
    {
        if (is_string($value)) {
            $value = trim($value);
        }
        if (!is_numeric($value)) {
            return self::RETENTION_DEFAULT_KEEP;
        }
        return max(1, min(self::RETENTION_MAX_KEEP, (int) $value));
    }

    /** Frequency of «Export completo pianificato»: 'off', 'daily' or 'weekly', exactly; anything else is null. */
    private function sanitize_scheduled_export_frequency($value)
    {
        return is_string($value) && in_array($value, self::SCHEDULED_EXPORT_FREQUENCIES, true) ? $value : null;
    }

    /** Time of the scheduled export: HH:MM from 00:00 to 23:59, exactly; anything else is null. */
    private function sanitize_scheduled_export_time($value)
    {
        return is_string($value) && preg_match('/\A(?:[01][0-9]|2[0-3]):[0-5][0-9]\z/', $value) ? $value : null;
    }

    /** Day of a weekly export: 0 (Sunday) to 6 as an integer or one digit; anything else is null. */
    private function sanitize_scheduled_export_day($value)
    {
        if (is_int($value)) {
            return $value >= 0 && $value <= 6 ? $value : null;
        }
        return is_string($value) && preg_match('/\A[0-6]\z/', $value) ? (int) $value : null;
    }

    /**
     * The next time of «Export completo pianificato» after $now, as a Unix timestamp, or 0 when it is off. The
     * time is a wall-clock time of the site's time zone: DateTimeImmutable moves by calendar days, so the export
     * stays at 03:00 across daylight saving time (a day is 23 or 25 hours then, never 86400 seconds added).
     */
    private function next_scheduled_export_time($settings, $now = null)
    {
        $frequency = $this->sanitize_scheduled_export_frequency(is_array($settings) ? ($settings['scheduled_export'] ?? null) : null);
        if (!in_array($frequency, array('daily', 'weekly'), true)) {
            return 0;
        }
        $time = $this->sanitize_scheduled_export_time($settings['scheduled_export_time'] ?? null) ?? self::SCHEDULED_EXPORT_DEFAULT_TIME;
        $day = $this->sanitize_scheduled_export_day($settings['scheduled_export_day'] ?? null) ?? self::SCHEDULED_EXPORT_DEFAULT_DAY;
        $now = null === $now ? time() : (int) $now;
        $hour = (int) substr($time, 0, 2);
        $minute = (int) substr($time, 3, 2);
        try {
            $zone = function_exists('wp_timezone') ? wp_timezone() : new DateTimeZone('UTC');
            $today = (new DateTimeImmutable('@' . $now))->setTimezone($zone);
        } catch (Exception $e) {
            return 0;
        }
        $candidate = $today->setTime($hour, $minute);
        if ('weekly' === $frequency) {
            $ahead = ($day - (int) $today->format('w') + 7) % 7;
            if ($ahead > 0) {
                $candidate = $today->modify('+' . $ahead . ' days')->setTime($hour, $minute);
            }
        }
        if ($candidate->getTimestamp() <= $now) {
            $candidate = $candidate->modify('weekly' === $frequency ? '+7 days' : '+1 day')->setTime($hour, $minute);
        }
        return $candidate->getTimestamp();
    }

    /**
     * Replaces the single event of the scheduled export with one at the next time, or only removes it when the
     * schedule is off. Returns the time scheduled, or 0.
     */
    private function schedule_scheduled_export($now = null)
    {
        wp_clear_scheduled_hook(self::SCHEDULED_EXPORT_HOOK);
        $next = $this->next_scheduled_export_time($this->settings(), $now);
        if ($next < 1) {
            return 0;
        }
        return false === wp_schedule_single_event($next, self::SCHEDULED_EXPORT_HOOK) ? 0 : $next;
    }

    /** After the settings are saved: the event follows the schedule, and a change of the schedule is in Attività. */
    private function sync_scheduled_export($previous_settings, $invalid = false)
    {
        $current = $this->settings();
        $next = $this->schedule_scheduled_export();
        if ($invalid) {
            $this->log_activity(__('Pianificazione dell’export completo non valida; è stato mantenuto il valore precedente.', 'static-bridge'), '', true);
        }
        $changed = false;
        foreach (array('scheduled_export', 'scheduled_export_time', 'scheduled_export_day') as $key) {
            $changed = $changed || ($previous_settings[$key] ?? null) !== $current[$key];
        }
        if (!$changed) {
            return;
        }
        if ($next > 0) {
            $this->log_activity(
                sprintf(/* translators: %s: date and time of the next scheduled export */ __('Export completo pianificato: il prossimo parte il %s.', 'static-bridge'), $this->format_site_datetime($next)),
                __('WP-Cron parte solo quando qualcuno carica WordPress: per un orario preciso serve un cron di sistema.', 'static-bridge')
            );
        } elseif ('off' === $current['scheduled_export']) {
            $this->log_activity(__('Export completo pianificato disattivato.', 'static-bridge'));
        } else {
            $this->log_activity(__('Export completo pianificato non programmato: WP-Cron ha rifiutato l’evento.', 'static-bridge'), '', true);
        }
    }

    /** The days of a weekly export for the Settings select, Monday first: 0 (Sunday) to 6 => translated name. */
    private function scheduled_export_weekdays()
    {
        return array(
            1 => __('lunedì', 'static-bridge'),
            2 => __('martedì', 'static-bridge'),
            3 => __('mercoledì', 'static-bridge'),
            4 => __('giovedì', 'static-bridge'),
            5 => __('venerdì', 'static-bridge'),
            6 => __('sabato', 'static-bridge'),
            0 => __('domenica', 'static-bridge'),
        );
    }

    /**
     * Date and time in the site's time zone and formats, from a time() timestamp. Never date_i18n() for these:
     * it takes the timestamp as already moved to the site's time zone and printed UTC until 2.4.4 («Ultimo
     * controllo», the releases, the Diagnostica), found on a site in Europe/Rome.
     */
    private function format_site_datetime($timestamp)
    {
        return wp_date(get_option('date_format', 'j F Y') . ' ' . get_option('time_format', 'H:i'), (int) $timestamp);
    }

    /**
     * Callback of static_bridge_scheduled_export (2.5.0). A running (alive) or paused export is never replaced:
     * the run is skipped and written in Attività. Otherwise start_export('schedule'), with the same checks as the
     * Generate tab (SSI safety, queue table, staging); a refused start is in Attività and, with «Avvisami per email
     * se un aggiornamento fallisce», sends the e-mail, because nobody is watching a scheduled run. The next run is
     * always scheduled, also after a skip or a failure.
     */
    public function run_scheduled_export()
    {
        try {
            if ('off' === $this->settings()['scheduled_export']) {
                return;
            }
            $job = $this->start_export('schedule');
            if (!is_wp_error($job)) {
                return;
            }
            $code = $job->get_error_code();
            if ('static_bridge_export_running' === $code) {
                $this->log_activity(
                    __('Export pianificato saltato: è già in corso un’esportazione.', 'static-bridge'),
                    __('L’export in corso pubblicherà una versione nuova; il prossimo export pianificato resta in calendario.', 'static-bridge')
                );
            } elseif ('static_bridge_export_paused' === $code) {
                $this->log_activity(__('Export pianificato saltato: c’è un’esportazione in pausa.', 'static-bridge'), $job->get_error_message(), true);
            } else {
                $this->log_activity(__('Export pianificato non avviato.', 'static-bridge'), $job->get_error_message(), true);
                $this->notify_update_failure('schedule', $job->get_error_message());
            }
        } catch (Throwable $e) {
            $this->log_activity(__('Export pianificato non avviato: errore interno.', 'static-bridge'), sanitize_text_field($e->getMessage()), true);
        } finally {
            $this->schedule_scheduled_export();
        }
    }

    /*
     * After an update of WP, the theme or a plugin (2.5.0). The release online was rendered with the CSS and JS of
     * before: its pages may ask for files with an old version in the name or in ?ver=, or files that are gone. The
     * hooks below only take note (AFTER_UPDATE_OPTION); the notice offers «Rigenera», a full export that publishes
     * removes what it covers, and «Rigenera dopo gli aggiornamenti» (off by default) starts that export by itself.
     * Not counted: translations (text only, and language packs update by themselves every few days), installs of a
     * plugin or theme that is not active, and Static Bridge itself (its scripts keep their path in the copy; a version
     * that needs a new export says so itself, and its own update runs this hook in the code of the old version).
     */

    /** upgrader_process_complete: WP, the active theme or its parent, an active plugin; only updates. */
    public function note_upgrader_change($upgrader = null, $hook_extra = array())
    {
        if (!is_array($hook_extra) || 'update' !== ($hook_extra['action'] ?? '')) {
            return;
        }
        $type = (string) ($hook_extra['type'] ?? '');
        try {
            if ('core' === $type) {
                $this->note_site_change('core', 'update', 'wordpress', 'WordPress');
            } elseif ('plugin' === $type) {
                $plugins = isset($hook_extra['plugins']) ? (array) $hook_extra['plugins'] : (isset($hook_extra['plugin']) ? array($hook_extra['plugin']) : array());
                foreach (array_slice($plugins, 0, 200) as $file) {
                    if (is_string($file) && $this->is_active_plugin_file($file)) {
                        $this->note_site_change('plugin', 'update', $file, $this->plugin_display_name($file));
                    }
                }
            } elseif ('theme' === $type) {
                $themes = isset($hook_extra['themes']) ? (array) $hook_extra['themes'] : (isset($hook_extra['theme']) ? array($hook_extra['theme']) : array());
                $active = array_filter(array((string) get_option('stylesheet', ''), (string) get_option('template', '')));
                foreach (array_slice($themes, 0, 200) as $slug) {
                    if (is_string($slug) && in_array($slug, $active, true)) {
                        $this->note_site_change('theme', 'update', $slug, $this->theme_display_name($slug));
                    }
                }
            }
        } catch (Throwable $e) {
            // Nothing here may break an update.
        }
    }

    /**
     * upgrader_overwrote_package: a ZIP uploaded over an installed plugin or theme. WP gives only its headers, so
     * the change counts when an active plugin, the active theme or its parent has that name.
     */
    public function note_overwritten_package($package = '', $data = array(), $package_type = '')
    {
        $name = is_array($data) && isset($data['Name']) && is_string($data['Name']) ? trim($data['Name']) : '';
        if ('' === $name) {
            return;
        }
        try {
            if ('plugin' === $package_type && function_exists('get_plugins')) {
                foreach ((array) get_plugins() as $file => $plugin) {
                    if (is_string($file) && is_array($plugin) && isset($plugin['Name']) && $name === $plugin['Name'] && $this->is_active_plugin_file($file)) {
                        $this->note_site_change('plugin', 'update', $file, $name);
                    }
                }
            } elseif ('theme' === $package_type) {
                foreach (array_unique(array_filter(array((string) get_option('stylesheet', ''), (string) get_option('template', '')))) as $slug) {
                    if ($name === $this->theme_display_name($slug)) {
                        $this->note_site_change('theme', 'update', $slug, $name);
                    }
                }
            }
        } catch (Throwable $e) {
            // Nothing here may break an upload.
        }
    }

    /** switch_theme: the new theme, by the name WP passes. */
    public function note_theme_switch($new_name = '')
    {
        try {
            $slug = (string) get_option('stylesheet', '');
            $this->note_site_change('theme', 'activate', 'switch', is_string($new_name) && '' !== trim($new_name) ? $new_name : $this->theme_display_name($slug));
        } catch (Throwable $e) {
            // Nothing here may break a theme switch.
        }
    }

    public function note_plugin_activated($plugin = '')
    {
        $this->note_plugin_switch($plugin, 'activate');
    }

    public function note_plugin_deactivated($plugin = '')
    {
        $this->note_plugin_switch($plugin, 'deactivate');
    }

    private function note_plugin_switch($plugin, $action)
    {
        if (!is_string($plugin) || '' === $plugin || $plugin === $this->own_plugin_file()) {
            return;
        }
        try {
            $this->note_site_change('plugin', $action, $plugin, $this->plugin_display_name($plugin));
        } catch (Throwable $e) {
            // Nothing here may break an activation.
        }
    }

    /** plugins/static-bridge/static-bridge.php as WP names it: «static-bridge/static-bridge.php». */
    private function own_plugin_file()
    {
        return function_exists('plugin_basename') ? plugin_basename(__FILE__) : basename(__DIR__) . '/' . basename(__FILE__);
    }

    /** An active plugin (also network-wide), never Static Bridge itself. */
    private function is_active_plugin_file($file)
    {
        if (!is_string($file) || '' === $file || $file === $this->own_plugin_file()) {
            return false;
        }
        if (in_array($file, (array) get_option('active_plugins', array()), true)) {
            return true;
        }
        if (function_exists('is_multisite') && is_multisite() && function_exists('get_site_option')) {
            $network = get_site_option('active_sitewide_plugins', array());
            return is_array($network) && isset($network[$file]);
        }
        return false;
    }

    /** The Plugin Name of the file's headers when WP can read them, otherwise its folder. */
    private function plugin_display_name($file)
    {
        $file = (string) $file;
        if (function_exists('get_plugin_data') && !preg_match('#(?:\A|/)\.\.(?:/|\z)#', $file) && is_readable(WP_PLUGIN_DIR . '/' . $file)) {
            $data = get_plugin_data(WP_PLUGIN_DIR . '/' . $file, false, false);
            if (is_array($data) && isset($data['Name']) && is_string($data['Name']) && '' !== trim($data['Name'])) {
                return $data['Name'];
            }
        }
        $folder = dirname($file);
        return '.' === $folder ? basename($file, '.php') : $folder;
    }

    private function theme_display_name($slug)
    {
        if (function_exists('wp_get_theme')) {
            $theme = wp_get_theme((string) $slug);
            $name = is_object($theme) && method_exists($theme, 'get') ? $theme->get('Name') : '';
            if (is_string($name) && '' !== trim($name)) {
                return $name;
            }
        }
        return (string) $slug;
    }

    /**
     * Notes one change: by type and file, the last action wins. Only with a release online (without one there is
     * nothing old to say). Keeps the AFTER_UPDATE_MAX_ITEMS most recent and counts the others; with «Rigenera dopo gli
     * aggiornamenti» it moves the single event to the end of the wait.
     */
    private function note_site_change($type, $action, $id, $name)
    {
        if (!$this->current_release()) {
            return;
        }
        $now = time();
        $state = $this->after_update_state();
        $key = $type . ':' . substr((string) $id, 0, 200);
        unset($state['items'][$key]);
        $state['items'][$key] = array('type' => $type, 'action' => $action, 'name' => self::short_change_name($name), 'at' => $now);
        while (count($state['items']) > self::AFTER_UPDATE_MAX_ITEMS) {
            array_shift($state['items']);
            $state['more']++;
        }
        $state['first'] = $state['first'] > 0 ? min($state['first'], $now) : $now;
        $state['last'] = $now;
        update_option(self::AFTER_UPDATE_OPTION, $state, false);
        if ($this->regenerate_after_updates_enabled()) {
            $this->schedule_after_update_export();
        }
    }

    private static function short_change_name($name)
    {
        $name = trim(sanitize_text_field((string) $name));
        $name = function_exists('mb_substr') ? mb_substr($name, 0, 80, 'UTF-8') : substr($name, 0, 80);
        return '' !== $name ? $name : '?';
    }

    /** AFTER_UPDATE_OPTION as {items: key => {type, action, name, at}, first, last, more}, whatever is stored. */
    private function after_update_state()
    {
        $stored = get_option(self::AFTER_UPDATE_OPTION, array());
        $state = array('items' => array(), 'first' => 0, 'last' => 0, 'more' => 0);
        if (!is_array($stored)) {
            return $state;
        }
        $actions = array('core' => array('update'), 'plugin' => array('update', 'activate', 'deactivate'), 'theme' => array('update', 'activate'));
        foreach (isset($stored['items']) && is_array($stored['items']) ? $stored['items'] : array() as $key => $item) {
            if (is_string($key) && is_array($item) && isset($item['type'], $item['action'], $item['name'], $item['at'])
                && is_string($item['type']) && isset($actions[$item['type']]) && in_array($item['action'], $actions[$item['type']], true)) {
                $state['items'][$key] = array('type' => $item['type'], 'action' => $item['action'], 'name' => self::short_change_name($item['name']), 'at' => max(0, (int) $item['at']));
            }
        }
        $state['items'] = array_slice($state['items'], -self::AFTER_UPDATE_MAX_ITEMS, null, true);
        foreach (array('first', 'last', 'more') as $field) {
            $state[$field] = isset($stored[$field]) && is_numeric($stored[$field]) ? max(0, (int) $stored[$field]) : 0;
        }
        return $state;
    }

    /** «aggiornamento di WordPress, Contact Form attivato e altri 2»: the changes in the viewer's language. */
    private function after_update_summary($state)
    {
        $parts = array();
        foreach ($state['items'] as $item) {
            if ('core' === $item['type']) {
                $parts[] = __('aggiornamento di WordPress', 'static-bridge');
            } elseif ('theme' === $item['type']) {
                $parts[] = 'update' === $item['action']
                    ? sprintf(/* translators: %s: theme name */ __('aggiornamento del tema %s', 'static-bridge'), $item['name'])
                    : sprintf(/* translators: %s: theme name */ __('tema %s attivato', 'static-bridge'), $item['name']);
            } elseif ('update' === $item['action']) {
                $parts[] = sprintf(/* translators: %s: plugin name */ __('aggiornamento di %s', 'static-bridge'), $item['name']);
            } else {
                $parts[] = 'activate' === $item['action']
                    ? sprintf(/* translators: %s: plugin name */ __('%s attivato', 'static-bridge'), $item['name'])
                    : sprintf(/* translators: %s: plugin name */ __('%s disattivato', 'static-bridge'), $item['name']);
            }
        }
        if ($state['more'] > 0) {
            $parts[] = sprintf(/* translators: %s: number of other changes */ _n('un altro cambiamento', 'altri %s cambiamenti', $state['more'], 'static-bridge'), number_format_i18n($state['more']));
        }
        $last = array_pop($parts);
        return empty($parts) ? (string) $last : sprintf(/* translators: 1: comma-separated list, 2: last item */ __('%1$s e %2$s', 'static-bridge'), implode(', ', $parts), $last);
    }

    /** A full export that published: the changes made before it started are in the release now. */
    private function forget_changes_before($started_at)
    {
        $state = $this->after_update_state();
        if (empty($state['items'])) {
            if (false !== get_option(self::AFTER_UPDATE_OPTION, false)) {
                delete_option(self::AFTER_UPDATE_OPTION);
            }
            return;
        }
        $started_at = (int) $started_at;
        $left = array_filter($state['items'], function ($item) use ($started_at) {
            return $item['at'] >= $started_at;
        });
        if (empty($left)) {
            delete_option(self::AFTER_UPDATE_OPTION);
            wp_clear_scheduled_hook(self::AFTER_UPDATE_HOOK);
            return;
        }
        if (count($left) === count($state['items'])) {
            return;
        }
        $times = array_column($left, 'at');
        update_option(self::AFTER_UPDATE_OPTION, array('items' => $left, 'first' => min($times), 'last' => max($times), 'more' => 0), false);
    }

    private function regenerate_after_updates_enabled()
    {
        $settings = get_option(self::SETTINGS_OPTION, array());
        return is_array($settings) && !empty($settings['regenerate_after_updates']);
    }

    /** The end of the wait: the last change + AFTER_UPDATE_WAIT, never past the first + twice that. */
    private function after_update_due($state)
    {
        $now = time();
        $first = min($now, max(1, (int) $state['first']));
        $last = min($now, max($first, (int) $state['last']));
        return min($last + self::AFTER_UPDATE_WAIT, $first + 2 * self::AFTER_UPDATE_WAIT);
    }

    /** Replaces the single event with one at $at (or at the end of the wait). Returns its time, or 0. */
    private function schedule_after_update_export($at = 0)
    {
        wp_clear_scheduled_hook(self::AFTER_UPDATE_HOOK);
        $state = $this->after_update_state();
        if (empty($state['items'])) {
            return 0;
        }
        $at = max(time(), $at > 0 ? (int) $at : $this->after_update_due($state));
        return false === wp_schedule_single_event($at, self::AFTER_UPDATE_HOOK) ? 0 : $at;
    }

    /**
     * WP is updating: the .maintenance file (wp_is_maintenance_mode(), which ignores one older than 10 minutes), or
     * the lock of the automatic updates (the whole series of a background run) or of a core update.
     */
    private function site_update_in_progress()
    {
        if (function_exists('wp_is_maintenance_mode') ? wp_is_maintenance_mode() : file_exists(ABSPATH . '.maintenance')) {
            return true;
        }
        foreach (array('auto_updater.lock' => 3600, 'core_updater.lock' => 900) as $lock => $timeout) {
            $since = get_option($lock, false);
            if (false !== $since && is_numeric($since) && time() - (int) $since < $timeout) {
                return true;
            }
        }
        return false;
    }

    /**
     * Callback of static_bridge_after_update_export, only with «Rigenera dopo gli aggiornamenti». One full export at a
     * time: an export started after the last change already brings it; an older one, maintenance or an updater lock
     * make it look again after AFTER_UPDATE_RETRY; a paused export is never replaced (the notice stays).
     */
    public function run_after_update_export()
    {
        try {
            $state = $this->after_update_state();
            if (empty($state['items']) || !$this->regenerate_after_updates_enabled() || !$this->current_release()) {
                return;
            }
            $now = time();
            if ($this->after_update_due($state) > $now) {
                $this->schedule_after_update_export();
                return;
            }
            if ($this->site_update_in_progress()) {
                $this->schedule_after_update_export($now + self::AFTER_UPDATE_RETRY);
                return;
            }
            if ($this->job_is_running()) {
                $job = get_option(self::JOB_OPTION, array());
                if (!is_array($job) || (int) ($job['started_at'] ?? 0) < $state['last']) {
                    $this->schedule_after_update_export($now + self::AFTER_UPDATE_RETRY);
                }
                return;
            }
            $job = $this->start_export('update');
            if (!is_wp_error($job)) {
                $this->log_activity(__('Rigenerazione dopo gli aggiornamenti avviata.', 'static-bridge'), $this->after_update_summary($state));
                return;
            }
            $code = $job->get_error_code();
            if ('static_bridge_export_running' === $code) {
                $this->schedule_after_update_export($now + self::AFTER_UPDATE_RETRY);
            } elseif ('static_bridge_export_paused' === $code) {
                $this->log_activity(__('Rigenerazione dopo gli aggiornamenti saltata: c’è un’esportazione in pausa.', 'static-bridge'), $job->get_error_message(), true);
            } else {
                $this->log_activity(__('Rigenerazione dopo gli aggiornamenti non avviata.', 'static-bridge'), $job->get_error_message(), true);
            }
        } catch (Throwable $e) {
            $this->log_activity(__('Rigenerazione dopo gli aggiornamenti non avviata: errore interno.', 'static-bridge'), sanitize_text_field($e->getMessage()), true);
        }
    }

    /**
     * The notice, to whoever may run an export, on the dashboard, Plugins, Themes, Updates and Static Bridge's page;
     * not without a release, not while an export runs (it brings the changes, or the notice comes back after it).
     */
    public function render_after_update_notice()
    {
        if (!$this->can_run_exports() || !function_exists('get_current_screen')) {
            return;
        }
        $screen = get_current_screen();
        if (!$screen || !in_array((string) $screen->id, array('dashboard', 'plugins', 'themes', 'update-core', 'toplevel_page_' . self::ADMIN_SLUG), true)) {
            return;
        }
        $state = $this->after_update_state();
        if (empty($state['items']) || !$this->current_release() || $this->job_is_running()) {
            return;
        }
        $text = sprintf(
            /* translators: %s: list of changes, such as «aggiornamento di WordPress e Contact Form attivato» */
            __('Static Bridge: la copia statica è di prima di questi cambiamenti: %s. Le pagine statiche possono richiamare file CSS e JavaScript vecchi o mostrare il sito com’era finché non la rigeneri con un export completo.', 'static-bridge'),
            $this->after_update_summary($state)
        );
        $next = $this->regenerate_after_updates_enabled() ? (int) wp_next_scheduled(self::AFTER_UPDATE_HOOK) : 0;
        if ($next > 0) {
            $text .= ' ' . sprintf(/* translators: %s: date and time */ __('La rigenerazione automatica parte il %s, a manutenzione finita.', 'static-bridge'), $this->format_site_datetime($next));
        }
        ?>
        <div class="notice notice-warning sb-after-update-notice">
            <p><?php echo esc_html($text); ?></p>
            <form method="post" action="<?php echo esc_url(admin_url('admin-post.php')); ?>">
                <input type="hidden" name="action" value="static_bridge_after_update">
                <?php wp_nonce_field('static_bridge_after_update'); ?>
                <p><button type="submit" class="button button-primary" name="do" value="regenerate"><?php esc_html_e('Rigenera', 'static-bridge'); ?></button>
                    <button type="submit" class="button" name="do" value="dismiss"><?php esc_html_e('Ignora', 'static-bridge'); ?></button></p>
            </form>
        </div>
        <?php
    }

    /**
     * admin-post static_bridge_after_update: «Rigenera» starts the full export as the Generate tab does (same checks,
     * same refusals); «Ignora» forgets the changes. The export capability, then the nonce.
     */
    public function handle_after_update()
    {
        if (!$this->can_run_exports()) {
            wp_die(esc_html__('Non hai i permessi necessari.', 'static-bridge'), '', array('response' => 403));
        }
        check_admin_referer('static_bridge_after_update');
        $do = isset($_POST['do']) && is_string($_POST['do']) ? sanitize_key(wp_unslash($_POST['do'])) : '';
        if ('dismiss' === $do) {
            $state = $this->after_update_state();
            delete_option(self::AFTER_UPDATE_OPTION);
            wp_clear_scheduled_hook(self::AFTER_UPDATE_HOOK);
            if (!empty($state['items'])) {
                $this->log_activity(__('Avviso dopo gli aggiornamenti ignorato: la copia statica resta quella di prima.', 'static-bridge'), $this->after_update_summary($state));
            }
            $back = function_exists('wp_get_referer') ? wp_get_referer() : false;
            wp_safe_redirect(is_string($back) && '' !== $back ? $back : admin_url());
            exit;
        }
        if ('regenerate' !== $do) {
            wp_die(esc_html__('Azione sconosciuta.', 'static-bridge'), '', array('response' => 400));
        }
        $job = $this->start_export('notice');
        if (is_wp_error($job)) {
            $data = $job->get_error_data();
            wp_die(esc_html($job->get_error_message()), '', array('response' => is_array($data) && isset($data['status']) ? (int) $data['status'] : 500, 'back_link' => true));
        }
        wp_safe_redirect($this->tab_url('generate'));
        exit;
    }

    /** What WP-Cron does for whom: the single events of Static Bridge, by hook, for the WP-Cron check (2.5.0). */
    private function cron_hook_labels()
    {
        return array(
            'static_bridge_process_incremental_queue' => __('aggiornamenti incrementali', 'static-bridge'),
            'static_bridge_process_export_queue' => __('export completo', 'static-bridge'),
            self::SCHEDULED_EXPORT_HOOK => __('export pianificato', 'static-bridge'),
            self::NIGHTLY_PATHS_HOOK => __('pagine da aggiornare ogni notte', 'static-bridge'),
            self::LAYOUT_REFRESH_HOOK => __('aggiornamento dopo menu e widget', 'static-bridge'),
            self::AFTER_UPDATE_HOOK => __('rigenerazione dopo gli aggiornamenti', 'static-bridge'),
            self::LINK_CHECK_HOOK => __('controllo dei link', 'static-bridge'),
            self::RETENTION_HOOK => __('conservazione delle release', 'static-bridge'),
            self::CLOUDFLARE_PURGE_HOOK => __('svuotamento di Cloudflare', 'static-bridge'),
            self::SERVED_COPY_HOOK => __('copie servite da Apache', 'static-bridge'),
        );
    }

    /** site_status_tests: a direct test, read-only, with the result of the Server tab's WP-Cron check. */
    public function add_site_status_tests($tests)
    {
        if (is_array($tests)) {
            $tests['direct'] = isset($tests['direct']) && is_array($tests['direct']) ? $tests['direct'] : array();
            $tests['direct']['static_bridge_wp_cron'] = array(
                'label' => __('WP-Cron per Static Bridge', 'static-bridge'),
                'test' => array($this, 'site_status_wp_cron'),
            );
        }
        return $tests;
    }

    public function site_status_wp_cron()
    {
        $result = (new Static_Bridge_Server_Check(array('cron_hooks' => $this->cron_hook_labels())))->run('wp-cron');
        $status = is_array($result) && in_array($result['status'] ?? '', Static_Bridge_Server_Check::STATUSES, true) ? $result['status'] : 'skip';
        $health = array('pass' => 'good', 'tip' => 'recommended', 'warning' => 'critical', 'skip' => 'recommended');
        $labels = array(
            'pass' => __('WP-Cron fa partire in tempo gli aggiornamenti di Static Bridge', 'static-bridge'),
            'tip' => __('Static Bridge consiglia un cron di sistema per WP-Cron', 'static-bridge'),
            'warning' => __('WP-Cron non parte: gli aggiornamenti di Static Bridge aspettano', 'static-bridge'),
            'skip' => __('WP-Cron per Static Bridge non verificabile', 'static-bridge'),
        );
        $actions = '' !== (string) ($result['remediation'] ?? '') ? '<p>' . esc_html($result['remediation']) . '</p>' : '';
        if (current_user_can('manage_options')) {
            $actions .= '<p><a href="' . esc_url($this->tab_url('server')) . '">' . esc_html__('Apri la scheda Server', 'static-bridge') . '</a></p>';
        }
        return array(
            'label' => $labels[$status],
            'status' => $health[$status],
            'badge' => array('label' => __('Static Bridge', 'static-bridge'), 'color' => 'blue'),
            'description' => '<p>' . esc_html((string) ($result['summary'] ?? '')) . '</p>',
            'actions' => $actions,
            'test' => 'static_bridge_wp_cron',
        );
    }

    /**
     * «Pagine da aggiornare a ogni pubblicazione» and «Pagine da aggiornare ogni notte» (2.5.0): one line each, a
     * path of this site (/eventi/) or its full address. Checked as the other routes the plugin queues
     * (sanitize_public_urls()): another host, a query or a fragment, a file, «..» or a path kept with WP are refused.
     * Returns {paths: route paths, at most MAX_REFRESH_PATHS, invalid: refused lines, dropped: lines past the limit}.
     */
    private function sanitize_refresh_paths($lines)
    {
        $result = array('paths' => array(), 'invalid' => array(), 'dropped' => 0);
        foreach (is_array($lines) ? $lines : array() as $line) {
            if (!is_string($line) || '' === ($line = trim($line))) {
                continue;
            }
            $urls = strlen($line) <= 2048 && !preg_match('/[\s?#]/', $line) ? $this->sanitize_public_urls(array($line)) : array();
            $path = empty($urls) ? '' : $this->normalize_route_path($urls[0]);
            if ('' === $path) {
                $result['invalid'][] = $line;
            } elseif (!in_array($path, $result['paths'], true)) {
                if (count($result['paths']) >= self::MAX_REFRESH_PATHS) {
                    $result['dropped']++;
                } else {
                    $result['paths'][] = $path;
                }
            }
        }
        return $result;
    }

    /** A stored list of refresh paths: route paths only, without duplicates, at most MAX_REFRESH_PATHS. */
    private function stored_refresh_paths($settings, $key)
    {
        $paths = array();
        foreach (isset($settings[$key]) && is_array($settings[$key]) ? $settings[$key] : array() as $path) {
            $path = is_string($path) ? $this->normalize_route_path($path) : '';
            if ('' !== $path && !in_array($path, $paths, true)) {
                $paths[] = $path;
            }
        }
        return array_slice($paths, 0, self::MAX_REFRESH_PATHS);
    }

    /** The URLs of «Pagine da aggiornare a ogni pubblicazione», checked again now (an excluded path drops out). */
    private function publish_refresh_urls()
    {
        $paths = $this->settings()['publish_paths'];
        return empty($paths) ? array() : $this->sanitize_public_urls($paths);
    }

    /**
     * Replaces the single event of «Pagine da aggiornare ogni notte» with one at the next NIGHTLY_PATHS_TIME of the
     * site's time zone (right after the date changes, for lists that depend on it), or only removes it when the list
     * is empty. Returns the time scheduled, or 0.
     */
    private function schedule_nightly_paths($now = null)
    {
        wp_clear_scheduled_hook(self::NIGHTLY_PATHS_HOOK);
        if (empty($this->settings()['nightly_paths'])) {
            return 0;
        }
        $next = $this->next_scheduled_export_time(array('scheduled_export' => 'daily', 'scheduled_export_time' => self::NIGHTLY_PATHS_TIME), $now);
        if ($next < 1) {
            return 0;
        }
        return false === wp_schedule_single_event($next, self::NIGHTLY_PATHS_HOOK) ? 0 : $next;
    }

    /**
     * Callback of static_bridge_nightly_paths (2.5.0): queues the nightly paths like static_bridge_queue_paths does
     * (refresh, dependent), with incremental updates on and a release, and always schedules the next night.
     */
    public function run_nightly_paths()
    {
        try {
            $paths = $this->settings()['nightly_paths'];
            if (empty($paths) || empty($this->settings()['incremental_enabled']) || !$this->current_release()) {
                return;
            }
            $queued = $this->enqueue_incremental_urls($this->sanitize_public_urls($paths), 0, 'refresh', array(), 'dependent');
            if ($queued > 0) {
                $this->log_activity(
                    __('Pagine da aggiornare ogni notte accodate.', 'static-bridge'),
                    sprintf(/* translators: %d: number of queued paths */ __('Percorsi accodati: %d.', 'static-bridge'), (int) $queued)
                );
            }
        } catch (Throwable $e) {
            $this->log_activity(__('Pagine da aggiornare ogni notte non accodate: errore interno.', 'static-bridge'), sanitize_text_field($e->getMessage()), true);
        } finally {
            $this->schedule_nightly_paths();
        }
    }

    private function manual_excluded_paths()
    {
        $settings = get_option(self::SETTINGS_OPTION, array());
        $paths = is_array($settings) && isset($settings['excluded_paths']) && is_array($settings['excluded_paths'])
            ? $settings['excluded_paths']
            : array('/iscriviti/', '/contatti/');
        $normalized = array();
        foreach ($paths as $path) {
            $path = $this->normalize_route_path($path);
            if ('' !== $path && '/' !== $path && !in_array($path, $normalized, true)) {
                $normalized[] = $path;
            }
        }
        return $normalized;
    }

    private function woocommerce_plugin_installed()
    {
        return defined('WP_PLUGIN_DIR') && is_file(trailingslashit(WP_PLUGIN_DIR) . 'woocommerce/woocommerce.php');
    }

    private function woocommerce_is_active()
    {
        return class_exists('WooCommerce') && function_exists('wc_get_page_id');
    }

    private function woocommerce_pages()
    {
        if (!$this->woocommerce_is_active()) {
            return array();
        }
        $page_names = array(
            'cart' => __('Carrello', 'static-bridge'),
            'checkout' => __('Checkout', 'static-bridge'),
            'myaccount' => __('Il mio account', 'static-bridge'),
        );
        $pages = array();
        foreach ($page_names as $page_name => $label) {
            $page_id = (int) wc_get_page_id($page_name);
            if ($page_id < 1 || 'publish' !== get_post_status($page_id)) {
                continue;
            }
            $url = get_permalink($page_id);
            $path = $this->normalize_route_path($url);
            if ('' === $path || '/' === $path) {
                continue;
            }
            $pages[$path] = array(
                'path' => $path,
                'url' => $url,
                'label' => $label,
            );
        }
        return array_values($pages);
    }

    /** With WooCommerce active, switch on or off: a static cart, checkout, account or payment answer is never right. */
    private function woocommerce_dynamic_paths()
    {
        if (!$this->woocommerce_is_active()) {
            return array();
        }
        return array_values(array_unique(array_merge(array_column($this->woocommerce_pages(), 'path'), $this->woocommerce_endpoint_paths())));
    }

    /**
     * WooCommerce is active and the integration is on: on until an administrator saves the settings with the switch
     * off (woocommerce_decided), because a shop with the integration off has a stale catalog (2.2.13). Read without
     * settings(), which calls back into here.
     */
    private function woocommerce_integration_enabled()
    {
        $settings = get_option(self::SETTINGS_OPTION, array());
        if (!$this->woocommerce_is_active() || !is_array($settings)) {
            return false;
        }
        return empty($settings['woocommerce_decided']) || !empty($settings['woocommerce_enabled']);
    }

    /**
     * Prefixes WooCommerce answers outside its pages: /wc-api/ (payment gateway callbacks and returns, also by GET)
     * and /wc-auth/ (REST API key authorization). Kept from the export and routed to WordPress, so that Strict
     * never answers 404 for them.
     */
    private function woocommerce_endpoint_paths()
    {
        return array('/wc-api/', '/wc-auth/');
    }

    /** Before a product or variation is written: what changed, and the lists it was in when a list may change. */
    public function note_woocommerce_product_changes($product)
    {
        if (!is_object($product) || !method_exists($product, 'get_id') || !method_exists($product, 'get_changes')) {
            return;
        }
        $id = (int) $product->get_id();
        if ($id < 1 || '' !== $this->render_request_token()) {
            // A new product (woocommerce_new_product follows) or a write during a render.
            return;
        }
        $changes = array_keys((array) $product->get_changes());
        $known = isset($this->woocommerce_product_changes[$id]) ? $this->woocommerce_product_changes[$id] : array();
        $this->woocommerce_product_changes[$id] = array_values(array_unique(array_merge($known, $changes)));
        // Terms, visibility and slug are written by the data store without wp_update_post(): remember the lists
        // the product leaves, as remember_incremental_old_archives() does for an edit in the editor.
        if (array_intersect($changes, array('category_ids', 'tag_ids', 'catalog_visibility', 'slug', 'status'))
            && !isset($this->incremental_old_archive_urls[$id]) && $this->woocommerce_catalog_refresh_enabled()) {
            $post = get_post($id);
            if ($post instanceof WP_Post && 'product' === $post->post_type && 'publish' === $post->post_status) {
                $this->incremental_old_archive_urls[$id] = $this->archive_urls_for_post($post);
            }
        }
    }

    public function note_woocommerce_new_product($product_id)
    {
        $this->queue_woocommerce_product($product_id, 'lists');
    }

    /** After a save: the product page, and its lists unless only page-only properties changed (a stock count). */
    public function note_woocommerce_product_saved($product_id)
    {
        $id = (int) $product_id;
        $changes = isset($this->woocommerce_product_changes[$id]) ? $this->woocommerce_product_changes[$id] : array();
        unset($this->woocommerce_product_changes[$id]);
        $this->queue_woocommerce_product($id, array() === array_diff($changes, self::WOOCOMMERCE_PAGE_ONLY_CHANGES) ? 'page' : 'lists');
    }

    /** woocommerce_product_set_stock, woocommerce_variation_set_stock: the count shows on the product page. */
    public function note_woocommerce_product_page($product)
    {
        $this->queue_woocommerce_product($product, 'page');
    }

    /** Stock status, catalog order, a variation removed: the lists show it too (price range, "out of stock"). */
    public function note_woocommerce_product_lists($product)
    {
        $this->queue_woocommerce_product($product, 'lists');
    }

    private function queue_woocommerce_product($product, $scope)
    {
        $id = is_object($product) && method_exists($product, 'get_id') ? (int) $product->get_id() : (is_numeric($product) ? (int) $product : 0);
        if ($id < 1 || '' !== $this->render_request_token() || !$this->woocommerce_integration_enabled()) {
            return;
        }
        // A variation shows on its parent's page and in the parent's lists.
        if ('product_variation' === get_post_type($id)) {
            $id = (int) wp_get_post_parent_id($id);
            if ($id < 1) {
                return;
            }
        }
        if (empty($this->woocommerce_pending_products)) {
            // One write of the queue at the end of the request, for every product an order or an import touched.
            add_action('shutdown', array($this, 'flush_woocommerce_catalog_changes'));
        }
        if ('lists' === $scope || !isset($this->woocommerce_pending_products[$id])) {
            $this->woocommerce_pending_products[$id] = 'lists' === $scope ? 'lists' : 'page';
        }
    }

    private function woocommerce_catalog_refresh_enabled()
    {
        return $this->woocommerce_integration_enabled() && !empty($this->settings()['incremental_enabled']) && '' !== (string) $this->current_release();
    }

    /**
     * At shutdown: queues the page of every product changed in this request (a variation counts as its parent),
     * the pages that show it with its price (grouped products, up-sells) and, when a list may have changed, the
     * shop, its categories and tags with all their pages, the home and the pages with a product block or loop.
     */
    public function flush_woocommerce_catalog_changes()
    {
        $pending = $this->woocommerce_pending_products;
        $this->woocommerce_pending_products = array();
        $this->woocommerce_product_changes = array();
        if (empty($pending) || !$this->woocommerce_catalog_refresh_enabled()) {
            return;
        }
        $lists = array();
        $with_lists = false;
        foreach ($pending as $product_id => $scope) {
            $old_lists = isset($this->incremental_old_archive_urls[(int) $product_id]) ? $this->incremental_old_archive_urls[(int) $product_id] : array();
            unset($this->incremental_old_archive_urls[(int) $product_id]);
            $lists = array_merge($lists, $old_lists);
            $post = get_post((int) $product_id);
            if (!$this->is_public_incremental_post($post) || 'publish' !== $post->post_status || $this->is_shared_content_post_type($post->post_type)) {
                // Withdrawn or deleted: wp_after_insert_post and before_delete_post remove its page.
                continue;
            }
            $this->enqueue_incremental_url(get_permalink($post), (int) $post->ID, 'refresh', $this->page_builders($post), 'single');
            foreach ($this->woocommerce_products_showing((int) $post->ID) as $other_id) {
                $other = get_post($other_id);
                if ($this->is_public_incremental_post($other) && 'publish' === $other->post_status) {
                    $lists[] = get_permalink($other);
                }
            }
            if ('lists' === $scope || !empty($old_lists)) {
                $lists = array_merge($lists, $this->archive_urls_for_post($post));
                $with_lists = true;
                // «Related products» are drawn at random from the same categories and tags (2.3.0).
                foreach ($this->woocommerce_products_sharing_terms((int) $post->ID) as $related_id) {
                    $lists[] = get_permalink($related_id);
                }
            }
        }
        if ($with_lists) {
            $lists = array_merge($lists, $this->discover_query_page_urls());
        }
        $lists = array_values(array_unique(array_filter($lists, 'is_string')));
        if (!empty($lists)) {
            $this->enqueue_incremental_urls($lists, 0, 'refresh', array(), 'dependent');
        }
    }

    /**
     * Published products in the same categories or tags, the ones whose «Related products» may show this one:
     * at most WOOCOMMERCE_RELATED_LIMIT, the most recently changed first.
     */
    private function woocommerce_products_sharing_terms($product_id)
    {
        $terms = array();
        foreach (array('product_cat', 'product_tag') as $taxonomy) {
            $ids = function_exists('wp_get_post_terms') ? wp_get_post_terms((int) $product_id, $taxonomy, array('fields' => 'ids')) : array();
            if (is_array($ids) && !empty($ids)) {
                $terms[] = array('taxonomy' => $taxonomy, 'field' => 'term_id', 'terms' => array_map('intval', $ids));
            }
        }
        if (empty($terms)) {
            return array();
        }
        $limit = max(0, min(500, (int) apply_filters('static_bridge_woocommerce_related_limit', self::WOOCOMMERCE_RELATED_LIMIT)));
        if (0 === $limit) {
            return array();
        }
        $ids = get_posts(array(
            'post_type' => 'product',
            'post_status' => 'publish',
            'posts_per_page' => $limit,
            'post__not_in' => array((int) $product_id),
            'orderby' => 'modified',
            'order' => 'DESC',
            'fields' => 'ids',
            'no_found_rows' => true,
            'has_password' => false,
            'tax_query' => array_merge(array('relation' => 'OR'), $terms),
        ));
        return array_values(array_diff(array_map('intval', is_array($ids) ? $ids : array()), array((int) $product_id)));
    }

    /** Products whose page shows this one with its price: grouped products that contain it, products that up-sell it. */
    private function woocommerce_products_showing($product_id)
    {
        global $wpdb;
        if (!is_object($wpdb) || !isset($wpdb->postmeta) || (int) $product_id < 1) {
            return array();
        }
        // Both metas are serialized lists of integers: a:2:{i:0;i:30;i:1;i:12;}. A match on an index is only an
        // extra refresh.
        $like = '%' . $wpdb->esc_like('i:' . (int) $product_id . ';') . '%';
        $ids = $wpdb->get_col($wpdb->prepare(
            "SELECT DISTINCT post_id FROM {$wpdb->postmeta} WHERE meta_key IN ('_children', '_upsell_ids') AND meta_value LIKE %s LIMIT 50",
            $like
        ));
        return array_values(array_diff(array_map('intval', is_array($ids) ? $ids : array()), array((int) $product_id)));
    }

    /**
     * The image, display type and order of a product category are term meta: the WooCommerce REST API and the category
     * screen change them without edited_term. The category archive, the shop, the home and the pages with products show them.
     */
    public function maybe_queue_woocommerce_term_meta($meta_id, $term_id, $meta_key)
    {
        if (!in_array((string) $meta_key, array('thumbnail_id', 'display_type', 'order'), true) || '' !== $this->render_request_token()
            || !$this->woocommerce_catalog_refresh_enabled() || !function_exists('get_term')) {
            return;
        }
        $term = get_term((int) $term_id);
        $taxonomy = is_object($term) && !is_wp_error($term) && isset($term->taxonomy) ? (string) $term->taxonomy : '';
        $taxonomy_object = '' !== $taxonomy && function_exists('get_taxonomy') ? get_taxonomy($taxonomy) : null;
        if (!$taxonomy_object || empty($taxonomy_object->public) || !in_array('product', (array) $taxonomy_object->object_type, true)) {
            return;
        }
        $urls = $this->term_route_urls((int) $term_id, $taxonomy);
        $shop = function_exists('get_post_type_archive_link') ? get_post_type_archive_link('product') : '';
        $urls = array_merge($urls, array(home_url('/')), is_string($shop) && '' !== $shop ? array($shop) : array(), $this->discover_query_page_urls());
        $this->enqueue_incremental_urls(array_values(array_unique($urls)), 0, 'refresh', array(), 'dependent');
    }

    public function maybe_note_woocommerce_option($option)
    {
        if ($this->woocommerce_option_change_noted || !is_string($option) || !in_array($option, self::WOOCOMMERCE_DISPLAY_OPTIONS, true)) {
            return;
        }
        $this->woocommerce_option_change_noted = true;
        add_action('shutdown', array($this, 'maybe_queue_woocommerce_settings_refresh'));
    }

    /** At the end of a request that changed a store setting shown in every page: one refresh of all the routes. */
    public function maybe_queue_woocommerce_settings_refresh()
    {
        if ('' !== $this->render_request_token() || !$this->woocommerce_integration_enabled() || '' === (string) $this->current_release()) {
            return;
        }
        $fingerprint = $this->woocommerce_fingerprint();
        if ($fingerprint === get_option(self::WOOCOMMERCE_FINGERPRINT_OPTION)) {
            return;
        }
        update_option(self::WOOCOMMERCE_FINGERPRINT_OPTION, $fingerprint, false);
        $this->woocommerce_dynamic_routes_cache = null;
        // The cart, checkout and account pages may have moved: the rules name them (the Nginx block is pasted again).
        if (!$this->update_routing_rules()) {
            $this->log_activity(__('Impostazioni WooCommerce cambiate, ma .htaccess non aggiornato.', 'static-bridge'), __('Il server non consente la scrittura del file .htaccess.', 'static-bridge'), true);
        }
        $this->queue_shared_output_refresh(__('Le impostazioni del negozio WooCommerce sono cambiate.', 'static-bridge'));
    }

    private function woocommerce_fingerprint()
    {
        $state = array();
        foreach (self::WOOCOMMERCE_DISPLAY_OPTIONS as $option) {
            $state[$option] = get_option($option);
        }
        return sha1(serialize($state));
    }

    /** The render token of this request, once: '' on every request that is not a Static Bridge render. */
    private function render_request_token()
    {
        if (null === $this->render_request_token_cache) {
            $this->render_request_token_cache = $this->dynamic_render_response_token();
        }
        return $this->render_request_token_cache;
    }

    /**
     * Filter nonce_life, which wp_create_nonce() applies with the action (WordPress 6.1+). During a render for
     * Static Bridge it notes the action, so that the end of the render can tell which nonces the page prints.
     */
    public function record_render_nonce_action($life, $action = -1)
    {
        if ((is_string($action) || is_int($action)) && !isset($this->render_nonce_actions[(string) $action])
            && '' !== $this->render_request_token()) {
            if (count($this->render_nonce_actions) >= self::MAX_RENDER_NONCE_ACTIONS) {
                $this->render_nonce_overflow = true;
            } else {
                $this->render_nonce_actions[(string) $action] = $action;
            }
        }
        return $life;
    }

    /** wp_headers, last: whether WordPress or a plugin asked not to cache this page (nocache_headers()). */
    public function record_render_cache_headers($headers)
    {
        if (is_array($headers) && '' !== $this->render_request_token()) {
            foreach ($headers as $name => $value) {
                if (is_string($name) && 'cache-control' === strtolower($name) && preg_match('/\b(?:private|no-store)\b/i', (string) $value)) {
                    $this->render_private = true;
                }
            }
        }
        return $headers;
    }

    /**
     * What the render of this page carried, for the worker: the nonce actions whose current value is in the
     * HTML, whether WooCommerce took it for a cart, checkout or account page, whether it was marked private.
     */
    private function render_facts($html)
    {
        $nonces = array();
        foreach ($this->render_nonce_actions as $key => $action) {
            $value = wp_create_nonce($action);
            if (is_string($value) && strlen($value) >= 8 && false !== strpos($html, $value)) {
                $nonces[(string) $key] = $value;
            }
        }
        $woocommerce = false;
        if (function_exists('is_cart') && function_exists('is_checkout') && function_exists('is_account_page')) {
            $woocommerce = is_cart() || is_checkout() || is_account_page() || (function_exists('is_wc_endpoint_url') && is_wc_endpoint_url());
        }
        return array('nonces' => $nonces, 'nonce_overflow' => $this->render_nonce_overflow, 'woocommerce' => $woocommerce, 'private' => $this->render_private);
    }

    /** Takes the render facts of this token out of the body; anything malformed counts as no facts. */
    private function extract_render_facts($body, $render_token)
    {
        $facts = array('nonces' => array(), 'nonce_overflow' => false, 'woocommerce' => false, 'private' => false);
        if (!is_string($render_token) || !preg_match('/^[a-f0-9]{48}$/', $render_token)) {
            return array($body, $facts);
        }
        $pattern = '~<!--static-bridge-facts:' . $render_token . ':([A-Za-z0-9+/=]{0,20000})-->~';
        if (preg_match_all($pattern, $body, $matches)) {
            $decoded = json_decode((string) base64_decode((string) end($matches[1]), true), true);
            if (is_array($decoded)) {
                foreach (isset($decoded['nonces']) && is_array($decoded['nonces']) ? $decoded['nonces'] : array() as $action => $value) {
                    if (count($facts['nonces']) < self::MAX_RENDER_NONCE_ACTIONS && preg_match('/\A[\x20-\x7E]{1,190}\z/', (string) $action)
                        && is_string($value) && preg_match('/\A[a-f0-9]{8,32}\z/', $value)) {
                        $facts['nonces'][(string) $action] = $value;
                    }
                }
                foreach (array('nonce_overflow', 'woocommerce', 'private') as $flag) {
                    $facts[$flag] = !empty($decoded[$flag]);
                }
            }
            $body = preg_replace($pattern, '', $body);
        }
        return array($body, $facts);
    }

    /**
     * Before writing a page with the WooCommerce integration on: a cart, checkout or account page, a page marked
     * private, or a page with a nonce Static Bridge cannot renew stays with WordPress (that route only). A page with
     * the Store API or REST nonce gets assets/woocommerce-static.js, which asks for fresh ones.
     */
    private function prepare_woocommerce_static_html($url, $html, $facts)
    {
        $html = (string) $html;
        $facts = is_array($facts) ? $facts : array();
        if (!$this->woocommerce_integration_enabled()) {
            // Switched off on purpose: still never a static cart, checkout or account (a page with the shortcode too).
            return $this->woocommerce_is_active() && !empty($facts['woocommerce'])
                ? new WP_Error('static_bridge_woocommerce_dynamic', sprintf(/* translators: %s: list of reasons */ __('WooCommerce: la pagina resta dinamica perché %s.', 'static-bridge'), __('è il carrello, il checkout o l’account di WooCommerce', 'static-bridge')), array('path' => $this->normalize_route_path($url), 'actions' => array()))
                : $html;
        }
        $nonces = $this->without_fluent_forms_vars_nonce($html, isset($facts['nonces']) && is_array($facts['nonces']) ? $facts['nonces'] : array());
        $static_actions = apply_filters('static_bridge_static_nonce_actions', array());
        $allowed = array_merge(self::RENEWABLE_NONCE_ACTIONS, array('wp_rest'), is_array($static_actions) ? array_filter($static_actions, 'is_string') : array());
        $blocking = array_values(array_diff(array_map('strval', array_keys($nonces)), $allowed));
        $reasons = array();
        if (!empty($facts['woocommerce'])) {
            $reasons[] = __('è il carrello, il checkout o l’account di WooCommerce', 'static-bridge');
        }
        if (!empty($facts['private'])) {
            $reasons[] = __('WordPress ha chiesto di non metterla in cache (Cache-Control private o no-store)', 'static-bridge');
        }
        if (!empty($blocking)) {
            $reasons[] = sprintf(/* translators: %s: comma-separated nonce actions */ __('contiene nonce che Static Bridge non sa rinnovare (%s)', 'static-bridge'), implode(', ', array_map('sanitize_text_field', array_slice($blocking, 0, 5))));
        }
        if (!empty($facts['nonce_overflow'])) {
            $reasons[] = __('crea troppi nonce diversi per controllarli tutti', 'static-bridge');
        }
        if (!empty($reasons)) {
            return new WP_Error(
                'static_bridge_woocommerce_dynamic',
                sprintf(/* translators: %s: list of reasons */ __('WooCommerce: la pagina resta dinamica perché %s.', 'static-bridge'), implode('; ', $reasons)),
                array('path' => $this->normalize_route_path($url), 'actions' => array_slice($blocking, 0, 20))
            );
        }
        $renew = array_intersect_key($nonces, array('wc_store_api' => 1, 'wp_rest' => 1));
        if (empty($renew) || false !== strpos($html, 'id="static-bridge-woocommerce"')) {
            return $html;
        }
        $tag = '<script id="static-bridge-woocommerce" src="'
            . esc_url(plugin_dir_url(__FILE__) . 'assets/woocommerce-static.js?ver=' . self::VERSION)
            . '" data-endpoint="' . esc_url(admin_url('admin-ajax.php')) . '" data-stale="' . esc_attr((string) wp_json_encode($renew)) . '" defer></script>';
        foreach (array('~</head\s*>~i', '~</body\s*>~i') as $closing) {
            if (preg_match($closing, $html, $match, PREG_OFFSET_CAPTURE)) {
                return substr($html, 0, $match[0][1]) . $tag . substr($html, $match[0][1]);
            }
        }
        return $html . $tag;
    }

    /**
     * Fluent Forms prints wp_create_nonce() with no action (-1) as fluentFormVars.nonce on every page with a form:
     * Fluent Forms itself never verifies it (only the step-form progress of Fluent Forms Pro sends it back), and
     * assets/fluent-forms-static.js renews it with the other Fluent Forms nonces. When that is the only place the
     * value appears, it is not a nonce Static Bridge cannot renew (2.4.1: every page with a footer form stayed
     * dynamic). The same value anywhere else in the page still counts.
     */
    private function without_fluent_forms_vars_nonce($html, $nonces)
    {
        if (!isset($nonces['-1']) || !is_string($nonces['-1']) || '' === $nonces['-1']) {
            return $nonces;
        }
        $value = $nonces['-1'];
        $found = false;
        $rest = preg_replace_callback(
            '~\bvar\s+fluentFormVars\s*=\s*(\{.*?\});(?=\s*(?:var\s|/\*|</script>))~s',
            static function ($match) use ($value, &$found) {
                $vars = json_decode($match[1], true);
                if (!is_array($vars) || !isset($vars['nonce']) || $value !== $vars['nonce']) {
                    return $match[0];
                }
                $found = true;
                return str_replace('"nonce":"' . $value . '"', '"nonce":""', $match[0]);
            },
            (string) $html
        );
        if ($found && is_string($rest) && false === strpos($rest, $value)) {
            unset($nonces['-1']);
        }
        return $nonces;
    }

    /** Fluent Forms, then WooCommerce: the HTML to write, or the WP_Error that keeps the route with WordPress. */
    private function prepare_static_html($url, $result)
    {
        $prepared = $this->prepare_fluent_forms_static_html($url, $result['body']);
        if (is_wp_error($prepared)) {
            return $prepared;
        }
        return $this->prepare_woocommerce_static_html($url, $prepared, isset($result['render_facts']) ? $result['render_facts'] : array());
    }

    /** Records the route of a page prepare_static_html() refused, in the list of its plugin. */
    private function record_dynamic_route_for($error, $url)
    {
        $data = (array) $error->get_error_data();
        if ('static_bridge_woocommerce_dynamic' === $error->get_error_code()) {
            return $this->record_woocommerce_dynamic_route($url, $error->get_error_message(), isset($data['actions']) ? $data['actions'] : array());
        }
        return $this->record_fluent_forms_dynamic_route($url, $error->get_error_message(), isset($data['form_ids']) ? $data['form_ids'] : array());
    }

    /**
     * 2.5.0: what a page about to be saved says against a copy that stays the same for hours: Cache-Control private
     * or no-store asked by WP or a plugin (nocache_headers()), a nonce nobody renews in the browser, more nonce
     * actions than the render can check. With the WooCommerce integration on such a page already stays with WP
     * (prepare_woocommerce_static_html()); otherwise it is saved as before and the reasons only go to one line of the
     * export issues and of Attività. '' when there is nothing to say.
     */
    private function cache_signal_reason($html, $facts)
    {
        $html = (string) $html;
        $facts = is_array($facts) ? $facts : array();
        $nonces = $this->without_fluent_forms_vars_nonce($html, isset($facts['nonces']) && is_array($facts['nonces']) ? $facts['nonces'] : array());
        $static_actions = apply_filters('static_bridge_static_nonce_actions', array());
        $renewed = is_array($static_actions) ? array_values(array_filter($static_actions, 'is_string')) : array();
        // A nonce is renewed in the browser only where the script that renews it is in the page.
        if (false !== strpos($html, 'id="static-bridge-fluent-forms"')) {
            $renewed = array_merge($renewed, array_diff(self::RENEWABLE_NONCE_ACTIONS, array('wc_store_api')));
        }
        if (false !== strpos($html, 'id="static-bridge-woocommerce"')) {
            $renewed = array_merge($renewed, array('wc_store_api', 'wp_rest'));
        }
        $stale = array_values(array_diff(array_map('strval', array_keys($nonces)), $renewed));
        $reasons = array();
        if (!empty($facts['private'])) {
            $reasons[] = __('WordPress ha chiesto di non metterla in cache (Cache-Control private o no-store)', 'static-bridge');
        }
        if (!empty($stale)) {
            $reasons[] = sprintf(/* translators: %s: comma-separated nonce actions */ __('contiene nonce che Static Bridge non sa rinnovare (%s)', 'static-bridge'), implode(', ', array_map('sanitize_text_field', array_slice($stale, 0, 5))));
        }
        if (!empty($facts['nonce_overflow'])) {
            $reasons[] = __('crea troppi nonce diversi per controllarli tutti', 'static-bridge');
        }
        return implode('; ', $reasons);
    }

    /** Counts a saved page with cache signals; the first MAX_CACHE_SIGNAL_PAGES are named with their reasons. */
    private function note_cache_signal(&$signals, $url, $reason)
    {
        if ('' === (string) $reason) {
            return;
        }
        $signals = is_array($signals) ? $signals : array();
        $signals['count'] = max(0, (int) ($signals['count'] ?? 0)) + 1;
        $pages = isset($signals['pages']) && is_array($signals['pages']) ? $signals['pages'] : array();
        $path = $this->normalize_route_path($url);
        if ('' !== $path && count($pages) < self::MAX_CACHE_SIGNAL_PAGES) {
            $pages[$path] = (string) $reason;
        }
        $signals['pages'] = $pages;
    }

    /** The one line for the job issues and Attività: how many pages, the first ones with their reasons, what to do. */
    private function cache_signals_message($signals)
    {
        $count = is_array($signals) ? max(0, (int) ($signals['count'] ?? 0)) : 0;
        if ($count < 1) {
            return '';
        }
        $listed = array();
        foreach (isset($signals['pages']) && is_array($signals['pages']) ? $signals['pages'] : array() as $path => $reason) {
            $listed[] = $path . ' (' . $reason . ')';
        }
        if ($count > count($listed)) {
            $listed[] = '…';
        }
        return sprintf(
            /* translators: 1: number of pages, 2: list of pages with their reasons */
            _n('%1$s pagina salvata nella copia statica ha chiesto di non essere messa in cache o contiene nonce che scadono: %2$s.', '%1$s pagine salvate nella copia statica hanno chiesto di non essere messe in cache o contengono nonce che scadono: %2$s.', $count, 'static-bridge'),
            number_format_i18n($count),
            implode('; ', $listed)
        ) . ' ' . __('Sono state salvate come prima. Un nonce vale da 12 a 24 ore: se in una di queste pagine un modulo o un pulsante smette di funzionare, escludila dalla copia statica; se il nonce scaduto non rompe niente, dichiaralo con il filtro static_bridge_static_nonce_actions.', 'static-bridge');
    }

    /** End of a worker run or of a push: one Attività line for the pages saved with cache signals, then forgets them. */
    private function flush_incremental_cache_signals()
    {
        $message = $this->cache_signals_message($this->incremental_cache_signals);
        $this->incremental_cache_signals = array();
        if ('' !== $message) {
            $this->log_activity(__('Pagine salvate con un segnale «non mettere in cache» o con nonce che scadono.', 'static-bridge'), $message, true);
        }
    }

    /** Routes kept with WordPress by the WooCommerce integration (see prepare_woocommerce_static_html()). */
    private function woocommerce_dynamic_routes()
    {
        if (!is_array($this->woocommerce_dynamic_routes_cache)) {
            $routes = array();
            $stored = get_option(self::WOOCOMMERCE_DYNAMIC_OPTION, array());
            foreach (is_array($stored) ? $stored : array() as $path => $info) {
                $path = $this->normalize_route_path($path);
                if ('' === $path || !is_array($info)) {
                    continue;
                }
                $actions = isset($info['actions']) && is_array($info['actions']) ? $info['actions'] : array();
                $routes[$path] = array(
                    'reason' => isset($info['reason']) ? sanitize_text_field((string) $info['reason']) : '',
                    'actions' => array_values(array_unique(array_map('sanitize_text_field', array_filter($actions, 'is_string')))),
                    'at' => isset($info['at']) ? (int) $info['at'] : 0,
                );
            }
            $this->woocommerce_dynamic_routes_cache = $routes;
        }
        return $this->woocommerce_dynamic_routes_cache;
    }

    private function record_woocommerce_dynamic_route($path, $reason, $actions)
    {
        $path = $this->normalize_route_path($path);
        if ('' === $path) {
            return false;
        }
        $routes = $this->woocommerce_dynamic_routes();
        $entry = array(
            'reason' => sanitize_text_field((string) $reason),
            'actions' => array_values(array_unique(array_map('sanitize_text_field', array_filter((array) $actions, 'is_string')))),
            'at' => time(),
        );
        if (isset($routes[$path]) && $routes[$path]['reason'] === $entry['reason'] && $routes[$path]['actions'] === $entry['actions']) {
            return true;
        }
        if (!isset($routes[$path]) && count($routes) >= self::MAX_WOOCOMMERCE_DYNAMIC_ROUTES) {
            return false;
        }
        $routes[$path] = $entry;
        $this->woocommerce_dynamic_routes_cache = null;
        update_option(self::WOOCOMMERCE_DYNAMIC_OPTION, $routes, false);
        $stored = $this->woocommerce_dynamic_routes();
        return isset($stored[$path]) && $stored[$path]['reason'] === $entry['reason'];
    }

    private function forget_woocommerce_dynamic_route($path)
    {
        $path = $this->normalize_route_path($path);
        $routes = $this->woocommerce_dynamic_routes();
        if ('' === $path || !isset($routes[$path])) {
            return true;
        }
        unset($routes[$path]);
        $this->woocommerce_dynamic_routes_cache = null;
        empty($routes) ? delete_option(self::WOOCOMMERCE_DYNAMIC_OPTION) : update_option(self::WOOCOMMERCE_DYNAMIC_OPTION, $routes, false);
        return !isset($this->woocommerce_dynamic_routes()[$path]);
    }

    /** After a publication, routes that have a static file again no longer need WordPress. */
    private function prune_woocommerce_dynamic_routes()
    {
        $routes = $this->woocommerce_dynamic_routes();
        $kept = array();
        foreach ($routes as $path => $info) {
            if (!$this->static_file_exists_for_path($path)) {
                $kept[$path] = $info;
            }
        }
        if (count($kept) !== count($routes)) {
            $this->woocommerce_dynamic_routes_cache = null;
            empty($kept) ? delete_option(self::WOOCOMMERCE_DYNAMIC_OPTION) : update_option(self::WOOCOMMERCE_DYNAMIC_OPTION, $kept, false);
        }
    }

    /**
     * Fresh Store API and REST nonces for a static shop page (admin-ajax, POST, no-store). For an anonymous
     * visitor user and session are empty: these are the values every dynamic page prints, and the Store API sends
     * the same one back in its Nonce header to anybody. No request input is read: the actions are fixed.
     */
    public function ajax_public_woocommerce_nonces()
    {
        nocache_headers();
        if (!headers_sent()) {
            header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0, private');
            header('X-Robots-Tag: noindex, nofollow');
        }
        if (!$this->woocommerce_integration_enabled()) {
            wp_send_json_error(null, 404);
        }
        $data = array();
        $ttl = PHP_INT_MAX;
        foreach (array('store_api' => 'wc_store_api', 'rest' => 'wp_rest') as $key => $action) {
            $data[$key] = wp_create_nonce($action);
            $life = (int) apply_filters('nonce_life', defined('DAY_IN_SECONDS') ? DAY_IN_SECONDS : 86400, $action);
            $ttl = min($ttl, (int) floor($life / 2));
        }
        // A nonce stays valid for at least half its lifetime after it is created.
        $data['ttl'] = max(60, $ttl);
        wp_send_json_success($data);
    }

    private function form_modes()
    {
        $stored = get_option(self::FORM_MODES_OPTION, array());
        if (!is_array($stored)) {
            return array();
        }
        $modes = array();
        foreach ($stored as $path => $mode) {
            $path = $this->normalize_route_path($path);
            if (!is_string($mode)) {
                continue;
            }
            $mode = sanitize_key($mode);
            if ('' !== $path && in_array($mode, array('static', 'dynamic'), true)) {
                $modes[$path] = $mode;
            }
        }
        return $modes;
    }

    private function managed_dynamic_form_paths()
    {
        $paths = array();
        foreach ($this->form_modes() as $path => $mode) {
            if ('dynamic' === $mode) {
                $paths[] = $path;
            }
        }
        if (!$this->fluent_forms_nonce_refresh_enabled() && $this->fluent_form_token_protection_configured()) {
            if (!is_array($this->token_protected_form_paths_cache)) {
                $this->token_protected_form_paths_cache = array();
                foreach ($this->discover_form_pages() as $form_page) {
                    if (!empty($form_page['token_protection_enabled'])) {
                        $this->token_protected_form_paths_cache[] = $form_page['path'];
                    }
                }
            }
            $paths = array_merge($paths, $this->token_protected_form_paths_cache);
        }
        return $paths;
    }

    private function fluent_form_token_protection_configured()
    {
        $settings = get_option('_fluentform_global_form_settings', array());
        $globally_enabled = is_array($settings)
            && isset($settings['misc']['tokenBasedProtectionStatus'])
            && 'yes' === $settings['misc']['tokenBasedProtectionStatus'];

        return $globally_enabled
            || (function_exists('has_filter') && false !== has_filter('fluentform/token_based_spam_protection_status'));
    }

    private function fluent_form_token_protection_enabled($form_ids)
    {
        $settings = get_option('_fluentform_global_form_settings', array());
        $enabled = is_array($settings)
            && isset($settings['misc']['tokenBasedProtectionStatus'])
            && 'yes' === $settings['misc']['tokenBasedProtectionStatus'];
        $form_ids = is_array($form_ids) ? array_values(array_unique(array_filter(array_map('absint', $form_ids)))) : array();

        if (empty($form_ids)) {
            return $enabled;
        }

        foreach ($form_ids as $form_id) {
            if (function_exists('apply_filters')) {
                $form_enabled = apply_filters('fluentform/token_based_spam_protection_status', $enabled, (int) $form_id);
            } else {
                $form_enabled = $enabled;
            }
            if ($form_enabled) {
                return true;
            }
        }

        return false;
    }

    /** The static nonce refresh is on unless switched off in the Moduli tab. */
    private function fluent_forms_nonce_refresh_enabled()
    {
        $stored = get_option(self::FLUENT_FORMS_REFRESH_OPTION, 1);
        return !(0 === $stored || '0' === $stored || false === $stored || '' === $stored);
    }

    private function fluent_forms_active()
    {
        return defined('FLUENTFORM_VERSION');
    }

    /**
     * Prepare the HTML of a page that is about to be written as a static copy.
     *
     * Fluent Forms prints nonces that expire after 12-24 hours: token_nonce in
     * fluentFormVars (token-based spam protection) and the per-form submit
     * nonce (checked when fluentform/nonce_verify is on). Per-page fields such
     * as __fluent_form_embded_post_id and _wp_http_referer stay as rendered.
     * When every form on the page has the markers the refresher understands,
     * a deferred script is added; it asks WordPress for current nonces the
     * first time a visitor uses a form, before Fluent Forms sends them.
     * Unknown markup on a form that needs fresh nonces returns an error, so the
     * route stays WordPress-dynamic instead of publishing a copy that breaks.
     *
     * @return string|WP_Error
     */
    private function prepare_fluent_forms_static_html($url, $html)
    {
        $html = (string) $html;
        if (!$this->fluent_forms_nonce_refresh_enabled() || false === stripos($html, 'frm-fluent-form')
            || false !== strpos($html, 'id="static-bridge-fluent-forms"')) {
            return $html;
        }
        $forms = $this->fluent_forms_in_html($html);
        if (empty($forms)) {
            return $html;
        }
        $vars = $this->fluent_forms_global_vars($html);
        $problems = array();
        $blocking = array();
        foreach ($forms as $form) {
            $form_id = $form['id'];
            $token = $this->fluent_form_token_protection_enabled(array($form_id));
            $verify = (bool) apply_filters('fluentform/nonce_verify', false, (int) $form_id);
            $problem = '';
            if (!is_array($vars) || empty($vars['ajaxUrl'])) {
                $problem = __('fluentFormVars assente o non leggibile', 'static-bridge');
            } elseif (!preg_match('~\bname\s*=\s*(["\']?)_fluentform_' . $form_id . '_fluentformnonce\1~', $form['markup'])) {
                $problem = __('campo nonce di invio assente', 'static-bridge');
            } elseif ($token && !array_key_exists('token_nonce', $vars)) {
                $problem = __('token_nonce assente in fluentFormVars', 'static-bridge');
            } elseif ($token && false === strpos($form['markup'], 'fluent-form-token-field')) {
                $problem = __('campo token anti-spam assente', 'static-bridge');
            }
            if ('' === $problem) {
                continue;
            }
            $problems[$form_id] = $problem;
            if ($token || $verify) {
                $blocking[$form_id] = $problem;
            }
        }
        if (!empty($blocking)) {
            $reasons = array();
            foreach ($blocking as $form_id => $problem) {
                $reasons[] = sprintf(/* translators: 1: form ID, 2: problem found */ __('modulo %1$s: %2$s', 'static-bridge'), $form_id, $problem);
            }
            return new WP_Error(
                'static_bridge_fluentforms_dynamic',
                sprintf(/* translators: %s: list of the problems found */ __('Fluent Forms: markup non riconosciuto (%s); la pagina resta dinamica.', 'static-bridge'), implode('; ', array_unique($reasons))),
                array('path' => $this->normalize_route_path($url), 'form_ids' => array_map('strval', array_keys($blocking)))
            );
        }
        if (!empty($problems)) {
            // Nothing on these forms expires: keep the plain static copy.
            return $html;
        }
        $tag = '<script id="static-bridge-fluent-forms" src="'
            . esc_url(plugin_dir_url(__FILE__) . 'assets/fluent-forms-static.js?ver=' . self::VERSION)
            . '" data-endpoint="' . esc_url(admin_url('admin-ajax.php')) . '" defer></script>';
        foreach (array('~</head\s*>~i', '~</body\s*>~i') as $closing) {
            if (preg_match($closing, $html, $match, PREG_OFFSET_CAPTURE)) {
                return substr($html, 0, $match[0][1]) . $tag . substr($html, $match[0][1]);
            }
        }
        return $html . $tag;
    }

    /** Fluent Forms <form> elements: numeric data-form_id, frm-fluent-form class, inner markup. */
    private function fluent_forms_in_html($html)
    {
        $forms = array();
        if (!preg_match_all('~<form\b([^>]*)>~i', $html, $tags, PREG_SET_ORDER | PREG_OFFSET_CAPTURE)) {
            return $forms;
        }
        foreach ($tags as $tag) {
            $attributes = $tag[1][0];
            if (!preg_match('~\bclass\s*=\s*(["\'])[^"\']*\bfrm-fluent-form\b~i', $attributes)
                || !preg_match('~\bdata-form_id\s*=\s*(["\']?)(\d+)\1~i', $attributes, $id_match)
                || (int) $id_match[2] < 1) {
                continue;
            }
            $start = $tag[0][1] + strlen($tag[0][0]);
            $end = stripos($html, '</form', $start);
            $forms[] = array(
                'id' => (string) absint($id_match[2]),
                'markup' => false === $end ? substr($html, $start) : substr($html, $start, $end - $start),
            );
        }
        return $forms;
    }

    /** The fluentFormVars object printed by wp_localize_script; the last assignment wins in the browser. */
    private function fluent_forms_global_vars($html)
    {
        if (!preg_match_all('~\bvar\s+fluentFormVars\s*=\s*(\{.*?\});(?=\s*(?:var\s|/\*|</script>))~s', $html, $matches)) {
            return null;
        }
        $vars = json_decode((string) end($matches[1]), true);
        return is_array($vars) ? $vars : null;
    }

    /** Routes kept WordPress-dynamic because their Fluent Forms markup was not recognized. */
    private function fluent_forms_dynamic_routes()
    {
        if (!is_array($this->fluent_forms_dynamic_routes_cache)) {
            $routes = array();
            $stored = get_option(self::FLUENT_FORMS_DYNAMIC_OPTION, array());
            foreach (is_array($stored) ? $stored : array() as $path => $info) {
                $path = $this->normalize_route_path($path);
                if ('' === $path || !is_array($info)) {
                    continue;
                }
                $form_ids = isset($info['form_ids']) && is_array($info['form_ids']) ? $info['form_ids'] : array();
                $routes[$path] = array(
                    'reason' => isset($info['reason']) ? sanitize_text_field((string) $info['reason']) : '',
                    'form_ids' => array_values(array_unique(array_map('strval', array_filter(array_map('absint', $form_ids))))),
                    'at' => isset($info['at']) ? (int) $info['at'] : 0,
                );
            }
            $this->fluent_forms_dynamic_routes_cache = $routes;
        }
        return $this->fluent_forms_dynamic_routes_cache;
    }

    private function record_fluent_forms_dynamic_route($path, $reason, $form_ids)
    {
        $path = $this->normalize_route_path($path);
        if ('' === $path) {
            return false;
        }
        $routes = $this->fluent_forms_dynamic_routes();
        $entry = array(
            'reason' => sanitize_text_field((string) $reason),
            'form_ids' => array_values(array_unique(array_map('strval', array_filter(array_map('absint', (array) $form_ids))))),
            'at' => time(),
        );
        if (isset($routes[$path]) && $routes[$path]['reason'] === $entry['reason'] && $routes[$path]['form_ids'] === $entry['form_ids']) {
            return true;
        }
        if (!isset($routes[$path]) && count($routes) >= self::MAX_FLUENT_FORMS_DYNAMIC_ROUTES) {
            return false;
        }
        $routes[$path] = $entry;
        $this->fluent_forms_dynamic_routes_cache = null;
        update_option(self::FLUENT_FORMS_DYNAMIC_OPTION, $routes, false);
        $stored = $this->fluent_forms_dynamic_routes();
        return isset($stored[$path]) && $stored[$path]['reason'] === $entry['reason'];
    }

    private function forget_fluent_forms_dynamic_route($path)
    {
        $path = $this->normalize_route_path($path);
        $routes = $this->fluent_forms_dynamic_routes();
        if ('' === $path || !isset($routes[$path])) {
            return true;
        }
        unset($routes[$path]);
        $this->fluent_forms_dynamic_routes_cache = null;
        update_option(self::FLUENT_FORMS_DYNAMIC_OPTION, $routes, false);
        return !isset($this->fluent_forms_dynamic_routes()[$path]);
    }

    /** After a publication, routes that have a static file again no longer need the fallback. */
    private function prune_fluent_forms_dynamic_routes()
    {
        foreach (array_keys($this->fluent_forms_dynamic_routes()) as $path) {
            if ($this->static_file_exists_for_path($path)) {
                $this->forget_fluent_forms_dynamic_route($path);
            }
        }
    }

    /**
     * Fresh Fluent Forms nonces for a static page (admin-ajax, POST, no-store).
     *
     * wp_create_nonce() is bound to the current user and session token; for
     * logged-out visitors both are empty (unless a plugin filters
     * nonce_user_logged_out), so these are the values every anonymous dynamic
     * page prints, and admin-ajax verifies them in the same request context.
     * No request input is read: the actions are fixed and form-independent.
     */
    public function ajax_public_form_nonces()
    {
        nocache_headers();
        if (!headers_sent()) {
            header('Cache-Control: no-store, no-cache, must-revalidate, max-age=0, private');
            header('X-Robots-Tag: noindex, nofollow');
        }
        if (!$this->fluent_forms_active() || !$this->fluent_forms_nonce_refresh_enabled()) {
            wp_send_json_error(null, 404);
        }
        $actions = array(
            'submit_nonce' => 'fluentform-submit-form',
            'file_delete_nonce' => 'fluentform_file_delete',
            // fluentFormVars.nonce: wp_create_nonce() with no action, as Fluent Forms prints it (2.4.1).
            'vars_nonce' => -1,
        );
        if ($this->fluent_form_token_protection_configured()) {
            $actions['token_nonce'] = 'fluentform_generate_token_nonce';
        }
        $data = array();
        $ttl = PHP_INT_MAX;
        foreach ($actions as $key => $action) {
            $data[$key] = wp_create_nonce($action);
            $life = (int) apply_filters('nonce_life', defined('DAY_IN_SECONDS') ? DAY_IN_SECONDS : 86400, $action);
            $ttl = min($ttl, (int) floor($life / 2));
        }
        // A nonce stays valid for at least half its lifetime after it is created.
        $data['ttl'] = max(60, $ttl);
        wp_send_json_success($data);
    }

    public function save_form_nonce_refresh()
    {
        if (!current_user_can('manage_options')) {
            wp_die(esc_html__('Non hai i permessi necessari.', 'static-bridge'));
        }
        check_admin_referer('static_bridge_save_form_nonce_refresh');

        $enabled = isset($_POST['fluent_forms_nonce_refresh']) ? 1 : 0;
        update_option(self::FLUENT_FORMS_REFRESH_OPTION, $enabled, false);
        $this->token_protected_form_paths_cache = null;
        $this->fluent_forms_dynamic_routes_cache = null;
        $released = 0;
        if ($enabled && !empty($_POST['release_token_dynamic_modes'])) {
            $stored = get_option(self::FORM_MODES_OPTION, array());
            $stored = is_array($stored) ? $stored : array();
            foreach ($this->discover_form_pages() as $form_page) {
                if (!empty($form_page['token_protection_enabled']) && isset($stored[$form_page['path']]) && 'dynamic' === $stored[$form_page['path']]) {
                    unset($stored[$form_page['path']]);
                    $released++;
                }
            }
            if ($released > 0) {
                update_option(self::FORM_MODES_OPTION, $stored, false);
            }
        }
        $rules_written = $this->update_routing_rules();
        if (!$rules_written) {
            $this->log_activity(__('Rinnovo nonce Fluent Forms salvato, ma .htaccess non aggiornato.', 'static-bridge'), __('Il server non consente la scrittura del file .htaccess.', 'static-bridge'), true);
        } else {
            $this->log_activity(
                $enabled ? __('Rinnovo nonce Fluent Forms attivato.', 'static-bridge') : __('Rinnovo nonce Fluent Forms disattivato.', 'static-bridge'),
                ($enabled
                    ? __('Le pagine con moduli restano statiche; lo script di rinnovo viene aggiunto alla prossima generazione o al prossimo aggiornamento della pagina.', 'static-bridge')
                    : __('Le pagine con protezione token tornano dinamiche.', 'static-bridge'))
                . ($released > 0 ? ' ' . sprintf(/* translators: %s: number of pages */ __('Pagine protette riportate a statiche: %s.', 'static-bridge'), number_format_i18n($released)) : '')
            );
        }
        wp_safe_redirect(add_query_arg(array('page' => self::ADMIN_SLUG, 'tab' => 'forms', $rules_written ? 'forms-updated' : 'forms-rules-error' => '1'), admin_url('admin.php')));
        exit;
    }

    private function routing_excluded_paths()
    {
        $paths = $this->settings()['excluded_paths'];
        if ($this->fluent_forms_nonce_refresh_enabled()) {
            // Not export exclusions: the next generation re-checks these routes.
            $paths = array_merge($paths, array_keys($this->fluent_forms_dynamic_routes()));
        }
        if ($this->woocommerce_is_active()) {
            $paths = array_merge($paths, array_keys($this->woocommerce_dynamic_routes()));
        }
        foreach ($this->discover_form_pages() as $form_page) {
            if ('static' === $form_page['mode'] && !$form_page['file_exists'] && !in_array($form_page['path'], $paths, true)) {
                $paths[] = $form_page['path'];
            }
        }
        // OpenLiteSpeed would apply these short-lived exclusions only at its next restart, and each would change
        // .htaccess and ask for one: as on Nginx, the file check of the rules is what sends a route to WP.
        $queue = 'openlitespeed' === $this->web_server_kind() ? array() : $this->incremental_queue();
        foreach ($queue as $item) {
            if (!is_array($item) || empty($item['url'])) {
                continue;
            }
            $path = $this->normalize_route_path($item['url']);
            if ('' === $path) {
                continue;
            }
            if ('delete' === (isset($item['action']) ? $item['action'] : '') || !$this->static_file_exists_for_path($path)) {
                $paths[] = $path;
            }
        }
        return array_values(array_unique($paths));
    }

    private function static_file_exists_for_path($path)
    {
        $release = $this->current_release();
        if (!$release) {
            return false;
        }
        $relative = $this->relative_html_path(home_url($path));
        return !is_wp_error($relative) && is_readable(trailingslashit($release) . $relative);
    }

    private function normalize_route_path($path)
    {
        if (!is_string($path) && !is_numeric($path)) {
            return '';
        }
        $path = (string) $path;
        $parts = wp_parse_url($path);
        if (!is_array($parts) || isset($parts['query']) || isset($parts['fragment'])) {
            return '';
        }
        if (isset($parts['host']) && !$this->same_site_url($path)) {
            return '';
        }
        $path = isset($parts['path']) ? rawurldecode($parts['path']) : '';
        if ('' === $path || preg_match('~[\x00-\x1F\\?#]~', $path)) {
            return '';
        }
        foreach (explode('/', $path) as $segment) {
            if ('.' === $segment || '..' === $segment) {
                return '';
            }
        }
        $path = trim($path, '/');
        return '' === $path ? '/' : '/' . $path . '/';
    }

    private function discover_form_pages()
    {
        $pages = array();
        $post_types = get_post_types(array('public' => true), 'names');
        unset($post_types['attachment']);
        if (!empty($post_types)) {
            $candidate_queries = array(
                array('s' => 'fluentform'),
                array('s' => 'fluentfom'),
                array(
                    'meta_query' => array(
                        'relation' => 'OR',
                        array('key' => '_elementor_data', 'value' => 'fluentform', 'compare' => 'LIKE'),
                        array('key' => '_elementor_data', 'value' => 'fluent-form-widget', 'compare' => 'LIKE'),
                        array('key' => '_bricks_page_content_2', 'value' => 'fluentform', 'compare' => 'LIKE'),
                        array('key' => '_bricks_page_content', 'value' => 'fluentform', 'compare' => 'LIKE'),
                    ),
                ),
            );
            $scan_budget = self::MAX_FORM_SCAN_POSTS;
            foreach ($candidate_queries as $candidate_query) {
                for ($page_number = 1; $scan_budget > 0; $page_number++) {
                    $page_size = min(self::FORM_SCAN_PAGE_SIZE, $scan_budget);
                    $query = array_merge(array(
                        'post_type' => array_values($post_types),
                        'post_status' => 'publish',
                        'posts_per_page' => $page_size,
                        'paged' => $page_number,
                        'fields' => 'ids',
                        'orderby' => 'ID',
                        'order' => 'ASC',
                        'no_found_rows' => true,
                    ), $candidate_query);
                    $post_ids = get_posts($query);
                    if (empty($post_ids) || !is_array($post_ids)) {
                        break;
                    }
                    $scan_budget -= count($post_ids);
                    foreach ($post_ids as $post_id) {
                        $post = get_post($post_id);
                        if (!$post) {
                            continue;
                        }
                        $form_ids = $this->extract_fluent_form_ids_from_post($post);
                        if (empty($form_ids)) {
                            continue;
                        }
                        $this->merge_form_detection($pages, get_permalink($post), get_the_title($post), $form_ids);
                    }
                    if (count($post_ids) < $page_size) {
                        break;
                    }
                }
                if ($scan_budget <= 0) {
                    break;
                }
            }
        }

        // Manual dynamic paths are a small, explicit set. Inspect their owning
        // public posts as a fallback for builder templates whose metadata is
        // not returned by a host/plugin-filtered WP_Query meta search.
        foreach (array_slice($this->manual_excluded_paths(), 0, 100) as $manual_path) {
            $post_id = url_to_postid(home_url($manual_path));
            if (!$post_id) {
                $manual_post = get_page_by_path(trim($manual_path, '/'), 'OBJECT', array_values($post_types));
                if ($manual_post && isset($manual_post->ID)) {
                    $post_id = (int) $manual_post->ID;
                }
            }
            if (!$post_id) {
                continue;
            }
            $post = get_post($post_id);
            if (!$post || 'publish' !== (string) $post->post_status
                || !in_array((string) $post->post_type, $post_types, true)
                || !empty($post->post_password)) {
                continue;
            }
            $form_ids = $this->extract_fluent_form_ids_from_post($post);
            if (!empty($form_ids)) {
                $this->merge_form_detection($pages, get_permalink($post), get_the_title($post), $form_ids);
            }
        }

        $release = $this->current_release();
        if ($release && is_dir($release)) {
            try {
                $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($release, FilesystemIterator::SKIP_DOTS));
                $scanned = 0;
                foreach ($iterator as $file) {
                    if (!$file->isFile() || 'html' !== strtolower($file->getExtension())) {
                        continue;
                    }
                    if (++$scanned > 2500 || $file->getSize() > 5242880 || !is_readable($file->getPathname())) {
                        continue;
                    }
                    $html = file_get_contents($file->getPathname());
                    if (!is_string($html) || false === stripos($html, 'fluentform')) {
                        continue;
                    }
                    $relative = ltrim(str_replace(DIRECTORY_SEPARATOR, '/', substr($file->getPathname(), strlen(trailingslashit($release)))), '/');
                    if ('index.html' === $relative) {
                        $path = '/';
                    } elseif (preg_match('~^(.*?)/index\.html$~', $relative, $relative_match)) {
                        $path = '/' . trim($relative_match[1], '/') . '/';
                    } else {
                        continue;
                    }
                    preg_match_all('/data-form_id\s*=\s*["\'](\d+)["\']/i', $html, $id_matches);
                    $url = home_url($path);
                    $post_id = url_to_postid($url);
                    $title = $post_id ? get_the_title($post_id) : $path;
                    $this->merge_form_detection($pages, $url, $title, isset($id_matches[1]) ? $id_matches[1] : array());
                }
            } catch (Exception $exception) {
                // The shortcode scan still provides the WordPress-side detections.
            }
        }

        $nonce_refresh = $this->fluent_forms_nonce_refresh_enabled();
        $dynamic_routes = $nonce_refresh ? $this->fluent_forms_dynamic_routes() : array();
        foreach ($dynamic_routes as $dynamic_path => $dynamic_route) {
            // A fallback route has no static file, so the release scan cannot list it.
            $this->merge_form_detection($pages, home_url($dynamic_path), $dynamic_path, $dynamic_route['form_ids']);
            if (isset($pages[$dynamic_path]) && $pages[$dynamic_path]['title'] === $dynamic_path) {
                $post_id = url_to_postid(home_url($dynamic_path));
                if ($post_id) {
                    $pages[$dynamic_path]['title'] = wp_strip_all_tags(get_the_title($post_id));
                }
            }
        }

        $modes = $this->form_modes();
        $manual_paths = $this->manual_excluded_paths();
        foreach ($pages as $path => &$page) {
            $page['manual_excluded'] = false;
            foreach ($manual_paths as $manual_path) {
                if (0 === strpos(trailingslashit($path), $manual_path)) {
                    $page['manual_excluded'] = true;
                    break;
                }
            }
            $page['token_protection_enabled'] = $this->fluent_form_token_protection_enabled($page['form_ids']);
            $page['nonce_refresh'] = $nonce_refresh;
            $page['saved_mode'] = isset($modes[$path]) ? $modes[$path] : 'static';
            $page['markup_fallback'] = isset($dynamic_routes[$path]) ? $dynamic_routes[$path]['reason'] : '';
            $page['mode_locked'] = $page['manual_excluded'] || ($page['token_protection_enabled'] && !$nonce_refresh) || isset($dynamic_routes[$path]);
            $page['mode'] = $page['mode_locked'] ? 'dynamic' : $page['saved_mode'];
            $page['file_exists'] = $this->static_file_exists_for_path($path);
            if (isset($dynamic_routes[$path]) && !$page['manual_excluded']) {
                $page['state'] = 'dynamic';
                $page['state_label'] = __('WordPress dinamico · markup non riconosciuto', 'static-bridge');
            } elseif ('dynamic' === $page['mode']) {
                $page['state'] = 'dynamic';
                $page['state_label'] = __('WordPress dinamico', 'static-bridge');
            } elseif ($page['file_exists']) {
                $page['state'] = 'static';
                $page['state_label'] = __('Copia statica attiva', 'static-bridge');
            } else {
                $page['state'] = 'pending';
                $page['state_label'] = __('In attesa di generazione', 'static-bridge');
            }
            sort($page['form_ids'], SORT_NUMERIC);
            $page['form_ids'] = array_values(array_unique($page['form_ids']));
        }
        unset($page);
        ksort($pages, SORT_NATURAL | SORT_FLAG_CASE);
        return array_values($pages);
    }

    private function extract_fluent_form_ids_from_post($post)
    {
        if (!$post || !isset($post->ID)) {
            return array();
        }
        $sources = array(isset($post->post_content) ? (string) $post->post_content : '');
        foreach (array('_elementor_data', '_bricks_page_content_2', '_bricks_page_content') as $meta_key) {
            $meta_value = get_post_meta((int) $post->ID, $meta_key, true);
            if (is_string($meta_value) || is_numeric($meta_value)) {
                $sources[] = (string) $meta_value;
            } elseif (is_array($meta_value) || is_object($meta_value)) {
                $encoded_meta = wp_json_encode($meta_value);
                if (is_string($encoded_meta)) {
                    $sources[] = $encoded_meta;
                }
            }
        }
        $form_ids = array();
        foreach ($sources as $source) {
            $form_ids = array_merge($form_ids, $this->extract_fluent_form_ids($source));
        }
        return array_values(array_unique($form_ids));
    }

    private function extract_fluent_form_ids($content)
    {
        $form_ids = array();
        $content = (string) $content;
        $sources = array($content);
        $trimmed_content = ltrim($content);
        if (strlen($content) <= 5242880 && isset($trimmed_content[0]) && ('[' === $trimmed_content[0] || '{' === $trimmed_content[0])) {
            $decoded_content = json_decode($content, true);
            if (is_array($decoded_content)) {
                $values = array($decoded_content);
                $visited = 0;
                while (!empty($values) && $visited < 10000) {
                    $value = array_pop($values);
                    $visited++;
                    if (is_string($value)) {
                        if ('' !== $value) {
                            $sources[] = $value;
                        }
                    } elseif (is_array($value)) {
                        if (isset($value['widgetType'], $value['settings'])
                            && 'fluent-form-widget' === $value['widgetType']
                            && is_array($value['settings'])
                            && isset($value['settings']['form_list'])
                            && ctype_digit((string) $value['settings']['form_list'])
                            && (int) $value['settings']['form_list'] > 0) {
                            $form_ids[] = (string) absint($value['settings']['form_list']);
                        }
                        foreach ($value as $nested_value) {
                            $values[] = $nested_value;
                        }
                    }
                }
            }
        }
        foreach ($sources as $source) {
            if (preg_match_all('/\[\s*fluentform\b([^\]]*)\]/i', $source, $shortcodes)) {
                foreach ($shortcodes[1] as $attributes) {
                    $attributes = shortcode_parse_atts($attributes);
                    if (is_array($attributes) && isset($attributes['id']) && ctype_digit((string) $attributes['id'])) {
                        $form_ids[] = (string) absint($attributes['id']);
                    }
                }
            }
            if (preg_match_all('~<!--\s*wp:(?:fluentform/form|fluentfom/guten-block)\s+(.+?)\s*/?\s*-->~is', $source, $blocks)) {
                foreach ($blocks[1] as $attributes) {
                    $attributes = trim((string) $attributes);
                    if ('/' === substr($attributes, -1)) {
                        $attributes = rtrim(substr($attributes, 0, -1));
                    }
                    $attributes = json_decode($attributes, true);
                    if (!is_array($attributes)) {
                        continue;
                    }
                    foreach (array('formId', 'form_id', 'id') as $key) {
                        if (isset($attributes[$key]) && ctype_digit((string) $attributes[$key]) && (int) $attributes[$key] > 0) {
                            $form_ids[] = (string) absint($attributes[$key]);
                            break;
                        }
                    }
                }
            }
        }
        return array_values(array_unique($form_ids));
    }

    private function merge_form_detection(&$pages, $url, $title, $form_ids)
    {
        $path = $this->normalize_route_path($url);
        if ('' === $path) {
            return;
        }
        if (!isset($pages[$path])) {
            $pages[$path] = array(
                'path' => $path,
                'url' => home_url($path),
                'title' => '' !== (string) $title ? wp_strip_all_tags($title) : $path,
                'form_ids' => array(),
            );
        }
        foreach ((array) $form_ids as $form_id) {
            if (ctype_digit((string) $form_id) && (int) $form_id > 0) {
                $pages[$path]['form_ids'][] = (string) absint($form_id);
            }
        }
    }

    private function static_root()
    {
        return trailingslashit(WP_CONTENT_DIR) . 'static-bridge';
    }

    /**
     * On OpenLiteSpeed, wp-content/static-bridge/.htaccess refuses at once every direct request to the folder:
     * unlike the root .htaccess, read only when the server starts, a folder's .htaccess is read again when it
     * changes, and the root rules that serve the static pages end the rewriting before it. Elsewhere the file goes,
     * when it is ours: Apache may refuse its directives in a subfolder and answer 500 to every static page.
     */
    private function sync_openlitespeed_folder_guard()
    {
        $root = $this->static_root();
        if (is_link($root) || !is_dir($root)) {
            return;
        }
        $file = $root . '/.htaccess';
        $ours = !is_link($file) && is_file($file) && self::OPENLITESPEED_FOLDER_GUARD === @file_get_contents($file);
        if ('openlitespeed' !== $this->web_server_kind()) {
            if ($ours) {
                @unlink($file);
            }
            return;
        }
        if ($ours || file_exists($file) || is_link($file)) {
            // Ours, or someone else's: never overwritten.
            return;
        }
        $temporary = $file . '.static-bridge-' . wp_generate_password(6, false, false) . '.tmp';
        if (strlen(self::OPENLITESPEED_FOLDER_GUARD) === @file_put_contents($temporary, self::OPENLITESPEED_FOLDER_GUARD, LOCK_EX)) {
            @chmod($temporary, 0644);
            if (@rename($temporary, $file)) {
                return;
            }
        }
        if (file_exists($temporary) || is_link($temporary)) {
            @unlink($temporary);
        }
        $this->log_activity(__('Protezione della cartella statica non scritta per OpenLiteSpeed.', 'static-bridge'), __('Fino al prossimo riavvio del server i file di wp-content/static-bridge restano raggiungibili per indirizzo diretto: controlla i permessi della cartella.', 'static-bridge'), true);
    }

    private function safe_release_root($create = false)
    {
        if (!defined('WP_CONTENT_DIR') || !is_dir(WP_CONTENT_DIR)) {
            return '';
        }
        $content_real = realpath(WP_CONTENT_DIR);
        if (!$content_real) {
            return '';
        }
        $root = $this->static_root();
        if (is_link($root) || (file_exists($root) && !is_dir($root))) {
            return '';
        }
        if (!is_dir($root) && (!$create || !wp_mkdir_p($root))) {
            return '';
        }
        $root_real = realpath($root);
        $expected_root = trailingslashit($content_real) . 'static-bridge';
        if (!$root_real || $root_real !== $expected_root) {
            return '';
        }
        if ($create) {
            // Before the first page is written: on OpenLiteSpeed the root rules arrive only with a restart.
            $this->sync_openlitespeed_folder_guard();
        }
        $release_root = trailingslashit($root) . 'releases';
        if (is_link($release_root) || (file_exists($release_root) && !is_dir($release_root))) {
            return '';
        }
        if (!is_dir($release_root) && (!$create || !wp_mkdir_p($release_root))) {
            return '';
        }
        $release_real = realpath($release_root);
        return $release_real && dirname($release_real) === $root_real ? $release_real : '';
    }

    private function valid_release_stage($job)
    {
        if (!is_array($job) || empty($job['release_id']) || empty($job['stage'])
            || !preg_match('/^[A-Za-z0-9_-]{1,100}$/', (string) $job['release_id'])) {
            return false;
        }
        $release_root = $this->safe_release_root(false);
        $stage = (string) $job['stage'];
        if ('' === $release_root || is_link($stage) || !is_dir($stage)) {
            return false;
        }
        $stage_real = realpath($stage);
        $expected = trailingslashit($release_root) . $job['release_id'];
        return $stage_real && $stage_real === $expected && dirname($stage_real) === $release_root;
    }

    private function current_release()
    {
        $release_root = $this->safe_release_root(false);
        $current = $this->static_root() . '/current';
        // Another PHP-FPM worker may have swapped the pointer; drop this
        // process's cached resolution so writes target the active release.
        clearstatcache(true, $current);
        if ('' === $release_root || !is_link($current)) {
            return '';
        }
        $real = realpath($current);
        return $real && is_dir($real) && dirname($real) === $release_root ? $real : '';
    }

    private function count_html_files($directory)
    {
        $count = 0;
        try {
            $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($directory, FilesystemIterator::SKIP_DOTS));
            foreach ($iterator as $file) {
                if ($file->isFile() && 'html' === strtolower($file->getExtension())) {
                    $count++;
                }
            }
        } catch (Exception $exception) {
            return 0;
        }
        return $count;
    }

    /** Genera, «Pagine dinamiche»: each path WordPress serves instead of a static copy, with the reason (2.2.14). */
    private function dynamic_pages_with_reasons()
    {
        $pages = array();
        foreach ($this->settings()['excluded_paths'] as $path) {
            $pages[(string) $path] = __('esclusa nelle Impostazioni', 'static-bridge');
        }
        foreach ($this->editor_excluded_paths() as $path) {
            $pages[(string) $path] = __('esclusa dall’editor del contenuto', 'static-bridge');
        }
        foreach ($this->woocommerce_dynamic_paths() as $path) {
            $pages[(string) $path] = __('WooCommerce: carrello, cassa, account o pagamenti', 'static-bridge');
        }
        foreach ($this->woocommerce_dynamic_routes() as $path => $info) {
            $pages[(string) $path] = __('WooCommerce: la pagina contiene dati del visitatore', 'static-bridge') . ('' !== $info['reason'] ? ' (' . $info['reason'] . ')' : '');
        }
        foreach ($this->fluent_forms_dynamic_routes() as $path => $info) {
            $pages[(string) $path] = __('modulo Fluent Forms con chiavi che scadono', 'static-bridge');
        }
        $rate_limited = get_option(self::RATE_LIMITED_ROUTES_OPTION, array());
        foreach (is_array($rate_limited) && isset($rate_limited['urls']) && is_array($rate_limited['urls']) ? $rate_limited['urls'] : array() as $url) {
            $path = $this->normalize_route_path((string) $url);
            if ('' !== $path) {
                $pages[$path] = __('omessa per errori 429 nell’ultimo export', 'static-bridge');
            }
        }
        $pages['/…?…'] = __('ogni indirizzo con parametri dopo il punto di domanda', 'static-bridge');
        return $pages;
    }

    private function release_date($release)
    {
        $last = get_option('static_bridge_last_release', array());
        if (is_array($last) && isset($last['id']) && basename($release) === $last['id'] && !empty($last['published_at'])) {
            return sprintf(/* translators: %s: date and time */ __('Pubblicato il %s', 'static-bridge'), $this->format_site_datetime($last['published_at']));
        }
        $directory = $this->static_root() . '/releases';
        $candidates = glob($directory . '/*', GLOB_ONLYDIR);
        if (!is_array($candidates)) {
            $candidates = array();
        }
        $timestamp = 0;
        foreach ($candidates as $candidate) {
            if (realpath($candidate) === $release) {
                $timestamp = filemtime($candidate);
                break;
            }
        }
        return $timestamp ? sprintf(/* translators: %s: date and time */ __('Versione del %s', 'static-bridge'), $this->format_site_datetime($timestamp)) : '';
    }

    private function sync_strict_marker($enabled)
    {
        $root = $this->static_root();
        if (is_link($root) || (file_exists($root) && !is_dir($root))) {
            return false;
        }
        if (!is_dir($root)) {
            if (!$enabled) {
                return true;
            }
            if (!wp_mkdir_p($root)) {
                return false;
            }
        }
        $marker = $root . '/.strict';
        if (is_link($marker) || (file_exists($marker) && !is_file($marker))) {
            return false;
        }
        if ($enabled && ($this->stale_release_pending() || $this->routing_held())) {
            $enabled = false;
        }
        if ($enabled && $this->current_release()) {
            if (is_file($marker)) {
                return true;
            }
            $handle = @fopen($marker, 'x');
            if (false === $handle) {
                return false;
            }
            fclose($handle);
            return true;
        }
        return !is_file($marker) || @unlink($marker);
    }

    private function sync_routing_enabled_marker($enabled)
    {
        $root = $this->static_root();
        if ($enabled && ('' === $this->safe_release_root(true) || $this->routing_held())) {
            return false;
        }
        if (is_link($root) || (file_exists($root) && !is_dir($root))) {
            return false;
        }
        $marker = trailingslashit($root) . '.enabled';
        if ($enabled) {
            if (is_link($marker) || (file_exists($marker) && !is_file($marker))) {
                return false;
            }
            if (file_exists($marker)) {
                return true;
            }
            $marker_content = "enabled\n";
            $written = @file_put_contents($marker, $marker_content, LOCK_EX);
            if (strlen($marker_content) === $written) {
                return true;
            }
            if (file_exists($marker) && !is_link($marker)) {
                @unlink($marker);
            }
            return false;
        }
        if (is_file($marker) || is_link($marker)) {
            return @unlink($marker);
        }
        return true;
    }

    private function update_routing_rules()
    {
        if ($this->routing_held()) {
            // The release may still hold a copy of content withdrawn while the plugin was off: no route is
            // served static until a full export replaces it (doc 23, item 169).
            $marker_removed = $this->sync_routing_enabled_marker(false);
            return $this->server_uses_nginx() ? $marker_removed : ($this->write_rewrite_rules(false) && $marker_removed);
        }
        // Nginx configuration is server-owned and is never edited from PHP.
        // The GUI exposes the current safe snippet; the administrator reloads Nginx.
        if ($this->server_uses_nginx()) {
            return true;
        }
        // One writer at a time: no request may publish rules older than the ones just published.
        $lock = $this->acquire_served_copy_lock();
        if (!is_resource($lock)) {
            $this->schedule_served_copy_maintenance(60);
            return false;
        }
        try {
            $record = $this->served_copy_record();
            $base = 'current';
            $copy = null;
            if ($this->served_copies_enabled() && $this->current_release() && $this->htaccess_is_writable()) {
                $copy = $this->ensure_served_copy($record);
                $root = $this->safe_served_root(false);
                if (is_wp_error($copy) && 'static_bridge_served_changed' === $copy->get_error_code()
                    && '' !== $record['id'] && '' !== $root && is_dir($root . '/' . $record['id'])) {
                    // Another writer is changing the release right now and will publish it
                    // itself: keep serving the previous (complete, immutable) copy meanwhile.
                    $copy = array('id' => $record['id'], 'created' => false, 'release' => $record['release'], 'manifest' => $record['manifest'],
                        'mode' => $record['mode'], 'files' => $record['files'], 'time' => $record['created']);
                    $this->schedule_served_copy_maintenance(60);
                }
                if (is_wp_error($copy)) {
                    if (empty($record['fallback_logged'])) {
                        $this->log_activity(
                            __('Copia immutabile per Apache non creata: le regole servono current/.', 'static-bridge'),
                            $copy->get_error_message() . ' ' . __('Il sito resta pubblicato come nella 2.0.19 (wp-content/static-bridge/current/), con il rischio raro di una pagina troncata durante una pubblicazione. Al prossimo tentativo riuscito Apache tornerà a una copia immutabile.', 'static-bridge'),
                            true
                        );
                        $record['fallback_logged'] = 1;
                    }
                    $copy = null;
                    $this->schedule_served_copy_maintenance(900);
                } else {
                    $base = 'served/' . $copy['id'];
                }
            }
            $written = $this->write_rewrite_rules(true, $base);
            if ($written) {
                $this->record_served_copy($record, $copy);
            } else {
                if (is_array($copy) && !empty($copy['created'])) {
                    // The rules never referenced it: no request can be reading it.
                    $this->remove_served_copy($copy['id']);
                }
                $this->schedule_served_copy_maintenance(300);
            }
            $this->prune_served_copies(microtime(true) + self::SERVED_COPY_PRUNE_BUDGET);
            if (!$written) {
                return false;
            }
        } finally {
            $this->release_served_copy_lock($lock);
        }
        return $this->sync_routing_enabled_marker(true);
    }

    private function served_copies_enabled()
    {
        // OpenLiteSpeed reads .htaccess only when it starts: rules naming a new copy at every publication would keep
        // it on the copy of its last restart. It serves current/ instead, whose rules change only with the settings.
        if ('openlitespeed' === $this->web_server_kind()) {
            return false;
        }
        // Emergency switch in wp-config.php: false restores the 2.0.19 rules on current/.
        return !defined('STATIC_BRIDGE_APACHE_SERVED_COPIES') || false !== constant('STATIC_BRIDGE_APACHE_SERVED_COPIES');
    }

    private function htaccess_is_writable()
    {
        $htaccess = trailingslashit(ABSPATH) . '.htaccess';
        return !is_link($htaccess) && is_file($htaccess) && is_readable($htaccess) && is_writable($htaccess);
    }

    private function valid_served_copy_id($id)
    {
        return is_string($id) && (bool) preg_match('/\A[0-9]{8}T[0-9]{6}Z-[a-f0-9]{8}\z/D', $id);
    }

    private function served_copy_record()
    {
        $stored = get_option(self::SERVED_COPY_OPTION, array());
        $stored = is_array($stored) ? $stored : array();
        $retired = array();
        foreach (isset($stored['retired']) && is_array($stored['retired']) ? $stored['retired'] : array() as $id => $time) {
            if ($this->valid_served_copy_id((string) $id)) {
                $retired[(string) $id] = (int) $time;
            }
        }
        $id = isset($stored['id']) && $this->valid_served_copy_id((string) $stored['id']) ? (string) $stored['id'] : '';
        return array(
            'id' => $id,
            'release' => '' !== $id && isset($stored['release']) ? (string) $stored['release'] : '',
            'manifest' => '' !== $id && isset($stored['manifest']) ? (string) $stored['manifest'] : '',
            'mode' => '' !== $id && isset($stored['mode']) && 'copy' === $stored['mode'] ? 'copy' : ('' !== $id ? 'link' : ''),
            'files' => '' !== $id && isset($stored['files']) ? absint($stored['files']) : 0,
            'created' => '' !== $id && isset($stored['created']) ? (int) $stored['created'] : 0,
            'retired' => $retired,
            'fallback_logged' => !empty($stored['fallback_logged']) ? 1 : 0,
        );
    }

    /** Record the copy the rules now serve ('' for current/) and retire the one they served before. */
    private function record_served_copy($record, $copy)
    {
        $id = is_array($copy) ? (string) $copy['id'] : '';
        if ('' !== $record['id'] && $record['id'] !== $id) {
            $record['retired'][$record['id']] = time();
        }
        unset($record['retired'][$id]);
        if (is_array($copy)) {
            if (!empty($record['fallback_logged'])) {
                $this->log_activity(__('Apache serve di nuovo una copia immutabile della release.', 'static-bridge'), 'wp-content/static-bridge/served/' . $id . '/');
            }
            $record = array_merge($record, array(
                'id' => $id,
                'release' => (string) $copy['release'],
                'manifest' => (string) $copy['manifest'],
                'mode' => (string) $copy['mode'],
                'files' => (int) $copy['files'],
                'created' => (int) $copy['time'],
                'fallback_logged' => 0,
            ));
        } else {
            $record = array_merge($record, array('id' => '', 'release' => '', 'manifest' => '', 'mode' => '', 'files' => 0, 'created' => 0));
        }
        update_option(self::SERVED_COPY_OPTION, $record, false);
        if (!empty($record['retired'])) {
            $this->schedule_served_copy_maintenance(self::SERVED_COPY_GRACE + 5);
        }
    }

    private function acquire_served_copy_lock()
    {
        $lock_directory = realpath(sys_get_temp_dir());
        if (!$lock_directory) {
            return false;
        }
        $lock_path = trailingslashit($lock_directory) . 'static-bridge-served-' . substr(hash('sha256', $this->static_root()), 0, 24) . '.lock';
        if (is_link($lock_path) || (file_exists($lock_path) && !is_file($lock_path))) {
            return false;
        }
        $handle = @fopen($lock_path, 'c');
        if (!is_resource($handle)) {
            return false;
        }
        @chmod($lock_path, 0600);
        $deadline = microtime(true) + self::SERVED_COPY_LOCK_WAIT;
        while (!@flock($handle, LOCK_EX | LOCK_NB)) {
            if (microtime(true) >= $deadline) {
                fclose($handle);
                return false;
            }
            usleep(50000);
        }
        return $handle;
    }

    private function release_served_copy_lock($handle)
    {
        if (is_resource($handle)) {
            @flock($handle, LOCK_UN);
            fclose($handle);
        }
    }

    private function safe_served_root($create = false)
    {
        if ('' === $this->safe_release_root(false)) {
            return '';
        }
        $root_real = realpath($this->static_root());
        $served = $this->static_root() . '/served';
        if (is_link($served) || (file_exists($served) && !is_dir($served))) {
            return '';
        }
        if (!is_dir($served) && (!$create || (!@mkdir($served, 0755) && !is_dir($served)))) {
            return '';
        }
        $served_real = realpath($served);
        return $root_real && $served_real && dirname($served_real) === $root_real ? $served_real : '';
    }

    private function release_manifest_hash($directory)
    {
        $manifest = trailingslashit((string) $directory) . 'manifest.json';
        if (is_link($manifest) || !is_file($manifest)) {
            return '';
        }
        $hash = @hash_file('sha256', $manifest);
        return is_string($hash) ? $hash : '';
    }

    /**
     * The served copy of the current release, created if the release changed. Every change
     * to a release replaces its manifest, so the manifest hash identifies its content.
     */
    private function ensure_served_copy($record)
    {
        $release = $this->current_release();
        if (!$release) {
            return new WP_Error('static_bridge_served_release', __('Nessuna release corrente da servire.', 'static-bridge'));
        }
        $root = $this->safe_served_root(true);
        if ('' === $root) {
            return new WP_Error('static_bridge_served_root', __('La cartella wp-content/static-bridge/served non è nel percorso previsto o non può essere creata.', 'static-bridge'));
        }
        $hash = $this->release_manifest_hash($release);
        if ('' === $hash) {
            return new WP_Error('static_bridge_served_manifest', __('La release corrente non ha un manifest leggibile.', 'static-bridge'));
        }
        if ('' !== $record['id'] && basename($release) === $record['release'] && is_dir($root . '/' . $record['id'])
            && !is_link($root . '/' . $record['id']) && $hash === $this->release_manifest_hash($root . '/' . $record['id'])) {
            return array('id' => $record['id'], 'created' => false, 'release' => $record['release'], 'manifest' => $hash,
                'mode' => $record['mode'], 'files' => $record['files'], 'time' => $record['created']);
        }
        for ($attempt = 0; $attempt < 3; $attempt++) {
            $built = $this->build_served_copy($release, $root);
            if (is_wp_error($built)) {
                return $built;
            }
            $partial = $root . '/.partial-' . $built['id'];
            // The release must not have changed while it was being linked.
            if ($release === $this->current_release() && $hash === $this->release_manifest_hash($release)
                && $hash === $this->release_manifest_hash($partial)) {
                if (!@rename($partial, $root . '/' . $built['id'])) {
                    $this->remove_served_copy('.partial-' . $built['id']);
                    return new WP_Error('static_bridge_served_rename', __('Impossibile completare la copia servita.', 'static-bridge'));
                }
                return array_merge($built, array('created' => true, 'release' => basename($release), 'manifest' => $hash, 'time' => time()));
            }
            $this->remove_served_copy('.partial-' . $built['id']);
            $release = $this->current_release();
            $hash = $release ? $this->release_manifest_hash($release) : '';
            if (!$release || '' === $hash) {
                break;
            }
        }
        return new WP_Error('static_bridge_served_changed', __('La release è cambiata durante la creazione della copia servita.', 'static-bridge'));
    }

    /** Link (or, without hard links, copy) every file Apache may serve into served/.partial-<id>. */
    private function build_served_copy($release, $root)
    {
        $id = gmdate('Ymd\THis\Z') . '-' . bin2hex(random_bytes(4));
        $partial = $root . '/.partial-' . $id;
        if (file_exists($partial) || is_link($partial) || !@mkdir($partial, 0755)) {
            return new WP_Error('static_bridge_served_create', __('Impossibile creare la cartella della copia servita (permessi o spazio disco).', 'static-bridge'));
        }
        $minimum_free_space = $this->minimum_free_disk_space_bytes();
        $manifest = json_decode((string) @file_get_contents($release . '/manifest.json'), true);
        $pages = is_array($manifest) && isset($manifest['pages_saved']) ? absint($manifest['pages_saved']) : 0;
        // A copy made of hard links costs one directory block and one entry per page.
        if (!$this->has_sufficient_export_disk_space($root, $minimum_free_space, ($pages + 1) * 4096)) {
            $this->remove_served_copy('.partial-' . $id);
            return new WP_Error('static_bridge_served_space', $this->insufficient_disk_space_message($minimum_free_space));
        }
        $use_links = false !== $this->served_copy_hardlinks && function_exists('link');
        $mode = $use_links ? 'link' : 'copy';
        $files = 0;
        $render_backup = '/\Aindex\.html\.sb-render-[a-f0-9]{48}-[0-9]{1,5}\.bak\z/D';
        try {
            $iterator = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($release, FilesystemIterator::SKIP_DOTS), RecursiveIteratorIterator::SELF_FIRST);
            $iterator->setMaxDepth(64);
            foreach ($iterator as $entry) {
                $path = $entry->getPathname();
                if (is_link($path) || !$entry->isFile()) {
                    continue;
                }
                $name = $entry->getFilename();
                $directory = substr(dirname($path), strlen($release));
                if ('index.html' === $name || ('' === $directory && 'manifest.json' === $name)
                    || ('index.html.gz' === $name && is_file(dirname($path) . '/index.html') && !is_link(dirname($path) . '/index.html'))) {
                    // A .gz goes into the copy only with its page (2.3.0).
                    $target = $name;
                } elseif (preg_match($render_backup, $name) && !file_exists(dirname($path) . '/index.html')) {
                    // A route suspended by a render bypass (2.0.15): this is its published file.
                    $target = 'index.html';
                } else {
                    continue;
                }
                $destination_directory = $partial . $directory;
                if (!is_dir($destination_directory) && !@mkdir($destination_directory, 0755, true) && !is_dir($destination_directory)) {
                    throw new RuntimeException(__('Impossibile creare una cartella della copia servita.', 'static-bridge'));
                }
                $destination = $destination_directory . '/' . $target;
                if (file_exists($destination) || is_link($destination)) {
                    continue;
                }
                if ($use_links && @link($path, $destination)) {
                    ++$files;
                    continue;
                }
                // No hard links here (filesystem, open_basedir, disabled link()): copy instead.
                $use_links = false;
                $mode = 'copy';
                $size = $entry->getSize();
                if (!$this->has_sufficient_export_disk_space($root, $minimum_free_space, (int) $size)
                    || !@copy($path, $destination) || filesize($destination) !== $size) {
                    throw new RuntimeException($this->insufficient_disk_space_message($minimum_free_space));
                }
                @chmod($destination, 0644);
                ++$files;
            }
        } catch (Throwable $exception) {
            $this->remove_served_copy('.partial-' . $id);
            return new WP_Error('static_bridge_served_build', sprintf(/* translators: %s: error message */ __('Copia servita non completata: %s', 'static-bridge'), sanitize_text_field($exception->getMessage())));
        }
        if (!is_file($partial . '/manifest.json')) {
            $this->remove_served_copy('.partial-' . $id);
            return new WP_Error('static_bridge_served_build', __('Copia servita non completata: manifest assente.', 'static-bridge'));
        }
        return array('id' => $id, 'mode' => $mode, 'files' => $files);
    }

    private function remove_served_copy($name, $deadline = null)
    {
        $root = $this->safe_served_root(false);
        if ('' === $root || !preg_match('/\A(?:\.partial-)?[0-9]{8}T[0-9]{6}Z-[a-f0-9]{8}\z/D', (string) $name)) {
            return 'failed';
        }
        $path = $root . '/' . $name;
        clearstatcache(true, $path);
        if (is_link($path) || !is_dir($path) || realpath($path) !== $path) {
            return 'failed';
        }
        $bytes = 0;
        return $this->remove_retention_tree($path, null === $deadline ? microtime(true) + 30 : $deadline, $bytes, 0);
    }

    /**
     * Served copies named anywhere in .htaccess, whether its Static Bridge block exists, and
     * whether that block still serves current/. 'readable' is false when .htaccess exists but
     * cannot be read safely: callers must then delete nothing.
     */
    private function htaccess_routing_state()
    {
        $htaccess = trailingslashit(ABSPATH) . '.htaccess';
        $state = array('readable' => true, 'block' => false, 'current' => false, 'served' => array());
        if (!file_exists($htaccess) && !is_link($htaccess)) {
            return $state;
        }
        $contents = is_link($htaccess) || !is_file($htaccess) || !is_readable($htaccess) ? false : @file_get_contents($htaccess);
        if (!is_string($contents)) {
            $state['readable'] = false;
            return $state;
        }
        $state['block'] = (bool) preg_match('~^# BEGIN Static Bridge\R~m', $contents);
        $state['current'] = false !== strpos($contents, 'wp-content/static-bridge/current/index.html');
        if (preg_match_all('~wp-content/static-bridge/served/([0-9]{8}T[0-9]{6}Z-[a-f0-9]{8})/~', $contents, $matches)) {
            $state['served'] = array_values(array_unique($matches[1]));
        }
        return $state;
    }

    /**
     * True only when the plugin's Apache rules serve a copy that is not the current release:
     * visitors still see older content. No rules, or rules on current/, count as up to date.
     */
    private function apache_serves_stale_copy()
    {
        if ($this->server_uses_nginx()) {
            return false;
        }
        $state = $this->htaccess_routing_state();
        if (!$state['readable'] || !$state['block'] || $state['current'] || empty($state['served'])) {
            return false;
        }
        $release = $this->current_release();
        $hash = $release ? $this->release_manifest_hash($release) : '';
        $root = $this->safe_served_root(false);
        if ('' === $hash || '' === $root) {
            return false;
        }
        foreach ($state['served'] as $id) {
            if ($hash === $this->release_manifest_hash($root . '/' . $id)) {
                return false;
            }
        }
        return true;
    }

    /**
     * Remove copies the rules stopped serving at least SERVED_COPY_GRACE seconds ago. A copy
     * named in .htaccess (by the plugin or any other writer) or recorded as served is kept.
     */
    private function prune_served_copies($deadline = null)
    {
        $root = $this->safe_served_root(false);
        if ('' === $root) {
            return false;
        }
        $state = $this->htaccess_routing_state();
        if (!$state['readable']) {
            return false;
        }
        $names = @scandir($root);
        if (!is_array($names)) {
            return false;
        }
        $deadline = null === $deadline ? microtime(true) + self::SERVED_COPY_PRUNE_BUDGET : $deadline;
        $referenced = array_flip($state['served']);
        $record = $this->served_copy_record();
        $before = $record['retired'];
        $now = time();
        $present = array();
        foreach ($names as $name) {
            if ('.' === $name || '..' === $name || microtime(true) >= $deadline) {
                continue;
            }
            $path = $root . '/' . $name;
            if (is_link($path) || !is_dir($path)) {
                continue;
            }
            if (preg_match('/\A\.partial-[0-9]{8}T[0-9]{6}Z-[a-f0-9]{8}\z/D', $name)) {
                // Callers hold the served-copy lock: no copy is being built right now.
                $this->remove_served_copy($name, $deadline);
                continue;
            }
            if (!$this->valid_served_copy_id($name)) {
                continue;
            }
            $present[$name] = true;
            if ($name === $record['id']) {
                unset($record['retired'][$name]);
            } elseif (isset($referenced[$name])) {
                // Still named in .htaccess: its grace period starts when the reference goes.
                $record['retired'][$name] = $now;
            } elseif (!isset($record['retired'][$name])) {
                $record['retired'][$name] = $now;
            } elseif ($now - $record['retired'][$name] >= self::SERVED_COPY_GRACE
                && 'done' === $this->remove_served_copy($name, $deadline)) {
                unset($record['retired'][$name], $present[$name]);
            }
        }
        foreach (array_keys($record['retired']) as $name) {
            if (!isset($present[$name]) && !is_dir($root . '/' . $name)) {
                unset($record['retired'][$name]);
            }
        }
        if ($record['retired'] !== $before) {
            $stored = get_option(self::SERVED_COPY_OPTION, array());
            $stored = is_array($stored) ? $stored : array();
            $stored['retired'] = $record['retired'];
            update_option(self::SERVED_COPY_OPTION, $stored, false);
        }
        if (!empty($record['retired'])) {
            $this->schedule_served_copy_maintenance(self::SERVED_COPY_GRACE + 5);
        }
        return true;
    }

    private function schedule_served_copy_maintenance($delay)
    {
        if (!wp_next_scheduled(self::SERVED_COPY_HOOK)) {
            wp_schedule_single_event(time() + max(1, absint($delay)), self::SERVED_COPY_HOOK);
        }
    }

    /**
     * Rules still on current/ (a site upgraded from 2.0.19, or a fallback after a failed
     * copy): let the maintenance cron move Apache to a served copy without waiting for the
     * next publication. Cheap: one read of .htaccess on privileged admin requests.
     */
    public function maybe_schedule_served_copy_adoption()
    {
        if (!is_admin() || !current_user_can('manage_options') || $this->server_uses_nginx()
            || !$this->served_copies_enabled() || wp_next_scheduled(self::SERVED_COPY_HOOK) || !$this->current_release()) {
            return;
        }
        $state = $this->htaccess_routing_state();
        if ($state['readable'] && $state['block'] && $state['current']) {
            $this->schedule_served_copy_maintenance(1);
        }
    }

    /** Cron: republish rules that lag behind the current release, then prune retired copies. */
    public function process_served_copy_maintenance()
    {
        $state = $this->htaccess_routing_state();
        $on_current = $state['readable'] && $state['block'] && $state['current'] && $this->served_copies_enabled();
        if (!$this->server_uses_nginx() && $this->current_release()
            && ($on_current || $this->apache_serves_stale_copy() || $this->served_copy_rules_drifted())) {
            $this->update_routing_rules();
            return;
        }
        $lock = $this->acquire_served_copy_lock();
        if (!is_resource($lock)) {
            $this->schedule_served_copy_maintenance(60);
            return;
        }
        try {
            $this->prune_served_copies();
        } finally {
            $this->release_served_copy_lock($lock);
        }
    }

    /** The recorded copy is not the one .htaccess serves (another writer restored older rules). */
    private function served_copy_rules_drifted()
    {
        $record = $this->served_copy_record();
        if ('' === $record['id']) {
            return false;
        }
        $state = $this->htaccess_routing_state();
        return $state['readable'] && $state['block'] && array($record['id']) !== $state['served'];
    }

    /** $base: 'current' or 'served/<id>'; null keeps the recorded served copy (or current). */
    private function write_rewrite_rules($enabled, $base = null)
    {
        $this->sync_openlitespeed_folder_guard();
        $htaccess = trailingslashit(ABSPATH) . '.htaccess';
        if (is_link($htaccess) || !is_file($htaccess) || !is_readable($htaccess) || !is_writable($htaccess)) {
            return false;
        }
        $contents = file_get_contents($htaccess);
        if (false === $contents) {
            return false;
        }
        $original = $contents;
        // Remove each block together with the blank lines that follow it, so that
        // rewriting the rules on every publication leaves .htaccess unchanged.
        $contents = preg_replace('~^# BEGIN Static Bridge\R.*?^# END Static Bridge\h*(?:\R\h*(?=\R|$))*\R?~ms', '', $contents, 1);
        $contents = preg_replace('~^# BEGIN Static Bridge Archive Protection\R.*?^# END Static Bridge Archive Protection\h*(?:\R\h*(?=\R|$))*\R?~ms', '', $contents, 1);
        $block = $enabled || $this->has_archived_releases() ? $this->archive_protection_block() : '';
        if ($enabled) {
            $block .= "\n\n" . $this->rewrite_block($base);
        }
        if ('' !== $block) {
            $wordpress_marker = '# BEGIN WordPress';
            $position = strpos($contents, $wordpress_marker);
            if (false === $position) {
                $contents = $block . "\n" . ltrim($contents);
            } else {
                $before = rtrim(substr($contents, 0, $position));
                $contents = ('' === $before ? '' : $before . "\n\n") . $block . "\n\n" . substr($contents, $position);
            }
        }

        $temporary = $htaccess . '.static-bridge-' . wp_generate_password(6, false, false) . '.tmp';
        if (file_exists($temporary) || is_link($temporary)) {
            return false;
        }
        $written = file_put_contents($temporary, $contents, LOCK_EX);
        if (strlen($contents) !== $written) {
            if (file_exists($temporary) || is_link($temporary)) {
                @unlink($temporary);
            }
            return false;
        }
        $mode = fileperms($htaccess);
        if (false !== $mode) {
            @chmod($temporary, $mode & 0777);
        }
        if (!@rename($temporary, $htaccess)) {
            if (file_exists($temporary) || is_link($temporary)) {
                @unlink($temporary);
            }
            return false;
        }
        if ($original !== $contents && 'openlitespeed' === $this->web_server_kind()) {
            $this->log_activity(
                __('Regole di Static Bridge cambiate nel file .htaccess: OpenLiteSpeed le applica dopo un riavvio.', 'static-bridge'),
                __('Riavvia OpenLiteSpeed (Graceful Restart dal WebAdmin o dal pannello dell’hosting, oppure lswsctrl restart). Fino ad allora vale ciò che aveva al suo ultimo avvio; la Diagnostica dice se il riavvio serve ancora.', 'static-bridge')
            );
        }
        return true;
    }

    /**
     * Root .htaccess block kept also when routing is off. Its mod_include part (hardening note 36 of
     * the 3 November 2026 audit) stops SSI in static copies on a host that applies INCLUDES to .html
     * with AddOutputFilter; AddOutputFilterByType is not undone by RemoveOutputFilter. It lives here,
     * scoped by <If>, and not in a .htaccess inside wp-content/static-bridge: the root .htaccess is
     * known to allow FileInfo (mod_rewrite needs it), a subfolder may not, and there the directive
     * would answer 500 to every static page. The SSI guard stays off on Apache: an export with a
     * page containing <!--#… would fail entirely.
     */
    private function archive_protection_block()
    {
        return "# BEGIN Static Bridge Archive Protection\n"
            . "# Questo blocco resta attivo anche dopo la disattivazione: le release archiviate non vengono cancellate.\n"
            . "<IfModule mod_rewrite.c>\nRewriteEngine On\n"
            . "RewriteRule ^wp-content/static-bridge/releases(?:/|$) - [F,END,NC]\n"
            . "RewriteRule ^wp-content/static-bridge/current/(?:manifest\\.json|\\.ready)$ - [F,END,NC]\n"
            . "# Nessun file di Static Bridge è raggiungibile per URL diretto (come su Nginx); le route statiche\n"
            . "# vi arrivano solo tramite le regole sotto, il cui flag END salta questo controllo.\n"
            . "RewriteRule ^wp-content/static-bridge(?:/|$) - [F,END,NC]\n"
            . "</IfModule>\n"
            . "# Le copie statiche non passano da mod_include anche dove il server lo applica ai file .html.\n"
            . "<IfModule mod_include.c>\n<IfModule mod_mime.c>\n"
            . "<If \"%{REQUEST_FILENAME} =~ m#/wp-content/static-bridge/#\">\n"
            . "RemoveOutputFilter .html .htm .shtml\n"
            . "</If>\n</IfModule>\n</IfModule>\n"
            . "# END Static Bridge Archive Protection";
    }

    private function has_archived_releases()
    {
        $releases = glob(trailingslashit($this->static_root()) . 'releases/*', GLOB_ONLYDIR);
        $served = glob(trailingslashit($this->static_root()) . 'served/*', GLOB_ONLYDIR);
        return (is_array($releases) && !empty($releases)) || (is_array($served) && !empty($served));
    }

    /** Directory under wp-content/static-bridge/ that the Apache rules serve. */
    private function rewrite_base($base = null)
    {
        if (null === $base) {
            $record = $this->served_copy_record();
            $root = $this->safe_served_root(false);
            $base = '' !== $record['id'] && '' !== $root && is_dir($root . '/' . $record['id']) ? 'served/' . $record['id'] : 'current';
        }
        $base = (string) $base;
        return 'current' === $base || (0 === strpos($base, 'served/') && $this->valid_served_copy_id(substr($base, 7))) ? $base : 'current';
    }

    /**
     * Redirects WordPress makes for another plugin (Lingua Bridge: old slugs, terms of a language, a language home not
     * translated yet), written as server rules so that they hold where the copy answers without WordPress (Strict):
     * `static_bridge_redirects` gives from-path => array('to' => URL or path of this site, 'status' => 301|302|307|308).
     * Only plain paths of this site (letters, digits, - . _ ~ /), never a route WordPress keeps dynamic, at most
     * MAX_PLUGIN_REDIRECTS. Without a filter: none, the rules are as before. 2.5.0: then the redirects imported from
     * Redirection, Rank Math and Yoast SEO Premium («Importa i redirect di…», only with Strict), never over a path the
     * filter gives: the code that fills the filter knows its redirects better than a guess from another plugin's data.
     *
     * @param bool $with_imported False leaves out the imported redirects (their report counts the paths of the filter).
     * @return array<string, array{to: string, status: int}> Decoded from-path => target path and status.
     */
    private function plugin_redirects($with_imported = true)
    {
        $given = apply_filters('static_bridge_redirects', array());
        $redirects = array();
        foreach (is_array($given) ? $given : array() as $from => $redirect) {
            if (count($redirects) >= self::MAX_PLUGIN_REDIRECTS) {
                break;
            }
            $entry = $this->plugin_redirect_entry($from, $redirect);
            if (null !== $entry) {
                $redirects[$entry['from']] = array('to' => $entry['to'], 'status' => $entry['status']);
            }
        }
        if ($with_imported) {
            foreach ($this->imported_redirects($redirects)['redirects'] as $from => $redirect) {
                if (count($redirects) >= self::MAX_PLUGIN_REDIRECTS) {
                    break;
                }
                $redirects[$from] = $redirect;
            }
        }
        return $redirects;
    }

    /**
     * One redirect of `static_bridge_redirects` checked for the server rules: the from-path decoded, with a leading
     * «/», 1 to 300 characters of `[A-Za-z0-9._~/-]`, never «/», «//», «.» or «..» segments, never a path
     * is_excluded_path() keeps dynamic; the target a path (made a URL with home_url()) or a URL of this site
     * (same_site_url()), without a query, whose path is at most 300 characters of `[A-Za-z0-9._~/-]` and «%» followed
     * by two hex digits (2.5.0: a lone «%» is refused), never «//», never the from-path itself. A status outside 301,
     * 302, 307 and 308 becomes 301.
     *
     * @return array{from: string, to: string, status: int}|null The from-path without its trailing «/», the target
     *                                                           path and the status; null when refused.
     */
    private function plugin_redirect_entry($from, $redirect)
    {
        $from = '/' . ltrim(rawurldecode((string) $from), '/');
        $to = is_array($redirect) && isset($redirect['to']) && is_string($redirect['to']) ? $redirect['to'] : '';
        $status = is_array($redirect) && isset($redirect['status']) ? (int) $redirect['status'] : 301;
        if ('' !== $to && 0 === strpos($to, '/') && 0 !== strpos($to, '//')) {
            $to = home_url($to);
        }
        $to_path = $this->same_site_url($to) ? (string) wp_parse_url($to, PHP_URL_PATH) : '';
        if ('/' === $from || strlen($from) > 300 || !preg_match('#^/[A-Za-z0-9._~/-]+$#D', $from) || false !== strpos($from, '//')
            || preg_match('~(^|/)\.\.?(/|$)~', $from) || $this->is_excluded_path(trailingslashit($from))
            || '' === $to_path || strlen($to_path) > 300 || !preg_match('#^/(?:[A-Za-z0-9._~/-]|%[0-9A-Fa-f]{2})*$#D', $to_path) || false !== strpos($to_path, '//')
            || null !== wp_parse_url($to, PHP_URL_QUERY) || untrailingslashit($from) === untrailingslashit(rawurldecode($to_path))) {
            return null;
        }
        return array('from' => untrailingslashit($from), 'to' => $to_path, 'status' => in_array($status, array(301, 302, 307, 308), true) ? $status : 301);
    }

    /** «Importa i redirect di…» (2.5.0): the known keys of REDIRECT_IMPORT_SOURCES in $value, in that order. */
    private function sanitize_redirect_import_sources($value)
    {
        $given = is_array($value) ? array_filter($value, 'is_string') : array();
        return array_values(array_filter(array_keys(self::REDIRECT_IMPORT_SOURCES), function ($source) use ($given) {
            return in_array($source, $given, true);
        }));
    }

    /**
     * Whether the plugin behind an import is running: its own constants, defined only while it is active. An inactive
     * plugin makes no redirect in WP, so its stored redirects must not reach the rules either.
     */
    private function redirect_import_source_active($source)
    {
        $constants = array(
            'redirection' => array('REDIRECTION_VERSION', 'REDIRECTION_FILE'),
            'rank_math' => array('RANK_MATH_VERSION', 'RANK_MATH_FILE'),
            'yoast_premium' => array('WPSEO_PREMIUM_VERSION', 'WPSEO_PREMIUM_FILE'),
        );
        foreach (isset($constants[$source]) ? $constants[$source] : array() as $constant) {
            if (defined($constant)) {
                return true;
            }
        }
        return false;
    }

    /**
     * «Importa i redirect di…» (2.5.0): the simple redirects of the chosen plugins, for plugin_redirects(). Empty
     * unless Strict is on: without it WP runs and the plugin makes its redirects itself. Each reader gives exact
     * from-path → target, status and visits; regular expressions, conditions and a query in the from-path are only
     * counted. A from-path given twice with different targets or statuses (in one plugin or in two) is left out: which
     * one WP would apply depends on hook order and positions this plugin cannot see. Paths of $filtered (the filter
     * static_bridge_redirects) win. At most MAX_IMPORTED_REDIRECTS, those with the most visits first; each one passes
     * plugin_redirect_entry(), as the filter does. Read again at every rules write, never cached: a removed redirect
     * leaves the rules at the next write.
     *
     * @param array<string, mixed> $filtered The redirects of the filter, by from-path.
     * @return array{redirects: array<string, array{to: string, status: int}>, sources: array<string, array>, strict: bool, conflicts: int, overridden: int, over_limit: int}
     */
    private function imported_redirects($filtered = array())
    {
        $settings = $this->settings();
        $result = array('redirects' => array(), 'sources' => array(), 'strict' => !empty($settings['strict_mode']), 'conflicts' => 0, 'overridden' => 0, 'over_limit' => 0);
        if (!$result['strict'] || empty($settings['import_redirects'])) {
            return $result;
        }
        $candidates = array();
        $order = 0;
        foreach ($settings['import_redirects'] as $source) {
            $read = $this->redirect_import_source_active($source)
                ? $this->read_imported_redirects($source)
                : array('state' => 'inactive', 'rows' => array(), 'complex' => 0, 'unsupported' => 0);
            $result['sources'][$source] = array('state' => $read['state'], 'imported' => 0, 'complex' => $read['complex'], 'unsupported' => $read['unsupported']);
            foreach ($read['rows'] as $row) {
                $key = untrailingslashit('/' . ltrim(rawurldecode($row['from']), '/'));
                $candidates[$key][] = $row + array('source' => $source, 'order' => $order++);
            }
        }
        $chosen = array();
        foreach ($candidates as $key => $rows) {
            $targets = array();
            foreach ($rows as $row) {
                $targets[$row['to'] . ' ' . $row['status']] = true;
            }
            if (count($targets) > 1) {
                $result['conflicts'] += count($rows);
            } elseif (isset($filtered[$key])) {
                $result['overridden']++;
            } else {
                $chosen[] = $rows[0];
            }
        }
        // The most visited first; the same number of visits keeps the order of the plugins.
        usort($chosen, function ($a, $b) {
            return $b['hits'] === $a['hits'] ? $a['order'] - $b['order'] : ($b['hits'] > $a['hits'] ? 1 : -1);
        });
        foreach ($chosen as $index => $row) {
            if (count($result['redirects']) >= self::MAX_IMPORTED_REDIRECTS) {
                $result['over_limit'] = count($chosen) - $index;
                break;
            }
            $entry = $this->plugin_redirect_entry($row['from'], array('to' => $row['to'], 'status' => $row['status']));
            if (null === $entry || isset($filtered[$entry['from']])) {
                $result['sources'][$row['source']]['unsupported']++;
                continue;
            }
            $result['redirects'][$entry['from']] = array('to' => $entry['to'], 'status' => $entry['status']);
            $result['sources'][$row['source']]['imported']++;
        }
        return $result;
    }

    /**
     * The redirects one plugin keeps, read as it stores them. Never an error: a missing table or option gives
     * `missing`, other columns or another shape give `unrecognized`, Rank Math with its Redirections module off gives
     * `module_off`; then no row. Rows: from (the source as written), to (normalized by imported_redirect_target()),
     * status 301, 302, 307 or 308, hits. `complex` counts regular expressions, conditions and a query in the source;
     * `unsupported` the other codes and targets that are not a URL or a path. At most MAX_REDIRECT_IMPORT_ROWS.
     *
     * - Redirection: `{prefix}redirection_items` joined with `{prefix}redirection_groups`, items and groups
     *   `enabled`, groups of the WordPress module (`module_id` 1: the Apache and Nginx modules write their own server
     *   rules), by `position`. Only `match_type` `url` with `action_type` `url`, `regex` 0 and no `flag_regex` in the
     *   JSON of `match_data`; the target is `action_data`.
     * - Rank Math: `{prefix}rank_math_redirections` with `status` `active`, `sources` a serialized list of
     *   `pattern`/`comparison`, only `comparison` `exact`; the target is `url_to`, the visits `hits`. The table
     *   `{prefix}rank_math_redirections_cache` is never read: it remembers addresses already matched, regular
     *   expressions included.
     * - Yoast SEO Premium: the option `wpseo-premium-redirects-base`, a list of `origin`, `url`, `type`, `format`;
     *   only `format` `plain`. Origins and relative targets are stored without the leading «/».
     *
     * @return array{state: string, rows: array<int, array{from: string, to: string, status: int, hits: int}>, complex: int, unsupported: int}
     */
    private function read_imported_redirects($source)
    {
        global $wpdb;
        $read = array('state' => 'ok', 'rows' => array(), 'complex' => 0, 'unsupported' => 0);
        $codes = array(301, 302, 307, 308);
        $add = function ($from, $to, $status, $hits, $relative_target) use (&$read, $codes) {
            $from = is_string($from) ? trim($from) : '';
            $target = is_string($to) ? $this->imported_redirect_target($to, $relative_target) : '';
            if (false !== strpos($from, '?')) {
                $read['complex']++;
            } elseif ('' === $from || '' === $target || !in_array((int) $status, $codes, true)) {
                $read['unsupported']++;
            } else {
                $read['rows'][] = array('from' => $from, 'to' => $target, 'status' => (int) $status, 'hits' => max(0, (int) $hits));
            }
        };
        if ('yoast_premium' === $source) {
            $stored = get_option('wpseo-premium-redirects-base', null);
            if (null === $stored || false === $stored) {
                $read['state'] = 'missing';
                return $read;
            }
            if (!is_array($stored)) {
                $read['state'] = 'unrecognized';
                return $read;
            }
            foreach (array_slice($stored, 0, self::MAX_REDIRECT_IMPORT_ROWS) as $redirect) {
                if (!is_array($redirect) || !isset($redirect['origin'], $redirect['url'], $redirect['type'], $redirect['format'])) {
                    $read['unsupported']++;
                } elseif ('plain' !== $redirect['format']) {
                    $read['complex']++;
                } else {
                    $add($redirect['origin'], $redirect['url'], is_numeric($redirect['type']) ? $redirect['type'] : 0, 0, true);
                }
            }
            return $read;
        }
        if ('rank_math' === $source) {
            $modules = get_option('rank_math_modules', array());
            if (!is_array($modules) || !in_array('redirections', $modules, true)) {
                $read['state'] = 'module_off';
                return $read;
            }
            $table = $this->imported_redirects_table('rank_math_redirections', array('id', 'sources', 'url_to', 'header_code', 'hits', 'status'));
            if (!is_string($table)) {
                $read['state'] = $table ? 'unrecognized' : 'missing';
                return $read;
            }
            $rows = $this->imported_redirects_query(
                // phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared -- The table name is the prefix plus a fixed name, checked by imported_redirects_table().
                $wpdb->prepare("SELECT sources, url_to, header_code, hits FROM `{$table}` WHERE status = %s ORDER BY id ASC LIMIT %d", 'active', self::MAX_REDIRECT_IMPORT_ROWS)
            );
            if (null === $rows) {
                $read['state'] = 'unrecognized';
                return $read;
            }
            foreach ($rows as $row) {
                $sources = isset($row['sources']) && is_string($row['sources']) && preg_match('/\\Aa:[0-9]+:\\{/', $row['sources'])
                    ? @unserialize($row['sources'], array('allowed_classes' => false)) // phpcs:ignore WordPress.PHP.DiscouragedPHPFunctions -- No object is ever built.
                    : false;
                if (!is_array($sources) || empty($sources)) {
                    $read['unsupported']++;
                    continue;
                }
                foreach ($sources as $pattern) {
                    if (!is_array($pattern) || !isset($pattern['pattern'], $pattern['comparison']) || !is_string($pattern['pattern'])) {
                        $read['unsupported']++;
                    } elseif ('exact' !== $pattern['comparison']) {
                        $read['complex']++;
                    } else {
                        $add($pattern['pattern'], isset($row['url_to']) ? $row['url_to'] : '', isset($row['header_code']) ? $row['header_code'] : 0, isset($row['hits']) ? $row['hits'] : 0, false);
                    }
                }
            }
            return $read;
        }
        if ('redirection' !== $source) {
            $read['state'] = 'unrecognized';
            return $read;
        }
        $items = $this->imported_redirects_table('redirection_items', array('id', 'url', 'regex', 'position', 'group_id', 'status', 'action_type', 'action_code', 'action_data', 'match_type', 'match_data', 'last_count'));
        $groups = $this->imported_redirects_table('redirection_groups', array('id', 'module_id', 'status'));
        if (!is_string($items) || !is_string($groups)) {
            $read['state'] = (is_string($items) || $items) && (is_string($groups) || $groups) ? 'unrecognized' : 'missing';
            return $read;
        }
        $rows = $this->imported_redirects_query(
            // phpcs:ignore WordPress.DB.PreparedSQL.InterpolatedNotPrepared -- The table names are the prefix plus fixed names, checked by imported_redirects_table().
            $wpdb->prepare("SELECT i.url, i.regex, i.match_type, i.match_data, i.action_type, i.action_code, i.action_data, i.last_count FROM `{$items}` i INNER JOIN `{$groups}` g ON g.id = i.group_id WHERE i.status = %s AND g.status = %s AND g.module_id = %d ORDER BY i.position ASC, i.id ASC LIMIT %d", 'enabled', 'enabled', 1, self::MAX_REDIRECT_IMPORT_ROWS)
        );
        if (null === $rows) {
            $read['state'] = 'unrecognized';
            return $read;
        }
        foreach ($rows as $row) {
            $flags = isset($row['match_data']) && is_string($row['match_data']) && '' !== $row['match_data'] ? json_decode($row['match_data'], true) : array();
            $regex = !empty($row['regex']) || (is_array($flags) && !empty($flags['source']['flag_regex']));
            if ($regex || !isset($row['match_type']) || 'url' !== $row['match_type']) {
                $read['complex']++;
            } elseif (!is_array($flags) || !isset($row['action_type']) || 'url' !== $row['action_type']) {
                $read['unsupported']++;
            } else {
                $add(isset($row['url']) ? $row['url'] : '', isset($row['action_data']) ? $row['action_data'] : '', isset($row['action_code']) ? $row['action_code'] : 0, isset($row['last_count']) ? $row['last_count'] : 0, false);
            }
        }
        return $read;
    }

    /**
     * «Importa i redirect di…» (2.5.0) in words, for the Settings and Attività: one sentence per chosen plugin (how
     * many entered the rules, or why none did) and the counts of what was left out. Reads the plugins now, through
     * imported_redirects() with the filter's paths, as the next rules write will.
     *
     * @return string[]
     */
    private function redirect_import_summary()
    {
        $settings = $this->settings();
        if (empty($settings['import_redirects'])) {
            return array();
        }
        $imported = $this->imported_redirects($this->plugin_redirects(false));
        if (!$imported['strict']) {
            return array(__('Spenta finché la Modalità strict è spenta: senza Strict i redirect li fa il plugin che li gestisce.', 'static-bridge'));
        }
        $lines = array();
        foreach ($imported['sources'] as $source => $report) {
            $name = self::REDIRECT_IMPORT_SOURCES[$source];
            $states = array(
                /* translators: %s: plugin name */
                'inactive' => __('%s: plugin non attivo, nessun redirect importato.', 'static-bridge'),
                /* translators: %s: plugin name */
                'module_off' => __('%s: modulo dei redirect spento, nessun redirect importato.', 'static-bridge'),
                /* translators: %s: plugin name */
                'missing' => __('%s: tabella o opzione dei redirect non trovata, nessun redirect importato.', 'static-bridge'),
                /* translators: %s: plugin name */
                'unrecognized' => __('%s: formato dei redirect non riconosciuto, nessun redirect importato.', 'static-bridge'),
            );
            if (isset($states[$report['state']])) {
                $lines[] = sprintf($states[$report['state']], $name);
                continue;
            }
            /* translators: 1: plugin name, 2: number of redirects */
            $line = sprintf(_n('%1$s: %2$s redirect importato.', '%1$s: %2$s redirect importati.', $report['imported'], 'static-bridge'), $name, number_format_i18n($report['imported']));
            if ($report['complex'] > 0) {
                /* translators: %s: number of redirects */
                $line .= ' ' . sprintf(_n('%s saltato: espressioni regolari, condizioni o parametri nell’indirizzo di partenza.', '%s saltati: espressioni regolari, condizioni o parametri nell’indirizzo di partenza.', $report['complex'], 'static-bridge'), number_format_i18n($report['complex']));
            }
            if ($report['unsupported'] > 0) {
                /* translators: %s: number of redirects */
                $line .= ' ' . sprintf(_n('%s saltato: codice diverso da 301, 302, 307 e 308, destinazione fuori dal sito o indirizzo con caratteri non semplici.', '%s saltati: codice diverso da 301, 302, 307 e 308, destinazione fuori dal sito o indirizzo con caratteri non semplici.', $report['unsupported'], 'static-bridge'), number_format_i18n($report['unsupported']));
            }
            $lines[] = $line;
        }
        if ($imported['conflicts'] > 0) {
            /* translators: %s: number of redirects */
            $lines[] = sprintf(_n('%s redirect saltato: lo stesso indirizzo ha destinazioni diverse.', '%s redirect saltati: lo stesso indirizzo ha destinazioni diverse.', $imported['conflicts'], 'static-bridge'), number_format_i18n($imported['conflicts']));
        }
        if ($imported['overridden'] > 0) {
            /* translators: %s: number of redirects */
            $lines[] = sprintf(_n('%s redirect lasciato a quello che un altro plugin dà con il filtro static_bridge_redirects.', '%s redirect lasciati a quelli che un altro plugin dà con il filtro static_bridge_redirects.', $imported['overridden'], 'static-bridge'), number_format_i18n($imported['overridden']));
        }
        if ($imported['over_limit'] > 0) {
            /* translators: 1: number of redirects, 2: maximum number of redirects */
            $lines[] = sprintf(__('%1$s redirect oltre il limite di %2$s: entrano quelli con più visite.', 'static-bridge'), number_format_i18n($imported['over_limit']), number_format_i18n(self::MAX_IMPORTED_REDIRECTS));
        }
        return $lines;
    }

    /**
     * The target of an imported redirect as plugin_redirect_entry() reads it: an absolute URL as it is (its scheme
     * and host are checked there), a path with its leading «/». $relative (Yoast) also takes a path stored without the
     * «/», relative to the root of the site. '' for anything else: spaces, control characters, «#», «//…», a
     * relative path elsewhere, more than 2000 characters.
     */
    private function imported_redirect_target($url, $relative)
    {
        $url = trim((string) $url);
        if ('' === $url || strlen($url) > 2000 || preg_match('/[\x00-\x20\x7F#\\\\]/', $url) || 0 === strpos($url, '//')) {
            return '';
        }
        if (preg_match('#^[A-Za-z][A-Za-z0-9+.-]*:#', $url) || 0 === strpos($url, '/')) {
            return $url;
        }
        return $relative ? '/' . $url : '';
    }

    /**
     * A table of another plugin, by its name without the prefix: the full name when it exists with every column of
     * $columns, true when it exists without one of them, false when it does not exist or the name is not
     * `[A-Za-z0-9_]{1,64}` (a hostile prefix never reaches a query). One prepared query on information_schema.
     *
     * @return string|bool
     */
    private function imported_redirects_table($name, $columns)
    {
        global $wpdb;
        $table = (string) $wpdb->prefix . $name;
        if (!preg_match('/\A[A-Za-z0-9_]{1,64}\z/', $table)) {
            return false;
        }
        $suppressed = $wpdb->suppress_errors();
        try {
            $found = $wpdb->get_col($wpdb->prepare('SELECT COLUMN_NAME FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = %s', $table));
        } finally {
            $wpdb->suppress_errors($suppressed);
        }
        $found = is_array($found) ? array_map('strtolower', array_filter($found, 'is_string')) : array();
        if (empty($found)) {
            return false;
        }
        return array() === array_diff($columns, $found) ? $table : true;
    }

    /** The rows of a prepared query as associative arrays, or null when it failed (errors suppressed, never shown). */
    private function imported_redirects_query($prepared)
    {
        global $wpdb;
        $suppressed = $wpdb->suppress_errors();
        try {
            $rows = $wpdb->get_results($prepared, ARRAY_A);
        } finally {
            $wpdb->suppress_errors($suppressed);
        }
        return is_array($rows) ? $rows : null;
    }

    /**
     * The hosts of other languages (Lingua Bridge: a language with its own domain) that reach this same WordPress
     * through `static_bridge_hosts`: the copy is the main site's, so on these hosts WordPress answers, never the copy.
     *
     * @return string[] Lower-case host names without port, never the site's own.
     */
    private function other_language_hosts()
    {
        $given = apply_filters('static_bridge_hosts', array());
        $site = strtolower((string) wp_parse_url(home_url('/'), PHP_URL_HOST));
        $hosts = array();
        foreach (is_array($given) ? $given : array() as $host) {
            $host = strtolower((string) strtok((string) $host, ':'));
            if ('' !== $host && $site !== $host && preg_match('/^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/D', $host)) {
                $hosts[$host] = $host;
            }
            if (count($hosts) >= 50) {
                break;
            }
        }
        return array_values($hosts);
    }

    /** A regular expression of the other languages' hosts, with an optional port, or '' without any. */
    private function other_language_hosts_pattern()
    {
        $hosts = $this->other_language_hosts();
        return empty($hosts) ? '' : '^(?:' . implode('|', array_map(function ($host) {
            return preg_quote($host, '~');
        }, $hosts)) . ')(?::[0-9]+)?$';
    }

    /**
     * The routes the server rules always send to WP, whatever the copy holds: one regular expression each, without
     * delimiters, matched without regard to case against the decoded path. The Apache guard, the Nginx block and the
     * link check after a publication (2.5.0) read this one list, so the report says what the rules do.
     *
     * @param string|null $search_base_literal The search base already quoted for the target syntax (Nginx); null
     *                                         quotes it for PCRE with '~' as delimiter.
     * @return string[]
     */
    private function server_dynamic_route_patterns($search_base_literal = null)
    {
        $search = null === $search_base_literal ? preg_quote($this->search_base(), '~') : (string) $search_base_literal;
        return array(
            '^/(?:wp-admin|wp-content|wp-includes|wp-json)(?:/|$)',
            '^/(?:wp-login|wp-cron|wp-comments-post|wp-signup|wp-activate|wp-mail|wp-trackback|xmlrpc)\.php(?:/|$)',
            '^/(?:[^/]*sitemap[^/]*\.(?:xml|xsl)|robots\.txt)$',
            '^/(?:feed|comments/feed|.*?/feed)(?:/|$)',
            '^/(?:.+/)?(?:rss|rss2|atom|rdf)/?$',
            '^/' . $search . '(?:/|$)',
        );
    }

    /**
     * «Ignora i parametri di tracciamento» (2.5.0): the query names that still get the copy, from
     * TRACKING_PARAMS_DEFAULT through the filter static_bridge_tracking_params. Empty with the setting off, unless
     * $even_off (the Settings show the list). Each name is [A-Za-z0-9_-]{1,64}; a prefix is 3 to 32 of those
     * characters ending in «_», then «*». Never a name WP or Static Bridge reads (RESERVED_QUERY_NAMES, the
     * query_vars filter), never a prefix of one: such a query must reach WP. At most MAX_TRACKING_PARAMS.
     *
     * @return string[] Names, prefixes with their «*».
     */
    private function tracking_param_names($even_off = false)
    {
        if (!$even_off && empty($this->settings()['ignore_tracking_params'])) {
            return array();
        }
        $given = apply_filters('static_bridge_tracking_params', self::TRACKING_PARAMS_DEFAULT);
        $reserved = $this->reserved_query_names();
        $names = array();
        foreach (is_array($given) ? $given : array() as $name) {
            if (count($names) >= self::MAX_TRACKING_PARAMS) {
                break;
            }
            if (!is_string($name)) {
                continue;
            }
            $name = trim($name);
            $prefix = (bool) preg_match('/\A[A-Za-z0-9][A-Za-z0-9_-]{1,30}_\*\z/', $name);
            if (!$prefix && !preg_match('/\A[A-Za-z0-9_-]{1,64}\z/', $name)) {
                continue;
            }
            $stem = strtolower($prefix ? substr($name, 0, -1) : $name);
            $clash = false;
            foreach ($reserved as $reserved_name) {
                if ($prefix ? 0 === strpos($reserved_name, $stem) : $reserved_name === $stem) {
                    $clash = true;
                    break;
                }
            }
            if (!$clash && 0 !== strpos($stem, 'static_bridge')) {
                $names[$name] = $name;
            }
        }
        return array_values($names);
    }

    /** RESERVED_QUERY_NAMES with the query variables WP knows at run time, lower case. */
    private function reserved_query_names()
    {
        $names = self::RESERVED_QUERY_NAMES;
        $wp = isset($GLOBALS['wp']) && is_object($GLOBALS['wp']) ? $GLOBALS['wp'] : null;
        foreach (array('public_query_vars', 'private_query_vars') as $property) {
            if (null !== $wp && isset($wp->{$property}) && is_array($wp->{$property})) {
                $names = array_merge($names, $wp->{$property});
            }
        }
        // Plugins add theirs here (WooCommerce, languages, sitemaps); WP applies it when it parses a request.
        $filtered = apply_filters('query_vars', null !== $wp && isset($wp->public_query_vars) && is_array($wp->public_query_vars) ? $wp->public_query_vars : array());
        if (is_array($filtered)) {
            $names = array_merge($names, $filtered);
        }
        $reserved = array();
        foreach ($names as $name) {
            if (is_string($name) && '' !== $name) {
                $reserved[strtolower($name)] = true;
            }
        }
        return array_keys($reserved);
    }

    /**
     * The query strings that still get the copy, as one regular expression without delimiters (PCRE, the same for
     * Apache, Nginx and the link check; delimiter '#' in PHP): empty, or name=value pairs joined by single '&' whose
     * names are all in tracking_param_names(), compared with case, with values of TRACKING_VALUE_CLASS, at most
     * TRACKING_QUERY_MAX_LENGTH bytes. '' with the setting off: then only the empty query gets the copy, as before.
     * Everything else (an empty pair, a name without '=', '[]', an encoded name, another parameter) reaches WP.
     */
    private function tracking_query_pattern()
    {
        $alternatives = array();
        foreach ($this->tracking_param_names() as $name) {
            // Validated to [A-Za-z0-9_-]: literal in every regex flavour, nothing to quote.
            $alternatives[] = '*' === substr($name, -1) ? substr($name, 0, -1) . '[A-Za-z0-9_-]+' : $name;
        }
        if (empty($alternatives)) {
            return '';
        }
        $pair = '(?:' . implode('|', $alternatives) . ')=' . self::TRACKING_VALUE_CLASS . '*';
        return '^(?:(?=.{1,' . self::TRACKING_QUERY_MAX_LENGTH . '}$)' . $pair . '(?:&' . $pair . ')*)?$';
    }

    /** The Apache condition on the query string: «^$», or the tracking expression (2.5.0). */
    private function apache_query_condition()
    {
        $pattern = $this->tracking_query_pattern();
        return 'RewriteCond %{QUERY_STRING} ' . ('' === $pattern ? '^$' : $pattern);
    }

    /**
     * «Cookie che mandano a WP» (2.5.0): the names of the Settings field and of the filter
     * static_bridge_dynamic_cookies, validated by sanitize_dynamic_cookie_names().
     *
     * @return string[]
     */
    private function dynamic_cookie_names()
    {
        $names = $this->settings()['dynamic_cookies'];
        $added = apply_filters('static_bridge_dynamic_cookies', array(), $names);
        if (is_array($added)) {
            $names = array_merge($names, $added);
        }
        return $this->sanitize_dynamic_cookie_names($names)['names'];
    }

    /**
     * Cookie names for the server rules: [A-Za-z0-9_.-], 1 to DYNAMIC_COOKIE_MAX_LENGTH bytes, or a prefix of at
     * least 3 of them followed by «*». Duplicates without regard to case go; at most MAX_DYNAMIC_COOKIES.
     *
     * @return array{names: string[], invalid: string[], dropped: int}
     */
    private function sanitize_dynamic_cookie_names($names)
    {
        $valid = array();
        $invalid = array();
        $dropped = 0;
        foreach (is_array($names) ? $names : array() as $name) {
            if (!is_string($name)) {
                continue;
            }
            $name = trim($name);
            if ('' === $name) {
                continue;
            }
            if (strlen($name) > self::DYNAMIC_COOKIE_MAX_LENGTH + 1
                || !preg_match('/\A(?:[A-Za-z0-9_.-]{1,' . self::DYNAMIC_COOKIE_MAX_LENGTH . '}|[A-Za-z0-9_.-]{3,' . self::DYNAMIC_COOKIE_MAX_LENGTH . '}\*)\z/', $name)) {
                $invalid[] = $name;
                continue;
            }
            $key = strtolower($name);
            if (isset($valid[$key])) {
                continue;
            }
            if (count($valid) >= self::MAX_DYNAMIC_COOKIES) {
                $dropped++;
                continue;
            }
            $valid[$key] = $name;
        }
        return array('names' => array_values($valid), 'invalid' => $invalid, 'dropped' => $dropped);
    }

    /**
     * The cookies of dynamic_cookie_names() as one regular expression without delimiters, for Apache, Nginx and PHP
     * (matched without regard to case, like the session cookies): a cookie whose name is one of them, or starts
     * with a prefix, at the start of the header or after ';' (',' when a server joins two Cookie headers). The
     * value never counts. '' without names.
     */
    private function dynamic_cookie_pattern()
    {
        $alternatives = array();
        foreach ($this->dynamic_cookie_names() as $name) {
            $prefix = '*' === substr($name, -1);
            $literal = str_replace('.', '\\.', $prefix ? substr($name, 0, -1) : $name);
            $alternatives[] = $prefix ? $literal : $literal . '(?:[=;,\s]|$)';
        }
        return empty($alternatives) ? '' : '(?:^|[;,])\s*(?:' . implode('|', $alternatives) . ')';
    }

    private function rewrite_block($base = null)
    {
        $base = $this->rewrite_base($base);
        $excluded = array();
        $exclude_home = false;
        foreach ($this->routing_excluded_paths() as $path) {
            if ('/' === $path) {
                $exclude_home = true;
                continue;
            }
            $path = trim($path, '/');
            if ('' !== $path) {
                // A space or control byte would end the RewriteCond argument and break the whole .htaccess.
                $excluded[] = preg_replace_callback('/[\x00-\x20\x7F]/', function ($match) {
                    return '\\x' . strtoupper(bin2hex($match[0]));
                }, preg_quote($path, '~'));
            }
        }
        $user_exclusions = $exclude_home ? "RewriteCond %{REQUEST_URI} !^/$\n" : '';
        if (!empty($excluded)) {
            $user_exclusions .= "RewriteCond %{REQUEST_URI} !^/(?:" . implode('|', $excluded) . ")(?:/|$) [NC]\n";
        }
        // A RewriteCond applies only to the next RewriteRule, so every rule that
        // serves a release file (or answers the strict 404) repeats the full guard.
        $guard = $user_exclusions . <<<'RULES'
RewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/.enabled -f
RewriteCond %{REQUEST_METHOD} ^(?:GET|HEAD)$
RewriteCond %{HTTP_COOKIE} !(?:wordpress_logged_in_|comment_author_|wp-postpass_|woocommerce_items_in_cart|woocommerce_cart_hash|wp_woocommerce_session_) [NC]

RULES;
        // 2.5.0, both off by default and then byte for byte as before: the cookies that send to WP, and a query made
        // only of tracking parameters (the file served never depends on the query).
        $cookies = $this->dynamic_cookie_pattern();
        $guard .= ('' === $cookies ? '' : 'RewriteCond %{HTTP_COOKIE} !' . $cookies . " [NC]\n")
            . $this->apache_query_condition() . "\n";
        // The same list as the Nginx block and the link check after a publication (2.5.0).
        foreach ($this->server_dynamic_route_patterns() as $pattern) {
            $guard .= 'RewriteCond %{REQUEST_URI} !' . $pattern . " [NC]\n";
        }
        // The domains of other languages reach this WordPress too: the copy is the main site's, never theirs.
        $hosts = $this->other_language_hosts_pattern();
        $host_guard = '' === $hosts ? '' : 'RewriteCond %{HTTP_HOST} !' . $hosts . " [NC]\n";
        $guard .= $host_guard;
        // Redirects of other plugins (static_bridge_redirects): before the copy, a real 301/302 also in Strict, only
        // while the copy has no page at that path. In the substitution «%N» is a back-reference to a RewriteCond: an
        // encoded target (/a%20b/, ’ is %E2%80%99) keeps its «%» only as «\%» (2.5.0; before, /a%20b/ became /a0b/).
        $redirect_rules = '';
        foreach ($this->plugin_redirects() as $from => $redirect) {
            $path = ltrim($from, '/');
            $redirect_rules .= $host_guard
                . "RewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/.enabled -f\n"
                . 'RewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/' . $base . '/' . $path . "/index.html !-f\n"
                . 'RewriteRule ^' . preg_quote($path, '~') . '/?$ ' . str_replace('%', '\\%', $redirect['to']) . ' [R=' . $redirect['status'] . ",NE,END]\n";
        }
        if ('' !== $redirect_rules) {
            $redirect_rules = "# Reindirizzamenti di altri plugin (static_bridge_redirects).\n" . $redirect_rules . "\n";
        }
        // Only the form WordPress links to is static; the other one gets WordPress's 301.
        $slash = $this->routes_require_trailing_slash() ? "RewriteCond %{REQUEST_URI} /$\n" : "RewriteCond %{REQUEST_URI} !/$\n";

        // Optional CDN header: the rules tag static responses with an environment variable
        // (REDIRECT_-prefixed after the internal rewrite). The Strict 404 always carries no-store,
        // so a CDN never keeps a 404 for a page that is published a moment later.
        $cache_control = $this->settings()['static_cache_control'];
        $static_flags = '[END,E=STATIC_BRIDGE_ROUTE:static]';
        $strict_flags = '[R=404,END,E=STATIC_BRIDGE_STRICT:1]';
        // The site's security headers on static responses. setifempty skips one the server config already sets
        // with "Header always"; one set without "always" (another table) can appear twice, with the same value.
        $security = '';
        foreach ($this->security_headers() as $name => $value) {
            $security .= 'Header always setifempty ' . $name . ' ' . $this->quoted_header_value($value) . " env=STATIC_BRIDGE_ROUTE\n"
                . 'Header always setifempty ' . $name . ' ' . $this->quoted_header_value($value) . " env=REDIRECT_STATIC_BRIDGE_ROUTE\n";
        }
        // Precompressed pages (2.3.0): with gzip accepted and both files there, the .gz is served as text/html with
        // Content-Encoding: gzip. The <If> on the file served (as in the archive protection block) works after the
        // internal rewrite, where an E= variable would be renamed REDIRECT_ and mod_deflate would compress it again.
        $precompressed = $this->precompressed_pages_enabled();
        $gzip_flags = '[END,T=text/html,E=no-gzip:1,E=STATIC_BRIDGE_ROUTE:static,E=STATIC_BRIDGE_GZ:1]';
        $gzip_home = '';
        $gzip_route = '';
        if ($precompressed) {
            // 2.5.0: only with mod_headers, which writes Content-Encoding: without it Apache would send the
            // compressed bytes as plain text/html, and the visitor would see them; the plain file serves instead.
            $gzip_home = "<IfModule mod_headers.c>\n"
                . $guard
                . "RewriteCond %{HTTP:Accept-Encoding} \\bgzip\\b [NC]\n"
                . "RewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/" . $base . "/index.html -f\n"
                . "RewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/" . $base . "/index.html.gz -f\n"
                . "RewriteRule ^$ wp-content/static-bridge/" . $base . "/index.html.gz " . $gzip_flags . "\n"
                . "</IfModule>\n\n";
            $gzip_route = "<IfModule mod_headers.c>\n"
                . $guard
                . $slash
                . "RewriteCond %{HTTP:Accept-Encoding} \\bgzip\\b [NC]\n"
                . "RewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/" . $base . "/$1/index.html -f\n"
                . "RewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/" . $base . "/$1/index.html.gz -f\n"
                . "RewriteRule ^(.+?)/?$ wp-content/static-bridge/" . $base . "/$1/index.html.gz " . $gzip_flags . "\n"
                . "</IfModule>\n\n";
        }
        // 2.5.0: the marker the Nginx block sends (X-Static-Bridge-Route: static), on the copy, its .gz and the Strict
        // 404, never on a page of WP. "set" writes it once even if both names of a variable are there.
        $route_marker = '';
        foreach (array('STATIC_BRIDGE_ROUTE', 'REDIRECT_STATIC_BRIDGE_ROUTE', 'STATIC_BRIDGE_STRICT', 'REDIRECT_STATIC_BRIDGE_STRICT') as $variable) {
            $route_marker .= 'Header always set X-Static-Bridge-Route static env=' . $variable . "\n";
        }
        $headers = "<IfModule mod_headers.c>\n"
            . $route_marker
            . ('' === $cache_control ? '' : 'Header always set Cache-Control "' . $cache_control . "\" env=STATIC_BRIDGE_ROUTE\n"
                . 'Header always set Cache-Control "' . $cache_control . "\" env=REDIRECT_STATIC_BRIDGE_ROUTE\n")
            . ($precompressed ? "Header always merge Vary Accept-Encoding env=REDIRECT_STATIC_BRIDGE_ROUTE\n" : '')
            . $security
            . 'Header always set Cache-Control "' . self::STRICT_404_CACHE_CONTROL . "\" env=STATIC_BRIDGE_STRICT\n"
            . 'Header always set Cache-Control "' . self::STRICT_404_CACHE_CONTROL . "\" env=REDIRECT_STATIC_BRIDGE_STRICT\n"
            . "</IfModule>\n";

        $block = "# BEGIN Static Bridge\n"
            . "# Regole gestite dal plugin Static Bridge.\n"
            . "<IfModule mod_rewrite.c>\nRewriteEngine On\n\n"
            . $redirect_rules
            . $gzip_home
            . $guard
            . "RewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/" . $base . "/index.html -f\nRewriteRule ^$ wp-content/static-bridge/" . $base . "/index.html " . $static_flags . "\n\n"
            . $gzip_route
            . $guard
            . $slash
            . "RewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/" . $base . "/$1/index.html -f\nRewriteRule ^(.+?)/?$ wp-content/static-bridge/" . $base . "/$1/index.html " . $static_flags . "\n\n"
            . $guard
            . $slash
            // Strict answers routes only: /favicon.ico, /.well-known/… and other files stay with WordPress.
            . "RewriteCond %{REQUEST_URI} !^/\\.well-known/ [NC]\n"
            . "RewriteCond %{REQUEST_URI} !" . $this->file_extension_pattern() . "\n"
            . "RewriteCond %{DOCUMENT_ROOT}/wp-content/static-bridge/.strict -f\n"
            . "RewriteCond %{REQUEST_FILENAME} !-f\n"
            . "RewriteRule ^ - " . $strict_flags . "\n"
            . "</IfModule>\n"
            . $headers
            . ($precompressed ? "<If \"%{REQUEST_FILENAME} =~ m#/wp-content/static-bridge/.+\\.html\\.gz$#\">\n"
                . "<IfModule mod_mime.c>\nForceType text/html\n</IfModule>\n"
                . "<IfModule mod_env.c>\nSetEnv no-gzip 1\n</IfModule>\n"
                . "<IfModule mod_headers.c>\nHeader always set Content-Encoding gzip\nHeader always merge Vary Accept-Encoding\n</IfModule>\n"
                . "</If>\n" : '')
            . "# END Static Bridge";
        if ('openlitespeed' !== $this->web_server_kind()) {
            return $block;
        }
        // OpenLiteSpeed reads .htaccess only when it starts. The probe answers 410 only while the server applies this
        // very block; the Diagnostica asks it (openlitespeed_rules_loaded()) and otherwise says to restart the server.
        $probe = "# OpenLiteSpeed legge questo file solo all'avvio: la Diagnostica chiede questo indirizzo per sapere se le regole in uso sono queste.\n"
            . 'RewriteRule ^' . self::OPENLITESPEED_PROBE_PREFIX . substr(hash('sha256', $block), 0, 12) . "$ - [R=410,L]\n\n";
        $anchor = "RewriteEngine On\n\n";
        $position = strpos($block, $anchor) + strlen($anchor);
        return substr($block, 0, $position) . $probe . substr($block, $position);
    }

    /**
     * On OpenLiteSpeed: true when the server applies the Static Bridge block now in .htaccess (its probe answers 410),
     * false when it still applies older rules or none, a WP_Error when the block or the answer cannot be read.
     */
    private function openlitespeed_rules_loaded()
    {
        $file = trailingslashit(ABSPATH) . '.htaccess';
        $contents = is_link($file) || !is_readable($file) ? false : @file_get_contents($file);
        if (!is_string($contents) || !preg_match('~^RewriteRule \^(' . preg_quote(self::OPENLITESPEED_PROBE_PREFIX, '~') . '[a-f0-9]{12})\$ - \[R=410,L\]$~m', $contents, $match)) {
            return new WP_Error('static_bridge_openlitespeed_probe', __('Nel file .htaccess manca la regola di prova di Static Bridge per OpenLiteSpeed.', 'static-bridge'));
        }
        $response = $this->remote_get(home_url('/' . $match[1]), 10, 262144);
        if (is_wp_error($response)) {
            return $response;
        }
        return 410 === (int) wp_remote_retrieve_response_code($response);
    }

    /**
     * The OpenLiteSpeed context that adds to static pages the headers the .htaccess rules ask for and OpenLiteSpeed
     * ignores: Cache-Control and the site's security headers. Rewritten requests take the headers of the context of
     * the file they end on, so PHP pages keep theirs. '' when there is nothing to add.
     */
    private function openlitespeed_context_block()
    {
        $headers = array();
        $cache_control = $this->settings()['static_cache_control'];
        if ('' !== $cache_control) {
            $headers[] = 'Cache-Control: ' . $cache_control;
        }
        foreach ($this->security_headers() as $name => $value) {
            $headers[] = $name . ': ' . $value;
        }
        if (empty($headers)) {
            return '';
        }
        return "# Static Bridge - contesto da aggiungere al virtual host di OpenLiteSpeed, poi riavvia il server.\n"
            . "context /wp-content/static-bridge/ {\n"
            . "  location                \$DOC_ROOT/wp-content/static-bridge/\n"
            . "  allowBrowse             1\n"
            . "  extraHeaders            <<<END_extraHeaders\n"
            . implode("\n", $headers) . "\n"
            . "  END_extraHeaders\n"
            . "}";
    }

    /**
     * Cache-Control for static responses: a comma-separated allowlist of directives
     * (it is written verbatim into Nginx and Apache rules). '' disables the header.
     */
    private function sanitize_static_cache_control($value)
    {
        $invalid = new WP_Error('static_bridge_cache_control_invalid', __('Usa solo direttive Cache-Control standard separate da virgole, ad esempio "public, max-age=0, s-maxage=600". Sono ammesse: public, no-cache, no-store, no-transform, must-revalidate, proxy-revalidate, immutable, max-age, s-maxage, stale-while-revalidate, stale-if-error.', 'static-bridge'));
        if (!is_string($value)) {
            return $invalid;
        }
        $value = trim($value);
        if ('' === $value) {
            return '';
        }
        if (strlen($value) > 200) {
            return $invalid;
        }
        $flags = array('public', 'no-cache', 'no-store', 'no-transform', 'must-revalidate', 'proxy-revalidate', 'immutable');
        $seconds = array('max-age', 's-maxage', 'stale-while-revalidate', 'stale-if-error');
        $directives = array();
        foreach (explode(',', $value) as $directive) {
            $directive = strtolower(trim($directive));
            if (preg_match('/^([a-z-]+)=([0-9]{1,9})$/D', $directive, $match) && in_array($match[1], $seconds, true)) {
                $name = $match[1];
                $directive = $name . '=' . (int) $match[2];
            } elseif (in_array($directive, $flags, true)) {
                $name = $directive;
            } else {
                return $invalid;
            }
            if (isset($directives[$name])) {
                return $invalid;
            }
            $directives[$name] = $directive;
        }
        return implode(', ', $directives);
    }

    private function log_activity($message, $detail = '', $error = false)
    {
        $items = get_option(self::ACTIVITY_OPTION, array());
        if (!is_array($items)) {
            $items = array();
        }
        $items[] = array(
            'time' => date_i18n(get_option('date_format') . ' ' . get_option('time_format')),
            'message' => wp_strip_all_tags($message),
            'detail' => wp_strip_all_tags($detail),
            'error' => (bool) $error,
        );
        update_option(self::ACTIVITY_OPTION, array_slice($items, -30), false);
    }

    private function tab_url($tab)
    {
        return add_query_arg(array('page' => self::ADMIN_SLUG, 'tab' => $tab), admin_url('admin.php'));
    }

    private function paginate_form_pages($pages, $requested_page)
    {
        $pages = is_array($pages) ? array_values($pages) : array();
        $total_items = count($pages);
        $total_pages = max(1, (int) ceil($total_items / self::FORM_ADMIN_PAGE_SIZE));
        $current_page = max(1, min($total_pages, absint($requested_page)));
        $offset = ($current_page - 1) * self::FORM_ADMIN_PAGE_SIZE;
        $first_page_number = max(1, $current_page - 2);
        $last_page_number = min($total_pages, $current_page + 2);

        return array(
            'items' => array_slice($pages, $offset, self::FORM_ADMIN_PAGE_SIZE),
            'current_page' => $current_page,
            'total_pages' => $total_pages,
            'total_items' => $total_items,
            'first_item' => $total_items > 0 ? $offset + 1 : 0,
            'last_item' => min($total_items, $offset + self::FORM_ADMIN_PAGE_SIZE),
            'page_numbers' => range($first_page_number, $last_page_number),
            'show_first' => $first_page_number > 1,
            'show_first_ellipsis' => $first_page_number > 2,
            'show_last' => $last_page_number < $total_pages,
            'show_last_ellipsis' => $last_page_number < $total_pages - 1,
        );
    }

    private function merge_form_modes($detected, $paths, $modes, $saved_modes)
    {
        $allowed = array();
        foreach ($detected as $form_page) {
            $allowed[$form_page['path']] = $form_page;
            if (!empty($form_page['manual_excluded'])) {
                unset($saved_modes[$form_page['path']]);
            }
        }

        foreach ($paths as $index => $raw_path) {
            $path = $this->normalize_route_path($raw_path);
            if ('' === $path || !isset($allowed[$path]) || !empty($allowed[$path]['manual_excluded']) || !isset($modes[$index])) {
                continue;
            }
            $mode = sanitize_key($modes[$index]);
            if (in_array($mode, array('static', 'dynamic'), true)) {
                $saved_modes[$path] = $mode;
            }
        }

        return $saved_modes;
    }
}

// Run a low-cost guard before Static Bridge registers hooks or activation side effects.
// WordPress has already bootstrapped the site at this point; this cannot predict failures
// that happen earlier in core or other active plugins.
if (Static_Bridge_Plugin::is_activation_request()) {
    $static_bridge_activation_report = Static_Bridge_Plugin::activation_preflight();
    if (empty($static_bridge_activation_report['ok'])) {
        Static_Bridge_Plugin::halt_activation($static_bridge_activation_report);
    }
}

register_activation_hook(__FILE__, array('Static_Bridge_Plugin', 'activate'));
register_deactivation_hook(__FILE__, array('Static_Bridge_Plugin', 'deactivate'));
$static_bridge_plugin = new Static_Bridge_Plugin();
if (class_exists('Static_Bridge_CLI')) {
    Static_Bridge_CLI::register($static_bridge_plugin);
}
if (class_exists('Static_Bridge_Release_Updater')) {
    Static_Bridge_Release_Updater::init();
}
